package com.evi.live;

/**
 * How long the player is willing to wait for one trade, in the scanner's own words.
 *
 * Replaces {@link TradeDuration}, whose nine options were labelled in minutes and promised
 * something the market does not deliver. Measured over 60 days of archived prices by
 * replaying the real ranking and holding each pick for exactly as long as
 * the setting claimed: at ~5 minutes, ~30 minutes and ~1 hour, **not one round trip completed
 * inside its own window** at any cash stack tested (50k, 10m and 380m), leaving 100% of the
 * capital still tied up when the window ended. Those settings were not describing fast trades;
 * they were describing trades that had not finished yet.
 *
 * So the options are now the four the scanner already uses, each set to a length that was measured
 * to actually complete:
 *
 * <pre>
 *   at a 10m cash stack        sales completed   realised per sale   capital left stuck
 *   ~1 hour (dropped)                        0                   -                 100%
 *   Fast, 2 hours                           13              70,298                  83%
 *   Medium, 6 hours                         38             177,287                  61%
 *   Overnight, 12 hours                     39             285,156                  55%
 *   Slow, 48 hours                          74             369,945                  27%
 * </pre>
 *
 * Longer genuinely is better here, which is the only reason Slow exists: the standard set for it
 * was that a longer hold has to be verified to help, or it is only added risk. Beyond two days the
 * gain flattens -- 72 hours earned slightly less per sale and only tied up less capital -- so two
 * days is where the improvement stops being unambiguous and the list stops.
 *
 * A new keyName is used deliberately rather than reusing "tradeDuration": RuneLite stores config by
 * keyName, and a stored value naming an option that no longer exists is not something to gamble on.
 * The old setting is kept and hidden, so nothing stored is lost, and every player picks once.
 */
public enum TradePace {
  NONE, FAST, MEDIUM, OVERNIGHT, SLOW;

  /** RuneLite's config UI renders enum dropdowns using toString(), so this is the visible label. */
  @Override public String toString() {
    switch (this) {
      case FAST: return "Fast (~2 hours)";
      case MEDIUM: return "Medium (~6 hours)";
      case OVERNIGHT: return "Overnight (~12 hours)";
      case SLOW: return "Slow (~2 days)";
      default: return "No preference";
    }
  }

  /** Minutes to send as ?duration=, or 0 for NONE (meaning: leave the query parameter off entirely). */
  int minutes() {
    switch (this) {
      case FAST: return 120;
      case MEDIUM: return 360;
      case OVERNIGHT: return 720;
      case SLOW: return 2880;
      default: return 0;
    }
  }
}

package com.evi.live;

/**
 * RETIRED 6 Oct 2026. This was the "Trading profile" dropdown; it is now a hidden config item that
 * nothing reads, and the plugin never sends ?profile= at all. The enum stays only so a stored value
 * (most installs hold "STARTER", the old default) is still a valid value for RuneLite to load --
 * deleting the type under the same keyName is the config-loader risk the project notes warn about.
 *
 * Why it went: on market-wide picks, untaxed-only meant sub-50 gp bulk and nothing else. The
 * measurement below is kept as the record of why it was once the default.
 *
 * STARTER is training wheels, and it was chosen from measured evidence rather than intuition.
 * Replaying 90 archived days through EVI's own ranking, restricting market-wide
 * picks to items the Grand Exchange charges no tax on -- anything under 50 gp, plus the exemption
 * list -- changed the results dramatically for a small stack:
 *
 *   2m stack, 25% cash cap:  standard  220 sales, 85% won, 29% of capital left stuck, worst -132,164
 *                            starter   325 sales, 98% won,  5% of capital left stuck, worst  -14,920
 *
 * The same pattern held at 10m and 50m. Individual trades earn less (about 40k rather than 52k on a
 * 2m stack), but far more of them complete, almost none end up stuck, and the worst case is an order
 * of magnitude smaller -- which is what matters when you are learning and cannot afford to have your
 * whole stack frozen in something that will not sell.
 *
 * Two honest caveats. The simulation fills orders optimistically and ignores queue position, which
 * flatters cheap high-volume items most, so the real advantage is smaller than those numbers. And
 * tax-free items are cheap items, so profit per trade is small: this is a way to learn the mechanics
 * and grow steadily, not a way to make a fortune quickly.
 */
// (Historical) STARTER was the default: someone installing this for the first time is more likely to be learning
// than to be running a large stack, and the measured downside of starting here is smaller profit per
// trade rather than risk. Anyone who isn't a beginner switches to Standard in one click.
public enum TradingProfile {
  STANDARD, STARTER;

  /** RuneLite's config UI renders enum dropdowns using toString(), so this is the visible label. */
  @Override public String toString() {
    return this == STARTER ? "Starter" : "Standard";
  }
}

package com.evi.live.engine;

import com.evi.live.journal.BuyLimitUsage;
import com.evi.live.journal.CostBasis;
import com.evi.live.journal.FifoMatcher;
import com.evi.live.journal.Offer;
import com.evi.live.journal.StoreState;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

/**
 * ONE account's slice of the journal, built ONCE per poll: its live offers, its open lots, the cost basis read from them,
 * the items it has listed, and its buy-limit usage. The advice channel ({@link AdviceNotes} and the modules it composes)
 * is handed this and nothing else of the journal, so ACCOUNT SCOPING HOLDS BY CONSTRUCTION: no advice function can reach
 * {@code state().active}, {@code state().autoOpenPositions} or another account's lots, because it is never given them.
 *
 * <p>The scoping rule is the server's {@code ownedBy}, applied here and only here: a record belongs to the view when the poll
 * NAMES an account (not null, not empty) and the record carries the same one. A poll with no account (the login screen, a
 * world hop) gets {@link #nobody()}: an empty view, so it gets no advice at all -- never another account's offers (the 6 Oct
 * pure/main bug, fixed in JS first).
 *
 * <p>Why construction rather than a filter at each call site: a widening that only shows when two accounts touch the SAME
 * item, or only when this account holds nothing, slipped past every transcript three times over (the 7 Oct mutation passes:
 * the margin-gone buys, the cost basis, the crash notes' "You hold"). A view with no path back to the whole journal cannot
 * widen at all.
 *
 * <p>THE SUGGESTION TIERS READ THROUGH IT TOO (7 Oct, {@link Engine#decide}): the slot reserve ({@link #slotExposure}), the
 * listed-holding test ({@link #hasLiveSellOffer}), the persisted holding ({@link #pickPersistentOpenPosition}) and the open
 * offer's cost basis ({@link #heldCostBasis}) are methods of the view, and their list-taking kernels in {@link GeSlots},
 * {@link HoldingTiers} and {@link Prices} are package-private (kept for the JS vectors, which call them with the lists the
 * bridge passes). The JS functions scope with {@code !account || x.account === account} and are safe only because server.mjs
 * pre-filters (the PORT WARNING); here no caller can hand them a wider list than the view's own.
 *
 * <p>DELIBERATELY NOT HERE, and named as such where it is used: the player fill model reads EVERY account's offers
 * (server.mjs {@code playerFillModel}: {@code store.offers}, unscoped -- pinned by tier-safety-fill-sentence), so it takes
 * the journal's offers explicitly ({@link SafetyChecks#watchedOffers}); and the market readings (/latest, the crash watch,
 * the archive) are market-wide by nature.
 */
public final class AccountView {
  /** The account the poll names; null for {@link #nobody()}. */
  public final String account;
  /** This account's live offers, in {@code state().active} order. */
  public final List<Offer> active;
  /** Its live sells still unfilled (SELLING, and CANCELLED_SELL as server.mjs names it -- which can never be live). */
  public final List<Offer> liveSells;
  /** Its live buys still unfilled. */
  public final List<Offer> liveBuys;
  /** Its occupied slots ({@code state().occupied}: live offers and finished ones not yet collected), in that order. */
  public final List<Offer> occupied;
  /** Its open lots, in the journal's order. */
  public final List<FifoMatcher.OpenPosition> positions;
  /** Item id to unit cost from ITS lots only: {@code new Map(positions.map(p => [p.itemId, p.unitCost]))}, a later lot winning. */
  public final Map<Integer, Double> costBasis;
  /** Items it has standing in a SELLING offer (a listed holding is not stated again). */
  public final Set<Integer> listedItemIds;
  /** Its own buys in the journal (any state), the only input of {@link #buyLimitUsage}. */
  private final List<Offer> ownBuys;
  private final long now;

  private AccountView(String account, List<Offer> active, List<Offer> occupied, List<FifoMatcher.OpenPosition> positions, List<Offer> ownBuys,
                      long now) {
    this.account = account;
    this.active = Collections.unmodifiableList(active);
    this.occupied = Collections.unmodifiableList(occupied);
    List<Offer> sells = new ArrayList<>(), buys = new ArrayList<>();
    Set<Integer> listed = new LinkedHashSet<>();
    for (Offer o : active) {
      // CANCELLED_SELL is kept because server.mjs names it, but it can never match: store.mjs finished() counts a cancelled
      // offer as finished, so state().active never holds one (pinned by advice-lots-and-cancelled-sell). A JS dead clause,
      // recorded for the maintainer, not "fixed" here.
      if (("SELLING".equals(o.state) || "CANCELLED_SELL".equals(o.state)) && o.filled < o.total) sells.add(o);
      if ("BUYING".equals(o.state) && o.filled < o.total) buys.add(o);
      if ("SELLING".equals(o.state)) listed.add(o.itemId);
    }
    this.liveSells = Collections.unmodifiableList(sells);
    this.liveBuys = Collections.unmodifiableList(buys);
    this.positions = Collections.unmodifiableList(positions);
    Map<Integer, Double> cost = new LinkedHashMap<>();
    for (FifoMatcher.OpenPosition p : positions) cost.put(p.itemId, p.unitCost);
    this.costBasis = Collections.unmodifiableMap(cost);
    this.listedItemIds = Collections.unmodifiableSet(listed);
    this.ownBuys = Collections.unmodifiableList(ownBuys);
    this.now = now;
  }

  /** The server's {@code ownedBy}: a named account, a record, and the same account on it. */
  static boolean ownedBy(String account, String recordAccount) {
    return account != null && !account.isEmpty() && account.equals(recordAccount);
  }

  /** The view of a poll that names no account: nothing at all. */
  public static AccountView nobody() {
    return new AccountView(null, new ArrayList<>(), new ArrayList<>(), new ArrayList<>(), new ArrayList<>(), 0);
  }

  /**
   * The view for {@code account}, from one {@code store.state(now)} and the journal's offers ({@code store.offers()}, read
   * only for this account's buy-limit usage; null: no usage known). Null or empty account: {@link #nobody()}.
   */
  public static AccountView of(StoreState state, Collection<Offer> journalOffers, String account, long now) {
    if (account == null || account.isEmpty() || state == null) return nobody();
    List<Offer> active = new ArrayList<>();
    for (Offer o : state.active) if (ownedBy(account, o.account)) active.add(o);
    List<Offer> occupied = new ArrayList<>();
    if (state.occupied != null) for (Offer o : state.occupied) if (ownedBy(account, o.account)) occupied.add(o);
    List<FifoMatcher.OpenPosition> positions = new ArrayList<>();
    if (state.autoOpenPositions != null) for (FifoMatcher.OpenPosition p : state.autoOpenPositions) if (ownedBy(account, p.account)) positions.add(p);
    List<Offer> buys = new ArrayList<>();
    if (journalOffers != null) for (Offer o : journalOffers) if (ownedBy(account, o.account) && "buy".equals(o.side())) buys.add(o);
    return new AccountView(account, active, occupied, positions, buys, now);
  }

  /** True for {@link #nobody()} (and for an account with nothing at all). */
  public boolean isEmpty() {
    return active.isEmpty() && occupied.isEmpty() && positions.isEmpty() && ownBuys.isEmpty();
  }

  // ------------------------------------------------------------------------------------- the suggestion tiers' readings

  /**
   * slotExposure for this account: of its open lots, only those the plugin CONFIRMED are in the inventory right now
   * ({@code heldPositions=}; an unconfirmed lot never invents a constraint), against its occupied slots. What it is
   * committed to, and how many sells need a slot they do not already have.
   */
  public GeSlots.Exposure slotExposure(Set<Integer> confirmedHeld) {
    List<FifoMatcher.OpenPosition> confirmed = new ArrayList<>();
    for (FifoMatcher.OpenPosition p : positions) if (confirmedHeld != null && confirmedHeld.contains(p.itemId)) confirmed.add(p);
    return GeSlots.slotExposure(confirmed, occupied, account);
  }

  /** hasLiveSellOffer: is this item standing in one of THIS account's live SELLING offers? (Never the journal's ghosts.) */
  public boolean hasLiveSellOffer(int itemId) {
    return HoldingTiers.hasLiveSellOffer(active, itemId, account);
  }

  /**
   * pickPersistentOpenPosition: this account's oldest open lot not on {@code blocklist} and not already listed for sale
   * ({@link #hasLiveSellOffer}), or null.
   */
  public FifoMatcher.OpenPosition pickPersistentOpenPosition(Set<Integer> blocklist) {
    return HoldingTiers.pickPersistentOpenPosition(positions, account, blocklist, this::hasLiveSellOffer);
  }

  /** heldCostBasis: what this account paid for {@code itemId} still held -- its lots, plus its running buys' filled units. */
  public CostBasis heldCostBasis(int itemId) {
    return Prices.heldCostBasis(positions, active, itemId, account);
  }

  /** The items of its open lots, ascending, once each ({@code slots.positionItems}). */
  public List<Integer> positionItems() {
    return new ArrayList<>(new TreeSet<Integer>(lotItems(false)));
  }

  /**
   * The items the idle-stock tier must leave to the holding tier: its lots with units left and a known unit cost (only the
   * holding tier can say what was paid for them).
   */
  public Set<Integer> positionItemsWithCost() {
    return lotItems(true);
  }

  private Set<Integer> lotItems(boolean withCost) {
    Set<Integer> out = new LinkedHashSet<>();
    for (FifoMatcher.OpenPosition p : positions)
      if (!withCost || (p.remaining > 0 && JsValues.isFinite(p.unitCost))) out.add(p.itemId);
    return out;
  }

  /**
   * How much of {@code itemId} THIS account has bought in the GE's four-hour window, at the view's clock (store.mjs
   * {@code buyLimitUsage}, an under-estimate by design). Another account's buys never count: they are not in the view.
   */
  public BuyLimitUsage buyLimitUsage(int itemId) {
    return BuyLimitUsage.of(ownBuys, account, itemId, now);
  }
}

package com.evi.live.engine;

/**
 * One line of advice about something the player already has: an offer standing in a slot, or stock held. The shape the
 * bridge sends in {@code relistAdvice} (the list the plugin draws as cards under "Active offers"), and the shape each
 * advice module returns before the server trims it ({@link Relist}, {@link SellAdvice}, {@link BuyAdvice},
 * {@link BuyProgress}, {@link HoldingsAdvice}, and the crash notes in {@link AdviceNotes}).
 *
 * <p>A null field is ABSENT (or JSON null, which the plugin reads the same way). Numbers are doubles because they are the
 * JS numbers the bridge computed -- the plugin never parses a fractional one: every field it reads as a whole number is
 * whole by construction (an offer's own price, a {@code Math.round}ed figure).
 *
 * <p>NEVER AN INSTRUCTION. Every module states facts and leaves the decision with the player: EVI never places, edits,
 * relists or cancels an offer.
 */
public final class AdviceNote {
  public int itemId;
  public String name;
  public String message;
  /** The tooltip under a short message (8 Oct 2026: crash notes only). Null: absent, and the tooltip is the message. */
  public String detail;
  /** 'warn', 'caution' or 'info'. */
  public String level;
  public String label;
  public String figures;

  // relist.mjs
  public Double offerPrice;
  public Double marketPrice;
  public Double breakEven;
  public Double suggestedPrice;
  public Double openMinutes;
  public Boolean belowBreakEven;

  // sellAdvice.mjs
  public Double lossEach;
  public Double lossTotal;

  // buyAdvice.mjs: both null on a "Nobody selling" note (JS sends them as null)
  public Double marginPerUnit;
  public Double netAtMarket;

  // buyProgress.mjs
  public Double filled;
  public Double total;

  // holdingsAdvice.mjs
  public Double quantity;
  public Double unitCost;
  public Double cost;
  public Double worth;
  public Double net;
  public Boolean holding;
  /** The lot's buy offer id (8 Oct 2026): what the sidebar's line menu marks (Personal use, Gone). Null: absent. */
  public String buyId;

  AdviceNote(int itemId) {
    this.itemId = itemId;
  }

  /** An advice module's input price for one item: what sellers ask ({@code buyPrice}) and buyers pay ({@code sellPrice}). */
  public static final class Price {
    public final Double buyPrice;
    public final Double sellPrice;

    public Price(Double buyPrice, Double sellPrice) {
      this.buyPrice = buyPrice;
      this.sellPrice = sellPrice;
    }

    /** From {@link Prices#lookupItemPrice}'s answer (null in, null out). */
    public static Price of(ItemPrice p) {
      return p == null ? null : new Price((double) p.buyPrice, (double) p.sellPrice);
    }
  }
}

package com.evi.live.engine;

import com.evi.live.journal.FifoMatcher;
import com.evi.live.journal.Offer;
import com.evi.live.market.LatestPrices;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The advice channel the plugin draws under "Active offers": server.mjs's {@code relistAdvice} array, composed for ONE
 * account, in the bridge's order -- crash notes, then sell-below-break-even, margin-gone buys, relist advice, buy progress
 * and holdings. Pure: the account's view, the prices, the pace and the crash watch are handed in.
 *
 * <p>ACCOUNT SCOPING HOLDS BY CONSTRUCTION. Everything this class (and every module it composes) knows about offers,
 * positions and cost basis comes from one {@link AccountView}, built once per poll for the account the poll names. There is
 * no journal state here at all -- no {@code state().active}, no {@code autoOpenPositions}, no other account's lots -- so no
 * line below can widen to another account however it is edited. A poll with no account gets {@link AccountView#nobody()}
 * and therefore no advice (the 6 Oct pure/main bug, fixed in JS first). The only other inputs are MARKET-WIDE by nature
 * and named so: /latest and the crash watch.
 *
 * <p>Each module's own answer is TRIMMED to the fields the server sends (only the relist notes go out whole), so the
 * notes here are exactly the JSON the plugin parses.
 *
 * <p>CORRELATION IS NOT HERE AND NOT PORTED (a documented seam): the bridge's correlation gate needs more than 60 six-hour
 * blocks of archive (over 15 days) while the plugin keeps 14, so it could never arm. When retention allows, it plugs into
 * {@link PickChain.Options#correlationFor}, which every chain already honours.
 */
public final class AdviceNotes {
  private AdviceNotes() {}

  /** The inputs of one poll's advice. Everything may be null; a null view is {@link AccountView#nobody()}. */
  public static final class Inputs {
    /** The poll's account, as {@link AccountView#of} built it: its offers, lots and cost basis, and nothing else's. */
    public AccountView view;
    /** MARKET-WIDE: /latest as the bridge last fetched it (null: no prices -- no market-relative advice, holdings unpriced). */
    public LatestPrices marketLatest;
    /** The player's pace in minutes (null: none set -- relist falls back to 1440, buy progress says nothing). */
    public Double targetDurationMinutes;
    /** Items slotFill already says "may not fill in time" about ({@code likelyToFillInTime === false}). */
    public Set<Integer> slowFillItemIds;
    /** The item this poll suggests (null: none), which the holdings lines skip. */
    public Integer suggestedItemId;
    /** MARKET-WIDE: the crash watch (null: none running, so no crash notes). */
    public CrashWatch.Watch crashWatch;
    /** The clock, in ms. */
    public double now;
  }

  /** relistAdvice: [...crashNotes, ...sellNotes, ...buyNotes, ...relist, ...buyProgressNotes, ...holdingNotes]. */
  public static List<AdviceNote> compose(Inputs in) {
    AccountView view = in.view == null ? AccountView.nobody() : in.view;

    List<AdviceNote> sellNotes = new ArrayList<>();
    for (AdviceNote n : SellAdvice.forAccount(view)) {
      AdviceNote t = new AdviceNote(n.itemId);
      t.message = n.message;
      t.belowBreakEven = true;
      sellNotes.add(t);
    }

    List<AdviceNote> buyNotes = new ArrayList<>();
    for (AdviceNote n : BuyAdvice.forAccount(view, in.marketLatest)) {
      AdviceNote t = new AdviceNote(n.itemId);
      t.name = n.name;
      t.message = n.message;
      t.belowBreakEven = false;
      buyNotes.add(t);
    }

    List<AdviceNote> relist = Relist.forAccount(view, in.marketLatest, in.targetDurationMinutes != null ? in.targetDurationMinutes : 1440, in.now);

    List<AdviceNote> progressNotes = new ArrayList<>();
    for (AdviceNote n : BuyProgress.forAccount(view, in.targetDurationMinutes, in.slowFillItemIds == null ? new HashSet<>() : in.slowFillItemIds, in.now)) {
      AdviceNote t = card(n);
      t.belowBreakEven = false;
      progressNotes.add(t);
    }

    List<AdviceNote> holdingNotes = new ArrayList<>();
    for (AdviceNote n : HoldingsAdvice.forAccount(view, in.marketLatest, in.suggestedItemId)) {
      AdviceNote t = card(n);
      t.holding = true;
      t.belowBreakEven = false;
      t.buyId = n.buyId;                                  // the lot, for the line menu; absent with no id
      holdingNotes.add(t);
    }

    List<AdviceNote> out = new ArrayList<>(crashNotes(in.crashWatch, view));
    out.addAll(sellNotes);
    out.addAll(buyNotes);
    out.addAll(relist);
    out.addAll(progressNotes);
    out.addAll(holdingNotes);
    return out;
  }

  /** {itemId, name, message, level, label, figures}: the card fields the server keeps from a module's note. */
  private static AdviceNote card(AdviceNote n) {
    AdviceNote t = new AdviceNote(n.itemId);
    t.name = n.name;
    t.message = n.message;
    t.level = n.level;
    t.label = n.label;
    t.figures = n.figures;
    return t;
  }

  /**
   * {@code Object.fromEntries(offers.map(o => [String(o.itemId), lookupItemPrice(latest, o.itemId)]).filter(([, p]) => p))}:
   * MARKET-WIDE prices, keyed only by the items of the offers given (a view's own).
   */
  static Map<Integer, AdviceNote.Price> pricesFor(LatestPrices marketLatest, List<Offer> offers) {
    Map<Integer, AdviceNote.Price> out = new LinkedHashMap<>();
    for (Offer o : offers) {
      ItemPrice p = Prices.lookupItemPrice(marketLatest, o.itemId);
      if (p != null) out.put(o.itemId, AdviceNote.Price.of(p));
    }
    return out;
  }

  /**
   * Crash alerts for this player's OWN items -- running offers, then stock EVI knows is held -- one per item (the first
   * reason wins), each a complete sentence: what is happening, why the player is being told, the measured history, no
   * forecast -- as a short line and a tooltip detail (crashNote). Nothing is cancelled or relisted for them. Both lists come from the view, so an account holding nothing hears
   * of nothing (the 7 Oct M14 widening fell back to other accounts' positions exactly then).
   */
  static List<AdviceNote> crashNotes(CrashWatch.Watch watch, AccountView view) {
    List<AdviceNote> out = new ArrayList<>();
    if (watch == null) return out;
    Set<Integer> told = new HashSet<>();
    for (Offer o : view.active) {
      long left = Math.max(0, o.total - o.filled);
      if ("BUYING".equals(o.state) && left > 0)
        crashNote(out, told, watch, o.itemId, o.name, "Your buy for " + JsValues.localeUs(o.total) + " is still running (" + JsValues.localeUs(o.filled) + " bought).");
      else if ("SELLING".equals(o.state) && left > 0)
        crashNote(out, told, watch, o.itemId, o.name, "Your sell has " + JsValues.localeUs(left) + " still listed at " + JsValues.localeUs(o.price) + " gp.");
    }
    // A lot whose sell listing ENDED while EVI was not watching may have been sold, so its note never says "You hold": it
    // states EVI's record and that the outcome is unknown, like its holding card (server.mjs, 8 Oct 2026).
    for (FifoMatcher.OpenPosition p : view.positions) {
      String record = JsValues.localeUs(p.remaining) + " bought at " + JsValues.gp(p.unitCost) + " gp each";
      FifoMatcher.EndedUnseenMark gone = p.endedUnseen != null && p.endedUnseen.price > 0 ? p.endedUnseen : null;
      boolean some = gone != null && gone.quantity > 0 && gone.quantity < p.remaining;
      crashNote(out, told, watch, p.itemId, p.item, gone != null
        ? "EVI's record: " + record + ". A listing of " + (some ? JsValues.localeUs(gone.quantity) + " of them" : "them") + " at "
          + JsValues.localeUs(gone.price) + " gp ended while EVI wasn't watching, so whether it sold is unknown."
        : "You hold " + record + ".");
    }
    return out;
  }

  private static void crashNote(List<AdviceNote> out, Set<Integer> told, CrashWatch.Watch watch, int itemId, String name, String mine) {
    CrashWatch.Crash c = watch.isCrashing(itemId);
    if (c == null || told.contains(itemId)) return;
    told.add(itemId);
    AdviceNote n = new AdviceNote(itemId);
    n.name = name;
    // A short line and the tooltip's detail (crashNote, 8 Oct 2026), not the one long sentence.
    CrashWatch.Note text = CrashWatch.crashNote(c, name, mine);
    n.message = text.message;
    n.detail = text.detail;
    n.belowBreakEven = false;
    n.level = "warn";
    n.label = "Crashing";
    n.figures = "One of yours"; // `mine` is always given here, so never 'Watch before buying'
    out.add(n);
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Offer;
import com.evi.live.journal.Tax;
import com.evi.live.market.LatestPrices;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * "The trade you are still buying into no longer works." -- for a BUY offer still filling while the reason for it has gone
 * (bridge/buyAdvice.mjs {@code buyMarginAdvice}). Pure.
 *
 * <p>A running buy is the one place cancelling is free on every unfilled unit, so this is the cheapest warning EVI can
 * give. ARITHMETIC ON CURRENT PRICES AND THE TAX, NEVER A FORECAST: "margin gone" -- selling at what buyers pay now, after
 * tax, no longer clears the price being paid; "nobody selling" -- no sell-side price at all, said plainly rather than
 * treated as a margin of zero. Anything unreadable produces nothing (fail open). It never cancels or edits an offer.
 *
 * <p>Deliberately NOT included: "the market moved above your buy price". The plugin's offerDriftHint already says that, and
 * repeating it would put two sentences about one offer in the sidebar.
 */
public final class BuyAdvice {
  private BuyAdvice() {}

  /** MIN_MARGIN_SHARE: relative to the price being paid; prices wobble by less than this between polls. */
  public static final double MIN_MARGIN_SHARE = 0.005;

  /** An in-progress BUY offer: {itemId, name, price, total, filled, spent}; NaN for what the caller did not have. */
  public static final class BuyOffer {
    public final int itemId;
    public final String name;
    public final double price;
    public final double total;
    public final double filled;
    public final double spent;

    public BuyOffer(int itemId, String name, double price, double total, double filled, double spent) {
      this.itemId = itemId;
      this.name = name;
      this.price = price;
      this.total = total;
      this.filled = filled;
      this.spent = spent;
    }
  }

  /**
   * buyMarginAdvice for ONE account (server.mjs): its live buys, priced from /latest (market-wide, named as such) for
   * exactly those items. Another account's buy of the same item is not in the view, so it never draws a note here (the
   * 7 Oct M06 widening).
   */
  public static List<AdviceNote> forAccount(AccountView view, LatestPrices marketLatest) {
    List<BuyOffer> offers = new ArrayList<>();
    for (Offer o : view.liveBuys) offers.add(new BuyOffer(o.itemId, o.name, o.price, o.total, o.filled, o.spent));
    return buyMarginAdvice(offers, AdviceNotes.pricesFor(marketLatest, view.liveBuys));
  }

  /**
   * buyMarginAdvice: one note per offer worth mentioning, in offer order. {@code prices}: item id to its live price.
   * <p>Package-private on purpose: outside the engine the only way in is {@link #forAccount}, which reads ONE account's
   * records from its {@link AccountView}. The parity harness (same package) drives this record-level core directly.
   */
  static List<AdviceNote> buyMarginAdvice(List<BuyOffer> offers, Map<Integer, AdviceNote.Price> prices) {
    List<AdviceNote> out = new ArrayList<>();
    if (offers == null) return out;
    for (BuyOffer offer : offers) {
      if (offer == null || !(offer.price > 0) || !(offer.total > offer.filled)) continue;
      AdviceNote.Price p = prices == null ? null : prices.get(offer.itemId);
      String name = offer.name != null && !offer.name.isEmpty() ? offer.name : "item " + offer.itemId;
      double remaining = offer.total - offer.filled;
      String bought = offer.filled > 0
        ? " You have " + JsValues.gp(offer.filled) + " already" + (JsValues.isFinite(offer.spent) && offer.spent > 0 ? " at " + JsValues.gp(offer.spent / offer.filled) + " gp each" : "")
          + "; cancelling keeps those and only drops the " + JsValues.gp(remaining) + " still to buy."
        : " Nothing has filled yet, so cancelling costs nothing.";
      if (p == null || p.sellPrice == null || !(p.sellPrice > 0)) {
        if (p != null && p.buyPrice != null && p.buyPrice > 0) {
          AdviceNote n = new AdviceNote(offer.itemId);
          n.name = name;
          n.level = "caution";
          n.label = "Nobody selling";
          n.figures = JsValues.gp(remaining) + " still buying at " + JsValues.gp(offer.price);
          n.message = name + ": nobody is selling to buyers at the moment, so EVI cannot price an exit for the " + JsValues.gp(remaining)
            + " you are still buying at " + JsValues.gp(offer.price) + " gp." + bought + " EVI has no view on whether that changes.";
          out.add(n);
        }
        continue;
      }
      double netAtMarket = p.sellPrice - Tax.estimateUnitTax(offer.itemId, p.sellPrice);
      double marginPerUnit = netAtMarket - offer.price;
      if (marginPerUnit > offer.price * MIN_MARGIN_SHARE) continue;
      AdviceNote n = new AdviceNote(offer.itemId);
      n.name = name;
      n.marginPerUnit = marginPerUnit;
      n.netAtMarket = netAtMarket;
      n.level = marginPerUnit < 0 ? "warn" : "caution";
      n.label = "Margin gone";
      n.figures = JsValues.gp(offer.price) + " paid · " + JsValues.gp(netAtMarket) + " after tax";
      n.message = name + ": your buy at " + JsValues.gp(offer.price) + " gp no longer has a margin -- buyers are paying " + JsValues.gp(p.sellPrice)
        + " gp, which is " + JsValues.gp(netAtMarket) + " gp after tax, "
        + (marginPerUnit < 0 ? JsValues.gp(-marginPerUnit) + " gp BELOW" : "only " + JsValues.gp(marginPerUnit) + " gp above")
        + " what you are paying." + bought + " Whether to keep it is your call -- EVI never cancels anything, and it has no view on where the price goes next.";
      out.add(n);
    }
    return out;
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Offer;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

/**
 * "This buy has been open a while and here is how far it has got." (bridge/buyProgress.mjs {@code buyProgressAdvice}).
 * Pure; the clock is passed in.
 *
 * <p>IT STATES FACTS AND NEVER PREDICTS A FILL. A planned "this buy is dead" warning rested on "no buy gained a unit after
 * six hours", and re-measured (1 Oct, tools/buy-gain-timing.mjs) that was an ARTIFACT: packets only arrive while RuneLite is
 * open, no offer was watched past 4.51 hours, so of course none was seen to gain after six. So this says how long the buy
 * has been open, how much has filled, and the pace the player THEMSELVES set -- never that the offer is finished, never a
 * fill time, never "cancel". With no pace there is no bar and nothing is said: EVI must not invent an expectation the player
 * never expressed.
 */
public final class BuyProgress {
  private BuyProgress() {}

  /** An in-progress BUY offer: {itemId, name, total, filled, firstSeen}; NaN/null for what the caller did not have. */
  public static final class BuyOffer {
    public final Integer itemId;
    public final String name;
    public final double total;
    public final double filled;
    public final Double firstSeen;

    public BuyOffer(Integer itemId, String name, double total, double filled, Double firstSeen) {
      this.itemId = itemId;
      this.name = name;
      this.total = total;
      this.filled = filled;
      this.firstSeen = firstSeen;
    }
  }

  /** since(): "45m", "6h", "6.5h", "14h" -- short enough for the card's figures row. */
  static String since(double ms) {
    double mins = JsValues.jsRound(ms / 60000);
    if (mins < 90) return JsValues.text(mins) + "m";
    double h = mins / 60;
    // A whole number of hours reads as "6h", not "6.0h": the decimal implies a precision this does not have.
    if (Math.abs(h - JsValues.jsRound(h)) < 0.05) return JsValues.text(JsValues.jsRound(h)) + "h";
    return (h < 10 ? JsValues.toFixed(h, 1) : JsValues.text(JsValues.jsRound(h))) + "h";
  }

  /**
   * buyProgressAdvice: at most {@code max} notes, longest-open first (ties keep offer order). {@code targetDurationMinutes}
   * null, not finite or not above 0: nothing. {@code alreadyFlagged}: items the sidebar is already warning about through
   * slotFill ("May not fill in time"), skipped so one offer never produces two overlapping cards (null: none).
   * <p>Package-private on purpose: outside the engine the only way in is {@link #forAccount}, which reads ONE account's
   * records from its {@link AccountView}. The parity harness (same package) drives this record-level core directly.
   */
  static List<AdviceNote> buyProgressAdvice(List<BuyOffer> offers, Double targetDurationMinutes, Set<Integer> alreadyFlagged, double now, double max) {
    List<AdviceNote> out = new ArrayList<>();
    if (targetDurationMinutes == null || !JsValues.isFinite(targetDurationMinutes) || targetDurationMinutes <= 0) return out;
    List<Double> order = new ArrayList<>();
    for (BuyOffer o : offers) {
      if (o == null || o.itemId == null || o.firstSeen == null || !JsValues.isFinite(o.firstSeen)) continue;
      double total = JsValues.isFinite(o.total) ? o.total : 0;
      double filled = JsValues.isFinite(o.filled) ? o.filled : 0;
      if (!(total > 0) || filled >= total) continue; // complete: nothing to say
      if (alreadyFlagged != null && alreadyFlagged.contains(o.itemId)) continue; // slotFill is already speaking about it
      double openMs = now - o.firstSeen;
      if (!(openMs > targetDurationMinutes * 60000)) continue;
      String name = o.name != null && !o.name.isEmpty() ? o.name : "item " + o.itemId;
      AdviceNote n = new AdviceNote(o.itemId);
      n.name = name;
      // 'caution' rather than 'warn': nothing has gone wrong, and the player may be content to wait.
      n.level = "caution";
      n.label = filled == 0 ? "No fills yet" : "Part filled";
      n.figures = JsValues.gp(filled) + "/" + JsValues.gp(total) + " · open " + since(openMs);
      n.openMinutes = JsValues.jsRound(openMs / 60000);
      n.filled = filled;
      n.total = total;
      n.message = "Your pace is " + since(targetDurationMinutes * 60000) + ". "
        + "EVI is not predicting whether it will fill -- this is the clock and the progress, nothing more.";
      out.add(n);
      order.add(openMs);
    }
    // Longest open first: a stable sort on (b - a), as the JS sorts.
    List<Integer> idx = new ArrayList<>();
    for (int i = 0; i < out.size(); i++) idx.add(i);
    idx.sort((a, b) -> {
      double d = order.get(b) - order.get(a);
      return d > 0 ? 1 : d < 0 ? -1 : 0;
    });
    List<AdviceNote> sorted = new ArrayList<>();
    for (int i : idx) sorted.add(out.get(i));
    int keep = (int) Math.min(sorted.size(), sliceEnd(Math.max(0, max)));
    return new ArrayList<>(sorted.subList(0, keep));
  }

  /**
   * buyProgressAdvice for ONE account (server.mjs): its live buys, against the pace the player set (null: none -- nothing is
   * said), skipping the items slotFill already flags, with the default cap.
   */
  public static List<AdviceNote> forAccount(AccountView view, Double targetDurationMinutes, Set<Integer> alreadyFlagged, double now) {
    List<BuyOffer> offers = new ArrayList<>();
    for (Offer o : view.liveBuys) offers.add(new BuyOffer(o.itemId, o.name, o.total, o.filled, o.firstSeen == null ? null : (double) o.firstSeen));
    return buyProgressAdvice(offers, targetDurationMinutes, alreadyFlagged, now);
  }

  /** The default cap: {@code max = 3}. */
  static List<AdviceNote> buyProgressAdvice(List<BuyOffer> offers, Double targetDurationMinutes, Set<Integer> alreadyFlagged, double now) {
    return buyProgressAdvice(offers, targetDurationMinutes, alreadyFlagged, now, 3);
  }

  /** {@code slice(0, end)}'s end: ToIntegerOrInfinity (NaN is 0, a fraction truncates). */
  static double sliceEnd(double end) {
    if (Double.isNaN(end)) return 0;
    if (Double.isInfinite(end)) return end;
    return end < 0 ? Math.ceil(end) : Math.floor(end);
  }
}

package com.evi.live.engine;

import com.evi.live.market.HourBucket;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Crash alerts: an item's price collapsing right now, measured against the item's own recent behaviour and stated without
 * predicting what happens next (bridge/crashWatch.mjs: {@code buildBaselines}, {@code detectCrashes},
 * {@code crashMessage}, {@code measuredBandFor} and {@code createCrashWatch}'s state machine, whose {@code isCrashing} is
 * the gate that demotes a crashing buy).
 *
 * <p>WHAT THESE ALERTS DELIBERATELY DO NOT DO is what competing tools' dump alerts do: assume a crashed price rebounds.
 * When a crash is a permanent repricing, that is the adamant-arrows loss with a notification attached. Each alert carries
 * what tools/crash-recovery.mjs measured over 90 days for crashes of the same kind and says plainly it is no forecast.
 *
 * <p>A CRASH, per item, by the rules the measurement used: BOTH sides down (what buyers pay AND what sellers accept) by at
 * least {@link #MIN_DROP} and by {@link #Z} of the item's own typical hourly deviations -- one side alone is the wide-spread
 * instant-sell artefact the first measurement fell for; on real volume ({@link #VOL_RATIO} times the item's own average
 * for the window), so a misclick is not a crash; on an item that trades in most hours, so the baseline means something.
 *
 * <p>PURE. The baselines and the five-minute buckets are handed in; the {@link Watch} takes the clock on every call and
 * reads the archive only through the {@link Watch.HourlySource} its owner supplies, so it does no I/O of its own. NEEDS
 * DEPTH: an item must trade in 117.6 of 168 hours inside a 192-hour window, so a fresh archive never arms it -- which is
 * the documented fail-open state (no baseline, no alert), never a guess.
 */
public final class CrashWatch {
  private CrashWatch() {}

  /** CRASH.z: how many of the item's own hourly deviations both sides must fall. */
  public static final double Z = 4;
  /** CRASH.minDrop: the least fall, on both sides. */
  public static final double MIN_DROP = 0.10;
  /** CRASH.volRatio: units over the window against the item's own normal for that time. */
  public static final double VOL_RATIO = 3;
  /** CRASH.windowMinutes: the five-minute buckets read. */
  public static final int WINDOW_MINUTES = 30;
  static final int BASE_HOURS = 24, WEEK_HOURS = 168, HOUR = 3600;
  /** MAX_ALERT_HOURS: an alert still down after a day is ended as "still down", never as recovered. */
  public static final int MAX_ALERT_HOURS = 24;

  /** The rules detectCrashes applies ({@code CRASH}, or a caller's own). */
  public static final class Rules {
    public final double z;
    public final double minDrop;
    public final double volRatio;
    public final double windowMinutes;

    public Rules(double z, double minDrop, double volRatio, double windowMinutes) {
      this.z = z;
      this.minDrop = minDrop;
      this.volRatio = volRatio;
      this.windowMinutes = windowMinutes;
    }
  }

  public static final Rules CRASH = new Rules(Z, MIN_DROP, VOL_RATIO, WINDOW_MINUTES);

  /** One band of CRASH_MEASURED (19 Sep 2026, 90 days, 548 crashes with a day of data after them). */
  public static final class Band {
    public final String label;
    public final double max;
    public final int n;
    public final double back;
    public final double lower;

    Band(String label, double max, int n, double back, double lower) {
      this.label = label;
      this.max = max;
      this.n = n;
      this.back = back;
      this.lower = lower;
    }
  }

  public static final String MEASURED_ON = "2026-09-19";
  public static final int MEASURED_DAYS = 90;
  public static final List<Band> BANDS = Collections.unmodifiableList(java.util.Arrays.asList(
    new Band("items under 10k", 1e4, 432, 0.57, 0.06),
    new Band("items from 10k to 1m", 1e6, 98, 0.56, 0.06),
    new Band("items over 1m", Double.POSITIVE_INFINITY, 18, 0.22, 0.17)));
  /** CRASH_MEASURED.stillDownAfterHour. */
  public static final double STILL_DOWN_AFTER_HOUR = 0.75;

  /** One side's baseline: its 24-hour volume-weighted average and the deviation of its log gap. */
  public static final class Side {
    public final double base;
    public final double sd;

    public Side(double base, double sd) {
      this.base = base;
      this.sd = sd;
    }
  }

  public static final class Baseline {
    public final Side hi;
    public final Side lo;
    public final double hourlyUnits;

    public Baseline(Side hi, Side lo, double hourlyUnits) {
      this.hi = hi;
      this.lo = lo;
      this.hourlyUnits = hourlyUnits;
    }
  }

  /** A detected crash: prices rounded half-up, the drop and the units unrounded, as detectCrashes reports them. */
  public static final class Crash {
    public final int itemId;
    public final double hi;
    public final double lo;
    public final double baseHi;
    public final double baseLo;
    public final double drop;
    public final double units;
    public final double normalPerHour;

    public Crash(int itemId, double hi, double lo, double baseHi, double baseLo, double drop, double units, double normalPerHour) {
      this.itemId = itemId;
      this.hi = hi;
      this.lo = lo;
      this.baseHi = baseHi;
      this.baseLo = baseLo;
      this.drop = drop;
      this.units = units;
      this.normalPerHour = normalPerHour;
    }

    Crash with(double hi, double lo, double drop, double units) {
      return new Crash(itemId, hi, lo, baseHi, baseLo, drop, units, normalPerHour);
    }
  }

  /**
   * buildBaselines: per item and side, the 24-hour volume-weighted average up to {@code endTs} (seconds), and how far the
   * item's hourly price normally strays from its trailing 24-hour average over the week before. Only buckets inside the
   * 192 hours before {@code endTs} are read; an item with too little history is left OUT, never guessed. Keyed by item id.
   */
  public static Map<Integer, Baseline> buildBaselines(List<HourBucket> hourly, double endTs) {
    double t0 = endTs - (BASE_HOURS + WEEK_HOURS) * (double) HOUR;
    int n = BASE_HOURS + WEEK_HOURS;
    // JS Map keyed by the id STRING, so insertion order; the result is looked up by id, so order never shows.
    Map<Integer, double[][]> grid = new LinkedHashMap<>();
    if (hourly != null) for (HourBucket b : hourly) {
      if (!(b.ts >= t0 && b.ts < endTs)) continue;
      double idx = (b.ts - t0) / HOUR;
      // A typed array ignores a non-integer index (an hour not on the grid): the item is still entered, with nothing set.
      boolean onGrid = idx == Math.floor(idx);
      int i = (int) idx;
      for (int r = 0; r < b.size(); r++) {
        double[][] s = grid.computeIfAbsent(b.id(r), k -> {
          double[] hi = new double[n], lo = new double[n];
          java.util.Arrays.fill(hi, Double.NaN);
          java.util.Arrays.fill(lo, Double.NaN);
          return new double[][]{hi, new double[n], lo, new double[n]};
        });
        if (!onGrid) continue;
        double hi = side(b.avgHigh(r)), hv = b.highVolume(r), lo = side(b.avgLow(r)), lv = b.lowVolume(r);
        if (hi > 0 && hv > 0) {
          s[0][i] = hi;
          s[1][i] = hv;
        }
        if (lo > 0 && lv > 0) {
          s[2][i] = lo;
          s[3][i] = lv;
        }
      }
    }
    Map<Integer, Baseline> out = new TreeMap<>();
    for (Map.Entry<Integer, double[][]> e : grid.entrySet()) {
      double[][] s = e.getValue();
      double traded = 0, units = 0;
      for (int i = BASE_HOURS; i < n; i++) {
        double u = s[1][i] + s[3][i];
        units += u;
        if (u > 0) traded++;
      }
      if (traded < WEEK_HOURS * 0.7) continue;
      Side hi = side(s[0], s[1], n), lo = side(s[2], s[3], n);
      if (hi != null && lo != null) out.put(e.getKey(), new Baseline(hi, lo, units / WEEK_HOURS));
    }
    return out;
  }

  private static double side(long v) {
    return v == HourBucket.NONE ? Double.NaN : v;
  }

  private static double avg(double[] p, double[] v, int from, int to) {
    double gp = 0, u = 0;
    int h = 0;
    for (int j = from; j < to; j++)
      if (v[j] > 0) {
        gp += p[j] * v[j];
        u += v[j];
        h++;
      }
    return h >= BASE_HOURS / 2 ? gp / u : Double.NaN;
  }

  private static Side side(double[] p, double[] v, int n) {
    double sum = 0, sq = 0;
    int c = 0;
    for (int i = BASE_HOURS; i < n; i++) {
      if (!(v[i] > 0)) continue;
      double b = avg(p, v, i - BASE_HOURS, i);
      if (!(b > 0)) continue;
      double d = StrictMath.log(p[i] / b);
      sum += d;
      sq += d * d;
      c++;
    }
    double base = avg(p, v, n - BASE_HOURS, n);
    if (!(c >= 24 && base > 0)) return null;
    double mean = sum / c;
    return new Side(base, Math.sqrt(Math.max(1e-12, sq / c - mean * mean)));
  }

  /** One item's sums over the window (JS windowSums): gp and units per side, counted only where price and units are above 0. */
  static final class Sums {
    double hiGp, hv, loGp, lv;
  }

  /** windowSums, in the JS Map's insertion order: the order buckets come in, ids ascending within each. */
  static Map<Integer, Sums> windowSums(List<HourBucket> fiveMinute) {
    Map<Integer, Sums> sums = new LinkedHashMap<>();
    if (fiveMinute != null) for (HourBucket b : fiveMinute)
      for (int r = 0; r < b.size(); r++) {
        Sums s = sums.computeIfAbsent(b.id(r), k -> new Sums());
        double hi = side(b.avgHigh(r)), hv = b.highVolume(r), lo = side(b.avgLow(r)), lv = b.lowVolume(r);
        if (hi > 0 && hv > 0) {
          s.hiGp += hi * hv;
          s.hv += hv;
        }
        if (lo > 0 && lv > 0) {
          s.loGp += lo * lv;
          s.lv += lv;
        }
      }
    return sums;
  }

  /** detectCrashes: which items are crashing in the given five-minute buckets, in window order. */
  public static List<Crash> detectCrashes(Map<Integer, Baseline> baselines, List<HourBucket> fiveMinute, Rules rules) {
    return detect(baselines, windowSums(fiveMinute), rules);
  }

  public static List<Crash> detectCrashes(Map<Integer, Baseline> baselines, List<HourBucket> fiveMinute) {
    return detectCrashes(baselines, fiveMinute, CRASH);
  }

  private static List<Crash> detect(Map<Integer, Baseline> baselines, Map<Integer, Sums> sums, Rules rules) {
    List<Crash> found = new ArrayList<>();
    double floor = StrictMath.log(1 - rules.minDrop);
    for (Map.Entry<Integer, Sums> e : sums.entrySet()) {
      int itemId = e.getKey();
      Sums s = e.getValue();
      Baseline base = baselines == null ? null : baselines.get(itemId);
      if (base == null || !(s.hv > 0) || !(s.lv > 0)) continue;
      double hi = s.hiGp / s.hv, lo = s.loGp / s.lv;
      double dHi = StrictMath.log(hi / base.hi.base), dLo = StrictMath.log(lo / base.lo.base);
      if (!(dHi < floor && dLo < floor)) continue;
      if (dHi > -rules.z * base.hi.sd || dLo > -rules.z * base.lo.sd) continue;
      double units = s.hv + s.lv, normal = base.hourlyUnits * rules.windowMinutes / 60;
      if (units < rules.volRatio * normal) continue;
      found.add(new Crash(itemId, JsValues.jsRound(hi), JsValues.jsRound(lo), JsValues.jsRound(base.hi.base), JsValues.jsRound(base.lo.base),
        1 - hi / base.hi.base, units, base.hourlyUnits));
    }
    return found;
  }

  /** measuredBandFor: the first band whose ceiling the price is under, or null (a NaN price is under none). */
  public static Band measuredBandFor(double price) {
    for (Band b : BANDS) if (price < b.max) return b;
    return null;
  }

  /**
   * crashMessage: one plain sentence per alert. {@code mine} says why the player is being told (an offer, stock held, or
   * EVI's own current pick); null or empty adds nothing. The numbers are the measured ones; the history is quoted, never
   * extrapolated.
   */
  public static String crashMessage(Crash c, String name, String mine) {
    Band band = measuredBandFor(c.baseHi);
    String perHour = c.normalPerHour >= 10 ? JsValues.gp(c.normalPerHour) : ThinMarket.stripPointZero(JsValues.toFixed(c.normalPerHour, 1));
    String who = name == null || name.isEmpty() ? "Item " + c.itemId : name;
    String head = who + " is crashing: buyers are paying about " + JsValues.gp(c.hi) + " gp, " + JsValues.text(JsValues.jsRound(c.drop * 100))
      + "% under its 24-hour average of " + JsValues.gp(c.baseHi) + " gp, with " + JsValues.gp(c.units) + " traded in the last " + WINDOW_MINUTES
      + " minutes (normally about " + perHour + " an hour).";
    String why = mine != null && !mine.isEmpty() ? " " + mine : "";
    String history = band != null ? " Cause unknown. Of " + band.n + " crashes like this in " + band.label + " over the last " + MEASURED_DAYS + " days, "
      + JsValues.text(JsValues.jsRound(band.back * 100)) + "% had made back most of the drop a day later and " + JsValues.text(JsValues.jsRound(band.lower * 100))
      + "% were lower still" + (band.n < 30 ? " (a small sample)" : "") + ". That is history, not a forecast for this one." : " Cause unknown.";
    return head + why + history;
  }

  /** crashNote's answer: the sidebar line and its tooltip. */
  public static final class Note {
    public final String message;
    public final String detail;

    Note(String message, String detail) {
      this.message = message;
      this.detail = detail;
    }
  }

  /**
   * crashNote (8 Oct 2026, the maintainer: the one-sentence form was a single tooltip line too long to read): the sidebar's crash
   * note in two parts. {@code message} is the line read at a glance (the price buyers pay, the drop, the 24-hour average,
   * and {@code mine}, the player's reason); {@code detail} is the tooltip (the volume against normal, "Cause unknown.", the
   * measured history and its hedge). The same facts as {@link #crashMessage}, tightened; "a day later" because the
   * measurement read the price at the one-day mark.
   */
  public static Note crashNote(Crash c, String name, String mine) {
    Band band = measuredBandFor(c.baseHi);
    String perHour = c.normalPerHour >= 10 ? JsValues.gp(c.normalPerHour) : ThinMarket.stripPointZero(JsValues.toFixed(c.normalPerHour, 1));
    String who = name == null || name.isEmpty() ? "Item " + c.itemId : name;
    String message = who + " is crashing: buyers pay about " + JsValues.gp(c.hi) + " gp, " + JsValues.text(JsValues.jsRound(c.drop * 100))
      + "% under its 24-hour average of " + JsValues.gp(c.baseHi) + " gp." + (mine != null && !mine.isEmpty() ? " " + mine : "");
    String volume = JsValues.gp(c.units) + " traded in the last " + WINDOW_MINUTES + " minutes (normally about " + perHour + " an hour). Cause unknown.";
    String history = band != null ? " Of " + band.n + " similar crashes in " + band.label + " (" + MEASURED_DAYS + " days" + (band.n < 30 ? ", a small sample" : "")
      + "), " + JsValues.text(JsValues.jsRound(band.back * 100)) + "% had made back most of the drop a day later and "
      + JsValues.text(JsValues.jsRound(band.lower * 100)) + "% were lower still. History, not a forecast." : "";
    return new Note(message, volume + history);
  }

  /**
   * createCrashWatch's live state, with the clock passed in on every call: baselines rebuilt at most hourly, the last
   * {@link #WINDOW_MINUTES} of five-minute buckets held, alerts kept for a day after they end, every start and end handed
   * to the {@link Recorder}.
   *
   * <p>Once an alert runs it is judged against the price from BEFORE the crash, not the rolling average (crash hours drag
   * the 24-hour average down to meet the new price, and the alert would "end" with the price still on the floor). It ends
   * when buyers pay within half the minimum drop of that old price, or after {@link #MAX_ALERT_HOURS}, marked still down.
   * A window with no buying at all changes nothing.
   *
   * <p>NOT THREAD-SAFE, deliberately: like every engine piece it belongs to the one worker that owns the engine.
   */
  public static final class Watch {
    /** The hourly archive from {@code fromTs} (seconds) on, oldest first. May throw: a failure keeps the last baselines. */
    public interface HourlySource {
      List<HourBucket> load(double fromTs) throws Exception;
    }

    /** The five-minute buckets from {@code fromTs} on, read once when the window is first needed. May throw (nothing read). */
    public interface FiveMinuteSource {
      List<HourBucket> load(double fromTs) throws Exception;
    }

    /** Where each alert's start and end go, so these calls can be scored later. */
    public interface Recorder {
      void record(String event, double at, Crash crash, String because);
    }

    /** One alert: the crash (updated while it runs), when it started and was last updated, and how it ended. */
    public static final class Alert {
      public final int itemId;
      public Crash crash;
      public final double since;
      public double updated;
      public Double ended;
      public String endedBecause;

      Alert(int itemId, Crash crash, double since) {
        this.itemId = itemId;
        this.crash = crash;
        this.since = since;
        this.updated = since;
      }
    }

    private final HourlySource loadHourly;
    private final FiveMinuteSource loadFiveMinute;
    private final Recorder recorder;
    private Map<Integer, Baseline> baselines;
    private double baselinesFor = Double.NaN;
    private List<HourBucket> window;
    private final Map<Integer, Alert> alerts = new LinkedHashMap<>();

    /** Any source may be null: no archive (an empty one), no five-minute read at start, nothing recorded. */
    public Watch(HourlySource loadHourly, FiveMinuteSource loadFiveMinute, Recorder recorder) {
      this.loadHourly = loadHourly;
      this.loadFiveMinute = loadFiveMinute;
      this.recorder = recorder;
    }

    private Map<Integer, Baseline> ensureBaselines(double nowMs) {
      double hourStart = Math.floor(nowMs / 3600000) * 3600;
      if (baselines != null && baselinesFor == hourStart) return baselines;
      try {
        List<HourBucket> hourly = loadHourly == null ? null : loadHourly.load(hourStart - (BASE_HOURS + WEEK_HOURS + 1) * (double) HOUR);
        baselines = buildBaselines(hourly, hourStart);
        baselinesFor = hourStart;
      } catch (Exception e) {
        // The JS logs and keeps what it had (or nothing). An Error is a fault, never "no archive".
        if (baselines == null) baselines = new TreeMap<>();
      }
      return baselines;
    }

    private void end(int id, Alert a, double t, String because) {
      a.ended = t;
      a.endedBecause = because;
      if (recorder != null) recorder.record("crash-ended", t, a.crash, because);
    }

    /**
     * addFiveMinute: one stored five-minute bucket (null: just re-judge the window). Returns the crashes detected in the
     * window now -- running alerts included, as the JS returns them.
     */
    public List<Crash> addFiveMinute(HourBucket bucket, double nowMs) {
      if (window == null) {
        window = new ArrayList<>();
        try {
          List<HourBucket> first = loadFiveMinute == null ? null : loadFiveMinute.load(Math.floor(nowMs / 1000) - WINDOW_MINUTES * 60.0);
          if (first != null) window.addAll(first);
        } catch (Exception e) {
          // nothing read: the window starts empty
        }
      }
      if (bucket != null) {
        boolean seen = false;
        for (HourBucket b : window) if (b.ts == bucket.ts) seen = true;
        if (!seen) window.add(bucket);
      }
      if (window.isEmpty()) return new ArrayList<>();
      long newest = Long.MIN_VALUE;
      for (HourBucket b : window) newest = Math.max(newest, b.ts);
      List<HourBucket> kept = new ArrayList<>();
      for (HourBucket b : window) if (b.ts > newest - WINDOW_MINUTES * 60L) kept.add(b);
      kept.sort((a, b) -> Long.compare(a.ts, b.ts)); // stable, as JS's sort
      window = kept;
      List<Crash> found = detectCrashes(ensureBaselines(nowMs), window);
      double t = nowMs;
      Map<Integer, Sums> sums = windowSums(window);
      for (Crash c : found) {
        Alert a = alerts.get(c.itemId);
        if (a != null && a.ended == null) continue;
        // A re-set key keeps its place in a JS Map: an ended alert replaced by a new crash stays where it was.
        alerts.put(c.itemId, new Alert(c.itemId, c, t));
        if (recorder != null) recorder.record("crash", t, c, null);
      }
      List<Integer> expired = new ArrayList<>();
      for (Map.Entry<Integer, Alert> e : alerts.entrySet()) {
        int id = e.getKey();
        Alert a = e.getValue();
        if (a.ended != null) {
          if (t - a.ended > 24 * 3600000.0) expired.add(id);
          continue;
        }
        Sums s = sums.get(id);
        if (s != null && s.hv > 0) {
          double hi = s.hiGp / s.hv;
          a.crash = a.crash.with(JsValues.jsRound(hi), s.lv > 0 ? JsValues.jsRound(s.loGp / s.lv) : a.crash.lo, 1 - hi / a.crash.baseHi, s.hv + s.lv);
          a.updated = t;
          if (hi >= a.crash.baseHi * (1 - MIN_DROP / 2)) {
            end(id, a, t, "recovered");
            continue;
          }
        }
        if (t - a.since > MAX_ALERT_HOURS * 3600000.0) end(id, a, t, "still down after a day");
      }
      for (Integer id : expired) alerts.remove(id);
      return found;
    }

    /** isCrashing: the running alert's crash, or null. THE GATE: a crashing buy is demoted with the alert as its warning. */
    public Crash isCrashing(int itemId) {
      Alert a = alerts.get(itemId);
      return a != null && a.ended == null ? a.crash : null;
    }

    /** active(): the running alerts, in the order they started. */
    public List<Alert> active() {
      List<Alert> out = new ArrayList<>();
      for (Alert a : alerts.values()) if (a.ended == null) out.add(a);
      return out;
    }

    /** recent(): every alert still held (running, or ended within a day), newest first. */
    public List<Alert> recent() {
      List<Alert> out = new ArrayList<>(alerts.values());
      out.sort((a, b) -> {
        double d = b.since - a.since;
        return d > 0 ? 1 : d < 0 ? -1 : 0;
      });
      return out;
    }

    /** status(): whether a window is held, its size, and how many items have a baseline. */
    public int windowBuckets() {
      return window == null ? 0 : window.size();
    }

    public boolean watching() {
      return window != null && !window.isEmpty();
    }

    public int itemsWithBaseline() {
      return baselines == null ? 0 : baselines.size();
    }
  }
}

