  /**
   * The answer: the body of the bridge's GET /api/suggestion ({@link ResponseJson#response} writes it), plus two
   * diagnostics the suggestion log records and the plugin never sees. A failed request ({@link #error} set) carries
   * nothing else, as the bridge's 502 does.
   */
  public static final class Response {
    public final String error;
    public Pick suggestion;
    public final List<Pick> additional = new ArrayList<>();
    public ItemPrice openItemPrice;
    public final List<ItemPrice> slotPrices = new ArrayList<>();
    public final List<SlotFill> slotFill = new ArrayList<>();
    public List<AdviceNote> relistAdvice = new ArrayList<>();
    public Slots slots;
    public Profit profit;
    public Reachable reachable;
    public FellThrough fellThroughFromHistory;
    /** The first {@link #HELD_BACK_SHOWN} rows of {@link #heldBackAll}. */
    public List<HeldBack> heldBack = new ArrayList<>();
    /** LOG ONLY: every row held back on this poll. */
    public List<HeldBack> heldBackAll = new ArrayList<>();
    /** LOG ONLY: buy picks the sell-support check demoted on this poll, whichever pick ended up shown. */
    public final List<Pick> demotedPicks = new ArrayList<>();
    /**
     * NOT SENT: the bag the idle-stock tier read on this poll (server.mjs's lastInventory: set only when that tier was reached
     * with a non-empty inventory=, keyed by item id, the quantity as parseInt read it; an id past an item id's range counts as
     * a reading but names no item, so it is not in the map). Null when the tier did not read one. The plugin's "Yours, not
     * stock" mark takes its kept count from it, as the bridge's /personal-use route does.
     */
    public Map<Integer, Double> inventoryRead;
    /** LOG ONLY: the cash READING (not the cap), null when none was sent. */
    public Double cashReading;
    /** For a failed request that was not a missing input: what failed (never sent to the plugin). */
    public final RuntimeException cause;

    Response(String error, RuntimeException cause) {
      this.error = error;
      this.cause = cause;
    }

    public boolean failed() {
      return error != null;
    }
  }

  /** What the bridge's catch turns into a 502: a market input the request needs is missing. */
  static final class Unavailable extends RuntimeException {
    Unavailable(String message) {
      super(message);
    }
  }

  // ========================================================================================== decide

  /** A 502 still carries the bag the idle-stock tier read before the failure: server.mjs set lastInventory before it threw. */
  private static Response failed(Response r, Run run) {
    if (run != null && run.inventoryRead != null) r.inventoryRead = Collections.unmodifiableMap(run.inventoryRead);
    return r;
  }

  /**
   * One GET /api/suggestion.
   *
   * @param query the plugin's request ({@link Query#parse} of the very query text it sends the bridge)
   * @param view the asking account's slice of the journal ({@link AccountView#of} for {@code query.get("account")};
   *             {@link AccountView#nobody()} for a poll that names none) -- it must be the account the query names
   * @param journal the deliberately shared journal parts ({@link SharedJournal#of})
   * @param allAccountsJournalOffers EVERY account's journal offers ({@code store.offers()}): read by the fill model only
   * @param market the market snapshot
   * @param prefs the trading preferences
   * @param hooks the injected sell-support series (and the opt-in forecast, cushion and correlation)
   * @param now the request's clock, epoch ms
   * @return the answer; {@link Response#failed()} where the bridge would answer 502
   */
  public static Response decide(Query query, AccountView view, SharedJournal journal, Collection<Offer> allAccountsJournalOffers, MarketData market,
                                Prefs prefs, Hooks hooks, long now) {
    String account = emptyAsNull(query.get("account"));
    AccountView v = view == null ? AccountView.nobody() : view;
    if (!Objects.equals(v.account, account))
      throw new IllegalArgumentException("the account view (" + v.account + ") is not the account the request names (" + account + ")");
    Run run = null;
    try {
      run = new Run(query, v, journal, allAccountsJournalOffers, market == null ? new MarketData() : market, prefs == null ? Prefs.DEFAULT : prefs,
        hooks == null ? new Hooks() : hooks, now, account);
      return run.run();
    } catch (Unavailable e) {
      // server.mjs: } catch(e) {return send(502,{error:e.message});} -- a market input the request needs is missing.
      return failed(new Response(e.getMessage(), null), run);
    } catch (RuntimeException e) {
      // Any other failure the bridge would not have caught itself is also its 502; the cause is kept for the log and the
      // tests. An Error (an assertion, the JVM) is never an answer and propagates.
      return failed(new Response(e.toString(), e), run);
    }
  }

  /** One request's state, built in the bridge's order. */
  private static final class Run {
    final Query q;
    final AccountView view;
    final SharedJournal journal;
    final Collection<Offer> allOffers;
    final MarketData market;
    final Prefs prefs;
    final Hooks hooks;
    final long now;
    final String account;

    final List<HeldBack> heldBack = new ArrayList<>();
    final List<Pick> demotedPicks = new ArrayList<>();
    Map<Integer, Double> inventoryRead;
    LatestPrices latest;
    HourBucket volumes;
    double minProfit;
    boolean minProfitChosen;
    boolean requireMarginOverTax;
    Double maxSpend;
    Double target;
    String risk;
    LevelSettings level;
    String forecastHorizon;
    String forecastPolicy;
    boolean requireCushion;
    boolean taxFreeOnly;
    boolean bigger;
    double maxStackShare;
    Sizing.ItemGate gate = Sizing.ItemGate.NONE;
    Set<Integer> blocklist;
    Set<Integer> exposure;
    boolean includeMarket;
    String wantSource;
    MarketTier.Ranking marketRanking;

    Run(Query q, AccountView view, SharedJournal journal, Collection<Offer> allOffers, MarketData market, Prefs prefs, Hooks hooks, long now, String account) {
      this.q = q;
      this.view = view;
      this.journal = journal;
      this.allOffers = allOffers == null ? Collections.emptyList() : allOffers;
      this.market = market;
      this.prefs = prefs;
      this.hooks = hooks;
      this.now = now;
      this.account = account;
    }

    Response run() {
      latest = market.latest;
      if (latest == null) throw new Unavailable("no /latest prices");
      // suggestionPolicy
      double askedFor = Math.max(0, orZero(number(q.get("minProfit"))));
      minProfitChosen = askedFor > 0;
      double cashParam = QueryValues.cashFromQuery(q.get("cash"));
      minProfit = minProfitChosen ? askedFor : Policy.autoMinProfit(cashParam);
      requireMarginOverTax = askedFor != 1;
      blocklist = new LinkedHashSet<>();
      addItemIds(blocklist, q.get("blocklist"));
      addItemIds(blocklist, q.get("exclude"));
      String riskParam = q.get("risk");
      risk = "low".equals(riskParam) || "medium".equals(riskParam) || "high".equals(riskParam) ? riskParam : "low";
      level = LevelSettings.forRequest(risk);
      maxSpend = QueryValues.maxSpendFromQuery(q.get("cash"), q.get("account"));
      target = Sizing.duration(number(q.get("duration")));
      volumes = market.latestHour;
      String forecastParam = q.get("forecast");
      forecastHorizon = "1h".equals(forecastParam) || "6h".equals(forecastParam) || "overnight".equals(forecastParam) ? forecastParam : null;
      forecastPolicy = "skip".equals(q.get("onForecast")) ? "skip" : "warn";
      boolean freeToPlayWorld = "0".equals(q.get("members"));
      String focus = Focus.resolveFocus(q.get("focus"), prefs.focus);
      if (freeToPlayWorld || account != null || !"any".equals(focus)) gate = RequestGates.of(catalog(), freeToPlayWorld, focus, view, target, now);
      maxStackShare = QueryValues.maxStackShare(q.get("stackShare"));
      taxFreeOnly = "starter".equals(q.get("profile"));
      requireCushion = "1".equals(q.get("cushion"));
      bigger = "bigger".equals(q.get("sizing"));
      GeSlots.Capacity capacity = GeSlots.slotCapacity(q.get("freeSlots"), q.get("collectable"));
      boolean geFull = capacity.full;
      String sourceParam = q.get("source");
      wantSource = "market".equals(sourceParam) || "both".equals(sourceParam) ? sourceParam : "history";
      includeMarket = "1".equals(q.get("includeMarket"));
      boolean history = !"market".equals(wantSource);

      // The slot reserve: only lots the plugin CONFIRMED are in the inventory owe an exit.
      Set<Integer> confirmedHeld = new LinkedHashSet<>();
      addItemIds(confirmedHeld, q.get("heldPositions"));
      List<Integer> positionItems = view.positionItems();
      GeSlots.Exposure ex = view.slotExposure(confirmedHeld);
      exposure = new LinkedHashSet<>(ex.exposure);
      int sellSlotsOwed = ex.sellSlotsOwed;
      boolean buysHeldForExits = capacity.free != null && !geFull && capacity.free <= sellSlotsOwed;
      double holdBuyPriceParam = number(q.get("holdBuyPrice"));
      double holdBuyPrice = JsValues.isFinite(holdBuyPriceParam) && holdBuyPriceParam > 0 ? holdBuyPriceParam : Double.NaN;

      // --- the holding tier: the plugin's live signal, then the journal's open position for THIS account
      Pick suggestion = null;
      if (!geFull) suggestion = holdingOf(number(q.get("holdItemId")), number(q.get("holdQty")), emptyAsNull(q.get("holdName")),
        emptyAsNull(q.get("holdBuyId")), holdBuyPrice, null);
      if (suggestion == null && !geFull) {
        FifoMatcher.OpenPosition open = view.pickPersistentOpenPosition(blocklist);
        if (open != null) {
          suggestion = holdingOf(open.itemId, open.remaining, open.item, open.buyId, open.unitCost, open.endedUnseen);
          if (suggestion != null) suggestion.persisted = true;
        }
      }
      // --- the idle-stock tier (opt-in): stock in the bag with no observed buy behind it
      if (suggestion == null && !geFull && "1".equals(q.get("includeInventory"))) {
        TreeMap<Integer, Long> inventory = new TreeMap<>();
        Map<Integer, Double> read = new LinkedHashMap<>();
        boolean anyInventory = false;
        String raw = q.get("inventory");
        for (String pair : (raw == null ? "" : raw).split(",", -1)) {
          String[] parts = pair.split(":", -1);
          double id = parseInt(parts[0]), qty = parts.length > 1 ? parseInt(parts[1]) : Double.NaN;
          if (!(JsValues.isFinite(id) && id > 0 && JsValues.isFinite(qty) && qty > 0)) continue;
          anyInventory = true; // Object.keys(inventory).length counts an id past an item id's range too
          Integer item = itemIdOf(id);
          if (item != null) inventory.put(item, (long) qty); // past the range: no price, so never offered
          if (item != null) read.put(item, qty);
        }
        if (anyInventory) inventoryRead = read;
        if (anyInventory) {
          ItemCatalog catalog = catalog();
          HoldingTiers.InventoryOptions o = new HoldingTiers.InventoryOptions();
          Set<Integer> inventoryBlocklist = new LinkedHashSet<>(blocklist);
          inventoryBlocklist.addAll(journal.personalUseItemIds);
          o.blocklist = inventoryBlocklist;
          o.positionItemIds = view.positionItemsWithCost();
          o.membersBlocked = freeToPlayWorld ? gate::membersBlocked : null;
          o.keptForUse = journal.personalUseKept;
          suggestion = HoldingTiers.computeInventorySuggestion(latest, inventory, HoldingTiers.namesOf(catalog.items()), o);
        }
      }
      // Blocked with the sidebar's Block button: never BOUGHT again, added only AFTER the sell-side tiers above.
      blocklist.addAll(prefs.blocked);

      // --- the personal-history tier
      if (suggestion == null && !geFull && !buysHeldForExits && history)
        suggestion = historyChainUnderAuto(onBlocked -> chain(historyRank(minProfit, maxSpend), support(minProfit), blocklist, onBlocked, demotedPicks::add));
      // "Best of both": a history BUY is set aside to be compared with the market's pick, rather than ending the search.
      Pick historyPick = HoldingTiers.comparableAsHistoryPick(suggestion, wantSource) ? suggestion : null;
      if (historyPick != null) suggestion = null;
      Reachable reachable = null;
      FellThrough fellThrough = null;
      if (suggestion == null && !geFull && !buysHeldForExits && includeMarket) {
        MarketTier.Ranking ranking = ranking();
        // Its OWN copy of the blocklist: the chain adds to the set it is handed.
        Pick marketPick = PickChain.pick(chain(ranking.ranked(minProfit), support(minProfit), new LinkedHashSet<>(blocklist), this::holdBack,
          demotedPicks::add));
        suggestion = marketPick;
        // Say so when the floor, not an empty history, is why the player's own history was passed over.
        if (suggestion != null && !minProfitChosen) {
          try {
            Pick ownBest = HistoryTier.computeSuggestion(journal.flips, latest, now, historyOptions(0, blocklist, maxSpend));
            if (ownBest != null && ownBest.itemId != suggestion.itemId) fellThrough = new FellThrough(ownBest.name);
          } catch (Exception e) {
            // the bridge's catch: no note
          }
        }
        // Nothing to show AND a minimum set: the best figure reachable at a lower rung, through the SAME checks.
        if (suggestion == null && minProfit > 0) {
          try {
            reachable = reachableProbe(history);
          } catch (Exception e) {
            reachable = null;
          }
        }
      }
      // --- "Best of both": keep whichever pick is worth more at the price buyers are paying; ties go to the history.
      if (historyPick != null) {
        if (suggestion == null) suggestion = historyPick;
        else {
          Worth own = worthOf(historyPick), wide = worthOf(suggestion);
          if (own.value >= wide.value) {
            heldBack.add(new HeldBack(suggestion.itemId, "A market-wide pick worth about " + JsValues.gp(wide.value) + " gp, set aside for your own "
              + historyPick.name + " at about " + JsValues.gp(own.value) + " gp."));
            suggestion = historyPick;
          } else {
            heldBack.add(new HeldBack(historyPick.itemId, "Your own " + historyPick.name + " is worth about " + JsValues.gp(own.value)
              + " gp at the price buyers are paying, against " + JsValues.gp(wide.value) + " gp for this market-wide pick, so EVI set your history aside this time."));
          }
        }
      }
      // --- Auto never goes silent: the step-down to the 500 gp floor, every safety check intact and judged AT that floor
      boolean steppedDown = false;
      if (suggestion == null && !minProfitChosen && !geFull && !buysHeldForExits && minProfit > Policy.AUTO_MIN_PROFIT) {
        Pick stepped = null;
        if (history) {
          try {
            stepped = historyChainUnderAuto(onBlocked -> chain(historyRank(Policy.AUTO_MIN_PROFIT, maxSpend), support(Policy.AUTO_MIN_PROFIT), blocklist,
              onBlocked, demotedPicks::add));
          } catch (Exception e) {
            stepped = null;
          }
        }
        if (stepped == null && includeMarket) {
          try {
            stepped = PickChain.pick(chain(bl -> ranking().rankAt(bl, maxSpend, Policy.AUTO_MIN_PROFIT), support(Policy.AUTO_MIN_PROFIT), blocklist,
              this::holdBack, demotedPicks::add));
          } catch (Exception e) {
            stepped = null;
          }
        }
        if (stepped != null) {
          suggestion = stepped;
          steppedDown = true;
          suggestion.belowUsualBar = minProfit;
          suggestion.reasoning = (suggestion.reasoning != null && !suggestion.reasoning.isEmpty() ? suggestion.reasoning + " " : "")
            + "Smaller than usual: nothing reached the " + JsValues.gp(minProfit)
            + " gp Auto is aiming for with this cash stack, so this is the best trade available right now. Every safety check still applies to it.";
        }
      }
      // --- further positions, only when asked for: each ranked on the cash still unspent, through every check
      Response out = new Response(null, null);
      int wantPositions = positionsWanted(q.get("maxSuggestions"));
      if (suggestion != null && wantPositions > 1 && !geFull && !buysHeldForExits) {
        int slotsLeft = capacity.free == null ? wantPositions - 1 : Math.max(0, capacity.free - sellSlotsOwed - 1);
        // Only a BUY spends cash (fix (4)): a holding SELL carries the item's live low as its buyPrice.
        Double budget = maxSpend == null ? null : Math.max(0, maxSpend - (suggestion.isBuy() ? (double) suggestion.buyPrice * suggestion.quantity : 0));
        // Ranked AND judged at the main pick's minimum: the 500 floor after a step-down (fix (5) and the leftover fix (2)).
        double extrasMinimum = steppedDown ? Policy.AUTO_MIN_PROFIT : minProfit;
        Pick previous = suggestion;
        while (out.additional.size() < wantPositions - 1 && slotsLeft > 0) {
          // The position just taken is exposure now (correlation refuses its twin) and never picked again.
          exposure.add(previous.itemId);
          blocklist.add(previous.itemId);
          Double spend = budget;
          if (spend != null && !(spend > 0)) break;
          Pick next = null;
          // Sized like the main pick (fix (3)): the same typical-hour sizing, capture cap and window share.
          if (history) next = PickChain.pick(chain(historyRank(extrasMinimum, spend), support(extrasMinimum), blocklist, null, null));
          if (next == null && includeMarket)
            next = PickChain.pick(chain(bl -> ranking().rankAt(bl, spend, extrasMinimum), support(extrasMinimum), blocklist, null, null));
          if (next == null) break;
          out.additional.add(next);
          if (budget != null) budget = Math.max(0, budget - (double) next.buyPrice * next.quantity);
          slotsLeft--;
          previous = next;
        }
      }
      // --- the open offer's own price, with what this account paid for it
      double openItemId = number(q.get("openItemId"));
      ItemPrice openItemPrice = JsValues.isFinite(openItemId) ? Prices.lookupItemPrice(latest, openItemId) : null;
      if (openItemPrice != null) {
        double unitCost = Double.NaN, heldQty = 1;
        if (number(q.get("holdItemId")) == openItemId && JsValues.isFinite(holdBuyPrice)) {
          unitCost = holdBuyPrice;
          double hq = number(q.get("holdQty"));
          heldQty = Double.isNaN(hq) || hq == 0 ? 1 : hq; // Number(x) || 1
        } else {
          CostBasis basis = view.heldCostBasis(openItemPrice.itemId);
          if (basis != null) {
            unitCost = basis.unitCost;
            heldQty = basis.quantity;
          }
        }
        openItemPrice = Prices.withCostBasis(openItemPrice, unitCost, heldQty);
      }
      out.openItemPrice = openItemPrice;
      // --- the running offers' prices and, with a pace set, how long their remaining quantity typically takes
      String slots = q.get("slots");
      for (String pair : (slots == null ? "" : slots).split(",", -1)) {
        String[] parts = pair.split(":", -1);
        double id = parseInt(parts[0]), remaining = parts.length > 1 ? parseInt(parts[1]) : Double.NaN;
        if (!(JsValues.isFinite(id) && id > 0 && JsValues.isFinite(remaining) && remaining > 0)) continue;
        ItemPrice p = Prices.lookupItemPrice(latest, id);
        if (p != null) out.slotPrices.add(p);
        if (target != null) {
          Integer item = itemIdOf(id); // volumes[String(id)]: an id past the range has no row
          Sizing.OfferFill f = Sizing.estimateOfferFill(remaining, item == null ? null : VolumeRow.of(volumes, item), target);
          if (f != null) out.slotFill.add(new SlotFill(id, f.estimatedFillMinutes, f.likelyToFillInTime));
        }
      }
      // --- the player's own fill record for an order this size (EVERY account's offers: the one deliberate exception)
      if (suggestion != null && suggestion.isBuy()) {
        FillModel.Model model = market.fillModel == null ? null : market.fillModel.model(allOffers, now);
        suggestion.reasoning = SafetyChecks.fillSentence(suggestion.reasoning, model, suggestion, VolumeRow.of(volumes, suggestion.itemId), target);
      }
      String capacityNote = GeSlots.slotNote(capacity);
      if (suggestion != null && capacityNote != null) suggestion.reasoning = (suggestion.reasoning == null ? "" : suggestion.reasoning) + " " + capacityNote;
      if (suggestion != null && !suggestion.isBuy() && freeToPlayWorld && gate.membersBlocked(suggestion.itemId))
        suggestion.reasoning = (suggestion.reasoning == null ? "" : suggestion.reasoning) + MEMBERS_NOTE;
      // --- the fill history behind whichever buy pick survived, stated unless a warning already said it
      ThinMarket.Stats thinStats = null;
      if (suggestion != null && suggestion.isBuy()) {
        try {
          thinStats = market.thin == null ? null : market.thin.get(suggestion.itemId);
          suggestion.reasoning = SafetyChecks.withThinContext(suggestion.reasoning, thinStats, suggestion, target);
        } catch (Exception e) {
          // the bridge's catch: no statement (thinStats keeps whatever was read)
        }
      }
      // --- the advice channel, for THIS account only
      AdviceNotes.Inputs advice = new AdviceNotes.Inputs();
      advice.view = view;
      advice.marketLatest = latest;
      advice.targetDurationMinutes = target;
      Set<Integer> slow = new LinkedHashSet<>();
      for (SlotFill f : out.slotFill) {
        Integer id = itemIdOf(f.itemId);
        if (!f.likelyToFillInTime && id != null) slow.add(id);
      }
      advice.slowFillItemIds = slow;
      advice.suggestedItemId = suggestion == null ? null : suggestion.itemId;
      advice.crashWatch = market.crashWatch;
      advice.now = now;
      out.relistAdvice = AdviceNotes.compose(advice);
      // --- the headline enrichment, the primary with its fill-history reading and every extra position without one
      Verdict.enrich(suggestion, thinStats == null ? null : (int) thinStats.hoursTraded, thinStats == null ? null : (int) thinStats.hours);
      for (Pick a : out.additional) Verdict.enrich(a, null, null);

      out.suggestion = suggestion;
      out.slots = new Slots(capacity, sellSlotsOwed, buysHeldForExits, positionItems);
      out.profit = journal.profit;
      out.reachable = reachable;
      out.fellThroughFromHistory = fellThrough;
      out.heldBackAll = Collections.unmodifiableList(new ArrayList<>(heldBack));
      out.heldBack = Collections.unmodifiableList(new ArrayList<>(heldBack.subList(0, Math.min(HELD_BACK_SHOWN, heldBack.size()))));
      out.demotedPicks.addAll(demotedPicks);
      out.inventoryRead = inventoryRead == null ? null : Collections.unmodifiableMap(inventoryRead);
      out.cashReading = JsValues.isFinite(cashParam) && cashParam >= 0 ? cashParam : null;
      return out;
    }

    // ---------------------------------------------------------------------------------------------- the tiers' pieces

    ItemCatalog catalog() {
      if (market.catalog == null) throw new Unavailable("the item mapping is not available yet");
      return market.catalog;
    }

    /**
     * server.mjs's market rankers ({@code rank} and {@code marketRankAt}, both with this account's spread rank), built
     * once: they need the mapping and the latest hour, and without either the bridge's fetch would have failed.
     */
    MarketTier.Ranking ranking() {
      if (marketRanking != null) return marketRanking;
      ItemCatalog catalog = catalog();
      if (volumes == null) throw new Unavailable("the latest hour's volumes are not available");
      MarketTier.Options shared = new MarketTier.Options();
      shared.targetDurationMinutes = target == null ? Double.NaN : target;
      shared.now = now;
      shared.maxStackShare = maxStackShare;
      shared.taxFreeOnly = taxFreeOnly;
      shared.requireMarginOverTax = requireMarginOverTax;
      shared.rankPrices = market.rankPrices;
      shared.rankBy = level.marketRankBy;
      shared.typicalVolumes = market.typicalVolumes;
      shared.captureCap = prefs.captureCap;
      if (bigger) {
        shared.volumeWindowShare = Policy.BIGGER_POSITIONS_WINDOW_SHARE;
        shared.minVolumeInWindow = Policy.BIGGER_POSITIONS_MIN_VOLUME_IN_WINDOW;
      }
      shared.gate = gate;
      shared.level = level;
      marketRanking = new MarketTier.Ranking(catalog.items(), latest, volumes, shared, maxSpend, SpreadRank.spreadRankFor(account, prefs.spread));
      return marketRanking;
    }

    /** {@code onBlocked: rows => heldBack.push(...rows)}. */
    void holdBack(List<PickChain.Blocked> rows) {
      for (PickChain.Blocked b : rows) heldBack.add(row(b));
    }

    /** server.mjs's holdingOf: the reminder, unless that item is already listed by this account, and only if it should pre-empt. */
    Pick holdingOf(double holdItemId, double holdQty, String name, String buyId, double buyPrice, FifoMatcher.EndedUnseenMark endedUnseen) {
      if (!JsValues.isFinite(holdItemId) || holdItemId <= 0 || !JsValues.isFinite(holdQty) || holdQty <= 0) return null;
      Integer item = itemIdOf(holdItemId); // latestPrices[String(id)]: only a whole id in range names an item
      if (item == null) return null;
      Pick s = HoldingTiers.computeHoldingSuggestion(latest, item, JsValues.exactLong(holdQty), name, buyId, buyPrice, endedUnseen);
      if (s == null) return null;
      if (view.hasLiveSellOffer(s.itemId)) return null;
      return HoldingTiers.holdingPreempts(s, minProfit) ? s : null;
    }

    HistoryTier.Options historyOptions(double mp, Set<Integer> bl, Double spend) {
      HistoryTier.Options o = new HistoryTier.Options();
      o.minProfit = mp;
      o.blocklist = bl;
      o.risk = risk;
      o.maxSpend = spend == null ? Double.NaN : spend;
      o.targetDurationMinutes = target == null ? Double.NaN : target;
      o.volumes = volumes;
      o.maxStackShare = maxStackShare;
      o.typicalVolumes = market.typicalVolumes;
      o.captureCap = prefs.captureCap;
      if (bigger) o.volumeWindowShare = Policy.BIGGER_POSITIONS_WINDOW_SHARE;
      o.gate = gate;
      o.requireMarginOverTax = requireMarginOverTax;
      return o;
    }

    /** The history tier at a minimum and a budget, as a pick chain's ranking. */
    PickChain.Rank historyRank(double mp, Double spend) {
      return bl -> HistoryTier.computeSuggestion(journal.flips, latest, now, historyOptions(mp, bl, spend));
    }

    /** One pickWithForecast: the request's forecast, cushion and correlation, and sell support at {@code support}'s bar. */
    PickChain.Options chain(PickChain.Rank rank, PickChain.SupportHook support, Set<Integer> bl, Consumer<List<PickChain.Blocked>> onBlocked,
                            Consumer<Pick> onDemoted) {
      PickChain.Options c = new PickChain.Options();
      c.rank = rank;
      c.forecastFor = hooks.forecast == null ? null : itemId -> {
        try {
          return hooks.forecast.forecastFor(itemId, forecastHorizon);
        } catch (Exception e) {
          return null; // forecastForSuggestion never throws: no forecast for that one call
        }
      };
      c.policy = forecastPolicy;
      c.horizon = forecastHorizon;
      c.cushionFor = hooks.cushion == null ? null : cand -> {
        try {
          return hooks.cushion.cushionFor(cand);
        } catch (Exception e) {
          return null;
        }
      };
      c.requireCushion = requireCushion;
      c.correlationFor = hooks.correlation == null ? null : cand -> {
        try {
          if (cand == null || !cand.isBuy()) return null;
          List<Integer> held = new ArrayList<>();
          for (Integer id : exposure) if (id != cand.itemId) held.add(id);
          if (held.isEmpty()) return null;
          return hooks.correlation.against(cand, held);
        } catch (Exception e) {
          return null;
        }
      };
      c.supportFor = support;
      c.blocklist = bl;
      c.onBlocked = onBlocked;
      c.onDemoted = onDemoted;
      return c;
    }

    /**
     * historyChainUnderAuto (fix (1), 7 Oct): under Auto a history chain that HELD picks back and returned nothing runs
     * again -- the held-back items are already on the shared blocklist, so each pass ranks the next candidates -- until a
     * pass returns a pick or holds nothing back. A chosen minimum runs it once.
     */
    Pick historyChainUnderAuto(Function<Consumer<List<PickChain.Blocked>>, PickChain.Options> chain) {
      int[] held = {0};
      Consumer<List<PickChain.Blocked>> onBlocked = rows -> {
        holdBack(rows);
        held[0] += rows.size();
      };
      Pick pick = PickChain.pick(chain.apply(onBlocked));
      while (pick == null && !minProfitChosen && held[0] > 0) {
        held[0] = 0;
        pick = PickChain.pick(chain.apply(onBlocked));
      }
      return pick;
    }

    // ---------------------------------------------------------------------------------------------- sell support

    /** The archive's hours inside the sell-support window, oldest first ({@code archive.recentHourly(from)}). */
    List<HourBucket> archivedSince() {
      double from = Math.floor(now / 3600000.0) * 3600 - SellSupport.SELL_SUPPORT_HOURS * 3600;
      List<HourBucket> out = new ArrayList<>();
      if (market.recentHours != null) for (HourBucket b : market.recentHours) if (b != null && b.ts >= from) out.add(b);
      out.sort((a, b) -> Long.compare(a.ts, b.ts));
      return out;
    }

    /** The injected series in the bridge's own try: anything it throws is "no series". */
    List<SellSupport.Point> seriesFor(int itemId) {
      if (hooks.sellSeries == null) return null;
      try {
        return hooks.sellSeries.series(itemId);
      } catch (Exception e) {
        return null;
      }
    }

    /**
     * supportForSuggestion(candidate, rankedAt): a CRASHING pick is demoted with the crash alert (outside the fail-open
     * try, as in the bridge), then a THIN one with its note (in its own try), then the sell-support reading judged against
     * {@code rankedAt} -- the minimum the chain RANKS at (the request's own, or the 500 floor of the step-down and the
     * positions after it). Any failure of the reading is no reading.
     */
    PickChain.SupportHook support(double rankedAt) {
      return cand -> {
        CrashWatch.Crash crashing = market.crashWatch == null ? null : market.crashWatch.isCrashing(cand.itemId);
        if (crashing != null) return SafetyChecks.precheck(cand, crashing, null, target);
        try {
          SellSupport.Result thin = SafetyChecks.precheck(cand, null, market.thin, target);
          if (thin != null) return thin;
        } catch (Exception e) {
          // thinMarketIndex()'s own catch: no note
        }
        try {
          // No series hook at all (the plugin): the archive IS the series, read as the bridge's merge reads it. A hook (the
          // parity tests replaying the bridge's recorded series) keeps the bridge's own gate exactly.
          SellSupport.Detail detail = hooks.sellSeries == null
            ? SellSupport.readingFromArchive(archivedSince(), cand.itemId, cand.buyPrice, now)
            : SellSupport.reading(seriesFor(cand.itemId), archivedSince(), cand.itemId, cand.buyPrice, now);
          return SellSupport.judge(detail, cand, rankedAt, minProfitChosen, requireMarginOverTax, level);
        } catch (Exception e) {
          return null;
        }
      };
    }

    /** worthOf's answer: the value compared, the quoted spread, and the supported figure (rounded; null for no reading). */
    static final class Worth {
      final double value;
      final double quoted;
      final Double supported;

      Worth(double value, double quoted, Double supported) {
        this.value = value;
        this.quoted = quoted;
        this.supported = supported;
      }
    }

    /**
     * worthOf: what a candidate is really worth, for comparing one tier against another -- the margin at the price buyers
     * have paid over the last 12 hours, or the quoted spread without a reading. Its gate is the bridge's own and NOT the
     * sell-support check's: only a MISSING series needs the archive to cover the window (an empty one is read, with the
     * archive merged in) -- the 7 Oct fix (7) changed supportForSuggestion only.
     */
    Worth worthOf(Pick c) {
      double qty = c.quantity != 0 ? c.quantity : 1;
      double quoted = (double) (c.sellPrice - Tax.estimateUnitTax(c.itemId, c.sellPrice) - c.buyPrice) * qty;
      try {
        List<HourBucket> archived = archivedSince();
        if (hooks.sellSeries == null) { // the plugin: the archive is the series (SellSupport.readingFromArchive)
          SellSupport.Detail d = SellSupport.readingFromArchive(archived, c.itemId, c.buyPrice, now);
          if (d != null && d.netAtAverage != null && JsValues.isFinite(d.netAtAverage))
            return new Worth(d.netAtAverage * qty, quoted, JsValues.jsRound(d.netAtAverage * qty));
          return new Worth(quoted, quoted, null);
        }
        List<SellSupport.Point> series = seriesFor(c.itemId);
        if (series == null && archived.size() < SellSupport.SELL_SUPPORT_HOURS) return new Worth(quoted, quoted, null);
        if (series != null) for (SellSupport.Point p : series) if (p == null) return new Worth(quoted, quoted, null); // JS throws: caught
        SellSupport.Detail detail = SellSupport.sellPriceSupport(SellSupport.mergeArchiveHours(series == null ? new ArrayList<>() : series, archived, c.itemId),
          c.itemId, c.buyPrice, now);
        if (detail != null && detail.netAtAverage != null && JsValues.isFinite(detail.netAtAverage))
          return new Worth(detail.netAtAverage * qty, quoted, JsValues.jsRound(detail.netAtAverage * qty));
      } catch (Exception e) {
        // the bridge's catch: the quoted spread
      }
      return new Worth(quoted, quoted, null);
    }

    // ---------------------------------------------------------------------------------------------- the reachable probe

    /**
     * Nothing passed a chosen floor: probe DOWN MinProfitTier's own rungs below it and report the first rung that yields a
     * trade -- through the same checks as the real path at THAT rung (sell support judged at the rung, forecast, cushion,
     * correlation; three attempts each; the market with the account's spread rank), reporting nothing to heldBack. Every
     * pass ranks on its OWN COPY of the request's blocklist (8 Oct fix 1): the shared one is what the Auto step-down ranks
     * on next, and a candidate demoted at one rung must still be judged at a lower one. The figure must clear the rung it
     * is advertised at, at the price buyers are paying. A statement of what exists, never a suggestion.
     */
    Reachable reachableProbe(boolean history) {
      for (double rung : REACHABLE_RUNGS) {
        if (!(rung < minProfit)) continue;
        List<Pick> candidates = new ArrayList<>();
        if (history) {
          try {
            Pick own = PickChain.pick(chain(historyRank(rung, maxSpend), support(rung), new LinkedHashSet<>(blocklist), rows -> { }, p -> { }));
            if (own != null) candidates.add(own);
          } catch (Exception e) {
            // the bridge's catch: no history candidate on this rung
          }
        }
        if (includeMarket) {
          try {
            Pick m = PickChain.pick(chain(bl -> ranking().rankAt(bl, maxSpend, rung), support(rung), new LinkedHashSet<>(blocklist), rows -> { }, p -> { }));
            if (m != null) candidates.add(m);
          } catch (Exception e) {
            // the bridge's catch: no market candidate on this rung
          }
        }
        Reachable best = null;
        for (Pick c : candidates) {
          Worth w = worthOf(c);
          Double profit = Policy.headlineProfitOf(JsValues.jsRound(w.quoted), w.supported == null ? Double.NaN : w.supported);
          if (profit != null && JsValues.isFinite(profit) && profit > 0 && profit >= rung && (best == null || profit > best.profit))
            best = new Reachable(c.name, c.itemId, profit, rung);
        }
        if (best != null) return best;
      }
      return null;
    }
  }

  // ========================================================================================== the query, as server.mjs reads it

  /** {@code Number(searchParams.get(k))}: an absent parameter is Number(null), which is 0. */
  static double number(String raw) {
    return raw == null ? 0 : JsValues.toNumber(raw);
  }

  /** {@code x || 0}. */
  static double orZero(double d) {
    return Double.isNaN(d) || d == 0 ? 0 : d;
  }

  /** {@code searchParams.get(k) || undefined}. */
  static String emptyAsNull(String s) {
    return s == null || s.isEmpty() ? null : s;
  }

  /**
   * JS {@code parseInt(s, 10)}: white space, a sign, then decimal digits, as the NUMBER they spell (2^32 + 561 stays
   * 4294967857, three hundred and ten digits are Infinity); nothing parseable is NaN.
   */
  static double parseInt(String s) {
    String t = JsValues.trim(s);
    int i = 0;
    boolean neg = false;
    if (i < t.length() && (t.charAt(i) == '+' || t.charAt(i) == '-')) neg = t.charAt(i++) == '-';
    int start = i;
    while (i < t.length() && t.charAt(i) >= '0' && t.charAt(i) <= '9') i++;
    if (i == start) return Double.NaN;
    double v = Double.parseDouble(t.substring(start, i));
    return neg ? -v : v;
  }

  /**
   * The item a parsed number can name: only a whole number in int range. JS keeps every other number in its Set as the
   * number it is, where it equals no item id -- so it is dropped here, never narrowed ((int) of 2^32 + 561 would WRAP onto
   * Nature rune; tier-query-ids-past-int-range pins this for every id a request carries).
   */
  static Integer itemIdOf(double v) {
    return JsValues.isInteger(v) && v >= Integer.MIN_VALUE && v <= Integer.MAX_VALUE ? (int) v : null;
  }

  /** {@code (raw || '').split(',').map(s => parseInt(s, 10)).filter(Number.isFinite)}, into an item-id set. */
  static void addItemIds(Set<Integer> into, String raw) {
    for (String s : (raw == null ? "" : raw).split(",", -1)) {
      double v = parseInt(s);
      if (!JsValues.isFinite(v)) continue;
      Integer id = itemIdOf(v);
      if (id != null) into.add(id);
    }
  }

  /** positionsWanted: 1 unless the player opted into more, clamped to {@link #MAX_POSITIONS}; anything unusable is 1. */
  static int positionsWanted(String raw) {
    double asked = number(raw);
    if (!JsValues.isFinite(asked)) return 1;
    return (int) Math.min(MAX_POSITIONS, Math.max(1, Math.floor(asked)));
  }

  /** A pick chain's held-back row as the bridge pushes it. */
  static HeldBack row(PickChain.Blocked b) {
    return b.pick != null ? new HeldBack(b.pick) : new HeldBack(b.itemId, b.reason);
  }
}

package com.evi.live.engine;

import com.evi.live.journal.FifoMatcher;
import com.evi.live.journal.Offer;
import com.evi.live.market.HourBucket;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A fill model learned from the player's OWN offers, rather than assumed (bridge/fillModel.mjs {@code bandFor},
 * {@code buildFillModel}, {@code fillChance}, {@code fillChanceSentence}, with fillCalibration.mjs's runtime pieces
 * {@code bucketAt} and {@code predictedFillMinutes}). Pure: the offers, the archived hours and the clock are handed in.
 *
 * <p>The volume estimate answers "how long should this take if volume were spread evenly"; this answers what a player
 * asks: "how often did an offer like this one actually finish in time?" Grouped by size relative to what the item trades
 * in an hour. Price aggression matters more, but EVI only ever suggests passive prices, so every sample is the kind of
 * offer it suggests.
 *
 * <p>HONEST BY CONSTRUCTION: the offers that did NOT fill are counted (filled / gave up / still open and censored), never
 * dropped -- an early version kept only completed offers and reported "100% filled" in every band. A band with fewer than
 * {@link #MIN_SAMPLES} usable offers reports NOTHING (null), never a confident number from four trades. A one-item price
 * probe ({@link FifoMatcher#isMarginCheck}) is skipped: it would teach that tiny orders fill in seconds.
 */
public final class FillModel {
  private FillModel() {}

  /** One band of order size as a share of the item's hourly volume (the thinner side). */
  public static final class Band {
    public final String label;
    public final double max;

    Band(String label, double max) {
      this.label = label;
      this.max = max;
    }
  }

  public static final List<Band> SHARE_BANDS = Collections.unmodifiableList(java.util.Arrays.asList(
    new Band("tiny (under 1% of an hour's volume)", 0.01),
    new Band("small (1-10%)", 0.10),
    new Band("moderate (10-50%)", 0.50),
    new Band("large (50-200%)", 2),
    new Band("huge (over 200%)", Double.POSITIVE_INFINITY)));
  public static final int MIN_SAMPLES = 15;
  static final double MINUTES_PER_HOUR = 60;

  /** bandFor: the first band whose ceiling the share is under; -1 for none (NaN, Infinity). */
  public static int bandFor(double share) {
    for (int i = 0; i < SHARE_BANDS.size(); i++) if (share < SHARE_BANDS.get(i).max) return i;
    return -1;
  }

  /** One observed offer: the minutes it was up and how it ended (filled, gave up, or still open when last seen). */
  public static final class Sample {
    public final double minutes;
    public final boolean filled;
    public final boolean gaveUp;
    public final boolean open;

    Sample(double minutes, boolean filled, boolean gaveUp, boolean open) {
      this.minutes = minutes;
      this.filled = filled;
      this.gaveUp = gaveUp;
      this.open = open;
    }
  }

  public static final class BandStats {
    public final String band;
    public final List<Sample> samples;
    public final int count;
    public final int filledCount;
    /** The upper-middle filled time, or null with none filled. */
    public final Double median;
    public final boolean enough;

    BandStats(String band, List<Sample> samples, int count, int filledCount, Double median, boolean enough) {
      this.band = band;
      this.samples = Collections.unmodifiableList(samples);
      this.count = count;
      this.filledCount = filledCount;
      this.median = median;
      this.enough = enough;
    }
  }

  public static final class Model {
    public final List<BandStats> bands;
    public final int skipped;

    Model(List<BandStats> bands, int skipped) {
      this.bands = Collections.unmodifiableList(bands);
      this.skipped = skipped;
    }
  }

  /** bucketAt: the archived hour covering {@code whenMs}, by binary search over buckets sorted ascending; null for none. */
  public static HourBucket bucketAt(List<HourBucket> buckets, double whenMs) {
    double ts = Math.floor(whenMs / 1000 / 3600) * 3600;
    int lo = 0, hi = buckets.size() - 1;
    while (lo <= hi) {
      int mid = (lo + hi) >> 1;
      HourBucket b = buckets.get(mid);
      if (b.ts == ts) return b;
      if (b.ts < ts) lo = mid + 1;
      else hi = mid - 1;
    }
    return null;
  }

  /** predictedFillMinutes: the even-volume prediction on the thinner side; null with no usable volume. */
  public static Double predictedFillMinutes(double quantity, VolumeRow entry) {
    if (!(quantity > 0) || entry == null) return null;
    double liquidity = VolumeRow.liquidity(entry);
    if (!(liquidity > 0)) return null;
    return quantity / (liquidity / MINUTES_PER_HOUR);
  }

  /**
   * buildFillModel: one entry per band. {@code offers} are the journal's offers watched from placement (the bridge passes
   * every offer with {@code knownStart} and a finite {@code firstSeen}); {@code buckets} the archived hours, oldest first.
   * The size is the quantity OFFERED, not what happened to fill -- that is what a suggestion has to predict.
   */
  public static Model build(Iterable<Offer> offers, List<HourBucket> buckets, double now) {
    List<List<Sample>> bands = new ArrayList<>();
    for (int i = 0; i < SHARE_BANDS.size(); i++) bands.add(new ArrayList<>());
    int skipped = 0;
    if (offers != null) for (Offer o : offers) {
      double offered = o.total > 0 ? o.total : o.filled;
      if (!(offered > 0) || o.firstSeen == null || FifoMatcher.isMarginCheck(o)) {
        skipped++;
        continue;
      }
      HourBucket hour = bucketAt(buckets, o.firstSeen);
      int row = hour == null ? -1 : hour.indexOf(o.itemId);
      if (row < 0) {
        skipped++;
        continue;
      }
      double liquidity = Math.min(hour.highVolume(row), hour.lowVolume(row));
      if (!(liquidity > 0)) {
        skipped++;
        continue;
      }
      int index = bandFor(offered / liquidity);
      if (index < 0) {
        skipped++;
        continue;
      }
      boolean cancelled = o.state != null && o.state.startsWith("CANCELLED");
      boolean completedFully = o.filled >= offered && o.completedAt != null && o.completedAt != 0;
      double endedAt = o.completedAt != null ? o.completedAt : o.updated != null ? o.updated : now;
      double minutes = Math.max(0, (endedAt - o.firstSeen) / 60000);
      if (completedFully) bands.get(index).add(new Sample(minutes, true, false, false));
      else if (cancelled) bands.get(index).add(new Sample(minutes, false, true, false));
      else bands.get(index).add(new Sample(minutes, false, false, true));
    }
    List<BandStats> out = new ArrayList<>();
    for (int i = 0; i < SHARE_BANDS.size(); i++) {
      List<Sample> samples = bands.get(i);
      List<Double> filledTimes = new ArrayList<>();
      for (Sample s : samples) if (s.filled) filledTimes.add(s.minutes);
      filledTimes.sort(Double::compare);
      Double median = filledTimes.isEmpty() ? null : filledTimes.get(filledTimes.size() / 2);
      out.add(new BandStats(SHARE_BANDS.get(i).label, samples, samples.size(), filledTimes.size(), median, samples.size() >= MIN_SAMPLES));
    }
    return new Model(out, skipped);
  }

  /** How often an offer of this size actually finished within the window, from the player's own record. */
  public static final class Chance {
    public final double probability;
    public final int samples;
    public final Double medianMinutes;
    public final String band;

    Chance(double probability, int samples, Double medianMinutes, String band) {
      this.probability = probability;
      this.samples = samples;
      this.medianMinutes = medianMinutes;
      this.band = band;
    }
  }

  /**
   * fillChance: null -- never a guess -- when the band is too thin or the inputs are unusable. An offer still running when
   * last seen says nothing about a window longer than it was up for, so it is left out of that window's denominator.
   */
  public static Chance fillChance(Model model, double quantity, VolumeRow volumeEntry, double withinMinutes) {
    if (model == null || !(quantity > 0) || !(withinMinutes > 0) || volumeEntry == null) return null;
    double liquidity = VolumeRow.liquidity(volumeEntry);
    if (!(liquidity > 0)) return null;
    int i = bandFor(quantity / liquidity);
    BandStats band = i < 0 || i >= model.bands.size() ? null : model.bands.get(i);
    if (band == null || !band.enough) return null;
    int usable = 0, succeeded = 0;
    for (Sample s : band.samples) {
      if (!(s.filled || s.gaveUp || s.minutes >= withinMinutes)) continue;
      usable++;
      if (s.filled && s.minutes <= withinMinutes) succeeded++;
    }
    if (usable < MIN_SAMPLES) return null;
    return new Chance((double) succeeded / usable, usable, band.median, band.band);
  }

  /**
   * fillChanceSentence: one plain sentence for a suggestion's reasoning, naming how many of the player's own offers it rests
   * on so a thin-but-usable band reads as the weak evidence it is; null with nothing trustworthy to say.
   */
  public static String fillChanceSentence(Chance chance, double withinMinutes) {
    if (chance == null) return null;
    double hours = withinMinutes / 60;
    String window = hours >= 1
      ? (hours % 1 == 0 ? JsValues.text(hours) : JsValues.toFixed(hours, 1)) + " hour" + (hours == 1 ? "" : "s")
      : JsValues.text(JsValues.jsRound(withinMinutes)) + " minutes";
    // No typical time when NONE of the offers filled (the maintainer, 7 Oct 2026, fixed in JS first): the band's median is
    // then null, which used to print "typically 0 minutes" beside "0% finished".
    Double median = chance.medianMinutes;
    String typical = median == null || !JsValues.isFinite(median) ? ""
      : ", typically " + (median < 90 ? JsValues.text(JsValues.jsRound(median)) + " minutes" : JsValues.toFixed(median / 60, 1) + " hours");
    return "Of your own past offers this size relative to the item's trading, " + JsValues.text(JsValues.jsRound(chance.probability * 100)) + "% finished within "
      + window + " (" + chance.samples + " offers" + typical + "). That is your own record, not a forecast.";
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Offer;
import com.evi.live.market.HourBucket;
import java.util.Collection;
import java.util.List;

/**
 * The player fill model as server.mjs's {@code playerFillModel} keeps it: rebuilt AT MOST HOURLY, from every journal offer
 * watched from placement (ANY account's -- the maintainer, 7 Oct: the fill model is the one deliberate exception to account scoping,
 * a timing estimate learned from more history), over the archived hours those offers fall in. Never fatal: a failed build
 * gives "no model" and the suggestion simply carries no fill sentence. A failure is NOT kept: the next buy poll tries again,
 * exactly as server.mjs does (EngineDecideIntentTest.fillModelHour pins it). The retry waits on the engine thread only.
 *
 * <p>The cache is part of the behaviour, not an optimisation: a model built at one poll answers every poll for the next hour
 * even after new offers finish, exactly as the bridge's does. {@link Engine#decide} asks for it LAZILY, only for a BUY pick,
 * at the point the bridge does, so the hour starts when the bridge's would. Owned by the engine thread; not thread-safe.
 */
public final class FillModelCache implements Engine.FillModelSource {
  /** {@code (from) -> readArchive(dir, from)}: the archived hours from {@code from} (seconds) onward, oldest first. */
  public interface ArchiveFrom {
    List<HourBucket> load(long fromTs) throws Exception;
  }

  private final ArchiveFrom archive;
  private FillModel.Model model;
  private long at;

  public FillModelCache(ArchiveFrom archive) {
    this.archive = archive;
  }

  @Override public FillModel.Model model(Collection<Offer> allAccountsJournalOffers, long now) {
    if (model != null && now - at < 3600000) return model;
    try {
      List<Offer> watched = SafetyChecks.watchedOffers(allAccountsJournalOffers);
      if (watched.isEmpty()) return null;
      long from = (long) SafetyChecks.fillModelFrom(watched);
      FillModel.Model built = FillModel.build(watched, archive.load(from), now);
      model = built;
      at = now;
      return built;
    } catch (Exception e) {
      model = null;
      at = now;
      return null;
    }
  }
}

package com.evi.live.engine;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * The player's trading focus by the item's own buy limit (bridge/suggestions.mjs FOCUSES, resolveFocus, focusAllows):
 * "bulk" is an item bought by the thousand, "gear" one with a known smaller limit, "any" everything. Game data, not a
 * price or profit threshold. Pure.
 */
public final class Focus {
  private Focus() {}

  /** BULK_MIN_LIMIT. */
  public static final double BULK_MIN_LIMIT = 1000;
  /** FOCUSES, in the JS order. */
  public static final List<String> FOCUSES = Collections.unmodifiableList(Arrays.asList("any", "bulk", "gear"));

  /** The plugin's own setting when it names a focus, otherwise the scanner's stored switch, otherwise "any". */
  public static String resolveFocus(String requested, String stored) {
    if (requested != null && FOCUSES.contains(requested)) return requested;
    return stored != null && FOCUSES.contains(stored) ? stored : "any";
  }

  /**
   * Whether an item with this buy limit fits the focus. An item whose limit is unknown ({@code limit} null or not
   * finite) cannot be placed in either group, so only "any" includes it.
   */
  public static boolean focusAllows(String focus, Double limit) {
    boolean known = limit != null && JsValues.isFinite(limit);
    if ("bulk".equals(focus)) return known && limit >= BULK_MIN_LIMIT;
    if ("gear".equals(focus)) return known && limit > 0 && limit < BULK_MIN_LIMIT;
    return true;
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Js;
import com.evi.live.market.HourBucket;
import com.google.gson.JsonObject;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The opt-in price-pattern reading behind the "Exit risk" sentence (bridge/suggestions.mjs {@code forecastFromSeries},
 * bridge/fillOutlook.mjs {@code fillOutlook} / {@code fillOutlookSentence}), ported 8 Oct 2026 for the ~6 HOURS setting only.
 * Pure: the series is handed in, nothing is fetched.
 *
 * <p>WHAT IS SHOWN, AND WHY ONLY FOR SIX HOURS. The forecast's direction is measured to be wrong more often than chance, so it
 * is never shown; what the same label does separate is which side of a flip completes, and that table
 * ({@link #FILL_OUTLOOK_MEASURED}) was measured for the six-hour setting alone (65,006 offer pairs). The bridge reads the Wiki's
 * per-item HOURLY series for it; the plugin reads its own hourly archive, whose hours are the Wiki series' own (identical on
 * every one of 336 overlapping hours, and so are the forecasts -- the maintainer's investigation, 8 Oct). The ~1 hour and
 * Overnight settings read the Wiki's 5-minute and 6-hourly series, which the plugin does not keep, and have no measured table:
 * they are RETIRED in the plugin (no forecast at all; the bridge keeps them).
 *
 * <p>JS NUMBERS: every step is the JS arithmetic in the JS order; {@code Math.log} is {@link StrictMath#log} (fdlibm, which V8's
 * is a port of), {@code Math.round} is {@link JsValues#jsRound}. Proven against the JS by recorded vectors (ForecastVectorsTest).
 */
public final class Forecasts {
  private Forecasts() {}

  /** The one horizon the plugin forecasts for (the measured table's). */
  public static final String SIX_HOURS = "6h";
  /** How many of the newest usable points the six-hour reading looks at: the last n=18, and the n before them. */
  public static final int SIX_HOUR_POINTS = 36;

  /** A forecastFromSeries answer. {@code shortSeries}: under 8 usable points, the bare "Uncertain" answer. */
  public static final class Reading {
    public final String label;
    public final double dir, confidence, move, volatility, deviation, imbalance, noise, threshold;
    public final boolean shortSeries;

    Reading(String label, double dir, double confidence, double move, double volatility, double deviation, double imbalance, double noise,
            double threshold, boolean shortSeries) {
      this.label = label;
      this.dir = dir;
      this.confidence = confidence;
      this.move = move;
      this.volatility = volatility;
      this.deviation = deviation;
      this.imbalance = imbalance;
      this.noise = noise;
      this.threshold = threshold;
      this.shortSeries = shortSeries;
    }

    /** The object the bridge attaches as {@code candidate.forecast}, in its key order. */
    public JsonObject json() {
      JsonObject o = new JsonObject();
      o.addProperty("label", label);
      o.addProperty("dir", dir);
      o.addProperty("confidence", confidence);
      o.addProperty("move", move);
      if (shortSeries) return o;
      o.addProperty("volatility", volatility);
      o.addProperty("deviation", deviation);
      o.addProperty("imbalance", imbalance);
      o.addProperty("noise", noise);
      o.addProperty("threshold", threshold);
      return o;
    }
  }

  /** midpointPoint: the mid of both sides when both are positive, else whichever is, else none (null). */
  static Double midpoint(SellSupport.Point x) {
    double hi = num(x.avgHighPrice), lo = num(x.avgLowPrice);
    if (JsValues.isFinite(hi) && hi > 0 && JsValues.isFinite(lo) && lo > 0) return (hi + lo) / 2;
    if (JsValues.isFinite(hi) && hi > 0) return hi;
    if (JsValues.isFinite(lo) && lo > 0) return lo;
    return null;
  }

  /** {@code Number(v)}: a null field is Number(null), 0. */
  private static double num(Double v) {
    return v == null ? 0 : v;
  }

  static double linSlope(List<Double> vals) {
    List<Double> a = new ArrayList<>();
    for (Double v : vals) if (v != null && JsValues.isFinite(v)) a.add(v);
    if (a.size() < 3) return 0;
    int n = a.size();
    double mx = (n - 1) / 2.0, sum = 0;
    for (double v : a) sum += v;
    double my = sum / n, num = 0, den = 0;
    for (int i = 0; i < n; i++) {
      num += (i - mx) * (a.get(i) - my);
      den += (i - mx) * (i - mx);
    }
    return den != 0 ? num / den : 0;
  }

  static double ret(double a, double b) {
    return JsValues.isFinite(a) && a > 0 && JsValues.isFinite(b) ? b / a - 1 : 0;
  }

  static double volOf(List<Double> vals) {
    List<Double> rs = new ArrayList<>();
    for (int i = 1; i < vals.size(); i++) if (vals.get(i - 1) > 0 && vals.get(i) > 0) rs.add(StrictMath.log(vals.get(i) / vals.get(i - 1)));
    if (rs.size() < 2) return 0;
    double s = 0;
    for (double r : rs) s += r;
    double m = s / rs.size(), sq = 0;
    for (double r : rs) sq += (r - m) * (r - m);
    return Math.sqrt(sq / (rs.size() - 1));
  }

  /** {@code arr.slice(start, end)} with JS's negative-index rules. */
  private static <T> List<T> slice(List<T> arr, int start, int end) {
    int len = arr.size();
    int s = start < 0 ? Math.max(len + start, 0) : Math.min(start, len);
    int e = end < 0 ? Math.max(len + end, 0) : Math.min(end, len);
    return e <= s ? new ArrayList<>() : new ArrayList<>(arr.subList(s, e));
  }

  private static double clamp(double x, double a, double b) {
    return Math.max(a, Math.min(b, x));
  }

  /** {@code x.highPriceVolume || 0}: null, NaN and 0 are 0. */
  private static double orZero(Double v) {
    return v == null || Double.isNaN(v) ? 0 : v;
  }

  /**
   * forecastFromSeries(series, horizon). {@code series}: hourly points for the 6h horizon (any order; points with no usable
   * price are dropped). Under 8 usable points: the bare "Uncertain" answer. Never throws on a well-formed list.
   */
  public static Reading forecastFromSeries(List<SellSupport.Point> series, String horizon) {
    List<SellSupport.Point> clean = new ArrayList<>();
    if (series != null) for (SellSupport.Point p : series) if (p != null && midpoint(p) != null) clean.add(p);
    clean.sort((a, b) -> Js.compare(a.timestamp, b.timestamp)); // stable, as Array.prototype.sort is
    if (clean.size() < 8) return new Reading("Uncertain", 0, 20, 0, 0, 0, 0, 0, 0, true);
    List<Double> mids = new ArrayList<>();
    for (SellSupport.Point p : clean) mids.add(midpoint(p));
    double last = mids.get(mids.size() - 1);
    int n = "1h".equals(horizon) ? 12 : "6h".equals(horizon) ? 18 : 28;
    List<Double> recent = slice(mids, -n, mids.size()), prev = slice(mids, -Math.min(mids.size(), n * 2), -n);
    double slope = linSlope(recent) / (last != 0 && !Double.isNaN(last) ? last : 1);
    double momentum = ret(recent.get(0), recent.get(recent.size() - 1));
    double longer = prev.size() >= 3 ? ret(prev.get(0), prev.get(prev.size() - 1)) : momentum;
    double volatility = volOf(recent);
    double buyVol = 0, sellVol = 0;
    for (SellSupport.Point x : slice(clean, -n, clean.size())) buyVol = buyVol + orZero(x.highPriceVolume);
    for (SellSupport.Point x : slice(clean, -n, clean.size())) sellVol = sellVol + orZero(x.lowPriceVolume);
    double imbalance = (buyVol - sellVol) / Math.max(1, buyVol + sellVol);
    double sum = 0;
    for (double v : recent) sum = sum + v;
    double mean = sum / recent.size();
    double deviation = (last - mean) / Math.max(1, mean);
    double signal = 0.45 * momentum + 4.0 * slope + 0.012 * imbalance + 0.12 * longer;
    if (Math.abs(deviation) > .025) signal += -0.08 * deviation;
    double noise = Math.max(.002, volatility * Math.sqrt(Math.max(1, recent.size() / 4.0)));
    double strength = Math.abs(signal) / noise;
    double confidence = JsValues.jsRound(clamp(42 + strength * 22, 42, 88));
    if (clean.size() < 20) confidence = Math.min(confidence, 60);
    double threshold = Math.max(.0025, noise * .35);
    String label = "Stable";
    double dir = 0;
    if (signal > threshold) {
      label = "Likely rising";
      dir = 1;
    } else if (signal < -threshold) {
      label = "Likely falling";
      dir = -1;
    } else if (momentum < -.02 && deviation < -.015 && signal >= -threshold) {
      label = "Possible rebound";
      dir = 0.5;
    }
    return new Reading(label, dir, confidence, signal, volatility, deviation, imbalance, noise, threshold, false);
  }

  // ------------------------------------------------------------------------------------------- the fill outlook

  /** One row of the measured table. */
  static final class Rate {
    final double buy, sell;
    final int samples;

    Rate(double buy, double sell, int samples) {
      this.buy = buy;
      this.sell = sell;
      this.samples = samples;
    }
  }

  /** FILL_OUTLOOK_MEASURED (fillOutlook.mjs, measured 2026-09-18): the six-hour setting only. */
  public static final String MEASURED_HORIZON = "6h";
  static final int HORIZON_HOURS = 6;
  static final Rate BASELINE = new Rate(0.850, 0.833, 65006);
  static final Map<String, Rate> FILL_OUTLOOK_MEASURED;

  static {
    Map<String, Rate> m = new HashMap<>();
    m.put("Likely rising", new Rate(0.912, 0.744, 15137));
    m.put("Likely falling", new Rate(0.775, 0.878, 22977));
    m.put("Stable", new Rate(0.887, 0.837, 24948));
    m.put("Possible rebound", new Rate(0.768, 0.949, 1944));
    FILL_OUTLOOK_MEASURED = Collections.unmodifiableMap(m);
  }

  public static final double MIN_INTERESTING_GAP = 0.05;
  public static final int MIN_LABEL_SAMPLES = 1000;

  /** fillOutlook's answer. */
  public static final class Outlook {
    public final double buy, sell, buyGap, sellGap;
    public final String worst;
    public final int samples;
    public final boolean notable;

    Outlook(double buy, double sell, double buyGap, double sellGap, String worst, int samples, boolean notable) {
      this.buy = buy;
      this.sell = sell;
      this.buyGap = buyGap;
      this.sellGap = sellGap;
      this.worst = worst;
      this.samples = samples;
      this.notable = notable;
    }

    /** The object the bridge attaches as {@code candidate.fillOutlook}, in its key order. */
    public JsonObject json() {
      JsonObject o = new JsonObject();
      o.addProperty("buy", buy);
      o.addProperty("sell", sell);
      o.addProperty("buyGap", buyGap);
      o.addProperty("sellGap", sellGap);
      o.addProperty("worst", worst);
      JsonObject base = new JsonObject();
      base.addProperty("buy", BASELINE.buy);
      base.addProperty("sell", BASELINE.sell);
      o.add("baseline", base);
      o.addProperty("samples", samples);
      o.addProperty("horizonHours", HORIZON_HOURS);
      o.addProperty("notable", notable);
      return o;
    }
  }

  /** fillOutlook(forecast, FILL_OUTLOOK_MEASURED, horizon): null for any other horizon, an unmeasured label, or too few samples. */
  public static Outlook fillOutlook(Reading forecast, String horizon) {
    if (forecast == null) return null;
    if (!MEASURED_HORIZON.equals(horizon)) return null;
    Rate entry = FILL_OUTLOOK_MEASURED.get(forecast.label);
    if (entry == null || !(entry.samples >= MIN_LABEL_SAMPLES)) return null;
    double buyGap = entry.buy - BASELINE.buy, sellGap = entry.sell - BASELINE.sell;
    String worst = Math.abs(sellGap) >= Math.abs(buyGap) ? "sell" : "buy";
    return new Outlook(entry.buy, entry.sell, buyGap, sellGap, worst, entry.samples, Math.max(Math.abs(buyGap), Math.abs(sellGap)) >= MIN_INTERESTING_GAP);
  }

  private static String pct(double v) {
    return Js.numberToString(JsValues.jsRound(v * 100));
  }

  /** fillOutlookSentence: one plain sentence, or null when nothing is worth saying. Never names the direction. */
  public static String fillOutlookSentence(Outlook o) {
    if (o == null || !o.notable) return null;
    String hours = String.valueOf(HORIZON_HOURS), samples = JsValues.localeUs(o.samples);
    if ("sell".equals(o.worst) && o.sellGap < 0)
      return "Exit risk: items whose recent price pattern looks like this sold within " + hours + " hours only " + pct(o.sell) + "% of the time (against "
        + pct(o.buy) + "% for the buy side), across " + samples + " past offers in your price archive. The risk here is being left holding it rather than"
        + " missing the buy -- consider a smaller quantity or a keener sell price.";
    if ("sell".equals(o.worst) && o.sellGap > 0)
      return "Exit outlook: items with this recent price pattern sold within " + hours + " hours " + pct(o.sell) + "% of the time, above the "
        + pct(BASELINE.sell) + "% norm, though the buy side filled less often (" + pct(o.buy) + "%). Getting in is the harder half here. Based on "
        + samples + " past offers, not a guarantee.";
    if (o.buyGap < 0)
      return "Entry risk: items with this recent price pattern had their buy offer fill within " + hours + " hours only " + pct(o.buy)
        + "% of the time, across " + samples + " past offers in your price archive. You may simply not get the stock at this price.";
    return "Fill outlook: items with this recent price pattern filled the buy " + pct(o.buy) + "% and the sell " + pct(o.sell) + "% of the time within "
      + hours + " hours, across " + samples + " past offers. Rates from your own archive, not a forecast of price.";
  }

  /** What the forecast hook hands the pick chain for one item: the reading, its outlook and sentence. */
  public static PickChain.Forecast forHook(Reading r, String horizon) {
    if (r == null) return null;
    Outlook o = fillOutlook(r, horizon);
    return new PickChain.Forecast(r.json(), r.dir == -1 ? -1 : r.dir == 1 ? 1 : 0, r.confidence, fillOutlookSentence(o), o == null ? null : o.json());
  }

  // ------------------------------------------------------------------------------------------- the series, from the archive

  /**
   * Every item's newest {@link #SIX_HOUR_POINTS} usable hourly points, from the plugin's archive -- the same points the Wiki's
   * per-item series carries for those hours. Only the newest 36 usable points (and whether there are fewer than 8 or 20) can
   * change a six-hour reading, so nothing older is kept. Built once per archive state; immutable.
   *
   * <p>Expected difference from the bridge, documented: the Wiki series reaches 365 hours back, the archive 337; an item with
   * fewer than 36 usable hours in the archive's window but more in the Wiki's reads a shorter series (only very thin items).
   */
  public static final class Index {
    private final Map<Integer, List<SellSupport.Point>> byItem;
    public final long newestTs;
    public final int hours;

    private Index(Map<Integer, List<SellSupport.Point>> byItem, long newestTs, int hours) {
      this.byItem = byItem;
      this.newestTs = newestTs;
      this.hours = hours;
    }

    /** From archived hours (any order), using only hours up to and including {@code newestTs}. */
    public static Index build(List<HourBucket> archived, long newestTs) {
      List<HourBucket> hours = new ArrayList<>();
      if (archived != null) for (HourBucket b : archived) if (b != null && b.ts <= newestTs) hours.add(b);
      hours.sort((a, b) -> Long.compare(a.ts, b.ts));
      Map<Integer, ArrayDeque<SellSupport.Point>> keep = new HashMap<>();
      for (HourBucket b : hours) {
        for (int i = 0; i < b.size(); i++) {
          SellSupport.Point p = new SellSupport.Point(b.ts, side(b.avgHigh(i)), (double) b.highVolume(i), side(b.avgLow(i)), (double) b.lowVolume(i));
          if (midpoint(p) == null) continue;
          ArrayDeque<SellSupport.Point> q = keep.computeIfAbsent(b.id(i), k -> new ArrayDeque<>());
          q.addLast(p);
          if (q.size() > SIX_HOUR_POINTS) q.removeFirst();
        }
      }
      Map<Integer, List<SellSupport.Point>> out = new HashMap<>();
      for (Map.Entry<Integer, ArrayDeque<SellSupport.Point>> e : keep.entrySet()) out.put(e.getKey(), Collections.unmodifiableList(new ArrayList<>(e.getValue())));
      return new Index(out, newestTs, hours.size());
    }

    /** The item's points, oldest first (empty: none -- the Wiki's series would hold only empty hours: "Uncertain"). */
    public List<SellSupport.Point> series(int itemId) {
      List<SellSupport.Point> s = byItem.get(itemId);
      return s == null ? Collections.emptyList() : s;
    }
  }

  private static Double side(long v) {
    return v == HourBucket.NONE ? null : (double) v;
  }
}

package com.evi.live.engine;

import com.evi.live.market.HourBucket;
import java.util.Set;

/**
 * The checks that decide whether a candidate may be offered at all, ported from bridge/suggestions.mjs. Pure.
 *
 * <p>EVERY ONE FAILS OPEN. A missing or non-finite input never blocks a candidate: "we could not tell" must never
 * read as "we found a problem" (the standing rule). Each answers exactly as the JS does on NaN, infinities and
 * absent values, which is what EngineVectorsTest replays.
 *
 * <p>The bars the risk redesign may move (the margin multiples, the hourly floor) come from {@link LevelSettings};
 * the multiples here are only the JS functions' own parameter defaults.
 */
public final class Gates {
  private Gates() {}

  /** marginClearsTax's default bar, MARGIN_TAX_MULTIPLE (the tier with a track record). */
  public static final double MARGIN_TAX_MULTIPLE = 0.5;
  /** MARGIN_TAX_NO_HISTORY_MULTIPLE: the market-wide and scanner tiers. */
  public static final double MARGIN_TAX_NO_HISTORY_MULTIPLE = 1;
  /** MARGIN_TAX_WARN_MULTIPLE: below it a personal pick carries a warning. */
  public static final double MARGIN_TAX_WARN_MULTIPLE = 1;
  /** IMPLAUSIBLE_MARGIN_MULTIPLE: a margin over five times the buy price, on an hour nobody traded, is a dead spread. */
  public static final double IMPLAUSIBLE_MARGIN_MULTIPLE = 5;
  /** BUY_PRINT_MULTIPLE: a buy print under half its own hour's average sell is a print, not a price. */
  public static final double BUY_PRINT_MULTIPLE = 0.5;

  /** UNFLIPPABLE_ITEM_IDS: 13190, the Old school bond, which arrives untradeable. Never bought by any tier. */
  public static final Set<Integer> UNFLIPPABLE_ITEM_IDS = Set.of(13190);

  public static boolean isUnflippable(int itemId) {
    return UNFLIPPABLE_ITEM_IDS.contains(itemId);
  }

  /**
   * marginClearsTax: does the per-unit margin after tax cover {@code multiple} times the item's own tax? Unknown or
   * non-finite inputs never block, and neither does a tax-free item.
   */
  public static boolean marginClearsTax(double net, double tax, double multiple) {
    if (!JsValues.isFinite(net) || !JsValues.isFinite(tax)) return true;
    if (!(tax > 0)) return true;
    return net >= tax * multiple;
  }

  /**
   * implausibleSpread: a margin both extreme ({@code net / buyPrice > multiple}) and on an item that did not trade this
   * hour. {@code hourVolume} is NaN when the item is absent from the hour, which here counts as "did not trade" (the
   * one place absence is read that way, because the Wiki omits an item that changed no hands).
   */
  public static boolean implausibleSpread(double net, double buyPrice, double hourVolume, double multiple) {
    if (!JsValues.isFinite(net) || !JsValues.isFinite(buyPrice) || buyPrice <= 0 || net <= 0) return false;
    if (hourVolume > 0) return false; // someone is trading it
    return net / buyPrice > multiple;
  }

  /**
   * implausibleBuyPrint: a buy price under {@code multiple} times its own hour's average sell price, on an hour where
   * sells happened. False whenever there is nothing to judge against. {@code avgLowPrice}/{@code lowVolume} take NaN
   * when absent.
   */
  public static boolean implausibleBuyPrint(double low, double avgLowPrice, double lowVolume, double multiple) {
    if (!JsValues.isFinite(low) || low <= 0) return false;
    if (!(avgLowPrice > 0) || !(lowVolume > 0)) return false;
    return low < avgLowPrice * multiple;
  }

  /** The same, against the item's row of the latest hour (null when the item is absent from it). */
  public static boolean implausibleBuyPrint(double low, VolumeRow row, double multiple) {
    if (row == null) return implausibleBuyPrint(low, Double.NaN, Double.NaN, multiple);
    return implausibleBuyPrint(low, row.avgLow == HourBucket.NONE ? Double.NaN : row.avgLow, row.lowVolume, multiple);
  }

  /**
   * The market tier's liquidity floor ({@code liquidityFloorMet} in computeMarketSuggestion): the per-WINDOW floor when
   * {@code minVolumeInWindow} is a finite value above 0 ("Bigger positions"), otherwise the hourly floor -- the
   * level's minimum, raised by {@code minHourlyVolume} when that is set ({@code options.minHourlyVolume || 0}).
   *
   * @param liquidity the latest hour's thinner side (0 when the item is absent)
   * @param targetDurationMinutes the normalised pace, null for none (a window of one hour)
   * @param minVolumeInWindow NaN when unset
   * @param minHourlyVolume NaN when unset
   */
  public static boolean liquidityFloorMet(double liquidity, Double targetDurationMinutes, double minVolumeInWindow, double minHourlyVolume,
                                          LevelSettings level) {
    double windowHours = targetDurationMinutes != null ? targetDurationMinutes / 60 : 1;
    if (JsValues.isFinite(minVolumeInWindow) && minVolumeInWindow > 0) return liquidity * windowHours >= minVolumeInWindow;
    double raised = Double.isNaN(minHourlyVolume) || minHourlyVolume == 0 ? 0 : minHourlyVolume; // (x || 0)
    return liquidity >= Math.max(level.minHourlyVolume, raised);
  }
}

package com.evi.live.engine;

import com.evi.live.journal.FifoMatcher;
import com.evi.live.journal.Offer;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * The eight Grand Exchange slots (bridge/suggestions.mjs slotCapacity, slotExposure, slotNote). Pure.
 *
 * <p>THE PORT WARNING, honoured: the JS {@code slotExposure} scopes with {@code !account || x.account === account}, so
 * called with no account it counts EVERY account's positions and offers, and it is safe only because server.mjs
 * filters both lists with {@code ownedBy} first (6 Oct: a pure account's restock showed up as the main's holding).
 * This port scopes ITSELF with the server's rule: no account (null or empty) owns nothing. EngineVectorsTest compares
 * it with the JS answer on the lists server.mjs would actually pass.
 */
public final class GeSlots {
  private GeSlots() {}

  /** GE_SLOTS. */
  public static final int GE_SLOTS = 8;

  /** slotCapacity's answer. {@code free}/{@code collectable} are null when the plugin sent no usable count. */
  public static final class Capacity {
    public final Integer free;
    public final Integer collectable;
    /** Every slot occupied and none holds a finished offer: nothing can be placed. */
    public final boolean full;
    /** Every slot occupied, but collecting one is a click away: ranking continues with a note. */
    public final boolean tight;

    public Capacity(Integer free, Integer collectable, boolean full, boolean tight) {
      this.free = free;
      this.collectable = collectable;
      this.full = full;
      this.tight = tight;
    }
  }

  /** A raw query value as a slot count: a whole number from 0 to 8 as {@code Number()} reads it, else null. */
  static Integer count(String raw) {
    if (raw == null || raw.isEmpty()) return null;
    double n = JsValues.toNumber(raw);
    return JsValues.isInteger(n) && n >= 0 && n <= GE_SLOTS ? Integer.valueOf((int) n) : null;
  }

  /** slotCapacity, from the two raw counts the plugin sends (null when absent). Unknown never invents a constraint. */
  public static Capacity slotCapacity(String freeRaw, String collectableRaw) {
    Integer free = count(freeRaw), collectable = count(collectableRaw);
    boolean freeZero = free != null && free == 0;
    boolean full = freeZero && collectable != null && collectable == 0;
    return new Capacity(free, collectable, full, freeZero && !full);
  }

  /** One sentence for a tight GE, or null when there is nothing to say. */
  public static String slotNote(Capacity capacity) {
    if (capacity == null || !capacity.tight) return null;
    Integer n = capacity.collectable;
    return n != null && n > 0
      ? "All " + GE_SLOTS + " GE slots are in use, but " + n + " finished offer" + (n == 1 ? "" : "s") + " can be collected to free one."
      : "All " + GE_SLOTS + " GE slots are in use -- you will need to collect or cancel an offer before placing this.";
  }

  /** slotExposure's answer. */
  public static final class Exposure {
    /** Every item the account is committed to, held or being bought, in the JS Set's insertion order. */
    public final Set<Integer> exposure;
    /** Held stock with no slot of its own, in first-seen order. */
    public final List<Integer> owedItems;
    public final int sellSlotsOwed;

    Exposure(Set<Integer> exposure, List<Integer> owedItems) {
      this.exposure = Collections.unmodifiableSet(exposure);
      this.owedItems = Collections.unmodifiableList(owedItems);
      this.sellSlotsOwed = owedItems.size();
    }
  }

  /** server.mjs's {@code ownedBy}: a real account, and this record is that account's. */
  static boolean ownedBy(String account, String recordAccount) {
    return account != null && !account.isEmpty() && account.equals(recordAccount);
  }

  /**
   * slotExposure for ONE account: what it is committed to (open positions and offers buying), and how many sells
   * need a slot they do not already have -- stock held with no offer in any slot. A buy vacates its own slot when
   * collected and the sell goes straight into it, so anything in a slot brings its own slot with it.
   *
   * <p>PACKAGE-PRIVATE: the kernel the JS vectors call with the lists the bridge passes. Production reads it through
   * {@link AccountView#slotExposure}, which can only hand it one account's own lots and slots.
   */
  static Exposure slotExposure(List<FifoMatcher.OpenPosition> openPositions, List<Offer> occupiedOffers, String account) {
    List<Integer> held = new ArrayList<>();
    if (openPositions != null) for (FifoMatcher.OpenPosition p : openPositions) if (p != null && ownedBy(account, p.account)) held.add(p.itemId);
    Set<Integer> inASlot = new HashSet<>();
    List<Integer> buying = new ArrayList<>();
    if (occupiedOffers != null) for (Offer o : occupiedOffers) {
      if (o == null || !ownedBy(account, o.account)) continue;
      inASlot.add(o.itemId);
      if ("BUYING".equals(o.state) || "BOUGHT".equals(o.state)) buying.add(o.itemId);
    }
    List<Integer> owed = new ArrayList<>();
    for (Integer id : new LinkedHashSet<>(held)) if (!inASlot.contains(id)) owed.add(id);
    Set<Integer> exposure = new LinkedHashSet<>(held);
    exposure.addAll(buying);
    return new Exposure(exposure, owed);
  }
}

package com.evi.live.engine;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * A player's own reviewed flips, aggregated per item (bridge/suggestions.mjs {@code personalHistory}), and the risk
 * level's eligibility bar for the personal-history tier. Pure. Every input came from this account's own confirmed
 * trades, never a shared pool. (Which flips are passed in is the caller's choice; today the bridge passes every
 * account's, deliberately -- CLAUDE.md "Known and deliberate: EVI is only partly per-account".)
 */
public final class History {
  private History() {}

  /**
   * One flip as personalHistory reads it. Numbers are NaN when absent or not a number; {@code lastSell} and
   * {@code confirmedAt} are null when absent or null (the JS reads them with {@code ??}, where a NaN still counts).
   */
  public static final class Flip {
    public final boolean removed;
    public final double itemId;
    public final double profit;
    public final double quantity;
    public final double hold;
    public final Double lastSell;
    public final Double confirmedAt;
    public final String item;

    public Flip(boolean removed, double itemId, double profit, double quantity, double hold, Double lastSell, Double confirmedAt, String item) {
      this.removed = removed;
      this.itemId = itemId;
      this.profit = profit;
      this.quantity = quantity;
      this.hold = hold;
      this.lastSell = lastSell;
      this.confirmedAt = confirmedAt;
      this.item = item;
    }
  }

  /** One item's track record. */
  public static final class ItemHistory {
    public final double itemId;
    /** The most recent non-empty name, or the first flip's (possibly null). */
    public final String name;
    public final int trades;
    public final double winRate;
    public final double avgProfit;
    /** {@link Medians#average} of the quantities: can be x.5. */
    public final Double medianQty;
    public final Double medianHoldH;
    public final double lastTradeAt;

    ItemHistory(double itemId, String name, int trades, double winRate, double avgProfit, Double medianQty, Double medianHoldH, double lastTradeAt) {
      this.itemId = itemId;
      this.name = name;
      this.trades = trades;
      this.winRate = winRate;
      this.avgProfit = avgProfit;
      this.medianQty = medianQty;
      this.medianHoldH = medianHoldH;
      this.lastTradeAt = lastTradeAt;
    }
  }

  private static final class Acc {
    final double itemId;
    String name;
    int trades;
    int wins;
    double totalProfit;
    final List<Double> quantities = new ArrayList<>();
    final List<Double> holds = new ArrayList<>();
    double lastTradeAt;

    Acc(double itemId, String name) {
      this.itemId = itemId;
      this.name = name;
    }
  }

  /**
   * personalHistory: items in the order their FIRST flip appears (a JS Map keeps insertion order), skipping removed
   * flips and any whose id, profit or quantity is not a finite number.
   */
  public static List<ItemHistory> personalHistory(List<Flip> flips) {
    Map<Double, Acc> byItem = new LinkedHashMap<>();
    if (flips != null) for (Flip f : flips) {
      if (f == null || f.removed || !JsValues.isFinite(f.itemId) || !JsValues.isFinite(f.profit) || !JsValues.isFinite(f.quantity)) continue;
      double key = f.itemId == 0 ? 0.0 : f.itemId; // a JS Map key: -0 and 0 are the same item
      Acc h = byItem.get(key);
      if (h == null) {
        h = new Acc(f.itemId, f.item);
        byItem.put(key, h);
      }
      h.trades++;
      if (f.profit > 0) h.wins++;
      h.totalProfit += f.profit;
      h.quantities.add(f.quantity);
      if (JsValues.isFinite(f.hold)) h.holds.add(f.hold);
      Double at = f.lastSell != null ? f.lastSell : f.confirmedAt != null ? f.confirmedAt : Double.valueOf(0);
      if (at > h.lastTradeAt) h.lastTradeAt = at;
      if (f.item != null && !f.item.isEmpty()) h.name = f.item; // the most recent name wins
    }
    List<ItemHistory> out = new ArrayList<>(byItem.size());
    for (Acc h : byItem.values())
      out.add(new ItemHistory(h.itemId, h.name, h.trades, (double) h.wins / h.trades, h.totalProfit / h.trades,
        Medians.average(h.quantities), Medians.average(h.holds), h.lastTradeAt));
    return Collections.unmodifiableList(out);
  }

  /**
   * The personal tier's eligibility at a risk level: enough trades, a high enough win rate, a typical size of at
   * least one unit, and not blocked. ({@code h.trades >= tier.minTrades && h.winRate >= tier.minWinRate &&
   * h.medianQty >= 1 && !blocklist.has(h.itemId)}.)
   */
  public static boolean eligible(ItemHistory h, LevelSettings level, Set<Integer> blocklist) {
    boolean blocked = blocklist != null && JsValues.isInteger(h.itemId) && blocklist.contains((int) h.itemId);
    return h.trades >= level.historyMinTrades && h.winRate >= level.historyMinWinRate && h.medianQty != null && h.medianQty >= 1 && !blocked;
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Js;
import com.evi.live.journal.Tax;
import com.evi.live.market.HourBucket;
import com.evi.live.market.LatestPrices;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The personal-history tier (bridge/suggestions.mjs {@code computeSuggestion}): the best BUY among items the player has
 * flipped before, ranked on their own track record. Pure; the clock is passed in.
 *
 * <p>THE ORDER OF THE CHECKS IS THE JS ORDER, and each one is the shipped rule:
 * <ol>
 *   <li>eligible at the risk level ({@link History#eligible}: trades, win rate, a typical size of at least one, not blocked);</li>
 *   <li>both sides priced in /latest;</li>
 *   <li>a positive margin after tax, and one that clears the level's tax bar ({@link Gates#marginClearsTax}, 0.5x on this tier
 *       -- a winning history does not make a 2 gp edge survive a 1 gp tick), unless "no minimum at all" switched it off;</li>
 *   <li>not an implausible spread on an hour nobody traded, and not an implausible buy print;</li>
 *   <li>sized ({@link Sizing#historyQuantity}: own median, cash, stack share, volume share, trade length, buy limit);</li>
 *   <li>the predicted profit (margin x quantity) reaches the minimum, and the score is above zero.</li>
 * </ol>
 * The best SCORE wins (a stable sort, ties keep the history's order). Never dropped for a stale print here: the player's
 * own record makes an old last trade context, so it is named in the reasoning instead.
 *
 * <p>The risk level reaches this tier through {@link LevelSettings} only (the seam the redesign fills in).
 */
public final class HistoryTier {
  private HistoryTier() {}

  /** computeSuggestion's options. Unset numbers are NaN; unset objects null. */
  public static final class Options {
    /** Below this predicted total a candidate is not offered; NaN or not above 0 means no floor. */
    public double minProfit = Double.NaN;
    public Set<Integer> blocklist;
    /** "low", "medium" or "high"; anything else (null included) is MEDIUM, this tier's own fallback. */
    public String risk;
    /** The cash stack: NaN unknown (no cap), 0 carrying nothing. */
    public double maxSpend = Double.NaN;
    public double targetDurationMinutes = Double.NaN;
    /** The latest Wiki hour (null: none was fetched). */
    public HourBucket volumes;
    /** The 168-hour typical volume per item (null: none). */
    public Map<Integer, ? extends Number> typicalVolumes;
    public double maxStackShare = Double.NaN;
    public double maxVolumeShare = Double.NaN;
    public double volumeWindowShare = Double.NaN;
    public boolean captureCap;
    /** Members world, focus and the buy limit left. */
    public Sizing.ItemGate gate = Sizing.ItemGate.NONE;
    /** {@code options.requireMarginOverTax !== false}: only "no minimum at all" turns the tax bar off. */
    public boolean requireMarginOverTax = true;
    /** {@code options.marginTaxMultiple}: null takes the level's bar (the bridge never passes one). */
    public Double marginTaxMultiple;
  }

  /** recencyWeight: 1 within a day, 0.85 within a week, 0.6 within a month, else (and for no date) 0.35. */
  public static double recencyWeight(double lastTradeAt, double now) {
    double days = (now - lastTradeAt) / 86400000;
    if (days <= 1) return 1;
    if (days <= 7) return 0.85;
    if (days <= 30) return 0.6;
    return 0.35;
  }

  /**
   * RISK_TIERS[level].score: the average profit, times the win rate {@link LevelSettings#historyWinRatePower} times,
   * times the recency weight -- multiplied LEFT TO RIGHT as the JS writes it ({@code avgProfit * winRate * winRate * rw}),
   * so the rounding of a tie is the same.
   */
  public static double score(History.ItemHistory h, double recency, LevelSettings level) {
    double s = h.avgProfit;
    for (int i = 0; i < level.historyWinRatePower; i++) s *= h.winRate;
    return s * recency;
  }

  private static final class Candidate {
    final History.ItemHistory h;
    final LatestPrices.Quote p;
    final double score;
    final Sizing.Sized sized;
    final double predictedProfit;
    final Double ageMinutes;

    Candidate(History.ItemHistory h, LatestPrices.Quote p, double score, Sizing.Sized sized, double predictedProfit, Double ageMinutes) {
      this.h = h;
      this.p = p;
      this.score = score;
      this.sized = sized;
      this.predictedProfit = predictedProfit;
      this.ageMinutes = ageMinutes;
    }
  }

  /** {@code latestPrices[String(itemId)]}: only a whole id in int range names an item (String(1.5) finds nothing). */
  private static LatestPrices.Quote quote(LatestPrices latest, double itemId) {
    if (latest == null || !JsValues.isInteger(itemId) || itemId > Integer.MAX_VALUE || itemId < Integer.MIN_VALUE) return null;
    return latest.get((int) itemId);
  }

  private static double typicalFor(Map<Integer, ? extends Number> typical, int itemId) {
    Number n = typical == null ? null : typical.get(itemId);
    return n == null ? Double.NaN : n.doubleValue();
  }

  /** computeSuggestion: one best suggestion from the player's own history, or null. */
  public static Pick computeSuggestion(List<History.Flip> flips, LatestPrices latest, double now, Options options) {
    Options o = options == null ? new Options() : options;
    double minProfit = JsValues.isFinite(o.minProfit) && o.minProfit > 0 ? o.minProfit : 0;
    Double maxSpend = Sizing.maxSpend(o.maxSpend);
    Double target = Sizing.duration(o.targetDurationMinutes);
    LevelSettings level = LevelSettings.forHistoryTier(o.risk);
    double marginMultiple = o.marginTaxMultiple != null ? o.marginTaxMultiple : level.historyMarginTaxMultiple;
    Sizing.SizingOptions sizing = new Sizing.SizingOptions(o.maxVolumeShare, o.volumeWindowShare, o.captureCap);
    List<Candidate> candidates = new ArrayList<>();
    for (History.ItemHistory h : History.personalHistory(flips)) {
      if (!History.eligible(h, level, o.blocklist)) continue;
      LatestPrices.Quote p = quote(latest, h.itemId);
      if (p == null || !(p.low > 0) || !(p.high > 0)) continue;
      int itemId = (int) h.itemId;
      long tax = Tax.estimateUnitTax(itemId, p.high);
      long net = Js.subtract(Js.subtract(p.high, p.low), tax); // JS arithmetic on GP, exact below 2^53
      if (net <= 0) continue;
      // An edge that does not cover this item's own tax, however good the track record.
      if (o.requireMarginOverTax && !Gates.marginClearsTax(net, tax, marginMultiple)) continue;
      // A margin too good to be true on something nobody is trading; this tier keeps stale prints, which is how a
      // ten-hour-old 10 gp print on Rune dart(p++) became a buy of 1,301.
      VolumeRow row = VolumeRow.of(o.volumes, itemId);
      Long reading = VolumeRow.reading(row);
      if (Gates.implausibleSpread(net, p.low, reading == null ? Double.NaN : reading, Gates.IMPLAUSIBLE_MARGIN_MULTIPLE)) continue;
      if (Gates.implausibleBuyPrint(p.low, row, Gates.BUY_PRINT_MULTIPLE)) continue;
      Sizing.Sized sized = Sizing.historyQuantity(itemId, h.medianQty, p.low, maxSpend, o.maxStackShare, row, typicalFor(o.typicalVolumes, itemId),
        target, sizing, o.gate);
      if (sized == null) continue;
      double predictedProfit = (double) net * sized.quantity;
      if (predictedProfit < minProfit) continue;
      double score = score(h, recencyWeight(h.lastTradeAt, now), level);
      if (score <= 0) continue;
      Double ageMinutes = Prices.priceAgeMinutes(side(p.highTime), side(p.lowTime), now);
      candidates.add(new Candidate(h, p, score, sized, predictedProfit, ageMinutes));
    }
    if (candidates.isEmpty()) return null;
    candidates.sort((a, b) -> Js.compare(b.score, a.score)); // stable: an equal score keeps the history's order
    Candidate c = candidates.get(0);
    History.ItemHistory h = c.h;
    Sizing.Sized s = c.sized;
    double shareUsed = JsValues.isFinite(o.maxVolumeShare) ? o.maxVolumeShare : Sizing.volumeShareForDuration(target == null ? Double.NaN : target);
    List<String> notes = new ArrayList<>();
    if (s.cashLimited) notes.add("reduced from your usual size to what your current cash stack can afford");
    if (s.stackLimited) notes.add("reduced so this one trade commits at most " + JsValues.text(JsValues.jsRound(o.maxStackShare * 100)) + "% of your cash stack");
    // Worded from whichever cap actually bound (the maintainer, 7 Oct 2026): under "Bigger positions" the WINDOW share
    // replaces the per-hour one (Sizing.orderSizeCap), so it is the one named.
    if (s.shareLimited) notes.add(JsValues.isFinite(o.volumeWindowShare) && o.volumeWindowShare > 0
      ? "reduced to " + JsValues.text(JsValues.jsRound(o.volumeWindowShare * 100))
        + "% of what this item trades over your whole trade window, so the order isn't larger than the market absorbs"
      : "reduced to " + JsValues.text(JsValues.jsRound(shareUsed * 100))
        + "% of what this item trades in a typical hour, so the order isn't larger than the market absorbs");
    if (s.durationLimited) notes.add("reduced to fit an estimated ~" + JsValues.text(target) + "-minute trade");
    if (s.limitLimited) notes.add("reduced to what EVI has seen left of this item's GE buy limit, which is all that can fill before the limit resets in 4 hours -- a bigger offer would sit part-filled until then");
    if (c.ageMinutes != null && c.ageMinutes > Prices.MAX_PRICE_AGE_MINUTES)
      notes.add("note that one side of this item's price is about " + JsValues.text(JsValues.jsRound(c.ageMinutes / 60)) + " hour(s) old, so the current spread may not be real");
    Pick out = new Pick((int) h.itemId, h.name, "buy", s.quantity, c.p.low, c.p.high, "personal");
    out.trades = h.trades;
    out.reasoning = "You've flipped this " + h.trades + " time" + (h.trades == 1 ? "" : "s") + " with a " + JsValues.text(JsValues.jsRound(h.winRate * 100))
      + "% win rate and ~" + JsValues.gp(h.avgProfit) + " GP average profit. Suggested quantity matches your typical size (" + s.quantity + ")"
      + (notes.isEmpty() ? "" : " -- " + String.join("; ", notes)) + "; buy near " + Js.groupedUs(c.p.low) + " gp, aim to sell near "
      + Js.groupedUs(c.p.high) + " gp for a predicted ~" + JsValues.gp(c.predictedProfit) + " gp.";
    return out;
  }

  // A /latest timestamp as priceAgeMinutes reads it: NaN when the Wiki sent none.
  private static double side(long v) {
    return v == HourBucket.NONE ? Double.NaN : v;
  }
}

package com.evi.live.engine;

import com.evi.live.journal.FifoMatcher;
import com.evi.live.journal.Js;
import com.evi.live.journal.Offer;
import com.evi.live.journal.Tax;
import com.evi.live.market.ItemCatalog;
import com.evi.live.market.LatestPrices;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.Set;
import java.util.function.IntPredicate;

/**
 * The sell-side tiers: stock the player already holds (bridge/suggestions.mjs {@code computeHoldingSuggestion},
 * {@code holdingPreempts}, {@code hasLiveSellOffer}, {@code pickPersistentOpenPosition}, {@code computeInventorySuggestion}),
 * and the "Best of both" rule that keeps a sell out of a contest between two BUYS ({@code comparableAsHistoryPick}). Pure.
 *
 * <p>These run BEFORE any buy tier: closing out a position already opened beats being pointed at a new one. They are
 * reminders, never blocks; none of them is gated on the buy-side checks (a player holding an unflippable item is still
 * helped to sell it).
 *
 * <p>ACCOUNT SCOPING (the 6 Oct rule): every function that reads positions or offers takes the asking account and owns
 * nothing for a missing one. A poll from the login screen speaks for nobody.
 */
public final class HoldingTiers {
  private HoldingTiers() {}

  /** Coins: gp itself is never "something to sell". */
  public static final int COINS_ITEM_ID = 995;
  /** Platinum tokens, 1,000 gp each: counted as spending power by the plugin, so never offered for sale either. */
  public static final int PLATINUM_TOKEN_ITEM_ID = 13204;
  /** MIN_INVENTORY_VALUE: below this an idle stack is junk, not a suggestion. */
  public static final double MIN_INVENTORY_VALUE = 100000;

  private static LatestPrices.Quote priced(LatestPrices latest, int itemId) {
    LatestPrices.Quote p = latest == null ? null : latest.get(itemId);
    return p == null || !(p.low > 0) || !(p.high > 0) ? null : p; // HourBucket.NONE (no print) is negative
  }

  /**
   * computeHoldingSuggestion: a reminder that the player holds {@code holdQty} of an item from an earlier buy that has
   * not been resold. Null for a non-positive id or quantity, or an item without both sides priced. With a known unit cost
   * ({@code holdBuyPrice}, NaN when unknown) it states the net of selling now, the break-even, and -- a warning, never an
   * instruction -- the loss when there is one; never a guessed cost.
   *
   * @param holdQty a whole number of units (the plugin sends an int; the type rules out a fraction)
   */
  public static Pick computeHoldingSuggestion(LatestPrices latest, int holdItemId, long holdQty, String holdName, String holdBuyId, double holdBuyPrice) {
    return computeHoldingSuggestion(latest, holdItemId, holdQty, holdName, holdBuyId, holdBuyPrice, null);
  }

  /**
   * computeHoldingSuggestion for a position whose sell listing ENDED while EVI was not watching ({@code endedUnseen}, the
   * open position's mark; null for every other holding). Nobody knows whether that listing sold, so the card states what EVI
   * saw and nothing it did not (8 Oct 2026, a real case, fixed in JS first): no "would net about +", no loss, no
   * break-even, netIfSoldNow null -- an UNKNOWN worth, which {@link #holdingPreempts} always lets speak -- and the enrichment
   * gives it no headline profit. Never suppressed.
   */
  public static Pick computeHoldingSuggestion(LatestPrices latest, int holdItemId, long holdQty, String holdName, String holdBuyId, double holdBuyPrice,
                                              FifoMatcher.EndedUnseenMark endedUnseen) {
    if (holdItemId <= 0 || holdQty <= 0) return null;
    LatestPrices.Quote p = priced(latest, holdItemId);
    if (p == null) return null;
    String name = holdName != null && !holdName.isEmpty() ? holdName : "item " + holdItemId;
    String qtyText = Js.groupedUs(holdQty), high = Js.groupedUs(p.high);
    String reasoning = "You're holding " + qtyText + " " + name + " from an earlier buy that hasn't been resold yet -- sell near " + high + " gp before starting anything new.";
    Long breakEvenPrice = null, lossIfSoldNow = null;
    Double netIfSoldNow = null;
    if (JsValues.isFinite(holdBuyPrice) && holdBuyPrice > 0) {
      long tax = Tax.estimateUnitTax(holdItemId, p.high);
      double netPerUnit = p.high - holdBuyPrice - tax;
      // ROUNDED FIRST, then judged (the maintainer, 7 Oct 2026, fixed in JS first): a loss under half a gp in total rounds
      // to minus zero, and `|| 0` folds that into zero, so the holding takes the rounded branch ("would net about +0 gp")
      // instead of "a LOSS of about 0 gp". A loss that rounds to a whole gp or more is still the loss it is.
      double rounded = JsValues.jsRound(netPerUnit * holdQty);
      double totalNet = rounded == 0 ? 0.0 : rounded;
      breakEvenPrice = Tax.breakEvenSellPrice(holdItemId, holdBuyPrice);
      String breakEvenText = breakEvenPrice != null && breakEvenPrice != 0 ? " Break-even after tax: " + Js.groupedUs(breakEvenPrice) + " gp." : "";
      netIfSoldNow = totalNet;
      if (totalNet < 0) lossIfSoldNow = JsValues.exactLong(Math.abs(totalNet));
      String paid = JsValues.localeUs(holdBuyPrice);
      reasoning = totalNet >= 0
        ? "You're holding " + qtyText + " " + name + " bought at " + paid + " gp -- selling near " + high + " gp now would net about +"
          + JsValues.localeUs(totalNet) + " gp." + breakEvenText
        // A warning, never a block, and not an instruction either way: both numbers, so the choice is informed.
        : "WARNING: you're holding " + qtyText + " " + name + " bought at " + paid + " gp -- selling near " + high + " gp now would be a LOSS of about "
          + JsValues.localeUs(Math.abs(totalNet)) + " gp." + breakEvenText
          + " Not a recommendation either way: sell now to cap the loss at that amount, or list at or above break-even if you'd rather wait for the price to recover (it may not).";
    }
    FifoMatcher.EndedUnseenMark gone = endedUnseen != null && endedUnseen.price > 0 ? endedUnseen : null;
    if (gone != null) {
      String bought = JsValues.isFinite(holdBuyPrice) && holdBuyPrice > 0 ? " bought at " + JsValues.localeUs(holdBuyPrice) + " gp" : "";
      boolean some = gone.quantity > 0 && gone.quantity < holdQty;
      reasoning = "EVI's record: " + qtyText + " " + name + bought + ". EVI last saw "
        + (some ? Js.groupedUs(gone.quantity) + " of them" : "this")
        + " listed at " + Js.groupedUs(gone.price) + " gp; the listing was gone at your next login (it ended while EVI wasn't watching), so EVI can't tell whether it sold. "
        + (some ? "If it sold and the rest are gone too, press Gone." : "If it sold, press Gone.");
      breakEvenPrice = null;
      lossIfSoldNow = null;
      netIfSoldNow = null;
    }
    Pick s = new Pick(holdItemId, name, "sell", holdQty, p.low, p.high, "holding");
    s.reasoning = reasoning;
    s.buyId = holdBuyId != null && !holdBuyId.isEmpty() ? holdBuyId : null;
    s.breakEvenPrice = breakEvenPrice;
    s.lossIfSoldNow = lossIfSoldNow;
    s.netIfSoldNow = netIfSoldNow;
    s.endedUnseen = gone;
    return s;
  }

  /**
   * hasLiveSellOffer: is this item ACTUALLY on the market for this account right now? Pass the plugin's live slots
   * ({@code state().active}), never the journal, which keeps a cancelled offer SELLING for ever. Package-private: production
   * asks {@link AccountView#hasLiveSellOffer}.
   */
  static boolean hasLiveSellOffer(List<Offer> activeOffers, int itemId, String account) {
    if (account == null || account.isEmpty() || activeOffers == null) return false;
    for (Offer o : activeOffers) if (o != null && o.itemId == itemId && "SELLING".equals(o.state) && account.equals(o.account)) return true;
    return false;
  }

  /**
   * holdingPreempts: should a holding reminder take the place of a ranked suggestion? A LOSS always speaks, an UNKNOWN
   * worth always speaks; only a trivial GAIN under the player's minimum steps aside (28 Sept: a 152 gp pie outranking the
   * catalogue at 205m idle). Measured and settled 30 Sept -- do not "fix" it without beating it (tools/holding-gate.mjs).
   */
  public static boolean holdingPreempts(Pick suggestion, double minProfit) {
    if (suggestion == null) return false;
    Double net = suggestion.netIfSoldNow;
    if (net == null || !JsValues.isFinite(net)) return true;
    if (net < 0) return true;
    if (!JsValues.isFinite(minProfit) || minProfit <= 0) return true;
    return net >= minProfit;
  }

  /**
   * pickPersistentOpenPosition: the journal's oldest open position for THIS account with no sell offer behind it -- the
   * first one not already listed, not simply the oldest (29 Sept: one listed position starved three behind it). Null for
   * no account or nothing left after the exclusions. Package-private: production asks
   * {@link AccountView#pickPersistentOpenPosition}.
   */
  static FifoMatcher.OpenPosition pickPersistentOpenPosition(List<FifoMatcher.OpenPosition> openPositions, String account, Set<Integer> blocklist,
                                                                    IntPredicate isListed) {
    if (openPositions == null || account == null || account.isEmpty()) return null;
    List<FifoMatcher.OpenPosition> mine = new ArrayList<>();
    for (FifoMatcher.OpenPosition p : openPositions)
      if (p != null && account.equals(p.account) && p.remaining > 0 && (blocklist == null || !blocklist.contains(p.itemId))) mine.add(p);
    if (mine.isEmpty()) return null;
    // a.firstSeen - b.firstSeen: a JSON null firstSeen subtracts as 0 (JS null arithmetic), so it sorts as the oldest.
    mine.sort((a, b) -> Js.compare(a.firstSeen == null ? 0 : a.firstSeen, b.firstSeen == null ? 0 : b.firstSeen));
    for (FifoMatcher.OpenPosition p : mine) if (isListed == null || !isListed.test(p.itemId)) return p;
    return null;
  }

  /** computeInventorySuggestion's options. Every field may be null (nothing excluded, nothing kept). */
  public static final class InventoryOptions {
    public Set<Integer> blocklist;
    /** This account's own open positions: the holding tier owns those items and can state their cost. */
    public Set<Integer> positionItemIds;
    /** A free-to-play world: a members item cannot be sold there either. */
    public IntPredicate membersBlocked;
    /** How many of each item are kept FOR USE (only the surplus is stock). */
    public Map<Integer, Long> keptForUse;
  }

  /**
   * computeInventorySuggestion: the fallback of last resort -- stock in the bag with no observed buy behind it (a drop, a
   * reward, stock from before EVI watched), worth at least {@link #MIN_INVENTORY_VALUE} at today's high, the most
   * valuable first. {@code inventory} iterates in ascending item id, as the JS object's integer keys do; {@code names}
   * is the item catalogue's id -> name (a missing or empty name reads "item N").
   */
  public static Pick computeInventorySuggestion(LatestPrices latest, NavigableMap<Integer, Long> inventory, Map<Integer, String> names, InventoryOptions options) {
    if (inventory == null || names == null || latest == null) return null;
    InventoryOptions o = options == null ? new InventoryOptions() : options;
    List<Object[]> candidates = new ArrayList<>(); // {itemId, sellable, quote, value, name}
    for (Map.Entry<Integer, Long> e : inventory.entrySet()) {
      int itemId = e.getKey();
      Long qty = e.getValue();
      if (itemId == COINS_ITEM_ID || itemId == PLATINUM_TOKEN_ITEM_ID || qty == null || !(qty > 0)) continue;
      if (o.blocklist != null && o.blocklist.contains(itemId)) continue;
      if (o.positionItemIds != null && o.positionItemIds.contains(itemId)) continue;
      if (o.membersBlocked != null && o.membersBlocked.test(itemId)) continue;
      LatestPrices.Quote p = priced(latest, itemId);
      if (p == null) continue;
      Long kept = o.keptForUse == null ? null : o.keptForUse.get(itemId);
      long sellable = kept != null ? qty - Math.max(1, kept) : qty; // holding exactly what is kept leaves nothing
      if (!(sellable > 0)) continue;
      double value = (double) sellable * p.high;
      if (value < MIN_INVENTORY_VALUE) continue;
      String name = names.get(itemId);
      candidates.add(new Object[]{itemId, sellable, p, value, name != null && !name.isEmpty() ? name : "item " + itemId});
    }
    if (candidates.isEmpty()) return null;
    candidates.sort((a, b) -> Js.compare((double) b[3], (double) a[3]));
    Object[] c = candidates.get(0);
    int itemId = (int) c[0];
    long qty = (long) c[1];
    LatestPrices.Quote p = (LatestPrices.Quote) c[2];
    String name = (String) c[4];
    Pick s = new Pick(itemId, name, "sell", qty, p.low, p.high, "inventory");
    s.buyId = null;
    s.reasoning = "You're holding " + Js.groupedUs(qty) + " " + name + " worth an estimated " + JsValues.gp((double) c[3])
      + " gp at current prices, with no active offer and no buy EVI ever observed for it -- likely a drop, a quest reward, or stock from before EVI started watching. Sell near "
      + Js.groupedUs(p.high) + " gp if you don't need it.";
    return s;
  }

  /** The catalogue's names as computeInventorySuggestion reads them: a later entry for the same id wins. */
  public static Map<Integer, String> namesOf(List<ItemCatalog.Item> mapping) {
    Map<Integer, String> names = new HashMap<>();
    if (mapping != null) for (ItemCatalog.Item m : mapping) if (m != null) names.put(m.id, m.name);
    return Collections.unmodifiableMap(names);
  }

  /**
   * comparableAsHistoryPick: is this one of the two BUYS "Best of both" chooses between? A sell of stock already owned
   * is not: it consumes neither the slot nor the coins the buy needs (30 Sept, the Gilded d'hide vambraces).
   */
  public static boolean comparableAsHistoryPick(Pick suggestion, String wantSource) {
    return "both".equals(wantSource) && suggestion != null && suggestion.isBuy();
  }
}

package com.evi.live.engine;

import com.evi.live.journal.FifoMatcher;
import com.evi.live.journal.Tax;
import com.evi.live.market.HourBucket;
import com.evi.live.market.LatestPrices;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * "Here is what you are holding." -- every tracked position, always, WHATEVER THE PROFIT SETTING (bridge/holdingsAdvice.mjs
 * {@code holdingsAdvice}). Pure.
 *
 * <p>THE SEPARATION THIS CLASS IS (30 Sept 2026): "what should I do next" and "what am I holding" had shared the one
 * suggestion slot, so a holding had to beat a new trade to be mentioned at all, and {@code holdingPreempts} judges it
 * against the player's MINIMUM PROFIT -- a +254,063 gp position was invisible under a 1m minimum. Lowering that bar was
 * measured and COSTS GP (tools/holding-gate.mjs), so the bar stays and the QUESTION moves: these lines ride relistAdvice.
 * THIS METHOD CANNOT BE PASSED A MINIMUM PROFIT -- there is no parameter for one, which is the strongest guarantee the two
 * questions stay separate. A 152 gp pie is ALLOWED here: a line to scroll past, never a displaced suggestion.
 *
 * <p>Only positions with a REAL cost basis; nothing already standing in a sell slot (visible, and Relist/SellAdvice speak
 * about it); nothing about the item EVI is suggesting right now; a loss stated as plainly as a gain; and it states, never
 * advises.
 */
public final class HoldingsAdvice {
  private HoldingsAdvice() {}

  /** MAX_LINES: so thirty holdings are not a wall of text; the most valuable first. */
  public static final int MAX_LINES = 5;

  /**
   * One open position: {itemId, item, remaining, unitCost}; NaN for what the caller did not have. {@code endedUnseenPrice}:
   * the price of a sell listing of it that ENDED while EVI was not watching (the position's endedUnseen mark), null for none.
   */
  public static final class Position {
    public final Integer itemId;
    public final String item;
    public final double remaining;
    public final double unitCost;
    public final Double endedUnseenPrice;
    /** The lot's buy offer id (8 Oct 2026): carried onto its line for the sidebar's line menu; null or empty: no key. */
    public final String buyId;

    public Position(Integer itemId, String item, double remaining, double unitCost) {
      this(itemId, item, remaining, unitCost, null);
    }

    public Position(Integer itemId, String item, double remaining, double unitCost, Double endedUnseenPrice) {
      this(itemId, item, remaining, unitCost, endedUnseenPrice, null);
    }

    public Position(Integer itemId, String item, double remaining, double unitCost, Double endedUnseenPrice, String buyId) {
      this.itemId = itemId;
      this.item = item;
      this.remaining = remaining;
      this.unitCost = unitCost;
      this.endedUnseenPrice = endedUnseenPrice;
      this.buyId = buyId;
    }
  }

  /**
   * holdingsAdvice: at most {@code max} lines, most valuable first (ties keep position order). {@code highs}: item id to
   * what a seller gets now (/latest's {@code high}; absent or null: no current price -- the position is still LISTED, with
   * its cost and no worth). {@code listedItemIds}: items standing in a sell offer. {@code suggestedItemId}: this poll's
   * suggestion (null: none).
   * <p>Package-private on purpose: outside the engine the only way in is {@link #forAccount}, which reads ONE account's
   * records from its {@link AccountView}. The parity harness (same package) drives this record-level core directly.
   */
  static List<AdviceNote> holdingsAdvice(List<Position> positions, Map<Integer, Double> highs, Set<Integer> listedItemIds,
                                         Integer suggestedItemId, double max) {
    List<AdviceNote> rows = new ArrayList<>();
    List<Double> sortBy = new ArrayList<>();
    if (positions != null) for (Position p : positions) {
      if (p == null || p.itemId == null) continue;
      double qty = JsValues.isFinite(p.remaining) && p.remaining > 0 ? p.remaining : 0;
      if (qty == 0) continue;
      if (!(p.unitCost > 0)) continue;                                             // no cost basis: nothing honest to say
      if (listedItemIds != null && listedItemIds.contains(p.itemId)) continue;     // already on the market and visible
      if (p.itemId.equals(suggestedItemId)) continue;                              // already the suggestion
      String name = p.item != null && !p.item.isEmpty() ? p.item : "item " + p.itemId;
      double cost = p.unitCost * qty;
      // The lot's buyId, only when it is a non-empty string (the JS spreads {buyId} in then, nothing otherwise).
      String lot = p.buyId != null && !p.buyId.isEmpty() ? p.buyId : null;
      // A sell listing of it ENDED while EVI was not watching: it may have sold, so no worth and no net -- only the facts.
      // Still listed, never dropped: it may be in the bag.
      if (p.endedUnseenPrice != null && JsValues.isFinite(p.endedUnseenPrice) && p.endedUnseenPrice > 0) {
        AdviceNote gone = new AdviceNote(p.itemId);
        gone.buyId = lot;
        gone.name = name;
        gone.quantity = qty;
        gone.unitCost = JsValues.jsRound(p.unitCost);
        gone.cost = JsValues.jsRound(cost);
        gone.breakEven = null;
        gone.holding = true;
        sortBy.add(cost);
        gone.level = "caution";
        gone.label = "Holding, outcome unknown";
        gone.figures = JsValues.gp(qty) + " · last listed at " + JsValues.gp(p.endedUnseenPrice);
        gone.message = "Bought for " + JsValues.gp(cost) + ". EVI last saw it listed at " + JsValues.gp(p.endedUnseenPrice)
          + " gp and the listing was gone at your next login, so EVI can't tell whether it sold. No profit is claimed.";
        rows.add(gone);
        continue;
      }
      Double price = highs == null ? null : highs.get(p.itemId);
      Long breakEven = Tax.breakEvenSellPrice(p.itemId, p.unitCost);
      boolean hasBreakEven = breakEven != null && breakEven > 0;
      AdviceNote row = new AdviceNote(p.itemId);
      row.buyId = lot;
      row.name = name;
      row.quantity = qty;
      row.unitCost = JsValues.jsRound(p.unitCost);
      row.cost = JsValues.jsRound(cost);
      row.breakEven = hasBreakEven ? (double) breakEven : null;
      row.holding = true;
      if (price == null || !(price > 0)) {
        // No current price: say so rather than imply a worth; sorted by its cost, which is still real capital.
        sortBy.add(cost);
        row.level = "info";
        row.label = "Holding";
        row.figures = JsValues.gp(qty) + " · cost " + JsValues.gp(cost);
        row.message = "Cost " + JsValues.gp(cost) + (hasBreakEven ? ". Break-even " + JsValues.gp(breakEven) + " each" : "")
          + ". No current price, so EVI can't say what it's worth today.";
        rows.add(row);
        continue;
      }
      double net = (price - p.unitCost - Tax.estimateUnitTax(p.itemId, price)) * qty;
      row.worth = JsValues.jsRound(price * qty);
      row.net = JsValues.jsRound(net);
      sortBy.add(price * qty);
      row.level = net >= 0 ? "info" : "caution";
      row.label = net >= 0 ? "Holding" : "Holding, under water";
      row.figures = JsValues.gp(qty) + " · " + (net >= 0 ? "+" : "") + JsValues.gp(net) + " after tax";
      row.message = "Bought for " + JsValues.gp(cost) + (hasBreakEven ? ". Break-even " + JsValues.gp(breakEven) + " each" : "")
        + ". Listed because you own it, not as advice to sell.";
      rows.add(row);
    }
    List<Integer> idx = new ArrayList<>();
    for (int i = 0; i < rows.size(); i++) idx.add(i);
    idx.sort((a, b) -> {
      double d = sortBy.get(b) - sortBy.get(a);
      return d > 0 ? 1 : d < 0 ? -1 : 0; // NaN reads as equal, as in JS
    });
    List<AdviceNote> out = new ArrayList<>();
    double end = BuyProgress.sliceEnd(Math.max(0, max));
    for (int k = 0; k < idx.size() && k < end; k++) out.add(rows.get(idx.get(k)));
    return out;
  }

  /**
   * holdingsAdvice for ONE account (server.mjs): ITS open lots, skipping the items IT has listed, valued at /latest's buyers'
   * price (market-wide, named as such: every item's {@code high}), with the default cap. Another account's lot or listing is
   * not in the view, so it can neither add a line here nor hide one.
   */
  public static List<AdviceNote> forAccount(AccountView view, LatestPrices marketLatest, Integer suggestedItemId) {
    List<Position> held = new ArrayList<>();
    for (FifoMatcher.OpenPosition p : view.positions)
      held.add(new Position(p.itemId, p.item, p.remaining, p.unitCost, p.endedUnseen == null ? null : (double) p.endedUnseen.price, p.buyId));
    Map<Integer, Double> highs = new LinkedHashMap<>();
    if (marketLatest != null) for (Map.Entry<Integer, LatestPrices.Quote> e : marketLatest.all().entrySet())
      if (e.getValue().high != HourBucket.NONE) highs.put(e.getKey(), (double) e.getValue().high);
    return holdingsAdvice(held, highs, view.listedItemIds, suggestedItemId);
  }

  /** The default cap, {@link #MAX_LINES}. */
  static List<AdviceNote> holdingsAdvice(List<Position> positions, Map<Integer, Double> highs, Set<Integer> listedItemIds, Integer suggestedItemId) {
    return holdingsAdvice(positions, highs, listedItemIds, suggestedItemId, MAX_LINES);
  }
}

package com.evi.live.engine;

/**
 * An item's plain live price for an open GE offer ({@code lookupItemPrice}), optionally made aware of what the player
 * paid ({@code withCostBasis}). Immutable. {@code action}, {@code breakEvenPrice} and {@code lossIfSoldNow} are null
 * until a cost basis is known: never a guessed cost.
 */
public final class ItemPrice {
  public final int itemId;
  /** The last instant-sell price ({@code /latest} low): what to bid. */
  public final long buyPrice;
  /** The last instant-buy price ({@code /latest} high): what to ask. */
  public final long sellPrice;
  /** "sell" once a cost basis marks this as a sale of stock the player holds; otherwise null. */
  public final String action;
  public final Long breakEvenPrice;
  /** The total loss of selling the held units at {@link #sellPrice}, rounded half-up; null when it is not a loss. */
  public final Long lossIfSoldNow;

  public ItemPrice(int itemId, long buyPrice, long sellPrice, String action, Long breakEvenPrice, Long lossIfSoldNow) {
    this.itemId = itemId;
    this.buyPrice = buyPrice;
    this.sellPrice = sellPrice;
    this.action = action;
    this.breakEvenPrice = breakEvenPrice;
    this.lossIfSoldNow = lossIfSoldNow;
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Js;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;
import java.util.regex.Pattern;

/**
 * The JavaScript value rules the engine's ports lean on that {@code journal.Js} does not already cover: turning a
 * query-string value into a number exactly as {@code Number(string)} does, {@code String.prototype.trim}, and
 * converting an integral double to a quantity without ever wrapping or saturating.
 *
 * <p>Pure: no I/O, no clock, no threads. Each rule is checked against the real JS by EngineVectorsTest.
 *
 * <p>WHY {@code Number(string)} IS NOT {@code Double.parseDouble}. They disagree on exactly the inputs a query string
 * can carry: JS reads {@code " "} and {@code ""} as 0, {@code "0x10"} as 16, {@code "0b11"} as 3, and accepts
 * {@code "Infinity"}; Java throws on the first three and also accepts {@code "1d"}, {@code "NaN"}, {@code "0x1p3"}
 * and trims every control character, where JS trims only Unicode white space and line terminators.
 */
public final class JsValues {
  private JsValues() {}

  // StrDecimalLiteral without the Infinity forms: ASCII digits only, no separators, an optional sign.
  private static final Pattern DECIMAL = Pattern.compile("[+-]?(?:[0-9]+\\.?[0-9]*|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?");
  private static final Pattern NON_DECIMAL = Pattern.compile("0(?:[xX][0-9a-fA-F]+|[oO][0-7]+|[bB][01]+)");

  /**
   * ECMAScript WhiteSpace and LineTerminator: what {@code trim} removes and what {@code Number(" 3 ")} ignores.
   * TAB, VT, FF, ZWNBSP, every Zs space, LF, CR, LS and PS -- and NOT the other control characters, which Java's
   * {@link String#trim} would strip. Every non-ASCII character here is a unicode ESCAPE, never a literal: an invisible
   * literal does not survive a mis-encoded round trip of the file, and nobody reviewing it can see what it is.
   */
  public static boolean isJsSpace(char c) {
    switch (c) {
      case '\t': case '\u000B': case '\f': case ' ': case '\u00A0': case '\uFEFF':
      case '\n': case '\r': case '\u2028': case '\u2029':
      case '\u1680': case '\u202F': case '\u205F': case '\u3000':
        return true;
      default:
        return c >= '\u2000' && c <= '\u200A';
    }
  }

  /** {@code String.prototype.trim}. */
  public static String trim(String s) {
    int a = 0, b = s.length();
    while (a < b && isJsSpace(s.charAt(a))) a++;
    while (b > a && isJsSpace(s.charAt(b - 1))) b--;
    return s.substring(a, b);
  }

  /**
   * {@code Number(s)} for a string (ECMAScript StringToNumber): white space trimmed; empty is 0; a decimal literal,
   * {@code Infinity} with an optional sign, or an unsigned 0x/0o/0b integer, each rounded to the nearest double;
   * anything else NaN.
   */
  public static double toNumber(String s) {
    String t = trim(s);
    if (t.isEmpty()) return 0;
    switch (t) {
      case "Infinity": case "+Infinity": return Double.POSITIVE_INFINITY;
      case "-Infinity": return Double.NEGATIVE_INFINITY;
      default: break;
    }
    if (DECIMAL.matcher(t).matches()) return Double.parseDouble(t);
    if (NON_DECIMAL.matcher(t).matches()) {
      char k = Character.toLowerCase(t.charAt(1));
      int radix = k == 'x' ? 16 : k == 'o' ? 8 : 2;
      return new BigInteger(t.substring(2), radix).doubleValue(); // nearest double, ties to even, as JS rounds
    }
    return Double.NaN;
  }

  /** {@code Number.isFinite}. */
  public static boolean isFinite(double d) {
    return !Double.isNaN(d) && !Double.isInfinite(d);
  }

  /** {@code Number.isInteger}. */
  public static boolean isInteger(double d) {
    return isFinite(d) && Math.floor(d) == d;
  }

  // 2^63: the first magnitude a long cannot hold.
  private static final double TWO_63 = 0x1p63;
  // 2^52: from here on every double is a whole number, so Math.round has nothing to do.
  private static final double TWO_52 = 0x1p52;

  /**
   * {@code Math.round} exactly as JavaScript has it, as a DOUBLE: half-up ({@code 2.5 -> 3}, {@code -2.5 -> -2}), NaN and
   * the infinities unchanged, and -- the part a {@code long} cannot carry -- MINUS ZERO for anything in [-0.5, 0) and for
   * -0 itself. That sign is observable: {@code Math.round(-0.3).toLocaleString('en-US')} is "-0" in the bridge's wording,
   * so a sentence quoting a tiny negative margin says "-0 gp" there and must say it here too ({@link #gp}).
   */
  public static double jsRound(double x) {
    if (Double.isNaN(x) || Double.isInfinite(x)) return x;
    if (x < 0 && x >= -0.5 || (x == 0 && 1 / x < 0)) return -0.0;
    if (Math.abs(x) >= TWO_52) return x;
    return (double) Math.round(x); // Java's Math.round is floor(x + 0.5) done exactly, as V8's is
  }

  /**
   * {@code (x).toLocaleString('en-US')} for ANY number, pinned to the US format whatever the host locale is (a Dutch
   * install prints "1.234,5"): grouping commas, at most three fraction digits, rounded half AWAY from zero ("halfExpand")
   * -- and rounded on the number's SHORTEST decimal form, as ICU does, not on its exact binary value: {@code 1.0005}
   * prints "1.001" there although the double is 1.000499999.... A negative value that rounds to zero keeps its sign
   * ("-0"), and so does -0. NaN is "NaN" and the infinities "∞"/"-∞", as ICU writes them.
   */
  public static String localeUs(double x) {
    if (Double.isNaN(x)) return "NaN";
    if (Double.isInfinite(x)) return x > 0 ? "∞" : "-∞";
    boolean negative = x < 0 || (x == 0 && 1 / x < 0);
    BigDecimal shortest = new BigDecimal(Js.numberToString(Math.abs(x)));
    BigDecimal r = shortest.setScale(3, RoundingMode.HALF_UP).stripTrailingZeros();
    String plain = r.signum() == 0 ? "0" : r.toPlainString();
    int dot = plain.indexOf('.');
    String whole = dot < 0 ? plain : plain.substring(0, dot), fraction = dot < 0 ? "" : plain.substring(dot);
    StringBuilder sb = new StringBuilder(negative ? "-" : "");
    for (int i = 0; i < whole.length(); i++) {
      if (i > 0 && (whole.length() - i) % 3 == 0) sb.append(',');
      sb.append(whole.charAt(i));
    }
    return sb.append(fraction).toString();
  }

  /** {@code Math.round(n).toLocaleString('en-US')}: the bridge's {@code gp(n)} helper, "-0" included. */
  public static String gp(double n) {
    return localeUs(jsRound(n));
  }

  /**
   * {@code (x).toFixed(digits)} exactly as JavaScript has it (Number.prototype.toFixed): rounded on the number's EXACT
   * binary value, a tie going to the LARGER magnitude -- so {@code (0.15).toFixed(1)} is "0.1" (0.1499999...) and
   * {@code (0.05).toFixed(1)} is "0.1" (0.0500000...). A negative number keeps its sign even when it rounds to zero
   * ({@code (-0.04).toFixed(1)} is "-0.0"); -0 prints without one. NaN is "NaN", and from 1e21 up the plain
   * {@code String(x)} is returned, as the spec says. Never {@code String.format}, which rounds the shortest decimal form
   * and follows the host locale (a Dutch install prints "0,1").
   */
  public static String toFixed(double x, int digits) {
    if (Double.isNaN(x)) return "NaN";
    if (Math.abs(x) >= 1e21 || Double.isInfinite(x)) return Js.numberToString(x);
    boolean negative = x < 0;
    BigDecimal r = new BigDecimal(Math.abs(x)).setScale(digits, RoundingMode.HALF_UP);
    return (negative ? "-" : "") + r.toPlainString();
  }

  /** {@code `${n}`}: a number interpolated into a template (ECMAScript Number::toString; -0 prints "0"). */
  public static String text(double n) {
    return Js.numberToString(n);
  }

  /**
   * An integral JS number as a long: a quantity the JS engine computed with {@code Math.floor}/{@code Math.max}.
   * Throws (ArithmeticException) for NaN, a fraction, an infinity or anything past what a long holds -- never wraps
   * round to the other sign or saturates, the same refusal {@code journal.Js.round} makes.
   */
  public static long exactLong(double d) {
    if (Double.isNaN(d) || d >= TWO_63 || d < -TWO_63 || Math.floor(d) != d)
      throw new ArithmeticException("quantity " + d + " is not a whole number a long can hold");
    return (long) d;
  }
}

package com.evi.live.engine;

/**
 * THE RISK-LEVEL SEAM. Every value the engine reads that the risk redesign is still deciding lives here, holding
 * exactly what the bridge does TODAY, so the ports never hard-code one deep inside a function and the redesign
 * can fill these in once its levels are calibrated (SELF-CONTAINED-PLAN Phase 5; EVI-REDESIGN-PLAN step 3).
 *
 * <p>TODAY THE RISK LEVEL CHANGES ONE THING: the personal-history tier's eligibility ({@code RISK_TIERS} in
 * suggestions.mjs: minimum trades, minimum win rate, and how strongly the win rate weighs in the score). The
 * margin bars and the liquidity floor are the same at every level, and the market tier does not read the level at
 * all. So {@link #LOW}, {@link #MEDIUM} and {@link #HIGH} differ only in those three history fields; the market tier's
 * bar, floor and ranking ({@link #noHistoryMarginTaxMultiple}, {@link #minHourlyVolume}, {@link #marketRankBy}) are the same
 * at every level, as in the bridge. Each value is
 * asserted against the JS constant it stands for by EngineVectorsTest, so a change on either side is caught.
 *
 * <p>Two defaults, deliberately different, because they are in the bridge: a request naming no (or an unknown) risk
 * is LOW ({@code server.mjs}: anything else falls back to 'low'), while the history tier's own fallback for an
 * unknown tier name is MEDIUM ({@code RISK_TIERS[options.risk] || RISK_TIERS.medium}).
 */
public final class LevelSettings {
  /** The bar for a tier with the player's own track record on the item ({@code MARGIN_TAX_MULTIPLE}). */
  public final double historyMarginTaxMultiple;
  /** The bar for the market-wide and scanner tiers, which have no track record ({@code MARGIN_TAX_NO_HISTORY_MULTIPLE}). */
  public final double noHistoryMarginTaxMultiple;
  /** Below this a personal-tier pick is offered with a warning ({@code MARGIN_TAX_WARN_MULTIPLE}). */
  public final double warnMarginTaxMultiple;
  /** The market tier's hourly liquidity floor ({@code MIN_HOURLY_VOLUME}). */
  public final double minHourlyVolume;
  /** {@code RISK_TIERS[level].minTrades}. */
  public final int historyMinTrades;
  /** {@code RISK_TIERS[level].minWinRate}. */
  public final double historyMinWinRate;
  /** The power of the win rate in {@code RISK_TIERS[level].score}: 2 for low, 1 for medium, 0 for high. */
  public final int historyWinRatePower;
  /**
   * The market tier's ranking rule ({@code options.rankBy} in computeMarketSuggestion): {@code null} -- the shipped
   * score, the margin times log(liquidity + 1) -- at EVERY level today, because server.mjs's suggestionPolicy passes
   * {@code marketRankBy: undefined} on purpose (4 Oct: the BIGGER_POSITIONS 'profit' ranking was a shipped defect, and
   * nothing may fill this seam without a replay behind it). The other values {@link MarketTier} understands are
   * 'profit-per-hour', 'profit' and 'soft-liquidity', each measured and none in use.
   */
  public final String marketRankBy;

  private LevelSettings(int minTrades, double minWinRate, int winRatePower) {
    this.historyMarginTaxMultiple = 0.5;
    this.noHistoryMarginTaxMultiple = 1;
    this.warnMarginTaxMultiple = 1;
    this.minHourlyVolume = 5;
    this.historyMinTrades = minTrades;
    this.historyMinWinRate = minWinRate;
    this.historyWinRatePower = winRatePower;
    this.marketRankBy = null;
  }

  public static final LevelSettings LOW = new LevelSettings(3, 0.75, 2);
  public static final LevelSettings MEDIUM = new LevelSettings(1, 0.5, 1);
  public static final LevelSettings HIGH = new LevelSettings(1, 0.4, 0);

  /** The level a request asks for: 'low', 'medium' or 'high', anything else (absent included) LOW, as server.mjs reads it. */
  public static LevelSettings forRequest(String risk) {
    if ("medium".equals(risk)) return MEDIUM;
    if ("high".equals(risk)) return HIGH;
    return LOW;
  }

  /** The history tier's own lookup: an unknown name is MEDIUM ({@code RISK_TIERS[options.risk] || RISK_TIERS.medium}). */
  public static LevelSettings forHistoryTier(String risk) {
    if ("low".equals(risk)) return LOW;
    if ("high".equals(risk)) return HIGH;
    return MEDIUM;
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Js;
import com.evi.live.journal.Tax;
import com.evi.live.market.HourBucket;
import com.evi.live.market.ItemCatalog;
import com.evi.live.market.LatestPrices;
import com.evi.live.market.MarketAggregates;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The market-wide tier (bridge/suggestions.mjs {@code computeMarketSuggestion}): the best BUY in the whole item catalogue
 * for a player with no history on it, and the request's three ways of asking for one (server.mjs's {@code rank} and
 * {@code marketRankAt}, as {@link Ranking}). Pure; the clock is passed in.
 *
 * <p>THE ORDER OF THE CHECKS IS THE JS ORDER, item by item in the MAPPING's order:
 * <ol>
 *   <li>a valid id, not blocklisted, not a members item on a free world;</li>
 *   <li>both sides priced in /latest;</li>
 *   <li>the liquidity floor on the LATEST hour ({@link Gates#liquidityFloorMet}: 5 an hour, or 24 over the window under
 *       "Bigger positions");</li>
 *   <li>tax-free only (the old Starter profile), when asked;</li>
 *   <li>not a stale spread: the staler side at most an hour old ({@link Prices#MAX_PRICE_AGE_MINUTES}; unknown times fail open);</li>
 *   <li>a positive margin after tax that clears the NO-HISTORY bar, 1x the item's own tax ({@link LevelSettings#noHistoryMarginTaxMultiple}),
 *       on the live quote AND on the steady (336-hour robust) price -- an item has to clear both views, not whichever flatters it;</li>
 *   <li>not an implausible spread on an hour nobody traded, and not an implausible buy print;</li>
 *   <li>sized ({@link Sizing#marketQuantity}: the buy limit across the pace's windows, cash, the trade length, the stack
 *       share, the window or volume share on the typical hour, the 4-hour buy-limit clip);</li>
 *   <li>the more cautious of the live and the steady total reaches the minimum, and the score is above zero.</li>
 * </ol>
 *
 * <p>RANK ON A STEADY PRICE, QUOTE THE LIVE ONE. The score is the steady margin times the quantity (once cash or a pace
 * constrains), times {@code log(liquidity + 1)} on the LATEST hour; the quote, the predicted profit and the reasoning are
 * the live figures. {@link StrictMath#log} (fdlibm, which V8's Math.log is a port of), so a tie in the score is a tie in
 * both engines -- and a tie keeps the MAPPING's order (a stable sort; {@link Js#compare}, NaN as equal), because the
 * order and the ties decide which item {@code spreadRank} hands each account.
 *
 * <p>THE RANKING RULE is {@link Options#rankBy}: null is the shipped score. The other three are measured variants the
 * bridge never passes ({@link LevelSettings#marketRankBy} is null at every level); they are ported so the tools'
 * replays and this port answer alike, not to be switched on.
 *
 * <p>GP is a {@code long} wherever a price, a margin or a quantity is held; a margin TIMES a quantity is the double JS
 * computes ({@code net * quantity}), exact below 2^53, and only ever compared or printed.
 */
public final class MarketTier {
  private MarketTier() {}

  /** computeMarketSuggestion's options. Unset numbers are NaN; unset objects null. */
  public static final class Options {
    /** Below this (the more cautious total) a candidate is not offered; NaN or not above 0 means no floor. */
    public double minProfit = Double.NaN;
    public Set<Integer> blocklist;
    /** The cash stack: NaN unknown (no cap), 0 carrying nothing (afford nothing). */
    public double maxSpend = Double.NaN;
    public double targetDurationMinutes = Double.NaN;
    /**
     * The clock, epoch ms, for the stale-spread check. The JS falls back to Date.now(); this port has no clock of its own,
     * so the caller always passes one -- NaN judges nothing stale (an age against no clock is no age).
     */
    public double now = Double.NaN;
    /** {@code options.maxPriceAgeMinutes}; NaN takes {@link Prices#MAX_PRICE_AGE_MINUTES}. */
    public double maxPriceAgeMinutes = Double.NaN;
    /** {@code options.maxVolumeShare}: NaN takes the pace's share ({@link Sizing#volumeShareForDuration}); 0 or below turns the cap off. */
    public double maxVolumeShare = Double.NaN;
    /** "Bigger positions": a share of the WHOLE window's volume instead of the per-hour cap; NaN unset. */
    public double volumeWindowShare = Double.NaN;
    /** "Bigger positions": the per-WINDOW liquidity floor instead of the hourly one; NaN unset. */
    public double minVolumeInWindow = Double.NaN;
    /** Raises the hourly floor above the level's (never below it); NaN unset. */
    public double minHourlyVolume = Double.NaN;
    /** The share of the cash stack one trade may commit (stackShare / 100); NaN unset. Only with a known stack. */
    public double maxStackShare = Double.NaN;
    /** Only items the GE charges no tax on. */
    public boolean taxFreeOnly;
    /** {@code options.requireMarginOverTax !== false}: only "no minimum at all" turns the tax bar off. */
    public boolean requireMarginOverTax = true;
    /** {@code options.marginTaxMultiple}: null takes the level's no-history bar (the bridge never passes one). */
    public Double marginTaxMultiple;
    /** The steady price to RANK on, by item ({@code robustPricesCached}); null or a missing item ranks on the live quote. */
    public Map<Integer, MarketAggregates.RobustPrice> rankPrices;
    /** The ranking rule: null (today's), 'profit-per-hour', 'profit' or 'soft-liquidity'. */
    public String rankBy;
    /** Which candidate from the top this account is handed (0 the best); NaN is 0, and it is CLAMPED to the last. */
    public double spreadRank = Double.NaN;
    /** The 168-hour typical volume per item (null: none), the basis an order is SIZED on. */
    public Map<Integer, ? extends Number> typicalVolumes;
    /** {@code options.volumes}: an hour for SIZING only. The bridge never passes it (the hour is the volumes argument). */
    public HourBucket volumes;
    /** The opt-in capture-curve cap (falsified 4 Oct, off by default). */
    public boolean captureCap;
    /** Members world, focus and the buy limit left. */
    public Sizing.ItemGate gate = Sizing.ItemGate.NONE;
    /** The level whose bars apply; null is LOW (today the market tier reads the same bars at every level). */
    public LevelSettings level;
  }

  private static final class Candidate {
    final ItemCatalog.Item item;
    final LatestPrices.Quote p;
    final double predictedProfit;
    final double score;
    final Sizing.Sized sized;
    final boolean limitKnown;
    final long fullSize;

    Candidate(ItemCatalog.Item item, LatestPrices.Quote p, double predictedProfit, double score, Sizing.Sized sized, boolean limitKnown, long fullSize) {
      this.item = item;
      this.p = p;
      this.predictedProfit = predictedProfit;
      this.score = score;
      this.sized = sized;
      this.limitKnown = limitKnown;
      this.fullSize = fullSize;
    }
  }

  // A /latest timestamp as priceAgeMinutes reads it: NaN when the Wiki sent none.
  private static double side(long v) {
    return v == HourBucket.NONE ? Double.NaN : v;
  }

  private static double typicalFor(Map<Integer, ? extends Number> typical, int itemId) {
    Number n = typical == null ? null : typical.get(itemId);
    return n == null ? Double.NaN : n.doubleValue();
  }

  /** windowShareOn: is the "Bigger positions" window share in force (a finite share above 0)? The same test the sizing makes. */
  static boolean windowShareOn(double volumeWindowShare) {
    return JsValues.isFinite(volumeWindowShare) && volumeWindowShare > 0;
  }

  /**
   * computeMarketSuggestion: the best market-wide buy, or null. {@code mapping} is the Wiki /mapping in its own order,
   * {@code latest} the /latest quotes, {@code volumes} the latest Wiki hour (the floor, the fill check and the score read
   * it; null for none).
   */
  public static Pick computeMarketSuggestion(List<ItemCatalog.Item> mapping, LatestPrices latest, HourBucket volumes, Options options) {
    if (mapping == null || latest == null) return null;
    Options o = options == null ? new Options() : options;
    double minProfit = JsValues.isFinite(o.minProfit) && o.minProfit > 0 ? o.minProfit : 0;
    Set<Integer> blocklist = o.blocklist == null ? Collections.emptySet() : o.blocklist;
    Double maxSpend = Sizing.maxSpend(o.maxSpend);
    Double target = Sizing.duration(o.targetDurationMinutes);
    double maxPriceAge = JsValues.isFinite(o.maxPriceAgeMinutes) ? o.maxPriceAgeMinutes : Prices.MAX_PRICE_AGE_MINUTES;
    double volumeShare = JsValues.isFinite(o.maxVolumeShare) ? o.maxVolumeShare : Sizing.volumeShareForDuration(target == null ? Double.NaN : target);
    LevelSettings level = o.level == null ? LevelSettings.LOW : o.level;
    double marginMultiple = o.marginTaxMultiple != null ? o.marginTaxMultiple : level.noHistoryMarginTaxMultiple;
    Sizing.SizingOptions sizing = new Sizing.SizingOptions(o.maxVolumeShare, o.volumeWindowShare, o.captureCap);
    Sizing.ItemGate gate = o.gate == null ? Sizing.ItemGate.NONE : o.gate;
    List<Candidate> candidates = new ArrayList<>();
    for (ItemCatalog.Item item : mapping) {
      if (item == null || blocklist.contains(item.id)) continue;
      // A members-only item cannot be traded on a free-to-play world at all.
      if (gate.membersBlocked(item.id)) continue;
      LatestPrices.Quote p = latest.get(item.id);
      if (p == null || !(p.low > 0) || !(p.high > 0)) continue; // NONE (no price) is Long.MIN_VALUE: not above 0
      VolumeRow row = VolumeRow.of(volumes, item.id);
      long liquidity = VolumeRow.liquidity(row);
      // "Does this item trade at all" is about NOW: the floor reads the latest hour, only the SIZE reads a typical one.
      if (!Gates.liquidityFloorMet(liquidity, target, o.minVolumeInWindow, o.minHourlyVolume, level)) continue;
      if (o.taxFreeOnly && Tax.estimateUnitTax(item.id, p.high) > 0) continue;
      // No track record backs this tier, so a spread nobody has traded on either side within the hour is not ranked.
      Double ageMinutes = Prices.priceAgeMinutes(side(p.highTime), side(p.lowTime), o.now);
      if (ageMinutes != null && ageMinutes > maxPriceAge) continue;
      long tax = Tax.estimateUnitTax(item.id, p.high);
      long net = Js.subtract(Js.subtract(p.high, p.low), tax);
      if (net <= 0) continue;
      // The tier that suggested the blood runes: an edge thinner than the item's own tax is not offered at all.
      if (o.requireMarginOverTax && !Gates.marginClearsTax(net, tax, marginMultiple)) continue;
      // RANK on the steady price, QUOTE the live one -- and clear every bar on BOTH.
      MarketAggregates.RobustPrice r = o.rankPrices == null ? null : o.rankPrices.get(item.id);
      long rankHigh = r != null && r.high > 0 ? r.high : p.high;
      long rankLow = r != null && r.low > 0 ? r.low : p.low;
      long rankTax = Tax.estimateUnitTax(item.id, rankHigh);
      long netRank = Js.subtract(Js.subtract(rankHigh, rankLow), rankTax);
      if (netRank <= 0) continue;
      if (o.requireMarginOverTax && !Gates.marginClearsTax(netRank, rankTax, marginMultiple)) continue;
      Long reading = VolumeRow.reading(row);
      if (Gates.implausibleSpread(net, p.low, reading == null ? Double.NaN : reading, Gates.IMPLAUSIBLE_MARGIN_MULTIPLE)) continue;
      if (Gates.implausibleBuyPrint(p.low, row, Gates.BUY_PRINT_MULTIPLE)) continue;
      // The item's own buy limit when known, across every 4-hour window the pace spans, else the flat cap of 100.
      Long catalogLimit = item.limit();
      boolean limitKnown = catalogLimit != null;
      double limit = limitKnown ? catalogLimit : Double.NaN;
      long fullSize = JsValues.exactLong(Math.max(1, limitKnown
        ? Sizing.limitAllowance(limit, 0, Double.NaN, target == null ? Double.NaN : target, 0) : Sizing.DEFAULT_MARKET_QUANTITY_CAP));
      Long optionsReading = o.volumes == null ? null : VolumeRow.reading(VolumeRow.of(o.volumes, item.id));
      Sizing.Sized sized = Sizing.marketQuantity(item.id, limit, p.low, maxSpend, o.maxStackShare, row, optionsReading,
        typicalFor(o.typicalVolumes, item.id), target, sizing, gate);
      if (sized == null) continue;
      long quantity = sized.quantity;
      // The floor is judged on the more cautious of the live and the steady total; the reasoning quotes the live one.
      double predictedProfit = (double) net * quantity;
      double rankProfit = (double) netRank * quantity;
      if (Math.min(predictedProfit, rankProfit) < minProfit) continue;
      // Once cash or a pace constrains, the best TOTAL reachable within it, log-damped by real liquidity; else per unit.
      boolean constrained = maxSpend != null || target != null;
      double score = (constrained ? rankProfit : netRank) * StrictMath.log(liquidity + 1);
      if ("profit-per-hour".equals(o.rankBy)) {
        double hours = Math.max(Sizing.correctedFillMinutes(Sizing.estimatedFillMinutes(quantity, liquidity, Sizing.VOLUME_WINDOW_MINUTES)) * 2,
          Sizing.FILL_FLOOR_MINUTES) / 60;
        score = rankProfit / hours;
      }
      if ("profit".equals(o.rankBy)) score = rankProfit;
      if ("soft-liquidity".equals(o.rankBy)) score = (constrained ? rankProfit : netRank) * Math.sqrt(StrictMath.log(liquidity + 1));
      if (score <= 0) continue;
      candidates.add(new Candidate(item, p, predictedProfit, score, sized, limitKnown, fullSize));
    }
    if (candidates.isEmpty()) return null;
    candidates.sort((a, b) -> Js.compare(b.score, a.score)); // stable: an equal score keeps the mapping's order
    Candidate c = candidates.get(spreadIndex(o.spreadRank, candidates.size()));
    return pick(c, o, target, volumeShare);
  }

  /**
   * {@code Math.min(Math.max(0, Math.floor(spreadRank) || 0), candidates.length - 1)}: NaN, -0 and anything below 0 are
   * the top pick, a fraction is floored, and a rank past the end CLAMPS to the last candidate rather than answering
   * nothing (a thin hour with two candidates still answers a spread rank of 4).
   */
  static int spreadIndex(double spreadRank, int size) {
    double floored = Math.floor(spreadRank);
    double rank = Double.isNaN(floored) || floored == 0 ? 0 : floored; // (x || 0)
    return (int) Math.min(Math.max(0, rank), size - 1);
  }

  private static Pick pick(Candidate c, Options o, Double target, double volumeShare) {
    ItemCatalog.Item item = c.item;
    Sizing.Sized s = c.sized;
    List<String> notes = new ArrayList<>();
    // fullSize counts EVERY window the pace spans, so it is never quoted as the per-window limit (5 Oct: Ancient essence's
    // 300,000 was told as 3,600,000 per 4 hours on Slow); the total is named beside it only past one window.
    long windows = c.limitKnown ? Js.round(c.fullSize / (double) item.limit()) : 1;
    notes.add(c.limitKnown
      ? "sized to this item's own GE buy limit of " + Js.groupedUs(item.limit()) + " per 4 hours"
        + (windows > 1 ? ", counted over the " + windows + " four-hour windows your trade spans (" + Js.groupedUs(c.fullSize) + " in all)" : "")
      : "capped at " + Js.groupedUs(c.fullSize) + " because this item's GE buy limit is unknown");
    if (s.cashLimited) notes.add("capped to what your current cash stack can afford");
    if (s.durationLimited) notes.add("capped to fit an estimated ~" + JsValues.text(target) + "-minute trade");
    if (s.limitLimited) notes.add("capped to what EVI has seen left of this item's GE buy limit, which is all that can fill before the limit resets in 4 hours -- a bigger offer would sit part-filled until then");
    if (s.stackLimited) notes.add("capped so this one trade commits at most " + JsValues.text(JsValues.jsRound(o.maxStackShare * 100)) + "% of your cash stack");
    // Worded from whichever cap actually bound (the maintainer, 7 Oct 2026): under "Bigger positions" the WINDOW share
    // replaces the per-hour one, so it is the one named.
    if (s.shareLimited) notes.add(windowShareOn(o.volumeWindowShare)
      ? "capped to " + JsValues.text(JsValues.jsRound(o.volumeWindowShare * 100))
        + "% of what this item trades over your whole trade window, so the order isn't larger than the market absorbs"
      : "capped to " + JsValues.text(JsValues.jsRound(volumeShare * 100))
        + "% of what this item trades in a typical hour, so the order isn't larger than the market absorbs"
        + (volumeShare > Sizing.DEFAULT_MAX_VOLUME_SHARE ? " over your " + windowWords(target) + " trade window" : ""));
    Pick out = new Pick(item.id, item.name, "buy", s.quantity, c.p.low, c.p.high, "market");
    out.reasoning = "Market-wide pick -- you have no flip history for this item yet. Current margin after tax is ~" + JsValues.gp(c.predictedProfit)
      + " gp at quantity " + s.quantity + (notes.isEmpty() ? "" : " (" + String.join("; ", notes) + ")") + " (buy near " + Js.groupedUs(c.p.low)
      + " gp, sell near " + Js.groupedUs(c.p.high) + " gp). Verify liquidity and news yourself before committing capital; this ranking has no track record behind it.";
    return out;
  }

  /**
   * {@code targetDurationMinutes >= 120 ? Math.round(t / 60) + '-hour' : t + '-minute'} -- and with NO pace (an explicit
   * per-hour share above 10% and no duration) the JS prints "undefined-minute", which is kept as it is: the sentence is
   * the bridge's, and changing it belongs in the JS first.
   */
  private static String windowWords(Double target) {
    if (target == null) return "undefined-minute";
    return target >= 120 ? JsValues.text(JsValues.jsRound(target / 60)) + "-hour" : JsValues.text(target) + "-minute";
  }

  // ------------------------------------------------------------------------------------------- the request's rankers

  /**
   * One request's market-tier rankers, as server.mjs builds them inside GET /api/suggestion from its {@code marketOpts}
   * (cash, pace, the stack share, tax-free only, the steady prices, the ranking rule, the sizing spread and the gates):
   * <ul>
   *   <li>{@link #rank}: the main pick, at the request's own minimum and cash, handed this account's {@code spreadRank};</li>
   *   <li>{@link #rankAt}: {@code marketRankAt(bl, spend, mp)} -- the Auto step-down, the reachable probe and the further
   *       positions, at a budget and a minimum of their own, with the SAME spread rank.</li>
   * </ul>
   * Until 8 Oct the second carried no spread rank (the 5 Oct wiring gap: above 10m most picks are the step-down's, and
   * 60-68% of accounts shared one); the maintainer approved closing it, in the bridge first. The bridge's dead
   * {@code marketAt}/{@code rankAtMinimum} closures were deleted the same day. The scanner-pushed shortlist the bridge may
   * prefer inside marketRankAt has no source in the self-contained plugin, so this is always the catalogue ranking.
   */
  public static final class Ranking {
    private final List<ItemCatalog.Item> mapping;
    private final LatestPrices latest;
    private final HourBucket volumes;
    private final Double maxSpend;
    private final double spreadRank;
    private final Options shared;

    /**
     * @param shared the request's {@code marketOpts}: everything but the minimum, the blocklist, the cash and the spread
     *               rank, which each call sets (its own blocklist, minimum and cash fields are ignored)
     * @param maxSpend the request's cash cap ({@link QueryValues#maxSpendFromQuery}): null unknown, 0 carrying nothing
     * @param spreadRank {@link SpreadRank#spreadRankFor} for the asking account
     */
    public Ranking(List<ItemCatalog.Item> mapping, LatestPrices latest, HourBucket volumes, Options shared, Double maxSpend, double spreadRank) {
      this.mapping = mapping;
      this.latest = latest;
      this.volumes = volumes;
      this.shared = shared;
      this.maxSpend = maxSpend;
      this.spreadRank = spreadRank;
    }

    private Options with(Set<Integer> blocklist, Double spend, double minProfit, double spread) {
      Options o = new Options();
      o.minProfit = minProfit;
      o.blocklist = blocklist;
      o.maxSpend = spend == null ? Double.NaN : spend;
      o.spreadRank = spread;
      o.targetDurationMinutes = shared.targetDurationMinutes;
      o.now = shared.now;
      o.maxPriceAgeMinutes = shared.maxPriceAgeMinutes;
      o.maxVolumeShare = shared.maxVolumeShare;
      o.volumeWindowShare = shared.volumeWindowShare;
      o.minVolumeInWindow = shared.minVolumeInWindow;
      o.minHourlyVolume = shared.minHourlyVolume;
      o.maxStackShare = shared.maxStackShare;
      o.taxFreeOnly = shared.taxFreeOnly;
      o.requireMarginOverTax = shared.requireMarginOverTax;
      o.marginTaxMultiple = shared.marginTaxMultiple;
      o.rankPrices = shared.rankPrices;
      o.rankBy = shared.rankBy;
      o.typicalVolumes = shared.typicalVolumes;
      o.volumes = shared.volumes;
      o.captureCap = shared.captureCap;
      o.gate = shared.gate;
      o.level = shared.level;
      return o;
    }

    /** server.mjs {@code rank(bl)}: the request's minimum and cash, and this account's spread rank. */
    public Pick rank(Set<Integer> blocklist, double minProfit) {
      return computeMarketSuggestion(mapping, latest, volumes, with(blocklist, maxSpend, minProfit, spreadRank));
    }

    /**
     * server.mjs {@code marketRankAt(bl, spend, mp)}: a budget and a minimum of its own, and the SAME spread rank as
     * {@link #rank} (8 Oct fix 2: the Auto step-down, the reachable probe and further positions all carry it).
     */
    public Pick rankAt(Set<Integer> blocklist, Double spend, double minProfit) {
      return computeMarketSuggestion(mapping, latest, volumes, with(blocklist, spend, minProfit, spreadRank));
    }

    /** {@link #rank} as a pick chain's tier. */
    public PickChain.Rank ranked(double minProfit) {
      return bl -> rank(bl, minProfit);
    }

    /** {@link #rankAt} as a pick chain's tier. */
    public PickChain.Rank rankedAt(Double spend, double minProfit) {
      return bl -> rankAt(bl, spend, minProfit);
    }
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Js;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * THE ENGINE HAS TWO DIFFERENT MEDIANS, and swapping them changes answers (bridge-inventory risk 7):
 * <ul>
 *   <li>{@link #average}: suggestions.mjs's {@code median()}, used by {@code personalHistory} for a player's typical
 *       quantity and hold. An even count AVERAGES the middle pair, so a typical size can be x.5 and is then rounded
 *       half-up.</li>
 *   <li>{@link #upper}: the robust price's, the typical volume's and the thin-market's
 *       {@code s[Math.floor(s.length / 2)]}. An even count takes the UPPER middle, never an average, so the answer is
 *       always one of the readings (the market layer's {@code LongList.upperMedian} is the same rule).</li>
 * </ul>
 * Both sort with the JS comparator {@code (a, b) => a - b} (a stable sort that treats -0 and 0 as equal).
 */
public final class Medians {
  private Medians() {}

  /** median(): null for no values; the middle value, or the mean of the middle two for an even count. */
  public static Double average(List<Double> values) {
    if (values.isEmpty()) return null;
    List<Double> s = new ArrayList<>(values);
    s.sort((a, b) -> Js.compare(a, b));
    int mid = s.size() / 2;
    return s.size() % 2 == 1 ? s.get(mid) : (s.get(mid - 1) + s.get(mid)) / 2;
  }

  /** {@code s[Math.floor(s.length / 2)]} of the sorted values; null for none. */
  public static Long upper(long[] values) {
    if (values.length == 0) return null;
    long[] s = values.clone();
    Arrays.sort(s);
    return s[s.length / 2];
  }
}

package com.evi.live.engine;

/**
 * One suggestion as the tiers build it and the checks after them annotate it: the object {@code computeSuggestion},
 * {@code computeHoldingSuggestion} and {@code computeInventorySuggestion} return in bridge/suggestions.mjs, which
 * {@code pickWithForecast} and the server's enrichment then MUTATE (reasoning grows, a sell-support reading, a demotion,
 * a verdict, the headline profit are attached). It is mutable for exactly that reason: the JS order of those mutations is
 * part of the behaviour (a warning goes FIRST in the reasoning, a demotion note LAST), and a copy-on-write object would
 * hide which step wrote what.
 *
 * <p>Every field the JS leaves undefined is null here, and a null field is simply absent from the answer.
 *
 * <p>GP is a {@code long} everywhere a price or a price times a quantity is held, with ONE deliberate exception:
 * {@link #netIfSoldNow} is the double JS {@code Math.round} left. Since the maintainer's 7 Oct fix the holding tier folds minus
 * zero into zero, and the verdict prints any -0 handed to it as "0" (see {@link Verdict}); the field stays a double so a
 * vector carrying -0 still reaches it as the JS sees it. It is always a whole number.
 */
public final class Pick {
  public final int itemId;
  public final String name;
  /** "buy" or "sell". */
  public final String action;
  public final long quantity;
  public final long buyPrice;
  public final long sellPrice;
  /** "personal", "holding" or "inventory" in the tiers ported so far ("market" and "scanner" later). */
  public final String source;

  /** The personal tier's flip count on the item (so the verdict can say "your N flips here"). */
  public Integer trades;
  public String reasoning;
  /** The buy offer a holding came from, for the personal-use button; null when there is none. */
  public String buyId;
  /** Holding tier: never estimated, null when the cost basis is unknown. */
  public Long breakEvenPrice;
  public Long lossIfSoldNow;
  /** Holding tier: what selling now nets after tax, a whole number (never -0 from the holding tier, see the class note); null when unknown. */
  public Double netIfSoldNow;
  /** Holding tier: the position's sell listing ended while EVI was not watching (null for every other holding). */
  public com.evi.live.journal.FifoMatcher.EndedUnseenMark endedUnseen;
  /** Set by the caller when a holding was reconstructed from the journal rather than watched this session. */
  public Boolean persisted;

  /** The sell-support reading attached by the pick chain, whether or not anything was wrong with it. */
  public SellSupport.Detail sellSupport;
  /** Set when this pick is shown only because nothing better passed the sell-support check. */
  public Boolean demoted;
  /** An opaque forecast handed in by the forecast hook (off by default; plan decision 13). */
  public Object forecast;
  public Object fillOutlook;

  // ------------------------------------------------------------------------------------- the enrichment (Verdict.enrich)
  public Verdict.Result verdict;
  public Long quotedProfit;
  /** The headline figure; null for idle stock, which has no cost basis to state a profit against. */
  public Long expectedProfit;
  /** The fill-history reading the thin-market index carried, when there was one. */
  public Integer fillHistoryHoursTraded;
  public Integer fillHistoryHours;
  /** Set by the Auto step-down: the minimum this pick fell below. */
  public Double belowUsualBar;

  public Pick(int itemId, String name, String action, long quantity, long buyPrice, long sellPrice, String source) {
    this.itemId = itemId;
    this.name = name;
    this.action = action;
    this.quantity = quantity;
    this.buyPrice = buyPrice;
    this.sellPrice = sellPrice;
    this.source = source;
  }

  public boolean isBuy() {
    return "buy".equals(action);
  }
}

package com.evi.live.engine;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;

/**
 * The checks every BUY candidate passes after its tier ranked it (bridge/suggestions.mjs {@code pickWithForecast}):
 * forecast (opt-in), margin cushion (opt-in), correlation with what is already held, and sell support, with up to
 * {@code maxAttempts} candidates tried. A failed check puts the item in the blocklist and asks the tier again. Pure.
 *
 * <p>SYNCHRONOUS BY CONSTRUCTION. On 5 Oct the JS {@code rank} became async on three paths (the Auto step-down, the
 * reachable probe, the additional positions) and was not awaited, so the candidate was a Promise, its {@code action}
 * undefined, and every check below was skipped for those paths. Here {@link Rank#rank} returns the candidate itself and
 * every hook returns its answer: there is no future to forget to wait for, on any path.
 *
 * <p>What each outcome means, as in the JS:
 * <ul>
 *   <li>not a buy (a holding or idle-stock reminder): returned at once, unchecked;</li>
 *   <li>forecast: its sentence and the policy note are appended; it may DROP the candidate only when
 *       {@link #FORECAST_MAY_DROP_CANDIDATES} (false: measured to call direction backwards);</li>
 *   <li>cushion or correlation blocks: the item is blocklisted and the next candidate is tried (correlation records why);</li>
 *   <li>sell support BLOCKED (thinner than its own tax at the price buyers pay): HELD BACK, with its warning first in the
 *       reasoning -- never shown, however large the quantity makes it look (27 Sept, 172,266 blood runes);</li>
 *   <li>sell support WARNED: DEMOTED -- set aside for the next candidate, and shown, flagged, only if nothing passes.</li>
 * </ul>
 * The blocklist is the CALLER's set and is mutated, exactly as the JS mutates the Set it is handed: several call sites
 * share one, so the order of calls changes what the later ones see, and a port that copied it would change answers.
 *
 * <p>Plan decision 13 (drop the opt-in cushion and forecast in the self-contained build): the hooks are kept and are OFF
 * by default -- a null hook is never consulted.
 */
public final class PickChain {
  private PickChain() {}

  /** FORECAST_MAY_DROP_CANDIDATES: the forecast is shown but removes nothing (calibration found it inverted). */
  public static final boolean FORECAST_MAY_DROP_CANDIDATES = false;
  /** UNFAVORABLE_FORECAST_CONFIDENCE: what "meaningfully unfavourable" would need, were dropping allowed. */
  public static final double UNFAVORABLE_FORECAST_CONFIDENCE = 55;

  /** A tier's ranking against the current blocklist. Returns the candidate itself -- never a future. */
  public interface Rank {
    Pick rank(Set<Integer> blocklist);
  }

  /** What the forecast hook hands back: the direction and confidence, and the sentence the caller built for it. */
  public static final class Forecast {
    public final Object detail;
    public final int dir;
    public final double confidence;
    /** The fill-outlook sentence for this forecast (null for none). */
    public final String outlookSentence;
    public final Object outlook;

    public Forecast(Object detail, int dir, double confidence, String outlookSentence, Object outlook) {
      this.detail = detail;
      this.dir = dir;
      this.confidence = confidence;
      this.outlookSentence = outlookSentence;
      this.outlook = outlook;
    }
  }

  public interface ForecastHook {
    Forecast forecastFor(int itemId);
  }

  /** A cushion or correlation answer: blocked or not, and a note. */
  public static final class Check {
    public final boolean blocked;
    public final String note;

    public Check(boolean blocked, String note) {
      this.blocked = blocked;
      this.note = note;
    }
  }

  public interface CheckHook {
    Check check(Pick candidate);
  }

  public interface SupportHook {
    SellSupport.Result supportFor(Pick candidate);
  }

  /**
   * The bridge's sell-support hook FAILS OPEN: server.mjs's supportForSuggestion wraps the reading and the judgement in
   * {@code try { ... } catch { return null; }}, so one bad series means "no reading" and the candidate goes on, never a failed
   * poll. {@link #pick} itself propagates a hook's exception, exactly as pickWithForecast does, so the catch belongs to
   * whoever wires the hook: wrap the reading-and-judge part ({@link SellSupport#reading} then {@link SellSupport#judge}) in
   * this. The crash check runs OUTSIDE that try in the bridge and must stay outside it here.
   *
   * <p>WHAT IT ABSORBS, pinned by TierIntentTest.aBrokenSupportReadingFailsOpen: every {@link Exception} -- whatever
   * the reading can throw (an ArithmeticException from a GP figure past a long, a NullPointerException from a missing
   * field, a parse error), and a checked exception that reached it undeclared, since the JS {@code catch} has no notion
   * of a type and absorbs anything a reading throws. What it PROPAGATES: an {@link Error} (an AssertionError, a stack
   * overflow, running out of memory) is a fault in the JVM or a test, never "no reading", and swallowing it would turn a
   * broken build green. The hook's answer otherwise passes through untouched: the same Result, or null.
   */
  public static SupportHook failOpen(SupportHook hook) {
    if (hook == null) return null;
    return candidate -> {
      try {
        return hook.supportFor(candidate);
      } catch (Exception e) {
        return null;
      }
    };
  }

  /** One candidate held back for a stated reason: the whole pick (sell support), or an item and why (correlation). */
  public static final class Blocked {
    public final Pick pick;
    public final int itemId;
    public final String reason;

    Blocked(Pick pick) {
      this.pick = pick;
      this.itemId = pick.itemId;
      this.reason = null;
    }

    Blocked(int itemId, String reason) {
      this.pick = null;
      this.itemId = itemId;
      this.reason = reason;
    }
  }

  /** The chain's inputs. Only {@link #rank} and {@link #blocklist} are required; every hook is off when null. */
  public static final class Options {
    public Rank rank;
    public ForecastHook forecastFor;
    /** 'warn' or 'skip'. */
    public String policy;
    /** The forecast horizon; null or empty switches the forecast off. */
    public String horizon;
    public CheckHook cushionFor;
    public boolean requireCushion;
    public CheckHook correlationFor;
    public SupportHook supportFor;
    public Set<Integer> blocklist;
    public int maxAttempts = 3;
    public Consumer<List<Blocked>> onBlocked;
    public Consumer<Pick> onDemoted;
  }

  /** decideForecast: 'keep' or 'retry'. Always 'keep' while {@link #FORECAST_MAY_DROP_CANDIDATES} is false. */
  public static String decideForecast(Forecast forecast, String policy) {
    if (forecast == null) return "keep";
    if (!FORECAST_MAY_DROP_CANDIDATES) return "keep";
    if ("skip".equals(policy) && forecast.dir == -1 && forecast.confidence >= UNFAVORABLE_FORECAST_CONFIDENCE) return "retry";
    return "keep";
  }

  /** forecastPolicyNote: the plain statement that "skip" is inactive, so a setting never silently does nothing. */
  public static String forecastPolicyNote(String policy) {
    return "skip".equals(policy) && !FORECAST_MAY_DROP_CANDIDATES
      ? "Note: \"skip on an unfavourable forecast\" is currently inactive. Measured against 90 days of price history, this forecast's direction calls were wrong more often than chance, and skipping on them threw away better trades than it avoided -- so the forecast is shown but no longer removes a candidate."
      : null;
  }

  /** pickWithForecast: the first candidate that passes every check, the best demoted one, or null. */
  public static Pick pick(Options o) {
    Set<Integer> blocklist = o.blocklist;
    List<Blocked> blocked = new ArrayList<>();
    List<Pick> demoted = new ArrayList<>();
    for (int attempt = 0; attempt < o.maxAttempts; attempt++) {
      Pick candidate = o.rank.rank(blocklist);
      if (candidate == null) break;
      if (!candidate.isBuy()) return candidate;
      if (o.forecastFor != null && o.horizon != null && !o.horizon.isEmpty()) {
        Forecast forecast = o.forecastFor.forecastFor(candidate.itemId);
        if (forecast != null) {
          candidate.forecast = forecast.detail;
          candidate.fillOutlook = forecast.outlook;
          if (forecast.outlookSentence != null && !forecast.outlookSentence.isEmpty()) candidate.reasoning += " " + forecast.outlookSentence;
          String note = forecastPolicyNote(o.policy);
          if (note != null) candidate.reasoning += " " + note;
          if ("retry".equals(decideForecast(forecast, o.policy))) {
            blocklist.add(candidate.itemId);
            continue;
          }
        }
      }
      if (o.cushionFor != null && o.requireCushion) {
        Check cushion = o.cushionFor.check(candidate);
        if (cushion != null) {
          if (cushion.blocked) {
            blocklist.add(candidate.itemId);
            continue;
          }
          if (cushion.note != null && !cushion.note.isEmpty()) candidate.reasoning += " " + cushion.note;
        }
      }
      // Several slots in items that move together is one position wearing several hats. A null answer (no archive,
      // too little shared history, nothing held) never blocks anything.
      if (o.correlationFor != null) {
        Check correlated = o.correlationFor.check(candidate);
        if (correlated != null && correlated.blocked) {
          blocked.add(new Blocked(candidate.itemId, correlated.note));
          blocklist.add(candidate.itemId);
          continue;
        }
      }
      // Last: the one check that costs a fetch in the bridge.
      if (o.supportFor != null) {
        SellSupport.Result support = o.supportFor.supportFor(candidate);
        if (support != null && support.blocked) {
          candidate.reasoning = joinTrim(support.warning, candidate.reasoning);
          candidate.sellSupport = support.detail;
          blocked.add(new Blocked(candidate));
          blocklist.add(candidate.itemId);
          continue;
        }
        if (support != null && support.detail != null) candidate.sellSupport = support.detail;
        if (support != null && support.warning != null && !support.warning.isEmpty()) {
          candidate.reasoning = support.warning + " " + (candidate.reasoning == null ? "" : candidate.reasoning);
          candidate.sellSupport = support.detail;
          demoted.add(candidate);
          if (o.onDemoted != null) o.onDemoted.accept(candidate);
          blocklist.add(candidate.itemId);
          continue;
        }
      }
      return candidate;
    }
    if (!demoted.isEmpty()) {
      Pick best = demoted.get(0);
      best.demoted = true;
      best.reasoning += " No other candidate passed this check right now, which is why this one is shown.";
      return best;
    }
    if (!blocked.isEmpty() && o.onBlocked != null) o.onBlocked.accept(Collections.unmodifiableList(blocked));
    return null;
  }

  // `${warning || ''} ${reasoning || ''}`.trim(), with JS's trim.
  private static String joinTrim(String warning, String reasoning) {
    return JsValues.trim((warning == null ? "" : warning) + " " + (reasoning == null ? "" : reasoning));
  }
}

package com.evi.live.engine;

/**
 * Two small server.mjs rules every tier's answer passes through, kept out of the orchestration so they can be proven on
 * their own (bridge/server.mjs {@code autoMinProfit}, {@code headlineProfit}). Pure.
 */
public final class Policy {
  private Policy() {}

  /** AUTO_MIN_PROFIT: the floor against absurdity when the player chose no minimum. */
  public static final double AUTO_MIN_PROFIT = 500;
  /** AUTO_STACK_SHARE: Auto's floor is also 0.1% of the cash stack (28 Sept: 89m offered 500 gp trades). */
  public static final double AUTO_STACK_SHARE = 0.001;
  /**
   * BIGGER_POSITIONS (server.mjs), "Position sizing = Bigger positions" ({@code sizing=bigger}): the market tier's hourly
   * floor becomes a per-WINDOW floor of 24 units, and every tier's per-hour volume cap becomes 10% of what trades over the
   * whole window. The SIZING half only: the constant carries no ranking since 4 Oct ({@link LevelSettings#marketRankBy}).
   */
  public static final double BIGGER_POSITIONS_MIN_VOLUME_IN_WINDOW = 24;
  public static final double BIGGER_POSITIONS_WINDOW_SHARE = 0.10;

  /**
   * autoMinProfit: {@code max(500, Math.round(cash x 0.1%))}, or 500 for an unknown or empty stack. Under Auto this is a
   * PREFERENCE, not a gate (the step-down answers below it); an explicit minimum is never raised.
   */
  public static double autoMinProfit(double cash) {
    if (!JsValues.isFinite(cash) || cash <= 0) return AUTO_MIN_PROFIT;
    return Math.max(AUTO_MIN_PROFIT, JsValues.jsRound(cash * AUTO_STACK_SHARE));
  }

  /**
   * headlineProfit: the more cautious of the quoted spread and what buyers have actually been paying, or the quoted
   * spread alone when nothing was measured (no measurement must never invent a constraint). Null without a quote.
   */
  public static Long headlineProfit(Long quoted, Long supported) {
    if (quoted == null) return null;
    if (supported == null) return quoted;
    return Math.min(quoted, supported);
  }

  /** The same over arbitrary JS numbers (NaN for none), as the bridge function takes them. */
  public static Double headlineProfitOf(double quoted, double supported) {
    if (!JsValues.isFinite(quoted)) return null;
    if (!JsValues.isFinite(supported)) return quoted;
    return Math.min(quoted, supported);
  }
}

package com.evi.live.engine;

import com.evi.live.journal.CostBasis;
import com.evi.live.journal.FifoMatcher;
import com.evi.live.journal.Offer;
import com.evi.live.journal.Tax;
import com.evi.live.market.HourBucket;
import com.evi.live.market.LatestPrices;
import java.util.List;

/**
 * Prices for one item, and what the player paid for it (bridge/suggestions.mjs lookupItemPrice, priceAgeMinutes,
 * withCostBasis, heldCostBasis). Pure; time is passed in.
 *
 * <p>The prompt and the sidebar must never disagree about whether a sale loses GP, so {@link #withCostBasis} uses the
 * same tax ({@link Tax#estimateUnitTax}) and break-even search ({@link Tax#breakEvenSellPrice}) as everything else. A
 * warning, never a block: the price is still offered, with the break-even beside it.
 */
public final class Prices {
  private Prices() {}

  /** MAX_PRICE_AGE_MINUTES: a market-wide pick whose staler side is older than this has no trustworthy spread. */
  public static final double MAX_PRICE_AGE_MINUTES = 60;

  /**
   * lookupItemPrice: the item's live low/high, with no ranking and no filter, or null for an invalid id or an item
   * without both sides priced. Never a fabricated number.
   */
  public static ItemPrice lookupItemPrice(LatestPrices latest, double itemId) {
    if (!JsValues.isFinite(itemId) || itemId <= 0) return null;
    // latestPrices[String(itemId)]: only a whole id in range names an item; 1.5 or 1e21 find nothing.
    if (latest == null || !JsValues.isInteger(itemId) || itemId > Integer.MAX_VALUE) return null;
    LatestPrices.Quote q = latest.get((int) itemId);
    if (q == null || !(priced(q.low) > 0) || !(priced(q.high) > 0)) return null;
    return new ItemPrice((int) itemId, q.low, q.high, null, null, null);
  }

  // A /latest side as the JS sees it: NaN (not > 0) when the Wiki sent none.
  private static double priced(long v) {
    return v == HourBucket.NONE ? Double.NaN : v;
  }

  /**
   * priceAgeMinutes: the age of the STALER side in minutes, or null unless both sides carry a usable timestamp
   * (unix seconds; NaN for none). Fails open.
   */
  public static Double priceAgeMinutes(double highTime, double lowTime, double nowMs) {
    boolean h = JsValues.isFinite(highTime) && highTime > 0, l = JsValues.isFinite(lowTime) && lowTime > 0;
    if (!h || !l) return null;
    return (nowMs / 1000 - Math.min(highTime, lowTime)) / 60;
  }

  /** The same for a {@code /latest} quote (null quote: no answer). */
  public static Double priceAgeMinutes(LatestPrices.Quote q, long nowMs) {
    if (q == null) return null;
    return priceAgeMinutes(priced(q.highTime), priced(q.lowTime), nowMs);
  }

  /**
   * withCostBasis: the open-item price, made aware of what the player paid. Unchanged (the same object) when there is
   * no price or no usable cost. {@code quantity} below 1 or not finite counts as one unit.
   */
  public static ItemPrice withCostBasis(ItemPrice price, double unitCost, double quantity) {
    if (price == null || !JsValues.isFinite(unitCost) || unitCost <= 0) return price;
    Long breakEven = Tax.breakEvenSellPrice(price.itemId, unitCost);
    long tax = Tax.estimateUnitTax(price.itemId, price.sellPrice);
    double netPerUnit = price.sellPrice - unitCost - tax;
    double held = JsValues.isFinite(quantity) && quantity > 0 ? quantity : 1;
    // ROUNDED FIRST, then judged, exactly as the holding tier does it (the maintainer, 7 Oct 2026, fixed in JS first): the
    // SIGNED total is rounded half-up once and only a total still below zero is a loss. A loss under half a gp in total is
    // no loss (never "0 gp"), and an exact .5 tie rounds toward +infinity (-2.5 -> a loss of 2), as the sidebar does.
    double totalNet = JsValues.jsRound(netPerUnit * held);
    return new ItemPrice(price.itemId, price.buyPrice, price.sellPrice, "sell", breakEven,
      totalNet < 0 ? JsValues.exactLong(-totalNet) : null);
  }

  /**
   * heldCostBasis for ONE account ({@link CostBasis#held}, which scopes itself: no account, no answer -- the PORT
   * WARNING). Null when nothing held has a known price. Package-private:
   * production asks {@link AccountView#heldCostBasis}.
   */
  static CostBasis heldCostBasis(List<FifoMatcher.OpenPosition> openPositions, List<Offer> activeOffers, int itemId, String account) {
    return CostBasis.held(openPositions, activeOffers, itemId, account);
  }
}

package com.evi.live.engine;

/**
 * Reading a suggestion request's values the way server.mjs reads its query string ({@code cashFromQuery},
 * {@code maxSpendFromQuery}). Pure. The in-process transport receives the same query text the bridge did, so the
 * same text must mean the same thing.
 *
 * <p>ABSENT IS NOT ZERO (Phase 0's F1 fix, 6 Oct): no cash reading from an identified player means "unknown, no spend
 * cap"; {@code cash=0} means "carrying nothing, afford nothing"; and a poll naming neither an account nor a cash
 * figure describes no player at all and stays at 0, exactly as the bridge keeps it.
 */
public final class QueryValues {
  private QueryValues() {}

  /** cashFromQuery: NaN when the parameter is absent or blank, otherwise {@code Number(raw)}. */
  public static double cashFromQuery(String raw) {
    return raw == null || JsValues.trim(raw).isEmpty() ? Double.NaN : JsValues.toNumber(raw);
  }

  /**
   * The {@code stackShare} parameter (EviLiveConfig.maxTradeShare, a percentage) as server.mjs reads it:
   * {@code Number(searchParams.get('stackShare'))} -- so an ABSENT parameter is Number(null), 0 -- kept only when it is
   * finite and in (0, 100], as a fraction; NaN otherwise (no share cap). Only meaningful beside a known cash stack.
   */
  public static double maxStackShare(String raw) {
    double share = raw == null ? 0 : JsValues.toNumber(raw);
    return JsValues.isFinite(share) && share > 0 && share <= 100 ? share / 100 : Double.NaN;
  }

  /**
   * maxSpendFromQuery: the cash reading when it is a finite value of at least 0; else null (no limit) when the poll
   * names an account; else 0. {@code accountRaw} is the raw parameter (null when absent; empty names no account).
   */
  public static Double maxSpendFromQuery(String cashRaw, String accountRaw) {
    double cash = cashFromQuery(cashRaw);
    if (JsValues.isFinite(cash) && cash >= 0) return cash;
    if (accountRaw == null || accountRaw.isEmpty()) return 0.0;
    return null;
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Offer;
import com.evi.live.journal.Tax;
import com.evi.live.market.LatestPrices;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * "This hasn't sold. Here is what it would take." (bridge/relist.mjs {@code relistAdvice}). Pure; the clock is passed in.
 *
 * <p>EVI never relists anything itself -- it has never placed, edited or cancelled an offer. This produces a sentence for
 * the sidebar; the player decides and clicks. Three rules keep it honest:
 * <ul>
 *   <li>It speaks only when the offer has genuinely sat: a share ({@link #RELIST_AFTER_SHARE}) of the player's own target
 *       duration, never before {@link #MIN_WAIT_MINUTES} -- OR when the market has run away ({@link #DRIFT_SPEAKS_NOW}),
 *       after {@link #DRIFT_MIN_WAIT_MINUTES} so a fresh offer is not second-guessed on the spot.</li>
 *   <li>It never suggests a price below break-even. Below it, it says the loss plainly and stops.</li>
 *   <li>With no cost basis it stays quiet about break-even rather than guessing what was paid.</li>
 * </ul>
 *
 * <p>THE HAND-OFF AT 5%, AND ITS ONE EXCEPTION (2 Oct 2026). Above {@link #PLUGIN_SPEAKS_ABOVE} the plugin's own
 * {@code offerDriftHint} (OFFER_DRIFT_THRESHOLD, also 0.05) speaks, so the early path stays quiet and one offer never draws
 * two sentences. EXCEPT BELOW BREAK-EVEN, where the early path speaks WHATEVER THE GAP: the plugin's hint knows nothing of
 * cost basis and ends "or take the current price", which there locks in a loss, and this is the only sentence that names
 * it. The hole was widest when the news was worst. It was never permanent (the clock speaks regardless after a quarter
 * of the pace), but that is 12 hours on Slow. Merging the two speakers is a Phase 6 behaviour change, not this port's.
 */
public final class Relist {
  private Relist() {}

  /** RELIST_AFTER_SHARE: a quarter of the target duration (the backtest's 6 hours into a 24-hour window). */
  public static final double RELIST_AFTER_SHARE = 0.25;
  public static final double MIN_WAIT_MINUTES = 30;
  /** MIN_GAP: below this the market has barely moved and repricing is noise. */
  public static final double MIN_GAP = 0.005;
  /**
   * DRIFT_SPEAKS_NOW: past 1% over the going rate asks took 6-7 hours and a third never sold (a few hundred sell offers
   * watched from placement). 2% was tried first and stayed silent on the hauberk at 1.59% that prompted it, so 1.5%.
   */
  public static final double DRIFT_SPEAKS_NOW = 0.015;
  /** PLUGIN_SPEAKS_ABOVE: the plugin's own OFFER_DRIFT_THRESHOLD; the early path hands over here, unless below break-even. */
  public static final double PLUGIN_SPEAKS_ABOVE = 0.05;
  /** DRIFT_MIN_WAIT_MINUTES: an ask within 1% of the market typically fills in 6 to 24 minutes. */
  public static final double DRIFT_MIN_WAIT_MINUTES = 15;

  /** An in-progress SELL offer: {itemId, name, price, remaining, firstSeen}. NaN/null for what the caller did not have. */
  public static final class SellOffer {
    public final int itemId;
    public final String name;
    public final double price;
    public final double remaining;
    public final Double firstSeen;

    public SellOffer(int itemId, String name, double price, double remaining, Double firstSeen) {
      this.itemId = itemId;
      this.name = name;
      this.price = price;
      this.remaining = remaining;
      this.firstSeen = firstSeen;
    }
  }

  /**
   * relistAdvice for ONE account (server.mjs): its live sells, priced from /latest (market-wide, named as such) for those
   * items, against ITS OWN cost basis -- all three from the view. {@code targetDurationMinutes}: the player's pace, or 1440
   * when none is set (the bridge's {@code targetDurationMinutes ?? 1440}).
   */
  public static List<AdviceNote> forAccount(AccountView view, LatestPrices marketLatest, double targetDurationMinutes, double now) {
    List<SellOffer> offers = new ArrayList<>();
    for (Offer o : view.liveSells)
      offers.add(new SellOffer(o.itemId, o.name, o.price, Math.max(0, o.total - o.filled), o.firstSeen == null ? null : (double) o.firstSeen));
    return relistAdvice(offers, AdviceNotes.pricesFor(marketLatest, view.liveSells), view.costBasis, targetDurationMinutes, now);
  }

  /**
   * relistAdvice: one note per offer worth mentioning, in offer order. An offer priced at or under the market is left
   * alone (it is simply queueing). {@code prices}: item id to its live price (only {@code sellPrice} is read);
   * {@code costBasis}: item id to what was actually paid per unit, where the journal knows it (null: knows nothing).
   * {@code targetDurationMinutes}: the bridge passes the player's pace, or 1440 when none is set.
   * <p>Package-private on purpose: outside the engine the only way in is {@link #forAccount}, which reads ONE account's
   * records from its {@link AccountView}. The parity harness (same package) drives this record-level core directly.
   */
  static List<AdviceNote> relistAdvice(List<SellOffer> offers, Map<Integer, AdviceNote.Price> prices, Map<Integer, Double> costBasis,
                                              double targetDurationMinutes, double now) {
    double waitMinutes = Math.max(MIN_WAIT_MINUTES, targetDurationMinutes * RELIST_AFTER_SHARE);
    List<AdviceNote> out = new ArrayList<>();
    if (offers == null) return out;
    for (SellOffer offer : offers) {
      if (offer == null || !(offer.price > 0) || offer.firstSeen == null || !JsValues.isFinite(offer.firstSeen)) continue;
      double openMinutes = (now - offer.firstSeen) / 60000;
      AdviceNote.Price p = prices == null ? null : prices.get(offer.itemId);
      Double marketBoxed = p == null ? null : p.sellPrice;
      if (marketBoxed == null || !(marketBoxed > 0)) continue;
      double market = marketBoxed;
      if (offer.price <= market) continue; // at or under the market already: it is simply queueing
      double gap = (offer.price - market) / offer.price;
      if (gap < MIN_GAP) continue;
      boolean pastTheClock = openMinutes >= waitMinutes;
      Double paid = costBasis == null ? null : costBasis.get(offer.itemId);
      Long breakEven = paid != null && paid > 0 ? Tax.breakEvenSellPrice(offer.itemId, paid) : null;
      boolean marketUnderBreakEven = breakEven != null && market < breakEven;
      // Below break-even the early path speaks whatever the gap: the plugin's hint would say "take the current price".
      boolean drifted = openMinutes >= DRIFT_MIN_WAIT_MINUTES
        && gap >= DRIFT_SPEAKS_NOW
        && (gap < PLUGIN_SPEAKS_ABOVE || marketUnderBreakEven);
      if (!pastTheClock && !drifted) continue;
      double hours = openMinutes / 60;
      String rounded = ThinMarket.stripPointZero(JsValues.toFixed(hours, hours < 10 ? 1 : 0)); // "8 hours", not "8.0 hours"
      String waited = hours >= 1 ? rounded + " hour" + ("1".equals(rounded) ? "" : "s") : JsValues.text(JsValues.jsRound(openMinutes)) + " minutes";
      String what = offer.remaining > 0 ? JsValues.localeUs(offer.remaining) + " still unsold" : "unsold";
      // The 6-7h figure is EVI's OWN measurement over one player's sell offers, never "your own asks".
      String head = pastTheClock
        ? what + " after " + waited + "."
        : JsValues.toFixed(gap * 100, 1) + "% over the going rate, " + what + ". Past 1%, asks have taken 6-7h to sell in EVI's measurements, and a third never did.";
      String message;
      double suggestedPrice;
      if (breakEven == null) {
        suggestedPrice = market;
        message = head + " Relisting nearer " + JsValues.localeUs(market) + " would be likelier to sell. EVI doesn't know what you paid, so check it is still a profit.";
      } else if (!marketUnderBreakEven) {
        suggestedPrice = market;
        message = head + " Relisting at market still clears your break-even of " + JsValues.localeUs(breakEven) + " after tax. Your call -- EVI never relists for you.";
      } else {
        // The market is under water. Say so and stop; cutting a loss is the player's decision.
        suggestedPrice = breakEven;
        message = head + " The market is now BELOW your break-even (" + JsValues.localeUs(breakEven) + " after tax), so relisting there would lock in a loss. Hold or cut -- EVI won't choose for you.";
      }
      AdviceNote n = new AdviceNote(offer.itemId);
      n.name = offer.name;
      n.message = message;
      n.offerPrice = offer.price;
      n.marketPrice = market;
      n.level = marketUnderBreakEven ? "warn" : "caution";
      n.label = pastTheClock ? "Not selling" : "Market moved away";
      n.figures = JsValues.localeUs(offer.price) + " asked · " + JsValues.localeUs(market) + " market";
      n.breakEven = breakEven == null ? null : (double) breakEven;
      n.suggestedPrice = suggestedPrice;
      n.openMinutes = JsValues.jsRound(openMinutes);
      n.belowBreakEven = marketUnderBreakEven;
      out.add(n);
    }
    return out;
  }
}

package com.evi.live.engine;

import com.evi.live.journal.BuyLimitUsage;
import com.evi.live.market.ItemCatalog;

/**
 * The three item gates one suggestion request builds (bridge/server.mjs GET /api/suggestion: {@code membersBlocked},
 * {@code focusBlocked} and {@code limitFor}), as the {@link Sizing.ItemGate} every buy tier -- personal, market -- clips its
 * candidates through. Pure: the catalogue, the account's view and the clock are handed in.
 *
 * <p>Each gate exists only when the request asks for it, exactly as the bridge builds them:
 * <ul>
 *   <li>members: only on a FREE world ({@code members=0}); an absent flag (before login) blocks nothing;</li>
 *   <li>focus: only when the player's focus is "bulk" or "gear", judged on the item's own buy limit ({@link Focus#focusAllows});</li>
 *   <li>the buy limit: only for a poll that NAMES an account, and only from THAT account's buys ({@link AccountView#buyLimitUsage}):
 *       what can fill NOW, one window's remainder ({@link Sizing#limitFor}). An unknown limit constrains nothing; a poll with
 *       no account -- the login screen, the five ticks after a login, when the cash may already be read -- has no limit
 *       reading at all, never another account's.</li>
 * </ul>
 */
public final class RequestGates {
  private RequestGates() {}

  /**
   * @param catalog the Wiki /mapping (the bridge's {@code itemIndex()}); needed whenever any gate is in force
   * @param freeToPlayWorld {@code members=0} on the request
   * @param focus the resolved focus ({@link Focus#resolveFocus}): "any", "bulk" or "gear"
   * @param view the asking account's view ({@link AccountView#nobody()} for a poll that names none)
   * @param targetDurationMinutes the normalised pace (null: none), for the limit's allowance across windows
   * @param now the request's clock, epoch ms
   */
  public static Sizing.ItemGate of(ItemCatalog catalog, boolean freeToPlayWorld, String focus, AccountView view, Double targetDurationMinutes, long now) {
    boolean focused = !"any".equals(focus);
    boolean limited = view != null && view.account != null;
    if (!freeToPlayWorld && !focused && !limited) return Sizing.ItemGate.NONE;
    if (catalog == null) throw new IllegalArgumentException("the item gates need the item mapping");
    double target = targetDurationMinutes == null ? Double.NaN : targetDurationMinutes;
    return new Sizing.ItemGate() {
      @Override public boolean membersBlocked(int itemId) {
        return freeToPlayWorld && catalog.membersOnly(itemId);
      }

      @Override public boolean focusBlocked(int itemId) {
        if (!focused) return false;
        Long limit = catalog.limitFor(itemId);
        return !Focus.focusAllows(focus, limit == null ? null : (double) limit);
      }

      @Override public Double limitRemaining(int itemId) {
        if (!limited) return null;
        Long limit = catalog.limitFor(itemId);
        if (limit == null) return null; // unknown limit: no constraint
        BuyLimitUsage u = view.buyLimitUsage(itemId);
        Sizing.Limit l = Sizing.limitFor(limit, u.used, u.windowEndsAt == null ? Double.NaN : u.windowEndsAt, target, now);
        return l == null ? null : l.remaining;
      }
    };
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Profit;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

/**
 * {@link Engine.Response} written as the JSON the bridge's GET /api/suggestion sends ({@code send(200, {...})}), field for
 * field and in the bridge's key order: the body the plugin's {@code SuggestionResponse} parses. Pure; Gson's tree classes
 * only (no Gson instance is created here -- the plugin serialises the tree with the client's injected one).
 *
 * <p>NUMBERS ARE WRITTEN AS THEIR EXACT VALUE. A whole number is written whole (the plugin parses buyPrice, sellPrice,
 * breakEvenPrice and the quantities as {@code long}, and Gson refuses {@code 295.07} for a long, failing the WHOLE
 * response); a fraction (a sell-support average) as the exact decimal of its double, which parses back to the same double.
 * A field the engine left unset is ABSENT, as JSON.stringify drops {@code undefined}; a field the bridge sends as
 * {@code null} is written as null.
 *
 * <p>The golden-transcript parity test (EngineTranscriptTest) compares exactly this output with the bridge's recorded
 * bodies, so the serialiser the plugin will read is the one the parity suite proves.
 */
public final class ResponseJson {
  private ResponseJson() {}

  /** A double: its EXACT value; a non-finite one (never in an answer) as the parity recorder's tag. */
  public static JsonElement number(double d) {
    if (Double.isNaN(d) || Double.isInfinite(d)) {
      JsonObject t = new JsonObject();
      t.addProperty("$num", Double.isNaN(d) ? "NaN" : d > 0 ? "Infinity" : "-Infinity");
      return t;
    }
    return new JsonPrimitive(new BigDecimal(d));
  }

  /** A boxed number: null is JSON null, a Double its exact value, any integral type as written. */
  public static JsonElement number(Number n) {
    if (n == null) return JsonNull.INSTANCE;
    if (n instanceof Double || n instanceof Float) return number(n.doubleValue());
    return new JsonPrimitive(BigDecimal.valueOf(n.longValue()));
  }

  /** Sets {@code k} only when {@code n} is not null (an undefined JS field). */
  public static void put(JsonObject o, String k, Number n) {
    if (n != null) o.add(k, number(n));
  }

  public static void put(JsonObject o, String k, String s) {
    if (s != null) o.addProperty(k, s);
  }

  public static void put(JsonObject o, String k, Boolean b) {
    if (b != null) o.addProperty(k, b);
  }

  /** A JSON value with every number rewritten as its double's exact value (an opaque hook object, e.g. a forecast). */
  public static JsonElement exact(JsonElement e) {
    if (e == null || e.isJsonNull()) return e;
    if (e.isJsonPrimitive()) return e.getAsJsonPrimitive().isNumber() ? number(Double.parseDouble(e.getAsString())) : e;
    if (e.isJsonArray()) {
      JsonArray a = new JsonArray();
      for (JsonElement x : e.getAsJsonArray()) a.add(exact(x));
      return a;
    }
    JsonObject o = new JsonObject();
    for (Map.Entry<String, JsonElement> x : e.getAsJsonObject().entrySet()) o.add(x.getKey(), exact(x.getValue()));
    return o;
  }

  /** A sell-support reading. */
  public static JsonElement detail(SellSupport.Detail d) {
    if (d == null) return JsonNull.INSTANCE;
    JsonObject j = new JsonObject();
    put(j, "units", d.units);
    put(j, "hours", d.hours);
    put(j, "averagePaid", d.averagePaid);
    put(j, "netAtAverage", d.netAtAverage);
    j.addProperty("supported", d.supported);
    put(j, "latestPaid", d.latestPaid);
    put(j, "staleness", d.staleness);
    put(j, "crashing", d.crashing);
    put(j, "thinMarket", d.thinMarket);
    put(j, "thinnerThanTax", d.thinnerThanTax);
    put(j, "belowMinimumAtSupportedPrice", d.belowMinimumAtSupportedPrice);
    put(j, "stale", d.stale);
    return j;
  }

  public static JsonElement verdict(Verdict.Result v) {
    if (v == null) return JsonNull.INSTANCE;
    JsonObject j = new JsonObject();
    j.addProperty("level", v.level);
    j.addProperty("label", v.label);
    JsonArray checks = new JsonArray();
    for (Verdict.Line l : v.checks) {
      JsonObject c = new JsonObject();
      if (l.ok == null) c.add("ok", JsonNull.INSTANCE);
      else c.addProperty("ok", l.ok);
      c.addProperty("text", l.text);
      checks.add(c);
    }
    j.add("checks", checks);
    return j;
  }

  /**
   * A suggestion as the JS object serialises (a null field is absent). An opaque hook object (the forecast, the fill
   * outlook) is written only when it is a JSON tree; the self-contained build ships no forecast hook (plan decision 13).
   */
  public static JsonElement pick(Pick p) {
    if (p == null) return JsonNull.INSTANCE;
    JsonObject j = new JsonObject();
    j.add("itemId", number(p.itemId));
    put(j, "name", p.name);
    put(j, "action", p.action);
    j.add("quantity", number(p.quantity));
    j.add("buyPrice", number(p.buyPrice));
    j.add("sellPrice", number(p.sellPrice));
    put(j, "source", p.source);
    put(j, "trades", p.trades);
    put(j, "reasoning", p.reasoning);
    put(j, "buyId", p.buyId);
    put(j, "breakEvenPrice", p.breakEvenPrice);
    put(j, "lossIfSoldNow", p.lossIfSoldNow);
    put(j, "netIfSoldNow", p.netIfSoldNow);
    if (p.endedUnseen != null) {
      JsonObject u = new JsonObject();
      u.addProperty("sellId", p.endedUnseen.sellId);
      u.add("price", number(p.endedUnseen.price));
      u.add("at", number(p.endedUnseen.at));
      u.add("quantity", number(p.endedUnseen.quantity));
      j.add("endedUnseen", u);
    }
    put(j, "persisted", p.persisted);
    if (p.sellSupport != null) j.add("sellSupport", detail(p.sellSupport));
    put(j, "demoted", p.demoted);
    if (p.forecast instanceof JsonElement) j.add("forecast", exact((JsonElement) p.forecast));
    if (p.fillOutlook instanceof JsonElement) j.add("fillOutlook", exact((JsonElement) p.fillOutlook));
    if (p.fillHistoryHoursTraded != null) {
      JsonObject fh = new JsonObject();
      fh.add("hoursTraded", number(p.fillHistoryHoursTraded));
      fh.add("hours", number(p.fillHistoryHours));
      j.add("fillHistory", fh);
    }
    if (p.verdict != null) j.add("verdict", verdict(p.verdict));
    put(j, "quotedProfit", p.quotedProfit);
    put(j, "expectedProfit", p.expectedProfit);
    put(j, "belowUsualBar", p.belowUsualBar);
    return j;
  }

  /** lookupItemPrice's {itemId, buyPrice, sellPrice}, plus withCostBasis's fields when it added them. */
  public static JsonElement price(ItemPrice p) {
    if (p == null) return JsonNull.INSTANCE;
    JsonObject j = new JsonObject();
    j.add("itemId", number(p.itemId));
    j.add("buyPrice", number(p.buyPrice));
    j.add("sellPrice", number(p.sellPrice));
    if (p.action != null) {
      j.addProperty("action", p.action);
      j.add("breakEvenPrice", number(p.breakEvenPrice));
      j.add("lossIfSoldNow", number(p.lossIfSoldNow));
    }
    return j;
  }

  /** One {@code relistAdvice} entry, the fields the server keeps. */
  public static JsonElement note(AdviceNote n) {
    JsonObject j = new JsonObject();
    j.add("itemId", number(n.itemId));
    put(j, "name", n.name);
    put(j, "message", n.message);
    put(j, "detail", n.detail);
    put(j, "level", n.level);
    put(j, "label", n.label);
    put(j, "figures", n.figures);
    put(j, "offerPrice", n.offerPrice);
    put(j, "marketPrice", n.marketPrice);
    put(j, "breakEven", n.breakEven);
    put(j, "suggestedPrice", n.suggestedPrice);
    put(j, "openMinutes", n.openMinutes);
    put(j, "belowBreakEven", n.belowBreakEven);
    put(j, "lossEach", n.lossEach);
    put(j, "lossTotal", n.lossTotal);
    put(j, "marginPerUnit", n.marginPerUnit);
    put(j, "netAtMarket", n.netAtMarket);
    put(j, "filled", n.filled);
    put(j, "total", n.total);
    put(j, "quantity", n.quantity);
    put(j, "unitCost", n.unitCost);
    put(j, "cost", n.cost);
    put(j, "worth", n.worth);
    put(j, "net", n.net);
    put(j, "holding", n.holding);
    put(j, "buyId", n.buyId);
    return j;
  }

  public static JsonArray notes(List<AdviceNote> list) {
    JsonArray a = new JsonArray();
    for (AdviceNote n : list) a.add(note(n));
    return a;
  }

  /** The sidebar's profit line (server.mjs profitSince): {@code since} is sent as null when the player never reset it. */
  public static JsonElement profit(Profit p) {
    if (p == null) return JsonNull.INSTANCE;
    JsonObject j = new JsonObject();
    j.add("since", number(p.since));
    j.add("gp", number(p.gp));
    j.add("trades", number(p.trades));
    j.add("winners", number(p.winners));
    j.add("losers", number(p.losers));
    j.add("unmatchedSales", number(p.unmatchedSales));
    j.add("openPositions", number(p.openPositions));
    return j;
  }

  /** One {@code heldBack} row: a held-back pick is the whole candidate (as the bridge pushes it), anything else {itemId, reason}. */
  public static JsonElement heldBack(Engine.HeldBack h) {
    if (h.pick != null) return pick(h.pick);
    JsonObject r = new JsonObject();
    r.add("itemId", number(h.itemId));
    put(r, "reason", h.reason);
    return r;
  }

  /** The whole body, in the bridge's key order; a failed request is {@code {error}} (the bridge's 502 body). */
  public static JsonObject response(Engine.Response r) {
    JsonObject j = new JsonObject();
    if (r.error != null) {
      j.addProperty("error", r.error);
      return j;
    }
    j.add("suggestion", pick(r.suggestion));
    JsonArray additional = new JsonArray();
    for (Pick a : r.additional) additional.add(pick(a));
    j.add("additional", additional);
    j.add("openItemPrice", price(r.openItemPrice));
    JsonArray slotPrices = new JsonArray();
    for (ItemPrice p : r.slotPrices) slotPrices.add(price(p));
    j.add("slotPrices", slotPrices);
    JsonArray slotFill = new JsonArray();
    for (Engine.SlotFill f : r.slotFill) {
      JsonObject o = new JsonObject();
      o.add("itemId", number(f.itemId));
      o.add("estimatedFillMinutes", number(f.estimatedFillMinutes));
      o.addProperty("likelyToFillInTime", f.likelyToFillInTime);
      slotFill.add(o);
    }
    j.add("slotFill", slotFill);
    j.add("relistAdvice", notes(r.relistAdvice));
    JsonObject slots = new JsonObject();
    slots.add("free", number(r.slots.free));
    slots.add("collectable", number(r.slots.collectable));
    slots.addProperty("full", r.slots.full);
    slots.addProperty("tight", r.slots.tight);
    slots.add("sellSlotsOwed", number(r.slots.sellSlotsOwed));
    slots.addProperty("buysHeldForExits", r.slots.buysHeldForExits);
    JsonArray positionItems = new JsonArray();
    for (Integer id : r.slots.positionItems) positionItems.add(number(id));
    slots.add("positionItems", positionItems);
    j.add("slots", slots);
    j.add("profit", profit(r.profit));
    if (r.reachable == null) j.add("reachable", JsonNull.INSTANCE);
    else {
      JsonObject o = new JsonObject();
      if (r.reachable.name == null) o.add("name", JsonNull.INSTANCE);
      else o.addProperty("name", r.reachable.name);
      o.add("itemId", number(r.reachable.itemId));
      o.add("profit", number(r.reachable.profit));
      o.add("atMinimum", number(r.reachable.atMinimum));
      j.add("reachable", o);
    }
    if (r.fellThroughFromHistory == null) j.add("fellThroughFromHistory", JsonNull.INSTANCE);
    else {
      JsonObject o = new JsonObject();
      put(o, "name", r.fellThroughFromHistory.name); // {name: undefined} is {} in JSON
      j.add("fellThroughFromHistory", o);
    }
    JsonArray heldBack = new JsonArray();
    for (Engine.HeldBack h : r.heldBack) heldBack.add(heldBack(h));
    j.add("heldBack", heldBack);
    return j;
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Offer;
import com.evi.live.market.HourBucket;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.regex.Pattern;

/**
 * The Phase 4 readings that sit around a buy pick in server.mjs's GET /api/suggestion, as pure functions the orchestration
 * (Engine.decide, not ported yet) and the test composer call in the bridge's order:
 * <ol>
 *   <li>{@link #precheck}: the first two readings of {@code supportForSuggestion} -- a pick CRASHING right now is demoted
 *       with the crash alert as its warning, before anything else (its recent average says nothing about where it is
 *       heading); then a pick whose price may never come back on a thin market ({@link ThinMarket}) is demoted with that
 *       note. They run BEFORE the sell-support reading, and the crash check runs OUTSIDE the fail-open try in the bridge
 *       (see {@link PickChain#failOpen}), so its owner must call it outside that wrapper too.</li>
 *   <li>{@link #fillSentence}: after the pick, the player's own fill record for an offer this size ({@link FillModel}).</li>
 *   <li>{@link #withThinContext}: the fill-history figures stated (not warned) for whichever buy pick survived, unless a
 *       warning already said it.</li>
 * </ol>
 * Neither reading ever BLOCKS a pick: a demoted pick is still shown, flagged, if nothing better passes. Absent data means
 * no reading (an archive under {@link ThinMarket#MIN_HOURS}, no crash baseline, a thin fill band), never a guess.
 *
 * <p>CORRELATION: see {@link AdviceNotes} -- not ported, a documented seam on {@link PickChain.Options#correlationFor}.
 */
public final class SafetyChecks {
  private SafetyChecks() {}

  /**
   * The crash and thin-market readings for a candidate, or null when neither speaks (the sell-support reading then
   * runs). {@code crashing}: the crash watch's {@code isCrashing(candidate.itemId)} (null: not crashing, or no watch);
   * {@code thin}: the thin-market index, or null when the archive is too short to have one.
   */
  public static SellSupport.Result precheck(Pick candidate, CrashWatch.Crash crashing, ThinMarket.Index thin, Double targetDurationMinutes) {
    if (crashing != null) {
      SellSupport.Detail d = new SellSupport.Detail(null, null, null, null, false, null, null);
      d.crashing = true;
      return new SellSupport.Result(false, "Warning: " + CrashWatch.crashMessage(crashing, candidate.name, null), d);
    }
    if (thin != null) {
      String note = ThinMarket.note(thin.get(candidate.itemId), candidate.name, (double) ThinMarket.windowFor(targetDurationMinutes),
        (double) candidate.quantity, (double) thin.hours);
      if (note != null) {
        SellSupport.Detail d = new SellSupport.Detail(null, null, null, null, false, null, null);
        d.thinMarket = true;
        return new SellSupport.Result(false, note, d);
      }
    }
    return null;
  }

  /**
   * The offers the player fill model learns from: every journal offer watched from placement ({@code knownStart} and a
   * {@code firstSeen}), in the journal's order. Empty: no model at all.
   *
   * <p>EVERY ACCOUNT'S OFFERS, DELIBERATELY -- the one place the advice and safety code reads past the poll's
   * {@link AccountView}, and the parameter is named for it. server.mjs {@code playerFillModel} builds from
   * {@code store.offers} unscoped (an item fills the same whoever placed the offer), and the port keeps parity: pinned by
   * tier-safety-fill-sentence, where another account's sixteen fills give the sentence. Pass {@code store.offers()} here,
   * never a view's offers.
   */
  public static List<Offer> watchedOffers(Collection<Offer> allAccountsJournalOffers) {
    List<Offer> out = new ArrayList<>();
    for (Offer o : allAccountsJournalOffers) if (o.knownStart && o.firstSeen != null) out.add(o);
    return out;
  }

  /** The archive read the fill model needs: from an hour before the earliest watched offer, in seconds. */
  public static double fillModelFrom(List<Offer> watched) {
    double min = Double.POSITIVE_INFINITY;
    for (Offer o : watched) min = Math.min(min, o.firstSeen);
    return Math.floor(min / 1000) - 3600;
  }

  /**
   * The fill sentence for a BUY pick: {@code (reasoning || '') + ' ' + sentence} when the player's own record has one,
   * the reasoning unchanged otherwise. {@code volumes}: the pick's row of the latest hour; the window is the player's pace,
   * or a day without one.
   */
  public static String fillSentence(String reasoning, FillModel.Model model, Pick pick, VolumeRow volumes, Double targetDurationMinutes) {
    double window = targetDurationMinutes != null ? targetDurationMinutes : 1440;
    String sentence = FillModel.fillChanceSentence(FillModel.fillChance(model, pick.quantity, volumes, window), window);
    return sentence == null ? reasoning : (reasoning == null ? "" : reasoning) + " " + sentence;
  }

  private static final Pattern ALREADY_SAID = Pattern.compile("barely trades|did not trade at all|Fill history:");

  /**
   * The fill-history statement for whichever buy pick survived: appended once, never when a warning (or an earlier
   * statement) already carries the figures. {@code stats}: the pick's thin-market reading (null: none -- nothing appended).
   */
  public static String withThinContext(String reasoning, ThinMarket.Stats stats, Pick pick, Double targetDurationMinutes) {
    if (stats == null) return reasoning;
    String context = ThinMarket.context(stats, (double) ThinMarket.windowFor(targetDurationMinutes), (double) pick.quantity);
    String r = reasoning == null ? "" : reasoning;
    if (context == null || ALREADY_SAID.matcher(r).find()) return reasoning;
    return (r.isEmpty() ? "" : r + " ") + context;
  }

  /** The thin-market index the bridge builds: null when fewer than {@link ThinMarket#MIN_HOURS} hours are archived. */
  public static ThinMarket.Index thinIndex(List<HourBucket> fortnight) {
    return fortnight != null && fortnight.size() >= ThinMarket.MIN_HOURS ? ThinMarket.build(fortnight) : null;
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Offer;
import com.evi.live.journal.Tax;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * "The price you are asking does not cover what you paid." -- for a SELL offer already standing (bridge/sellAdvice.mjs
 * {@code sellAdvice}). Pure.
 *
 * <p>WHY: in a week of one player's Copilot log, five of six losing flips lost to the Grand Exchange TAX rather than to the
 * market -- a Light ballista sold 0.1% above cost and still lost 100,160 gp. Deliberately narrow: {@link Relist} speaks
 * about an ask ABOVE the market; this about an ask below the seller's own break-even, which can be true of an offer filling
 * perfectly well. It is about the player's own cost, never a market view; with no cost basis it says nothing; it warns
 * and never cancels, edits or re-prices.
 */
public final class SellAdvice {
  private SellAdvice() {}

  /** MIN_LOSS_SHARE: below this, relative to what the stock cost, the "loss" is tax rounding, not a decision. */
  public static final double MIN_LOSS_SHARE = 0.001;

  /** A live SELL offer: {itemId, name, price, remaining}; NaN for what the caller did not have. */
  public static final class SellOffer {
    public final int itemId;
    public final String name;
    public final double price;
    public final double remaining;

    public SellOffer(int itemId, String name, double price, double remaining) {
      this.itemId = itemId;
      this.name = name;
      this.price = price;
      this.remaining = remaining;
    }
  }

  /**
   * sellAdvice for ONE account (server.mjs): its live sells, each against ITS OWN cost basis -- both read from the view, so
   * another account's lot can never become this account's break-even (the 7 Oct M12 widening: one account selling stock
   * EVI never saw it buy, priced against another account's lot of the same item).
   */
  public static List<AdviceNote> forAccount(AccountView view) {
    List<SellOffer> offers = new ArrayList<>();
    for (Offer o : view.liveSells) offers.add(new SellOffer(o.itemId, o.name, o.price, Math.max(0, o.total - o.filled)));
    return sellAdvice(offers, view.costBasis);
  }

  /**
   * sellAdvice: one 'Below break-even' note per offer worth mentioning, in offer order.
   * <p>Package-private on purpose: outside the engine the only way in is {@link #forAccount}, which reads ONE account's
   * records from its {@link AccountView}. The parity harness (same package) drives this record-level core directly.
   */
  static List<AdviceNote> sellAdvice(List<SellOffer> offers, Map<Integer, Double> costBasis) {
    List<AdviceNote> out = new ArrayList<>();
    if (offers == null) return out;
    for (SellOffer offer : offers) {
      if (offer == null || !(offer.price > 0)) continue;
      Double remaining = JsValues.isFinite(offer.remaining) && offer.remaining > 0 ? offer.remaining : null;
      Double paid = costBasis == null ? null : costBasis.get(offer.itemId);
      if (paid == null || !(paid > 0)) continue; // no cost basis: nothing honest to say
      Long breakEven = Tax.breakEvenSellPrice(offer.itemId, paid);
      if (breakEven == null || !(breakEven > 0) || offer.price >= breakEven) continue;
      // What the ask actually returns per unit after tax, against what the unit cost.
      double netEach = offer.price - Tax.estimateUnitTax(offer.itemId, offer.price);
      double lossEach = paid - netEach;
      if (!(lossEach > 0) || lossEach / paid < MIN_LOSS_SHARE) continue;
      double units = remaining != null ? remaining : 1;
      String name = offer.name != null && !offer.name.isEmpty() ? offer.name : "item " + offer.itemId;
      String scope = remaining == null ? "" : " on the " + JsValues.gp(remaining) + " still unsold";
      AdviceNote n = new AdviceNote(offer.itemId);
      n.level = "warn";
      n.label = "Below break-even";
      n.figures = JsValues.gp(offer.price) + " asked · break-even " + JsValues.gp(breakEven);
      n.name = name;
      n.breakEven = (double) breakEven;
      n.lossEach = JsValues.jsRound(lossEach);
      n.lossTotal = JsValues.jsRound(lossEach * units);
      n.message = name + ": your sell at " + JsValues.gp(offer.price) + " gp is BELOW your break-even of " + JsValues.gp(breakEven) + " gp. "
        + "After tax it returns " + JsValues.gp(netEach) + " gp against the " + JsValues.gp(paid) + " gp it cost, so it loses about "
        + JsValues.gp(lossEach) + " gp each" + scope + " (" + JsValues.gp(lossEach * units) + " gp in total). "
        + "Selling at a loss is sometimes right -- EVI just won't let it happen quietly.";
      out.add(n);
    }
    return out;
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Js;
import com.evi.live.journal.Tax;
import com.evi.live.market.HourBucket;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Does a buy's margin survive at the price buyers have ACTUALLY been paying? (bridge/suggestions.mjs
 * {@code sellPriceSupport}, {@code mergeArchiveHours}, {@code sellSupportNote}, {@code supportIsStale},
 * {@code supportedPriceForHeadline}, and the judgement inside server.mjs's {@code supportForSuggestion}.) Pure: the
 * series and the archive hours are handed in, and so is the clock.
 *
 * <p>WHY: the sell price EVI quotes is /latest's "high", one print. On a thin item one trade can sit far above the
 * market -- the Eclipse Moon chestplate was quoted at 618,004 while 48 buyers had paid an average of 587,104 over twelve
 * hours, below the buy price. The 12-hour buyer average names that mechanism, so it is the reading used.
 *
 * <p>NEVER A GUESS: no series, no reading (null). A reading with no buyers says so. An unmeasurable staleness is NOT
 * stale ("we could not tell" must never read as "we found a problem").
 *
 * <p>THE ARCHIVE AND THE SERIES ARE DOUBLES HERE, on purpose. The Wiki's v2 per-item series carries two decimals and
 * this reading only RANKS and WARNS -- it never becomes a quoted price (the 4 Oct rule: if a quote ever comes from an
 * aggregate, round it at the source, buy ceil / sell floor). Every GP figure it prints goes through JS
 * {@code Math.round} first ({@link JsValues#gp}).
 */
public final class SellSupport {
  private SellSupport() {}

  /** SELL_SUPPORT_HOURS: the window the buyer average is taken over. */
  public static final int SELL_SUPPORT_HOURS = 12;
  /** STALE_SUPPORT_RATIO: above this the 12-hour average is mostly history (measured, 584,245 item-hours). */
  public static final double STALE_SUPPORT_RATIO = 1.5;
  /** SOFT_STALE_SUPPORT_RATIO: worth STATING but not acting on. */
  public static final double SOFT_STALE_SUPPORT_RATIO = 1.25;

  /**
   * One point of the Wiki's per-item hourly series ({timestamp, avgHighPrice, highPriceVolume, avgLowPrice,
   * lowPriceVolume}). A field the Wiki sent as null or did not send is null.
   */
  public static final class Point {
    public final double timestamp;
    public final Double avgHighPrice;
    public final Double highPriceVolume;
    public final Double avgLowPrice;
    public final Double lowPriceVolume;

    public Point(double timestamp, Double avgHighPrice, Double highPriceVolume, Double avgLowPrice, Double lowPriceVolume) {
      this.timestamp = timestamp;
      this.avgHighPrice = avgHighPrice;
      this.highPriceVolume = highPriceVolume;
      this.avgLowPrice = avgLowPrice;
      this.lowPriceVolume = lowPriceVolume;
    }
  }

  /**
   * A reading. {@code averagePaid}, {@code netAtAverage}, {@code latestPaid} and {@code staleness} are null when there is
   * nothing to measure them on. The flags are null unless a check set them (the crash and thin-market readings, which
   * have no window, carry null {@code units} and {@code hours}). {@link #stale} is set by the headline enrichment.
   */
  public static final class Detail {
    public final Double units;
    public final Integer hours;
    public final Double averagePaid;
    public final Double netAtAverage;
    public final boolean supported;
    public final Double latestPaid;
    public final Double staleness;
    public Boolean crashing;
    public Boolean thinMarket;
    public Boolean thinnerThanTax;
    public Boolean belowMinimumAtSupportedPrice;
    public Boolean stale;

    public Detail(Double units, Integer hours, Double averagePaid, Double netAtAverage, boolean supported, Double latestPaid, Double staleness) {
      this.units = units;
      this.hours = hours;
      this.averagePaid = averagePaid;
      this.netAtAverage = netAtAverage;
      this.supported = supported;
      this.latestPaid = latestPaid;
      this.staleness = staleness;
    }

    /** {@code {...detail, <flag>: true}}: a copy, so the reading a caller already holds is not changed under it. */
    Detail copy() {
      Detail d = new Detail(units, hours, averagePaid, netAtAverage, supported, latestPaid, staleness);
      d.crashing = crashing;
      d.thinMarket = thinMarket;
      d.thinnerThanTax = thinnerThanTax;
      d.belowMinimumAtSupportedPrice = belowMinimumAtSupportedPrice;
      d.stale = stale;
      return d;
    }
  }

  /**
   * {@code Number(x)} for a series field. A {@link Point} carries null both for a field the Wiki sent as JSON null and for
   * one it left out, and both read as NaN here. JS would read the first as 0 and the second as NaN; the only use below is
   * {@code > 0}, which both fail, so the two never answer differently.
   */
  private static double num(Double x) {
    return x == null ? Double.NaN : x;
  }

  /**
   * A reading's field as JS arithmetic sees it: the readings this engine builds carry {@code null} (never undefined) for
   * "nothing measured", and JS reads null as 0 in {@code Math.round}/{@code Math.abs} ("an average of 0 gp"). Only reached
   * on readings sellPriceSupport cannot build; kept so the wording never says "NaN".
   */
  static double nullAsZero(Double x) {
    return x == null ? 0 : x;
  }

  /**
   * sellPriceSupport: the buyer average over the {@code hours} FULL hours before {@code nowMs}, and the margin at it.
   * Null for no series, an empty one, or a buy price that is not above 0. The window is aligned to the hour:
   * {@code end = floor(nowMs / 3,600,000) * 3600} (seconds), {@code start = end - hours * 3600}; a point counts when
   * {@code start <= timestamp < end} and both its average buy price and its buy volume are above 0.
   */
  public static Detail sellPriceSupport(List<Point> series, int itemId, double buyPrice, int hours, double nowMs) {
    if (series == null || series.isEmpty() || !(buyPrice > 0)) return null;
    double end = Math.floor(nowMs / 3600000) * 3600, start = end - hours * 3600.0;
    double units = 0, gp = 0, latestTs = Double.NEGATIVE_INFINITY;
    Double latestPaid = null;
    for (Point p : series) {
      // A null point has no answer in JS (p.timestamp throws), so it is not skipped here either; reading() turns it into
      // "no reading", as server.mjs's catch does.
      if (p == null) throw new IllegalArgumentException("a null point in the sell-support series (the JS throws here)");
      if (!(p.timestamp >= start && p.timestamp < end)) continue;
      double price = num(p.avgHighPrice), vol = num(p.highPriceVolume);
      if (price > 0 && vol > 0) {
        units += vol;
        gp += price * vol;
        // The most recent hour anyone actually bought in: what tells the average apart from the present.
        if (p.timestamp > latestTs) {
          latestTs = p.timestamp;
          latestPaid = price;
        }
      }
    }
    if (units == 0) return new Detail(0.0, hours, null, null, false, null, null);
    double averagePaid = gp / units;
    double netAtAverage = averagePaid - Tax.estimateUnitTax(itemId, averagePaid) - buyPrice;
    Double staleness = latestPaid != null && latestPaid > 0 ? averagePaid / latestPaid : null;
    return new Detail(units, hours, averagePaid, netAtAverage, netAtAverage > 0, latestPaid, staleness);
  }

  /** The default window: {@link #SELL_SUPPORT_HOURS}. */
  public static Detail sellPriceSupport(List<Point> series, int itemId, double buyPrice, double nowMs) {
    return sellPriceSupport(series, itemId, buyPrice, SELL_SUPPORT_HOURS, nowMs);
  }

  /** supportIsStale: a measured staleness at or above {@code ratio}. Null-safe and fail-open. */
  public static boolean supportIsStale(Detail detail, double ratio) {
    return detail != null && detail.staleness != null && JsValues.isFinite(detail.staleness) && detail.staleness >= ratio;
  }

  public static boolean supportIsStale(Detail detail) {
    return supportIsStale(detail, STALE_SUPPORT_RATIO);
  }

  /**
   * supportedPriceForHeadline: the buyer average, capped at what buyers pay NOW when the support is stale. It caps the
   * NUMBER and never withholds the pick. Null without an average.
   */
  public static Double supportedPriceForHeadline(Detail detail) {
    if (detail == null || detail.averagePaid == null || !JsValues.isFinite(detail.averagePaid)) return null;
    if (!supportIsStale(detail)) return detail.averagePaid;
    return detail.latestPaid != null && JsValues.isFinite(detail.latestPaid) ? Math.min(detail.averagePaid, detail.latestPaid) : detail.averagePaid;
  }

  /**
   * mergeArchiveHours: the series with the local archive's hours laid over it. The archive's hour wins wherever it has
   * one (the Wiki's per-item series lags about an hour); an hour it lacks keeps the series' point; an archived hour
   * without the item adds nothing. Sorted by timestamp, oldest first (a stable sort, as JS's).
   */
  public static List<Point> mergeArchiveHours(List<Point> series, List<HourBucket> buckets, int itemId) {
    // A JS Map keyed by the timestamp NUMBER: insertion order, a re-set key keeps its place, -0 and 0 are one key.
    Map<Double, Point> byTs = new LinkedHashMap<>();
    if (series != null) for (Point p : series) byTs.put(p.timestamp == 0 ? 0.0 : p.timestamp, p);
    if (buckets != null) for (HourBucket b : buckets) {
      int i = b == null ? -1 : b.indexOf(itemId);
      if (i < 0) continue;
      double ts = b.ts;
      byTs.put(ts == 0 ? 0.0 : ts, new Point(ts, side(b.avgHigh(i)), (double) b.highVolume(i), side(b.avgLow(i)), (double) b.lowVolume(i)));
    }
    List<Point> out = new ArrayList<>(byTs.values());
    out.sort((a, b) -> Js.compare(a.timestamp, b.timestamp));
    return out;
  }

  private static Double side(long v) {
    return v == HourBucket.NONE ? null : (double) v;
  }

  /**
   * sellSupportNote: one warning sentence, or null when the margin holds at what buyers really pay. A warning, never a
   * block: the player may know something the average does not, and the price is still offered.
   */
  public static String sellSupportNote(Detail support, double sellPrice) {
    if (support == null || support.supported) return null;
    String quoted = JsValues.isFinite(sellPrice) ? JsValues.gp(sellPrice) + " gp" : "the sell price";
    if (support.units == null || support.units == 0 || Double.isNaN(support.units))
      return "Warning: nobody bought this item at all in the last " + hoursText(support) + " hours, so the sell price of " + quoted
        + " rests on almost no trading. Your sale may not fill.";
    String perItem = JsValues.gp(Math.abs(nullAsZero(support.netAtAverage)));
    return "Warning: the sell price of " + quoted + " rests on very few trades. Over the last " + hoursText(support) + " hours, "
      + JsValues.localeUs(support.units) + " buyers paid an average of " + JsValues.gp(nullAsZero(support.averagePaid))
      + " gp -- at that price this flip loses about " + perItem + " gp per item after tax.";
  }

  private static String hoursText(Detail d) {
    return d.hours == null ? "null" : String.valueOf(d.hours);
  }

  // ------------------------------------------------------------------------------------------ the server's judgement

  /** What the sell-support check tells the pick chain: hold it back, warn (demote) it, or carry the reading. */
  public static final class Result {
    public final boolean blocked;
    public final String warning;
    public final Detail detail;

    public Result(boolean blocked, String warning, Detail detail) {
      this.blocked = blocked;
      this.warning = warning;
      this.detail = detail;
    }
  }

  /**
   * The reading server.mjs takes for a candidate: the Wiki series ({@code series}, null when it could not be fetched)
   * with the archive's last hours merged in. With no USABLE series -- none, or an EMPTY one (the maintainer, 7 Oct 2026,
   * fixed in JS first: an empty series used to pass this gate and let a few archived hours pose as a 12-hour reading) --
   * AND fewer archived hours than the window there is no reading (null), and the check stays silent.
   */
  public static Detail reading(List<Point> series, List<HourBucket> archived, int itemId, double buyPrice, double nowMs) {
    int archivedHours = archived == null ? 0 : archived.size();
    if ((series == null || series.isEmpty()) && archivedHours < SELL_SUPPORT_HOURS) return null;
    // A series point the Wiki sent as null: mergeArchiveHours reads p.timestamp and THROWS in JS, and
    // supportForSuggestion's catch answers null -- NO reading, even when the archive alone covers the window. Never a
    // reading with that hour quietly skipped.
    if (series != null) for (Point p : series) if (p == null) return null;
    return sellPriceSupport(mergeArchiveHours(series == null ? new ArrayList<>() : series, archived, itemId), itemId, buyPrice, nowMs);
  }

  /**
   * The reading when the ARCHIVE IS THE SERIES: the plugin, which makes no per-item request (no {@link Engine.SellSeries}
   * hook at all -- not a series that failed). What the bridge computes from its series merged with its archive, rebuilt
   * from the archive alone (8 Oct 2026, approved by the maintainer).
   *
   * <p>The bridge's Wiki series ends at H-2 or H-1 (it is cached per item until hh+1:00:10; measured 8 Oct at 09:03 UTC: 10 of
   * 12 items already held H-1, 2 still ended at H-2), and its hours are the archive's own (measured identical, 19 Sept and
   * 8 Oct). Inside the window [H-12, H) the bridge therefore reads H-12..H-2 always, plus H-1 from the series or -- from
   * hh:05, when the archive asks for it -- from the archive. The old gate ({@link #reading} with no series: twelve archived
   * hours or nothing) had NO reading from hh:00 to about hh:05 every hour, while the bridge had one.
   *
   * <p>So: a reading exactly when the archive holds EVERY hour from H-12 to H-2 (the hours always settled); H-1 is used when
   * stored, and not required. From about hh:05 that IS the bridge's merged series (archive with no gap); from hh:00 to hh:05
   * it is the bridge's for items whose series still ends at H-2, and one hour short of it (eleven hours, not twelve) for the
   * rest -- the plugin has no H-1 before its archive fetches it. An archive with a gap the series would have filled still
   * gives no reading (fail open, never a guess).
   */
  public static Detail readingFromArchive(List<HourBucket> archived, int itemId, double buyPrice, double nowMs) {
    if (!archiveCoversSettledWindow(archived, nowMs)) return null;
    return sellPriceSupport(mergeArchiveHours(new ArrayList<>(), archived, itemId), itemId, buyPrice, nowMs);
  }

  /** Whether {@code archived} holds every hour from H-{@value #SELL_SUPPORT_HOURS} to H-2, where H is the hour {@code nowMs} is in. */
  public static boolean archiveCoversSettledWindow(List<HourBucket> archived, double nowMs) {
    if (archived == null) return false;
    long end = (long) (Math.floor(nowMs / 3600000.0) * 3600);
    java.util.Set<Long> have = new java.util.HashSet<>();
    for (HourBucket b : archived) if (b != null) have.add(b.ts);
    for (long ts = end - SELL_SUPPORT_HOURS * 3600L; ts <= end - 2 * 3600L; ts += 3600) if (!have.contains(ts)) return false;
    return true;
  }

  /**
   * The judgement inside server.mjs's {@code supportForSuggestion}, once the crash and thin-market readings have had
   * their say (they come first, and are Phase 4's). Null when there is no reading.
   * <ul>
   *   <li>HELD BACK when the margin at the price buyers really pay is thinner than the tier's own tax bar
   *       ({@link LevelSettings#historyMarginTaxMultiple} for the personal tier, the no-history bar otherwise) -- the
   *       blood runes of 27 Sept: quoted 7 gp against a 6 gp tax, really 1 gp. Only while the margin-over-tax check is
   *       on ({@code requireMarginOverTax}: off only for "no minimum at all").</li>
   *   <li>WARNED (demoted) when the trade is worth less than the minimum at that price -- always checked, chosen
   *       minimum or the Auto floor, because the default Auto tier sends no minimum (27 Sept).</li>
   *   <li>otherwise the plain support note, if any, and the reading itself, carried so a clean pick can show what was
   *       checked.</li>
   * </ul>
   */
  public static Result judge(Detail detail, Pick candidate, double minProfit, boolean minProfitChosen, boolean requireMarginOverTax, LevelSettings level) {
    String warning = sellSupportNote(detail, candidate.sellPrice);
    if (detail != null && detail.netAtAverage != null && JsValues.isFinite(detail.netAtAverage)) {
      double qty = candidate.quantity != 0 ? candidate.quantity : 1; // candidate.quantity || 1
      double supportedTotal = detail.netAtAverage * qty;
      double taxAtSupport = Tax.estimateUnitTax(candidate.itemId, nullAsZero(detail.averagePaid));
      double bar = "personal".equals(candidate.source) ? level.historyMarginTaxMultiple : level.noHistoryMarginTaxMultiple;
      if (requireMarginOverTax && !Gates.marginClearsTax(detail.netAtAverage, taxAtSupport, bar)) {
        Detail d = detail.copy();
        d.thinnerThanTax = true;
        return new Result(true, "Set aside: at the price buyers are actually paying this makes about " + JsValues.gp(detail.netAtAverage)
          + " gp a unit, against the " + JsValues.gp(taxAtSupport) + " gp tax on each one. An edge thinner than its own tax does not survive a single"
          + " price step -- measured over 335 hours, trades like this lose GP a third of the time,"
          + " however large the quantity makes the total look.", d);
      }
      if (supportedTotal < minProfit) {
        double quotedTotal = (double) (candidate.sellPrice - Tax.estimateUnitTax(candidate.itemId, candidate.sellPrice) - candidate.buyPrice) * qty;
        Detail d = detail.copy();
        d.belowMinimumAtSupportedPrice = true;
        return new Result(false, "Warning: " + (minProfitChosen ? "below your " + JsValues.gp(minProfit) + " gp minimum" : "worth under " + JsValues.gp(minProfit) + " gp")
          + " at the price buyers are actually paying. The quoted spread makes this look like " + JsValues.gp(quotedTotal) + " gp, but over the last "
          + hoursText(detail) + " hours " + (detail.units == null ? "null" : JsValues.localeUs(detail.units)) + " buyers paid an average of " + JsValues.gp(nullAsZero(detail.averagePaid))
          + " gp, which makes it about " + JsValues.gp(supportedTotal) + " gp.", d);
      }
    }
    if (warning != null) return new Result(false, warning, detail);
    return detail != null ? new Result(false, null, detail) : null;
  }
}

package com.evi.live.engine;

import com.evi.live.market.HourBucket;
import java.util.Map;

/**
 * How large one suggested order may be: the sizing half of bridge/suggestions.mjs (and the buy-limit closure in
 * server.mjs), ported for the self-contained plugin. Pure: no I/O, no clock (time is passed in), no threads.
 *
 * <p>THE ARITHMETIC IS THE JS ARITHMETIC. Every cap is computed in doubles, in the same order of operations, and only
 * the final whole number becomes a {@code long} (through {@link JsValues#exactLong}, which refuses rather than wraps).
 * A cash stack is a double here for the same reason: the JS divides it ({@code Math.floor(maxSpend / price)}), and a
 * whole number of gp under 2^53 is exact either way.
 *
 * <p>ABSENT IS NOT ZERO, in three places that have each cost GP once:
 * <ul>
 *   <li>cash: {@code null} is "unknown, no cap"; {@code 0} is "carrying nothing, afford nothing" (29 Sept);</li>
 *   <li>volume: an item ABSENT from the latest hour is no reading and constrains nothing; a LISTED zero is a
 *       measurement and sizes the order at one unit (the Eclipse Moon chestplate);</li>
 *   <li>the typical hour: a zero or missing typical reading falls back to the latest hour, but a measured zero in the
 *       latest hour beats any median ({@link #sizingLiquidityFor}, the 2 Oct precedence table).</li>
 * </ul>
 *
 * <p>THE ORDER OF THE CAPS differs by tier and is part of the behaviour: the quantity is the smallest cap whatever the
 * order, but WHICH cap is reported as having bound (and so which sentence the player reads) depends on it. Each tier's
 * order is ported as its own method ({@link #historyQuantity}, {@link #marketQuantity}, {@link #pushedQuantity}) and
 * proven against the real tier functions, not reconstructed.
 */
public final class Sizing {
  private Sizing() {}

  /** The Wiki /1h endpoint's window, in minutes (VOLUME_WINDOW_MINUTES). */
  public static final double VOLUME_WINDOW_MINUTES = 60;
  /** The volume share one order may take with no pace, or under six hours (DEFAULT_MAX_VOLUME_SHARE). */
  public static final double DEFAULT_MAX_VOLUME_SHARE = 0.10;
  /** VOLUME_SHARE_PER_HOUR, 1/24, as the same double. */
  public static final double VOLUME_SHARE_PER_HOUR = 1.0 / 24;
  /** The most of one hour's volume a single order may be (MAX_VOLUME_SHARE). */
  public static final double MAX_VOLUME_SHARE = 2;
  /** A market-wide pick's size when the item's buy limit is unknown (DEFAULT_MARKET_QUANTITY_CAP). */
  public static final long DEFAULT_MARKET_QUANTITY_CAP = 100;
  /** The GE's buy-limit window (LIMIT_WINDOW_MS). */
  public static final double LIMIT_WINDOW_MS = 4 * 3600 * 1000;
  public static final double FILL_FLOOR_MINUTES = 5;
  public static final double PASSIVE_FILL_FACTOR = 1.5;
  public static final double DURATION_TOLERANCE = 2;
  public static final double CAPTURE_CURVE_ANCHOR_UNITS = 100;
  public static final double CAPTURE_CURVE_AT_ANCHOR = 0.05;
  public static final double CAPTURE_MAX_SHARE = 0.25;

  // ------------------------------------------------------------------------------------------- inputs

  /** The sizing options the caps read: {@code options.maxVolumeShare}, {@code volumeWindowShare}, {@code captureCap}. */
  public static final class SizingOptions {
    /** NaN when the caller set none (the JS checks Number.isFinite, so NaN and absent are the same). */
    public final double maxVolumeShare;
    /** NaN when the caller set none; only a finite value above 0 switches to the per-window rule ("Bigger positions"). */
    public final double volumeWindowShare;
    /** The opt-in capture-curve cap (falsified 4 Oct, off by default). */
    public final boolean captureCap;

    public SizingOptions(double maxVolumeShare, double volumeWindowShare, boolean captureCap) {
      this.maxVolumeShare = maxVolumeShare;
      this.volumeWindowShare = volumeWindowShare;
      this.captureCap = captureCap;
    }

    /** No options: today's default ladder, no window share, no capture cap. */
    public static final SizingOptions DEFAULT = new SizingOptions(Double.NaN, Double.NaN, false);
  }

  /**
   * What only the caller knows about an item: a free-to-play world's members flag, the player's focus, and what is
   * left of the 4-hour buy limit. The three callbacks {@code gateCandidate} takes as options.
   */
  public interface ItemGate {
    boolean membersBlocked(int itemId);

    boolean focusBlocked(int itemId);

    /** {@code limitFor(itemId)?.remaining}: null when there is no limit (unknown limit, or no account); a non-finite value constrains nothing too. */
    Double limitRemaining(int itemId);

    /** Nothing blocked and no limit known. */
    ItemGate NONE = new ItemGate() {
      @Override public boolean membersBlocked(int itemId) {
        return false;
      }

      @Override public boolean focusBlocked(int itemId) {
        return false;
      }

      @Override public Double limitRemaining(int itemId) {
        return null;
      }
    };
  }

  /** A request's trade length as every tier normalises it: a finite value above 0, else null (no pace). */
  public static Double duration(double raw) {
    return JsValues.isFinite(raw) && raw > 0 ? raw : null;
  }

  /** A tier's cash cap: a finite value of at least 0, else null. {@code >= 0}: an empty coin pouch is a real answer. */
  public static Double maxSpend(double raw) {
    return JsValues.isFinite(raw) && raw >= 0 ? raw : null;
  }

  // ------------------------------------------------------------------------------------------- the caps

  /** volumeShareForDuration: 10% under six hours, 25% from six, then hours/12 from twelve hours, capped at 2x. */
  public static double volumeShareForDuration(double targetDurationMinutes) {
    if (!JsValues.isFinite(targetDurationMinutes) || targetDurationMinutes <= 0) return DEFAULT_MAX_VOLUME_SHARE;
    if (targetDurationMinutes >= 12 * 60) return Math.min(MAX_VOLUME_SHARE, (targetDurationMinutes / 60) * VOLUME_SHARE_PER_HOUR * 2);
    if (targetDurationMinutes >= 6 * 60) return 0.25;
    return DEFAULT_MAX_VOLUME_SHARE;
  }

  /**
   * orderSizeCap: the most units one order may be for an item's hourly liquidity and the player's window, floored at
   * one unit, or null when it constrains nothing (no reading, or a share switched off). A liquidity of 0 is a
   * measured zero and gives ONE unit, never "no constraint".
   */
  public static Long orderSizeCap(double liquidity, double targetDurationMinutes, SizingOptions options) {
    if (!JsValues.isFinite(liquidity) || liquidity < 0) return null;
    if (JsValues.isFinite(options.volumeWindowShare) && options.volumeWindowShare > 0) {
      double windowHours = JsValues.isFinite(targetDurationMinutes) && targetDurationMinutes > 0 ? targetDurationMinutes / 60 : 1;
      return JsValues.exactLong(Math.max(1, Math.floor(liquidity * windowHours * options.volumeWindowShare)));
    }
    double share = JsValues.isFinite(options.maxVolumeShare) ? options.maxVolumeShare : volumeShareForDuration(targetDurationMinutes);
    if (!(share > 0)) return null;
    return JsValues.exactLong(Math.max(1, Math.floor(liquidity * share)));
  }

  /**
   * captureFillable: the opt-in capture-curve cap, {@code (V/2)^(2/3)} held under a quarter of the flow, floored at 1;
   * null for no flow. {@link StrictMath#pow} (fdlibm, as V8's own pow), so a perfect cube cannot round differently.
   */
  public static Long captureFillable(double volumeInWindow) {
    if (!JsValues.isFinite(volumeInWindow) || volumeInWindow <= 0) return null;
    double fixedPoint = StrictMath.pow(volumeInWindow / 2, 2.0 / 3);
    return JsValues.exactLong(Math.max(1, Math.floor(Math.min(CAPTURE_MAX_SHARE * volumeInWindow, fixedPoint))));
  }

  /**
   * limitAllowance: what is left of the current 4-hour window, plus one whole limit for every further window that
   * STARTS before the player's duration runs out. Null for an unknown or non-positive limit. {@code used} and
   * {@code windowEndsAt} take NaN for "none" (the JS's undefined and null read the same here).
   */
  public static Double limitAllowance(double limit, double used, double windowEndsAt, double targetDurationMinutes, double now) {
    if (!JsValues.isFinite(limit) || limit <= 0) return null;
    double usedOr0 = Double.isNaN(used) || used == 0 ? 0 : used; // (used || 0)
    double inWindow = Math.max(0, limit - usedOr0);
    double duration = JsValues.isFinite(targetDurationMinutes) && targetDurationMinutes > 0 ? targetDurationMinutes * 60000 : 0;
    if (duration == 0) return inWindow;
    double firstReset = JsValues.isFinite(windowEndsAt) && windowEndsAt > now ? windowEndsAt - now : (used > 0 ? 0 : LIMIT_WINDOW_MS);
    double further = firstReset < duration ? Math.ceil((duration - firstReset) / LIMIT_WINDOW_MS) : 0;
    return inWindow + further * limit;
  }

  /** What server.mjs's {@code limitFor(itemId)} returns: the item's limit, what can fill NOW, and the allowance across windows. */
  public static final class Limit {
    public final double limit;
    /** One window's remainder and nothing more ({@code Math.max(0, limit - used)}): what gateCandidate clips to. */
    public final double remaining;
    public final Double acrossWindows;

    Limit(double limit, double remaining, Double acrossWindows) {
      this.limit = limit;
      this.remaining = remaining;
      this.acrossWindows = acrossWindows;
    }
  }

  /**
   * server.mjs's {@code limitFor} closure: null for an unknown or non-positive catalogue limit (no constraint);
   * otherwise the remainder of this window (a non-finite {@code used} counts as none) and the multi-window allowance.
   */
  public static Limit limitFor(double catalogLimit, double used, double windowEndsAt, double targetDurationMinutes, double now) {
    if (!JsValues.isFinite(catalogLimit) || catalogLimit <= 0) return null;
    Double across = limitAllowance(catalogLimit, used, windowEndsAt, targetDurationMinutes, now);
    return new Limit(catalogLimit, Math.max(0, catalogLimit - (JsValues.isFinite(used) ? used : 0)), across);
  }

  /**
   * sizingLiquidityFor: the hourly volume an order is sized on. The precedence table (2 Oct):
   * <pre>
   *   latest hour is a measured 0          -> 0        one unit; a median cannot say you could have exited this hour
   *   latest hour absent, typical present  -> typical
   *   latest hour trading, typical present -> typical  the point of the change
   *   latest hour trading, no typical      -> latest   the old behaviour
   *   both absent                          -> null     no signal, constrains nothing
   * </pre>
   * {@code typical} takes NaN for "none"; only a finite value above 0 is a typical reading.
   */
  public static Double sizingLiquidityFor(Long latestReading, double typical) {
    if (latestReading != null && latestReading == 0) return 0.0;
    if (JsValues.isFinite(typical) && typical > 0) return typical;
    return latestReading == null ? null : (double) latestReading;
  }

  /** The same, read from the price layer: the latest hour's row and the 168-hour typical volumes. */
  public static Double sizingLiquidityFor(HourBucket latestHour, Map<Integer, Long> typicalVolumes, int itemId) {
    Long typical = typicalVolumes == null ? null : typicalVolumes.get(itemId);
    return sizingLiquidityFor(VolumeRow.reading(VolumeRow.of(latestHour, itemId)), typical == null ? Double.NaN : typical);
  }

  // ------------------------------------------------------------------------------------------- fill time

  /** estimatedFillMinutes: quantity over the hour's rate; Infinity with no usable volume. */
  public static double estimatedFillMinutes(double quantity, double liquidity, double windowMinutes) {
    if (!(liquidity > 0)) return Double.POSITIVE_INFINITY;
    return quantity / (liquidity / windowMinutes);
  }

  /** correctedFillMinutes: floored at five minutes, times the passive-fill factor; a non-finite estimate passes through. */
  public static double correctedFillMinutes(double rawMinutes) {
    if (!JsValues.isFinite(rawMinutes)) return rawMinutes;
    return Math.max(FILL_FLOOR_MINUTES, rawMinutes) * PASSIVE_FILL_FACTOR;
  }

  /** The same for a value that may be absent: the JS returns a non-finite input UNCHANGED, so absent stays absent. */
  public static Double correctedFillMinutes(Double rawMinutes) {
    return rawMinutes == null ? null : correctedFillMinutes(rawMinutes.doubleValue());
  }

  /** estimateOfferFill's answer. */
  public static final class OfferFill {
    /** Rounded half-up; -1 when there is no estimate (no volume). */
    public final long estimatedFillMinutes;
    public final boolean likelyToFillInTime;

    OfferFill(long estimatedFillMinutes, boolean likelyToFillInTime) {
      this.estimatedFillMinutes = estimatedFillMinutes;
      this.likelyToFillInTime = likelyToFillInTime;
    }
  }

  /** estimateOfferFill: null without a remaining quantity, a pace or a row of the latest hour. */
  public static OfferFill estimateOfferFill(double remainingQty, VolumeRow row, double targetDurationMinutes) {
    if (!(remainingQty > 0) || !JsValues.isFinite(targetDurationMinutes) || targetDurationMinutes <= 0) return null;
    if (row == null) return null;
    double minutes = correctedFillMinutes(estimatedFillMinutes(remainingQty, VolumeRow.liquidity(row), VOLUME_WINDOW_MINUTES));
    return new OfferFill(JsValues.isFinite(minutes) ? com.evi.live.journal.Js.round(minutes) : -1, minutes <= targetDurationMinutes);
  }

  // ------------------------------------------------------------------------------------------- the buy-limit clip

  /** gateCandidate's answer: the quantity after the clip, and whether the buy limit is what cut it. */
  public static final class Clip {
    public final long quantity;
    public final boolean limited;

    Clip(long quantity, boolean limited) {
      this.quantity = quantity;
      this.limited = limited;
    }
  }

  /**
   * gateCandidate: never an unflippable item, a members item on a free world, or one outside the player's focus
   * (null); otherwise the quantity clipped to what is left of the 4-hour buy limit. A limit already used up drops
   * the candidate (null); no limit reading constrains nothing.
   */
  public static Clip gate(int itemId, long quantity, ItemGate gate) {
    if (Gates.isUnflippable(itemId)) return null;
    if (gate.membersBlocked(itemId)) return null;
    if (gate.focusBlocked(itemId)) return null;
    Double remaining = gate.limitRemaining(itemId);
    if (remaining == null || !JsValues.isFinite(remaining)) return new Clip(quantity, false);
    if (remaining < 1) return null; // the 4-hour limit for this item is already used up
    return remaining < quantity ? new Clip(JsValues.exactLong(remaining), true) : new Clip(quantity, false);
  }

  // ------------------------------------------------------------------------------------------- the chains

  /** A sized order: its quantity and which caps bound it (each flag is one sentence of the reasoning). */
  public static final class Sized {
    public final long quantity;
    public final boolean cashLimited;
    public final boolean stackLimited;
    public final boolean shareLimited;
    public final boolean durationLimited;
    public final boolean limitLimited;

    Sized(long quantity, boolean cash, boolean stack, boolean share, boolean duration, boolean limit) {
      this.quantity = quantity;
      this.cashLimited = cash;
      this.stackLimited = stack;
      this.shareLimited = share;
      this.durationLimited = duration;
      this.limitLimited = limit;
    }
  }

  /** Math.floor(budget / price): what a budget buys, as a double (the drop test is {@code < 1}). */
  private static double units(double budget, long price) {
    return Math.floor(budget / price);
  }

  /** The duration cap shared by the history and market tiers: null when even one unit would run well past the window. */
  private static final class DurationCap {
    final boolean dropped;
    final Long fillable;

    DurationCap(boolean dropped, Long fillable) {
      this.dropped = dropped;
      this.fillable = fillable;
    }
  }

  private static DurationCap durationCap(double liquidity, double target, boolean captureCap) {
    // Dropped only when a SINGLE unit would run past twice the target; sizing itself gets no tolerance.
    if (correctedFillMinutes(estimatedFillMinutes(1, liquidity, VOLUME_WINDOW_MINUTES)) > target * DURATION_TOLERANCE) return new DurationCap(true, null);
    double volumeInWindow = liquidity / VOLUME_WINDOW_MINUTES * target;
    Long fillable = captureCap ? captureFillable(volumeInWindow) : Long.valueOf(JsValues.exactLong(Math.max(1, Math.floor(volumeInWindow / PASSIVE_FILL_FACTOR))));
    return new DurationCap(false, fillable);
  }

  /**
   * The personal-history tier's order (computeSuggestion): the player's own median size, then cash, then the share of
   * the stack, then the volume share, then the trade length, then the buy-limit clip. Null when a cap drops the
   * candidate. {@code medianQty} is the item's median past quantity (an average of the middle pair for an even count,
   * so it can be x.5, rounded half-up here).
   *
   * @param maxSpend the cash cap, null when unknown ({@link #maxSpend})
   * @param maxStackShare {@code options.maxStackShare}, NaN when unset
   * @param typical the item's typical hourly volume, NaN when none
   * @param targetDurationMinutes the normalised pace, null for none ({@link #duration})
   */
  public static Sized historyQuantity(int itemId, double medianQty, long buyPrice, Double maxSpend, double maxStackShare, VolumeRow latest,
                                      double typical, Double targetDurationMinutes, SizingOptions options, ItemGate gate) {
    long quantity = Math.max(1, com.evi.live.journal.Js.round(medianQty));
    boolean cash = false, stack = false, share = false, duration = false;
    if (maxSpend != null) {
      double affordable = units(maxSpend, buyPrice);
      if (affordable < 1) return null; // can't afford even one unit at the current cash stack
      if (affordable < quantity) {
        quantity = JsValues.exactLong(affordable);
        cash = true;
      }
    }
    if (JsValues.isFinite(maxStackShare) && maxStackShare > 0 && maxSpend != null) {
      double withinShare = units(maxSpend * maxStackShare, buyPrice);
      if (withinShare < 1) return null; // one unit alone would commit more of the stack than allowed
      if (withinShare < quantity) {
        quantity = JsValues.exactLong(withinShare);
        stack = true;
      }
    }
    Double ownLiquidity = sizingLiquidityFor(VolumeRow.reading(latest), typical);
    if (ownLiquidity != null) {
      Long withinVolume = orderSizeCap(ownLiquidity, targetDurationMinutes == null ? Double.NaN : targetDurationMinutes, options);
      if (withinVolume != null && withinVolume < quantity) {
        quantity = withinVolume;
        share = true;
      }
    }
    if (targetDurationMinutes != null) {
      long liquidity = VolumeRow.liquidity(latest);
      if (liquidity > 0) { // no volume data at all: no signal to judge by, so no constraint
        DurationCap d = durationCap(liquidity, targetDurationMinutes, options.captureCap);
        if (d.dropped) return null;
        if (d.fillable != null && d.fillable < quantity) {
          quantity = d.fillable;
          duration = true;
        }
      }
    }
    Clip clip = gate(itemId, quantity, gate);
    if (clip == null) return null;
    return new Sized(clip.quantity, cash, stack, share, duration, clip.limited);
  }

  /**
   * The market-wide tier's order (computeMarketSuggestion), AFTER its liquidity floor ({@link Gates#liquidityFloorMet}):
   * the item's buy limit across the windows the pace spans (100 when the limit is unknown), then cash, then the trade
   * length, then the share of the stack, then the window or volume share (on the typical hour, else the latest), then
   * the buy-limit clip. Null when a cap drops it.
   *
   * @param catalogLimit the mapping's {@code limit}, NaN when absent
   */
  public static Sized marketQuantity(int itemId, double catalogLimit, long buyPrice, Double maxSpend, double maxStackShare, VolumeRow latest,
                                     double typical, Double targetDurationMinutes, SizingOptions options, ItemGate gate) {
    return marketQuantity(itemId, catalogLimit, buyPrice, maxSpend, maxStackShare, latest, null, typical, targetDurationMinutes, options, gate);
  }

  /**
   * The same, with the reading of computeMarketSuggestion's own {@code options.volumes} for the item ({@code optionsReading},
   * {@link VolumeRow#reading}: null when that option is absent or does not list the item). server.mjs never passes that
   * option -- it hands the hour over as an ARGUMENT -- so production sizes on the typical hour, else this hour
   * ({@code sizingLiquidityFor(options, id) ?? liquidity}); a caller that does pass it (the JS tests, the tools) gets
   * the precedence table on it, a measured zero there sizing the order at one unit.
   */
  public static Sized marketQuantity(int itemId, double catalogLimit, long buyPrice, Double maxSpend, double maxStackShare, VolumeRow latest,
                                     Long optionsReading, double typical, Double targetDurationMinutes, SizingOptions options, ItemGate gate) {
    double target = targetDurationMinutes == null ? Double.NaN : targetDurationMinutes;
    long liquidity = VolumeRow.liquidity(latest);
    // With no `volumes` option (the server's call) sizingLiquidityFor sees no latest reading: the typical hour when there
    // is one, else this hour's liquidity (`?? liquidity`). After the floor that is the same number either way, since the
    // floor has already refused a measured zero.
    Double sized = sizingLiquidityFor(optionsReading, typical);
    double sizingLiquidity = sized != null ? sized : liquidity;
    double volumeShare = JsValues.isFinite(options.maxVolumeShare) ? options.maxVolumeShare : volumeShareForDuration(target);
    boolean limitKnown = JsValues.isFinite(catalogLimit) && catalogLimit > 0;
    // limitAllowance with no usage and no running window: one limit, plus one per further window the pace spans.
    double start = limitKnown ? limitAllowance(catalogLimit, 0, Double.NaN, target, 0) : DEFAULT_MARKET_QUANTITY_CAP;
    long quantity = JsValues.exactLong(Math.max(1, start));
    boolean cash = false, stack = false, share = false, duration = false;
    if (maxSpend != null) {
      double affordable = units(maxSpend, buyPrice);
      if (affordable < 1) return null;
      if (affordable < quantity) {
        quantity = JsValues.exactLong(affordable);
        cash = true;
      }
    }
    if (targetDurationMinutes != null) {
      DurationCap d = durationCap(liquidity, targetDurationMinutes, options.captureCap);
      if (d.dropped) return null;
      if (d.fillable != null && d.fillable < quantity) {
        quantity = d.fillable;
        duration = true;
      }
    }
    if (JsValues.isFinite(maxStackShare) && maxStackShare > 0 && maxSpend != null) {
      double byStack = units(maxSpend * maxStackShare, buyPrice);
      if (byStack < 1) return null;
      if (byStack < quantity) {
        quantity = JsValues.exactLong(byStack);
        stack = true;
      }
    }
    if (JsValues.isFinite(options.volumeWindowShare) && options.volumeWindowShare > 0) {
      double windowHours = targetDurationMinutes != null ? targetDurationMinutes / 60 : 1;
      double byWindow = Math.max(1, Math.floor(sizingLiquidity * windowHours * options.volumeWindowShare));
      if (byWindow < quantity) {
        quantity = JsValues.exactLong(byWindow);
        share = true;
      }
    } else if (volumeShare > 0) {
      double byVolume = Math.max(1, Math.floor(sizingLiquidity * volumeShare));
      if (byVolume < quantity) {
        quantity = JsValues.exactLong(byVolume);
        share = true;
      }
    }
    Clip clip = gate(itemId, quantity, gate);
    if (clip == null) return null;
    return new Sized(clip.quantity, cash, stack, share, duration, clip.limited);
  }

  /**
   * The scanner-pushed tier's order (computePushedSuggestion): the item's buy limit across the pace's windows when the
   * catalogue knows it (else the scanner's own quantity, rounded half-up), then the volume share, then the buy-limit
   * clip, then cash -- the clip BEFORE cash, which is this tier's order. Null when a cap drops it.
   *
   * @param limitOf the catalogue limit, NaN when unknown
   * @param scannerQty the quantity the scanner pushed, NaN when absent
   */
  public static Sized pushedQuantity(int itemId, double limitOf, double scannerQty, long buyPrice, Double maxSpend, VolumeRow latest,
                                     double typical, Double targetDurationMinutes, SizingOptions options, ItemGate gate) {
    double target = targetDurationMinutes == null ? Double.NaN : targetDurationMinutes;
    long scanner = Math.max(1, com.evi.live.journal.Js.round(JsValues.isFinite(scannerQty) && scannerQty > 0 ? scannerQty : 1));
    long quantity = JsValues.isFinite(limitOf) && limitOf > 0
      ? JsValues.exactLong(Math.max(1, limitAllowance(limitOf, 0, Double.NaN, target, 0)))
      : scanner;
    boolean share = false, cash = false;
    Double liquidity = sizingLiquidityFor(VolumeRow.reading(latest), typical);
    if (liquidity != null) {
      Long withinVolume = orderSizeCap(liquidity, target, options);
      if (withinVolume != null && withinVolume < quantity) {
        quantity = withinVolume;
        share = true;
      }
    }
    Clip clip = gate(itemId, quantity, gate);
    if (clip == null) return null;
    quantity = clip.quantity;
    if (maxSpend != null) {
      double affordable = units(maxSpend, buyPrice);
      if (affordable < 1) return null;
      if (affordable < quantity) {
        quantity = JsValues.exactLong(affordable);
        cash = true;
      }
    }
    return new Sized(quantity, cash, false, share, false, clip.limited);
  }
}

package com.evi.live.engine;

/**
 * spreadRankFor (bridge/suggestions.mjs): which candidate from the top of the ranking this account is handed, so
 * that every user with the same settings is not pointed at the same item in the same hour (crowding, 3 Oct). Pure.
 *
 * <p>STABLE PER ACCOUNT: FNV-1a over the account id, no randomness and no state, so the same account gets the same
 * offset on every poll.
 *
 * <p>THE HASH IS AN UNSIGNED 32-BIT VALUE, and that is the trap. The JS does {@code Math.imul(h, prime) >>> 0} and
 * then {@code h % n} on a NON-NEGATIVE number. Java's {@code int} arithmetic gives the same bits, but a plain
 * {@code h % n} on a Java int is a SIGNED remainder: for about half of all accounts it would be a different (even
 * negative) bucket, and each of those players would quietly be handed a different pick from today. So the bucket is
 * {@link Integer#remainderUnsigned}. The account id is trimmed as {@code String.prototype.trim} trims
 * ({@link JsValues#trim}), not as {@link String#trim} does.
 */
public final class SpreadRank {
  private SpreadRank() {}

  private static final int FNV_OFFSET = 0x811c9dc5;
  private static final int FNV_PRIME = 0x01000193;

  /** The FNV-1a hash of the id's UTF-16 code units, as JS computes it (the bits of the unsigned value). */
  public static int fnv1a(String id) {
    int h = FNV_OFFSET;
    for (int i = 0; i < id.length(); i++) {
      h ^= id.charAt(i);
      h *= FNV_PRIME; // Math.imul: the low 32 bits of the product
    }
    return h;
  }

  /**
   * The rank (0 = the top pick) for this account under a spread of {@code spread} candidates. 0 for a spread of 1 or
   * less, a non-finite spread, or no account id.
   */
  public static long spreadRankFor(String accountId, double spread) {
    double n = JsValues.isFinite(spread) ? Math.floor(spread) : 1;
    if (n <= 1) return 0;
    String id = JsValues.trim(accountId == null ? "" : accountId);
    if (id.isEmpty()) return 0;
    int h = fnv1a(id);
    // n is a whole number of at least 2. Past 2^32 - 1 it exceeds every hash, so the remainder is the hash itself.
    if (n > 4294967295.0) return Integer.toUnsignedLong(h);
    return Integer.toUnsignedLong(Integer.remainderUnsigned(h, (int) (long) n));
  }
}

package com.evi.live.engine;

import com.evi.live.market.HourBucket;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * "EVI quotes the price it last sold for -- how realistic is buying at that price again?" (bridge/thinMarket.mjs). Pure:
 * the archived hours are handed in, nothing is read or cached here (the bridge rebuilds its index at most every six hours
 * from a fortnight of archive; whoever wires this owns that cache).
 *
 * <p>WHAT IT MEASURES, per item, from the archive only: CADENCE -- in how many of the archived hours the item traded at
 * all (a low price AND sell-side units both above zero), and units a day; RECURRENCE -- for each hour it traded, whether
 * any hour within the window traded at or below THAT hour's own price. Measured at the item's own level, so an item whose
 * price drifted is not scored "always available" because it used to be cheaper. Every figure is a count over hours that
 * really happened.
 *
 * <p>WHY IT MATTERS: it gates the history tier, which has no liquidity floor. The Berserker icon that prompted it traded
 * in 43 of 1,439 hours and its own price came back within 4 hours in 7% of cases. The measured bands (60 days, 400 items):
 * under 10% of hours 29% within 4h and a median of ONE unit; 10-40% of hours 67% within 4h with 7 units (a real trade --
 * which is why {@link #THIN_CADENCE} is a tenth and not a quarter).
 *
 * <p>FAIL OPEN: an item with too little archive gets no note at all, never a quiet pass ("EVI has not watched this long
 * enough" must never read as "this is fine"). But an item ABSENT from an archive long enough to judge traded in NONE of
 * those hours -- a count, not missing data -- and that is the strongest warning.
 *
 * <p>Numbers only, never a forecast, and never a block: the caller demotes the pick and shows the note.
 */
public final class ThinMarket {
  private ThinMarket() {}

  /** WINDOWS: the windows worth precomputing; a player's own trade duration is matched to the nearest. */
  public static final int[] WINDOWS = {1, 4, 12, 24};
  /** MIN_HOURS: below this many archived hours there is nothing to judge an item on. */
  public static final int MIN_HOURS = 72;
  /** THIN_RECURRENCE: fewer than half the item's own price levels coming back is a coin flip at best. */
  public static final double THIN_RECURRENCE = 0.5;
  /** THIN_CADENCE: trading in under a tenth of hours is thin however well its prices recur. */
  public static final double THIN_CADENCE = 0.10;

  /**
   * One item's reading. {@link #recurrence} and {@link #unitsWithin} are per window ({@link #WINDOWS} order): null when no
   * hour could be judged for that window (JS {@code null}), and null for a window the reading does not carry at all (JS
   * {@code undefined}, which only a hand-made reading can produce) -- both read as "nothing to say".
   */
  public static final class Stats {
    public final double hours;
    public final double hoursTraded;
    public final double cadence;
    public final double unitsPerDay;
    final Double[] recurrence;
    final Double[] unitsWithin;
    /** The LAST window's sample count, as the JS leaves it ({@code stats.samples} is overwritten per window). */
    public final double samples;

    public Stats(double hours, double hoursTraded, double cadence, double unitsPerDay, Double[] recurrence, Double[] unitsWithin, double samples) {
      this.hours = hours;
      this.hoursTraded = hoursTraded;
      this.cadence = cadence;
      this.unitsPerDay = unitsPerDay;
      this.recurrence = recurrence.clone();
      this.unitsWithin = unitsWithin.clone();
      this.samples = samples;
    }

    /** {@code stats.recurrence[w]}: null for none or for a window that is not one of {@link #WINDOWS}. */
    public Double recurrence(double w) {
      int i = windowIndex(w);
      return i < 0 ? null : recurrence[i];
    }

    /** {@code stats.unitsWithin[w]}. */
    public Double unitsWithin(double w) {
      int i = windowIndex(w);
      return i < 0 ? null : unitsWithin[i];
    }
  }

  /** The index: how many archived hours it was built on, and each item that traded in any of them. */
  public static final class Index {
    public final int hours;
    private final TreeMap<Integer, Stats> byItem;

    Index(int hours, TreeMap<Integer, Stats> byItem) {
      this.hours = hours;
      this.byItem = byItem;
    }

    /** The item's reading, or null: an item absent from a non-empty index traded in NONE of its hours. */
    public Stats get(int itemId) {
      return byItem.get(itemId);
    }

    /** Every item, in ascending id order. */
    public Map<Integer, Stats> all() {
      return Collections.unmodifiableMap(byItem);
    }
  }

  static int windowIndex(double w) {
    for (int i = 0; i < WINDOWS.length; i++) if (WINDOWS[i] == w) return i;
    return -1;
  }

  /** {@code WINDOWS.includes(w) ? w : 12}. */
  static int windowOr12(Double w) {
    return w != null && windowIndex(w) >= 0 ? (int) (double) w : 12;
  }

  /**
   * buildThinMarketIndex: archived hourly buckets, oldest first (null or empty: an index of 0 hours). An hour counts for
   * an item only when its low price AND its sell-side volume are both above zero.
   */
  public static Index build(List<HourBucket> buckets) {
    int hours = buckets == null ? 0 : buckets.size();
    TreeMap<Integer, Stats> out = new TreeMap<>();
    if (hours == 0) return new Index(0, out);
    // The grid, per item: the hour's low price and units (0 where it did not trade). Integers, as the archive is.
    TreeMap<Integer, long[][]> grid = new TreeMap<>();
    TreeMap<Integer, double[]> totals = new TreeMap<>(); // {traded, units}
    for (int i = 0; i < hours; i++) {
      HourBucket b = buckets.get(i);
      for (int r = 0; r < b.size(); r++) {
        long lo = b.avgLow(r), lv = b.lowVolume(r);
        if (lo == HourBucket.NONE || !(lo > 0) || !(lv > 0)) continue;
        int id = b.id(r);
        long[][] s = grid.computeIfAbsent(id, k -> new long[][]{new long[hours], new long[hours]});
        double[] t = totals.computeIfAbsent(id, k -> new double[2]);
        s[0][i] = lo;
        s[1][i] = lv;
        t[0]++;
        t[1] += lv;
      }
    }
    for (Map.Entry<Integer, long[][]> e : grid.entrySet()) {
      long[] lo = e.getValue()[0], lv = e.getValue()[1];
      double[] t = totals.get(e.getKey());
      Double[] recurrence = new Double[WINDOWS.length], unitsWithin = new Double[WINDOWS.length];
      int lastSamples = 0;
      for (int k = 0; k < WINDOWS.length; k++) {
        int w = WINDOWS[k];
        int samples = 0, matched = 0;
        double[] units = new double[Math.max(0, hours - w)];
        int n = 0;
        for (int i = 0; i + w < hours; i++) {
          long price = lo[i];
          if (!(price > 0)) continue;
          samples++;
          double available = 0;
          for (int j = i + 1; j <= i + w; j++) if (lo[j] > 0 && lo[j] <= price) available += lv[j];
          if (available > 0) matched++;
          units[n++] = available;
        }
        recurrence[k] = samples > 0 ? (double) matched / samples : null;
        unitsWithin[k] = samples > 0 ? upperMedian(Arrays.copyOf(units, n)) : null;
        lastSamples = samples;
      }
      out.put(e.getKey(), new Stats(hours, t[0], t[0] / hours, t[1] / (hours / 24.0), recurrence, unitsWithin, lastSamples));
    }
    return new Index(hours, out);
  }

  // The thin-market's median: the UPPER middle of the sorted values, never an average (Medians.upper's rule).
  private static double upperMedian(double[] v) {
    Arrays.sort(v);
    return v.length > 0 ? v[v.length / 2] : 0;
  }

  /** windowFor: the precomputed window nearest the player's own trade duration; 12 hours with none. */
  public static int windowFor(Double targetDurationMinutes) {
    double hours = targetDurationMinutes != null && JsValues.isFinite(targetDurationMinutes) && targetDurationMinutes > 0 ? targetDurationMinutes / 60 : 12;
    int best = WINDOWS[0];
    for (int w : WINDOWS) if (Math.abs(w - hours) < Math.abs(best - hours)) best = w;
    return best;
  }

  private static String plural(double n) {
    return n == 1 ? "" : "s";
  }

  /**
   * thinMarketNote: one warning sentence when a buy pick's own history says the price may simply not come back, or null.
   * {@code stats} null: the item is absent from the index -- the strongest warning when the archive is long enough
   * ({@code archivedHours} at least {@link #MIN_HOURS}), silence otherwise. Every parameter but {@code stats} may be null.
   */
  public static String note(Stats stats, String name, Double windowHours, Double quantity, Double archivedHours) {
    String who = name == null || name.isEmpty() ? "this item" : name;
    if (stats == null) {
      if (!(archivedHours != null && archivedHours >= MIN_HOURS)) return null;
      return "Warning: " + who + " did not trade at all in the last " + JsValues.gp(archivedHours) + " hours EVI has records for, "
        + "on either side of the market. There is no recent price to buy or sell it at, so an offer may sit indefinitely. "
        + "That is EVI's own record of the market, not a forecast.";
    }
    if (stats.hours < MIN_HOURS) return null;
    int w = windowOr12(windowHours);
    Double recurrence = stats.recurrence(w);
    if (recurrence == null) return null;
    boolean thin = stats.cadence < THIN_CADENCE || recurrence < THIN_RECURRENCE;
    if (!thin) return null;
    String perDay = stats.unitsPerDay >= 10 ? JsValues.gp(stats.unitsPerDay) : stripPointZero(JsValues.toFixed(stats.unitsPerDay, 1));
    Double availableBoxed = stats.unitsWithin(w);
    double available = availableBoxed == null ? Double.NaN : availableBoxed;
    Double wanted = quantity != null && JsValues.isFinite(quantity) && quantity > 0 ? quantity : null;
    return "Warning: " + who + " barely trades -- in " + JsValues.gp(stats.hoursTraded) + " of the last " + JsValues.gp(stats.hours) + " hours "
      + "(" + JsValues.text(JsValues.jsRound(stats.cadence * 100)) + "%), about " + perDay + " a day. Over those hours, a price like this one was matched again "
      + "within " + w + " hour" + (w == 1 ? "" : "s") + " only " + JsValues.text(JsValues.jsRound(recurrence * 100)) + "% of the time, with typically "
      + JsValues.gp(available) + " unit" + plural(available) + " available at or under it"
      + (wanted != null && available < wanted ? ", against the " + JsValues.gp(wanted) + " you would be buying" : "")
      + ". Your offer may simply sit unfilled. That is this item's own record, not a forecast.";
  }

  /**
   * thinMarketContext: the same figures as a plain statement rather than a warning, for every buy pick whose item EVI has
   * records for (the thresholds above are a cliff and real items sit on it). Facts only, no verdict; null when there is
   * nothing to say.
   */
  public static String context(Stats stats, Double windowHours, Double quantity) {
    if (stats == null || stats.hours < MIN_HOURS) return null;
    int w = windowOr12(windowHours);
    Double recurrence = stats.recurrence(w);
    if (recurrence == null) return null;
    Double availableBoxed = stats.unitsWithin(w);
    double available = availableBoxed == null ? Double.NaN : availableBoxed;
    Double wanted = quantity != null && JsValues.isFinite(quantity) && quantity > 0 ? quantity : null;
    return "Fill history: this item traded in " + JsValues.gp(stats.hoursTraded) + " of the last " + JsValues.gp(stats.hours) + " hours "
      + "(" + JsValues.text(JsValues.jsRound(stats.cadence * 100)) + "%), and a price like this one was matched again within " + w + " hour" + (w == 1 ? "" : "s") + " "
      + "in " + JsValues.text(JsValues.jsRound(recurrence * 100)) + "% of those cases, typically " + JsValues.gp(available) + " unit" + plural(available) + " "
      + "at or under it" + (wanted != null ? " (you would be buying " + JsValues.gp(wanted) + ")" : "") + ".";
  }

  /** {@code s.replace(/\.0$/, '')}. */
  static String stripPointZero(String s) {
    return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
  }
}

package com.evi.live.engine;

import com.evi.live.journal.Js;
import com.evi.live.journal.Tax;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * What EVI thinks of its own suggestion, as something the sidebar can draw (bridge/verdict.mjs
 * {@code suggestionVerdict}), and the headline enrichment server.mjs applies to every pick before it is sent (the
 * {@code enrich} closure: the verdict, the quoted profit, and the CAUTIOUS headline figure). Pure.
 *
 * <p>The verdict invents nothing: every line restates a figure a check already produced, and no verdict at all (null)
 * means "no opinion", never "fine". Lines are short on purpose (the 225px panel).
 *
 * <p>MINUS ZERO PRINTS AS "0" (the maintainer, 7 Oct 2026, fixed in JS first): a holding whose net rounded to minus zero
 * used to read "+-0 gp over what you paid", because {@code Math.round(-0).toLocaleString()} is "-0". The verdict's own
 * {@link #gp} folds only that one value; every other figure prints exactly as {@link JsValues#gp} does.
 */
public final class Verdict {
  private Verdict() {}

  public static final String CLEAR = "clear";
  public static final String CAUTION = "caution";
  public static final String WARN = "warn";

  /** One line of a verdict: passed (true), failed (false) or a plain fact (null). */
  public static final class Line {
    public final Boolean ok;
    public final String text;

    Line(Boolean ok, String text) {
      this.ok = ok;
      this.text = text;
    }
  }

  public static final class Result {
    public final String level;
    public final String label;
    public final List<Line> checks;

    Result(String level, String label, List<Line> checks) {
      this.level = level;
      this.label = label;
      this.checks = Collections.unmodifiableList(checks);
    }
  }

  /**
   * verdict.mjs's own {@code gp}: {@code Math.round(n).toLocaleString('en-US')} with MINUS ZERO folded into 0, so a net within
   * half a gp of break-even reads "+0", never "+-0". NaN and every other value print exactly as {@link JsValues#gp}.
   */
  static String gp(double n) {
    double r = JsValues.jsRound(n);
    return JsValues.localeUs(r == 0 ? 0.0 : r);
  }

  private static boolean finite(Double d) {
    return d != null && JsValues.isFinite(d);
  }

  /** suggestionVerdict: null for no suggestion, an item id of 0, or nothing measured. */
  public static Result suggestionVerdict(Pick s) {
    if (s == null || s.itemId == 0) return null;
    List<Line> checks = new ArrayList<>();
    String level = CLEAR;
    String label = null;
    double qty = s.quantity > 0 ? s.quantity : 1;
    double quotedNet = (double) (s.sellPrice - s.buyPrice - Tax.estimateUnitTax(s.itemId, s.sellPrice)) * qty;

    // A sell that would realise a loss outranks everything else. Warn, never block.
    if (s.lossIfSoldNow != null && s.lossIfSoldNow > 0) {
      List<Line> l = new ArrayList<>();
      l.add(new Line(false, "Down " + gp(s.lossIfSoldNow) + " gp at today's price"));
      if (s.breakEvenPrice != null) l.add(new Line(null, "Break-even after tax: " + gp(s.breakEvenPrice)));
      return new Result(WARN, "Selling now is a loss", l);
    }
    // A holding whose sell listing ENDED while EVI was not watching (8 Oct, a real case): it may have sold. Never a
    // profit and never green -- only what EVI saw, at CAUTION, like idle stock.
    if ("holding".equals(s.source) && s.endedUnseen != null) {
      checks.add(new Line(null, "Last seen listed at " + gp(s.endedUnseen.price)));
      checks.add(new Line(null, "Gone at your next login"));
      checks.add(new Line(null, "No sale seen, so no profit is claimed"));
      level = CAUTION;
      label = "Ended while EVI was away";
    }
    // A holding that is NOT a loss draws a card too (30 Sept: only the bad news used to).
    if ("holding".equals(s.source) && finite(s.netIfSoldNow) && s.netIfSoldNow >= 0) {
      checks.add(new Line(true, "+" + gp(s.netIfSoldNow) + " gp over what you paid"));
      if (s.breakEvenPrice != null) checks.add(new Line(null, "Break-even after tax: " + gp(s.breakEvenPrice)));
      label = label != null ? label : "Above break-even"; // JS: label || 'Above break-even'
    }
    // Stock EVI never watched being bought: there is no profit to state, only what the stack is worth today.
    if ("inventory".equals(s.source)) {
      double worth = (double) s.sellPrice * qty;
      if (worth > 0) checks.add(new Line(null, "Worth ~" + gp(worth) + " at today's price"));
      checks.add(new Line(null, "No buy on record, so no profit is claimed"));
      level = CLEAR.equals(level) ? CAUTION : level;
      label = label != null ? label : "Not bought through EVI";
    }
    // The margin at the price buyers have actually been paying, against the quoted spread.
    SellSupport.Detail support = s.sellSupport;
    if (support != null && finite(support.netAtAverage)) {
      double supportedTotal = JsValues.jsRound(support.netAtAverage * qty);
      if (supportedTotal < quotedNet * 0.7) {
        level = CAUTION;
        label = "Worth less than it looks";
        checks.add(new Line(false, gp(supportedTotal) + " at what buyers really pay"));
        if (finite(support.averagePaid) && finite(support.units))
          checks.add(new Line(null, gp(support.units) + " paid ~" + gp(support.averagePaid) + " in " + (support.hours == null ? "null" : support.hours) + "h"));
      } else if (supportedTotal >= quotedNet) {
        checks.add(new Line(true, "Buyers paying more than quoted"));
      } else {
        checks.add(new Line(true, "Holds up at ~" + gp(SellSupport.nullAsZero(support.averagePaid))));
      }
    }
    // The support is mostly HISTORY: the headline has already been capped on it, so say why.
    if (support != null && finite(support.staleness) && finite(support.latestPaid)) {
      if (support.staleness >= SellSupport.STALE_SUPPORT_RATIO) {
        level = CLEAR.equals(level) ? CAUTION : level;
        label = label != null ? label : "Buyers have moved on";
        checks.add(new Line(false, "Now paying ~" + gp(support.latestPaid) + ", not " + gp(SellSupport.nullAsZero(support.averagePaid))));
      } else if (support.staleness >= SellSupport.SOFT_STALE_SUPPORT_RATIO) {
        checks.add(new Line(null, "Buyers now paying ~" + gp(support.latestPaid)));
      }
    }
    // Can this price be bought again at all: the fill-history reading.
    if (s.fillHistoryHoursTraded != null && s.fillHistoryHours != null && s.fillHistoryHours > 0) {
      double share = (double) s.fillHistoryHoursTraded / s.fillHistoryHours;
      if (share < 0.25) {
        level = CLEAR.equals(level) ? CAUTION : level;
        label = label != null ? label : "Rarely traded";
        checks.add(new Line(false, "Traded only " + s.fillHistoryHoursTraded + " of " + s.fillHistoryHours + " hours"));
      } else {
        checks.add(new Line(true, "Traded " + s.fillHistoryHoursTraded + " of " + s.fillHistoryHours + " hours"));
      }
    }
    if ("personal".equals(s.source) && s.trades != null && s.trades > 0)
      checks.add(new Line(true, "Your " + s.trades + " flip" + (s.trades == 1 ? "" : "s") + " here"));
    // Demoted for a reason none of the above named: say so rather than show a clean card.
    if (Boolean.TRUE.equals(s.demoted) && CLEAR.equals(level)) {
      level = CAUTION;
      label = "Shown because nothing passed";
    }
    if (checks.isEmpty() && CLEAR.equals(level)) return null;
    return new Result(level, label != null ? label : "Every check passed", checks.size() > 4 ? checks.subList(0, 4) : checks);
  }

  /**
   * The server's {@code enrich}: the fill-history reading (when there is one), the verdict, the quoted profit, the
   * headline figure -- the LOWER of the quoted spread and the margin at the price buyers pay (capped at what they pay NOW
   * when the support is stale) -- and the stale flag on the reading. Idle stock gets no headline: with no cost basis
   * the spread is not a profit (30 Sept). Mutates {@code s}, as the JS does.
   *
   * @param hoursTraded the thin-market reading's hours traded (null: none)
   */
  public static void enrich(Pick s, Integer hoursTraded, Integer hours) {
    if (s == null) return;
    if (hoursTraded != null && hours != null) {
      s.fillHistoryHoursTraded = hoursTraded;
      s.fillHistoryHours = hours;
    }
    Result v = suggestionVerdict(s);
    if (v != null) s.verdict = v;
    long q = s.quantity > 0 ? s.quantity : 1;
    long quoted = Js.multiply(s.sellPrice - s.buyPrice - Tax.estimateUnitTax(s.itemId, s.sellPrice), q);
    SellSupport.Detail support = s.sellSupport;
    Double honest = SellSupport.supportedPriceForHeadline(support);
    Long supported = support != null && finite(support.netAtAverage) && finite(honest)
      ? Js.round((honest - Tax.estimateUnitTax(s.itemId, honest) - s.buyPrice) * q) : null;
    if (support != null && SellSupport.supportIsStale(support)) support.stale = true;
    s.quotedProfit = quoted;
    // Idle stock, and a holding whose listing ended unseen: neither has a profit EVI can state.
    s.expectedProfit = "inventory".equals(s.source) || s.endedUnseen != null ? null : Policy.headlineProfit(quoted, supported);
  }
}

package com.evi.live.engine;

import com.evi.live.market.HourBucket;
import com.evi.live.market.MarketAggregates;

/**
 * One item's row of the latest hour ({@code volumes[String(itemId)]} in suggestions.mjs: the Wiki /1h data entry),
 * read out of the price layer's {@link HourBucket}. A missing average stays {@link HourBucket#NONE}; a missing
 * volume is 0, exactly as the JS reads {@code v.highPriceVolume || 0}. An item ABSENT from the hour is a null row,
 * never a row of zeros: absent means "no reading" and a listed zero is a measurement, and the engine keeps the two
 * apart everywhere (see {@link Sizing#sizingLiquidityFor}).
 */
public final class VolumeRow {
  public final long avgHigh;
  public final long highVolume;
  public final long avgLow;
  public final long lowVolume;

  public VolumeRow(long avgHigh, long highVolume, long avgLow, long lowVolume) {
    this.avgHigh = avgHigh;
    this.highVolume = highVolume;
    this.avgLow = avgLow;
    this.lowVolume = lowVolume;
  }

  /** The item's row of the hour, or null when the hour is missing or the item is absent from it. */
  public static VolumeRow of(HourBucket hour, int itemId) {
    if (hour == null) return null;
    int i = hour.indexOf(itemId);
    if (i < 0) return null;
    return new VolumeRow(hour.avgHigh(i), hour.highVolume(i), hour.avgLow(i), hour.lowVolume(i));
  }

  /** {@code volumeReadingFor}: the thinner side, or null with no row. The same answer as {@link MarketAggregates#volumeReadingFor}. */
  public static Long reading(VolumeRow row) {
    return row == null ? null : Math.min(row.highVolume, row.lowVolume);
  }

  /** {@code Math.min(v.highPriceVolume || 0, v.lowPriceVolume || 0)}, or 0 with no row: the liquidity a duration check reads. */
  public static long liquidity(VolumeRow row) {
    return row == null ? 0 : Math.min(row.highVolume, row.lowVolume);
  }
}

