/**
 * THE ONE COMPOSITION of {@link Engine#decide}'s inputs from the plugin's own layers: the journal ({@link PluginJournal}), the
 * price layer ({@link PriceDataService}) and its archive, and a preferences file, for the in-process engine
 * ({@link InProcessEngine}, which answers the sidebar).
 *
 * <p>The statics are pure. An INSTANCE holds the archive readings ONE consumer thread keeps, exactly as the bridge keeps them
 * (see {@link #refresh}); it is not thread-safe and belongs to that consumer's own thread.
 *
 * <p>No network of its own, and no file but the preferences file: the prices are the ones the price layer already fetched
 * (all-items endpoints only), the archive is read on the price layer's own thread ({@link PriceDataService#readHours}) and the
 * journal on the journal's ({@link PluginJournal#engineView}). The sell-support reading uses the archive, never a per-item
 * Wiki request.
 */
public final class EngineFeed {
  /** archive.recentHourly keeps this many hours (priceArchive.mjs RECENT_HOURS); the sell-support window is cut from them. */
  public static final int RECENT_HOURS = 26;
  /** thinMarketIndex: two weeks of the archive, rebuilt at most every six hours (server.mjs). */
  public static final long THIN_SPAN_S = 14L * 86400;
  public static final long THIN_EVERY_MS = 6L * 3600_000;

  // ------------------------------------------------------------------------------------------- the inputs

  /** The plugin's journal: what {@link Engine#decide} reads from it at one moment. A null future: no journal running. */
  public interface JournalSource {
    CompletableFuture<PluginJournal.EngineView> view(long nowMs);
  }

  /** The plugin's price layer: its snapshot (null when none runs), and its archive's hours from a time on (oldest first). */
  public interface MarketSource {
    Market market(long nowMs);

    CompletableFuture<List<HourBucket>> hoursFrom(long fromTs);
  }

  /** What the price layer knew at one moment, as the engine reads it (null fields: not available yet). */
  public static final class Market {
    public final LatestPrices latest;
    public final long latestFetchedAtMs;
    public final HourBucket latestHour;
    public final ItemCatalog catalog;
    /** Null before the first build: the engine then sizes on the live hour, as the bridge does before its cache is warm. */
    public final Map<Integer, Long> typical;
    public final Map<Integer, MarketAggregates.RobustPrice> robust;
    public final long newestStoredTs;
    public final int hoursStored, windowHours, robustHours, typicalHours;
    /** {@link MarketSnapshot#archiveRevision}: moves whenever the price layer learns of another hour, older ones included. */
    public final long archiveRevision;
    /** {@link MarketSnapshot#hoursUnavailable}: hours of the window the Wiki would not give this session. */
    public final int hoursUnavailable;
    /** {@link MarketSnapshot#catchingUp}: hours of the window are still to be FETCHED this session. */
    public final boolean catchingUp;
    /** {@link MarketSnapshot#readingsHoursStored}: the window's stored hours when the readings the engine ranks on were built. */
    public final int readingsHoursStored;

    /** No hour given up, catching up while any hour is missing, and readings over every stored hour. */
    public Market(LatestPrices latest, long latestFetchedAtMs, HourBucket latestHour, ItemCatalog catalog, Map<Integer, Long> typical,
                  Map<Integer, MarketAggregates.RobustPrice> robust, long newestStoredTs, int hoursStored, int windowHours, int robustHours, int typicalHours,
                  long archiveRevision) {
      this(latest, latestFetchedAtMs, latestHour, catalog, typical, robust, newestStoredTs, hoursStored, windowHours, robustHours, typicalHours,
        archiveRevision, 0, hoursStored < windowHours, hoursStored);
    }

    public Market(LatestPrices latest, long latestFetchedAtMs, HourBucket latestHour, ItemCatalog catalog, Map<Integer, Long> typical,
                  Map<Integer, MarketAggregates.RobustPrice> robust, long newestStoredTs, int hoursStored, int windowHours, int robustHours, int typicalHours,
                  long archiveRevision, int hoursUnavailable, boolean catchingUp, int readingsHoursStored) {
      this.latest = latest;
      this.latestFetchedAtMs = latestFetchedAtMs;
      this.latestHour = latestHour;
      this.catalog = catalog;
      this.typical = typical;
      this.robust = robust == null ? Collections.emptyMap() : robust;
      this.newestStoredTs = newestStoredTs;
      this.hoursStored = hoursStored;
      this.windowHours = windowHours;
      this.robustHours = robustHours;
      this.typicalHours = typicalHours;
      this.archiveRevision = archiveRevision;
      this.hoursUnavailable = hoursUnavailable;
      this.catchingUp = catchingUp;
      this.readingsHoursStored = readingsHoursStored;
    }

    /** From the price layer's published snapshot. */
    public static Market of(MarketSnapshot s, long nowMs) {
      boolean built = s.readingsBuiltAtMs != 0;
      return new Market(s.latest, s.latestFetchedAtMs, s.latestHour(nowMs), s.catalog, built ? s.typical : null, s.robust, s.newestStoredTs,
        s.hoursStored, s.windowHours, s.robustHours, s.typicalHours, s.archiveRevision, s.hoursUnavailable, s.catchingUp, s.readingsHoursStored);
    }
  }

  /** The plugin's journal, wherever the plugin currently keeps it (it is replaced on every startUp). */
  public static JournalSource journalOf(Supplier<PluginJournal> journal) {
    return now -> {
      PluginJournal j = journal.get();
      return j == null ? null : j.engineView(now);
    };
  }

  /** The plugin's price layer, wherever the plugin currently keeps it. */
  public static MarketSource marketOf(Supplier<PriceDataService> prices) {
    return new MarketSource() {
      @Override public Market market(long nowMs) {
        PriceDataService p = prices.get();
        return p == null ? null : Market.of(p.snapshot(), nowMs);
      }

      @Override public CompletableFuture<List<HourBucket>> hoursFrom(long fromTs) {
        PriceDataService p = prices.get();
        if (p != null) return p.readHours(fromTs);
        CompletableFuture<List<HourBucket>> f = new CompletableFuture<>();
        f.completeExceptionally(new IllegalStateException("the price layer is not running"));
        return f;
      }
    };
  }

  // ------------------------------------------------------------------------------------------- pure

  /** The engine's market inputs from the price layer's: the crash watch is absent (no five-minute stream in the plugin yet). */
  public static Engine.MarketData marketData(Market m, List<HourBucket> recentHours, ThinMarket.Index thin, Engine.FillModelSource fill) {
    Engine.MarketData d = new Engine.MarketData();
    d.latest = m.latest;
    d.latestHour = m.latestHour;
    d.catalog = m.catalog;
    d.typicalVolumes = m.typical;
    d.rankPrices = m.robust;
    d.recentHours = recentHours;
    d.thin = thin;
    d.crashWatch = null;
    d.fillModel = fill;
    return d;
  }

  /**
   * One request decided from the plugin's own inputs: the query's account's view (which MUST be the account the query names --
   * {@link AccountView#of} on {@code query.get("account")}), the journal's shared parts with the profit line's reset time, and no
   * hooks but an optional per-item series (production passes none: the archive serves the sell-support reading; the parity
   * tests pass the bridge's recorded series). No forecast, cushion or correlation (all off by default in the bridge).
   */
  public static Engine.Response decide(Engine.Query query, AccountView view, StoreState state, Collection<Offer> journalOffers, Engine.MarketData market,
                                       Engine.Prefs prefs, Engine.SellSeries series, Long profitSince, long now) {
    return decide(query, view, state, journalOffers, market, prefs, series, null, profitSince, now);
  }

  /**
   * As {@link #decide(Engine.Query, AccountView, StoreState, Collection, Engine.MarketData, Engine.Prefs, Engine.SellSeries, Long, long)}, with
   * the opt-in forecast hook ({@link #forecastHook}: the ~6 hours setting read from the plugin's archive; null: none). No
   * cushion or correlation.
   */
  public static Engine.Response decide(Engine.Query query, AccountView view, StoreState state, Collection<Offer> journalOffers, Engine.MarketData market,
                                       Engine.Prefs prefs, Engine.SellSeries series, Engine.ForecastHook forecast, Long profitSince, long now) {
    Engine.Hooks hooks = new Engine.Hooks();
    hooks.sellSeries = series;
    hooks.forecast = forecast;
    return Engine.decide(query, view, Engine.SharedJournal.of(state, profitSince), journalOffers, market, prefs, hooks, now);
  }

  /**
   * A preferences file (the shape of the bridge's data/preferences.json), else the bridge's defaults. {@code source[0]} says
   * which, naming the file as {@code label}: the file, "defaults (no label)", or "defaults (label unreadable: Why)".
   */
  public static Engine.Prefs readPreferences(Filepath file, String label, Function<String, JsonElement> parser, String[] source) {
    if (!file.isFile()) {
      source[0] = "defaults (no " + label + ")";
      return Engine.Prefs.DEFAULT;
    }
    try (InputStream in = file.openInputStream()) {
      Engine.Prefs p = Engine.Prefs.fromJson(parser.apply(new String(in.readAllBytes(), StandardCharsets.UTF_8)));
      source[0] = label;
      return p;
    } catch (IOException | RuntimeException e) {
      source[0] = "defaults (" + label + " unreadable: " + e.getClass().getSimpleName() + ")";
      return Engine.Prefs.DEFAULT;
    }
  }

  /**
   * The preferences with the plugin's own Block-button list added (the plugin keeps those blocks itself, per character; the old
   * companion app kept them in this very file's {@code blocked}). The engine reads the list only as a set of items never to BUY, so the union is
   * kept sorted; nothing else in the preferences changes. {@code extra} null or empty: {@code prefs} itself.
   */
  public static Engine.Prefs withBlocked(Engine.Prefs prefs, java.util.Collection<Integer> extra) {
    if (extra == null || extra.isEmpty()) return prefs;
    java.util.TreeSet<Integer> all = new java.util.TreeSet<>(prefs.blocked);
    for (Integer id : extra) if (id != null && id > 0) all.add(id);
    return new Engine.Prefs(prefs.focus, new java.util.ArrayList<>(all), prefs.spread, prefs.captureCap);
  }

  /** Waits for a layer's answer on the CALLER's thread (a consumer's own), bounded. A null future: the layer is not running. */
  public static <T> T await(CompletableFuture<T> f, long ms) throws InterruptedException, ExecutionException, TimeoutException {
    if (f == null) throw new IllegalStateException("not running");
    return f.get(ms, TimeUnit.MILLISECONDS);
  }

  /** A failure's short name and message, for a log line. */
  public static String why(Throwable e) {
    Throwable c = e instanceof ExecutionException && e.getCause() != null ? e.getCause() : e;
    return c.getClass().getSimpleName() + (c.getMessage() == null ? "" : ": " + c.getMessage());
  }

  // ------------------------------------------------------------------------------------------- one consumer's readings

  private final MarketSource market;
  private final long archiveWaitMs;
  private List<HourBucket> recent;
  private long recentFor;
  private ThinMarket.Index thin;
  private long thinAt;
  /** The thin index was built while hours of the window were still to be fetched ({@link Market#catchingUp}). */
  private boolean thinBuiltCatchingUp;
  /** The six-hour forecast's series per item, for one archive state and one newest hour (built on the first forecast asked). */
  private Forecasts.Index forecastIndex;
  private long forecastRevision = Long.MIN_VALUE, forecastEnd = Long.MIN_VALUE;
  /** The Wiki's per-item hourly series holds 365 points: the forecast reads the archive over the same span (it keeps 337). */
  public static final long FORECAST_SPAN_S = 364L * 3600;
  /** The hourly fill model over the archive (the bridge's playerFillModel cache). */
  public final FillModelCache fill;

  /** @param archiveWaitMs how long one archive read may take before it counts as failed */
  public EngineFeed(MarketSource market, long archiveWaitMs) {
    this.market = market;
    this.archiveWaitMs = archiveWaitMs;
    this.fill = new FillModelCache(from -> await(market.hoursFrom(from), archiveWaitMs));
  }

  /**
   * The archive readings the engine needs beside the snapshot, read on the price layer's thread and kept as the bridge keeps
   * them. THE LAST 26 HOURS again whenever the price layer has learned of another hour ({@link Market#archiveRevision}): the
   * bridge's archive.recentHourly takes every hour it stores, backfilled ones included, and the plugin backfills NEWEST
   * FIRST, so the older hours of a gap arrive after the newest -- keyed on the newest stored hour, the window would miss them
   * until the next hour closed. THE THIN INDEX as server.mjs thinMarketIndex keeps it: a built index for six hours, but a
   * NULL one (under {@link ThinMarket#MIN_HOURS} archived hours, or a failed read) is built again on the next poll. A fresh
   * archive passes 72 hours minutes after the first poll; a null cached for six hours would differ from the bridge on every
   * poll meanwhile (the decide-thin-index-retried transcript pins the bridge's rule). An index built while the archive was
   * still CATCHING UP is built once more when the catch-up ends: the plugin backfills newest first, so the older hours of a
   * gap are missing from it, and kept for six hours it read "N of the last 330 hours" all morning after a night away
   * (10 Oct). The bridge never meets this, its archive being filled around the clock. A failed read is noted in {@code notes}.
   */
  public void refresh(Market m, long at, JsonObject notes) {
    long nowS = Math.floorDiv(at, 1000L);
    if (recent == null || recentFor != m.archiveRevision) {
      try {
        recent = await(market.hoursFrom(nowS - RECENT_HOURS * 3600L), archiveWaitMs);
        recentFor = m.archiveRevision;
      } catch (Exception e) {
        recent = null;
        notes.addProperty("recentHoursFailed", why(e));
      }
    }
    if (thin == null || at - thinAt >= THIN_EVERY_MS || (thinBuiltCatchingUp && !m.catchingUp)) {
      thinAt = at;
      thinBuiltCatchingUp = m.catchingUp;
      try {
        thin = SafetyChecks.thinIndex(await(market.hoursFrom(nowS - THIN_SPAN_S), archiveWaitMs));
      } catch (Exception e) {
        thin = null;
        notes.addProperty("thinIndexFailed", why(e));
      }
    }
  }

  /** The last 26 hours as last read (null: none read, or the read failed). */
  public List<HourBucket> recent() {
    return recent;
  }

  /** The thin index as last built (null: too little archive, or the read failed). */
  public ThinMarket.Index thin() {
    return thin;
  }

  /**
   * THE OPT-IN FORECAST from the plugin's own hourly archive (8 Oct 2026, approved): the ~6 hours setting only -- the one the
   * fill-outlook table was measured for, and the one whose series is hourly. Its series is the item's archived hours up to and
   * including {@code newestTs} (the newest stored hour). The ~1 hour and Overnight settings were removed in 4.0.0: nothing asks for them.
   *
   * <p>The archive is read on the price layer's thread the first time a forecast is asked for, and the per-item series kept
   * until the archive learns of another hour or {@code newestTs} moves; a failed read is no forecast (as the bridge's failed
   * fetch is), noted in {@code notes}, and not retried for that archive state. Nothing is read while the setting is off.
   */
  public Engine.ForecastHook forecastHook(Market m, long newestTs, JsonObject notes) {
    return (itemId, horizon) -> {
      if (!Forecasts.SIX_HOURS.equals(horizon)) return null;
      Forecasts.Index idx = forecastIndex(m, newestTs, notes);
      return idx == null ? null : Forecasts.forHook(Forecasts.forecastFromSeries(idx.series(itemId), horizon), horizon);
    };
  }

  private Forecasts.Index forecastIndex(Market m, long newestTs, JsonObject notes) {
    if (newestTs == Long.MIN_VALUE) return null;
    if (forecastRevision == m.archiveRevision && forecastEnd == newestTs) return forecastIndex;
    forecastRevision = m.archiveRevision;
    forecastEnd = newestTs;
    try {
      forecastIndex = Forecasts.Index.build(await(market.hoursFrom(newestTs - FORECAST_SPAN_S), archiveWaitMs), newestTs);
    } catch (Exception e) {
      forecastIndex = null;
      if (notes != null) notes.addProperty("forecastFailed", why(e));
    }
    return forecastIndex;
  }

  /** The engine's market inputs: {@code m} with this consumer's archive readings and fill model. */
  public Engine.MarketData marketData(Market m) {
    return marketData(m, recent, thin, fill);
  }
}

package com.evi.live.inprocess;

import com.evi.live.engine.AccountView;
import com.evi.live.engine.Engine;
import com.evi.live.engine.ResponseJson;
import com.evi.live.journal.Offer;
import com.evi.live.journal.PluginJournal;
import com.evi.live.journal.Tax;
import com.evi.live.market.MarketAggregates;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;
import net.runelite.client.util.Filepath;

/**
 * THE IN-PROCESS ENGINE: the plugin answering its own suggestion poll, from its own journal and the OSRS Wiki's public prices.
 *
 * <p>Each poll's query is handed to {@link #request}, which returns at once;
 * the work runs on ONE plugin-owned daemon thread, {@value #THREAD_NAME}: the journal is read on the journal's own thread,
 * the archive on the price layer's, {@link Engine#decide} runs here, and the body is written by the production serialiser
 * ({@link ResponseJson}) -- the answer shape the plugin's poll path, DTOs and panel read.
 * The composition is {@link EngineFeed}'s. This thread refuses to run on the client
 * thread or the Swing EDT. At most one request waits: a newer one replaces it (the older one's future completes with null).
 *
 * <p>THE FIRST-RUN GATE ON BUYS (plan decision 7, risk 4: ranking on a short window was measured less safe). Until the
 * readings the engine ranks on rest on {@link #BASIS_HOURS} hours of the plugin's own archive -- the engine's own constant,
 * {@link MarketAggregates#ROBUST_PRICE_HOURS} -- the query is asked WITHOUT the buy tiers ({@link #withoutBuyTiers}): no
 * history, market, step-down or further positions, so no buy and no "reachable" figure. Everything about what the player
 * already has still speaks from its own data: the holding and idle-stock tiers (they price from /latest), the open item's
 * price, the running offers' prices and fill estimates, and the whole advice channel (relist, below break-even, margin
 * gone, buy progress, holdings). Nothing is fabricated for the missing hours; the sidebar says how many are in
 * ({@link #backfillLine}).
 *
 * <p>No network of its own and no file but an optional {@value #PREFERENCES} in the plugin's data folder (the bridge's
 * preferences.json shape: spread, focus, blocked items, capture cap; without it, the bridge's defaults) and, when the plugin hands
 * it {@link SuggestionRecords}, the suggestion log those keep (the id "I took this one" echoes, as server.mjs logs each answer).
 * The sidebar's Block list is handed in too and merged into the preferences' blocked items at every decide (decision 12): the
 * list of the account the query names, only (blocks are per character since 8 Oct 2026; the bridge's list is one for the machine).
 */
public final class InProcessEngine implements Answerer {
  public static final String THREAD_NAME = "evi-engine";
  /** The optional preferences file, in the plugin's data folder. */
  public static final String PREFERENCES = "preferences.json";
  /** The hours the engine's steady prices are built over: buys wait until the readings rest on this many. */
  public static final int BASIS_HOURS = MarketAggregates.ROBUST_PRICE_HOURS;
  static final long JOURNAL_WAIT_MS = 30_000;
  static final long ARCHIVE_WAIT_MS = 120_000;
  /**
   * How old the latest prices may be before buys are held back (review, 10 Oct; the maintainer chose ten minutes). They arrive about
   * once a minute while logged in and are kept when a fetch fails, so past this the Wiki is not answering (or the player was
   * logged out) and a buy would be quoted from old prices. The market tier drops prints over an hour old item by item; the
   * history tier had no such check. Sells and the advice about the player's own offers still speak.
   */
  public static final long STALE_PRICES_MS = 10 * 60_000L;

  /** One answer: the body the bridge would have sent, or why there is none, and what the sidebar says about price data. */
  public static final class Answer {
    /** The query this answers. */
    public final String query;
    /** The suggestion body ({@code GET /api/suggestion}'s shape), or null when there is none ({@link #unavailable} says why). */
    public final String body;
    /** A plain sentence for the suggestion card when there is no body; null when there is one. */
    public final String unavailable;
    /** The sidebar's price-history line while buys wait for the basis; null once they no longer do (or nothing is known). */
    public final String backfillLine;
    /** Whether the buy tiers were asked. */
    public final boolean buysReady;
    /** When the latest prices were fetched (epoch ms), or 0 before any. */
    public final long latestFetchedAtMs;
    /** The buy tiers were not asked because the latest prices are older than {@link #STALE_PRICES_MS}. */
    public final boolean pricesStale;

    public Answer(String query, String body, String unavailable, String backfillLine, boolean buysReady, long latestFetchedAtMs) {
      this(query, body, unavailable, backfillLine, buysReady, latestFetchedAtMs, false);
    }

    public Answer(String query, String body, String unavailable, String backfillLine, boolean buysReady, long latestFetchedAtMs,
                  boolean pricesStale) {
      this.pricesStale = pricesStale;
      this.query = query;
      this.body = body;
      this.unavailable = unavailable;
      this.backfillLine = backfillLine;
      this.buysReady = buysReady;
      this.latestFetchedAtMs = latestFetchedAtMs;
    }
  }

  // ------------------------------------------------------------------------------------------- pure

  /** Whether the readings the engine ranks on rest on the full basis: the window's stored hours when they were BUILT. */
  public static boolean buysReady(EngineFeed.Market m) {
    return m != null && m.readingsHoursStored >= BASIS_HOURS;
  }

  /**
   * The sidebar's line while buys wait for the basis (null once they do not). ASCII only; a market-wide count of hours, never
   * anything from the player's own trading.
   */
  public static String backfillLine(EngineFeed.Market m) {
    if (m == null || buysReady(m)) return null;
    int have = Math.min(Math.max(0, m.hoursStored), BASIS_HOURS);
    if (!m.catchingUp && m.hoursStored < BASIS_HOURS && m.hoursUnavailable > 0)
      return "Price history: " + have + " of " + BASIS_HOURS + " hours. The OSRS Wiki did not send the rest this time; EVI asks again"
        + " when RuneLite next starts. Buy suggestions start once it is complete.";
    return "Loading price history: " + have + " of " + BASIS_HOURS + " hours. Buy suggestions start when it's done.";
  }

  /** Whether the latest prices are too old to quote a buy from at {@code now}: none at all counts as not stale (nothing is quoted). */
  public static boolean pricesStale(long latestFetchedAtMs, long now) {
    return latestFetchedAtMs > 0 && now - latestFetchedAtMs > STALE_PRICES_MS;
  }

  /** The sidebar line while buys wait for fresh prices. ASCII only. */
  public static String staleLine(long latestFetchedAtMs, long now) {
    long minutes = Math.max(0, (now - latestFetchedAtMs) / 60_000L);
    return "The latest prices from the OSRS Wiki are " + minutes + " minutes old. Buy suggestions are paused until fresh prices"
      + " arrive (they load while you are logged in).";
  }

  /**
   * The query with the buy tiers switched off: {@code includeMarket} dropped and {@code source=market} (so the history tier is
   * not asked either). Under those two the engine runs no history chain, no market tier, no Auto step-down, no further
   * positions and no reachable probe; every sell-side tier and the advice channel are untouched.
   */
  public static String withoutBuyTiers(String query) {
    StringBuilder out = new StringBuilder();
    String q = query == null ? "" : query.startsWith("?") ? query.substring(1) : query;
    for (String part : q.split("&", -1)) {
      if (part.isEmpty()) continue;
      Engine.Query one = Engine.Query.parse(part); // the name as the engine decodes it (URLSearchParams)
      if (one.has("includeMarket") || one.has("source")) continue;
      if (out.length() > 0) out.append('&');
      out.append(part);
    }
    if (out.length() > 0) out.append('&');
    return out.append("source=market").toString();
  }

  /**
   * The break-even sell price of each of this account's live SELL offers whose cost basis the journal knows -- exactly the
   * figure the relist advice compares the market with ({@link Tax#breakEvenSellPrice} on the view's cost basis). The plugin
   * reads it to give each offer ONE voice: below break-even the relist sentence, never its own "take the current price".
   */
  public static Map<Integer, Long> sellBreakEven(AccountView view) {
    Map<Integer, Long> out = new TreeMap<>();
    for (Offer o : view.liveSells) {
      Double paid = view.costBasis.get(o.itemId);
      Long be = paid != null && paid > 0 ? Tax.breakEvenSellPrice(o.itemId, paid) : null;
      if (be != null) out.put(o.itemId, be);
    }
    return out;
  }

  // ------------------------------------------------------------------------------------------- the thread

  private final class Job implements Runnable {
    final String query;
    final long at;
    final CompletableFuture<Answer> done = new CompletableFuture<>();

    Job(String query, long at) {
      this.query = query;
      this.at = at;
    }

    @Override public void run() {
      InProcessEngine.this.run(this);
    }
  }

  private final Filepath pluginDir;
  private final EngineFeed.JournalSource journal;
  private final EngineFeed.MarketSource market;
  private final Function<String, JsonElement> parser;
  private final Consumer<String> log;
  private final BooleanSupplier onUiThread;
  private final Supplier<Long> profitSince;
  /** Null in production (the archive serves the sell-support reading; no per-item request is ever made). */
  private final Engine.SellSeries series;
  /** The plugin's own Block-button list for the account a query names (null/"" for none), read at every decide. Per character. */
  private final Function<String, ? extends java.util.Collection<Integer>> blocked;
  /** The suggestion ids and "I took this one" (null: no id is issued, as before decision 12's persistence). */
  private final SuggestionRecords records;
  /** server.mjs lastInventory: the bag the idle-stock tier last read, per query account ("" for none), with when. */
  private final Map<String, Reading> lastInventory = new java.util.concurrent.ConcurrentHashMap<>();

  private static final class Reading {
    final Map<Integer, Double> items;
    final long at;

    Reading(Map<Integer, Double> items, long at) {
      this.items = items;
      this.at = at;
    }
  }

  /** server.mjs /personal-use: a bag read more than this long ago is ignored (the mark falls back to the blanket kind). */
  public static final long KEPT_FRESH_MS = 60_000;
  private final ThreadPoolExecutor executor;
  private volatile Thread thread;
  private volatile boolean closed;
  /** How many times {@link Engine#decide} ran, and on which thread it last did (diagnostics and tests). */
  private volatile int decided;
  private volatile String decidedOn;

  // ---- engine thread only
  private final EngineFeed feed;

  /**
   * @param pluginDir   the plugin's data folder (only {@value #PREFERENCES} is read from it)
   * @param parser      JSON text to a tree: the plugin passes the client's injected Gson
   * @param log         one line of local diagnostics (the client log)
   * @param onUiThread  true on the client thread or the Swing EDT, where this engine refuses to run
   * @param profitSince the player's last profit-line reset (epoch ms), or null for never
   */
  public InProcessEngine(Filepath pluginDir, EngineFeed.JournalSource journal, EngineFeed.MarketSource market, Function<String, JsonElement> parser,
                         Consumer<String> log, BooleanSupplier onUiThread, Supplier<Long> profitSince) {
    this(pluginDir, journal, market, parser, log, onUiThread, profitSince, null);
  }

  /**
   * TESTS ONLY: as above, with a per-item series for the sell-support reading -- the parity test hands in the bridge's recorded
   * Wiki series so the transcripts whose buys needed one can be replayed. The plugin never passes one: it makes no per-item request.
   */
  public InProcessEngine(Filepath pluginDir, EngineFeed.JournalSource journal, EngineFeed.MarketSource market, Function<String, JsonElement> parser,
                         Consumer<String> log, BooleanSupplier onUiThread, Supplier<Long> profitSince, Engine.SellSeries series) {
    this(pluginDir, journal, market, parser, log, onUiThread, profitSince, series, account -> java.util.Collections.emptyList(), null);
  }

  /**
   * The plugin's engine with the sidebar's stores (SELF-CONTAINED decision 12): {@code blocked}, the Block button's items of the
   * account a query names (merged into the preferences' blocked list at every decide, for that query only), and {@code records}, which issues the suggestion's id and reads back
   * whether it was taken. {@code series}: tests only, as above.
   */
  public InProcessEngine(Filepath pluginDir, EngineFeed.JournalSource journal, EngineFeed.MarketSource market, Function<String, JsonElement> parser,
                         Consumer<String> log, BooleanSupplier onUiThread, Supplier<Long> profitSince, Engine.SellSeries series,
                         Function<String, ? extends java.util.Collection<Integer>> blocked, SuggestionRecords records) {
    this.series = series;
    this.blocked = blocked == null ? account -> java.util.Collections.emptyList() : blocked;
    this.records = records;
    this.pluginDir = pluginDir;
    this.journal = journal;
    this.market = market;
    this.parser = parser;
    this.log = log;
    this.onUiThread = onUiThread;
    this.profitSince = profitSince;
    this.feed = new EngineFeed(market, ARCHIVE_WAIT_MS);
    this.executor = new ThreadPoolExecutor(1, 1, 0L, TimeUnit.MILLISECONDS, new ArrayBlockingQueue<>(1), r -> {
      Thread t = new Thread(r, THREAD_NAME);
      t.setDaemon(true); // never holds the client open
      thread = t;
      return t;
    }, (r, ex) -> {
      if (ex.isShutdown()) {
        ((Job) r).done.complete(null);
        return;
      }
      Runnable waiting = ex.getQueue().poll(); // the newest request replaces the one still waiting
      if (waiting != null) ((Job) waiting).done.complete(null);
      if (!ex.getQueue().offer(r)) ((Job) r).done.complete(null);
    });
  }

  /**
   * Hands one poll's query over and returns at once (any thread; the plugin calls it from its poll thread). The future
   * completes with the answer, or with null if a newer request replaced this one or the engine is shut down.
   */
  @Override public CompletableFuture<Answer> request(String query, long at) {
    Job j = new Job(query == null ? "" : query, at);
    if (closed) {
      j.done.complete(null);
      return j.done;
    }
    try {
      executor.execute(j);
    } catch (RejectedExecutionException e) {
      j.done.complete(null);
    }
    return j.done;
  }

  /** How many times {@link Engine#decide} has run. */
  public int decisions() {
    return decided;
  }

  /** The thread {@link Engine#decide} last ran on (always {@value #THREAD_NAME}), or null before the first. */
  public String lastDecidedOn() {
    return decidedOn;
  }

  /**
   * The kept count for a "Yours, not stock" mark pressed at {@code now} by {@code account} (null: none named), as server.mjs's
   * /personal-use reads it: the bag the idle-stock tier last read for that account (else for a poll naming none), if under
   * {@link #KEPT_FRESH_MS} old; with no account named and that reading absent or stale, the bag of the ONE account read in the
   * last {@link #KEPT_FRESH_MS} (two or more: nobody can say who pressed, so no count -- the 8 Oct 2026 bridge fix). Null when
   * no such bag holds the item: the blanket mark. Any thread. The plugin names its own account, which is always exact here.
   */
  public Double keptFor(String account, int itemId, long now) {
    boolean named = account != null && !account.isEmpty();
    Reading seen = lastInventory.get(named ? account : "");
    if (seen == null) seen = lastInventory.get(""); // lastInventory.get(b.account||'')||lastInventory.get('')
    Map<Integer, Double> fresh = seen != null && now - seen.at < KEPT_FRESH_MS ? seen.items : null;
    if (fresh == null && !named) {
      Reading only = null;
      int recent = 0;
      for (Reading r : lastInventory.values())
        if (now - r.at < KEPT_FRESH_MS) {
          only = r;
          recent++;
        }
      if (recent == 1) fresh = only.items;
    }
    if (fresh == null) return null;
    Double q = fresh.get(itemId);
    return q != null && Double.isFinite(q) ? q : null;
  }

  /** Stops taking requests; one already running finishes. Never interrupts. */
  public void shutdown() {
    closed = true;
    executor.shutdown();
  }

  public boolean isShutdown() {
    return executor.isShutdown();
  }

  /** Tests only (it blocks; never the client thread): waits for the engine's thread to finish after {@link #shutdown}. */
  public boolean awaitTermination(long ms) throws InterruptedException {
    return executor.awaitTermination(ms, TimeUnit.MILLISECONDS);
  }

  private void run(Job j) {
    try {
      Thread t = Thread.currentThread();
      if (t != thread || onUiThread.getAsBoolean()) throw new IllegalStateException("EVI engine work attempted on " + t.getName() + ", not " + THREAD_NAME);
      j.done.complete(once(j));
    } catch (Throwable e) { // a failure here must never reach the game; the poll shows a plain sentence
      log.accept("EVI engine: " + e);
      j.done.complete(new Answer(j.query, null, "EVI could not work out a suggestion just now. Details are in the client log.", null, false, 0));
    }
  }

  private Answer once(Job j) {
    EngineFeed.Market m = market.market(j.at);
    if (m == null) return new Answer(j.query, null, "EVI's price data has not started. Details are in the client log.", null, false, 0);
    String backfill = backfillLine(m);
    boolean ready = buysReady(m);
    if (m.catalog == null) return new Answer(j.query, null, "Loading the item list from the OSRS Wiki...", backfill, ready, m.latestFetchedAtMs);
    if (m.latest == null)
      return new Answer(j.query, null, "Waiting for the latest prices from the OSRS Wiki. They load while you are logged in.", backfill, ready, m.latestFetchedAtMs);
    PluginJournal.EngineView jv;
    try {
      jv = EngineFeed.await(journal.view(j.at), JOURNAL_WAIT_MS);
    } catch (Exception e) {
      log.accept("EVI engine: the journal could not be read (" + EngineFeed.why(e) + ")");
      jv = null;
    }
    if (jv == null) return new Answer(j.query, null, "EVI could not read its trade record just now. Details are in the client log.", backfill, ready, m.latestFetchedAtMs);
    feed.refresh(m, j.at, new JsonObject());
    // Buys wait for fresh prices as they wait for the basis: the same query without the buy tiers, and a line saying why.
    boolean stale = ready && pricesStale(m.latestFetchedAtMs, j.at);
    if (stale) {
      ready = false;
      backfill = staleLine(m.latestFetchedAtMs, j.at);
    }
    String[] prefsSource = {null};
    Engine.Query q = Engine.Query.parse(ready ? j.query : withoutBuyTiers(j.query));
    // the Block list of the account this query is for (per character); none named: none
    Engine.Prefs prefs = EngineFeed.withBlocked(EngineFeed.readPreferences(pluginDir.joinSegment(PREFERENCES), PREFERENCES, parser, prefsSource),
      blocked.apply(q.get("account")));
    AccountView view = AccountView.of(jv.state, jv.offers, q.get("account"), j.at);
    decidedOn = Thread.currentThread().getName();
    decided++;
    // The opt-in forecast: ~6 hours only, from the archive up to its newest stored hour (the ~1 hour and Overnight settings are retired).
    Engine.Response r = EngineFeed.decide(q, view, jv.state, jv.offers, feed.marketData(m), prefs, series, feed.forecastHook(m, m.newestStoredTs, null),
      profitSince.get(), j.at);
    String account = q.get("account") == null || q.get("account").isEmpty() ? null : q.get("account"); // get('account')||undefined
    if (r.inventoryRead != null) lastInventory.put(account == null ? "" : account, new Reading(r.inventoryRead, j.at));
    if (r.failed()) {
      log.accept("EVI engine: no answer (" + r.error + ")");
      return new Answer(j.query, null, "EVI could not work out a suggestion just now. Details are in the client log.", backfill, ready, m.latestFetchedAtMs, stale);
    }
    JsonObject body = ResponseJson.response(r);
    // The handle "I took this one" echoes (server.mjs: suggestion.id, suggestion.accepted from the log), added after the body is
    // written, as the bridge adds them after the suggestion is built. Absent when the log line could not be written.
    if (records != null && r.suggestion != null && body.get("suggestion") != null && body.get("suggestion").isJsonObject()) {
      String id = records.record(account, r.suggestion, r.demotedPicks, j.at);
      if (id != null) {
        body.getAsJsonObject("suggestion").addProperty("id", id);
        body.getAsJsonObject("suggestion").addProperty("accepted", records.wasAccepted(id));
      }
    }
    JsonObject be = new JsonObject();
    for (Map.Entry<Integer, Long> e : sellBreakEven(view).entrySet()) be.addProperty(String.valueOf(e.getKey()), e.getValue());
    body.add("sellBreakEven", be);
    return new Answer(j.query, body.toString(), null, backfill, ready, m.latestFetchedAtMs, stale);
  }
}

package com.evi.live.inprocess;

import com.evi.live.journal.FifoMatcher;
import com.evi.live.journal.ManualFlip;
import com.evi.live.journal.Offer;
import com.evi.live.journal.StoreState;
import com.evi.live.journal.TradeLogExport;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;

/**
 * bridge/suggestionOutcomes.mjs {@code joinSuggestionOutcomes}, ported: what EVI suggested (the plugin's own suggestion log,
 * {@link SuggestionRecords}) joined to what actually happened (the journal's offers and flips). NOTHING IN THE PLUGIN SHOWS IT
 * YET -- the bridge's consumer is the scanner's track-record page -- so this exists to keep "I took this one" meaning what it means
 * in the bridge: a record that can be joined to the offer that followed it.
 *
 * <p>Three attributions, never pooled (read the JS header before changing anything):
 * <ul>
 *   <li>OBSERVED: the player pressed "I took this one" for the id. The earliest unclaimed offer for the item, on the suggested
 *       side, placed within {@link #ACCEPTED_WINDOW_MS} after the suggestion was shown, is "the" offer, at WHATEVER price -- the
 *       player said they took it. With no such offer the row is still taken ({@code noOfferFound}).</li>
 *   <li>MATCHED: not pressed, but the offer carries EVI's exact fingerprint -- the suggested price TO THE GP and the suggested
 *       quantity to the unit, the quantity at least {@link #MATCH_MIN_QUANTITY}. One gp off is not a match.</li>
 *   <li>INFERRED: any other offer for the item on that side within {@link #TAKEN_WINDOW_MS}.</li>
 * </ul>
 * A margin check never counts; each offer is claimed once, oldest suggestion first. Pure; JS semantics kept (a missing number
 * fails every comparison; the sort is stable).
 */
public final class SuggestionOutcomes {
  private SuggestionOutcomes() {}

  public static final long TAKEN_WINDOW_MS = 2L * 3600 * 1000;
  public static final long ACCEPTED_WINDOW_MS = 12L * 3600 * 1000;
  public static final int MATCH_MIN_QUANTITY = 11;

  /** One joined row: the log entry, and what happened. */
  public static final class Row {
    public final JsonObject suggestion;
    public final boolean taken;
    /** "observed", "matched", "inferred", or null when not taken. */
    public final String attribution;
    /** Only on a row with no offer: true when it was observed (taken, never placed). */
    public final Boolean noOfferFound;
    public final String offerId;
    public final Long actualPrice;
    public final Long actualQuantity;
    public final Long filled;
    public final Boolean filledFully;
    public final Double minutesToComplete;
    public final Boolean stillOpen;
    public final Long profit;
    public final Double soldWithinHours;

    Row(JsonObject suggestion, boolean taken, String attribution, Boolean noOfferFound, Offer match, Long profit, Double soldWithinHours) {
      this.suggestion = suggestion;
      this.taken = taken;
      this.attribution = attribution;
      this.noOfferFound = noOfferFound;
      this.offerId = match == null ? null : match.offerId;
      this.actualPrice = match == null ? null : match.price;
      this.actualQuantity = match == null ? null : match.total;
      this.filled = match == null ? null : match.filled;
      this.filledFully = match == null ? null : match.total > 0 && match.filled >= match.total;
      boolean finished = match != null && match.completedAt != null;
      this.minutesToComplete = match == null || !finished ? null : (match.completedAt - (double) match.firstSeen) / 60000;
      this.stillOpen = match == null ? null : !finished;
      this.profit = profit;
      this.soldWithinHours = soldWithinHours;
    }
  }

  /** A flip as the join reads it: {@code [...state.flips, ...state.autoFlips]}. */
  public static final class Flip {
    final String buyId;
    final long profit;
    final Long firstBuy;
    final Long lastSell;

    public Flip(String buyId, long profit, Long firstBuy, Long lastSell) {
      this.buyId = buyId;
      this.profit = profit;
      this.firstBuy = firstBuy;
      this.lastSell = lastSell;
    }

    public static List<Flip> of(Collection<ManualFlip> flips, Collection<FifoMatcher.AutoFlip> autoFlips) {
      List<Flip> out = new ArrayList<>();
      if (flips != null) for (ManualFlip f : flips) out.add(new Flip(f.buyId, f.profit, f.firstBuy, f.lastSell));
      if (autoFlips != null) for (FifoMatcher.AutoFlip f : autoFlips) out.add(new Flip(f.buyId, f.profit, f.firstBuy, f.lastSell));
      return out;
    }
  }

  private static boolean isBuy(Offer o) {
    return "BUYING".equals(o.state) || "BOUGHT".equals(o.state) || "CANCELLED_BUY".equals(o.state);
  }

  /** A finite JSON number, else null (JS Number.isFinite on whatever the log line holds). */
  static Double finite(JsonElement e) {
    if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber()) return null;
    double d = e.getAsDouble();
    return Double.isFinite(d) ? d : null;
  }

  private static String string(JsonElement e) {
    return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isString() ? e.getAsString() : null;
  }

  /** suggestionOutcomes.mjs fingerprinted: the suggested price to the gp AND the quantity to the unit, the quantity at least 11. */
  static boolean fingerprinted(JsonObject s, Offer offer) {
    Double wanted = finite("buy".equals(string(s.get("action"))) ? s.get("buyPrice") : s.get("sellPrice"));
    Double quantity = finite(s.get("quantity"));
    if (wanted == null || quantity == null) return false;
    if (quantity < MATCH_MIN_QUANTITY) return false;
    return offer.price == wanted && offer.total == quantity;
  }

  /**
   * @param suggestions the log's entries, oldest first
   * @param offers      every journal offer, in the store's order
   * @param wasAccepted the acceptance record's answer for an id (null: none)
   */
  public static List<Row> join(List<JsonObject> suggestions, Collection<Offer> offers, List<Flip> flips, long takenWindowMs,
                               Predicate<String> wasAccepted) {
    Map<String, Flip> flipByBuyId = new HashMap<>();
    if (flips != null) for (Flip f : flips) if (f != null && f.buyId != null && !f.buyId.isEmpty()) flipByBuyId.put(f.buyId, f);
    Set<String> used = new HashSet<>();
    List<Row> rows = new ArrayList<>();
    for (JsonObject s : suggestions) {
      if (s == null) continue;
      Double itemId = finite(s.get("itemId")), ts = finite(s.get("ts"));
      if (itemId == null || ts == null) continue;
      boolean wantBuy = "buy".equals(string(s.get("action")));
      String id = string(s.get("id"));
      boolean observed = wasAccepted != null && id != null && !id.isEmpty() && wasAccepted.test(id);
      long window = observed ? ACCEPTED_WINDOW_MS : takenWindowMs;
      Offer match = null;
      for (Offer o : offers) {
        if (o.itemId != itemId || isBuy(o) != wantBuy || used.contains(o.offerId) || FifoMatcher.isMarginCheck(o)) continue;
        if (o.firstSeen == null || !(o.firstSeen >= ts) || !(o.firstSeen <= ts + window)) continue;
        if (match == null || o.firstSeen < match.firstSeen) match = o; // the earliest; a tie keeps the first (a stable sort's [0])
      }
      if (match == null) {
        rows.add(new Row(s, observed, observed ? "observed" : null, observed, null, null, null));
        continue;
      }
      used.add(match.offerId);
      Flip flip = flipByBuyId.get(match.offerId);
      // (lastSell - firstBuy) / 3600000; a missing time is NaN, as an undefined one is in JS
      Double within = flip == null ? null
        : flip.lastSell == null || flip.firstBuy == null ? Double.NaN : (flip.lastSell - (double) flip.firstBuy) / 3600000;
      rows.add(new Row(s, true, observed ? "observed" : fingerprinted(s, match) ? "matched" : "inferred", null, match,
        flip == null ? null : flip.profit, within));
    }
    return rows;
  }

  /**
   * The trade-log export's links (voluntary sharing, 9 Oct 2026): every offer this join claimed, by offer id, with its attribution
   * and the suggested price for the suggestion's side -- the same price {@link #fingerprinted} compares (buyPrice for a buy,
   * sellPrice otherwise), empty when the record holds no whole number. A row with no offer links nothing. Only the price and the
   * attribution leave the record: never its id, account, quantity or anything else.
   */
  public static Map<String, TradeLogExport.Link> offerLinks(List<Row> rows) {
    Map<String, TradeLogExport.Link> out = new HashMap<>();
    for (Row r : rows) {
      if (r.offerId == null || r.attribution == null) continue;
      Double p = finite("buy".equals(string(r.suggestion.get("action"))) ? r.suggestion.get("buyPrice") : r.suggestion.get("sellPrice"));
      Long price = p == null || p != Math.floor(p) || Math.abs(p) > 9.007199254740991E15 ? null : (long) (double) p;
      out.put(r.offerId, new TradeLogExport.Link(r.attribution, price));
    }
    return out;
  }

  /**
   * {@link #offerLinks} over everything the plugin has logged: the suggestion log's current file, oldest first, joined with the
   * default windows (2 h, 12 h when observed) to every offer and flip the export is built from, as the bridge joins them. Reads
   * the plugin's suggestion files, so never on the client thread or the Swing EDT. An offer older than the log, or imported
   * from the old companion app's history (whose suggestions the plugin never logged), has no link.
   */
  public static Map<String, TradeLogExport.Link> offerLinks(SuggestionRecords records, StoreState state, Collection<Offer> offers) {
    if (records == null) return new HashMap<>();
    return offerLinks(join(records.logged(), offers, Flip.of(state.flips, state.autoFlips), TAKEN_WINDOW_MS, records::wasAccepted));
  }
}

package com.evi.live.inprocess;

import com.evi.live.engine.Pick;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Function;
import net.runelite.client.util.Filepath;

/**
 * "I took this one" (SELF-CONTAINED decision 12): the suggestion's id and the record of which ones the player
 * took -- bridge/suggestionLog.mjs and bridge/acceptances.mjs, kept by the plugin in its own data folder.
 *
 * <p>THE ID is the bridge's scheme exactly: {@code now.toString(36) + "-" + itemId + "-" + (seq++ % 1296).toString(36)} padded to
 * two characters, with {@code seq} counting from 0 for each plugin start as the bridge's counts from 0 for each bridge start. A
 * REPEAT of the same suggestion for the same account (item, action, source, quantity, both prices and the demoted picks, as
 * suggestionLog.mjs keys it) inside {@link #REPEAT_MS} keeps its first id, so a pick that has been on screen a while still names
 * a logged entry. The repeat memory is in memory, as the bridge's is: after a restart the same pick is a new entry with a new id.
 * Only the first suggestion of a poll gets an id (the bridge logs no further position).
 *
 * <p>THE FILES, in {@value #DIR}/ of the plugin's data folder, through {@link Filepath} only: {@value #LOG} (one line per id
 * issued: the fields the outcome join needs -- {@link SuggestionOutcomes}) and {@value #ACCEPTED} (one line per press:
 * {@code {id, account, itemId, accepted, at}}). Both append-only; the newest record for an id wins, so taking an acceptance
 * back is just another line. Each moves to {@code .1} past its cap (50 MB / 8 MB, the bridge's), and, as in the bridge, only
 * the current acceptance file is read back at start. The acceptance file is read lazily, at the first use, on whichever
 * background thread asks first -- never at construction (that is the client thread). Local only; nothing is ever sent.
 *
 * <p>Deliberate differences from the bridge, none of which changes an answer: the log line carries only the suggestion's own
 * fields (the bridge also logs the poll's settings and its checks, which no join reads); and the acceptance line carries the
 * account that pressed the button (the plugin never sends one to the bridge, which writes null).
 *
 * <p>Thread-safe: the engine's thread issues ids, a background thread records presses.
 */
public final class SuggestionRecords {
  public static final String DIR = "suggestions";
  public static final String LOG = "suggestion-log.jsonl";
  public static final String ACCEPTED = "suggestion-accepted.jsonl";
  /** suggestionLog.mjs REPEAT_MS. */
  public static final long REPEAT_MS = 30L * 60 * 1000;
  static final long LOG_MAX_BYTES = 50L * 1024 * 1024;
  static final long ACCEPTED_MAX_BYTES = 8L * 1024 * 1024;

  private static final class Last {
    final String key;
    final long at;
    final String id;

    Last(String key, long at, String id) {
      this.key = key;
      this.at = at;
      this.id = id;
    }
  }

  private final Filepath dir;
  private final Function<String, JsonElement> parser;
  private final Consumer<String> log;
  private final Map<String, Last> last = new HashMap<>();
  private int seq;
  /** id -> the newest acceptance record's {accepted, at}; null until first read. */
  private Map<String, JsonObject> byId;

  /** @param pluginDir the plugin's data folder; nothing is read or written here until the first use */
  public SuggestionRecords(Filepath pluginDir, Function<String, JsonElement> parser, Consumer<String> log) {
    this.dir = pluginDir.joinSegment(DIR);
    this.parser = parser;
    this.log = log;
  }

  /** suggestionLog.mjs makeId: the clock in base 36, the item, and a two-character base-36 counter. */
  static String makeId(long now, int itemId, int seq) {
    String c = Integer.toString(seq % 1296, 36);
    return Long.toString(now, 36) + "-" + itemId + "-" + (c.length() < 2 ? "0" + c : c);
  }

  /** suggestionLog.mjs's repeat key: {@code [itemId, action, source, quantity, buyPrice, sellPrice, demotedIds].join('|')}. */
  static String key(Pick s, List<Pick> demoted) {
    StringBuilder d = new StringBuilder();
    if (demoted != null)
      for (int i = 0; i < demoted.size(); i++) {
        if (i > 0) d.append(',');
        d.append(demoted.get(i).itemId);
      }
    return s.itemId + "|" + nz(s.action) + "|" + nz(s.source) + "|" + s.quantity + "|" + s.buyPrice + "|" + s.sellPrice + "|" + d;
  }

  private static String nz(String s) {
    return s == null ? "" : s; // Array.join writes null and undefined as nothing
  }

  /**
   * The id for the suggestion a poll is answered with, logging it when it is new (suggestionLog.record). {@code account} is the
   * query's (null when it names none). Null only when a NEW entry could not be written -- the plugin then shows no button, as
   * with the bridge; as in the bridge, the repeat memory was already moved on, so the next poll of the same pick returns this id.
   */
  public synchronized String record(String account, Pick s, List<Pick> demoted, long now) {
    if (s == null) return null;
    String k = key(s, demoted);
    String who = account == null ? "" : account;
    Last prev = last.get(who);
    if (prev != null && prev.key.equals(k) && now - prev.at < REPEAT_MS) return prev.id;
    String id = makeId(now, s.itemId, seq++);
    last.put(who, new Last(k, now, id));
    JsonObject e = new JsonObject();
    e.addProperty("id", id);
    e.addProperty("ts", now);
    if (account == null) e.add("account", JsonNull.INSTANCE);
    else e.addProperty("account", account);
    e.addProperty("itemId", s.itemId);
    if (s.name != null) e.addProperty("name", s.name);
    if (s.action != null) e.addProperty("action", s.action);
    if (s.source != null) e.addProperty("source", s.source);
    e.addProperty("quantity", s.quantity);
    e.addProperty("buyPrice", s.buyPrice);
    e.addProperty("sellPrice", s.sellPrice);
    if (s.breakEvenPrice == null) e.add("breakEvenPrice", JsonNull.INSTANCE);
    else e.addProperty("breakEvenPrice", s.breakEvenPrice);
    if (s.lossIfSoldNow == null) e.add("lossIfSoldNow", JsonNull.INSTANCE);
    else e.addProperty("lossIfSoldNow", s.lossIfSoldNow);
    e.addProperty("persisted", Boolean.TRUE.equals(s.persisted));
    try {
      append(LOG, LOG_MAX_BYTES, e);
    } catch (IOException | RuntimeException ex) {
      log.accept("EVI: a suggestion could not be logged, so it has no \"I took this one\" button: " + ex);
      return null;
    }
    return id;
  }

  /**
   * One press of "I took this one" (acceptances.accept): an id is required; the record is appended, then remembered. Returns
   * false (and remembers nothing) when there is no id or the line could not be written.
   */
  public synchronized boolean accept(String id, String account, Integer itemId, boolean accepted, long now) {
    if (id == null || id.isEmpty()) return false;
    loadAcceptances();
    JsonObject r = new JsonObject();
    r.addProperty("id", id);
    if (account == null) r.add("account", JsonNull.INSTANCE);
    else r.addProperty("account", account);
    if (itemId == null) r.add("itemId", JsonNull.INSTANCE);
    else r.addProperty("itemId", itemId);
    r.addProperty("accepted", accepted);
    r.addProperty("at", now);
    try {
      append(ACCEPTED, ACCEPTED_MAX_BYTES, r);
    } catch (IOException | RuntimeException ex) {
      log.accept("EVI: \"I took this one\" could not be saved: " + ex);
      return false;
    }
    byId.put(id, r);
    return true;
  }

  /** acceptances.wasAccepted: the newest record for the id says accepted. */
  public synchronized boolean wasAccepted(String id) {
    if (id == null || id.isEmpty()) return false;
    loadAcceptances();
    JsonObject r = byId.get(id);
    return r != null && r.has("accepted") && r.get("accepted").isJsonPrimitive() && r.get("accepted").getAsJsonPrimitive().isBoolean()
      && r.get("accepted").getAsBoolean();
  }

  /** Every line of the suggestion log still in its current file, oldest first (unreadable lines skipped, as the bridge's recent()). */
  public synchronized List<JsonObject> logged() {
    List<JsonObject> out = new ArrayList<>();
    for (String line : lines(dir.joinSegment(LOG))) {
      try {
        JsonElement e = parser.apply(line);
        if (e != null && e.isJsonObject()) out.add(e.getAsJsonObject());
      } catch (RuntimeException ignored) {
        // a partial or damaged line is discarded rather than guessed at
      }
    }
    return out;
  }

  private void loadAcceptances() {
    if (byId != null) return;
    byId = new HashMap<>();
    for (String line : lines(dir.joinSegment(ACCEPTED))) {
      try {
        JsonElement e = parser.apply(line);
        if (e == null || !e.isJsonObject()) continue;
        JsonObject r = e.getAsJsonObject();
        JsonElement id = r.get("id");
        if (id != null && id.isJsonPrimitive() && id.getAsJsonPrimitive().isString() && !id.getAsString().isEmpty()) byId.put(id.getAsString(), r);
      } catch (RuntimeException ignored) {
        // acceptances.mjs skips a line that does not parse
      }
    }
  }

  private List<String> lines(Filepath f) {
    List<String> out = new ArrayList<>();
    if (!f.isFile()) return out;
    try (InputStream in = f.openInputStream()) {
      for (String l : new String(in.readAllBytes(), StandardCharsets.UTF_8).split("\n", -1)) if (!l.isEmpty()) out.add(l);
    } catch (IOException e) {
      log.accept("EVI: " + f.getFileName() + " could not be read: " + e);
    }
    return out;
  }

  private void append(String name, long maxBytes, JsonObject line) throws IOException {
    dir.createDirectories();
    Filepath f = dir.joinSegment(name);
    if (f.isFile() && f.size() > maxBytes) f.moveTo(dir.joinSegment(name + ".1"), StandardCopyOption.REPLACE_EXISTING);
    try (OutputStream out = f.openOutputStream(StandardOpenOption.CREATE, StandardOpenOption.WRITE, StandardOpenOption.APPEND)) {
      out.write((line.toString() + "\n").getBytes(StandardCharsets.UTF_8));
    }
  }
}

package com.evi.live.journal;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * The account id EVI journals under: SHA-256 of {@code salt:profile} (plus {@code :economy:<scope>} on a separate-economy world),
 * as lowercase hex. ONE formula, used by the plugin at login and by the import, which recognises the records a former data
 * folder wrote by that folder's own salt ({@code import/identity-salt.txt}, see {@link PluginJournal}). Pure.
 */
public final class AccountIds {
  private AccountIds() {}

  public static String of(String salt, String profile, String economy) {
    String identity = salt + ":" + profile + (economy == null || economy.isEmpty() ? "" : ":economy:" + economy);
    byte[] hash;
    try {
      hash = MessageDigest.getInstance("SHA-256").digest(identity.getBytes(StandardCharsets.UTF_8));
    } catch (NoSuchAlgorithmException e) {
      throw new IllegalStateException(e);
    }
    StringBuilder h = new StringBuilder(64);
    for (byte b : hash) h.append(Character.forDigit((b >> 4) & 15, 16)).append(Character.forDigit(b & 15, 16));
    return h.toString();
  }
}

package com.evi.live.journal;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Which records of a BRIDGE journal (data/events.jsonl, every account on the machine in one file) belong
 * to ONE account, for the plugin's one-time, opt-in import. Pure: records in, records out.
 *
 * <p>Ownership is always EXPLICIT EQUALITY with a non-null account -- never "no account means everyone's"
 * (the 6 Oct 2026 bug that showed a pure's holdings to the main):
 * <ul>
 *   <li>a packet: its {@code account}; a recorded purchase: its {@code account};</li>
 *   <li>a reviewed flip: its own {@code account} (or, on a flip journalled without one, its buy's owner);</li>
 *   <li>a flip mark: the owner of the flip it marks;</li>
 *   <li>personal use, a closed or reopened position, a removed recorded purchase: the owner of the offer
 *       it names, resolved through the bridge's login-time aliases exactly as the store resolves it.</li>
 * </ul>
 * Records tied to NO account -- an item-level "for my own use" mark and imported flip histories -- cannot
 * be attributed and are left out and counted. None of them changes the profit line or the holdings.
 *
 * <p>EXCEPT, when asked (since 8 Oct 2026 in both modes; the built-in engine since 8 Oct): the item-level marks ("Yours, not
 * stock" and its undo) are the bridge's MACHINE-WIDE choices, so they are copied into every importing account's selection, in
 * journal order, and counted as {@code itemMarks}. The plugin's store is machine-wide too, so they apply to every account
 * exactly as in the bridge.
 *
 * <p>AND (8 Oct 2026, approved): the flip histories imported into the bridge from another tracker ({@code flips-imported}: a
 * Flipping Copilot export, a flips.csv) name the CHARACTER each trade was made on -- its display name, not EVI's account id. Given
 * the importing character's display name, each such record is copied with only the flips made under THAT name
 * ({@link CharacterNames#same}: case, space / underscore / hyphen / non-breaking space as the game treats them), in journal
 * order, and only those the bridge still holds after every record (an import removed later is not taken; a repeated
 * fingerprint is not taken twice). A flip naming no character, or another one, is never taken. The bridge reads every
 * imported flip machine-wide in its personal-history ranking ({@code [...state.flips, ...state.importedFlips]}), and so does the
 * plugin's store: once a character is imported, every account on the machine ranks from its history, as in the bridge.
 *
 * <p>AND (8 Oct 2026, approved): a character renamed since keeps its trades under its FORMER name too, when the player says so
 * ({@link OldNames}, {@code oldNames} in import/preferences.json): such a flip is taken as if it carried the current name.
 */
public final class BridgeImport {
  private BridgeImport() {}

  public static final class Selection {
    public final List<JournalRecord> records;
    public final int total;
    public final int otherAccounts;
    public final int notTiedToAnAccount;
    public final int unresolved;
    /** Item-level marks copied in for every account (0 unless asked for). */
    public final int itemMarks;
    /** Imported flips (another tracker's) taken for this character, and those left for other characters' names. */
    public final int flips, flipsOtherCharacters;
    /**
     * Of {@link #flips}, those kept under one of this character's FORMER names ({@link OldNames}); and the flips under a former
     * name the player's mapping refused (taken by no character; also counted in {@link #flipsOtherCharacters}).
     */
    public final int flipsViaOldNames, flipsOldNamesRefused;

    Selection(List<JournalRecord> records, int total, int otherAccounts, int notTiedToAnAccount, int unresolved) {
      this(records, total, otherAccounts, notTiedToAnAccount, unresolved, 0, 0, 0);
    }

    Selection(List<JournalRecord> records, int total, int otherAccounts, int notTiedToAnAccount, int unresolved, int itemMarks, int flips,
              int flipsOtherCharacters) {
      this(records, total, otherAccounts, notTiedToAnAccount, unresolved, itemMarks, flips, flipsOtherCharacters, 0, 0);
    }

    Selection(List<JournalRecord> records, int total, int otherAccounts, int notTiedToAnAccount, int unresolved, int itemMarks, int flips,
              int flipsOtherCharacters, int flipsViaOldNames, int flipsOldNamesRefused) {
      this.records = Collections.unmodifiableList(records);
      this.total = total;
      this.otherAccounts = otherAccounts;
      this.notTiedToAnAccount = notTiedToAnAccount;
      this.unresolved = unresolved;
      this.itemMarks = itemMarks;
      this.flips = flips;
      this.flipsOtherCharacters = flipsOtherCharacters;
      this.flipsViaOldNames = flipsViaOldNames;
      this.flipsOldNamesRefused = flipsOldNamesRefused;
    }
  }

  /**
   * The records of {@code all} that belong to {@code account}, in journal order. Throws when the bridge
   * journal does not replay (the import is then refused and nothing is written).
   */
  public static Selection select(List<JournalRecord> all, String account) {
    return select(all, account, false);
  }

  /**
   * As {@link #select(List, String)}; with {@code itemMarks}, the item-level marks are kept for this account too (see the class
   * note), each counted in {@link Selection#itemMarks} rather than as not tied to an account.
   */
  public static Selection select(List<JournalRecord> all, String account, boolean itemMarks) {
    return select(all, account, itemMarks, null);
  }

  /**
   * As {@link #select(List, String, boolean)}, with the importing character's display name ({@code characterName}; null: not
   * known, and no imported flip is taken). See the class note.
   */
  public static Selection select(List<JournalRecord> all, String account, boolean itemMarks, String characterName) {
    return select(all, account, itemMarks, characterName, OldNames.NONE);
  }

  /**
   * As {@link #select(List, String, boolean, String)}, with the player's stated former names ({@code oldNames}, never null): a flip
   * kept under a former name is taken exactly as if it carried the current name it maps to, and one under a refused former name
   * by no character ({@link OldNames}).
   */
  public static Selection select(List<JournalRecord> all, String account, boolean itemMarks, String characterName, OldNames oldNames) {
    if (oldNames == null) throw new IllegalArgumentException("oldNames");
    if (!Packet.id(account)) throw new JournalException("Invalid account");
    Store whole = Store.replay(all, r -> {
      throw new IllegalStateException("an import replay must not write");
    });
    // The imported flips the bridge still holds after every record, by IDENTITY: a flip of a later-removed import, or one whose
    // fingerprint an earlier record already brought, is not among them.
    Map<ImportedFlip, Boolean> held = new IdentityHashMap<>();
    for (ImportedFlip f : whole.importedFlipsNow()) held.put(f, Boolean.TRUE);
    Map<String, String> offerOwner = new HashMap<>();
    for (Offer o : whole.offers()) offerOwner.put(o.offerId, o.account);
    // A recorded purchase removed later is no longer an offer, but its records still name it.
    for (JournalRecord r : all) {
      if (r instanceof JournalRecord.PurchaseRecorded) {
        JournalRecord.PurchaseRecorded p = (JournalRecord.PurchaseRecorded) r;
        offerOwner.putIfAbsent(p.offerId, p.account);
      }
    }
    Map<String, String> flipOwner = new HashMap<>();
    List<JournalRecord> out = new ArrayList<>();
    int other = 0, global = 0, unresolved = 0, marks = 0, flipsTaken = 0, flipsOther = 0, viaOld = 0, oldRefused = 0;
    String me = CharacterNames.key(characterName);
    for (JournalRecord r : all) {
      String owner;
      boolean attributable = true;
      if (r instanceof JournalRecord.FlipsImported && characterName == null) {
        global++; // no character named: nothing to tie these to, exactly as before names were read
        continue;
      }
      if (r instanceof JournalRecord.FlipsImported) {
        List<ImportedFlip> mine = new ArrayList<>();
        boolean others = false;
        for (ImportedFlip f : ((JournalRecord.FlipsImported) r).flips) {
          if (!held.containsKey(f) || f.account == null) continue;
          String k = CharacterNames.key(f.account);
          String now = oldNames.currentOf(k); // a stated former name: compared as its current name, and only as that
          if (oldNames.refused(k)) oldRefused++;
          else if (me != null && me.equals(now != null ? now : k)) {
            mine.add(f);
            if (now != null) viaOld++;
            continue;
          }
          flipsOther++;
          others = true;
        }
        if (!mine.isEmpty()) {
          out.add(mine.size() == ((JournalRecord.FlipsImported) r).flips.size() ? r : new JournalRecord.FlipsImported(mine));
          flipsTaken += mine.size();
        } else if (others) other++;
        else global++; // every flip names no character, or was removed in the bridge later
        continue;
      }
      if (itemMarks && (r instanceof JournalRecord.PersonalUseItem || r instanceof JournalRecord.PersonalUseItemUndo)) {
        out.add(r); // machine-wide in the bridge, machine-wide in the plugin: every importing account takes it
        marks++;
        continue;
      }
      if (r instanceof JournalRecord.PacketRecord) {
        owner = ((JournalRecord.PacketRecord) r).packet.account;
      } else if (r instanceof JournalRecord.PurchaseRecorded) {
        owner = ((JournalRecord.PurchaseRecorded) r).account;
      } else if (r instanceof JournalRecord.PurchaseRecordRemoved) {
        owner = offerOwner.get(((JournalRecord.PurchaseRecordRemoved) r).offerId);
      } else if (r instanceof JournalRecord.PositionClosed) {
        owner = offerOwner.get(whole.resolve(((JournalRecord.PositionClosed) r).buyId));
      } else if (r instanceof JournalRecord.PositionReopened) {
        owner = offerOwner.get(whole.resolve(((JournalRecord.PositionReopened) r).buyId));
      } else if (r instanceof JournalRecord.PersonalUse) {
        owner = offerOwner.get(whole.resolve(((JournalRecord.PersonalUse) r).buyId));
      } else if (r instanceof JournalRecord.FlipRecord) {
        ManualFlip f = ((JournalRecord.FlipRecord) r).flip;
        owner = f.account != null ? f.account : (f.buyId == null ? null : offerOwner.get(whole.resolve(f.buyId)));
        if (f.id != null && owner != null) flipOwner.putIfAbsent(f.id, owner);
      } else if (r instanceof JournalRecord.FlipMark) {
        owner = flipOwner.get(((JournalRecord.FlipMark) r).id);
      } else {
        owner = null;
        attributable = false; // personal-use-item(-undo) when not asked for; flips-import-removed (applied through `held`)
      }
      if (!attributable) global++;
      else if (owner == null) unresolved++;
      else if (owner.equals(account)) out.add(r);
      else other++;
    }
    return new Selection(out, all.size(), other, global, unresolved, marks, flipsTaken, flipsOther, viaOld, oldRefused);
  }

  /**
   * The imported records first, then every record the plugin journalled for this account that the import does
   * not already hold. Only a PACKET can be held twice: the plugin sent the bridge the very same packet, received
   * at a slightly different time, so it is the same packet when its session and seq match. Every other record
   * in a plugin events file is a press made IN the plugin (a mark, a close), which never reached the bridge --
   * a press goes to one place -- so it is always kept, even when its line is byte-identical to an imported one.
   * (Until 8 Oct 2026 such a line was dropped: an imported mark, its imported undo, then the same mark pressed
   * again in the plugin lost the new mark at the next rebuild. Marks carry no time, so identical lines are
   * normal.)
   */
  public static List<JournalRecord> merge(List<JournalRecord> imported, List<JournalRecord> existing) {
    Dedup d = Dedup.of(imported);
    List<JournalRecord> out = new ArrayList<>(imported);
    for (JournalRecord r : existing) {
      if (d.contains(r)) continue;
      out.add(r);
    }
    return out;
  }

  /**
   * What an import already holds, by {@link #merge}'s rule: a packet by its session and seq; nothing else (a
   * plugin-written record is never one the import holds). The plugin keeps one per account so a line appended
   * to the events file later is skipped exactly as a rebuild's merge would skip it.
   */
  public static final class Dedup {
    private final Set<String> packets = new HashSet<>();

    private Dedup() {}

    public static Dedup of(List<JournalRecord> imported) {
      Dedup d = new Dedup();
      for (JournalRecord r : imported) {
        if (r instanceof JournalRecord.PacketRecord) d.packets.add(packetKey((JournalRecord.PacketRecord) r));
      }
      return d;
    }

    public boolean contains(JournalRecord r) {
      return r instanceof JournalRecord.PacketRecord && packets.contains(packetKey((JournalRecord.PacketRecord) r));
    }
  }

  private static String packetKey(JournalRecord.PacketRecord r) {
    return r.packet.session + "\n" + r.packet.seq;
  }
}

package com.evi.live.journal;

/**
 * How much of an item ONE account has bought in the GE's rolling four-hour window, from EVI's own journal
 * (store.mjs {@code buyLimitUsage}).
 *
 * <p>Deliberately an UNDER-estimate: only buys EVI observed count, so callers may use it to REDUCE a
 * suggested quantity, never to justify a larger one. Each buy is attributed to when it completed (or was
 * last seen changing), the closest time the journal has. A buy exactly four hours old still counts.
 *
 * <p>SCOPED BY CONSTRUCTION: the account is compared for equality and a null account matches nothing
 * (never "every account"). That is the 6 Oct pure/main bug's lesson; the JS engine gives the same answer
 * here (no offer has an undefined account), and the vectors assert it.
 */
public final class BuyLimitUsage {
  /** The GE's window, 4 hours. */
  public static final long WINDOW_MS = 4L * 3600 * 1000;

  public final long used;
  /** When the oldest counted buy leaves the window; null when nothing is counted (absent, not zero). */
  public final Long windowEndsAt;

  BuyLimitUsage(long used, Long windowEndsAt) {
    this.used = used;
    this.windowEndsAt = windowEndsAt;
  }

  public static BuyLimitUsage of(Iterable<Offer> offers, String account, int itemId, long now) {
    if (account == null) return new BuyLimitUsage(0, null);
    long windowStart = now - WINDOW_MS;
    long used = 0;
    Long oldest = null;
    for (Offer o : offers) {
      if (!account.equals(o.account) || o.itemId != itemId || !"buy".equals(o.side()) || !(o.filled > 0)) continue;
      Long at = o.completedAt != null ? o.completedAt : o.updated != null ? o.updated : o.firstSeen;
      if (at == null || at < windowStart) continue;
      used = Js.add(used, o.filled);
      if (oldest == null || at < oldest) oldest = at;
    }
    return new BuyLimitUsage(used, oldest == null ? null : oldest + WINDOW_MS);
  }
}

package com.evi.live.journal;

import java.util.Locale;
import net.runelite.client.util.Text;

/**
 * Whether two Old School display names are the SAME name, as the game treats them: letter case does not matter, and a space,
 * an underscore, a hyphen and a non-breaking space are one character (RuneLite's own {@link Text#toJagexName}: the client hands
 * the local player's name with non-breaking spaces, and an export may spell it with underscores). Nothing looser: no other
 * character is dropped or merged, so a name that is not the same name never matches -- an imported flip history must never
 * land on another character.
 */
public final class CharacterNames {
  private CharacterNames() {}

  /** The name as compared: RuneLite's Jagex form, lower case. Null or blank: null (matches nothing). */
  public static String key(String name) {
    if (name == null) return null;
    String k = Text.toJagexName(name).toLowerCase(Locale.ROOT);
    return k.isEmpty() ? null : k;
  }

  public static boolean same(String a, String b) {
    String x = key(a), y = key(b);
    return x != null && x.equals(y);
  }
}

package com.evi.live.journal;

import java.util.List;

/**
 * What ONE account paid, on average, for the units of an item it holds (suggestions.mjs
 * {@code heldCostBasis}): finished purchases still held (FIFO open positions, each at its own unit cost)
 * plus buy offers still RUNNING that have filled some units. Never double counted, because FIFO only
 * admits finished offers. Null when nothing held has a known price: never a guessed cost.
 *
 * <p>THE PORT WARNING, honoured (the self-contained port's notes): the JS function scopes with
 * {@code !account || x.account === account}, so called WITHOUT an account it averages every account's
 * stock together, and it is safe today only because server.mjs pre-filters. This port scopes itself: the
 * account is REQUIRED, a null account returns null, and the vectors record the JS answer for the
 * no-account call beside the Java one so the difference is visible rather than hidden.
 */
public final class CostBasis {
  public final double unitCost;
  public final long quantity;

  CostBasis(double unitCost, long quantity) {
    this.unitCost = unitCost;
    this.quantity = quantity;
  }

  public static CostBasis held(List<FifoMatcher.OpenPosition> openPositions, List<Offer> activeOffers, int itemId, String account) {
    // server.mjs's ownedBy is !!account && ...: an EMPTY account is no account too (it owns nothing).
    if (account == null || account.isEmpty()) return null;
    long units = 0;
    double gp = 0;
    // (openPositions || []) and (activeOffers || []): a missing list holds nothing, as in the JS.
    if (openPositions != null) for (FifoMatcher.OpenPosition p : openPositions) {
      if (p == null || p.itemId != itemId || !account.equals(p.account) || !(p.unitCost > 0) || !(p.remaining > 0)) continue;
      units = Js.add(units, p.remaining);
      gp += p.unitCost * p.remaining;
    }
    if (activeOffers != null) for (Offer o : activeOffers) {
      if (o == null || o.itemId != itemId || !account.equals(o.account) || !"BUYING".equals(o.state) || !(o.filled > 0) || !(o.spent > 0)) continue;
      units = Js.add(units, o.filled);
      gp += o.spent;
    }
    return units > 0 ? new CostBasis(gp / units, units) : null;
  }
}

package com.evi.live.journal;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Automatic FIFO matching with exact GE tax, ported from store.mjs ({@code computeAutoFlips},
 * {@code isMarginCheck}, {@code availableAt}, {@code dataHealthOf}). Pure: offers in, flips out.
 *
 * <p>Per account AND item (never across accounts), every finished, fully observed offer is walked in the
 * order its goods or GP came into existence; buys become cost-basis lots, sells consume them oldest
 * first, and a lot closes into a flip the moment it is fully sold.
 *
 * <p>ROUNDING: the running capital and proceeds are DOUBLES (a lot's unit cost is spent/filled, which is
 * rarely whole) and are rounded only on the way out, with {@link Js#round(double)} -- half-up, exactly
 * JavaScript's Math.round, never rint or HALF_EVEN, and loud (never saturating) past 2^63. A profit is the
 * rounded DIFFERENCE, not the difference of the rounded parts. Both are asserted on exact .5 ties.
 */
public final class FifoMatcher {
  private FifoMatcher() {}

  /** A probe is filled within this many game ticks (store.mjs MARGIN_CHECK_TICKS). */
  public static final int MARGIN_CHECK_TICKS = 2;
  /** One game tick, for ordering a purchase by its first fill. */
  public static final long GAME_TICK_MS = 600;

  /** A position the player said is gone (store.mjs closePosition): {reason, at}. */
  public static final class Closed {
    public final String reason;
    public final long at;

    public Closed(String reason, long at) {
      this.reason = reason;
      this.at = at;
    }
  }

  /** An automatic flip: one buy lot, fully sold (or, when closed, the part that was sold: partial). */
  public static final class AutoFlip {
    public final String id;
    public final String account;
    public final int itemId;
    public final String item;
    public final long quantity;
    public final long capital;
    public final long netProceeds;
    public final long profit;
    public final Long firstBuy;
    public final Long lastSell;
    public final double hold;
    public final String buyId;
    public final List<String> sellIds;
    public final boolean exact;
    public final String source = "auto-fifo";
    /** True for the sold part of a closed lot; null otherwise (the JS object has no such key). */
    public final Boolean partial;
    public final String closedReason;

    AutoFlip(Lot lot, long quantity, Boolean partial, String closedReason) {
      this.id = "auto:" + lot.offerId;
      this.account = lot.account;
      this.itemId = lot.itemId;
      this.item = lot.item;
      this.quantity = quantity;
      this.capital = Js.round(lot.capital);
      this.netProceeds = Js.round(lot.netProceeds);
      this.profit = Js.round(lot.netProceeds - lot.capital);
      this.firstBuy = lot.firstSeen;
      this.lastSell = lot.lastSell;
      this.hold = lot.lastSell == null || lot.firstSeen == null ? Double.NaN : (double) (lot.lastSell - lot.firstSeen) / 3600000;
      this.buyId = lot.offerId;
      this.sellIds = Collections.unmodifiableList(new ArrayList<>(lot.sellIds));
      this.exact = lot.exact;
      this.partial = partial;
      this.closedReason = closedReason;
    }
  }

  /**
   * A SELL offer that ended while EVI was not watching ({@link Store}'s ended-unseen rule), with the packet ts at which it
   * was found gone. NEVER a sale: no flip, no profit, no FIFO match -- it only limits what an open lot may claim.
   */
  public static final class EndedUnseen {
    public final Offer offer;
    public final long at;

    public EndedUnseen(Offer offer, long at) {
      this.offer = offer;
      this.at = at;
    }
  }

  /**
   * What an open lot carries when a vanished sell listing may have held it (store.mjs {@code endedUnseen}): the listing's
   * offerId, price, when it was found gone, and how many of the lot's remaining units it covered (fewer than
   * {@code remaining} = partly covered).
   */
  public static final class EndedUnseenMark {
    public final String sellId;
    public final long price;
    public final long at;
    public final long quantity;

    public EndedUnseenMark(String sellId, long price, long at, long quantity) {
      this.sellId = sellId;
      this.price = price;
      this.at = at;
      this.quantity = quantity;
    }
  }

  /** A lot still (partly) held. unitCost is the real average paid, spent/filled, never the offer price. */
  public static final class OpenPosition {
    public final String account;
    public final int itemId;
    public final String item;
    public final String buyId;
    public final long remaining;
    public final long totalQty;
    public final Long firstSeen;
    public final double unitCost;
    public final boolean partiallySold;
    /** Non-null only when a sell listing that may have held this lot ended unseen (the JS object has no key otherwise). */
    public final EndedUnseenMark endedUnseen;

    public OpenPosition(String account, int itemId, String item, String buyId, long remaining, long totalQty, Long firstSeen,
                        double unitCost, boolean partiallySold) {
      this(account, itemId, item, buyId, remaining, totalQty, firstSeen, unitCost, partiallySold, null);
    }

    public OpenPosition(String account, int itemId, String item, String buyId, long remaining, long totalQty, Long firstSeen,
                        double unitCost, boolean partiallySold, EndedUnseenMark endedUnseen) {
      this.endedUnseen = endedUnseen;
      this.account = account;
      this.itemId = itemId;
      this.item = item;
      this.buyId = buyId;
      this.remaining = remaining;
      this.totalQty = totalQty;
      this.firstSeen = firstSeen;
      this.unitCost = unitCost;
      this.partiallySold = partiallySold;
    }
  }

  /** A sale matching cannot account for: the offer itself, plus how much of it and why. */
  public static final class UnmatchedSell {
    public final Offer offer;
    /** Null when no part could be matched because the sale had no usable tax calculation. */
    public final Long unmatchedQty;
    public final String reason;

    UnmatchedSell(Offer offer, Long unmatchedQty, String reason) {
      this.offer = offer;
      this.unmatchedQty = unmatchedQty;
      this.reason = reason;
    }
  }

  public static final class Result {
    public final List<AutoFlip> flips;
    public final List<OpenPosition> openPositions;
    public final List<UnmatchedSell> unmatchedSells;

    Result(List<AutoFlip> flips, List<OpenPosition> openPositions, List<UnmatchedSell> unmatchedSells) {
      this.flips = Collections.unmodifiableList(flips);
      this.openPositions = Collections.unmodifiableList(openPositions);
      this.unmatchedSells = Collections.unmodifiableList(unmatchedSells);
    }
  }

  static final String NO_TAX = "No usable tax calculation for this sale (pre-tax-era or invalid data)";
  static final String OVERSOLD = "Sold quantity exceeds every known preceding buy for this account/item -- likely a buy observed only partway through, or stock held before EVI started watching";

  private static final class Lot {
    final String offerId, account, item;
    final int itemId;
    long remaining;
    final long totalQty;
    final double unitCost;
    final Long firstSeen;
    /** availableAt of the buy: a sell listing placed before this could not have held the lot's units. */
    final double at;
    double capital, netProceeds;
    final List<String> sellIds = new ArrayList<>();
    boolean exact = true;
    Long lastSell;

    Lot(Offer o, double at) {
      this.at = at;
      offerId = o.offerId;
      account = o.account;
      itemId = o.itemId;
      item = o.name;
      remaining = o.filled;
      totalQty = o.filled;
      unitCost = (double) o.spent / o.filled;
      firstSeen = o.firstSeen;
    }
  }

  /**
   * A "margin check": the one-item probe placed at a deliberately bad price to find what an item really
   * trades at. INVISIBLE ON PURPOSE: never a flip, never an open position. Positive evidence only --
   * exactly one unit, filled within two ticks, AND at a strictly better price than asked (the fingerprint
   * a probe has by construction). An unknown tick count is never a probe.
   */
  public static boolean isMarginCheck(Offer o) {
    return o != null && o.total == 1 && o.filled == 1 && o.ticksToFill != null && o.ticksToFill >= 0
      && o.ticksToFill <= MARGIN_CHECK_TICKS && filledBetterThanAsked(o);
  }

  private static boolean filledBetterThanAsked(Offer o) {
    if (!(o.filled > 0) || !(o.price > 0)) return false;
    double actual = (double) o.spent / o.filled;
    return "buy".equals(o.side()) ? actual < o.price : actual > o.price;
  }

  /**
   * When an offer's goods or GP came into existence, for the FIFO order. A sale: when it completed. A
   * purchase: its FIRST fill (firstSeen + ticks x 600ms), never later than its completion, because part of
   * a buy can be collected and sold while the rest is still open. NaN only when the offer carries no time
   * at all, which the sort then treats as equal to everything, as JS does.
   */
  public static double availableAt(Offer o) {
    Long completed = o.completedAt != null ? o.completedAt : o.firstSeen;
    if ("buy".equals(o.side()) && o.ticksToFill != null && o.ticksToFill >= 0 && o.firstSeen != null) {
      double first = (double) o.firstSeen + (double) o.ticksToFill * GAME_TICK_MS;
      return completed == null ? Double.NaN : Math.min(first, (double) completed);
    }
    return completed == null ? Double.NaN : (double) completed;
  }

  public static Result computeAutoFlips(List<Offer> offers, Map<String, Closed> closed) {
    return computeAutoFlips(offers, closed, Collections.emptyList());
  }

  /** One vanished listing's units still to hand out to the lots. */
  private static final class Vanished {
    final EndedUnseen s;
    long left;

    Vanished(EndedUnseen s) {
      this.s = s;
      this.left = s.offer.total;
    }
  }

  /**
   * computeAutoFlips with the sells that ENDED UNSEEN: never sales; after matching, each one's listed quantity ({@code total}:
   * every unit left the bag when listed) is handed, oldest listing first, to the open lots of the same account and item that
   * existed when it was listed, oldest lot first. A lot that receives any carries {@link EndedUnseenMark} with the FIRST
   * listing that covered it and the units covered.
   *
   * <p>An ended-unseen BUY in the same list (the maintainer's decision, 8 Oct 2026) is different: its FILLED units, as last seen, were certainly
   * bought, so they become an ordinary lot exactly as a cancelled part-filled buy's do -- the same filters (knownStart,
   * filled &gt; 0, not a margin check), cost basis spent/filled, ordered as though it had finished at its last sighting
   * ({@code updated}). Added to its item's group AFTER every completed offer, as store.mjs does. The caller leaves out buys it
   * would leave out of {@code offers} (manually matched, or marked personal use).
   */
  public static Result computeAutoFlips(List<Offer> offers, Map<String, Closed> closed, List<EndedUnseen> endedUnseen) {
    Map<String, List<Vanished>> vanished = new LinkedHashMap<>();
    if (endedUnseen != null) for (EndedUnseen s : endedUnseen) {
      if (s == null || !"sell".equals(s.offer.side()) || !(s.offer.total > 0)) continue;
      vanished.computeIfAbsent(s.offer.account + " " + s.offer.itemId, k -> new ArrayList<>()).add(new Vanished(s));
    }
    for (List<Vanished> list : vanished.values())
      list.sort((a, b) -> Js.compare(seen(a.s.offer), seen(b.s.offer))); // stable, like V8's
    Map<String, List<Offer>> groups = new LinkedHashMap<>();
    for (Offer o : offers) {
      // Margin checks are not trades and must not become flips or open positions.
      if (o == null || !o.knownStart || !o.finished() || !(o.filled > 0) || isMarginCheck(o)) continue;
      groups.computeIfAbsent(o.account + " " + o.itemId, k -> new ArrayList<>()).add(o);
    }
    if (endedUnseen != null) for (EndedUnseen e : endedUnseen) {
      if (e == null) continue;
      Offer b = e.offer;
      if (!"buy".equals(b.side()) || !b.knownStart || !(b.filled > 0) || isMarginCheck(b)) continue;
      // {...b, completedAt: b.completedAt ?? b.updated}
      Offer asFinished = new Offer(b.slot, b.state, b.offerId, b.itemId, b.name, b.price, b.total, b.filled, b.spent, b.knownStart,
        b.ticksToFill, b.account, b.session, b.firstSeen, b.updated, b.completedAt != null ? b.completedAt : b.updated, b.recorded);
      groups.computeIfAbsent(b.account + " " + b.itemId, k -> new ArrayList<>()).add(asFinished);
    }
    List<AutoFlip> flips = new ArrayList<>();
    List<OpenPosition> open = new ArrayList<>();
    List<UnmatchedSell> unmatched = new ArrayList<>();
    for (List<Offer> list : groups.values()) {
      List<Offer> sorted = new ArrayList<>(list);
      sorted.sort((a, b) -> Js.compare(availableAt(a), availableAt(b))); // List.sort is stable, like V8's
      List<Lot> lots = new ArrayList<>();
      for (Offer o : sorted) {
        double at = availableAt(o);
        // Lots closed before this offer: settle their sold part and drop them, walking from the END as
        // store.mjs does (so several closed at once land in reverse order).
        for (int i = lots.size() - 1; i >= 0; i--) {
          Closed c = closed.get(lots.get(i).offerId);
          if (c != null && c.at <= at) {
            soldPart(lots.get(i), closed, flips);
            lots.remove(i);
          }
        }
        if ("buy".equals(o.side())) {
          lots.add(new Lot(o, at));
          continue;
        }
        Tax.Proceeds proceeds = Tax.saleProceeds(o);
        if (proceeds == null) {
          unmatched.add(new UnmatchedSell(o, null, NO_TAX));
          continue;
        }
        long remainingSellQty = o.filled;
        double unitNet = (double) proceeds.net / o.filled;
        while (remainingSellQty > 0 && !lots.isEmpty() && lots.get(0).remaining > 0) {
          Lot lot = lots.get(0);
          long take = Math.min(lot.remaining, remainingSellQty);
          lot.remaining -= take;
          remainingSellQty -= take;
          lot.capital += take * lot.unitCost;
          lot.netProceeds += take * unitNet;
          lot.sellIds.add(o.offerId);
          lot.exact = lot.exact && proceeds.exact;
          lot.lastSell = o.completedAt != null ? o.completedAt : o.firstSeen;
          if (lot.remaining == 0) {
            flips.add(new AutoFlip(lot, lot.totalQty, null, null));
            lots.remove(0);
          }
        }
        if (remainingSellQty > 0) unmatched.add(new UnmatchedSell(o, remainingSellQty, OVERSOLD));
      }
      List<Vanished> gone = vanished.getOrDefault(list.get(0).account + " " + list.get(0).itemId, Collections.emptyList());
      for (Lot lot : lots) {
        if (closed.containsKey(lot.offerId)) {
          soldPart(lot, closed, flips);
          continue;
        }
        if (!(lot.remaining > 0)) continue;
        // Only a listing placed once this lot's goods existed can have held them.
        long need = lot.remaining;
        EndedUnseen first = null;
        for (Vanished v : gone) {
          if (!(need > 0)) break;
          if (!(v.left > 0) || !(seen(v.s.offer) >= lot.at)) continue;
          long take = Math.min(v.left, need);
          v.left -= take;
          need -= take;
          if (first == null) first = v.s;
        }
        EndedUnseenMark mark = first == null ? null : new EndedUnseenMark(first.offer.offerId, first.offer.price, first.at, lot.remaining - need);
        open.add(new OpenPosition(lot.account, lot.itemId, lot.item, lot.offerId, lot.remaining,
          lot.totalQty, lot.firstSeen, lot.unitCost, lot.remaining < lot.totalQty, mark));
      }
    }
    return new Result(flips, open, unmatched);
  }

  /** An offer's firstSeen as JS reads it: NaN when absent, so every comparison with it is false. */
  private static double seen(Offer o) {
    return o.firstSeen == null ? Double.NaN : (double) o.firstSeen;
  }

  private static void soldPart(Lot lot, Map<String, Closed> closed, List<AutoFlip> flips) {
    long qty = lot.totalQty - lot.remaining;
    if (qty > 0) flips.add(new AutoFlip(lot, qty, Boolean.TRUE, closed.get(lot.offerId).reason));
  }

  /** What the profit total does not include, in counts and GP (store.mjs dataHealthOf). Nothing estimated. */
  public static final class DataHealth {
    public final int openPositions;
    public final long openCost;
    public final List<Integer> openItemIds;
    public final int unmatchedSales;
    public final long unmatchedGross;
    public final int personalUseSales;
    public final long personalUseGross;

    DataHealth(int openPositions, long openCost, List<Integer> openItemIds, int unmatchedSales, long unmatchedGross,
               int personalUseSales, long personalUseGross) {
      this.openPositions = openPositions;
      this.openCost = openCost;
      this.openItemIds = Collections.unmodifiableList(openItemIds);
      this.unmatchedSales = unmatchedSales;
      this.unmatchedGross = unmatchedGross;
      this.personalUseSales = personalUseSales;
      this.personalUseGross = personalUseGross;
    }
  }

  /**
   * Unmatched sales are split between "really unmatched" and "sale of stock marked personal use": each
   * unmatched sale (oldest first) is attributed to flagged buys of the SAME account and item placed before
   * it, never more units than those buys bought.
   */
  public static DataHealth dataHealthOf(Result auto, List<Offer> personalUseBuys) {
    double openCost = 0;
    for (OpenPosition p : auto.openPositions) openCost += p.unitCost > 0 && p.remaining > 0 ? p.unitCost * p.remaining : 0;
    Map<String, List<double[]>> pools = new HashMap<>(); // {at, left}
    for (Offer b : personalUseBuys) {
      if (b == null || !(b.filled > 0)) continue;
      pools.computeIfAbsent(b.account + "|" + b.itemId, k -> new ArrayList<>())
        .add(new double[]{b.firstSeen != null ? b.firstSeen : 0, b.filled});
    }
    int unmatchedSales = 0, personalUseSales = 0;
    double unmatchedGross = 0, personalUseGross = 0;
    List<UnmatchedSell> byTime = new ArrayList<>(auto.unmatchedSells);
    byTime.sort((a, b) -> Js.compare(when(a.offer), when(b.offer)));
    for (UnmatchedSell u : byTime) {
      Offer o = u.offer;
      Long filled = o.filled > 0 ? o.filled : null;
      Long qty = u.unmatchedQty != null ? u.unmatchedQty : filled;
      Double gpPerUnit = filled != null ? (double) o.spent / filled : null;
      long covered = 0;
      for (double[] lot : pools.getOrDefault(o.account + "|" + o.itemId, Collections.emptyList())) {
        if (qty == null || !(qty > covered)) break;
        if (lot[0] > when(o) || lot[1] <= 0) continue;
        long take = (long) Math.min(lot[1], (double) (qty - covered));
        lot[1] -= take;
        covered += take;
      }
      if (covered > 0) {
        personalUseSales++;
        if (gpPerUnit != null) personalUseGross += gpPerUnit * covered;
      }
      if (qty == null) {
        unmatchedSales++;
        unmatchedGross += o.spent;
      } else if (qty - covered > 0) {
        unmatchedSales++;
        if (gpPerUnit != null) unmatchedGross += gpPerUnit * (qty - covered);
      }
    }
    Set<Integer> ids = new LinkedHashSet<>();
    for (OpenPosition p : auto.openPositions) ids.add(p.itemId);
    return new DataHealth(auto.openPositions.size(), Js.round(openCost), new ArrayList<>(ids), unmatchedSales,
      Js.round(unmatchedGross), personalUseSales, Js.round(personalUseGross));
  }

  private static double when(Offer o) {
    if (o.completedAt != null) return o.completedAt;
    if (o.updated != null) return o.updated;
    if (o.firstSeen != null) return o.firstSeen;
    return 0;
  }
}

package com.evi.live.journal;

/**
 * A completed trade imported from another tracker (store.mjs {@code importFlips}). Feeds ranking, never
 * the profit total: EVI did not observe it.
 */
public final class ImportedFlip {
  public final String fp;
  public final String source;
  public final int itemId;
  public final String item;
  public final long quantity;
  public final long capital;
  public final long netProceeds;
  public final long profit;
  public final long firstBuy;
  public final long lastSell;
  public final double hold;
  /** Null when the import named no account (the line carries "account":null). */
  public final String account;

  public ImportedFlip(String fp, String source, int itemId, String item, long quantity, long capital, long netProceeds,
                      long profit, long firstBuy, long lastSell, double hold, String account) {
    this.fp = fp;
    this.source = source;
    this.itemId = itemId;
    this.item = item;
    this.quantity = quantity;
    this.capital = capital;
    this.netProceeds = netProceeds;
    this.profit = profit;
    this.firstBuy = firstBuy;
    this.lastSell = lastSell;
    this.hold = hold;
    this.account = account;
  }

  /**
   * What the trade IS, so the same trade cannot be imported twice through two routes with different
   * fingerprints: {@code [itemId, account ?? '', quantity, profit, firstBuy, lastSell].join('|')}.
   */
  public String contentKey() {
    return itemId + "|" + (account == null ? "" : account) + "|" + quantity + "|" + profit + "|" + firstBuy + "|" + lastSell;
  }
}

package com.evi.live.journal;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;

/**
 * The journal line format, both ways.
 *
 * <p>{@link #encodeLine} writes exactly what {@code JSON.stringify(record)} writes in store.mjs: the same
 * keys in the same order, the same string escapes, the same number text. That is what keeps an
 * events.jsonl the plugin writes readable by every private tool, and it is checked byte for byte: against
 * the JS engine's own lines in JournalVectorsTest, and against every line of the real journal in the
 * private parity test. No Gson instance is involved (Gson HTML-escapes {@code '} and {@code =} by
 * default, and prints 3.0 for 3).
 *
 * <p>{@link #decode} reads a parsed line (any parser's tree) leniently, as {@code apply} does: a record
 * is trusted because it was validated when it was written.
 */
public final class JournalCodec {
  private JournalCodec() {}

  // ---------------------------------------------------------------------------------------------- decode

  public static JournalRecord decode(JsonElement line) {
    if (line == null || !line.isJsonObject()) throw new JournalException("Journal line is not an object");
    JsonObject r = line.getAsJsonObject();
    String type = Js.string(r.get("type"));
    if (type == null) type = "";
    switch (type) {
      case "flip-reopened": case "flip-removed": case "flip-restored":
        return new JournalRecord.FlipMark(type, Js.string(r.get("id")));
      case "flip":
        return new JournalRecord.FlipRecord(flip(r.getAsJsonObject("flip")));
      case "personal-use":
        return new JournalRecord.PersonalUse(false, Js.string(r.get("buyId")));
      case "personal-use-undo":
        return new JournalRecord.PersonalUse(true, Js.string(r.get("buyId")));
      case "personal-use-item":
        return new JournalRecord.PersonalUseItem(i(r, "itemId"), Js.number(r.get("kept")));
      case "personal-use-item-undo":
        return new JournalRecord.PersonalUseItemUndo(i(r, "itemId"));
      case "flips-imported": {
        List<ImportedFlip> flips = new ArrayList<>();
        for (JsonElement e : r.getAsJsonArray("flips")) flips.add(imported(e.getAsJsonObject()));
        return new JournalRecord.FlipsImported(flips);
      }
      case "flips-import-removed":
        return new JournalRecord.FlipsImportRemoved(Js.string(r.get("source")));
      case "purchase-recorded": {
        JsonObject o = r.getAsJsonObject("purchase");
        return new JournalRecord.PurchaseRecorded(Js.string(o.get("offerId")), i(o, "itemId"), Js.string(o.get("name")),
          l(o, "quantity"), l(o, "unitPrice"), l(o, "at"), Js.string(o.get("account")));
      }
      case "purchase-record-removed":
        return new JournalRecord.PurchaseRecordRemoved(Js.string(r.get("offerId")));
      case "position-closed":
        return new JournalRecord.PositionClosed(Js.string(r.get("buyId")), Js.string(r.get("reason")), l(r, "at"));
      case "position-reopened":
        return new JournalRecord.PositionReopened(Js.string(r.get("buyId")));
      default:
        // store.mjs treats every other record as a packet record (its apply() falls through to r.packet).
        if (!r.has("packet") || !r.get("packet").isJsonObject()) throw new JournalException("Journal line has no packet: type " + type);
        return new JournalRecord.PacketRecord(l(r, "received"), packet(r.getAsJsonObject("packet")));
    }
  }

  private static Packet packet(JsonObject p) {
    List<Packet.SlotOffer> offers = new ArrayList<>();
    for (JsonElement e : p.getAsJsonArray("offers")) {
      JsonObject o = e.getAsJsonObject();
      Double ticks = Js.number(o.get("ticksToFill"));
      offers.add(new Packet.SlotOffer(i(o, "slot"), Js.string(o.get("state")), Js.string(o.get("offerId")), i(o, "itemId"),
        Js.string(o.get("name")), l(o, "price"), l(o, "total"), l(o, "filled"), l(o, "spent"),
        o.has("knownStart") && o.get("knownStart").getAsBoolean(), ticks == null ? null : (int) (double) ticks));
    }
    return new Packet(i(p, "version"), Js.string(p.get("session")), Js.string(p.get("account")), l(p, "seq"), l(p, "ts"),
      p.get("loggedIn").getAsBoolean(), offers);
  }

  static ManualFlip flip(JsonObject f) {
    List<String> sellIds = null;
    if (f.has("sellIds") && f.get("sellIds").isJsonArray()) {
      sellIds = new ArrayList<>();
      for (JsonElement e : f.getAsJsonArray("sellIds")) sellIds.add(Js.string(e));
    }
    Double hold = Js.number(f.get("hold"));
    return new ManualFlip(Js.string(f.get("id")), Js.string(f.get("buyId")), Js.string(f.get("sellId")), sellIds,
      Js.string(f.get("account")), i(f, "itemId"), Js.string(f.get("item")), l(f, "quantity"), l(f, "capital"),
      l(f, "netProceeds"), l(f, "profit"), lOrNull(f, "firstBuy"), lOrNull(f, "lastSell"), hold == null ? Double.NaN : hold,
      lOrNull(f, "confirmedAt"), Js.string(f.get("source")), Js.string(f.get("proceedsMethod")));
  }

  static ImportedFlip imported(JsonObject f) {
    Double hold = Js.number(f.get("hold"));
    return new ImportedFlip(Js.string(f.get("fp")), Js.string(f.get("source")), i(f, "itemId"), Js.string(f.get("item")),
      l(f, "quantity"), l(f, "capital"), l(f, "netProceeds"), l(f, "profit"), l(f, "firstBuy"), l(f, "lastSell"),
      hold == null ? Double.NaN : hold, Js.string(f.get("account")));
  }

  private static int i(JsonObject o, String k) {
    Double d = Js.number(o.get(k));
    return d == null ? 0 : (int) (double) d;
  }

  private static long l(JsonObject o, String k) {
    Double d = Js.number(o.get(k));
    return d == null ? 0 : (long) (double) d;
  }

  private static Long lOrNull(JsonObject o, String k) {
    Double d = Js.number(o.get(k));
    return d == null ? null : (long) (double) d;
  }

  // ---------------------------------------------------------------------------------------------- encode

  /** The line store.mjs would write for this record, without the trailing newline. */
  public static String encodeLine(JournalRecord rec) {
    Obj r = new Obj().put("type", str(rec.type()));
    if (rec instanceof JournalRecord.PacketRecord) {
      JournalRecord.PacketRecord x = (JournalRecord.PacketRecord) rec;
      Packet p = x.packet;
      List<String> offers = new ArrayList<>();
      for (Packet.SlotOffer o : p.offers) {
        Obj w = new Obj().put("slot", num(o.slot)).put("state", str(o.state)).put("offerId", str(o.offerId)).put("itemId", num(o.itemId))
          .put("name", str(o.name)).put("price", num(o.price)).put("total", num(o.total)).put("filled", num(o.filled))
          .put("spent", num(o.spent)).put("knownStart", String.valueOf(o.knownStart));
        if (o.ticksToFill != null) w.put("ticksToFill", num(o.ticksToFill));
        offers.add(w.toString());
      }
      Obj pk = new Obj().put("version", num(p.version)).put("session", str(p.session)).put("account", str(p.account))
        .put("seq", num(p.seq)).put("ts", num(p.ts)).put("loggedIn", String.valueOf(p.loggedIn)).put("offers", arr(offers));
      r.put("received", num(x.received)).put("packet", pk.toString());
    } else if (rec instanceof JournalRecord.FlipRecord) {
      r.put("flip", flipJson(((JournalRecord.FlipRecord) rec).flip));
    } else if (rec instanceof JournalRecord.FlipMark) {
      r.put("id", str(((JournalRecord.FlipMark) rec).id));
    } else if (rec instanceof JournalRecord.PersonalUse) {
      r.put("buyId", str(((JournalRecord.PersonalUse) rec).buyId));
    } else if (rec instanceof JournalRecord.PersonalUseItem) {
      JournalRecord.PersonalUseItem x = (JournalRecord.PersonalUseItem) rec;
      r.put("itemId", num(x.itemId));
      if (x.kept != null) r.put("kept", dbl(x.kept));
    } else if (rec instanceof JournalRecord.PersonalUseItemUndo) {
      r.put("itemId", num(((JournalRecord.PersonalUseItemUndo) rec).itemId));
    } else if (rec instanceof JournalRecord.FlipsImported) {
      List<String> flips = new ArrayList<>();
      for (ImportedFlip f : ((JournalRecord.FlipsImported) rec).flips) flips.add(importedJson(f));
      r.put("flips", arr(flips));
    } else if (rec instanceof JournalRecord.FlipsImportRemoved) {
      r.put("source", str(((JournalRecord.FlipsImportRemoved) rec).source));
    } else if (rec instanceof JournalRecord.PurchaseRecorded) {
      JournalRecord.PurchaseRecorded x = (JournalRecord.PurchaseRecorded) rec;
      r.put("purchase", new Obj().put("offerId", str(x.offerId)).put("itemId", num(x.itemId)).put("name", str(x.name))
        .put("quantity", num(x.quantity)).put("unitPrice", num(x.unitPrice)).put("at", num(x.at)).put("account", str(x.account)).toString());
    } else if (rec instanceof JournalRecord.PurchaseRecordRemoved) {
      r.put("offerId", str(((JournalRecord.PurchaseRecordRemoved) rec).offerId));
    } else if (rec instanceof JournalRecord.PositionClosed) {
      JournalRecord.PositionClosed x = (JournalRecord.PositionClosed) rec;
      r.put("buyId", str(x.buyId)).put("reason", str(x.reason)).put("at", num(x.at));
    } else if (rec instanceof JournalRecord.PositionReopened) {
      r.put("buyId", str(((JournalRecord.PositionReopened) rec).buyId));
    } else {
      throw new IllegalArgumentException("unknown record " + rec.getClass());
    }
    return r.toString();
  }

  // confirm()'s key order. sellId is always written (null when several sales); sellIds and the optional
  // numbers only when present, so a line journalled before a field existed re-encodes as it was.
  private static String flipJson(ManualFlip f) {
    Obj w = new Obj().put("id", str(f.id)).put("buyId", str(f.buyId)).put("sellId", str(f.sellId));
    if (f.sellIds != null) {
      List<String> ids = new ArrayList<>();
      for (String s : f.sellIds) ids.add(str(s));
      w.put("sellIds", arr(ids));
    }
    w.put("account", str(f.account)).put("itemId", num(f.itemId)).put("item", str(f.item)).put("quantity", num(f.quantity))
      .put("capital", num(f.capital)).put("netProceeds", num(f.netProceeds)).put("profit", num(f.profit));
    if (f.firstBuy != null) w.put("firstBuy", num(f.firstBuy));
    if (f.lastSell != null) w.put("lastSell", num(f.lastSell));
    if (!Double.isNaN(f.hold)) w.put("hold", dbl(f.hold));
    if (f.confirmedAt != null) w.put("confirmedAt", num(f.confirmedAt));
    if (f.source != null) w.put("source", str(f.source));
    if (f.proceedsMethod != null) w.put("proceedsMethod", str(f.proceedsMethod));
    return w.toString();
  }

  private static String importedJson(ImportedFlip f) {
    return new Obj().put("fp", str(f.fp)).put("source", str(f.source)).put("itemId", num(f.itemId)).put("item", str(f.item))
      .put("quantity", num(f.quantity)).put("capital", num(f.capital)).put("netProceeds", num(f.netProceeds)).put("profit", num(f.profit))
      .put("firstBuy", num(f.firstBuy)).put("lastSell", num(f.lastSell)).put("hold", dbl(f.hold)).put("account", str(f.account))
      .put("imported", "true").toString();
  }

  private static String str(String s) {
    return s == null ? "null" : Js.quote(s);
  }

  // String(n) for an integer. Up to 2^53 that is every digit; past it JS prints the SHORTEST digits that
  // read back to the same double (4611686014132420608 is written 4611686014132420600), and a long that
  // came out of the JS-equal arithmetic in Js is always such a double, so the conversion loses nothing.
  private static String num(long n) {
    return Js.isSafe(n) ? Long.toString(n) : Js.numberToString((double) n);
  }

  private static String dbl(double d) {
    // JSON.stringify writes NaN and the infinities as null.
    return Double.isNaN(d) || Double.isInfinite(d) ? "null" : Js.numberToString(d);
  }

  private static String arr(List<String> items) {
    return "[" + String.join(",", items) + "]";
  }

  /** Keys in insertion order, values already JSON text. */
  private static final class Obj {
    private final StringBuilder sb = new StringBuilder("{");
    private boolean first = true;

    Obj put(String k, String rawJson) {
      if (!first) sb.append(',');
      first = false;
      Js.quote(sb, k);
      sb.append(':').append(rawJson);
      return this;
    }

    @Override public String toString() {
      return sb.toString() + "}";
    }
  }
}

package com.evi.live.journal;

/**
 * A refusal from the journal engine. The message is the exact sentence store.mjs throws, because the
 * bridge sends it to the player as {@code {error: message}} and the wording is a considered thing.
 */
public final class JournalException extends RuntimeException {
  public JournalException(String message) {
    super(message);
  }
}

package com.evi.live.journal;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardOpenOption;
import java.nio.file.attribute.FileTime;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Filepath;

/**
 * The plugin's journal files, one per account, in the bridge's events.jsonl line format, read and written
 * ONLY through RuneLite's {@link Filepath} (the 6 Oct 2026 forbidden-API list bans java.io file APIs).
 *
 * <p>ONE FILE PER ACCOUNT, because two RuneLite clients are two processes sharing one data folder. The
 * game never lets one account be logged in twice, so each file has exactly one writer at a time. The
 * writer still checks, before and after every append, that the file is the length it last saw: a change
 * it did not make means another process wrote, and the caller re-reads before trusting its own state.
 *
 * <p>Appends are one complete line per write call, in APPEND mode, then forced to disk (store.mjs does the
 * same: one writeFileSync of the line, then fsync). A reader only ever consumes up to the last newline, so
 * a line still being written is never half-read.
 *
 * <p>AN ACCOUNT'S EVENTS FILE IS NEVER REWRITTEN, only appended to (and, after a crash, cut back to its last
 * complete line, which no reader ever consumed past). That invariant is what lets another client follow a
 * file by remembering how many bytes it has read. The one-time import therefore does NOT merge into the
 * events file: it writes a SEPARATE, immutable {@code imported-<account>.jsonl}, created under a name that
 * does not exist yet ({@link #writeNew}). Replacing an existing file is avoided on purpose: on Windows a
 * move over a file fails with AccessDenied whenever any other process has that file open, which is exactly
 * what a second client's read does.
 */
final class JournalFile {
  private JournalFile() {}

  static final String PREFIX = "events-";
  static final String SUFFIX = ".jsonl";
  static final String IMPORTED_PREFIX = "imported-";
  /** store.mjs refuses to append past 100 MB; so does this. */
  static final long MAX_BYTES = 100L * 1024 * 1024;
  static final String TOO_LARGE = "Journal reached 100 MB. Back up data and contact support before continuing.";
  private static final Pattern NAME = Pattern.compile("events-([a-zA-Z0-9-]{1,80})\\.jsonl");
  private static final Pattern IMPORTED_NAME = Pattern.compile("imported-([a-zA-Z0-9-]{1,80})\\.jsonl");

  /**
   * TEST SEAM: told (file, "before") just before append() reads the length it checks, and (file, "after")
   * between its write and the length check that follows, so a test can stand in for another writer at
   * exactly those moments. Null in production.
   */
  static volatile BiConsumer<Filepath, String> appendSeam;
  /** TEST SEAM: told the target just before writeNew() moves its finished temporary file into place. Null in production. */
  static volatile Consumer<Filepath> moveSeam;

  /** Another process changed the file between this process's reads and its write. */
  static final class ConcurrentWrite extends RuntimeException {
    ConcurrentWrite(String message) {
      super(message);
    }
  }

  /** The file an account's records live in. The account must be a store.mjs id (letters, digits, hyphens). */
  static String fileName(String account) {
    if (!Packet.id(account)) throw new JournalException("Invalid account");
    return PREFIX + account + SUFFIX;
  }

  /** The one-time import's file for an account: the bridge's records for it, written once, never changed. */
  static String importedFileName(String account) {
    if (!Packet.id(account)) throw new JournalException("Invalid account");
    return IMPORTED_PREFIX + account + SUFFIX;
  }

  /** The account a journal file belongs to, or null when the name is not a journal file's. */
  static String accountOf(String fileName) {
    return match(NAME, fileName);
  }

  /** The account an imported file belongs to, or null when the name is not an imported file's. */
  static String importedAccountOf(String fileName) {
    return match(IMPORTED_NAME, fileName);
  }

  private static String match(Pattern p, String fileName) {
    if (fileName == null) return null;
    Matcher m = p.matcher(fileName);
    return m.matches() ? m.group(1) : null;
  }

  /** Every events file in {@code dir}, keyed by account, in ascending name order. */
  static List<String> accounts(Filepath dir) throws IOException {
    return list(dir, NAME);
  }

  /** Every imported file in {@code dir}, keyed by account, in ascending name order. */
  static List<String> importedAccounts(Filepath dir) throws IOException {
    return list(dir, IMPORTED_NAME);
  }

  private static List<String> list(Filepath dir, Pattern p) throws IOException {
    List<String> out = new ArrayList<>();
    if (!dir.isDirectory()) return out;
    try (java.util.stream.Stream<Filepath> s = dir.walk(1)) {
      s.forEach(f -> {
        String a = f.isFile() ? match(p, f.getFileName()) : null;
        if (a != null) out.add(a);
      });
    }
    out.sort(null);
    return out;
  }

  static long size(Filepath f) throws IOException {
    return f.exists() ? f.size() : 0;
  }

  /**
   * The bytes of {@code f} from {@code from} up to and including the LAST newline -- never a partial
   * trailing line. Empty when there is nothing complete past {@code from}.
   */
  static byte[] readComplete(Filepath f, long from) throws IOException {
    if (!f.exists()) return new byte[0];
    try (FileChannel ch = f.openFileChannel(StandardOpenOption.READ)) {
      long size = ch.size();
      if (size <= from) return new byte[0];
      long len = size - from;
      if (len > Integer.MAX_VALUE - 16) throw new IOException("journal file too large to read");
      ByteBuffer buf = ByteBuffer.allocate((int) len);
      ch.position(from);
      while (buf.hasRemaining() && ch.read(buf) >= 0) {
        // read until full or end of file
      }
      byte[] b = buf.array();
      int end = lastNewline(b, buf.position());
      return Arrays.copyOf(b, end);
    }
  }

  /** Index just past the last '\n' in the first {@code length} bytes, or 0. */
  static int lastNewline(byte[] b, int length) {
    for (int i = length - 1; i >= 0; i--) if (b[i] == '\n') return i + 1;
    return 0;
  }

  /** The last complete line of the first {@code length} bytes (its '\n' included), or an empty array. */
  static byte[] lastLine(byte[] b, int length) {
    int end = lastNewline(b, length);
    if (end == 0) return new byte[0];
    int start = lastNewline(b, end - 1);
    return Arrays.copyOfRange(b, start, end);
  }

  /** store.mjs's {@code split('\n').filter(Boolean)} over UTF-8 text. */
  static List<String> lines(byte[] bytes) {
    List<String> out = new ArrayList<>();
    for (String l : new String(bytes, StandardCharsets.UTF_8).split("\n", -1)) if (!l.isEmpty()) out.add(l);
    return out;
  }

  /**
   * Appends one line (which must end in '\n') when the file is exactly {@code expectedSize} long, and
   * returns the new size. Throws {@link ConcurrentWrite} WITHOUT writing when the length differs, and
   * AFTER writing when the length afterwards is not the expected one (another writer appended too: the
   * line is intact, because each write is one whole line in append mode, but the caller must re-read).
   */
  static long append(Filepath f, String line, long expectedSize) throws IOException {
    if (!line.endsWith("\n")) throw new IllegalArgumentException("a journal line must end in a newline");
    byte[] bytes = line.getBytes(StandardCharsets.UTF_8);
    try (FileChannel ch = f.openFileChannel(StandardOpenOption.CREATE, StandardOpenOption.WRITE, StandardOpenOption.APPEND)) {
      BiConsumer<Filepath, String> seam = appendSeam;
      if (seam != null) seam.accept(f, "before");
      long before = ch.size();
      if (before != expectedSize) throw new ConcurrentWrite("journal changed on disk: " + before + " bytes, expected " + expectedSize);
      if (before > MAX_BYTES) throw new JournalException(TOO_LARGE);
      ByteBuffer buf = ByteBuffer.wrap(bytes);
      while (buf.hasRemaining()) ch.write(buf);
      ch.force(true);
      if (seam != null) seam.accept(f, "after");
      long after = ch.size();
      if (after != before + bytes.length) throw new ConcurrentWrite("journal grew by " + (after - before) + " bytes, expected " + bytes.length);
      return after;
    }
  }

  /**
   * Creates {@code target} holding {@code content}, complete or not at all: written in full to a temporary
   * file in the same folder (a name no reader lists), forced to disk, then renamed into place.
   * NEVER over an existing file: when {@code target} exists this throws {@link AlreadyExists} and changes
   * nothing (see the class comment for why a replace is avoided) -- and that holds when another process
   * creates {@code target} between the check and the rename, because the rename is asked NOT to replace: a
   * rename that fails while {@code target} is there is reported as {@link AlreadyExists} too. (ATOMIC_MOVE is
   * deliberately not used: on Windows it is a move that REPLACES an existing file.) A failure leaves no
   * temporary file behind.
   */
  static void writeNew(Filepath target, byte[] content) throws IOException {
    if (target.exists()) throw new AlreadyExists(target.getFileName(), null);
    Filepath tmp = target.getParent().joinSegment(target.getFileName() + ".tmp");
    tmp.deleteIfExists();
    try {
      try (FileChannel ch = tmp.openFileChannel(StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
        ByteBuffer buf = ByteBuffer.wrap(content);
        while (buf.hasRemaining()) ch.write(buf);
        ch.force(true);
      }
      Consumer<Filepath> seam = moveSeam;
      if (seam != null) seam.accept(target);
      try {
        tmp.moveTo(target); // no REPLACE_EXISTING, no ATOMIC_MOVE: an existing target fails the move
      } catch (IOException e) {
        if (target.exists()) throw new AlreadyExists(target.getFileName(), e); // created by another writer meanwhile
        throw e;
      }
    } finally {
      tmp.deleteIfExists();
    }
  }

  /**
   * {@link #writeNew}'s target was already there (before the write, or created by another writer before its rename):
   * nothing was written. The plugin's own exception, so no java.nio.file exception class is named.
   */
  static final class AlreadyExists extends IOException {
    AlreadyExists(String fileName, IOException cause) {
      super(fileName + " already exists", cause);
    }
  }

  /**
   * store.mjs's interrupted-tail recovery, for a file this process is about to start writing: whatever
   * follows the last newline (a line cut off by a crash) is saved beside it and cut from the journal.
   * Returns the saved file's name, or null when there was nothing to recover.
   */
  static String recoverTail(Filepath f, long now) throws IOException {
    if (!f.exists()) return null;
    try (FileChannel ch = f.openFileChannel(StandardOpenOption.READ, StandardOpenOption.WRITE)) {
      long size = ch.size();
      long end = 0;
      // Scan back from the end for the last newline, in small blocks.
      ByteBuffer buf = ByteBuffer.allocate(8192);
      long pos = size;
      search:
      while (pos > 0) {
        int n = (int) Math.min(buf.capacity(), pos);
        pos -= n;
        buf.clear().limit(n);
        ch.position(pos);
        while (buf.hasRemaining() && ch.read(buf) >= 0) {
          // fill
        }
        for (int i = n - 1; i >= 0; i--) {
          if (buf.get(i) == '\n') {
            end = pos + i + 1;
            break search;
          }
        }
      }
      if (end == size) return null;
      ByteBuffer tail = ByteBuffer.allocate((int) Math.min(size - end, 16L * 1024 * 1024));
      ch.position(end);
      while (tail.hasRemaining() && ch.read(tail) >= 0) {
        // fill
      }
      String name = "interrupted-tail-" + f.getFileName() + "-" + now + ".txt";
      f.getParent().joinSegment(name).write(Arrays.copyOf(tail.array(), tail.position()));
      ch.truncate(end);
      ch.force(true);
      return name;
    }
  }

  /**
   * Bytes read from EACH end of a file for its {@link Fingerprint}. Tests lower it so a change between the two
   * windows is reachable with a small file.
   */
  static volatile int fingerprintWindow = 64 * 1024;

  /**
   * What a reader remembers about an immutable file (an account's imported file) to notice that it has been
   * changed by anything at all: its length, its last-modified time, and its first and last
   * {@link #fingerprintWindow} bytes. A file that GROWS or SHRINKS changes the length; one REPLACED with
   * content of the same length changes the time (a fresh write) or the bytes at either end. Reading both
   * ends costs at most two windows, so it is cheap enough to check before every use, unlike a hash of a file
   * that may be tens of megabytes. Its one blind spot -- same length, a restored time and identical ends --
   * is a deliberate forgery, not something a copy, an editor or another client does.
   */
  static final class Fingerprint {
    final long size;
    final FileTime modified;
    final byte[] head;
    final byte[] tail;

    Fingerprint(long size, FileTime modified, byte[] head, byte[] tail) {
      this.size = size;
      this.modified = modified;
      this.head = head;
      this.tail = tail;
    }

    @Override public boolean equals(Object o) {
      if (!(o instanceof Fingerprint)) return false;
      Fingerprint f = (Fingerprint) o;
      return size == f.size && Objects.equals(modified, f.modified) && Arrays.equals(head, f.head) && Arrays.equals(tail, f.tail);
    }

    @Override public int hashCode() {
      return Objects.hash(size, modified, Arrays.hashCode(head), Arrays.hashCode(tail));
    }
  }

  /** The {@link Fingerprint} of {@code f}; a missing file has size 0, no time and no bytes. */
  static Fingerprint fingerprint(Filepath f) throws IOException {
    if (!f.exists()) return new Fingerprint(0, null, new byte[0], new byte[0]);
    FileTime modified = f.getLastModifiedTime();
    try (FileChannel ch = f.openFileChannel(StandardOpenOption.READ)) {
      long size = ch.size();
      int window = (int) Math.min(fingerprintWindow, size);
      return new Fingerprint(size, modified, readAt(ch, 0, window), readAt(ch, size - window, window));
    }
  }

  private static byte[] readAt(FileChannel ch, long from, int len) throws IOException {
    ByteBuffer buf = ByteBuffer.allocate(len);
    ch.position(from);
    while (buf.hasRemaining() && ch.read(buf) >= 0) {
      // read until full or end of file
    }
    return Arrays.copyOf(buf.array(), buf.position());
  }

  /** The whole file as bytes (a small text file: an import marker, the import source). */
  static byte[] readAll(Filepath f) throws IOException {
    try (InputStream in = f.openInputStream()) {
      return in.readAllBytes();
    }
  }

  /** Appends text to a small local log file (the comparison log), creating it if needed. */
  static void appendText(Filepath f, String text) throws IOException {
    try (OutputStream out = f.openOutputStream(StandardOpenOption.CREATE, StandardOpenOption.WRITE, StandardOpenOption.APPEND)) {
      out.write(text.getBytes(StandardCharsets.UTF_8));
    }
  }
}

package com.evi.live.journal;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * One line of the journal ({@code events.jsonl}). The twelve kinds store.mjs writes and replays; the line
 * format itself lives in {@link JournalCodec}.
 */
public abstract class JournalRecord {
  private JournalRecord() {}

  /** The {@code type} field of the line. */
  public abstract String type();

  /** {type:'packet', received, packet}: a validated slot snapshot, journalled only when something changed. */
  public static final class PacketRecord extends JournalRecord {
    public final long received;
    public final Packet packet;

    public PacketRecord(long received, Packet packet) {
      this.received = received;
      this.packet = packet;
    }

    @Override public String type() { return "packet"; }
  }

  /** {type:'flip', flip}: a manually reviewed flip. */
  public static final class FlipRecord extends JournalRecord {
    public final ManualFlip flip;

    public FlipRecord(ManualFlip flip) { this.flip = flip; }

    @Override public String type() { return "flip"; }
  }

  /** flip-removed, flip-restored, flip-reopened: {type, id}. */
  public static final class FlipMark extends JournalRecord {
    public static final String REMOVED = "flip-removed", RESTORED = "flip-restored", REOPENED = "flip-reopened";
    private final String type;
    public final String id;

    public FlipMark(String type, String id) {
      if (!REMOVED.equals(type) && !RESTORED.equals(type) && !REOPENED.equals(type)) throw new IllegalArgumentException(type);
      this.type = type;
      this.id = id;
    }

    @Override public String type() { return type; }
  }

  /** personal-use / personal-use-undo: {type, buyId}, one specific observed purchase. */
  public static final class PersonalUse extends JournalRecord {
    public final boolean undo;
    public final String buyId;

    public PersonalUse(boolean undo, String buyId) {
      this.undo = undo;
      this.buyId = buyId;
    }

    @Override public String type() { return undo ? "personal-use-undo" : "personal-use"; }
  }

  /**
   * personal-use-item: {type, itemId, kept?}. kept is the raw number as written (it can be any integer
   * the caller passed); apply() only honours it when it is a whole number from 1 to 2^31-1, as JS does.
   * Null means the line carries no kept count: the blanket, pre-1-Oct kind of mark.
   */
  public static final class PersonalUseItem extends JournalRecord {
    public final int itemId;
    public final Double kept;

    public PersonalUseItem(int itemId, Double kept) {
      this.itemId = itemId;
      this.kept = kept;
    }

    @Override public String type() { return "personal-use-item"; }
  }

  /** personal-use-item-undo: {type, itemId}. */
  public static final class PersonalUseItemUndo extends JournalRecord {
    public final int itemId;

    public PersonalUseItemUndo(int itemId) { this.itemId = itemId; }

    @Override public String type() { return "personal-use-item-undo"; }
  }

  /** flips-imported: {type, flips}. */
  public static final class FlipsImported extends JournalRecord {
    public final List<ImportedFlip> flips;

    public FlipsImported(List<ImportedFlip> flips) { this.flips = Collections.unmodifiableList(new ArrayList<>(flips)); }

    @Override public String type() { return "flips-imported"; }
  }

  /** flips-import-removed: {type, source}. */
  public static final class FlipsImportRemoved extends JournalRecord {
    public final String source;

    public FlipsImportRemoved(String source) { this.source = source; }

    @Override public String type() { return "flips-import-removed"; }
  }

  /** purchase-recorded: {type, purchase:{offerId,itemId,name,quantity,unitPrice,at,account}}. */
  public static final class PurchaseRecorded extends JournalRecord {
    public final String offerId;
    public final int itemId;
    public final String name;
    public final long quantity;
    public final long unitPrice;
    public final long at;
    public final String account;

    public PurchaseRecorded(String offerId, int itemId, String name, long quantity, long unitPrice, long at, String account) {
      this.offerId = offerId;
      this.itemId = itemId;
      this.name = name;
      this.quantity = quantity;
      this.unitPrice = unitPrice;
      this.at = at;
      this.account = account;
    }

    @Override public String type() { return "purchase-recorded"; }
  }

  /** purchase-record-removed: {type, offerId}. */
  public static final class PurchaseRecordRemoved extends JournalRecord {
    public final String offerId;

    public PurchaseRecordRemoved(String offerId) { this.offerId = offerId; }

    @Override public String type() { return "purchase-record-removed"; }
  }

  /** position-closed: {type, buyId, reason, at}. */
  public static final class PositionClosed extends JournalRecord {
    public final String buyId;
    public final String reason;
    public final long at;

    public PositionClosed(String buyId, String reason, long at) {
      this.buyId = buyId;
      this.reason = reason;
      this.at = at;
    }

    @Override public String type() { return "position-closed"; }
  }

  /** position-reopened: {type, buyId}. */
  public static final class PositionReopened extends JournalRecord {
    public final String buyId;

    public PositionReopened(String buyId) { this.buyId = buyId; }

    @Override public String type() { return "position-reopened"; }
  }
}

package com.evi.live.journal;

import com.google.gson.JsonElement;
import com.google.gson.JsonPrimitive;
import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.text.NumberFormat;
import java.util.Locale;

/**
 * The few JavaScript semantics the journal engine depends on, in one place so each is written once and
 * tested once (JournalVectorsTest replays what the real JS engine produced for each).
 *
 * <p>Ported for the self-contained plugin. Pure: no I/O, no clock, no threads.
 *
 * <ul>
 *   <li>Reading a JSON value the way {@code JSON.parse} would: every number is an IEEE double, so
 *       {@code 1.0} is the integer 1, {@code 1e400} is Infinity, and an integer past 2^53 has already
 *       been rounded before any check sees it. {@link #number} parses the original text with
 *       {@link Double#parseDouble}, which rounds exactly as JS does.</li>
 *   <li>{@code Number.isSafeInteger} and the store's own {@code integer(x,min,max)} check.</li>
 *   <li>Writing a journal line exactly as {@code JSON.stringify} does, so a line the Java engine writes
 *       is byte-identical to one the bridge would have written and other readers of the same format still read it:
 *       strings ({@link #quote}) and numbers ({@link #numberToString}, the ECMAScript Number::toString
 *       algorithm: shortest round-trip digits, exponent only outside 1e-7..1e21).</li>
 *   <li>{@code toLocaleString('en-US')} grouping, pinned to {@link Locale#US} whatever the host locale is
 *       (the 6 Oct F2 fix in the bridge is the same rule).</li>
 * </ul>
 */
public final class Js {
  private Js() {}

  /** Number.MAX_SAFE_INTEGER. */
  public static final double MAX_SAFE = 9007199254740991.0;
  /** The default upper bound of store.mjs's integer(): 2^31-1. Beyond Max Cash is the open question here. */
  public static final double INT32_MAX = 2147483647.0;

  /** Number.MAX_SAFE_INTEGER as a long. */
  public static final long MAX_SAFE_LONG = 9007199254740991L;
  // 2^63: the first magnitude a long cannot hold (and -2^63 the last one it can).
  private static final double TWO_63 = 0x1p63;

  /** Number.isSafeInteger for a long. */
  public static boolean isSafe(long v) {
    return v >= -MAX_SAFE_LONG && v <= MAX_SAFE_LONG;
  }

  // ------------------------------------------------------------------------------- GP arithmetic
  //
  // Every GP figure the JS engine computes is a DOUBLE. While every operand and the result are safe
  // integers (|x| <= 2^53 - 1, about 9 quadrillion gp: thousands of times any real Grand Exchange wealth)
  // double arithmetic is exact, so these return exactly what long arithmetic would. Past 2^53 they round
  // exactly as JS does -- the result is the double nearest the true value, which a long then holds
  // exactly -- so Java and JS agree to the last digit there too, instead of Java quietly being "more
  // right" than the journal it shares with the bridge. Past 2^63 a long cannot hold JS's answer at all:
  // these THROW (ArithmeticException), never wrap round to the other sign or saturate at Long.MAX_VALUE.
  //
  // The invariant that makes the past-2^53 branch exact: every long these produce, and every long the
  // journal decodes, is a value a double holds exactly, so (double) v loses nothing.

  /** a + b, as JS adds two integers (see above). */
  public static long add(long a, long b) {
    if (isSafe(a) && isSafe(b)) {
      long r = a + b; // cannot overflow: both are under 2^53
      if (isSafe(r)) return r;
    }
    return exactLong((double) a + (double) b);
  }

  /** a - b, as JS subtracts two integers. */
  public static long subtract(long a, long b) {
    if (isSafe(a) && isSafe(b)) {
      long r = a - b;
      if (isSafe(r)) return r;
    }
    return exactLong((double) a - (double) b);
  }

  /** a x b, as JS multiplies two integers (a price times a quantity). */
  public static long multiply(long a, long b) {
    if (isSafe(a) && isSafe(b)) {
      long r = a * b;
      // The 128-bit product fits a long exactly when its high half is just the sign of the low half.
      if (Math.multiplyHigh(a, b) == (r >> 63) && isSafe(r)) return r;
    }
    return exactLong((double) a * (double) b);
  }

  /**
   * Math.round as JavaScript has it (half-up: 2.5 -> 3, -1.5 -> -1), for a value that must become a
   * long. Throws ArithmeticException for NaN and for anything at or past 2^63, where {@link Math#round}
   * would silently saturate at Long.MAX_VALUE / MIN_VALUE.
   */
  public static long round(double x) {
    if (Double.isNaN(x) || x >= TWO_63 || x < -TWO_63) throw new ArithmeticException("GP figure " + numberToString(x) + " is past what a long can hold");
    return Math.round(x);
  }

  // An integral double as a long, refusing (loudly) anything a long cannot hold.
  private static long exactLong(double d) {
    if (Double.isNaN(d) || d >= TWO_63 || d < -TWO_63) throw new ArithmeticException("GP figure " + numberToString(d) + " is past what a long can hold");
    return (long) d;
  }

  /** Number.isSafeInteger. */
  public static boolean isSafeInteger(double d) {
    return !Double.isNaN(d) && !Double.isInfinite(d) && Math.floor(d) == d && Math.abs(d) <= MAX_SAFE;
  }

  /** Number.isInteger: any finite integral double, however large. */
  public static boolean isInteger(double d) {
    return !Double.isNaN(d) && !Double.isInfinite(d) && Math.floor(d) == d;
  }

  /** The value as JSON.parse would give it, when it is a JSON number; null for anything else (absent too). */
  public static Double number(JsonElement e) {
    if (e == null || !e.isJsonPrimitive()) return null;
    JsonPrimitive p = e.getAsJsonPrimitive();
    if (!p.isNumber()) return null;
    return Double.parseDouble(p.getAsString());
  }

  /** store.mjs: {@code integer(x,min,max) = Number.isSafeInteger(x) && x >= min && x <= max}. */
  public static boolean integer(JsonElement e, double min, double max) {
    Double d = number(e);
    return d != null && isSafeInteger(d) && d >= min && d <= max;
  }

  /** store.mjs: {@code integer(x)} with its defaults, min 0 and max 2^31-1. */
  public static boolean integer(JsonElement e) {
    return integer(e, 0, INT32_MAX);
  }

  /** typeof x === 'string'. */
  public static boolean isString(JsonElement e) {
    return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isString();
  }

  /** typeof x === 'boolean'. */
  public static boolean isBoolean(JsonElement e) {
    return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isBoolean();
  }

  /** A string value, or null when the JSON value is anything else. */
  public static String string(JsonElement e) {
    return isString(e) ? e.getAsString() : null;
  }

  /**
   * The sign of a JS sort comparator's {@code a - b}: a NaN difference counts as "equal", exactly as
   * Array.prototype.sort treats it. Double.compare would order NaN last and reorder ties.
   */
  public static int compare(double a, double b) {
    double d = a - b;
    return d < 0 ? -1 : d > 0 ? 1 : 0;
  }

  /** (n).toLocaleString('en-US') for a whole number: grouping commas, nothing else. Never the host locale. */
  public static String groupedUs(long n) {
    return NumberFormat.getIntegerInstance(Locale.US).format(n);
  }

  /** JSON.stringify(s) for a string: the quotes, the short escapes, \\u00xx for other controls and lone surrogates. */
  public static void quote(StringBuilder sb, String s) {
    sb.append('"');
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      switch (c) {
        case '"': sb.append("\\\""); break;
        case '\\': sb.append("\\\\"); break;
        case '\b': sb.append("\\b"); break;
        case '\f': sb.append("\\f"); break;
        case '\n': sb.append("\\n"); break;
        case '\r': sb.append("\\r"); break;
        case '\t': sb.append("\\t"); break;
        default:
          if (c < 0x20) { hex4(sb, c); break; }
          if (Character.isHighSurrogate(c) && i + 1 < s.length() && Character.isLowSurrogate(s.charAt(i + 1))) {
            sb.append(c).append(s.charAt(++i));
          } else if (Character.isSurrogate(c)) {
            hex4(sb, c); // well-formed JSON.stringify (ES2019): a lone surrogate is escaped, lowercase
          } else {
            sb.append(c);
          }
      }
    }
    sb.append('"');
  }

  private static void hex4(StringBuilder sb, char c) {
    String h = Integer.toHexString(c);
    sb.append("\\u");
    for (int k = h.length(); k < 4; k++) sb.append('0');
    sb.append(h);
  }

  /** JSON.stringify(s) for a string. */
  public static String quote(String s) {
    StringBuilder sb = new StringBuilder(s.length() + 2);
    quote(sb, s);
    return sb.toString();
  }

  /**
   * String(d), the ECMAScript Number::toString algorithm, which JSON.stringify also uses for finite numbers.
   * Double.toString differs in format ("3.0", "1.0E21") and, on Java 11, is not always the shortest.
   */
  public static String numberToString(double d) {
    if (Double.isNaN(d)) return "NaN";
    if (d == Double.POSITIVE_INFINITY) return "Infinity";
    if (d == Double.NEGATIVE_INFINITY) return "-Infinity";
    if (d == 0) return "0"; // -0 prints as 0 too
    if (d < 0) return "-" + numberToString(-d);
    BigDecimal exact = new BigDecimal(d);
    BigDecimal best = null;
    for (int p = 1; p <= 17 && best == null; p++) {
      BigDecimal r = exact.round(new MathContext(p, RoundingMode.HALF_EVEN));
      BigDecimal ulp = r.ulp();
      // The nearest p-digit decimal can miss the round-trip interval where it is lopsided (at a power of
      // two) while a neighbour hits it; the spec then wants the round-tripping one closest to d.
      for (BigDecimal c : new BigDecimal[]{r, r.subtract(ulp), r.add(ulp)}) {
        if (c.signum() <= 0 || c.doubleValue() != d) continue;
        if (best == null || c.subtract(exact).abs().compareTo(best.subtract(exact).abs()) < 0) best = c;
      }
    }
    if (best == null) best = exact; // unreachable: 17 digits always round-trip
    best = best.stripTrailingZeros();
    String s = best.unscaledValue().toString();
    int k = s.length();
    int n = k - best.scale();
    if (k <= n && n <= 21) return s + "0".repeat(n - k);
    if (0 < n && n <= 21) return s.substring(0, n) + "." + s.substring(n);
    if (-6 < n && n <= 0) return "0." + "0".repeat(-n) + s;
    int e = n - 1;
    String exp = "e" + (e >= 0 ? "+" : "-") + Math.abs(e);
    return k == 1 ? s + exp : s.charAt(0) + "." + s.substring(1) + exp;
  }
}

package com.evi.live.journal;

import java.util.List;

/**
 * A flip the player reviewed and confirmed by hand (store.mjs {@code confirm}), as journalled. The
 * {@link #removed} and {@link #reopened} flags are not part of the journal line: later records set them,
 * exactly as store.mjs mutates the stored object. Null means the flag was never set, which is not the
 * same as false (a restored flip carries removed:false).
 */
public final class ManualFlip {
  public final String id;
  public final String buyId;
  /** Null when several sales were matched (the line still carries "sellId":null). */
  public final String sellId;
  /** Null only on a flip journalled before the field existed; read through {@link #sellIdsOrSingle}. */
  public final List<String> sellIds;
  public final String account;
  public final int itemId;
  public final String item;
  public final long quantity;
  public final long capital;
  public final long netProceeds;
  public final long profit;
  public final Long firstBuy;
  public final Long lastSell;
  public final double hold;
  public final Long confirmedAt;
  public final String source;
  public final String proceedsMethod;
  Boolean removed;
  Boolean reopened;

  public ManualFlip(String id, String buyId, String sellId, List<String> sellIds, String account, int itemId, String item,
                    long quantity, long capital, long netProceeds, long profit, Long firstBuy, Long lastSell, double hold,
                    Long confirmedAt, String source, String proceedsMethod) {
    this.id = id;
    this.buyId = buyId;
    this.sellId = sellId;
    this.sellIds = sellIds;
    this.account = account;
    this.itemId = itemId;
    this.item = item;
    this.quantity = quantity;
    this.capital = capital;
    this.netProceeds = netProceeds;
    this.profit = profit;
    this.firstBuy = firstBuy;
    this.lastSell = lastSell;
    this.hold = hold;
    this.confirmedAt = confirmedAt;
    this.source = source;
    this.proceedsMethod = proceedsMethod;
  }

  /** {@code f.sellIds ?? [f.sellId]}. */
  public List<String> sellIdsOrSingle() {
    return sellIds != null ? sellIds : java.util.Collections.singletonList(sellId);
  }

  public Boolean removed() {
    return removed;
  }

  public Boolean reopened() {
    return reopened;
  }

  boolean isRemoved() {
    return Boolean.TRUE.equals(removed);
  }

  boolean isReopened() {
    return Boolean.TRUE.equals(reopened);
  }
}

package com.evi.live.journal;

/**
 * One Grand Exchange offer as the journal knows it: the record store.mjs keeps in {@code this.offers},
 * keyed by its (resolved) offerId. Immutable; every packet that changes it produces a new one, exactly as
 * the JS engine builds a fresh object with {@code {...o, ...}}.
 *
 * <p>ABSENT IS NOT ZERO, and the nullable fields carry that distinction:
 * <ul>
 *   <li>{@link #ticksToFill} null: no reading at all (journalled before the plugin sent it, or never
 *       filled while watched). -1 never appears here: the store keeps the earlier real reading instead.</li>
 *   <li>{@link #completedAt} null: not finished when last seen.</li>
 *   <li>{@link #recorded} true only for a purchase the player told EVI about ({@code recordPurchase});
 *       null for everything EVI observed.</li>
 * </ul>
 *
 * <p>Prices, totals and counters are {@code long}: a recorded purchase's spend can pass 2^31.
 */
public final class Offer {
  public final int slot;
  public final String state;
  public final String offerId;
  public final int itemId;
  public final String name;
  public final long price;
  public final long total;
  public final long filled;
  public final long spent;
  public final boolean knownStart;
  public final Integer ticksToFill;
  public final String account;
  public final String session;
  public final Long firstSeen;
  public final Long updated;
  public final Long completedAt;
  public final Boolean recorded;

  public Offer(int slot, String state, String offerId, int itemId, String name, long price, long total, long filled,
               long spent, boolean knownStart, Integer ticksToFill, String account, String session, Long firstSeen,
               Long updated, Long completedAt, Boolean recorded) {
    this.slot = slot;
    this.state = state;
    this.offerId = offerId;
    this.itemId = itemId;
    this.name = name;
    this.price = price;
    this.total = total;
    this.filled = filled;
    this.spent = spent;
    this.knownStart = knownStart;
    this.ticksToFill = ticksToFill;
    this.account = account;
    this.session = session;
    this.firstSeen = firstSeen;
    this.updated = updated;
    this.completedAt = completedAt;
    this.recorded = recorded;
  }

  /** store.mjs side(): BUYING, BOUGHT and CANCELLED_BUY are buys; EVERYTHING else (EMPTY included) is a sell. */
  public static String side(String state) {
    return "BUYING".equals(state) || "BOUGHT".equals(state) || "CANCELLED_BUY".equals(state) ? "buy" : "sell";
  }

  /** store.mjs finished(): a terminal state, or every unit filled. */
  public static boolean finished(String state, long total, long filled) {
    return "BOUGHT".equals(state) || "SOLD".equals(state) || "CANCELLED_BUY".equals(state) || "CANCELLED_SELL".equals(state)
      || (total > 0 && filled == total);
  }

  public String side() {
    return side(state);
  }

  public boolean finished() {
    return finished(state, total, filled);
  }
}

package com.evi.live.journal;

import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.IOException;
import java.io.StringReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * A character's FORMER display names, as the player states them for the one-time import (the maintainer's decision, 8 Oct 2026):
 * {@code "oldNames": {"OldName": "Current Name"}} in {@code import/preferences.json}. The bridge's flip histories from another
 * tracker are kept by the display name each trade was made under; a character that has since been renamed would otherwise never
 * take the trades made under its old name. Read ONLY by the import; nothing else uses it.
 *
 * <p>The rules, each deliberate:
 * <ul>
 *   <li><b>Explicit only.</b> A name is a former name only when the file says so; nothing is ever inferred.</li>
 *   <li>Names are compared as {@link CharacterNames#key} compares them (case; space / underscore / hyphen / non-breaking space
 *       alike), on both sides.</li>
 *   <li>A former name is RESOLVED to its current name before any comparison, so trades under it are taken by the character now
 *       holding the current name and by no other -- not even by a character whose own name is the former one.</li>
 *   <li><b>Refused</b> (the trades under that former name are taken by NO character): a former name mapped to two different
 *       current names (exact duplicate keys, or two spellings of one name); a current name that is not a non-blank string; and
 *       a CHAIN -- a current name that is itself listed as a former name ({@code "A": "B", "B": "C"} refuses A). Chains are
 *       refused rather than followed: the file is meant to name each former name's CURRENT name, so a current name that is
 *       itself a former one is a contradiction, and following it would guess which character the player meant.</li>
 *   <li>An entry mapping a name to itself means nothing and is dropped; a blank former name matches nothing and is dropped.</li>
 * </ul>
 */
public final class OldNames {
  /** No former names: every flip is compared by its own name, as before 8 Oct 2026. */
  public static final OldNames NONE = new OldNames(Collections.emptyMap(), Collections.emptySet(), false);

  /** Former name key -> current name key. */
  private final Map<String, String> current;
  /** Former name keys refused (see the class note). */
  private final Set<String> refused;
  /** Whether the file held an {@code oldNames} object at all (even an empty one). */
  public final boolean present;

  private OldNames(Map<String, String> current, Set<String> refused, boolean present) {
    this.current = Collections.unmodifiableMap(current);
    this.refused = Collections.unmodifiableSet(refused);
    this.present = present;
  }

  /** How many former names are mapped (usable), and how many were refused. */
  public int mapped() {
    return current.size();
  }

  public int refusedCount() {
    return refused.size();
  }

  /** Whether trades kept under {@code key} (a {@link CharacterNames#key}) are refused. */
  boolean refused(String key) {
    return key != null && refused.contains(key);
  }

  /** The current name key a former name key maps to, or null when it is not a (usable) former name. */
  String currentOf(String key) {
    return key == null ? null : current.get(key);
  }

  /** From explicit pairs (former name, current name; a null current name is an invalid entry). Package-private: tests. */
  static OldNames of(List<String[]> pairs, boolean present) {
    Map<String, Set<String>> targets = new LinkedHashMap<>();
    Set<String> refused = new LinkedHashSet<>();
    for (String[] p : pairs) {
      String k = CharacterNames.key(p[0]);
      if (k == null) continue; // a blank former name matches nothing
      String v = p[1] == null ? null : CharacterNames.key(p[1]);
      if (v == null) {
        refused.add(k); // stated as a former name, with no usable current name: its trades go to no one
        continue;
      }
      targets.computeIfAbsent(k, x -> new LinkedHashSet<>()).add(v);
    }
    Map<String, String> current = new HashMap<>();
    for (Map.Entry<String, Set<String>> e : targets.entrySet()) {
      String k = e.getKey();
      if (refused.contains(k)) continue;
      if (e.getValue().size() > 1) {
        refused.add(k); // one former name, two different current names
        continue;
      }
      String v = e.getValue().iterator().next();
      if (!v.equals(k)) current.put(k, v); // a name mapped to itself means nothing
    }
    // Chains: a current name that is itself a stated former name (mapped or refused) -- refused, never followed.
    Set<String> former = new HashSet<>(current.keySet());
    former.addAll(refused);
    for (Map.Entry<String, String> e : new ArrayList<>(current.entrySet())) {
      if (former.contains(e.getValue())) {
        current.remove(e.getKey());
        refused.add(e.getKey());
      }
    }
    return new OldNames(current, refused, present);
  }

  /**
   * The {@code oldNames} object of a preferences file's text (every other field is skipped unread). No such field (or null):
   * {@link #NONE}. Throws {@link IllegalArgumentException} when the text is not one JSON object, or {@code oldNames} is not an
   * object: the import is then refused rather than run without names the player meant to give (it runs once per account).
   * Duplicate keys are seen here, which a parsed tree would hide (the last one silently wins).
   */
  public static OldNames parse(String text) {
    List<String[]> pairs = new ArrayList<>();
    boolean present = false;
    // A leading byte-order mark (Notepad may save one) is skipped by JsonReader itself (mutation-checked 8 Oct: stripping it here
    // changed nothing); the test pins that.
    try (JsonReader r = new JsonReader(new StringReader(text))) {
      if (r.peek() != JsonToken.BEGIN_OBJECT) throw new IllegalArgumentException("not a JSON object");
      r.beginObject();
      while (r.hasNext()) {
        if (!"oldNames".equals(r.nextName())) {
          r.skipValue();
          continue;
        }
        if (r.peek() == JsonToken.NULL) {
          r.nextNull();
          continue;
        }
        if (r.peek() != JsonToken.BEGIN_OBJECT) throw new IllegalArgumentException("oldNames is not an object");
        present = true;
        r.beginObject();
        while (r.hasNext()) {
          String k = r.nextName();
          if (r.peek() == JsonToken.STRING) pairs.add(new String[]{k, r.nextString()});
          else {
            r.skipValue();
            pairs.add(new String[]{k, null});
          }
        }
        r.endObject();
      }
      r.endObject();
      if (r.peek() != JsonToken.END_DOCUMENT) throw new IllegalArgumentException("more than one JSON value");
    } catch (IOException | IllegalStateException e) {
      throw new IllegalArgumentException("not valid JSON: " + e.getMessage(), e);
    }
    return of(pairs, present);
  }
}

package com.evi.live.journal;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * One snapshot of the eight GE slots from the plugin, after store.mjs's {@code validatePacket}.
 *
 * <p>{@link #validate} takes the JSON TREE, not a typed object, on purpose: its checks are about JSON
 * types and JS number semantics ({@code 1.0} is the integer 1, a string "5" is not a number, an absent
 * {@code ticksToFill} is fine but {@code null} is not), and the same tree is what a journal line holds.
 * A plugin building packets in-process converts to the tree with the injected Gson and goes through the
 * same single validation path.
 *
 * <p>THE INT32 CAP IS KEPT AS THE JS ENGINE HAS IT, and it is an open decision rather than an
 * endorsement: price, total, filled and spent are refused above 2,147,483,647, so since Beyond Max Cash a
 * unit priced over max cash (or a spend past it) makes the WHOLE packet invalid. Recorded by the golden
 * fixtures max-cash-unit-price-over-int32 and max-cash-spent-overflow. Raising it is the maintainer's call and must
 * happen in JS first.
 */
public final class Packet {
  public final int version;
  public final String session;
  public final String account;
  public final long seq;
  public final long ts;
  public final boolean loggedIn;
  public final List<SlotOffer> offers;

  public Packet(int version, String session, String account, long seq, long ts, boolean loggedIn, List<SlotOffer> offers) {
    this.version = version;
    this.session = session;
    this.account = account;
    this.seq = seq;
    this.ts = ts;
    this.loggedIn = loggedIn;
    this.offers = Collections.unmodifiableList(new ArrayList<>(offers));
  }

  /** One slot of a packet, exactly the eleven fields validatePacket keeps. */
  public static final class SlotOffer {
    public final int slot;
    public final String state;
    public final String offerId;
    public final int itemId;
    public final String name;
    public final long price;
    public final long total;
    public final long filled;
    public final long spent;
    public final boolean knownStart;
    /** -1 for "no reading" from a validated packet; null only in a journal line written before the field existed. */
    public final Integer ticksToFill;

    public SlotOffer(int slot, String state, String offerId, int itemId, String name, long price, long total, long filled,
                     long spent, boolean knownStart, Integer ticksToFill) {
      this.slot = slot;
      this.state = state;
      this.offerId = offerId;
      this.itemId = itemId;
      this.name = name;
      this.price = price;
      this.total = total;
      this.filled = filled;
      this.spent = spent;
      this.knownStart = knownStart;
      this.ticksToFill = ticksToFill;
    }

    public boolean empty() {
      return "EMPTY".equals(state);
    }
  }

  public static final Set<String> STATES = Set.of("EMPTY", "BUYING", "SELLING", "BOUGHT", "SOLD", "CANCELLED_BUY", "CANCELLED_SELL");
  private static final Pattern ID = Pattern.compile("[a-zA-Z0-9-]{1,80}");

  /** store.mjs id(): a string of 1-80 letters, digits or hyphens. */
  public static boolean id(JsonElement e) {
    return Js.isString(e) && ID.matcher(e.getAsString()).matches();
  }

  /** store.mjs id() for a value already known to be a string (or null). */
  public static boolean id(String s) {
    return s != null && ID.matcher(s).matches();
  }

  /** store.mjs validatePacket: the same checks, in the same order, with the same messages. */
  public static Packet validate(JsonElement input) {
    if (input == null || !input.isJsonObject()) throw new JournalException("Invalid packet");
    JsonObject p = input.getAsJsonObject();
    Double version = Js.number(p.get("version"));
    if (version == null || version != 1 || !id(p.get("session")) || !id(p.get("account"))
        || !Js.integer(p.get("seq"), 1, Js.MAX_SAFE) || !Js.integer(p.get("ts"), 1, Js.MAX_SAFE)
        || !Js.isBoolean(p.get("loggedIn")) || p.get("offers") == null || !p.get("offers").isJsonArray()
        || p.getAsJsonArray("offers").size() > 8) throw new JournalException("Invalid packet");
    JsonArray raw = p.getAsJsonArray("offers");
    Set<Integer> slots = new HashSet<>();
    List<SlotOffer> offers = new ArrayList<>();
    for (JsonElement e : raw) {
      if (e == null || !e.isJsonObject()) throw new JournalException("Invalid offer");
      JsonObject o = e.getAsJsonObject();
      if (!Js.integer(o.get("slot"), 0, 7) || slots.contains(slot(o)) || !Js.isString(o.get("state"))
          || !STATES.contains(o.get("state").getAsString()) || !id(o.get("offerId"))
          || !Js.integer(o.get("itemId")) || !Js.integer(o.get("price")) || !Js.integer(o.get("total"))
          || !Js.integer(o.get("filled")) || Js.number(o.get("filled")) > Js.number(o.get("total"))
          || !Js.integer(o.get("spent")) || !Js.isBoolean(o.get("knownStart")) || !Js.isString(o.get("name"))
          || o.get("name").getAsString().length() > 150) throw new JournalException("Invalid offer");
      String state = o.get("state").getAsString();
      if (!"EMPTY".equals(state) && (Js.number(o.get("itemId")) == 0 || Js.number(o.get("total")) == 0 || Js.number(o.get("price")) == 0))
        throw new JournalException("Invalid nonempty offer");
      // Optional: older plugin builds do not send it. Absent is fine; null is not (null !== undefined).
      if (o.has("ticksToFill") && !Js.integer(o.get("ticksToFill"), -1, 1000000)) throw new JournalException("Invalid ticksToFill");
      slots.add(slot(o));
      offers.add(new SlotOffer(slot(o), state, o.get("offerId").getAsString(), (int) (double) Js.number(o.get("itemId")),
        o.get("name").getAsString(), (long) (double) Js.number(o.get("price")), (long) (double) Js.number(o.get("total")),
        (long) (double) Js.number(o.get("filled")), (long) (double) Js.number(o.get("spent")), o.get("knownStart").getAsBoolean(),
        o.has("ticksToFill") ? (int) (double) Js.number(o.get("ticksToFill")) : -1));
    }
    boolean loggedIn = p.get("loggedIn").getAsBoolean();
    if (loggedIn && offers.size() != 8) throw new JournalException("Expected all eight slots");
    return new Packet(1, p.get("session").getAsString(), p.get("account").getAsString(), (long) (double) Js.number(p.get("seq")),
      (long) (double) Js.number(p.get("ts")), loggedIn, offers);
  }

  // Only ever called once the slot is known to be a safe integer in 0..7 (or for the duplicate check,
  // where a non-number simply cannot collide: Js.integer above has already failed for it).
  private static Integer slot(JsonObject o) {
    Double d = Js.number(o.get("slot"));
    return d == null ? null : (int) (double) d;
  }
}

