import java.util.function.LongSupplier;
import net.runelite.client.util.Filepath;

/**
 * The plugin's OWN trade journal: every Grand Exchange packet the plugin observes, recorded into a Java {@link Store} (ported
 * with parity from the old companion app's store.mjs), persisted in the same events.jsonl line format, and reloaded at
 * startup. The engine reads everything it knows about the player's trades from here.
 *
 * <h3>Threads</h3>
 * Every file operation and every touch of the Store happens on ONE plugin-owned thread,
 * {@value #THREAD_NAME}, and is checked there (a file operation anywhere else throws). The client thread
 * only hands over the packet text it built. {@link #shutdown()} uses {@code shutdown()}, never {@code shutdownNow()}: queued
 * writes finish, and no thread is ever interrupted (Thread.interrupt is on the Hub's forbidden list).
 *
 * <p>HANDOVER: when the plugin is switched off and on again, the old journal may still be finishing its
 * queue. The new one is started with the old one as its predecessor ({@link #start(PluginJournal)}), and its
 * own thread -- never the caller's -- waits (bounded) for the old one to finish before it reads anything, so
 * the two never write one file at the same time and every queued packet lands in its original order.
 *
 * <h3>Files</h3> (in the plugin's data folder, {@link PluginFolder#PATH}, through {@link Filepath} only)
 * <ul>
 *   <li>{@code journal/events-<account>.jsonl}: one per account, so two clients never share a file.
 *       APPEND-ONLY: never rewritten, so another client can follow it by the bytes it has read.
 *       The Store is MACHINE-WIDE like the bridge's (every account's file is replayed into it, which is
 *       what the profit line sums), and it re-reads files another client has appended to before it acts.</li>
 *   <li>{@code journal/imported-<account>.jsonl}: the one-time import's result -- the bridge's records for
 *       that account -- created once under a new name and never changed. Replayed BEFORE the account's
 *       events file, skipping any event the import already holds ({@link BridgeImport#merge}).</li>
 *   <li>{@code import/events.jsonl}: a copy of the bridge's data/events.jsonl, placed there BY THE PLAYER.
 *       Read only while the "Import old trade history" setting is on, once per account (the imported
 *       file records that it happened; {@code journal/import-done-<account>.json} holds its counts).</li>
 *   <li>{@code import/identity-salt.txt} (optional, 9 Oct 2026): the FORMER data folder's salt, placed there by the player. The
 *       bridge journalled each account under the id that salt gives ({@link AccountIds}); a new data folder has a new salt, so
 *       its ids match none of the bridge's records. When present, the import selects this account's records by the id the old
 *       salt gives and files them under the account's current id. Read only, never changed; absent, the import is as before.</li>
 * </ul>
 *
 * <h3>The sidebar's marks (SELF-CONTAINED decision 12)</h3>
 * Personal use (a buy, or an item: "Yours, not stock") and "I don't have this anymore" are the SAME records the bridge
 * journals (store.mjs markPersonalUse / markPersonalUseItem / closePosition, through the same {@link Store}), written to an
 * events file like every other record, so they survive a restart exactly as the bridge's do and the machine-wide Store
 * replays them as the bridge's does. A record names no account of its own: it goes to the file of the account that OWNS the
 * offer it names (as {@link BridgeImport} attributes it), else -- an item mark names no offer -- to the file of the account
 * that pressed the button. Nothing reaches a file without an account.
 */
public final class PluginJournal {
  public static final String THREAD_NAME = "evi-journal";
  public static final String JOURNAL_DIR = "journal";
  public static final String IMPORT_DIR = "import";
  /** The bridge's preferences copied beside the import file; this journal reads only its {@code oldNames} ({@link OldNames}). */
  static final String PREFERENCES_FILE = "preferences.json";
  /** A preferences file is a few hundred bytes; anything past this is not one. */
  static final long PREFERENCES_MAX_BYTES = 1024 * 1024;
  public static final String IMPORT_FILE = "events.jsonl";
  /** The former data folder's identity salt, copied beside the import file by the player (optional; see the class note). */
  static final String SALT_FILE = "identity-salt.txt";
  /** A salt is a 36-character UUID; anything past this is not one. */
  static final long SALT_MAX_BYTES = 4096;
  /** The log hint when no record matched and no salt file was given (the README names the old folder). */
  static final String SALT_HINT = "copy " + SALT_FILE + " from the older EVI version's plugin-data folder";
  /**
   * The sidebar line (the maintainer's decision, 6 Oct 2026) shown ONLY while the import setting is on, the account
   * has not been imported, and there is no import file. Plain and neutral: it says what is missing and where it
   * goes, nothing more.
   */
  public static final String IMPORT_MISSING_NOTICE = "Import is on, but no file was found at " + PluginFolder.PATH + "/"
    + IMPORT_DIR + "/" + IMPORT_FILE + ".";
  private static final int MAX_PENDING = 4096;
  /** How long a new journal's thread waits for its predecessor to finish its queue before going on anyway. */
  static final long HANDOVER_WAIT_MS = 30_000;
  /** An import that failed on file I/O (a locked or blocked file) is retried at later packets, this many times a session. */
  static final int IMPORT_TRIES = 3;
  /**
   * The largest import file read (it is read whole). The bridge refuses to append past 100 MB, so its
   * journal is at most that plus one line; anything larger is not a bridge journal. Tests lower it.
   */
  static volatile long importMaxBytes = JournalFile.MAX_BYTES + 1024 * 1024;

  /**
   * What a look at the import file found. UNKNOWN: it could not be told -- isFile() said no, but the file system did not say
   * the file is ABSENT either (an I/O error reading its attributes, such as a sharing violation while a virus scan holds it).
   * Found 8 Oct 2026: isFile() (Files.isRegularFile, which answers false on ANY I/O error) twice read a 10 MB import file that
   * was there as missing, and the sidebar said "no file was found". Only proven absence is "missing" now; UNKNOWN shows no line,
   * logs nothing about a missing file, counts no import attempt, and is looked at again at the next packet.
   */
  enum ImportFileState { PRESENT, ABSENT, UNKNOWN }

  /** The three looks {@link #importFileState} takes at a file. A seam: a test drives UNKNOWN with no real lock. */
  interface FileLook {
    boolean isFile();

    /** Reads the file's attributes: throws NoSuchFileException when it is not there, another IOException when it cannot tell. */
    void attributes() throws IOException;

    boolean isDirectory();
  }

  /** PRESENT when it is a file; ABSENT only on proof (no such file, or a folder in its place); UNKNOWN otherwise. */
  static ImportFileState importFileState(FileLook f) {
    if (f.isFile()) return ImportFileState.PRESENT;
    try {
      f.attributes();
    } catch (NoSuchFileException e) {
      return ImportFileState.ABSENT;
    } catch (IOException | RuntimeException e) {
      return ImportFileState.UNKNOWN;
    }
    return f.isDirectory() ? ImportFileState.ABSENT : ImportFileState.UNKNOWN;
  }

  static FileLook look(Filepath f) {
    return new FileLook() {
      @Override
      public boolean isFile() {
        return f.isFile();
      }

      @Override
      public void attributes() throws IOException {
        f.getLastModifiedTime();
      }

      @Override
      public boolean isDirectory() {
        return f.isDirectory();
      }
    };
  }

  /** TEST SEAM: how the import file is looked at. Production: {@link #look}. */
  volatile Function<Filepath, FileLook> importFileLook = PluginJournal::look;

  /** TEST SEAM: told the current thread's name at every file operation. Null in production. */
  static volatile Consumer<String> ioThreadSeam;

  private final Filepath root;
  private final Filepath dir;
  private final LongSupplier clock;
  private final Function<String, JsonElement> parser;
  private final BooleanSupplier importEnabled;
  private final Consumer<String> log;
  private final ThreadPoolExecutor executor;
  private volatile Thread thread;
  private volatile boolean closed;
  /**
   * Whether the import also takes the bridge's item-level marks ("Yours, not stock") for every importing account: the built-in
   * engine only (8 Oct 2026); off, the import is exactly what it was. Read when an import runs.
   */
  private volatile BooleanSupplier importItemMarks = () -> false;
  /**
   * Each account's character DISPLAY NAME, as the plugin learned it at login (any thread may tell it). The import takes the
   * bridge's flip histories from another tracker -- kept by display name -- for the character of that name only.
   */
  private final Map<String, String> characterNames = new java.util.concurrent.ConcurrentHashMap<>();
  /** Whether the plugin tells the character names (it does); an import that needs one then waits for it. */
  private volatile boolean namesExpected;
  /** Each account's RS profile and economy scope, as the plugin combined them with its salt (any thread may tell it). */
  private final Map<String, String[]> identities = new java.util.concurrent.ConcurrentHashMap<>();
  /** Told the import line to show (the text) or hide (null), on the journal thread, only when it changes. */
  private volatile Consumer<String> importNotice;

  // ---- owned by the journal thread
  private Store store;
  /** Bytes of each account's events file already applied to the store (complete lines only). */
  private final Map<String, Long> consumed = new TreeMap<>();
  /**
   * The last line applied from each account's events file, as bytes. Before reading on from
   * {@link #consumed}, sync checks those bytes are still where they were: a file that was REPLACED rather
   * than appended to (by anything outside EVI) is then re-read whole instead of being read from the middle.
   */
  private final Map<String, byte[]> tails = new TreeMap<>();
  /**
   * Each account's imported file as it was when the store was built ({@link JournalFile.Fingerprint}: length,
   * time and both ends). Any change -- grown, SHRUNK or replaced -- rebuilds the store from disk.
   */
  private final Map<String, JournalFile.Fingerprint> importedPrints = new TreeMap<>();
  /** Per account, the events its imported file already holds (skipped in the events file, as merge skips them). */
  private final Map<String, BridgeImport.Dedup> imported = new TreeMap<>();
  /** Accounts whose file has a line that does not decode: never written, never applied. */
  private final Set<String> broken = new TreeSet<>();
  /** Accounts whose imported file does not decode: logged once, left out. */
  private final Set<String> brokenImports = new TreeSet<>();
  /** Accounts this process has started writing (an interrupted tail is recovered first). */
  private final Set<String> claimed = new TreeSet<>();
  /** Accounts known to be imported already (their imported file or marker exists). */
  private final Set<String> importDone = new TreeSet<>();
  /** Import attempts this session per account; at {@link #IMPORT_TRIES} the account is not tried again. */
  private final Map<String, Integer> importTries = new TreeMap<>();
  /** Accounts already told there is no import file, so the log line is not repeated at every packet. */
  private final Set<String> importMissingLogged = new TreeSet<>();
  /** Accounts whose import file could not be checked (UNKNOWN), logged once a session. */
  private final Set<String> importUnknownLogged = new TreeSet<>();
  /** Accounts whose import waits for the character's name (the import file holds flips kept by name). */
  private final Set<String> waitingForName = new TreeSet<>();
  /** Accounts whose import waits for the account's identity (an import/identity-salt.txt is present), logged once. */
  private final Set<String> waitingForIdentity = new TreeSet<>();
  /** The account of the last packet: the one the import line speaks about between packets. */
  private String lastAccount;
  /** What the import line was last told, and whether it has been told anything yet. */
  private String noticeShown;
  private boolean noticeSent;
  private boolean rebuildNeeded = true;
  private String failure;
  /** The account that pressed a sidebar mark being written right now (journal thread only), or null between marks. */
  private String markAccount;

  /**
   * @param root           the plugin's data folder ({@code Plugin.getPluginDirectory()})
   * @param clock          epoch milliseconds; read where a packet is handed over, as the bridge reads its clock on receipt
   * @param parser         JSON text to a tree: the plugin passes the client's injected Gson
   * @param importEnabled  the opt-in import setting, read each time it could apply
   * @param log            one line of local diagnostics (the client log)
   */
  public PluginJournal(Filepath root, LongSupplier clock, Function<String, JsonElement> parser, BooleanSupplier importEnabled,
                       Consumer<String> log) {
    this.root = root;
    this.dir = root.joinSegment(JOURNAL_DIR);
    this.clock = clock;
    this.parser = parser;
    this.importEnabled = importEnabled;
    this.log = log;
    this.executor = new ThreadPoolExecutor(1, 1, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<>(MAX_PENDING), r -> {
      Thread t = new Thread(r, THREAD_NAME);
      t.setDaemon(true); // never holds the client open
      thread = t;
      return t;
    });
  }

  // ------------------------------------------------------------------------------------- any thread

  /** Loads every account's journal, on the journal thread. */
  public void start() {
    start(null);
  }

  /**
   * Loads every account's journal, on the journal thread, after {@code predecessor} -- the journal this one
   * replaces, when the plugin was switched off and on -- has finished every packet it had queued. The wait
   * runs on THIS journal's thread (packets handed over meanwhile queue behind it), never on the caller's,
   * and is bounded by {@value #HANDOVER_WAIT_MS} ms; past that this journal goes on, and whatever the old one
   * still writes is read as any other writer's appends are.
   */
  public void start(PluginJournal predecessor) {
    final PluginJournal before = predecessor == this ? null : predecessor;
    if (before != null) before.shutdown(); // a predecessor takes no new work; it only finishes what it has
    submit(() -> {
      if (before != null && !before.executor.awaitTermination(HANDOVER_WAIT_MS, TimeUnit.MILLISECONDS)) {
        log.accept("EVI journal: the previous journal was still writing after " + HANDOVER_WAIT_MS / 1000
          + " s; going on, and its remaining lines are read as another writer's");
      }
      ioCheck();
      dir.createDirectories();
      rebuild();
    });
  }

  /**
   * One packet, exactly the text the plugin built from the slots. Called on the client thread: only the hand-over
   * happens here; parsing, the store and the file are all on the journal thread.
   */
  public void offerPacket(String json) {
    if (json == null) return;
    final long now = clock.getAsLong();
    submit(() -> ingest(json, now));
  }

  /**
   * Where the import line goes: {@code listener} is told {@link #IMPORT_MISSING_NOTICE} to show it and null to
   * hide it, on the journal thread, and only when that changes. Set it before {@link #start}.
   */
  public void importItemMarks(BooleanSupplier enabled) {
    importItemMarks = enabled == null ? () -> false : enabled;
  }

  /**
   * The character's display name for {@code account} (the plugin tells it at login, before that account's first packet). The
   * one-time import takes the bridge's flip histories from another tracker made under this name only (see BridgeImport). Any
   * thread; a null or blank name is ignored.
   */
  public void characterName(String account, String name) {
    if (account == null || CharacterNames.key(name) == null) return;
    characterNames.put(account, name);
  }

  /**
   * What {@code account}'s id was made from besides the salt ({@link AccountIds#of}): its RS profile and economy scope. The import
   * needs it only when the player placed a former folder's {@code import/identity-salt.txt}, to name this account's bridge records
   * by the id that salt gives. Any thread; only stored. A null account or empty profile is ignored.
   */
  public void accountIdentity(String account, String profile, String economy) {
    if (account == null || profile == null || profile.isEmpty()) return;
    identities.put(account, new String[]{profile, economy == null ? "" : economy});
  }

  /**
   * Whether names will be told ({@link #characterName}). The plugin says yes: an import whose file holds flips kept by name then
   * WAITS for the character's name rather than run without it -- the import happens once per account, so running without the
   * name would lose that history for good. Off (the default, and every caller that never names a character): the import runs at
   * once and takes no such flip.
   */
  public void expectCharacterNames(boolean expected) {
    namesExpected = expected;
  }

  public void onImportNotice(Consumer<String> listener) {
    importNotice = listener;
  }

  /**
   * The import setting changed. Switched on (again), accounts not yet imported are tried at their next packet.
   * Either way the import line is brought up to date at once for the last account seen, not left until a packet.
   */
  public void importRequested() {
    submit(() -> {
      importDone.clear();
      importTries.clear();
      importMissingLogged.clear();
      importUnknownLogged.clear();
      waitingForName.clear();
      waitingForIdentity.clear();
      String a = lastAccount;
      ImportFileState w = a == null ? null : waitingForImportFile(a);
      if (w != ImportFileState.UNKNOWN) notice(w == ImportFileState.ABSENT ? IMPORT_MISSING_NOTICE : null);
    });
  }

  /**
   * The sidebar's "Personal use" on a held buy (store.mjs markPersonalUse with personal:true). Returns at once; the future
   * completes, on the journal thread, with null when the mark is in the journal (or already was), or with the refusal the
   * bridge would have answered 400 with (an unknown buy, an invalid account...). Never throws to the caller.
   */
  public java.util.concurrent.CompletableFuture<String> markPersonalUse(String account, String buyId) {
    return mark(account, s -> s.markPersonalUse(buyId, true));
  }

  /**
   * "Yours, not stock" on idle stock (store.mjs markPersonalUseItem with personal:true): {@code kept} is the count the bridge's
   * route reads from the last bag (null: none, which is the blanket mark the plugin's own request has always made). See
   * {@link #markPersonalUse} for the future.
   */
  public java.util.concurrent.CompletableFuture<String> markPersonalUseItem(String account, int itemId, Double kept) {
    return mark(account, s -> {
      JsonObject a = new JsonObject();
      a.addProperty("itemId", itemId);
      a.addProperty("personal", true);
      if (kept != null) a.addProperty("kept", kept);
      s.markPersonalUseItem(a);
    });
  }

  /** "I don't have this anymore" (store.mjs closePosition, reason "sold-untracked" as the plugin sends it). See {@link #markPersonalUse}. */
  public java.util.concurrent.CompletableFuture<String> closePosition(String account, String buyId) {
    final long now = clock.getAsLong();
    return mark(account, s -> s.closePosition(buyId, "sold-untracked", now));
  }

  private interface Mark {
    void apply(Store s);
  }

  private java.util.concurrent.CompletableFuture<String> mark(String account, Mark m) {
    java.util.concurrent.CompletableFuture<String> f = new java.util.concurrent.CompletableFuture<>();
    if (closed) {
      f.complete("the journal is shut down");
      return f;
    }
    try {
      executor.execute(() -> {
        try {
          ioCheck();
          if (failure != null) {
            f.complete("the journal stopped: " + failure);
            return;
          }
          sync();
          if (store == null) {
            f.complete("the journal is not loaded");
            return;
          }
          markAccount = account;
          try {
            for (int attempt = 0; ; attempt++) {
              try {
                m.apply(store);
                break;
              } catch (JournalFile.ConcurrentWrite e) {
                if (attempt >= 2) throw e;
                sync(); // another client wrote: re-read, then try again on the current state
              }
            }
          } finally {
            markAccount = null;
          }
          f.complete(null);
        } catch (JournalException e) {
          log.accept("EVI journal: a sidebar mark was refused: " + e.getMessage());
          f.complete(e.getMessage());
        } catch (Throwable e) { // never reaches the game or the Swing thread
          log.accept("EVI journal: a sidebar mark could not be saved: " + e);
          f.complete(String.valueOf(e));
        }
      });
    } catch (RejectedExecutionException e) {
      f.complete("the journal's queue is full");
    }
    return f;
  }

  /**
   * What the plugin's engine reads from the journal at one moment: one {@code store.state(now)}
   * and a copy of the list of every offer (each offer is immutable), taken together on the journal thread.
   */
  public static final class EngineView {
    public final StoreState state;
    /** Every account's offers, in the store's order ({@code store.offers()}). */
    public final List<Offer> offers;
    /** How many accounts the store was built from. */
    public final int accounts;

    EngineView(StoreState state, List<Offer> offers, int accounts) {
      this.state = state;
      this.offers = java.util.Collections.unmodifiableList(offers);
      this.accounts = accounts;
    }
  }

  /**
   * DEVELOPER SHADOW MODE ONLY: the journal as the engine reads it at {@code now}, built on the journal thread after catching
   * up with every file (as a packet would). Returns at once. The future completes with null when the journal has stopped (it
   * did not replay), and exceptionally when it is shut down or its queue is full. Reads; never writes.
   */
  public java.util.concurrent.CompletableFuture<EngineView> engineView(long now) {
    java.util.concurrent.CompletableFuture<EngineView> f = new java.util.concurrent.CompletableFuture<>();
    if (closed) {
      f.completeExceptionally(new IllegalStateException("the journal is shut down"));
      return f;
    }
    try {
      executor.execute(() -> {
        try {
          ioCheck();
          sync();
          f.complete(store == null ? null : new EngineView(store.state(now), new ArrayList<>(store.offers()), knownAccounts()));
        } catch (Throwable t) { // reaches the caller's future, never the game
          f.completeExceptionally(t);
        }
      });
    } catch (RejectedExecutionException e) {
      f.completeExceptionally(e);
    }
    return f;
  }

  /** What {@link #exportTradeLog} saved: the file and how many offers and flips it holds. */
  public static final class SavedLog {
    public final Filepath file;
    public final int offers;
    public final int flips;

    SavedLog(Filepath file, int offers, int flips) {
      this.file = file;
      this.offers = offers;
      this.flips = flips;
    }
  }

  /**
   * The sidebar's "Save my trade log..." (9 Oct 2026, voluntary sharing): every account's journal as {@link TradeLogExport}
   * writes it, saved to {@code share/<fileName>} in the plugin's data folder, built and written on the journal thread after
   * catching up with every file (as a packet would). A file of the same name is REPLACED (the same day's export, refreshed),
   * whole or not at all: it is written to a temporary file first and renamed over it. Returns at once; the future completes
   * with what was saved, or exceptionally (the file could not be written, the journal stopped, or it never replayed).
   * Reads the journal; writes only that one file. Nothing is sent anywhere.
   *
   * <p>{@code linker} (null: none) names, by offer id, the offers linked to a suggestion EVI showed (the suggestion-outcome join,
   * which the caller owns); it runs here, on the journal thread, with the same state and offers the file is built from. A linker
   * that throws is logged and the file is saved without links, never with a guessed one.
   */
  public java.util.concurrent.CompletableFuture<SavedLog> exportTradeLog(String fileName, long now,
      java.util.function.BiFunction<StoreState, java.util.Collection<Offer>, Map<String, TradeLogExport.Link>> linker) {
    java.util.concurrent.CompletableFuture<SavedLog> f = new java.util.concurrent.CompletableFuture<>();
    if (closed) {
      f.completeExceptionally(new IllegalStateException("the journal is shut down"));
      return f;
    }
    try {
      executor.execute(() -> {
        try {
          ioCheck();
          sync();
          if (store == null || failure != null) throw new IllegalStateException(failure != null ? failure : "EVI's trade record is not loaded");
          StoreState state = store.state(now);
          List<Offer> offers = new ArrayList<>(store.offers());
          Map<String, TradeLogExport.Link> links = null;
          if (linker != null) {
            try {
              links = linker.apply(state, java.util.Collections.unmodifiableList(offers));
            } catch (RuntimeException e) {
              log.accept("EVI trade log: saved without EVI's suggested prices, which could not be read: " + e);
            }
          }
          TradeLogExport.Csv csv = TradeLogExport.of(state, offers, links);
          Filepath folder = root.joinSegment(TradeLogExport.SHARE_DIR);
          folder.createDirectories();
          Filepath target = folder.joinSegment(fileName);
          Filepath tmp = folder.joinSegment(fileName + ".tmp");
          tmp.deleteIfExists();
          try {
            tmp.write(csv.bytes, java.nio.file.StandardOpenOption.CREATE_NEW, java.nio.file.StandardOpenOption.WRITE);
            tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
          } finally {
            tmp.deleteIfExists();
          }
          f.complete(new SavedLog(target, csv.offers, csv.flips));
        } catch (Throwable t) { // reaches the caller's future, never the game
          f.completeExceptionally(t);
        }
      });
    } catch (RejectedExecutionException e) {
      f.completeExceptionally(e);
    }
    return f;
  }

  /** Stops accepting work; queued writes still finish. Never interrupts. */
  public void shutdown() {
    closed = true;
    executor.shutdown();
  }

  public boolean isShutdown() {
    return executor.isShutdown();
  }

  /** Tests and diagnostics only (it blocks): waits for every task queued so far. Never call on the client thread. */
  public boolean awaitIdle(long timeoutMs) throws Exception {
    if (Thread.currentThread() == thread) throw new IllegalStateException("awaitIdle on the journal thread");
    if (executor.isShutdown()) return executor.awaitTermination(timeoutMs, TimeUnit.MILLISECONDS);
    executor.submit(() -> { }).get(timeoutMs, TimeUnit.MILLISECONDS);
    return true;
  }

  /** Tests only: run {@code task} on the journal thread with the store current, and return its answer. */
  <T> T call(Function<Store, T> task) throws Exception {
    Callable<T> c = () -> {
      ioCheck();
      sync();
      return store == null ? null : task.apply(store);
    };
    Future<T> f = executor.submit(c);
    return f.get(30, TimeUnit.SECONDS);
  }

  /** Tests only: why journalling stopped, or null. */
  String failure() throws Exception {
    return executor.submit(() -> failure).get(30, TimeUnit.SECONDS);
  }

  /** A unit of journal-thread work; may throw, and whatever it throws is logged, never propagated. */
  private interface Task {
    void run() throws Exception;
  }

  private void submit(Task task) {
    if (closed) return;
    try {
      executor.execute(() -> {
        try {
          task.run();
        } catch (Throwable t) { // a failure here must never reach the game or the bridge path
          log.accept("EVI journal: " + t);
        }
      });
    } catch (RejectedExecutionException e) {
      if (!closed) log.accept("EVI journal: work queue full; a packet was not journalled");
    }
  }

  // -------------------------------------------------------------------------------- journal thread

  private void ioCheck() {
    Thread t = Thread.currentThread();
    Consumer<String> seam = ioThreadSeam;
    if (seam != null) seam.accept(t.getName());
    if (t != thread) throw new IllegalStateException("EVI journal file work attempted on " + t.getName() + ", not " + THREAD_NAME);
  }

  private Filepath file(String account) {
    return dir.joinSegment(JournalFile.fileName(account));
  }

  private List<JournalRecord> decode(byte[] bytes) {
    List<JournalRecord> out = new ArrayList<>();
    for (String line : JournalFile.lines(bytes)) out.add(JournalCodec.decode(parser.apply(line)));
    return out;
  }

  private static byte[] encode(List<JournalRecord> records) {
    StringBuilder sb = new StringBuilder();
    for (JournalRecord r : records) sb.append(JournalCodec.encodeLine(r)).append('\n');
    return sb.toString().getBytes(StandardCharsets.UTF_8);
  }

  private Filepath importedFile(String account) {
    return dir.joinSegment(JournalFile.importedFileName(account));
  }

  /** Every account the store was built from: an events file, an imported file, or both. */
  private int knownAccounts() {
    Set<String> all = new TreeSet<>(consumed.keySet());
    all.addAll(importedPrints.keySet());
    return all.size();
  }

  /**
   * Replays every account into a fresh store: its imported file first, then its events file minus what the
   * import already holds. An events file with an unreadable line is left out (with its imported file) and
   * never written; an imported file with an unreadable line is left out on its own.
   */
  void rebuild() throws IOException { // package-private only so a test can call it off the journal thread and see it refused
    ioCheck();
    List<String> eventAccounts = JournalFile.accounts(dir);
    List<String> importedAccounts = JournalFile.importedAccounts(dir);
    Set<String> accounts = new TreeSet<>(eventAccounts);
    accounts.addAll(importedAccounts);
    List<JournalRecord> all = new ArrayList<>();
    Map<String, Long> sizes = new TreeMap<>();
    Map<String, byte[]> lastLines = new TreeMap<>();
    Map<String, JournalFile.Fingerprint> impPrints = new TreeMap<>();
    Map<String, BridgeImport.Dedup> dedups = new TreeMap<>();
    Set<String> bad = new TreeSet<>();
    Set<String> badImports = new TreeSet<>();
    for (String a : accounts) {
      List<JournalRecord> imp = new ArrayList<>();
      if (importedAccounts.contains(a)) {
        Filepath g = importedFile(a);
        impPrints.put(a, JournalFile.fingerprint(g)); // taken BEFORE the read: a change during it shows at the next sync
        try {
          imp = decode(JournalFile.readComplete(g, 0));
        } catch (RuntimeException e) {
          imp = new ArrayList<>();
          badImports.add(a);
          if (!brokenImports.contains(a)) log.accept("EVI journal: " + JournalFile.importedFileName(a) + " has an unreadable line and is left out: " + e.getMessage());
        }
      }
      List<JournalRecord> ev = new ArrayList<>();
      if (eventAccounts.contains(a)) {
        byte[] b = JournalFile.readComplete(file(a), 0);
        try {
          ev = decode(b);
        } catch (RuntimeException e) {
          bad.add(a);
          if (!broken.contains(a)) log.accept("EVI journal: " + JournalFile.fileName(a) + " has an unreadable line and is left untouched: " + e.getMessage());
          continue;
        }
        sizes.put(a, (long) b.length);
        lastLines.put(a, JournalFile.lastLine(b, b.length));
      }
      dedups.put(a, BridgeImport.Dedup.of(imp));
      all.addAll(BridgeImport.merge(imp, ev));
    }
    try {
      store = Store.replay(all, this::write);
    } catch (RuntimeException e) {
      store = null;
      failure = "the journal does not replay: " + e;
      log.accept("EVI journal: stopped -- " + failure);
      throw e;
    }
    consumed.clear();
    consumed.putAll(sizes);
    tails.clear();
    tails.putAll(lastLines);
    importedPrints.clear();
    importedPrints.putAll(impPrints);
    imported.clear();
    imported.putAll(dedups);
    broken.clear();
    broken.addAll(bad);
    brokenImports.clear();
    brokenImports.addAll(badImports);
    claimed.clear();
    rebuildNeeded = false;
  }

  /**
   * Brings the store up to date with every file: new lines another client appended are applied in order.
   * Anything that is not a plain append -- an imported file appearing or changing, an events file whose
   * last-read line is no longer where it was (shrunk or replaced), or new lines that do not decode --
   * rebuilds the whole store from disk instead, so a read never starts in the middle of a line.
   */
  void sync() throws IOException { // package-private only so a test can call it off the journal thread and see it refused
    ioCheck();
    if (failure != null) return;
    if (rebuildNeeded || store == null) {
      rebuild();
      return;
    }
    List<String> imps = JournalFile.importedAccounts(dir);
    if (!imps.equals(new ArrayList<>(importedPrints.keySet()))) {
      rebuild(); // another client ran its import (or an imported file was removed)
      return;
    }
    for (String a : imps) {
      if (!JournalFile.fingerprint(importedFile(a)).equals(importedPrints.get(a))) { // grown, shrunk or replaced
        rebuild();
        return;
      }
    }
    List<String> accounts = JournalFile.accounts(dir);
    for (String a : consumed.keySet()) {
      if (!accounts.contains(a)) {
        rebuild();
        return;
      }
    }
    for (String a : accounts) {
      if (broken.contains(a)) continue;
      Filepath f = file(a);
      long size = JournalFile.size(f);
      long have = consumed.getOrDefault(a, 0L);
      if (size == have) continue; // EVI never rewrites an events file, so an unchanged length is an unchanged file
      // Re-read the last line already applied together with what follows it. If those bytes are no longer
      // where they were -- the file shrank, or was replaced by different content of any length -- it was
      // not appended to, and the store is rebuilt from disk rather than read on from the middle of a line.
      byte[] tail = tails.getOrDefault(a, new byte[0]);
      byte[] b = JournalFile.readComplete(f, have - tail.length);
      if (b.length < tail.length || !Arrays.equals(b, 0, tail.length, tail, 0, tail.length)) {
        rebuild();
        return;
      }
      if (b.length == tail.length) continue; // only part of a line so far
      byte[] fresh = Arrays.copyOfRange(b, tail.length, b.length);
      try {
        BridgeImport.Dedup d = imported.get(a);
        for (JournalRecord r : decode(fresh)) if (d == null || !d.contains(r)) store.apply(r);
      } catch (RuntimeException e) {
        rebuild(); // re-read everything (an unreadable line marks only its own file) rather than drop the work in hand
        return;
      }
      consumed.put(a, have + fresh.length);
      tails.put(a, JournalFile.lastLine(fresh, fresh.length));
    }
  }

  /** The Store's journal: each record goes to its account's file, or nowhere. Never a shared file. */
  private void write(JournalRecord r) {
    ioCheck();
    String account;
    if (r instanceof JournalRecord.PacketRecord) account = ((JournalRecord.PacketRecord) r).packet.account;
    else if (r instanceof JournalRecord.PurchaseRecorded) account = ((JournalRecord.PurchaseRecorded) r).account;
    else if (markAccount != null && (r instanceof JournalRecord.PersonalUse || r instanceof JournalRecord.PositionClosed))
      account = ownerOr(r instanceof JournalRecord.PersonalUse ? ((JournalRecord.PersonalUse) r).buyId : ((JournalRecord.PositionClosed) r).buyId, markAccount);
    else if (markAccount != null && r instanceof JournalRecord.PersonalUseItem) account = markAccount;
    else throw new JournalException("A " + r.type() + " record names no account; the plugin journal does not write it yet");
    if (!Packet.id(account)) throw new JournalException("Invalid account");
    if (broken.contains(account)) throw new JournalException("This account's journal file has an unreadable line, so EVI will not write to it");
    Filepath f = file(account);
    try {
      if (claimed.add(account)) {
        String saved = JournalFile.recoverTail(f, clock.getAsLong());
        if (saved != null) log.accept("EVI journal: an interrupted last line was saved to " + saved);
      }
      String line = JournalCodec.encodeLine(r) + "\n";
      long size = JournalFile.append(f, line, consumed.getOrDefault(account, 0L));
      consumed.put(account, size);
      tails.put(account, line.getBytes(StandardCharsets.UTF_8));
    } catch (JournalFile.ConcurrentWrite e) {
      rebuildNeeded = true;
      claimed.remove(account);
      throw e;
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    }
  }

  /** The account whose offer {@code buyId} names (resolved through the login-time aliases), else {@code fallback}. */
  private String ownerOr(String buyId, String fallback) {
    if (store != null && buyId != null) {
      String id = store.resolve(buyId);
      for (Offer o : store.offers()) if (o.offerId.equals(id) && Packet.id(o.account)) return o.account;
    }
    return fallback;
  }

  private void ingest(String json, long now) {
    ioCheck();
    if (failure != null) return;
    JsonElement el;
    Packet p;
    try {
      el = parser.apply(json);
      p = Packet.validate(el);
    } catch (RuntimeException e) {
      log.accept("EVI journal: refused a packet: " + e.getMessage());
      return;
    }
    // The import never costs the packet that triggered it: whatever it throws -- an I/O failure, a bug, or
    // an Error such as OutOfMemoryError on a huge file -- the packet is journalled next. An Error is not
    // retried this session (the same file would most likely do it again); switching the setting on resets it.
    lastAccount = p.account;
    try {
      maybeImport(p.account);
    } catch (Throwable e) {
      boolean retry = !(e instanceof Error);
      int attempt = importTries.getOrDefault(p.account, 0);
      if (!retry) importTries.put(p.account, IMPORT_TRIES);
      log.accept("EVI journal: the import did not complete (attempt " + attempt + " of " + IMPORT_TRIES
        + " this session; " + (retry ? "tried again at a later packet" : "not tried again this session") + "); this packet is journalled anyway: " + e);
    }
    try {
      sync();
      if (store == null) return;
      for (int attempt = 0; ; attempt++) {
        try {
          store.ingest(el, now);
          return;
        } catch (JournalFile.ConcurrentWrite e) {
          if (attempt >= 2) throw e;
          sync(); // another process wrote: re-read, then try again on the current state
        }
      }
    } catch (JournalException e) {
      log.accept("EVI journal: refused a packet: " + e.getMessage());
    } catch (IOException | RuntimeException e) {
      log.accept("EVI journal: could not journal a packet: " + e);
    }
  }

  static String markerName(String account) {
    return "import-done-" + account + ".json";
  }

  /**
   * The one-time, opt-in import for one account. Never runs while the setting is off. Writes ONLY a new
   * {@code imported-<account>.jsonl} (and the counts marker): the account's events file is not touched, so
   * a client following it is never disturbed. A missing import file is looked for again at every packet
   * (copying it in is enough); a file that cannot be used is not retried this session; a failed WRITE is
   * retried at later packets, {@value #IMPORT_TRIES} attempts a session. Switching the setting on again
   * resets all of that.
   */
  private void maybeImport(String account) throws IOException {
    ioCheck();
    ImportFileState file = waitingForImportFile(account);
    // UNKNOWN leaves the line as it is: no false "no file was found", and no line hidden on a guess either.
    if (file != ImportFileState.UNKNOWN) notice(file == ImportFileState.ABSENT ? IMPORT_MISSING_NOTICE : null);
    if (!importEnabled.getAsBoolean() || importDone.contains(account)) return;
    if (file == ImportFileState.UNKNOWN) {
      if (importUnknownLogged.add(account))
        log.accept("EVI journal: the import file could not be checked just now (it may be in use by another program); it is looked"
          + " at again at the next packet");
      return; // not an attempt: nothing was read
    }
    if (file == ImportFileState.ABSENT) {
      if (importMissingLogged.add(account)) {
        log.accept("EVI journal: import is on, but there is no " + IMPORT_DIR + "/" + IMPORT_FILE + " in the plugin's data folder"
          + " (" + PluginFolder.PATH + "/); nothing imported yet, and it is looked for again at every packet");
      }
      return;
    }
    int tries = importTries.getOrDefault(account, 0);
    if (tries >= IMPORT_TRIES) return;
    String name = characterNames.get(account);
    if (name == null && namesExpected && waitingForName.contains(account)) return; // still no name: nothing read again
    Filepath marker = dir.joinSegment(markerName(account));
    Filepath target = importedFile(account);
    Filepath src = root.joinSegment(IMPORT_DIR).joinSegment(IMPORT_FILE);
    importTries.put(account, tries + 1);
    long srcSize = JournalFile.size(src);
    if (srcSize > importMaxBytes) {
      importTries.put(account, IMPORT_TRIES);
      log.accept("EVI journal: " + IMPORT_DIR + "/" + IMPORT_FILE + " is " + srcSize + " bytes, larger than any EVI journal ("
        + importMaxBytes + " at most), so nothing was imported");
      return;
    }
    List<JournalRecord> all;
    BridgeImport.Selection sel;
    boolean marks;
    try {
      marks = importItemMarks.getAsBoolean();
    } catch (RuntimeException e) {
      marks = false;
    }
    try {
      all = decode(JournalFile.readComplete(src, 0));
      if (name == null && namesExpected && namesFlips(all)) {
        importTries.put(account, tries); // not an attempt: the import waits for the character's name, read at the next packet after it
        if (waitingForName.add(account))
          log.accept("EVI journal: the import waits for this character's name (its trade history from another tracker is kept by name)");
        return;
      }
    } catch (RuntimeException e) {
      importTries.put(account, IMPORT_TRIES);
      log.accept("EVI journal: the import file could not be read or replayed, so nothing was imported: " + e.getMessage());
      return;
    }
    // The player's stated former names (import/preferences.json "oldNames"), read only when the file holds flips kept by name.
    OldNames oldNames = OldNames.NONE;
    if (name != null && namesFlips(all)) {
      Filepath prefs = root.joinSegment(IMPORT_DIR).joinSegment(PREFERENCES_FILE);
      ImportFileState ps = importFileState(importFileLook.apply(prefs));
      if (ps == ImportFileState.UNKNOWN) {
        importTries.put(account, tries); // not an attempt: looked at again at the next packet, as the import file is
        if (importUnknownLogged.add(account))
          log.accept("EVI journal: " + IMPORT_DIR + "/" + PREFERENCES_FILE + " could not be checked just now (it may be in use by"
            + " another program); the import waits and looks again at the next packet");
        return;
      }
      if (ps == ImportFileState.PRESENT) {
        try {
          long n = JournalFile.size(prefs);
          if (n > PREFERENCES_MAX_BYTES) throw new IllegalArgumentException(n + " bytes, larger than any preferences file");
          oldNames = OldNames.parse(new String(JournalFile.readAll(prefs), StandardCharsets.UTF_8)); // whole: no trailing newline needed
        } catch (IllegalArgumentException e) {
          // The import runs once per account: never run it without former names the player may have meant to give.
          importTries.put(account, IMPORT_TRIES);
          log.accept("EVI journal: " + IMPORT_DIR + "/" + PREFERENCES_FILE + " could not be read (" + e.getMessage() + "), so nothing"
            + " was imported; correct it, then switch the import setting off and on");
          return;
        }
        if (oldNames.refusedCount() > 0)
          log.accept("EVI journal: " + oldNames.refusedCount() + " former name(s) in " + IMPORT_DIR + "/" + PREFERENCES_FILE
            + " oldNames were refused (mapped to two different current names, to no name, or to a name that is itself listed as a"
            + " former name); trades kept under them are left out");
      }
    }
    // The former data folder's salt (import/identity-salt.txt), when the player copied it: the bridge journalled this account under
    // the id THAT salt gives, so the records are selected by it and filed under this account's own id. Absent: as before.
    String from = account;
    Filepath saltFile = root.joinSegment(IMPORT_DIR).joinSegment(SALT_FILE);
    ImportFileState saltState = importFileState(importFileLook.apply(saltFile));
    if (saltState == ImportFileState.UNKNOWN) {
      importTries.put(account, tries); // not an attempt: looked at again at the next packet, as the import file is
      if (importUnknownLogged.add(account))
        log.accept("EVI journal: " + IMPORT_DIR + "/" + SALT_FILE + " could not be checked just now (it may be in use by another"
          + " program); the import waits and looks again at the next packet");
      return;
    }
    if (saltState == ImportFileState.PRESENT) {
      String[] identity = identities.get(account);
      if (identity == null) {
        importTries.put(account, tries); // not an attempt: the plugin tells the identity at login
        if (waitingForIdentity.add(account))
          log.accept("EVI journal: the import waits for this account's identity (" + IMPORT_DIR + "/" + SALT_FILE + " names its records by it)");
        return;
      }
      String salt;
      try {
        long n = JournalFile.size(saltFile);
        if (n > SALT_MAX_BYTES) throw new IllegalArgumentException(n + " bytes, larger than any identity salt");
        salt = new String(JournalFile.readAll(saltFile), StandardCharsets.UTF_8).replace("\uFEFF", "").trim();
        if (salt.isEmpty()) throw new IllegalArgumentException("it is empty");
      } catch (IllegalArgumentException e) {
        // The import runs once per account: never run it under an id the player did not mean (the preferences.json rule).
        importTries.put(account, IMPORT_TRIES);
        log.accept("EVI journal: " + IMPORT_DIR + "/" + SALT_FILE + " could not be read (" + e.getMessage() + "), so nothing was"
          + " imported; correct it, then switch the import setting off and on");
        return;
      }
      from = AccountIds.of(salt, identity[0], identity[1]);
    }
    try {
      sel = BridgeImport.select(all, from, marks, name, oldNames);
    } catch (RuntimeException e) {
      importTries.put(account, IMPORT_TRIES);
      log.accept("EVI journal: the import file could not be read or replayed, so nothing was imported: " + e.getMessage());
      return;
    }
    if (broken.contains(account)) {
      importTries.put(account, IMPORT_TRIES);
      log.accept("EVI journal: this account's journal has an unreadable line; import refused");
      return;
    }
    List<JournalRecord> existing;
    try {
      existing = decode(JournalFile.readComplete(file(account), 0));
    } catch (RuntimeException e) {
      importTries.put(account, IMPORT_TRIES);
      log.accept("EVI journal: this account's journal has an unreadable line; import refused");
      return;
    }
    List<JournalRecord> mine = from.equals(account) ? sel.records : rekey(sel.records, from, account);
    List<JournalRecord> merged = BridgeImport.merge(mine, existing);
    try {
      Store.replay(merged, r -> {
        throw new IllegalStateException("a validation replay must not write");
      }).state(clock.getAsLong());
    } catch (RuntimeException e) {
      importTries.put(account, IMPORT_TRIES);
      log.accept("EVI journal: the imported history does not replay, so nothing was imported: " + e);
      return;
    }
    // An I/O failure here (a locked or blocked file) propagates to ingest, which keeps the packet; this
    // attempt is already counted, so the import is tried again at a later packet, IMPORT_TRIES at most.
    dir.createDirectories();
    try {
      JournalFile.writeNew(target, encode(mine));
    } catch (JournalFile.AlreadyExists e) {
      // Another client imported this account between the check above and the write: its file IS the import
      // (written once, never changed), so this is success by another writer, not a failed attempt.
      importDone.add(account);
      rebuildNeeded = true;
      log.accept("EVI journal: another client imported this account's old history at the same moment; its import is used and nothing was written here");
      return;
    }
    importDone.add(account);
    rebuildNeeded = true;
    JsonObject m = new JsonObject();
    m.addProperty("at", clock.getAsLong());
    m.addProperty("imported", sel.records.size());
    m.addProperty("keptFromPlugin", merged.size() - sel.records.size());
    m.addProperty("bridgeRecords", sel.total);
    m.addProperty("otherAccounts", sel.otherAccounts);
    m.addProperty("notTiedToAnAccount", sel.notTiedToAnAccount);
    m.addProperty("unresolved", sel.unresolved);
    if (marks) m.addProperty("itemMarks", sel.itemMarks);
    m.addProperty("flips", sel.flips);
    m.addProperty("flipsOtherCharacters", sel.flipsOtherCharacters);
    if (oldNames.present) {
      m.addProperty("flipsViaOldNames", sel.flipsViaOldNames);
      m.addProperty("flipsOldNamesRefused", sel.flipsOldNamesRefused);
    }
    if (!from.equals(account)) m.addProperty("viaIdentitySalt", true);
    try {
      JournalFile.writeNew(marker, (m.toString() + "\n").getBytes(StandardCharsets.UTF_8));
    } catch (JournalFile.AlreadyExists e) {
      log.accept("EVI journal: the import is done; its counts were already saved by another client");
    } catch (IOException e) {
      log.accept("EVI journal: the import is done, but its counts could not be saved: " + e);
    }
    log.accept("EVI journal: imported " + sel.records.size() + " of the import file's " + sel.total + " records for this account ("
      + sel.otherAccounts + " belong to other accounts, " + (marks ? sel.itemMarks + " are item marks taken for every account, " : "")
      + sel.notTiedToAnAccount + " name no account); " + sel.flips + " trades from another tracker under this character's name, "
      + sel.flipsOtherCharacters + " under other names left out"
      + (oldNames.present ? " (" + sel.flipsViaOldNames + " taken under this character's former names, " + sel.flipsOldNamesRefused
        + " under refused former names)" : "")
      + (from.equals(account) ? "" : "; this account's records were recognised by " + IMPORT_DIR + "/" + SALT_FILE));
    if (saltState == ImportFileState.ABSENT && sel.otherAccounts > 0 && ownedCount(sel.records) == 0)
      log.accept("EVI journal: none of the import file's records carry this account's id. If they were kept by the old companion"
        + " app, its ids came from another identity salt: " + SALT_HINT + " into " + IMPORT_DIR + "/ (the README says where it is)"
        + " before your other accounts import");
  }

  /** The records an account owns (packets, flips, purchases, marks naming its offers): every kind but the machine-wide ones. */
  static int ownedCount(List<JournalRecord> records) {
    int n = 0;
    for (JournalRecord r : records)
      if (!(r instanceof JournalRecord.PersonalUseItem || r instanceof JournalRecord.PersonalUseItemUndo || r instanceof JournalRecord.FlipsImported)) n++;
    return n;
  }

  /**
   * The same records with every value equal to {@code from} (an account id: 64 hex digits, so it is never part of anything else)
   * replaced by {@code to}, through the journal's own line format. Records that do not name {@code from} are kept as they are.
   */
  private List<JournalRecord> rekey(List<JournalRecord> records, String from, String to) {
    String q = '"' + from + '"', r = '"' + to + '"';
    List<JournalRecord> out = new ArrayList<>(records.size());
    for (JournalRecord x : records) {
      String line = JournalCodec.encodeLine(x);
      out.add(line.contains(q) ? JournalCodec.decode(parser.apply(line.replace(q, r))) : x);
    }
    return out;
  }

  /** Whether a bridge journal holds flip histories from another tracker that name a character. */
  static boolean namesFlips(List<JournalRecord> all) {
    for (JournalRecord r : all)
      if (r instanceof JournalRecord.FlipsImported) for (ImportedFlip f : ((JournalRecord.FlipsImported) r).flips) if (f.account != null) return true;
    return false;
  }

  /**
   * Whether {@code account} is still waiting for an import file: null when it is not (the setting off, or the account
   * imported), else the state of {@code import/events.jsonl} -- ABSENT is the only "waiting for a file" ({@link
   * #importFileState}). An import already on disk (its imported file, or the counts marker on its own) is recorded as done
   * here, so the line never asks for a file an account no longer needs.
   */
  private ImportFileState waitingForImportFile(String account) throws IOException {
    ioCheck();
    if (!importEnabled.getAsBoolean() || importDone.contains(account)) return null;
    if (importedFile(account).exists() || dir.joinSegment(markerName(account)).exists()) {
      importDone.add(account);
      return null;
    }
    return importFileState(importFileLook.apply(root.joinSegment(IMPORT_DIR).joinSegment(IMPORT_FILE)));
  }

  /** Tells the import line {@code text} (null hides it), once per change. Journal thread. */
  private void notice(String text) {
    if (noticeSent && java.util.Objects.equals(text, noticeShown)) return;
    noticeSent = true;
    noticeShown = text;
    Consumer<String> l = importNotice;
    if (l != null) l.accept(text);
  }
}

package com.evi.live.journal;

import java.util.ArrayList;
import java.util.List;

/**
 * The sidebar's realised-profit line (server.mjs {@code profitSince}): every reviewed and automatic flip
 * whose last sale is at or after {@code since}, plus the two gaps it does NOT include, said out loud.
 *
 * <p>DELIBERATELY ACROSS EVERY ACCOUNT ON THE MACHINE -- the maintainer's 26 Sept 2026 decision ("leave it as it
 * is"), recorded in the project notes. The name says so, so no caller mistakes it for one account's figure. If it
 * is ever made per-account, that is the recommended fix there (the profit line, not the history tier).
 */
public final class Profit {
  /** Null means "since EVI started matching" (the player never pressed Reset). */
  public final Long since;
  public final long gp;
  public final int trades;
  public final int winners;
  public final int losers;
  public final int unmatchedSales;
  public final int openPositions;

  Profit(Long since, long gp, int trades, int winners, int losers, int unmatchedSales, int openPositions) {
    this.since = since;
    this.gp = gp;
    this.trades = trades;
    this.winners = winners;
    this.losers = losers;
    this.unmatchedSales = unmatchedSales;
    this.openPositions = openPositions;
  }

  public static Profit sinceAllAccounts(StoreState st, Long since) {
    List<Long[]> counted = new ArrayList<>(); // {profit, lastSell}
    for (ManualFlip f : st.flips) if (!f.isRemoved() && f.lastSell != null) counted.add(new Long[]{f.profit, f.lastSell});
    for (FifoMatcher.AutoFlip f : st.autoFlips) if (f.lastSell != null) counted.add(new Long[]{f.profit, f.lastSell});
    long gp = 0;
    int trades = 0, winners = 0, losers = 0;
    for (Long[] x : counted) {
      if (since != null && x[1] < since) continue;
      gp = Js.add(gp, x[0]);
      trades++;
      if (x[0] > 0) winners++;
      if (x[0] < 0) losers++;
    }
    return new Profit(since, gp, trades, winners, losers, st.dataHealth.unmatchedSales, st.dataHealth.openPositions);
  }
}

package com.evi.live.journal;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.TreeMap;
import java.util.function.Supplier;

/**
 * The journal: every GE offer EVI has seen, the flips made from them, and the player's own marks. Ported
 * from bridge/store.mjs for the self-contained plugin, and proven equal to it by the parity tests
 * (the public golden transcripts, the generated journal vectors, and a private replay of the real journal).
 *
 * <p>PURE: no file, no clock, no thread. Persistence is the {@link Journal} the caller supplies -- it is
 * handed each record BEFORE the record is applied, exactly as store.mjs writes the line and then applies
 * it, so a write that throws leaves the store unchanged. Time is always passed in. The caller confines a
 * Store to one thread (the journal's own executor); nothing here is synchronised.
 *
 * <p>Three behaviours worth knowing before "fixing" anything here, each deliberate:
 * <ul>
 *   <li>The plugin gives every offer a NEW offerId whenever it first sees it at login (every restart,
 *       relog or world hop). {@link #continuation} links that new id to the earlier record of the same GE
 *       offer -- same account, slot, item, side, price and quantity, still in that slot when its session
 *       last reported, counters not gone backwards, and only when exactly one candidate fits -- and the
 *       alias is rebuilt purely from the journal on replay.</li>
 *   <li>A 1-unit buy filled instantly at a better price than asked is a price probe and is invisible on
 *       purpose (see {@link FifoMatcher#isMarginCheck}).</li>
 *   <li>A logged-out packet ({@code offers: []}) says nothing about the market: it empties the session's
 *       slot list, not the journal's knowledge of the offers.</li>
 * </ul>
 *
 * <h3>Deliberate departures from store.mjs (the divergence list)</h3>
 * Everywhere else this class answers exactly as store.mjs does, and the parity tests hold it to that. These
 * are the only places it does not, each because a long cannot hold what a JS double silently rounds:
 * <ol>
 *   <li>{@link #recordPurchase} refuses a purchase whose total cost is past 2^53 - 1
 *       ({@value #TOO_LARGE_TO_RECORD}); JS records it with a rounded cost.</li>
 *   <li>{@link #importFlips} refuses a row whose capital + profit is past 2^53 - 1, with the bridge's own
 *       message for a bad figure; JS journals the rounded sum. The check runs AFTER both duplicate skips
 *       (same fingerprint, same content), as store.mjs reads nothing of a row it skips, so a re-import of a
 *       held trade is skipped here too (journal vectors {@code import-unsafe-duplicate}).</li>
 *   <li>{@link #state} throws ArithmeticException when a GP total reaches 2^63 (JS returns a rounded double);
 *       {@link #closePosition}, the one mutator that reads state, turns that into a {@link JournalException}
 *       ({@value #TOO_LARGE_TO_ANSWER}).</li>
 *   <li>{@link CostBasis#held} answers null without an account, where JS sums every account (the port
 *       warning of the self-contained port; the journal vectors count those calls).</li>
 * </ol>
 */
public final class Store {
  /** Where records go before they are applied: an events.jsonl appender in the plugin, a list in a test. */
  public interface Journal {
    void append(JournalRecord record);
  }

  /** A client session as the store tracks it (store.mjs {@code this.sessions} values). */
  static final class Session {
    final String account;
    long seq;
    long lastSeen;
    final boolean loggedIn;
    final List<String> slots;
    Long capturedAt;

    Session(String account, long seq, long lastSeen, boolean loggedIn, List<String> slots) {
      this.account = account;
      this.seq = seq;
      this.lastSeen = lastSeen;
      this.loggedIn = loggedIn;
      this.slots = slots;
    }
  }

  private final Journal journal;
  private final Map<String, Offer> offers = new LinkedHashMap<>();
  private final Map<String, Session> sessions = new LinkedHashMap<>();
  private final List<ManualFlip> flips = new ArrayList<>();
  private final Set<String> personalUse = new LinkedHashSet<>();
  private final Set<Integer> personalUseItems = new LinkedHashSet<>();
  private final Map<Integer, Long> personalUseKept = new LinkedHashMap<>();
  private final Map<String, String> alias = new HashMap<>();
  private final Map<String, String[]> lastSlots = new HashMap<>();
  /**
   * ENDED UNSEEN (8 Oct 2026, fixed in JS first). An offer only ends in the journal when EVI SEES it end; one that filled or
   * was cancelled while the player was logged out, its slot collected and reused in a session the plugin never reported,
   * stayed BUYING/SELLING for ever (a real case: the card kept quoting a net profit for an item already
   * sold). At each logged-in packet every slot is compared with the SAME ACCOUNT's previous logged-in session's last report:
   * an unfinished offer no longer in its slot (empty, or an offer {@link #continuation} did not link to it) ended unseen, at
   * the packet's ts. In memory only, rebuilt on replay exactly like the aliases; never a sale. Never from a logged-out
   * packet, a partial one, or within one session; withdrawn if the offer is ever seen again.
   */
  private final Map<String, LastLogin> lastLoggedIn = new HashMap<>();
  private final Map<String, Long> endedUnseen = new LinkedHashMap<>();

  /** An account's most recent logged-in packet: its session and resolved slots. */
  private static final class LastLogin {
    final String session;
    final String[] slots;

    LastLogin(String session, String[] slots) {
      this.session = session;
      this.slots = slots;
    }
  }
  private final Map<String, FifoMatcher.Closed> closed = new LinkedHashMap<>();
  private List<ImportedFlip> importedFlips = new ArrayList<>();
  private Set<String> importedFingerprints = new HashSet<>();
  private Set<String> importedContent = new HashSet<>();
  private int linkedCount;

  /**
   * The imported flip histories as they stand after every record so far (removals applied, a repeated fingerprint skipped):
   * the very objects of the records that hold them. Read-only; the import's selection uses it to take exactly the flips the
   * bridge still holds.
   */
  List<ImportedFlip> importedFlipsNow() {
    return Collections.unmodifiableList(importedFlips);
  }

  /** An empty store (a fresh install). */
  public Store(Journal journal) {
    this.journal = Objects.requireNonNull(journal, "journal");
  }

  /**
   * The bridge's constructor: replay a journal, then mark every session as not seen (a replayed session
   * is history, not a live connection).
   */
  public static Store replay(Iterable<JournalRecord> records, Journal journal) {
    Store s = new Store(journal);
    for (JournalRecord r : records) s.apply(r);
    for (Session x : s.sessions.values()) x.lastSeen = 0;
    return s;
  }

  private void append(JournalRecord r) {
    journal.append(r);
    apply(r);
  }

  /** Every offer the journal knows, in first-seen order. Read-only. */
  public Collection<Offer> offers() {
    return Collections.unmodifiableCollection(offers.values());
  }

  /** The original offerId a login-time id was linked to, or the id itself. */
  public String resolve(String offerId) {
    String a = alias.get(offerId);
    return a != null ? a : offerId;
  }

  void apply(JournalRecord rec) {
    if (rec instanceof JournalRecord.FlipMark) {
      JournalRecord.FlipMark r = (JournalRecord.FlipMark) rec;
      ManualFlip f = findFlip(r.id);
      if (f == null) return;
      if (JournalRecord.FlipMark.REOPENED.equals(r.type())) {
        f.removed = true;
        f.reopened = true;
      } else {
        f.removed = JournalRecord.FlipMark.REMOVED.equals(r.type());
      }
    } else if (rec instanceof JournalRecord.FlipRecord) {
      flips.add(((JournalRecord.FlipRecord) rec).flip);
    } else if (rec instanceof JournalRecord.PersonalUse) {
      JournalRecord.PersonalUse r = (JournalRecord.PersonalUse) rec;
      if (r.undo) personalUse.remove(resolve(r.buyId));
      else personalUse.add(resolve(r.buyId));
    } else if (rec instanceof JournalRecord.PersonalUseItem) {
      // kept = how many of this item the player holds FOR USE. A record with none (pre 1 Oct 2026) stays
      // a blanket exclusion; re-marking RAISES the count, never lowers it.
      JournalRecord.PersonalUseItem r = (JournalRecord.PersonalUseItem) rec;
      personalUseItems.add(r.itemId);
      if (r.kept != null && Js.isSafeInteger(r.kept) && r.kept >= 1 && r.kept <= Js.INT32_MAX) {
        Long had = personalUseKept.get(r.itemId);
        personalUseKept.put(r.itemId, Math.max(r.kept.longValue(), had == null ? 0 : had));
      }
    } else if (rec instanceof JournalRecord.PersonalUseItemUndo) {
      int itemId = ((JournalRecord.PersonalUseItemUndo) rec).itemId;
      personalUseItems.remove(itemId);
      personalUseKept.remove(itemId);
    } else if (rec instanceof JournalRecord.FlipsImported) {
      for (ImportedFlip f : ((JournalRecord.FlipsImported) rec).flips) {
        if (importedFingerprints.contains(f.fp)) continue;
        importedFingerprints.add(f.fp);
        importedContent.add(f.contentKey());
        importedFlips.add(f);
      }
    } else if (rec instanceof JournalRecord.FlipsImportRemoved) {
      String source = ((JournalRecord.FlipsImportRemoved) rec).source;
      List<ImportedFlip> kept = new ArrayList<>();
      for (ImportedFlip f : importedFlips) if (!Objects.equals(f.source, source)) kept.add(f);
      importedFlips = kept;
      importedFingerprints = new HashSet<>();
      importedContent = new HashSet<>();
      for (ImportedFlip f : kept) {
        importedFingerprints.add(f.fp);
        importedContent.add(f.contentKey());
      }
    } else if (rec instanceof JournalRecord.PurchaseRecorded) {
      // A purchase the player made while EVI was not watching: joins the offer pool as a finished buy,
      // marked recorded so what EVI observed and what it was told stay distinguishable.
      JournalRecord.PurchaseRecorded o = (JournalRecord.PurchaseRecorded) rec;
      offers.put(o.offerId, new Offer(-1, "BOUGHT", o.offerId, o.itemId, o.name, o.unitPrice, o.quantity, o.quantity,
        Js.multiply(o.unitPrice, o.quantity), true, null, o.account, "recorded", o.at, o.at, o.at, Boolean.TRUE));
    } else if (rec instanceof JournalRecord.PurchaseRecordRemoved) {
      offers.remove(((JournalRecord.PurchaseRecordRemoved) rec).offerId);
    } else if (rec instanceof JournalRecord.PositionClosed) {
      JournalRecord.PositionClosed r = (JournalRecord.PositionClosed) rec;
      closed.put(r.buyId, new FifoMatcher.Closed(r.reason, r.at));
    } else if (rec instanceof JournalRecord.PositionReopened) {
      closed.remove(((JournalRecord.PositionReopened) rec).buyId);
    } else if (rec instanceof JournalRecord.PacketRecord) {
      applyPacket((JournalRecord.PacketRecord) rec);
    } else {
      throw new IllegalArgumentException("unknown record " + rec.type());
    }
  }

  private void applyPacket(JournalRecord.PacketRecord r) {
    Packet p = r.packet;
    List<String> slotIds = new ArrayList<>();
    for (Packet.SlotOffer o : p.offers) slotIds.add(o.offerId);
    sessions.put(p.session, new Session(p.account, p.seq, r.received, p.loggedIn, Collections.unmodifiableList(slotIds)));
    for (Packet.SlotOffer o : p.offers) {
      if (o.empty()) continue;
      if (!o.knownStart && !offers.containsKey(o.offerId) && !alias.containsKey(o.offerId)) {
        Offer original = continuation(p, o);
        if (original != null) {
          alias.put(o.offerId, original.offerId);
          linkedCount++;
        }
      }
      boolean aliased = alias.containsKey(o.offerId);
      String key = resolve(o.offerId);
      Offer old = offers.get(key);
      if (aliased && old == null) throw new IllegalStateException("alias " + o.offerId + " points at no offer");
      // A linked continuation keeps the original record's coverage: the plugin can only say "false" for
      // an offer it first saw at login, even when EVI watched it start.
      boolean knownStart = aliased ? old.knownStart : (old != null ? old.knownStart : o.knownStart) && o.knownStart;
      // A packet with no tick reading (-1; every cancel sends one) keeps the real reading taken earlier.
      Integer ticks = o.ticksToFill != null && o.ticksToFill >= 0 ? o.ticksToFill : (old != null ? old.ticksToFill : null);
      Long firstSeen = old != null && old.firstSeen != null ? old.firstSeen : Long.valueOf(p.ts);
      Long completedAt = old != null && old.completedAt != null ? old.completedAt
        : (Offer.finished(o.state, o.total, o.filled) ? Long.valueOf(p.ts) : null);
      offers.put(key, new Offer(o.slot, o.state, key, o.itemId, o.name, o.price, o.total, o.filled, o.spent, knownStart, ticks,
        p.account, p.session, firstSeen, p.ts, completedAt, null));
      // Seen again (a linked continuation, or its own id): whatever was concluded about it is withdrawn.
      endedUnseen.remove(key);
    }
    if (p.loggedIn && p.offers.size() == 8) {
      String[] slots = new String[8];
      for (int i = 0; i < 8; i++) {
        for (Packet.SlotOffer o : p.offers) {
          if (o.slot != i) continue;
          slots[i] = o.empty() ? null : resolve(o.offerId);
          break;
        }
      }
      LastLogin prev = lastLoggedIn.get(p.account);
      if (prev != null && !Objects.equals(prev.session, p.session)) for (int i = 0; i < 8; i++) {
        String x = prev.slots[i];
        if (x == null || x.equals(slots[i]) || endedUnseen.containsKey(x)) continue;
        Offer was = offers.get(x);
        if (was == null || was.finished() || Arrays.asList(slots).contains(x)) continue;
        endedUnseen.put(x, p.ts);
      }
      lastSlots.put(p.session, slots);
      lastLoggedIn.put(p.account, new LastLogin(p.session, slots));
    }
  }

  /**
   * The earlier record of the same GE offer, for an offerId first seen at login; null unless exactly ONE
   * candidate fits. See the class comment.
   */
  Offer continuation(Packet p, Packet.SlotOffer o) {
    List<Offer> candidates = new ArrayList<>();
    String side = Offer.side(o.state);
    for (Offer x : offers.values()) {
      if (!Objects.equals(x.account, p.account) || Objects.equals(x.session, p.session) || x.slot != o.slot || x.itemId != o.itemId
        || !x.side().equals(side) || x.price != o.price || x.total != o.total || x.filled > o.filled || x.spent > o.spent) continue;
      String[] last = lastSlots.get(x.session);
      if (last == null || !Objects.equals(last[o.slot], x.offerId)) continue;
      if (x.finished() && (!x.state.equals(o.state) || x.filled != o.filled || x.spent != o.spent)) continue;
      candidates.add(x);
    }
    return candidates.size() == 1 ? candidates.get(0) : null;
  }

  /**
   * One packet from the plugin. Returns true when it was a duplicate (a seq already seen for its session)
   * and was ignored. Throws, with the bridge's exact message, when it is invalid, from a clock more than a
   * minute ahead, from a session that changed account, or when an offer's identity or counters changed.
   * Only a packet that changes something is journalled; heartbeats update freshness in memory.
   */
  public boolean ingest(JsonElement input, long now) {
    Packet p = Packet.validate(input);
    Session oldSession = sessions.get(p.session);
    if (p.ts > now + 60000) throw new JournalException("Plugin clock is ahead of EVI's clock");
    if (oldSession != null && !Objects.equals(oldSession.account, p.account)) throw new JournalException("Session account changed");
    if (oldSession != null && p.seq <= oldSession.seq) return true;
    for (Packet.SlotOffer o : p.offers) {
      Offer old = offers.get(resolve(o.offerId));
      if (old != null && (!Objects.equals(old.session, p.session) || !Objects.equals(old.account, p.account) || old.itemId != o.itemId
        || old.price != o.price || old.total != o.total || old.slot != o.slot || old.filled > o.filled || old.spent > o.spent
        || !old.side().equals(Offer.side(o.state)) || (old.finished() && !Offer.finished(o.state, o.total, o.filled))))
        throw new JournalException("Offer identity or counters changed");
    }
    boolean changed = oldSession == null || oldSession.loggedIn != p.loggedIn || !oldSession.slots.equals(slotIds(p));
    for (Packet.SlotOffer o : p.offers) {
      if (changed) break;
      if (o.empty()) continue;
      changed = differs(o);
    }
    if (changed) append(new JournalRecord.PacketRecord(now, p));
    Session session = sessions.get(p.session);
    session.lastSeen = now;
    session.seq = p.seq;
    // Queued packets are historical, not proof of a live game connection.
    session.capturedAt = p.ts;
    return false;
  }

  private static List<String> slotIds(Packet p) {
    List<String> ids = new ArrayList<>();
    for (Packet.SlotOffer o : p.offers) ids.add(o.offerId);
    return ids;
  }

  // Does this slot disagree with what the journal holds? A linked continuation is stored under its
  // original offerId and coverage, so those two fields legitimately differ; and a packet with no tick
  // reading is not disagreeing with the better value kept from when the offer filled.
  private boolean differs(Packet.SlotOffer o) {
    Offer rec = offers.get(resolve(o.offerId));
    if (rec == null) return true;
    boolean linked = alias.containsKey(o.offerId);
    if (o.slot != rec.slot || !o.state.equals(rec.state) || o.itemId != rec.itemId || !Objects.equals(o.name, rec.name)
      || o.price != rec.price || o.total != rec.total || o.filled != rec.filled || o.spent != rec.spent) return true;
    if (!linked && (!o.offerId.equals(rec.offerId) || o.knownStart != rec.knownStart)) return true;
    return o.ticksToFill != null && o.ticksToFill >= 0 && !o.ticksToFill.equals(rec.ticksToFill);
  }

  /** Everything the journal knows, as of {@code now}. See {@link StoreState}. */
  public StoreState state(long now) {
    List<StoreState.SessionView> sessionViews = new ArrayList<>();
    List<Offer> slots = new ArrayList<>();
    for (Map.Entry<String, Session> e : sessions.entrySet()) {
      Session s = e.getValue();
      boolean live = s.lastSeen > now - 30000 && s.capturedAt != null && s.capturedAt > now - 30000;
      sessionViews.add(new StoreState.SessionView(e.getKey(), s, live));
      if (!live || !s.loggedIn) continue;
      for (String id : s.slots) {
        Offer o = offers.get(resolve(id));
        if (o != null) slots.add(o);
      }
    }
    // Cancellations with nothing filled moved no items or GP: not "completed" trades.
    List<Offer> completedOffers = new ArrayList<>();
    for (Offer o : offers.values()) if (o.finished() && !(o.state.startsWith("CANCELLED") && o.filled == 0)) completedOffers.add(o);
    // Anything claimed by a manual, non-reopened review stays out of automatic matching, so no trade is
    // counted twice; a buy marked personal use stays out entirely.
    Set<String> used = new HashSet<>();
    for (ManualFlip f : flips) {
      if (f.isReopened()) continue;
      used.add(f.buyId);
      used.addAll(f.sellIdsOrSingle());
    }
    List<Offer> pool = new ArrayList<>();
    for (Offer o : completedOffers) if (!used.contains(o.offerId) && !personalUse.contains(o.offerId)) pool.add(o);
    // Offers that ended while EVI was not watching. A sell is never a sale, only what an open position may claim; a buy's
    // filled units, as last seen, are an open lot (FifoMatcher.computeAutoFlips), unless it is matched or personal use.
    List<FifoMatcher.EndedUnseen> unseenOffers = new ArrayList<>();
    List<StoreState.EndedUnseenOffer> unseen = new ArrayList<>();
    for (Map.Entry<String, Long> e : endedUnseen.entrySet()) {
      unseen.add(new StoreState.EndedUnseenOffer(e.getKey(), e.getValue()));
      Offer o = offers.get(e.getKey());
      if (o != null && ("sell".equals(o.side()) || (!used.contains(o.offerId) && !personalUse.contains(o.offerId))))
        unseenOffers.add(new FifoMatcher.EndedUnseen(o, e.getValue()));
    }
    FifoMatcher.Result auto = FifoMatcher.computeAutoFlips(pool, closed, unseenOffers);
    List<ManualFlip> manual = new ArrayList<>(), removed = new ArrayList<>();
    for (ManualFlip f : flips) (f.isRemoved() ? removed : manual).add(f);
    // Two sums, then their sum: JS's order of additions, which matters only past 2^53 (see Js.add).
    long manualProfit = 0, autoProfit = 0;
    for (ManualFlip f : manual) manualProfit = Js.add(manualProfit, f.profit);
    for (FifoMatcher.AutoFlip f : auto.flips) autoProfit = Js.add(autoProfit, f.profit);
    long netProfit = Js.add(manualProfit, autoProfit);
    // Items excluded WHOLESALE from the idle-inventory tier: every buy-derived mark, plus item marks with
    // no kept count. An item mark WITH a count is in personalUseKept instead (only the surplus is offered).
    Set<Integer> puItemIds = new LinkedHashSet<>();
    for (String buyId : personalUse) {
      Offer o = offers.get(buyId);
      if (o != null) puItemIds.add(o.itemId);
    }
    for (Integer id : personalUseItems) if (!personalUseKept.containsKey(id)) puItemIds.add(id);
    List<Offer> active = new ArrayList<>(), occupied = new ArrayList<>();
    for (Offer o : slots) {
      if (!o.finished()) active.add(o);
      if (!"EMPTY".equals(o.state)) occupied.add(o);
    }
    List<Offer> newestFirst = new ArrayList<>(completedOffers);
    newestFirst.sort((a, b) -> Js.compare(num(b.updated), num(a.updated)));
    List<StoreState.CompletedOffer> completed = new ArrayList<>();
    for (Offer o : newestFirst)
      completed.add(new StoreState.CompletedOffer(o, "sell".equals(o.side()) ? Tax.saleProceeds(o) : null, FifoMatcher.isMarginCheck(o)));
    List<Offer> puBuys = new ArrayList<>();
    for (String id : personalUse) {
      Offer o = offers.get(id);
      if (o != null) puBuys.add(o);
    }
    StoreState.ImportedSummary summary = null;
    if (!importedFlips.isEmpty()) {
      Set<Integer> items = new HashSet<>();
      Set<String> sources = new LinkedHashSet<>();
      long profit = 0, from = Long.MAX_VALUE, to = Long.MIN_VALUE;
      for (ImportedFlip f : importedFlips) {
        items.add(f.itemId);
        sources.add(f.source);
        profit = Js.add(profit, f.profit);
        from = Math.min(from, f.firstBuy);
        to = Math.max(to, f.lastSell);
      }
      summary = new StoreState.ImportedSummary(importedFlips.size(), items.size(), profit, from, to, new ArrayList<>(sources));
    }
    List<StoreState.ClosedPosition> closedPositions = new ArrayList<>();
    for (Map.Entry<String, FifoMatcher.Closed> e : closed.entrySet()) {
      Offer o = offers.get(e.getKey());
      closedPositions.add(new StoreState.ClosedPosition(e.getKey(), e.getValue().reason, e.getValue().at,
        o == null ? null : o.name, o == null ? null : o.itemId, o == null ? null : o.account));
    }
    return new StoreState(now, sessionViews, active, occupied, completed, manual, removed, auto, FifoMatcher.dataHealthOf(auto, puBuys),
      new ArrayList<>(personalUse), new ArrayList<>(puItemIds), new ArrayList<>(personalUseItems), new TreeMap<>(personalUseKept),
      new ArrayList<>(importedFlips), summary, closedPositions, linkedCount, unseen, netProfit, manual.size() + auto.flips.size());
  }

  private static double num(Long v) {
    return v == null ? Double.NaN : v;
  }

  /** How much of an item THIS account bought in the last four hours (see {@link BuyLimitUsage}). */
  public BuyLimitUsage buyLimitUsage(String account, int itemId, long now) {
    return BuyLimitUsage.of(offers.values(), account, itemId, now);
  }

  // ------------------------------------------------------------------------------------------ mutators
  //
  // Each takes the request body the bridge route takes, as a JSON object, because the JS checks are about
  // JSON types (typeof personal === 'boolean', closed defaulting only when ABSENT). Typed overloads exist
  // for the plugin's own buttons.

  /** "I don't have the rest of this purchase any more." Reversible with closed:false. */
  public void closePosition(JsonObject args, long now) {
    if (!Packet.id(args.get("buyId"))) throw new JournalException("Invalid buyId");
    String buyId = resolve(args.get("buyId").getAsString());
    JsonElement c = args.get("closed");
    if (c != null && !Js.isBoolean(c)) throw new JournalException("Missing closed flag");
    boolean close = c == null || c.getAsBoolean(); // the JS default applies only when the key is absent
    if (!close) {
      if (closed.containsKey(buyId)) append(new JournalRecord.PositionReopened(buyId));
      return;
    }
    String reason = Js.string(args.get("reason"));
    if (!"used".equals(reason) && !"sold-untracked".equals(reason)) throw new JournalException("Choose why this position is gone");
    if (closed.containsKey(buyId)) return;
    StoreState st;
    try {
      st = state(now);
    } catch (ArithmeticException e) {
      // JAVA ONLY: a journal whose GP totals are past what a long holds (2^63) cannot be answered exactly,
      // and state() refuses rather than wrap. The caller gets the journal's own refusal, never a crash.
      throw new JournalException(TOO_LARGE_TO_ANSWER);
    }
    boolean open = false;
    for (FifoMatcher.OpenPosition p : st.autoOpenPositions) open |= buyId.equals(p.buyId);
    if (!open) throw new JournalException("That purchase is not an open position.");
    append(new JournalRecord.PositionClosed(buyId, reason, now));
  }

  public void closePosition(String buyId, String reason, long now) {
    JsonObject a = new JsonObject();
    if (buyId != null) a.addProperty("buyId", buyId);
    if (reason != null) a.addProperty("reason", reason);
    closePosition(a, now);
  }

  /** Flags one observed, finished buy as bought for use, not to flip. */
  public void markPersonalUse(JsonObject args) {
    if (!Packet.id(args.get("buyId"))) throw new JournalException("Invalid buyId");
    if (!Js.isBoolean(args.get("personal"))) throw new JournalException("Missing personal flag");
    boolean personal = args.get("personal").getAsBoolean();
    String buyId = resolve(args.get("buyId").getAsString());
    Offer o = offers.get(buyId);
    // An ended-unseen buy counts as finished here: its filled units are an open lot, so the card's Personal use reaches it.
    if (o == null || !"buy".equals(o.side()) || !(o.finished() || endedUnseen.containsKey(buyId)) || !o.knownStart || !(o.filled > 0))
      throw new JournalException("Unknown or not-yet-observed buy");
    if (personal == personalUse.contains(buyId)) return;
    append(new JournalRecord.PersonalUse(!personal, buyId));
  }

  public void markPersonalUse(String buyId, boolean personal) {
    JsonObject a = new JsonObject();
    if (buyId != null) a.addProperty("buyId", buyId);
    a.addProperty("personal", personal);
    markPersonalUse(a);
  }

  /** The reply to an item-level mark: kept appears only when there is one (an exact shape test asserts it). */
  public static final class PersonalUseItemReply {
    public final int itemId;
    public final boolean personal;
    public final Long kept;

    PersonalUseItemReply(int itemId, boolean personal, Long kept) {
      this.itemId = itemId;
      this.personal = personal;
      this.kept = kept;
    }
  }

  /**
   * "This thing I own is not stock": keyed by item, for gear EVI never saw bought. kept is how many are
   * held for use, floored at 1 (marking an item not held must not switch the exclusion off).
   */
  public PersonalUseItemReply markPersonalUseItem(JsonObject args) {
    if (!Js.integer(args.get("itemId"), 1, Js.INT32_MAX)) throw new JournalException("Invalid itemId");
    if (!Js.isBoolean(args.get("personal"))) throw new JournalException("Missing personal flag");
    int itemId = (int) (double) Js.number(args.get("itemId"));
    boolean personal = args.get("personal").getAsBoolean();
    Double k = Js.number(args.get("kept"));
    Double keep = k != null && Js.isInteger(k) && k >= 0 ? Math.max(1, k) : null;
    boolean already = personalUseItems.contains(itemId);
    Long had = personalUseKept.get(itemId);
    boolean raises = personal && already && keep != null && keep > (had == null ? 0 : had);
    if (personal != already || raises) {
      if (personal) append(new JournalRecord.PersonalUseItem(itemId, keep));
      else append(new JournalRecord.PersonalUseItemUndo(itemId));
    }
    Long now = personalUseKept.get(itemId);
    return new PersonalUseItemReply(itemId, personal, personal ? now : null);
  }

  public PersonalUseItemReply markPersonalUseItem(int itemId, boolean personal, Long kept) {
    JsonObject a = new JsonObject();
    a.addProperty("itemId", itemId);
    a.addProperty("personal", personal);
    if (kept != null) a.addProperty("kept", kept);
    return markPersonalUseItem(a);
  }

  /** The Java-only refusal in closePosition when the journal's totals are past 2^63 (see there). */
  static final String TOO_LARGE_TO_ANSWER =
    "This journal's GP totals are past what EVI can count exactly, so it cannot tell which positions are open. Treat the journal as corrupted";

  /** The Java-only refusal in recordPurchase (see there). */
  static final String TOO_LARGE_TO_RECORD =
    "That purchase is too large to record: its total cost is past 9,007,199,254,740,991 GP, the most EVI can count exactly";

  /** recordPurchase's reply: {removed} | {recorded:0, offerId, duplicate:true} | {recorded:1, offerId, cost}. */
  public static final class RecordResult {
    public final Integer removed;
    public final Integer recorded;
    public final String offerId;
    public final Boolean duplicate;
    public final Long cost;

    RecordResult(Integer removed, Integer recorded, String offerId, Boolean duplicate, Long cost) {
      this.removed = removed;
      this.recorded = recorded;
      this.offerId = offerId;
      this.duplicate = duplicate;
      this.cost = cost;
    }
  }

  /**
   * A purchase EVI did not see, told to it afterwards: stored as exactly that (recorded:true), never
   * disguised as an observation, and nothing in it estimated. Undone with remove:true and its offerId.
   */
  public RecordResult recordPurchase(JsonObject a, long now) {
    if (a.has("remove") && Js.isBoolean(a.get("remove")) && a.get("remove").getAsBoolean()) {
      String offerId = Js.string(a.get("offerId"));
      if (offerId == null || !offerId.startsWith("recorded:")) throw new JournalException("Name the recorded purchase to remove");
      if (!offers.containsKey(offerId)) return new RecordResult(0, null, null, null, null);
      append(new JournalRecord.PurchaseRecordRemoved(offerId));
      return new RecordResult(1, null, null, null, null);
    }
    if (!Js.integer(a.get("itemId"), 1, Js.INT32_MAX)) throw new JournalException("A recorded purchase needs an item id");
    String name = Js.string(a.get("name"));
    if (name == null || name.isEmpty() || name.length() > 150) throw new JournalException("A recorded purchase needs the item name");
    if (!Js.integer(a.get("quantity"), 1, Js.INT32_MAX)) throw new JournalException("Quantity must be a whole number of at least one");
    if (!Js.integer(a.get("unitPrice"), 1, Js.INT32_MAX)) throw new JournalException("Price each must be a whole number of at least one gp");
    if (!Js.integer(a.get("at"), Tax.TAX_ERA_START_MS, now)) throw new JournalException("The purchase time must be in the past, and after 30 May 2025");
    int itemId = (int) (double) Js.number(a.get("itemId"));
    long quantity = (long) (double) Js.number(a.get("quantity"));
    long unitPrice = (long) (double) Js.number(a.get("unitPrice"));
    long at = (long) (double) Js.number(a.get("at"));
    // JAVA ONLY, and the one place this port refuses what the bridge accepts: a total cost past 2^53 - 1
    // (9,007,199,254,740,991 gp), which JS can no longer hold exactly and Java's running totals could
    // eventually carry past 2^63. Each factor is already capped at 2^31 - 1; a real Grand Exchange trade
    // is under 2.2e12 (max cash plus every platinum token), more than four thousand times below this.
    if (!Js.isSafe(Js.multiply(unitPrice, quantity))) throw new JournalException(TOO_LARGE_TO_RECORD);
    String given = Js.string(a.get("offerId"));
    String id = given != null && !given.isEmpty() && given.startsWith("recorded:") ? given
      : "recorded:" + itemId + ":" + at + ":" + unitPrice + ":" + quantity;
    if (offers.containsKey(id)) return new RecordResult(null, 0, id, Boolean.TRUE, null);
    String account = Js.string(a.get("account"));
    account = account != null && !account.isEmpty() ? (account.length() > 80 ? account.substring(0, 80) : account) : "recorded";
    append(new JournalRecord.PurchaseRecorded(id, itemId, name, quantity, unitPrice, at, account));
    return new RecordResult(null, 1, id, null, Js.multiply(unitPrice, quantity));
  }

  /** importFlips's reply: {removed, total} or {accepted, duplicates, total}. */
  public static final class ImportResult {
    public final Integer removed;
    public final Integer accepted;
    public final Integer duplicates;
    public final int total;

    ImportResult(Integer removed, Integer accepted, Integer duplicates, int total) {
      this.removed = removed;
      this.accepted = accepted;
      this.duplicates = duplicates;
      this.total = total;
    }
  }

  /**
   * Completed flips from another tracker: they feed ranking and NEVER the profit total. A re-import by
   * the same route is caught by fingerprint, by another route by content (item, account, quantity,
   * profit and both timestamps), and a file listing a trade twice by the batch set.
   */
  public ImportResult importFlips(JsonObject a) {
    String source = Js.string(a.get("source"));
    if (source == null || source.isEmpty() || source.length() > 40) throw new JournalException("Name the import source");
    if (a.has("remove") && Js.isBoolean(a.get("remove")) && a.get("remove").getAsBoolean()) {
      int removed = 0;
      for (ImportedFlip f : importedFlips) if (source.equals(f.source)) removed++;
      if (removed > 0) append(new JournalRecord.FlipsImportRemoved(source));
      return new ImportResult(removed, null, null, importedFlips.size());
    }
    JsonElement fe = a.get("flips");
    if (fe == null || !fe.isJsonArray() || fe.getAsJsonArray().size() == 0 || fe.getAsJsonArray().size() > 500)
      throw new JournalException("Import between 1 and 500 flips per request");
    JsonArray flipsIn = fe.getAsJsonArray();
    List<ImportedFlip> clean = new ArrayList<>();
    Set<String> batchContent = new HashSet<>();
    for (JsonElement e : flipsIn) {
      JsonObject f = e != null && e.isJsonObject() ? e.getAsJsonObject() : null;
      String fp = f == null ? null : Js.string(f.get("fp"));
      if (fp == null || fp.isEmpty() || fp.length() > 300) throw new JournalException("Every imported flip needs a fingerprint");
      String item = Js.string(f.get("item"));
      if (!Js.integer(f.get("itemId"), 1, Js.INT32_MAX) || item == null || item.isEmpty() || item.length() > 150)
        throw new JournalException("Every imported flip needs a resolved itemId and name");
      Double profitD = Js.number(f.get("profit"));
      if (!Js.integer(f.get("quantity"), 1, Js.INT32_MAX) || profitD == null || !Js.isSafeInteger(profitD) || !Js.integer(f.get("capital")))
        throw new JournalException("Invalid quantity, capital or profit");
      if (!Js.integer(f.get("firstBuy"), 1, Js.MAX_SAFE) || !Js.integer(f.get("lastSell"), 1, Js.MAX_SAFE))
        throw new JournalException("Invalid trade timestamps");
      long capital = (long) (double) Js.number(f.get("capital"));
      long profit = (long) (double) profitD;
      if (importedFingerprints.contains(fp)) continue; // already imported through this same route
      long firstBuy = (long) (double) Js.number(f.get("firstBuy"));
      long lastSell = (long) (double) Js.number(f.get("lastSell"));
      String account = Js.string(f.get("account"));
      if (account != null && account.length() > 80) account = account.substring(0, 80);
      ImportedFlip row = new ImportedFlip(fp, source, (int) (double) Js.number(f.get("itemId")), item,
        (long) (double) Js.number(f.get("quantity")), capital, capital + profit, profit, firstBuy, lastSell,
        (double) (lastSell - firstBuy) / 3600000, account);
      String content = row.contentKey();
      if (importedContent.contains(content) || batchContent.contains(content)) continue;
      // JAVA ONLY (as in recordPurchase): the row's netProceeds, capital + profit, must itself be a safe
      // integer. JS accepts a profit up to 2^53 - 1 on top of a capital up to 2^31 - 1 and journals the
      // ROUNDED sum; this port refuses the row instead, with the bridge's own message for a bad figure,
      // so no line it writes can differ from the bridge's. Both inputs are safe, so the sum cannot overflow.
      // Checked only AFTER both duplicate skips, so a row JS would skip as already held is skipped here too
      // rather than refused (the import-unsafe-duplicate journal vectors pin that order).
      if (!Js.isSafe(capital + profit)) throw new JournalException("Invalid quantity, capital or profit");
      batchContent.add(content);
      clean.add(row);
    }
    if (!clean.isEmpty()) append(new JournalRecord.FlipsImported(clean));
    return new ImportResult(null, clean.size(), flipsIn.size() - clean.size(), importedFlips.size());
  }

  /**
   * Manual review: match a finished buy to the later finished sales of the same account and item. Proceeds
   * are the exact tax calculation unless the sales filled at mixed prices, when the player must state
   * them. newId stands in for randomUUID so a test can pin it.
   */
  public ManualFlip confirm(JsonObject a, long now, Supplier<String> newId) {
    JsonElement sellIdsEl = a.get("sellIds");
    List<JsonElement> ids = new ArrayList<>();
    boolean isArray;
    if (sellIdsEl == null || sellIdsEl.isJsonNull()) {
      isArray = true;
      ids.add(a.get("sellId"));
    } else {
      isArray = sellIdsEl.isJsonArray();
      if (isArray) for (JsonElement e : sellIdsEl.getAsJsonArray()) ids.add(e);
    }
    Set<String> distinct = new HashSet<>();
    boolean bad = !isArray || ids.isEmpty() || ids.size() > 100;
    for (JsonElement e : ids) {
      if (bad) break;
      bad = !Packet.id(e);
      if (!bad) distinct.add(e.getAsString());
    }
    if (bad || distinct.size() != ids.size()) throw new JournalException("Choose distinct completed sales");
    String buyId = resolve(Js.string(a.get("buyId")));
    if (personalUse.contains(buyId))
      throw new JournalException("That purchase is marked as personal use, so it is not a flip. Unmark it first if it really was one.");
    List<String> sorted = new ArrayList<>();
    for (JsonElement e : ids) sorted.add(resolve(e.getAsString()));
    Collections.sort(sorted); // String order is UTF-16 code unit order, as Array.prototype.sort's default
    if (new HashSet<>(sorted).size() != sorted.size()) throw new JournalException("Choose distinct completed sales");
    for (ManualFlip f : flips) {
      if (f.isReopened() || !Objects.equals(f.buyId, buyId)) continue;
      List<String> theirs = new ArrayList<>(f.sellIdsOrSingle());
      theirs.sort(Store::jsDefaultCompare);
      if (!theirs.equals(sorted)) continue;
      if (f.isRemoved()) throw new JournalException("This flip was removed. Restore it before reusing this match.");
      return f;
    }
    Offer b = buyId == null ? null : offers.get(buyId);
    List<Offer> sales = new ArrayList<>();
    for (String id : sorted) sales.add(offers.get(id));
    for (Offer s : sales) {
      if (s == null || b == null || !"sell".equals(s.side()) || !s.finished() || s.filled < 1 || !Objects.equals(s.account, b.account)
        || s.itemId != b.itemId || lessJs(s.firstSeen, b.completedAt))
        throw new JournalException("Choose later completed sales for the same account/item");
    }
    long filledSum = 0, firstSeen = Long.MAX_VALUE, completedAt = Long.MIN_VALUE;
    for (Offer s : sales) {
      filledSum = Js.add(filledSum, s.filled);
      firstSeen = Math.min(firstSeen, s.firstSeen);
      completedAt = Math.max(completedAt, s.completedAt);
    }
    Offer s0 = sales.get(0);
    if (!"buy".equals(b.side()) || !"sell".equals(s0.side()) || !b.finished() || !Offer.finished(s0.state, s0.total, filledSum)
      || !Objects.equals(b.account, s0.account) || b.itemId != s0.itemId || b.filled < 1 || b.filled != filledSum
      || lessJs(firstSeen, b.completedAt) || b.spent < 1)
      throw new JournalException(b.filled != filledSum
        ? "The selected sales total " + Js.groupedUs(filledSum) + " items but the purchase was " + Js.groupedUs(b.filled)
          + ". Select every sale of this purchase, or, if the rest was used or sold outside EVI, close it under \"Still held\" instead -- the part you sold still counts."
        : "Select a completed buy and later completed sales of the same item on the same account");
    for (ManualFlip f : flips) {
      if (f.isReopened()) continue;
      boolean overlap = Objects.equals(f.buyId, buyId);
      for (String x : f.sellIdsOrSingle()) overlap |= sorted.contains(x);
      if (overlap) throw new JournalException("An offer is already matched");
    }
    boolean automatic = !a.has("netProceeds");
    double netProceeds;
    if (automatic) {
      long net = 0;
      for (Offer s : sales) {
        Tax.Proceeds pr = Tax.saleProceeds(s);
        if (pr == null || !pr.exact) throw new JournalException("Execution prices are mixed or historical; review actual net proceeds");
        net = Js.add(net, pr.net);
      }
      netProceeds = net;
    } else {
      Double given = Js.number(a.get("netProceeds"));
      netProceeds = given == null ? Double.NaN : given;
    }
    long maximum = 0;
    for (Offer s : sales) maximum = Js.add(maximum, s.spent);
    if (!Js.isSafeInteger(maximum)) throw new JournalException("The selected sales have invalid GP counters.");
    if (!(Js.isSafeInteger(netProceeds) && netProceeds >= 1))
      throw new JournalException("Net proceeds must be a whole GP amount greater than zero. Leave it blank for automatic tax calculation.");
    long net = (long) netProceeds;
    if (net > maximum)
      throw new JournalException("Net proceeds of " + Js.groupedUs(net) + " GP is more than the GE reported for the selected sale(s): "
        + Js.groupedUs(maximum) + " GP before tax. Enter what you received after tax for exactly these sales (not the profit, and not including other sales).");
    ManualFlip flip = new ManualFlip(newId.get(), buyId, sorted.size() == 1 ? sorted.get(0) : null, Collections.unmodifiableList(sorted),
      b.account, b.itemId, b.name, b.filled, b.spent, net, Js.subtract(net, b.spent), b.firstSeen, completedAt,
      (double) (completedAt - b.firstSeen) / 3600000, now, "runelite-reviewed", automatic ? "calculated-tax" : "user-reviewed");
    append(new JournalRecord.FlipRecord(flip));
    return flip;
  }

  // a < b as JS compares a number with a value that may be null (null is 0 there).
  private static boolean lessJs(Long a, Long b) {
    return (a == null ? 0 : a) < (b == null ? 0 : b);
  }

  // Array.prototype.sort's default comparator for strings (a null sorts as the string "null", as JS does).
  private static int jsDefaultCompare(String a, String b) {
    return String.valueOf(a).compareTo(String.valueOf(b));
  }

  public void setRemoved(JsonObject a) {
    String id = Js.string(a.get("id"));
    ManualFlip f = findFlip(id);
    if (!Js.isBoolean(a.get("removed")) || f == null) throw new JournalException("Unknown flip");
    if (f.isReopened()) throw new JournalException("This version was reopened for correction. Save a new reviewed match instead.");
    append(new JournalRecord.FlipMark(a.get("removed").getAsBoolean() ? JournalRecord.FlipMark.REMOVED : JournalRecord.FlipMark.RESTORED, id));
  }

  public void reopen(JsonObject a) {
    String id = Js.string(a.get("id"));
    ManualFlip f = findFlip(id);
    if (f == null) throw new JournalException("Unknown flip");
    if (!f.isReopened()) append(new JournalRecord.FlipMark(JournalRecord.FlipMark.REOPENED, id));
  }

  private ManualFlip findFlip(String id) {
    for (ManualFlip f : flips) if (Objects.equals(f.id, id)) return f;
    return null;
  }
}

package com.evi.live.journal;

import java.util.Collections;
import java.util.List;
import java.util.SortedMap;

/**
 * Everything store.mjs's {@code state(now)} returns, field for field (the bridge serves it as
 * {@code GET /api/state}). Built fresh on every call; FIFO is recomputed each time, as in JS.
 *
 * <p>MACHINE-WIDE BY DESIGN, like the JS: it lists every account's offers, flips and positions, and
 * {@link #netProfit} sums all of them (the maintainer's 26 Sept decision about the profit line). Anything that
 * speaks for ONE account must filter by account itself, by equality, with a non-null account -- never
 * the {@code !account || x.account === account} shape that leaked one account's holdings to another on 6 Oct.
 */
public final class StoreState {
  public final int version = 1;
  public final long serverTime;
  public final List<SessionView> sessions;
  /** Offers in a live, logged-in session's slots that are not finished. */
  public final List<Offer> active;
  /** Offers in a live, logged-in session's slots, finished-but-uncollected included. */
  public final List<Offer> occupied;
  /** Finished offers (empty cancels left out), newest update first. */
  public final List<CompletedOffer> completed;
  public final List<ManualFlip> flips;
  public final List<ManualFlip> removedFlips;
  public final List<FifoMatcher.AutoFlip> autoFlips;
  public final List<FifoMatcher.OpenPosition> autoOpenPositions;
  public final List<FifoMatcher.UnmatchedSell> autoUnmatchedSells;
  public final FifoMatcher.DataHealth dataHealth;
  public final List<String> personalUseBuyIds;
  public final List<Integer> personalUseItemIds;
  public final List<Integer> personalUseItems;
  /** Item id to kept count. Sorted ascending, because a JS object with integer keys iterates that way. */
  public final SortedMap<Integer, Long> personalUseKept;
  public final List<ImportedFlip> importedFlips;
  /** Null when nothing was imported. */
  public final ImportedSummary importedSummary;
  public final List<ClosedPosition> closedPositions;
  public final int linkedLoginOffers;
  /** Offers that ended while EVI was not watching (store.mjs {@code endedUnseen}), in the order they were found gone. */
  public final List<EndedUnseenOffer> endedUnseen;
  public final long netProfit;
  public final int tradeCount;

  StoreState(long serverTime, List<SessionView> sessions, List<Offer> active, List<Offer> occupied, List<CompletedOffer> completed,
             List<ManualFlip> flips, List<ManualFlip> removedFlips, FifoMatcher.Result auto, FifoMatcher.DataHealth dataHealth,
             List<String> personalUseBuyIds, List<Integer> personalUseItemIds, List<Integer> personalUseItems,
             SortedMap<Integer, Long> personalUseKept, List<ImportedFlip> importedFlips, ImportedSummary importedSummary,
             List<ClosedPosition> closedPositions, int linkedLoginOffers, List<EndedUnseenOffer> endedUnseen, long netProfit, int tradeCount) {
    this.serverTime = serverTime;
    this.sessions = Collections.unmodifiableList(sessions);
    this.active = Collections.unmodifiableList(active);
    this.occupied = Collections.unmodifiableList(occupied);
    this.completed = Collections.unmodifiableList(completed);
    this.flips = Collections.unmodifiableList(flips);
    this.removedFlips = Collections.unmodifiableList(removedFlips);
    this.autoFlips = auto.flips;
    this.autoOpenPositions = auto.openPositions;
    this.autoUnmatchedSells = auto.unmatchedSells;
    this.dataHealth = dataHealth;
    this.personalUseBuyIds = Collections.unmodifiableList(personalUseBuyIds);
    this.personalUseItemIds = Collections.unmodifiableList(personalUseItemIds);
    this.personalUseItems = Collections.unmodifiableList(personalUseItems);
    this.personalUseKept = Collections.unmodifiableSortedMap(personalUseKept);
    this.importedFlips = Collections.unmodifiableList(importedFlips);
    this.importedSummary = importedSummary;
    this.closedPositions = Collections.unmodifiableList(closedPositions);
    this.linkedLoginOffers = linkedLoginOffers;
    this.endedUnseen = Collections.unmodifiableList(endedUnseen);
    this.netProfit = netProfit;
    this.tradeCount = tradeCount;
  }

  /** A client session: {id, account, seq, lastSeen, loggedIn, slots, capturedAt?, live}. */
  public static final class SessionView {
    public final String id;
    public final String account;
    public final long seq;
    public final long lastSeen;
    public final boolean loggedIn;
    /** The packet's offerIds as sent (not resolved through aliases), EMPTY slots included. */
    public final List<String> slots;
    /** Null after a bridge restart until the session's next packet: a replayed session was never captured live. */
    public final Long capturedAt;
    public final boolean live;

    SessionView(String id, Store.Session s, boolean live) {
      this.id = id;
      this.account = s.account;
      this.seq = s.seq;
      this.lastSeen = s.lastSeen;
      this.loggedIn = s.loggedIn;
      this.slots = s.slots;
      this.capturedAt = s.capturedAt;
      this.live = live;
    }
  }

  /** A finished offer as listed: the offer, its exact sale proceeds (sells only) and whether it was a probe. */
  public static final class CompletedOffer {
    public final Offer offer;
    /** Null for a buy, and for a sale with no usable tax calculation. */
    public final Tax.Proceeds proceeds;
    public final boolean marginCheck;

    CompletedOffer(Offer offer, Tax.Proceeds proceeds, boolean marginCheck) {
      this.offer = offer;
      this.proceeds = proceeds;
      this.marginCheck = marginCheck;
    }
  }

  public static final class ImportedSummary {
    public final int count;
    public final int items;
    public final long profit;
    public final long from;
    public final long to;
    public final List<String> sources;

    ImportedSummary(int count, int items, long profit, long from, long to, List<String> sources) {
      this.count = count;
      this.items = items;
      this.profit = profit;
      this.from = from;
      this.to = to;
      this.sources = Collections.unmodifiableList(sources);
    }
  }

  /** {offerId, at}: an offer found gone at its account's next login, and that packet's ts. */
  public static final class EndedUnseenOffer {
    public final String offerId;
    public final long at;

    EndedUnseenOffer(String offerId, long at) {
      this.offerId = offerId;
      this.at = at;
    }
  }

  /** A closed position, with the buy's name, item and account when the buy is still known (null otherwise). */
  public static final class ClosedPosition {
    public final String buyId;
    public final String reason;
    public final long at;
    public final String item;
    public final Integer itemId;
    public final String account;

    ClosedPosition(String buyId, String reason, long at, String item, Integer itemId, String account) {
      this.buyId = buyId;
      this.reason = reason;
      this.at = at;
      this.item = item;
      this.itemId = itemId;
      this.account = account;
    }
  }
}

package com.evi.live.journal;

import java.util.Set;

/**
 * The Grand Exchange tax, ported from bridge/tax.mjs (and {@code breakEvenSellPrice} from
 * bridge/suggestions.mjs). Pure.
 *
 * <p>The rules, each one checked against the JS engine by JournalVectorsTest:
 * <ul>
 *   <li>2% of the sale price, ROUNDED DOWN per unit: {@code floor(price / 50)}. So anything under 50 gp
 *       pays nothing (the under-50 rule falls out of the floor, it is not a separate branch).</li>
 *   <li>Capped at {@link #CAP} (5,000,000) a unit, which binds from 250,000,000 gp up.</li>
 *   <li>An exempt set of item ids pays nothing at all (cross-checked by the bridge against Flipping
 *       Utilities' Hub-pinned source; policy date 2025-05-29).</li>
 *   <li>A completed sale first seen before {@link #TAX_ERA_START_MS} (30 May 2025) is never
 *       reinterpreted: {@link #saleProceeds} returns null.</li>
 * </ul>
 *
 * <p>Every price and every total is a {@code long}. Where the JS engine works in doubles (a per-unit
 * average, a break-even search) this does the same double arithmetic in the same order, so the answer is
 * the same number. Integer GP arithmetic goes through {@link Js#add} and friends, which are exact below
 * 2^53 and round exactly as JS does above it, so the two agree to the last digit everywhere a long can hold.
 */
public final class Tax {
  private Tax() {}

  /** The per-unit cap, in gp. */
  public static final long CAP = 5_000_000L;
  /** Date.UTC(2025, 4, 30): the start of the tax regime this engine can reason about. */
  public static final long TAX_ERA_START_MS = 1748563200000L;

  private static final Set<Integer> EXEMPT = Set.of(1755, 5325, 2347, 1733, 13190, 233, 5341, 8794, 5329, 5343, 1735,
    952, 5331, 8011, 365, 2309, 882, 806, 1891, 8010, 28824, 2140, 2142, 3008, 3010, 3012, 3014, 8009, 3853, 347, 884,
    807, 28790, 379, 8008, 355, 2327, 558, 351, 2552, 329, 315, 886, 808, 8013, 361, 8007);

  public static boolean isExempt(int itemId) {
    return EXEMPT.contains(itemId);
  }

  /**
   * Estimated per-unit tax for a hypothetical future sale. Zero for an exempt item, and zero (not a
   * guess) for a price that is not a positive finite number.
   */
  public static long estimateUnitTax(int itemId, double sellPrice) {
    if (EXEMPT.contains(itemId)) return 0;
    if (Double.isNaN(sellPrice) || Double.isInfinite(sellPrice) || sellPrice <= 0) return 0;
    return (long) Math.min((double) CAP, Math.floor(sellPrice / 50));
  }

  /** What a completed sale actually paid: tax.mjs's {net, tax, exact}. */
  public static final class Proceeds {
    public final long net;
    public final long tax;
    /** False when the sale filled at several prices: the aggregate counter cannot say how each unit rounded. */
    public final boolean exact;

    Proceeds(long net, long tax, boolean exact) {
      this.net = net;
      this.tax = tax;
      this.exact = exact;
    }
  }

  /**
   * The exact tax on a completed sale. Null when the counters are unusable (nothing filled, a negative
   * spend) or the offer predates the tax regime; never an estimate dressed as a fact.
   */
  public static Proceeds saleProceeds(Offer o) {
    long q = o.filled, gross = o.spent;
    if (!Js.isSafeInteger(q) || q < 1 || !Js.isSafeInteger(gross) || gross < 0) return null;
    // An absent firstSeen is NOT before the era in JS (undefined < x is false), so it is taxed.
    if (o.firstSeen != null && o.firstSeen < TAX_ERA_START_MS) return null;
    if (EXEMPT.contains(o.itemId)) return new Proceeds(gross, 0, true);
    double unit = (double) gross / q;
    boolean exact = q == 1 || gross == Js.multiply(o.price, q);
    long tax = Js.multiply((long) Math.min((double) CAP, Math.floor(unit / 50)), q);
    return new Proceeds(Js.subtract(gross, tax), tax, exact);
  }

  /**
   * The lowest whole sell price that still returns the unit cost after tax, or null when the cost is not
   * a positive finite number (never a guessed cost). suggestions.mjs's search, step for step.
   */
  public static Long breakEvenSellPrice(int itemId, double unitCost) {
    if (Double.isNaN(unitCost) || Double.isInfinite(unitCost) || unitCost <= 0) return null;
    long p = (long) Math.ceil(unitCost);
    if (clears(itemId, p, unitCost)) return p; // tax-exempt, or too cheap to be taxed
    p = (long) Math.min(Math.ceil(unitCost * 50 / 49), Math.ceil(unitCost) + (double) CAP);
    for (int i = 0; i < 1000 && !clears(itemId, p, unitCost); i++) p++;
    for (int i = 0; i < 1000 && p > 1 && clears(itemId, p - 1, unitCost); i++) p--;
    return clears(itemId, p, unitCost) ? p : null;
  }

  private static boolean clears(int itemId, long p, double unitCost) {
    return (double) (p - estimateUnitTax(itemId, p)) >= unitCost;
  }
}

package com.evi.live.journal;

import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * The trade log a player can save and send by hand (9 Oct 2026, the maintainer's decision: VOLUNTARY sharing, option 2 of the
 * SELF-CONTAINED-PLAN bullet of that day). PURE: it turns what the journal already holds into CSV bytes and touches no file, no
 * thread and no network; {@link PluginJournal#exportTradeLog} writes them, on the journal thread.
 *
 * <p>WHAT IT CARRIES, and nothing else: every Grand Exchange offer EVI saw, from EVERY account's journal on this machine (item,
 * side, price, quantity, filled, its last state, cancelled, ended-unseen, when EVI first saw it and whether that was its start,
 * the tick reading, last seen, completed) -- with EVI's suggested price for that item and side when the offer can be linked to a
 * suggestion EVI showed, and how it was linked ({@link Link}; 9 Oct 2026, approved by the maintainer) -- plus every finished flip the profit line counts ({@code state.flips} -- reviewed,
 * removed ones left out -- and {@code state.autoFlips}, the FIFO matches; the same set as {@code tradeCount}) with its cost,
 * proceeds after tax and profit or loss. Imported flips are NOT included: they came from another tracker, EVI never saw them,
 * and the profit line leaves them out for the same reason. A purchase the player only TOLD EVI about ({@code recorded}) is not
 * an offer EVI saw and is left out too; a flip that used one keeps an empty {@code buy_ref}.
 *
 * <p>WHAT IT NEVER CARRIES: the account id, a character name, the session, the GE slot, cash, bank, inventory or any path, and
 * nothing from a suggestion record but its price and the link type (no suggestion id, account, cash, minimum profit or setting). Offer
 * ids are replaced by {@code ref}, a number that exists only in this file (so a flip can name the offers it matched); rows are
 * sorted by time, not by account, so the order does not group one account's trades either.
 *
 * <p>The 3 Oct 2026 CSV rules (the scanner's trade-log export): a UTF-8 BOM, {@code sep=,} as the first line (Excel on a
 * locale whose list separator is ';' would otherwise put every line in column A), COMMAS always -- never semicolons, which repair
 * one locale and break every other -- and RFC 4180 quoting for a field holding a comma, a quote or a line break. Times are
 * ISO-8601 UTC to the millisecond, exactly as recorded: the fill model needs them, and they must line up with the Wiki's series.
 */
public final class TradeLogExport {
  private TradeLogExport() {}

  /** The folder, inside the plugin's data folder, the file is saved in. */
  public static final String SHARE_DIR = "share";
  /** One table: an {@code offer} row leaves the flip columns empty and a {@code flip} row the offer columns. */
  public static final String HEADER = "record,ref,item_id,item_name,side,state,price,evi_price,evi_link,quantity,filled,cancelled,ended_unseen,known_start,"
    + "ticks_to_fill,first_seen_utc,last_seen_utc,completed_utc,matched,buy_ref,sell_refs,cost,proceeds,profit,first_buy_utc,last_sell_utc";
  static final int COLUMNS = HEADER.split(",", -1).length;
  static final String EOL = "\r\n";
  private static final byte[] BOM = {(byte) 0xEF, (byte) 0xBB, (byte) 0xBF};
  private static final DateTimeFormatter UTC = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'", Locale.US).withZone(ZoneOffset.UTC);

  /** The file's name for a (local) day: a second save on the same day replaces that day's file. */
  public static String fileName(LocalDate day) {
    return "evi-trade-log-" + day + ".csv";
  }

  /** The file's bytes and what it counted. */
  public static final class Csv {
    public final byte[] bytes;
    public final int offers;
    public final int flips;

    Csv(byte[] bytes, int offers, int flips) {
      this.bytes = bytes;
      this.offers = offers;
      this.flips = flips;
    }
  }

  /**
   * EVI's own suggestion behind one offer, by offer id: the suggested price for that side and how the offer was linked to it --
   * {@code observed}, {@code matched} or {@code inferred}, the suggestion-outcome join's three attributions, never pooled
   * (inprocess.SuggestionOutcomes, the port of bridge/suggestionOutcomes.mjs, decides them; nothing here infers a link). An offer
   * with no link leaves both columns empty. Nothing else from the suggestion record reaches the file.
   */
  public static final class Link {
    /** {@code observed}, {@code matched} or {@code inferred}. */
    final String type;
    /** The suggested price as recorded, or null when the record holds none. */
    final String price;

    public Link(String type, Long price) {
      if (!"observed".equals(type) && !"matched".equals(type) && !"inferred".equals(type))
        throw new IllegalArgumentException("not a link type: " + type);
      this.type = type;
      this.price = price == null ? null : String.valueOf(price);
    }
  }

  /** One finished flip as the file shows it: either kind of match, reduced to the fields both carry. */
  static final class Flip {
    final String matched;
    final int itemId;
    final String item;
    final long quantity;
    final long cost;
    final long proceeds;
    final long profit;
    final Long firstBuy;
    final Long lastSell;
    final String buyId;
    final List<String> sellIds;

    Flip(String matched, int itemId, String item, long quantity, long cost, long proceeds, long profit, Long firstBuy, Long lastSell,
         String buyId, List<String> sellIds) {
      this.matched = matched;
      this.itemId = itemId;
      this.item = item;
      this.quantity = quantity;
      this.cost = cost;
      this.proceeds = proceeds;
      this.profit = profit;
      this.firstBuy = firstBuy;
      this.lastSell = lastSell;
      this.buyId = buyId;
      this.sellIds = sellIds == null ? Collections.emptyList() : sellIds;
    }

    static Flip of(ManualFlip f) {
      return new Flip("reviewed", f.itemId, f.item, f.quantity, f.capital, f.netProceeds, f.profit, f.firstBuy, f.lastSell, f.buyId,
        f.sellIdsOrSingle());
    }

    static Flip of(FifoMatcher.AutoFlip f) {
      return new Flip("auto", f.itemId, f.item, f.quantity, f.capital, f.netProceeds, f.profit, f.firstBuy, f.lastSell, f.buyId, f.sellIds);
    }
  }

  /** The file for one journal moment: {@code offers} is the store's every offer ({@code Store.offers()}), {@code state} its state. */
  public static Csv of(StoreState state, Collection<Offer> offers, Map<String, Link> links) {
    Set<String> unseen = new HashSet<>();
    for (StoreState.EndedUnseenOffer u : state.endedUnseen) unseen.add(u.offerId);
    List<Flip> flips = new ArrayList<>();
    for (ManualFlip f : state.flips) flips.add(Flip.of(f));
    for (FifoMatcher.AutoFlip f : state.autoFlips) flips.add(Flip.of(f));
    return build(offers, unseen, flips, links);
  }

  static Csv build(Collection<Offer> all, Set<String> endedUnseen, List<Flip> allFlips, Map<String, Link> links) {
    List<Offer> offers = new ArrayList<>();
    for (Offer o : all) if (seen(o)) offers.add(o);
    offers.sort(Comparator.comparing((Offer o) -> o.firstSeen, Comparator.nullsLast(Comparator.naturalOrder()))
      .thenComparing(o -> o.updated, Comparator.nullsLast(Comparator.naturalOrder()))
      .thenComparingInt(o -> o.itemId));
    List<Flip> flips = new ArrayList<>(allFlips);
    flips.sort(Comparator.comparing((Flip f) -> f.lastSell, Comparator.nullsLast(Comparator.naturalOrder()))
      .thenComparing(f -> f.firstBuy, Comparator.nullsLast(Comparator.naturalOrder()))
      .thenComparingInt(f -> f.itemId));

    StringBuilder sb = new StringBuilder(256 + 160 * (offers.size() + flips.size()));
    sb.append("sep=,").append(EOL).append(HEADER).append(EOL);
    Map<String, Integer> refs = new HashMap<>();
    int ref = 0;
    for (Offer o : offers) {
      refs.put(o.offerId, ++ref);
      String[] row = new String[COLUMNS];
      row[0] = "offer";
      row[1] = String.valueOf(ref);
      row[2] = String.valueOf(o.itemId);
      row[3] = o.name;
      row[4] = o.side();
      row[5] = o.state;
      row[6] = String.valueOf(o.price);
      Link link = links == null ? null : links.get(o.offerId);
      if (link != null) {
        row[7] = link.price;
        row[8] = link.type;
      }
      row[9] = String.valueOf(o.total);
      row[10] = String.valueOf(o.filled);
      row[11] = yesNo(o.state.startsWith("CANCELLED"));
      row[12] = yesNo(endedUnseen.contains(o.offerId));
      row[13] = yesNo(o.knownStart);
      row[14] = o.ticksToFill == null ? null : String.valueOf(o.ticksToFill);
      row[15] = time(o.firstSeen);
      row[16] = time(o.updated);
      row[17] = time(o.completedAt);
      line(sb, row);
    }
    for (Flip f : flips) {
      String[] row = new String[COLUMNS];
      row[0] = "flip";
      row[1] = String.valueOf(++ref);
      row[2] = String.valueOf(f.itemId);
      row[3] = f.item;
      row[9] = String.valueOf(f.quantity);
      row[18] = f.matched;
      Integer buy = f.buyId == null ? null : refs.get(f.buyId);
      row[19] = buy == null ? null : String.valueOf(buy);
      StringBuilder sells = new StringBuilder();
      for (String id : f.sellIds) {
        Integer s = id == null ? null : refs.get(id);
        if (s == null) continue;
        if (sells.length() > 0) sells.append(' ');
        sells.append(s);
      }
      row[20] = sells.toString();
      row[21] = String.valueOf(f.cost);
      row[22] = String.valueOf(f.proceeds);
      row[23] = String.valueOf(f.profit);
      row[24] = time(f.firstBuy);
      row[25] = time(f.lastSell);
      line(sb, row);
    }
    byte[] text = sb.toString().getBytes(StandardCharsets.UTF_8);
    byte[] out = new byte[BOM.length + text.length];
    System.arraycopy(BOM, 0, out, 0, BOM.length);
    System.arraycopy(text, 0, out, BOM.length, text.length);
    return new Csv(out, offers.size(), flips.size());
  }

  /** An offer EVI watched: not a purchase the player only told it about, and not an empty slot. */
  /** Yes/no rather than true/false: the file is read by players in a spreadsheet, not parsed by EVI. */
  static String yesNo(boolean b) {
    return b ? "yes" : "no";
  }

  static boolean seen(Offer o) {
    return o != null && !Boolean.TRUE.equals(o.recorded) && o.itemId > 0 && o.state != null && !"EMPTY".equals(o.state);
  }

  /** ISO-8601 UTC to the millisecond, or empty when the journal holds no time. */
  static String time(Long epochMs) {
    return epochMs == null ? null : UTC.format(Instant.ofEpochMilli(epochMs));
  }

  private static void line(StringBuilder sb, String[] row) {
    for (int i = 0; i < row.length; i++) {
      if (i > 0) sb.append(',');
      sb.append(field(row[i]));
    }
    sb.append(EOL);
  }

  /** RFC 4180: a field holding a comma, a double quote or a line break is quoted, its quotes doubled. Null is empty. */
  static String field(String value) {
    if (value == null) return "";
    boolean quote = false;
    for (int i = 0; i < value.length() && !quote; i++) {
      char c = value.charAt(i);
      quote = c == ',' || c == '"' || c == '\n' || c == '\r';
    }
    return quote ? '"' + value.replace("\"", "\"\"") + '"' : value;
  }
}

package com.evi.live.market;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.StandardOpenOption;
import java.util.UUID;
import java.util.function.Consumer;
import java.util.function.ToLongFunction;
import net.runelite.client.util.Filepath;

/**
 * Creating a price-data file complete or not at all, safely with TWO RuneLite clients (two processes) sharing one
 * plugin-data folder. The rule is the journal's ({@code JournalFile.writeNew}, Phase 1), with one difference.
 *
 * <p>THE RULE: write the whole content to a temporary file in the same folder, force it to disk, then RENAME it into
 * place, and NEVER over an existing file: when the target exists the rename fails and changes nothing, and this
 * reports it (returns false). A replace is avoided on purpose -- on Windows a move over a file fails with AccessDenied whenever
 * any other process has that file open, which is exactly what the other client's read does (the Phase 1 lesson). So
 * no {@code REPLACE_EXISTING}, and no {@code ATOMIC_MOVE} (on Windows that one REPLACES). A plain rename in one folder
 * is atomic: a reader sees no file or the whole file, never part of one.
 *
 * <p>THE DIFFERENCE: the temporary name is UNIQUE PER WRITE ({@code <target>.<uuid>.tmp}). The journal's shared
 * {@code <target>.tmp} is safe there because one account's file has one writer; here both clients routinely fetch
 * the SAME hour at the same moment, and with a shared temporary name one client's clean-up could delete -- or its
 * rename could publish -- the other's half-written file. With unique names each writer only ever touches its own.
 */
final class ArchiveFiles {
  private ArchiveFiles() {}

  static final String TMP_SUFFIX = ".tmp";

  /** TEST SEAM: told the target just before writeNew() renames its finished temporary file into place. Null in production. */
  static volatile Consumer<Filepath> moveSeam;

  /**
   * TEST SEAM: answers a file's modified time (epoch ms) in place of the file system, so a test can show an old temporary
   * file without setting a real file's time (which Filepath, the only file API the tests use, cannot do). Null in production.
   */
  static volatile ToLongFunction<Filepath> modifiedSeam;

  /** {@code f}'s modified time in epoch ms: the file system's, or the test seam's when one is set. */
  static long modifiedMs(Filepath f) throws IOException {
    ToLongFunction<Filepath> seam = modifiedSeam;
    return seam != null ? seam.applyAsLong(f) : f.getLastModifiedTime().toMillis();
  }

  /** True when the content landed; false when the target already existed (another writer won, or it was there before). */
  static boolean writeNew(Filepath target, byte[] content) throws IOException {
    if (target.exists()) return false;
    Filepath tmp = target.getParent().joinSegment(target.getFileName() + "." + UUID.randomUUID() + TMP_SUFFIX);
    try {
      try (FileChannel ch = tmp.openFileChannel(StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
        ByteBuffer buf = ByteBuffer.wrap(content);
        while (buf.hasRemaining()) ch.write(buf);
        ch.force(true);
      }
      Consumer<Filepath> seam = moveSeam;
      if (seam != null) seam.accept(target);
      try {
        tmp.moveTo(target); // no REPLACE_EXISTING, no ATOMIC_MOVE: an existing target fails the move
        return true;
      } catch (IOException e) {
        if (target.exists()) return false; // created by someone else meanwhile: theirs stands, untouched
        throw e;
      }
    } finally {
      tmp.deleteIfExists(); // only ever this write's own temporary file
    }
  }
}

package com.evi.live.market;

import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.IOException;
import java.io.Reader;
import java.io.StringReader;
import java.util.Arrays;
import java.util.Map;
import java.util.TreeMap;

/**
 * One hour of the OSRS Wiki's all-items price averages: the bridge's archive bucket
 * {@code {ts, d:{itemId:[avgHighPrice, highPriceVolume, avgLowPrice, lowPriceVolume]}}} (priceArchive.mjs
 * compactBucket), held as primitive arrays sorted by item id.
 *
 * <p>THE BASIS IS v1, i.e. INTEGERS. The Wiki's v2 averages carry up to two decimals, and v1 is exactly
 * {@code Math.round(v2)} (measured on 8,281 of 8,281 readings, CLAUDE.md 4 Oct). Every number is rounded half-up
 * with {@link Math#round(double)} when it ARRIVES ({@link WikiJson#hour}), so what is stored and computed on is the
 * calibrated integer basis. Java's {@code Math.round(double)} is {@code floor(x + 0.5)}, the same as JavaScript's:
 * a {@code .5} tie goes UP (102.5 to 103). Never {@code rint}, HALF_EVEN or a formatter.
 *
 * <p>A missing average stays missing ({@link #NONE}, written as JSON null), never filled in; a missing volume is 0,
 * exactly as compactBucket does ({@code ?? null} for prices, {@code ?? 0} for volumes).
 */
public final class HourBucket {
  /** A price the Wiki did not report for that side of that hour (JSON null). */
  public static final long NONE = Long.MIN_VALUE;

  public final long ts;
  private final int[] ids;
  private final long[] avgHigh;
  private final long[] highVol;
  private final long[] avgLow;
  private final long[] lowVol;

  private HourBucket(long ts, int[] ids, long[] avgHigh, long[] highVol, long[] avgLow, long[] lowVol) {
    this.ts = ts;
    this.ids = ids;
    this.avgHigh = avgHigh;
    this.highVol = highVol;
    this.avgLow = avgLow;
    this.lowVol = lowVol;
  }

  /** A row as four numbers: avgHigh ({@link #NONE} when absent), highVolume, avgLow ({@link #NONE}), lowVolume. */
  static HourBucket of(long ts, Map<Integer, long[]> rows) {
    TreeMap<Integer, long[]> sorted = rows instanceof TreeMap ? (TreeMap<Integer, long[]>) rows : new TreeMap<>(rows);
    int n = sorted.size(), i = 0;
    int[] ids = new int[n];
    long[] ah = new long[n], hv = new long[n], al = new long[n], lv = new long[n];
    for (Map.Entry<Integer, long[]> e : sorted.entrySet()) {
      long[] r = e.getValue();
      ids[i] = e.getKey();
      ah[i] = r[0];
      hv[i] = r[1];
      al[i] = r[2];
      lv[i] = r[3];
      i++;
    }
    return new HourBucket(ts, ids, ah, hv, al, lv);
  }

  public int size() {
    return ids.length;
  }

  public int id(int i) {
    return ids[i];
  }

  public long avgHigh(int i) {
    return avgHigh[i];
  }

  public long highVolume(int i) {
    return highVol[i];
  }

  public long avgLow(int i) {
    return avgLow[i];
  }

  public long lowVolume(int i) {
    return lowVol[i];
  }

  /** The row index of {@code itemId}, or a negative number when this hour has no row for it. */
  public int indexOf(int itemId) {
    return Arrays.binarySearch(ids, itemId);
  }

  /**
   * The archive line, byte for byte what {@code JSON.stringify(compactBucket(json)) + '\n'} writes: {@code ts}
   * first, then {@code d} with its keys in ascending numeric order (JavaScript orders integer-like keys that way),
   * integers in plain decimal, a missing average as {@code null}.
   */
  public String line() {
    StringBuilder sb = new StringBuilder(32 + ids.length * 40);
    sb.append("{\"ts\":").append(ts).append(",\"d\":{");
    for (int i = 0; i < ids.length; i++) {
      if (i > 0) sb.append(',');
      sb.append('"').append(ids[i]).append("\":[");
      num(sb, avgHigh[i]).append(',').append(highVol[i]).append(',');
      num(sb, avgLow[i]).append(',').append(lowVol[i]).append(']');
    }
    return sb.append("}}\n").toString();
  }

  private static StringBuilder num(StringBuilder sb, long v) {
    return v == NONE ? sb.append("null") : sb.append(v);
  }

  /** Parses one archive line (see {@link #line}). Null when it is not a bucket with an integer {@code ts}. */
  public static HourBucket parseLine(String line) throws IOException {
    return parseLine(new StringReader(line));
  }

  /**
   * Parses one archive line from {@code in}. Keys may come in any order; a row that is not an array of four is
   * skipped (robustPrices skips non-arrays too); unknown keys are ignored. A number with a fraction -- which the
   * plugin never writes -- is rounded half-up, so the basis cannot drift to floats by way of a foreign file.
   */
  static HourBucket parseLine(Reader in) throws IOException {
    // Read straight into primitive arrays: hundreds of these are read per rebuild, inside the game client, so no boxed
    // ids and no per-row objects. The plugin writes ids in ascending order; anything else (a foreign file, a repeated
    // id) is put in order afterwards, the LAST of a repeated id winning as in JSON.parse.
    JsonReader r = new JsonReader(in);
    Long ts = null;
    int n = 0;
    int[] ids = new int[4096];
    long[] vals = new long[4 * 4096];
    boolean ascending = true;
    r.beginObject();
    while (r.hasNext()) {
      String name = r.nextName();
      if ("ts".equals(name) && r.peek() == JsonToken.NUMBER) {
        ts = WikiJson.integral(r.nextString());
      } else if ("d".equals(name) && r.peek() == JsonToken.BEGIN_OBJECT) {
        r.beginObject();
        while (r.hasNext()) {
          int id = WikiJson.itemIdOrMinus(r.nextName());
          if (id < 0 || r.peek() != JsonToken.BEGIN_ARRAY) {
            r.skipValue();
            continue;
          }
          if (n == ids.length) {
            ids = Arrays.copyOf(ids, n * 2);
            vals = Arrays.copyOf(vals, n * 8);
          }
          int k = 0;
          boolean ok = true;
          r.beginArray();
          while (r.hasNext()) {
            JsonToken t = r.peek();
            long v;
            if (t == JsonToken.NULL) {
              r.nextNull();
              v = NONE;
            } else if (t == JsonToken.NUMBER) {
              v = WikiJson.readRounded(r);
            } else {
              r.skipValue();
              ok = false;
              v = 0;
            }
            if (k < 4) vals[4 * n + k] = v;
            k++;
          }
          r.endArray();
          if (!ok || k != 4) continue;
          // volumes are never null in a compacted bucket (?? 0); a foreign null volume reads as 0
          if (vals[4 * n + 1] == NONE) vals[4 * n + 1] = 0;
          if (vals[4 * n + 3] == NONE) vals[4 * n + 3] = 0;
          if (n > 0 && id <= ids[n - 1]) ascending = false;
          ids[n++] = id;
        }
        r.endObject();
      } else {
        r.skipValue();
      }
    }
    r.endObject();
    if (ts == null) return null;
    if (!ascending) {
      TreeMap<Integer, long[]> rows = new TreeMap<>();
      for (int i = 0; i < n; i++) rows.put(ids[i], Arrays.copyOfRange(vals, 4 * i, 4 * i + 4));
      return of(ts, rows);
    }
    long[] ah = new long[n], hv = new long[n], al = new long[n], lv = new long[n];
    for (int i = 0; i < n; i++) {
      ah[i] = vals[4 * i];
      hv[i] = vals[4 * i + 1];
      al[i] = vals[4 * i + 2];
      lv[i] = vals[4 * i + 3];
    }
    return new HourBucket(ts, Arrays.copyOf(ids, n), ah, hv, al, lv);
  }

  @Override public boolean equals(Object o) {
    if (!(o instanceof HourBucket)) return false;
    HourBucket b = (HourBucket) o;
    return ts == b.ts && Arrays.equals(ids, b.ids) && Arrays.equals(avgHigh, b.avgHigh) && Arrays.equals(highVol, b.highVol)
      && Arrays.equals(avgLow, b.avgLow) && Arrays.equals(lowVol, b.lowVol);
  }

  @Override public int hashCode() {
    return Long.hashCode(ts) * 31 + Arrays.hashCode(ids);
  }
}

package com.evi.live.market;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.NavigableSet;
import java.util.TreeSet;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import net.runelite.client.util.Filepath;

/**
 * The plugin's own hourly price archive: one gzip file per hour in {@code prices/1h/} inside the plugin's data folder ({@code PluginFolder.PATH}),
 * read and written ONLY through RuneLite's {@link Filepath} (java.io file APIs are on the Hub's forbidden list).
 *
 * <p>A CACHE OF A PUBLIC DATASET, not a recording: every hour can be fetched again from the Wiki for at least 90 days,
 * so a gap (the game was closed) is repaired at the next login and nothing is ever lost for good. Retention is a
 * rolling window ({@link #prune}); the archive does not grow.
 *
 * <p>ONE FILE PER HOUR, created complete or not at all and never replaced ({@link ArchiveFiles#writeNew}), so two
 * clients sharing the folder cannot corrupt it: both fetching the same hour write the same content, the first
 * rename stands, the second finds the file there and changes nothing. Each file holds exactly one gzip member with
 * one line, byte for byte the bridge's archive line ({@link HourBucket#line}).
 *
 * <p>NOT READABLE BY THE PRIVATE TOOLS AS IS: the bridge's {@code readArchive} accepts only
 * {@code 1h-YYYY-MM.jsonl.gz} and silently skips any other name. These files are deliberately named differently
 * ({@code hour-<ts>.json.gz}) so that nothing mistakes one layout for the other; point a tool at them only through
 * a converter.
 *
 * <p>An hour the Wiki answered with nothing usable (no rows, or a different hour) is remembered by an empty marker
 * file ({@code hour-<ts>.none}), so it is not asked for again -- priceArchive.mjs records the asked-for ts in its
 * index for the same reason. Not thread-safe: one thread (the price-data thread) owns an instance.
 */
public final class HourlyArchive {
  static final String DIR = "1h";
  private static final Pattern DATA = Pattern.compile("hour-(\\d{1,12})\\.json\\.gz");
  private static final Pattern NONE = Pattern.compile("hour-(\\d{1,12})\\.none");
  private static final Pattern TMP = Pattern.compile("hour-\\d{1,12}\\.(json\\.gz|none)\\.[0-9a-f-]{36}\\.tmp");
  /** A temporary file this old belongs to no live write (one takes milliseconds); it was left by a crash. */
  static final long STALE_TMP_MS = 60L * 60 * 1000;

  private final Filepath dir;
  private final Consumer<String> log;

  public HourlyArchive(Filepath pricesDir, Consumer<String> log) {
    this.dir = pricesDir.joinSegment(DIR);
    this.log = log;
  }

  Filepath dir() {
    return dir;
  }

  static String dataName(long ts) {
    return "hour-" + ts + ".json.gz";
  }

  static String noneName(long ts) {
    return "hour-" + ts + ".none";
  }

  /** Every hour with a data file, ascending. Re-listed from the folder each time, so another client's writes count. */
  public NavigableSet<Long> storedHours() throws IOException {
    return list(DATA);
  }

  /** Every hour the Wiki answered with nothing usable. */
  NavigableSet<Long> answeredEmpty() throws IOException {
    return list(NONE);
  }

  /** TEST SEAM: told the hour folder just before it is listed; a test throws from it to stand for a folder that cannot be read. */
  interface ListSeam {
    void listing(Filepath dir) throws IOException;
  }

  /** The {@link ListSeam}. Null in production. */
  static volatile ListSeam listSeam;

  private NavigableSet<Long> list(Pattern p) throws IOException {
    TreeSet<Long> out = new TreeSet<>();
    if (!dir.isDirectory()) return out;
    ListSeam seam = listSeam;
    if (seam != null) seam.listing(dir);
    try (Stream<Filepath> s = dir.walk(1)) {
      s.forEach(f -> {
        Matcher m = p.matcher(f.getFileName());
        if (m.matches() && f.isFile()) out.add(Long.parseLong(m.group(1)));
      });
    }
    return out;
  }

  /** Whether this hour needs no fetch: stored, or answered empty (by this client or another). */
  boolean done(long ts) {
    return dir.joinSegment(dataName(ts)).exists() || dir.joinSegment(noneName(ts)).exists();
  }

  /**
   * Stores one hour. False when the file was already there (another client got it first, which is fine: the
   * content is the same public data). The bucket's own ts names the file.
   */
  boolean store(HourBucket b) throws IOException {
    dir.createDirectories();
    return ArchiveFiles.writeNew(dir.joinSegment(dataName(b.ts)), gzip(b.line()));
  }

  /** Remembers that the Wiki answered this hour with nothing usable. */
  void markEmpty(long ts) throws IOException {
    dir.createDirectories();
    ArchiveFiles.writeNew(dir.joinSegment(noneName(ts)), new byte[0]);
  }

  static byte[] gzip(String text) throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream(text.length() / 8 + 64);
    try (GZIPOutputStream z = new GZIPOutputStream(out)) {
      z.write(text.getBytes(StandardCharsets.UTF_8));
    }
    return out.toByteArray();
  }

  /**
   * One stored hour, or null when it is absent or cannot be read. A file whose CONTENT is bad (not gzip, not one
   * bucket, or a bucket of a different hour than its name) is deleted, so the hour reads as missing and is fetched
   * again; a file that cannot be OPENED (another program holding it, say) is left alone and skipped this time.
   */
  public HourBucket read(long ts) {
    Filepath f = dir.joinSegment(dataName(ts));
    InputStream raw;
    try {
      if (!f.exists()) return null;
      raw = f.openInputStream();
    } catch (IOException e) {
      log.accept("EVI prices: could not open " + f.getFileName() + " (" + e.getClass().getSimpleName() + "); skipped this time");
      return null;
    }
    HourBucket b;
    // raw is closed on every path (the gzip header check can throw before the reader exists), so a damaged file
    // is never still open when it is deleted -- on Windows an open file cannot be removed.
    try (InputStream in = raw; Reader r = new InputStreamReader(new GZIPInputStream(in, 65536), StandardCharsets.UTF_8)) {
      b = HourBucket.parseLine(r);
    } catch (IOException | RuntimeException e) {
      b = null;
    }
    if (b != null && b.ts == ts) return b;
    log.accept("EVI prices: " + f.getFileName() + " is damaged; removed so the hour is fetched again");
    try {
      f.deleteIfExists();
    } catch (IOException e) {
      log.accept("EVI prices: could not remove " + f.getFileName() + ": " + e.getMessage());
    }
    return null;
  }

  /** Every readable stored hour in [fromTs, toTs], oldest first. For tests and small windows; the engine uses {@link MarketAggregates#build}. */
  public List<HourBucket> read(long fromTs, long toTs) throws IOException {
    List<HourBucket> out = new ArrayList<>();
    for (long ts : storedHours().subSet(fromTs, true, toTs, true)) {
      HourBucket b = read(ts);
      if (b != null) out.add(b);
    }
    return out;
  }

  /**
   * The rolling window: removes hour files and empty-hour markers older than {@code oldestKept}, and temporary
   * files a crash left behind (older than {@link #STALE_TMP_MS}; a live write's own temporary file is never that
   * old). Returns how many files went. Two clients pruning at once is harmless: a file already gone is skipped.
   */
  int prune(long oldestKept, long nowMs) throws IOException {
    if (!dir.isDirectory()) return 0;
    List<Filepath> doomed = new ArrayList<>();
    try (Stream<Filepath> s = dir.walk(1)) {
      s.forEach(f -> {
        String name = f.getFileName();
        Matcher d = DATA.matcher(name), n = NONE.matcher(name);
        if (d.matches() && Long.parseLong(d.group(1)) < oldestKept) doomed.add(f);
        else if (n.matches() && Long.parseLong(n.group(1)) < oldestKept) doomed.add(f);
        else if (TMP.matcher(name).matches()) {
          try {
            if (nowMs - ArchiveFiles.modifiedMs(f) > STALE_TMP_MS) doomed.add(f);
          } catch (IOException ignored) {
            // gone already
          }
        }
      });
    }
    int removed = 0;
    for (Filepath f : doomed) {
      try {
        f.deleteIfExists();
        removed++;
      } catch (IOException e) {
        log.accept("EVI prices: could not remove " + f.getFileName() + ": " + e.getMessage());
      }
    }
    return removed;
  }
}

package com.evi.live.market;

import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.IOException;
import java.io.StringReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The Wiki's {@code /mapping}: every tradeable item's id, name, Grand Exchange buy limit and members flag.
 * Byte-identical between API versions.
 *
 * <p>PORTED FROM server.mjs {@code itemIndex()} and the first lines of its {@code limitFor}, with their rules kept:
 * <ul>
 *   <li>an entry counts only when it is an object whose {@code id} is a NUMBER ({@code Number.isFinite(i.id)}: a
 *       string id is not one); a repeated id -- the LAST one wins (a {@code Map} built in list order);</li>
 *   <li>the buy limit is known only when it is a finite number above zero; anything else -- absent, null, zero --
 *       is UNKNOWN, which constrains nothing (some items genuinely have no buy limit, and missing is not zero);</li>
 *   <li>members is {@code === true}: absent or anything but the literal true is not members-only.</li>
 * </ul>
 * The list keeps the response's own ORDER, because the market tier walks the mapping in that order and ties keep
 * it (CLAUDE.md: order and ties decide which item spreadRank hands out).
 *
 * <p>Two documented edges the Wiki never sends: an id or limit with a fraction is not an item id or limit here
 * (JavaScript would carry 2.5 through), and an id beyond 2^31-1 is skipped.
 */
public final class ItemCatalog {
  public static final class Item {
    public final int id;
    public final String name;
    /** The raw limit as sent, or null when it was absent, null or not a whole number. */
    private final Long limit;
    private final boolean members;

    Item(int id, String name, Long limit, boolean members) {
      this.id = id;
      this.name = name;
      this.limit = limit;
      this.members = members;
    }

    /** The buy limit when known (above zero), else null: unknown constrains nothing. */
    public Long limit() {
      return limit != null && limit > 0 ? limit : null;
    }

    public boolean members() {
      return members;
    }
  }

  private final List<Item> items;
  private final Map<Integer, Item> byId;

  private ItemCatalog(List<Item> items) {
    this.items = Collections.unmodifiableList(items);
    Map<Integer, Item> m = new HashMap<>(items.size() * 2);
    for (Item i : items) m.put(i.id, i);
    this.byId = m;
  }

  /** The entries in the mapping's own order. */
  public List<Item> items() {
    return items;
  }

  /** The item, or null when the mapping has no entry for it. */
  public Item get(int itemId) {
    return byId.get(itemId);
  }

  /** limitFor's first rule: the item's buy limit when known, null when unknown or the item is not listed. */
  public Long limitFor(int itemId) {
    Item i = byId.get(itemId);
    return i == null ? null : i.limit();
  }

  /** {@code index.get(itemId)?.members === true}. */
  public boolean membersOnly(int itemId) {
    Item i = byId.get(itemId);
    return i != null && i.members;
  }

  public int size() {
    return byId.size();
  }

  public static ItemCatalog parse(String body) throws IOException {
    JsonReader r = new JsonReader(new StringReader(body));
    List<Item> items = new ArrayList<>();
    r.beginArray();
    while (r.hasNext()) {
      if (r.peek() != JsonToken.BEGIN_OBJECT) {
        r.skipValue();
        continue;
      }
      Long id = null;
      String name = null;
      Long limit = null;
      boolean members = false, idIsNumber = false;
      r.beginObject();
      while (r.hasNext()) {
        String field = r.nextName();
        JsonToken t = r.peek();
        if ("id".equals(field) && t == JsonToken.NUMBER) {
          idIsNumber = true;
          id = WikiJson.integral(r.nextString());
        } else if ("name".equals(field) && t == JsonToken.STRING) {
          name = r.nextString();
        } else if ("limit".equals(field) && t == JsonToken.NUMBER) {
          limit = WikiJson.integral(r.nextString());
        } else if ("members".equals(field) && t == JsonToken.BOOLEAN) {
          members = r.nextBoolean();
        } else {
          // a repeated field overwrites, as JSON.parse does: a later non-number id makes the entry not an item
          if ("id".equals(field)) {
            idIsNumber = false;
            id = null;
          } else if ("limit".equals(field)) {
            limit = null;
          } else if ("members".equals(field)) {
            members = false;
          } else if ("name".equals(field)) {
            name = null;
          }
          r.skipValue();
        }
      }
      r.endObject();
      if (idIsNumber && id != null && id >= Integer.MIN_VALUE && id <= Integer.MAX_VALUE) items.add(new Item((int) (long) id, name, limit, members));
    }
    r.endArray();
    return new ItemCatalog(items);
  }
}

package com.evi.live.market;

import java.util.Collections;
import java.util.NavigableMap;
import java.util.TreeMap;

/**
 * The Wiki's {@code /latest}: per item, the last price someone paid in an instant buy ({@code high}) and the last
 * price someone accepted in an instant sell ({@code low}), with the unix second each printed. Any of the four may
 * be {@link HourBucket#NONE} (the Wiki sends null for a side that has never traded). Immutable.
 */
public final class LatestPrices {
  public static final class Quote {
    public final long high;
    public final long highTime;
    public final long low;
    public final long lowTime;

    Quote(long high, long highTime, long low, long lowTime) {
      this.high = high;
      this.highTime = highTime;
      this.low = low;
      this.lowTime = lowTime;
    }
  }

  private final NavigableMap<Integer, Quote> quotes;

  LatestPrices(TreeMap<Integer, Quote> quotes) {
    this.quotes = Collections.unmodifiableNavigableMap(quotes);
  }

  /** The quote for an item, or null when the Wiki has none. */
  public Quote get(int itemId) {
    return quotes.get(itemId);
  }

  public int size() {
    return quotes.size();
  }

  public NavigableMap<Integer, Quote> all() {
    return quotes;
  }
}

package com.evi.live.market;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableSet;
import java.util.TreeMap;

/**
 * The engine's readings of the hourly archive, PORTED WITH PARITY from the bridge:
 * <ul>
 *   <li>{@link #robustPrices} -- suggestions.mjs {@code robustPrices}: the median hourly average price per side over
 *       {@link #ROBUST_PRICE_HOURS} hours, at least {@link #MIN_ROBUST_HOURS} readings a side;</li>
 *   <li>{@link #robustPricesAt} -- server.mjs {@code robustPricesCached}: the same, over
 *       {@code readArchive(dir, now - 336h)}, with "nothing" reported as an empty map;</li>
 *   <li>{@link #typicalVolumesAt} -- server.mjs {@code typicalVolumesCached}: each side's median hourly volume over
 *       {@link #TYPICAL_VOLUME_HOURS} hours, combined at the END by taking the thinner side, at least
 *       {@link #MIN_TYPICAL_VOLUME_HOURS} readings, a zero never published;</li>
 *   <li>{@link #volumeReadingFor} -- suggestions.mjs {@code volumeReadingFor}: the latest hour's thinner side, where an
 *       item ABSENT from the hour is "no reading" (null) and one LISTED with a zero side is a measured 0;</li>
 *   <li>{@link #readArchive} -- priceArchive.mjs {@code readArchive}: buckets in [from, to], one per ts (the last
 *       wins), oldest first.</li>
 * </ul>
 *
 * <p>THE RULES THAT MAKE IT BYTE-IDENTICAL, each one a place a port goes quietly wrong:
 * <ul>
 *   <li>the MEDIAN is the UPPER middle, {@code sorted[floor(n/2)]}, with NO averaging of the two middles -- both
 *       JavaScript readers use it (it differs from suggestions.mjs's own module-level {@code median}, which
 *       averages; that one is not used here);</li>
 *   <li>robust prices: the window is relative to the NEWEST bucket ({@code ts > newest - hours*3600}, strict), a side
 *       counts only when its price is above 0, and an item needs BOTH sides; typical volumes: the window is relative
 *       to NOW ({@code ts >= floor(now/1000) - 168h}), and every listed row counts, zeros included;</li>
 *   <li>robustPrices answers null for nothing at all, which the server turns into an empty map.</li>
 * </ul>
 *
 * <p>MEMORY: the production path, {@link #build}, reads ONE hour file at a time into per-item primitive arrays and
 * keeps only the answers (a few numbers per item). It never holds the raw window: the bridge measured 167 MB of
 * retained heap for one 336-hour read in Node, and this runs inside the game client.
 */
public final class MarketAggregates {
  private MarketAggregates() {}

  public static final int ROBUST_PRICE_HOURS = 336;
  public static final int MIN_ROBUST_HOURS = 6;
  public static final int TYPICAL_VOLUME_HOURS = 168;
  public static final int MIN_TYPICAL_VOLUME_HOURS = 24;
  static final long HOUR = 3600;

  /** An item's steady price: the median hourly average a buyer paid ({@code high}) and a seller got ({@code low}). */
  public static final class RobustPrice {
    public final long high;
    public final long low;

    RobustPrice(long high, long low) {
      this.high = high;
      this.low = low;
    }

    /** One item's steady price as the market tier reads it ({@code options.rankPrices[id]}), for a caller outside this package. */
    public static RobustPrice of(long high, long low) {
      return new RobustPrice(high, low);
    }

    @Override public boolean equals(Object o) {
      return o instanceof RobustPrice && ((RobustPrice) o).high == high && ((RobustPrice) o).low == low;
    }

    @Override public int hashCode() {
      return Long.hashCode(high) * 31 + Long.hashCode(low);
    }

    @Override public String toString() {
      return "{high:" + high + ",low:" + low + "}";
    }
  }

  /** The answers of one {@link #build}: what the engine reads, and how many archived hours they came from. */
  public static final class Readings {
    /** Robust prices by item id; empty (never null) when there is nothing, as robustPricesCached serves it. */
    public final Map<Integer, RobustPrice> robust;
    /** Typical hourly volume by item id (only values above 0). */
    public final Map<Integer, Long> typical;
    /** Hour files read into the robust window, and into the typical window. */
    public final int robustHours;
    public final int typicalHours;

    Readings(Map<Integer, RobustPrice> robust, Map<Integer, Long> typical, int robustHours, int typicalHours) {
      this.robust = Collections.unmodifiableMap(robust);
      this.typical = Collections.unmodifiableMap(typical);
      this.robustHours = robustHours;
      this.typicalHours = typicalHours;
    }
  }

  // ------------------------------------------------------------------------------------------- accumulators

  /** A growable long array, allocated once at the expected size. */
  static final class LongList {
    long[] a;
    int n;

    LongList(int capacity) {
      a = new long[Math.max(1, capacity)];
    }

    void add(long v) {
      if (n == a.length) a = Arrays.copyOf(a, a.length * 2);
      a[n++] = v;
    }

    /** {@code s[Math.floor(s.length / 2)]} of the sorted values: the UPPER median, no averaging. Sorts in place. */
    long upperMedian() {
      Arrays.sort(a, 0, n);
      return a[n / 2];
    }
  }

  /**
   * Item id to a dense slot number, by open addressing over primitive arrays: the accumulators look an id up once per
   * row of every hour read (about a million times a rebuild), so this boxes nothing and allocates only when it grows.
   */
  static final class Slots {
    private int[] keys = new int[8192];
    private int[] slotOf = new int[8192];
    int[] ids = new int[4096];
    int size;

    Slots() {
      Arrays.fill(keys, -1);
    }

    /** The id's slot, adding it when new. Ids are never negative (-1 marks an empty cell). */
    int slot(int id) {
      int mask = keys.length - 1, i = mix(id) & mask;
      while (keys[i] != -1) {
        if (keys[i] == id) return slotOf[i];
        i = (i + 1) & mask;
      }
      if (size == ids.length) ids = Arrays.copyOf(ids, size * 2);
      ids[size] = id;
      keys[i] = id;
      slotOf[i] = size;
      if (++size * 2 > keys.length) grow();
      return size - 1;
    }

    private static int mix(int id) {
      int h = id * 0x9E3779B9;
      return h ^ (h >>> 16);
    }

    private void grow() {
      int[] k = keys, v = slotOf;
      keys = new int[k.length * 2];
      slotOf = new int[k.length * 2];
      Arrays.fill(keys, -1);
      int mask = keys.length - 1;
      for (int j = 0; j < k.length; j++) {
        if (k[j] == -1) continue;
        int i = mix(k[j]) & mask;
        while (keys[i] != -1) i = (i + 1) & mask;
        keys[i] = k[j];
        slotOf[i] = v[j];
      }
    }
  }

  /** robustPrices' loop: prices above 0 per side, for buckets with ts > cut (strict). */
  static final class RobustAcc {
    final long cut;
    final int capacity;
    final Slots slots = new Slots();
    LongList[] highs = new LongList[4096];
    LongList[] lows = new LongList[4096];

    RobustAcc(long cut, int capacity) {
      this.cut = cut;
      this.capacity = capacity;
    }

    boolean add(HourBucket b) {
      if (b == null || !(b.ts > cut)) return false;
      for (int i = 0; i < b.size(); i++) {
        long h = b.avgHigh(i), l = b.avgLow(i);
        boolean hk = h != HourBucket.NONE && h > 0, lk = l != HourBucket.NONE && l > 0;
        if (!hk && !lk) continue;
        int s = slots.slot(b.id(i));
        if (s >= highs.length) {
          highs = Arrays.copyOf(highs, highs.length * 2);
          lows = Arrays.copyOf(lows, lows.length * 2);
        }
        if (hk) (highs[s] == null ? highs[s] = new LongList(capacity) : highs[s]).add(h);
        if (lk) (lows[s] == null ? lows[s] = new LongList(capacity) : lows[s]).add(l);
      }
      return true;
    }

    /** null when nothing qualifies, as robustPrices returns null for an empty answer. */
    TreeMap<Integer, RobustPrice> result() {
      TreeMap<Integer, RobustPrice> out = new TreeMap<>();
      for (int s = 0; s < slots.size; s++) {
        LongList h = highs[s], l = lows[s];
        if (h == null || l == null || l.n == 0 || h.n == 0) continue;
        // Too few hours is one print wearing a median's clothes: left out, so the item falls back to its live price.
        if (h.n < MIN_ROBUST_HOURS || l.n < MIN_ROBUST_HOURS) continue;
        out.put(slots.ids[s], new RobustPrice(h.upperMedian(), l.upperMedian()));
      }
      return out.isEmpty() ? null : out;
    }
  }

  /** typicalVolumesCached's loop: every listed row's two volumes (a missing one is 0), each side kept separately. */
  static final class TypicalAcc {
    final int capacity;
    final Slots slots = new Slots();
    LongList[] highs = new LongList[4096];
    LongList[] lows = new LongList[4096];

    TypicalAcc(int capacity) {
      this.capacity = capacity;
    }

    void add(HourBucket b) {
      for (int i = 0; i < b.size(); i++) {
        int s = slots.slot(b.id(i));
        if (s >= highs.length) {
          highs = Arrays.copyOf(highs, highs.length * 2);
          lows = Arrays.copyOf(lows, lows.length * 2);
        }
        if (highs[s] == null) {
          highs[s] = new LongList(capacity);
          lows[s] = new LongList(capacity);
        }
        highs[s].add(b.highVolume(i));
        lows[s].add(b.lowVolume(i));
      }
    }

    TreeMap<Integer, Long> result() {
      TreeMap<Integer, Long> out = new TreeMap<>();
      for (int s = 0; s < slots.size; s++) {
        // Too few hours to call anything typical: fall back rather than invent one.
        if (highs[s].n < MIN_TYPICAL_VOLUME_HOURS) continue;
        // An order is limited by the thinner side of the book; the sides' medians are combined only at the end.
        long v = Math.min(highs[s].upperMedian(), lows[s].upperMedian());
        // A zero is not published: it would read as a measured zero and size the item at one unit.
        if (v > 0) out.put(slots.ids[s], v);
      }
      return out;
    }
  }

  // ------------------------------------------------------------------------------------- list-based ports

  /**
   * suggestions.mjs {@code robustPrices(hourlyBuckets, hours)}: null for no buckets or no qualifying item. The newest
   * ts is {@code max(0, every ts)}, and only buckets with {@code ts > newest - hours*3600} count.
   */
  public static Map<Integer, RobustPrice> robustPrices(List<HourBucket> buckets, int hours) {
    if (buckets == null || buckets.isEmpty()) return null;
    long newest = 0;
    for (HourBucket b : buckets) if (b != null) newest = Math.max(newest, b.ts);
    RobustAcc acc = new RobustAcc(newest - hours * HOUR, buckets.size());
    for (HourBucket b : buckets) acc.add(b);
    return acc.result();
  }

  /** priceArchive.mjs {@code readArchive} over buckets already in memory: ts in [from, to], the LAST per ts wins, oldest first. */
  public static List<HourBucket> readArchive(List<HourBucket> buckets, long fromTs, long toTs) {
    Map<Long, HourBucket> byTs = new LinkedHashMap<>();
    for (HourBucket b : buckets) if (b.ts >= fromTs && b.ts <= toTs) byTs.put(b.ts, b);
    List<HourBucket> out = new ArrayList<>(byTs.values());
    out.sort((x, y) -> Long.compare(x.ts, y.ts));
    return out;
  }

  /** server.mjs {@code robustPricesCached}'s build, at {@code nowMs}: never null (nothing is an empty map). */
  public static Map<Integer, RobustPrice> robustPricesAt(List<HourBucket> archive, long nowMs) {
    Map<Integer, RobustPrice> p = robustPrices(readArchive(archive, Math.floorDiv(nowMs, 1000) - ROBUST_PRICE_HOURS * HOUR, Long.MAX_VALUE),
      ROBUST_PRICE_HOURS);
    return p == null ? new TreeMap<>() : p;
  }

  /** server.mjs {@code typicalVolumesCached}'s build, at {@code nowMs}. */
  public static Map<Integer, Long> typicalVolumesAt(List<HourBucket> archive, long nowMs) {
    List<HourBucket> window = readArchive(archive, Math.floorDiv(nowMs, 1000) - TYPICAL_VOLUME_HOURS * HOUR, Long.MAX_VALUE);
    TypicalAcc acc = new TypicalAcc(window.size());
    for (HourBucket b : window) acc.add(b);
    return acc.result();
  }

  /**
   * suggestions.mjs {@code volumeReadingFor}: how much traded in the latest hour, for SIZING. Null -- no reading,
   * constrains nothing -- when there is no hour or the item is ABSENT from it; otherwise the thinner side, where a
   * listed zero is a measured 0 and must constrain.
   */
  public static Long volumeReadingFor(HourBucket latestHour, int itemId) {
    if (latestHour == null) return null;
    int i = latestHour.indexOf(itemId);
    if (i < 0) return null;
    return Math.min(latestHour.highVolume(i), latestHour.lowVolume(i));
  }

  // ------------------------------------------------------------------------------------- production path

  /**
   * Both readings at {@code nowMs}, streamed from the archive's hour files ONE AT A TIME -- the same answers as
   * {@link #robustPricesAt} and {@link #typicalVolumesAt} over the same hours, without holding the window.
   *
   * <p>Hours are read NEWEST FIRST, so the newest hour actually readable defines the robust window before any
   * older hour is added: an hour whose file cannot be read is then simply absent, exactly as if it had never
   * been stored, rather than shifting the window. Must run on the archive's own thread (it reads files).
   */
  public static Readings build(HourlyArchive archive, long nowMs) throws IOException {
    long nowS = Math.floorDiv(nowMs, 1000);
    long robustFrom = nowS - ROBUST_PRICE_HOURS * HOUR, typicalFrom = nowS - TYPICAL_VOLUME_HOURS * HOUR;
    NavigableSet<Long> hours = archive.storedHours().tailSet(Math.min(robustFrom, typicalFrom), true);
    RobustAcc robust = null;
    TypicalAcc typical = new TypicalAcc(hours.tailSet(typicalFrom, true).size());
    int robustHours = 0, typicalHours = 0;
    for (Long ts : hours.descendingSet()) {
      HourBucket b = archive.read(ts);
      if (b == null) continue; // unreadable: absent, as if never stored
      if (ts >= robustFrom) {
        if (robust == null) robust = new RobustAcc(Math.max(0, ts) - ROBUST_PRICE_HOURS * HOUR, hours.size()); // the newest readable hour
        if (robust.add(b)) robustHours++;
      }
      if (ts >= typicalFrom) {
        typical.add(b);
        typicalHours++;
      }
    }
    TreeMap<Integer, RobustPrice> r = robust == null ? null : robust.result();
    return new Readings(r == null ? new TreeMap<>() : r, typical.result(), robustHours, typicalHours);
  }
}

package com.evi.live.market;

import java.util.Collections;
import java.util.Map;

/**
 * Everything the price-data layer knows at one moment, published as ONE immutable object (a volatile reference in
 * {@link PriceDataService}), so a reader on any thread sees a consistent set and never touches the disk or the
 * network. The plugin's own engine reads it (com.evi.live.inprocess).
 */
public final class MarketSnapshot {
  public static final MarketSnapshot EMPTY = new MarketSnapshot(null, null, 0, null, null, 0, 0, 0, 0, Long.MIN_VALUE, true, 0, 0);

  /** The item list, or null before the first mapping arrived (from the Wiki or the disk cache). */
  public final ItemCatalog catalog;
  /** The last {@code /latest}, or null before one arrived (it is only fetched while logged in). */
  public final LatestPrices latest;
  public final long latestFetchedAtMs;
  /** The newest stored hour, or null. Read it through {@link #latestHour(long)}, which knows when it is too old. */
  private final HourBucket newestHour;
  /** Robust prices and typical volumes, from the last {@link MarketAggregates#build}; empty before the first. */
  public final Map<Integer, MarketAggregates.RobustPrice> robust;
  public final Map<Integer, Long> typical;
  public final int robustHours;
  public final int typicalHours;
  public final long readingsBuiltAtMs;
  /** Hours stored (or answered empty, which needs no fetch) inside the backfill window, and the window's size. */
  public final int hoursStored;
  /**
   * Hours of the window the Wiki would not give this session ({@value PriceDataService#HOUR_TRIES} failures in a row):
   * given up until the next session. Absent, but NOT still being fetched -- see {@link #catchingUp}.
   */
  public final int hoursUnavailable;
  public final int windowHours;
  /**
   * True while hours of the window are still to be FETCHED this session ({@code hoursStored + hoursUnavailable <
   * windowHours}). An hour given up is not "still coming", so it cannot hold this true for the two weeks it takes to
   * leave the window; a reader that needs every hour compares {@code hoursStored} with {@code windowHours} itself.
   */
  public final boolean catchingUp;
  public final long newestStoredTs;
  /**
   * Moves each time the layer learns of an hour it had not (loaded, stored, answered empty, or written by the other client);
   * never moves back. The engine reads its copy of the last 26 hours again when it changes (a backfilled
   * OLDER hour does not change {@link #newestStoredTs}).
   */
  public final long archiveRevision;
  /**
   * {@link #hoursStored} as it stood when the readings ({@link #robust}, {@link #typical}) were last built; 0 before the first
   * build. The readings are rebuilt on a cadence, so an hour stored since then is not in them yet: a reader that needs the
   * readings to rest on a full window (the in-process engine's first-run gate on buy suggestions) compares THIS, not
   * {@link #hoursStored}.
   */
  public final int readingsHoursStored;

  MarketSnapshot(ItemCatalog catalog, LatestPrices latest, long latestFetchedAtMs, HourBucket newestHour, MarketAggregates.Readings readings,
                 long readingsBuiltAtMs, int hoursStored, int hoursUnavailable, int windowHours, long newestStoredTs, boolean catchingUp,
                 long archiveRevision, int readingsHoursStored) {
    this.catalog = catalog;
    this.latest = latest;
    this.latestFetchedAtMs = latestFetchedAtMs;
    this.newestHour = newestHour;
    this.robust = readings == null ? Collections.emptyMap() : readings.robust;
    this.typical = readings == null ? Collections.emptyMap() : readings.typical;
    this.robustHours = readings == null ? 0 : readings.robustHours;
    this.typicalHours = readings == null ? 0 : readings.typicalHours;
    this.readingsBuiltAtMs = readingsBuiltAtMs;
    this.hoursStored = hoursStored;
    this.hoursUnavailable = hoursUnavailable;
    this.windowHours = windowHours;
    this.newestStoredTs = newestStoredTs;
    this.catchingUp = catchingUp;
    this.archiveRevision = archiveRevision;
    this.readingsHoursStored = readingsHoursStored;
  }

  /**
   * The latest hour's volumes for SIZING ({@link MarketAggregates#volumeReadingFor} reads it): the newest closed
   * hour, or the one before it while the newest is still settling or being fetched. Anything older is no longer
   * "the latest hour" and reads as null -- no reading -- rather than an old hour passed off as the present.
   */
  public HourBucket latestHour(long nowMs) {
    HourBucket h = newestHour;
    if (h == null) return null;
    return h.ts >= PriceDataService.newestClosedHour(nowMs) - MarketAggregates.HOUR ? h : null;
  }
}

package com.evi.live.market;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.NavigableSet;
import java.util.Set;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;
import java.util.zip.GZIPInputStream;
import net.runelite.client.util.Filepath;

/**
 * The price-data layer's scheduler: it owns ONE plugin thread ({@value #THREAD_NAME}), the hourly archive, the item
 * list and the latest prices, and publishes what it knows as one immutable {@link MarketSnapshot}. Data only: in
 * this phase nothing EVI suggests reads it.
 *
 * <h3>What it fetches, through {@link WikiPriceClient} only, one request at a time, at least {@code gapMs} apart</h3>
 * <ol>
 *   <li>the item list ({@code /mapping}) when there is none, then once a day; kept on disk so a restart needs no request;</li>
 *   <li>the latest prices ({@code /latest}) every {@code latestEveryMs} -- ONLY WHILE LOGGED IN;</li>
 *   <li>each missing hour of the archive window ({@code /1h?timestamp=}), NEWEST FIRST, as priceArchive.mjs does:
 *       the first run backfills the whole window, a later login repairs only the gap, and in steady running one
 *       request at about five past each hour (an hour is asked for {@value #SETTLE_S} s after it closes).</li>
 * </ol>
 * A failed request is retried with back-off (10 s doubling to 5 min), never in a loop. The back-off is kept PER KIND of
 * request (item list, latest prices, hours): a success of one kind never resets another kind's back-off, and a kind
 * that is backing off never holds up the others (an item list the Wiki will not give does not stop the history). An
 * hour that fails {@value #HOUR_TRIES} times running is left for the next session rather than blocking the ones behind
 * it. Whatever the kind, two requests are always at least {@code gapMs} apart. Nothing waits by sleeping (the Hub
 * forbids {@code Thread.sleep}): every wait is a scheduled task.
 *
 * <h3>Two clocks</h3>
 * Every SPACING -- the gap between requests, each kind's back-off, the minute between {@code /latest} requests, the
 * rebuild interval -- is measured on a MONOTONIC clock ({@link #MONOTONIC_MS} in the plugin), so the computer's clock
 * being set back (a time sync, a manual change) cannot leave the layer waiting for a moment that has already passed.
 * The WALL clock is used only for what is about calendar time: which hours exist and have settled, the day of the item
 * list, the window kept, and the times published in the snapshot.
 *
 * <h3>Generations</h3>
 * Turning the plugin off and on makes a new service while the old one may still have a request out (shutdown never
 * interrupts it). {@link #start(PriceDataService)} is handed the old one: the new service does NOTHING -- no disk read,
 * no request -- until every earlier generation's thread has finished, and then keeps their spacing, so a toggle never
 * puts two requests in flight or two closer than {@code gapMs}. (WikiPriceClient's own guard is process-wide as well.)
 *
 * <h3>Threads</h3>
 * Every file and network operation runs on this service's own thread and is refused anywhere else; the client thread
 * only flips {@link #loggedIn}, and any thread may read {@link #snapshot()}. {@link #shutdown()} is orderly:
 * {@code shutdown()}, never {@code shutdownNow()}, so nothing is ever interrupted; a request in flight finishes
 * (bounded by the client's 20 s call limit) and nothing new starts.
 */
public final class PriceDataService {
  public static final String THREAD_NAME = "evi-prices";
  /** The price data's folder inside the plugin's data folder. */
  public static final String DIR = "prices";
  /** Ask for an hour this long after it closes, as priceArchive.mjs does (SETTLE_S). */
  static final long SETTLE_S = 300;
  static final long HOUR = 3600;
  static final long MAPPING_EVERY_MS = 24L * 60 * 60 * 1000;
  static final long REBUILD_WHILE_CATCHING_UP_MS = 5L * 60 * 1000;
  static final long REBUILD_EVERY_MS = 15L * 60 * 1000;
  static final long MAX_IDLE_MS = 60_000;
  static final long BACKOFF_FIRST_MS = 10_000;
  static final long BACKOFF_MAX_MS = 5L * 60 * 1000;
  static final int HOUR_TRIES = 3;
  /** How often a new generation looks whether the previous one has finished. */
  static final long HANDOVER_POLL_MS = 250;
  /** The shortest wait between two scheduler ticks, so no condition can ever turn into a busy loop. */
  static final long MIN_TICK_MS = 10;
  private static final int K_MAPPING = 0, K_LATEST = 1, K_HOUR = 2;
  private static final Pattern MAPPING = Pattern.compile("mapping-(\\d{1,9})\\.json\\.gz");
  /** The monotonic clock the plugin passes, in milliseconds. Only the difference between two readings means anything. */
  public static final LongSupplier MONOTONIC_MS = () -> Math.floorDiv(System.nanoTime(), 1_000_000L);
  private static final Pattern MAPPING_TMP = Pattern.compile("mapping-\\d{1,9}\\.json\\.gz\\.[0-9a-f-]{36}\\.tmp");

  /**
   * PROVISIONAL DEFAULTS (the maintainer has not decided these yet; SELF-CONTAINED-PLAN decisions 8, 10, 11):
   * 14 days of hourly history kept, 2.5 s between requests (the bridge's own polite pace), and the latest prices
   * once a minute while logged in (the Wiki's cache keeps /latest for 60 s, so faster buys nothing).
   */
  public static final class Settings {
    public final long gapMs;
    public final long latestEveryMs;
    public final int retentionHours;
    /** False in tests that step the scheduler by hand ({@link #step}). */
    final boolean autoSchedule;

    public Settings(long gapMs, long latestEveryMs, int retentionHours) {
      this(gapMs, latestEveryMs, retentionHours, true);
    }

    Settings(long gapMs, long latestEveryMs, int retentionHours, boolean autoSchedule) {
      this.gapMs = gapMs;
      this.latestEveryMs = latestEveryMs;
      this.retentionHours = retentionHours;
      this.autoSchedule = autoSchedule;
    }

    public static final Settings DEFAULT = new Settings(2500, 60_000, 336);
  }

  /** What one scheduler step did. */
  enum Work { MAPPING, LATEST, HOUR, WAIT, IDLE }

  private final Filepath root;
  private final HourlyArchive archive;
  private final WikiPriceClient wiki;
  /** Wall-clock time: hour buckets, the item list's day, the window, and the times published. */
  private final LongSupplier clock;
  /** Monotonic time ({@link #MONOTONIC_MS}): every spacing and back-off. */
  private final LongSupplier mono;
  private final Consumer<String> log;
  private final Settings settings;
  private final ScheduledThreadPoolExecutor executor;
  private volatile Thread thread;
  private volatile boolean closed;
  private volatile boolean loggedIn;
  private volatile MarketSnapshot snapshot = MarketSnapshot.EMPTY;

  // ---- price-data thread only
  private final Set<Long> known = new HashSet<>();
  private final Set<Long> skipped = new HashSet<>();
  private final Map<Long, Integer> hourFailures = new HashMap<>();
  private ItemCatalog catalog;
  private long catalogDay = Long.MIN_VALUE;
  private LatestPrices latest;
  /** When the latest prices were fetched: wall time, published in the snapshot. */
  private long latestAt = Long.MIN_VALUE;
  /** The same moment on the monotonic clock: the minute between two /latest requests is measured from this. */
  private long latestMono = Long.MIN_VALUE;
  private HourBucket newestHour;
  private MarketAggregates.Readings readings;
  private long builtAt = Long.MIN_VALUE;
  /** The last rebuild on the monotonic clock: the rebuild interval is measured from this, never from {@link #builtAt}. */
  private long builtMono = Long.MIN_VALUE;
  /** The window's stored hours when {@link #readings} were built (published as {@link MarketSnapshot#readingsHoursStored}). */
  private int builtStored;
  private boolean dirty;
  /**
   * Moves (never back) each time an hour joins {@link #known}: loaded from disk, stored after a fetch, answered empty, or found
   * written by the other client. Published as {@link MarketSnapshot#archiveRevision}, so a reader that keeps its own copy of
   * the archive's hours (the engine's recent-archive readings) knows to read them again -- a backfilled OLDER hour leaves the newest
   * stored hour unchanged, which is why that cannot be the signal.
   */
  private long archiveRevision;
  private boolean otherWroteNewer;
  /** No request of any kind before this (the spacing), on the monotonic clock. Volatile: the next generation reads it once this one has finished. */
  private volatile long nextAllowedAt = Long.MIN_VALUE;
  /** Per kind (K_MAPPING, K_LATEST, K_HOUR): no request of that kind before this (monotonic clock), and its failures in a row. */
  private final long[] notBefore = {Long.MIN_VALUE, Long.MIN_VALUE, Long.MIN_VALUE};
  private final int[] failures = new int[3];
  /** The previous generation, until it and every generation before it have finished. Volatile: walked by the next one. */
  private volatile PriceDataService predecessor;
  private boolean loaded;
  private long chain;
  private ScheduledFuture<?> pending;
  private boolean started;

  /**
   * @param clock wall-clock milliseconds ({@code System::currentTimeMillis})
   * @param monotonic monotonic milliseconds ({@link #MONOTONIC_MS}). Both are required, so no caller can make the spacing
   *     follow the wall clock by leaving one out.
   */
  public PriceDataService(Filepath pluginDir, WikiPriceClient wiki, LongSupplier clock, LongSupplier monotonic, Consumer<String> log) {
    this(pluginDir, wiki, clock, monotonic, log, Settings.DEFAULT);
  }

  public PriceDataService(Filepath pluginDir, WikiPriceClient wiki, LongSupplier clock, LongSupplier monotonic, Consumer<String> log,
    Settings settings) {
    this.root = pluginDir.joinSegment(DIR);
    this.archive = new HourlyArchive(root, log);
    this.wiki = wiki;
    this.clock = clock;
    this.mono = monotonic;
    this.log = log;
    this.settings = settings;
    this.executor = new ScheduledThreadPoolExecutor(1, r -> {
      Thread t = new Thread(r, THREAD_NAME);
      t.setDaemon(true); // never holds the client open
      thread = t;
      return t;
    });
    // After shutdown(), a tick still waiting for its time is dropped, not run; one already running finishes.
    executor.setExecuteExistingDelayedTasksAfterShutdownPolicy(false);
    executor.setContinueExistingPeriodicTasksAfterShutdownPolicy(false);
    executor.setRemoveOnCancelPolicy(true);
  }

  /** The newest hour that has closed and settled at {@code nowMs}: its start, in unix seconds (nextMissingFor's {@code newest}). */
  static long newestClosedHour(long nowMs) {
    return Math.floorDiv(Math.floorDiv(nowMs, 1000) - SETTLE_S, HOUR) * HOUR - HOUR;
  }

  // ------------------------------------------------------------------------------------- any thread

  /** Loads what is on disk, then starts fetching. Returns at once; all of it runs on the price-data thread. */
  public void start() {
    start(null);
  }

  /**
   * As {@link #start()}, taking over from the service the previous {@code startUp()} made (null if none): nothing is
   * read or fetched until that one -- and any before it -- has finished, and the spacing it was keeping is kept.
   */
  public void start(PriceDataService previous) {
    if (previous == this) throw new IllegalArgumentException("a service cannot follow itself");
    if (previous != null) {
      previous.shutdown(); // idempotent; the caller has normally done it already
      predecessor = previous;
    }
    submit(() -> {
      if (started) return;
      started = true;
      ioCheck();
      if (settings.autoSchedule) schedule(0);
    });
  }

  /** The client thread says whether a player is logged in; {@code /latest} is fetched only while one is. */
  public void loggedIn(boolean in) {
    boolean was = loggedIn;
    loggedIn = in;
    if (in && !was && settings.autoSchedule) submit(() -> schedule(0)); // fetch the latest prices now, not at the next idle tick
  }

  /** Whether the client last said a player is logged in. */
  public boolean isLoggedIn() {
    return loggedIn;
  }

  /** What the layer knows now. Never blocks, never reads the disk. */
  public MarketSnapshot snapshot() {
    return snapshot;
  }

  /**
   * Every readable stored hour from {@code fromTs} (unix seconds) on, oldest first (the engine's recent-archive readings), read on the
   * price-data thread (the archive's files are touched nowhere else). Returns at once. Completes exceptionally when the layer
   * is shut down, or has not loaded yet (a previous generation still running, or no first tick). No request is made.
   */
  public java.util.concurrent.CompletableFuture<java.util.List<HourBucket>> readHours(long fromTs) {
    java.util.concurrent.CompletableFuture<java.util.List<HourBucket>> f = new java.util.concurrent.CompletableFuture<>();
    if (closed) {
      f.completeExceptionally(new IllegalStateException("the price layer is shut down"));
      return f;
    }
    try {
      executor.execute(() -> {
        try {
          ioCheck();
          if (predecessor != null || !loaded) throw new IllegalStateException("the price layer has not loaded its archive yet");
          f.complete(archive.read(fromTs, Long.MAX_VALUE));
        } catch (Throwable t) { // reaches the caller's future, never the game
          f.completeExceptionally(t);
        }
      });
    } catch (java.util.concurrent.RejectedExecutionException e) {
      f.completeExceptionally(e);
    }
    return f;
  }

  /** Stops taking work. Orderly: never interrupts; a request in flight finishes and nothing new starts. */
  public void shutdown() {
    closed = true;
    executor.shutdown();
  }

  public boolean isShutdown() {
    return executor.isShutdown();
  }

  /** True once shut down AND its thread has finished: nothing of this service can touch the network or the disk again. */
  public boolean isTerminated() {
    return executor.isTerminated();
  }

  /** Waits for the thread to finish after {@link #shutdown()}. Never call on the client thread. */
  public boolean awaitTermination(long timeoutMs) throws InterruptedException {
    return executor.awaitTermination(timeoutMs, TimeUnit.MILLISECONDS);
  }

  /** TESTS: runs one scheduler step on the price-data thread and says what it did. */
  Work step() throws Exception {
    return executor.submit(() -> tickOnce(clock.getAsLong())).get(60, TimeUnit.SECONDS);
  }

  /** TESTS: how long the scheduler would wait before its next tick if one finished now, worked out on the price-data thread. */
  long delay() throws Exception {
    return executor.submit(this::delayAfterTick).get(60, TimeUnit.SECONDS);
  }

  /** TESTS: waits for everything queued so far. */
  void awaitIdle() throws Exception {
    executor.submit(() -> { }).get(60, TimeUnit.SECONDS);
  }

  HourlyArchive archive() {
    return archive;
  }

  Thread thread() {
    return thread;
  }

  private void submit(Runnable task) {
    if (closed) return;
    try {
      executor.execute(() -> {
        try {
          task.run();
        } catch (Throwable t) { // never reaches the game
          log.accept("EVI prices: " + t);
        }
      });
    } catch (java.util.concurrent.RejectedExecutionException e) {
      // shut down meanwhile: nothing to do
    }
  }

  // -------------------------------------------------------------------------------- price-data thread

  private void ioCheck() {
    if (Thread.currentThread() != thread)
      throw new IllegalStateException("EVI price data work attempted on " + Thread.currentThread().getName() + ", not " + THREAD_NAME);
  }

  /** The one-shot chain: only the most recently scheduled tick runs; an older one finds its token stale and returns. */
  private void schedule(long delayMs) {
    if (closed) return;
    final long token = ++chain;
    ScheduledFuture<?> before = pending;
    if (before != null) before.cancel(false); // never with interrupt
    try {
      pending = executor.schedule(() -> {
        if (closed || token != chain) return;
        try {
          tickOnce(clock.getAsLong());
        } catch (Throwable t) {
          log.accept("EVI prices: " + t);
        }
        if (!closed && token == chain) schedule(delayAfterTick());
      }, Math.max(0, delayMs), TimeUnit.MILLISECONDS);
    } catch (java.util.concurrent.RejectedExecutionException e) {
      // shut down meanwhile
    }
  }

  /**
   * How long until something could be due: the earliest moment any kind of request may go (its own back-off, and the
   * spacing after the last request of any kind), the next /latest, the next hour settling, or at most a minute.
   */
  private long delayAfterTick() {
    long now = clock.getAsLong(), m = mono.getAsLong();
    if (predecessor != null) return HANDOVER_POLL_MS;
    long due = m + MAX_IDLE_MS; // on the monotonic clock, like every spacing
    if (catalog == null || mappingStale(now)) due = Math.min(due, notBefore[K_MAPPING]);
    if (loggedIn) due = Math.min(due, Math.max(notBefore[K_LATEST], latestMono == Long.MIN_VALUE ? m : latestMono + settings.latestEveryMs));
    if (nextMissingHour(now) != null) due = Math.min(due, notBefore[K_HOUR]);
    long settles = (newestClosedHour(now) + 2 * HOUR + SETTLE_S) * 1000 + 1000; // when the next hour has settled: WALL time
    due = Math.min(due, m + (settles - now));
    due = Math.max(due, Math.max(m, nextAllowedAt)); // the spacing applies to whatever goes next
    return Math.max(MIN_TICK_MS, due - m);
  }

  /**
   * True while an earlier generation (or one before it) is still running. Once none is, this one takes over the
   * latest spacing any of them was keeping and lets them go; from then on it is false without looking again.
   */
  private boolean predecessorBusy() {
    PriceDataService p = predecessor;
    if (p == null) return false;
    long pace = nextAllowedAt;
    for (PriceDataService q = p; q != null; q = q.predecessor) {
      if (!q.executor.isTerminated()) return true;
      pace = Math.max(pace, q.nextAllowedAt);
    }
    nextAllowedAt = pace;
    predecessor = null;
    return false;
  }

  private void load() {
    try {
      root.createDirectories();
      for (Long ts : archive.storedHours()) learned(ts);
      for (Long ts : archive.answeredEmpty()) learned(ts);
      loadMappingCache();
      NavigableSet<Long> stored = archive.storedHours();
      for (Long ts : stored.descendingSet()) {
        HourBucket b = archive.read(ts);
        if (b != null) {
          newestHour = b;
          break;
        }
      }
      long now = clock.getAsLong();
      prune(now);
      if (!stored.isEmpty()) rebuild(now);
    } catch (IOException e) {
      log.accept("EVI prices: could not read the price folder: " + e.getMessage());
    }
    publish(clock.getAsLong());
  }

  /** One step: at most ONE request, then any due rebuild or prune, then a fresh snapshot. */
  Work tickOnce(long now) throws IOException {
    ioCheck();
    if (predecessorBusy()) return Work.WAIT;
    if (!loaded) {
      loaded = true;
      started = true;
      load();
    }
    long m = mono.getAsLong();
    if (m < nextAllowedAt) return Work.WAIT;
    Work w = next(now, m);
    if (w == Work.MAPPING) fetchMapping(now);
    else if (w == Work.LATEST) fetchLatest(now, m);
    else if (w == Work.HOUR) fetchHour(nextMissingHour(now));
    long after = clock.getAsLong();
    if (otherWroteNewer) adoptNewestFromDisk(after);
    if (rebuildDue(after, mono.getAsLong())) {
      try {
        rebuild(after);
      } catch (IOException e) {
        builtAt = after; // tried: not again on every tick; the next attempt comes with the next due rebuild
        builtMono = mono.getAsLong();
        dirty = false;
        log.accept("EVI prices: the price readings could not be rebuilt: " + e.getMessage());
      }
    }
    publish(after);
    return w;
  }

  /**
   * The other client stored an hour newer than this one's newest: read it, so "the latest hour" follows the archive
   * whoever fetched it, and prune to the new window.
   */
  private void adoptNewestFromDisk(long now) throws IOException {
    otherWroteNewer = false;
    for (Long ts : archive.storedHours().descendingSet()) {
      if (newestHour != null && ts <= newestHour.ts) return;
      HourBucket b = archive.read(ts);
      if (b != null) {
        newestHour = b;
        prune(now);
        return;
      }
    }
  }

  /**
   * What to ask for next, in priority order, skipping any kind still backing off: WAIT when something is due but every
   * due kind is backing off, IDLE when nothing is due. Reads state; changes nothing but the stat cache. {@code now} is wall
   * time (which hours, which day), {@code m} monotonic (every back-off, and the minute between /latest requests).
   */
  private Work next(long now, long m) {
    boolean held = false;
    if (catalog == null) {
      if (m >= notBefore[K_MAPPING]) return Work.MAPPING;
      held = true; // no item list, and the Wiki is refusing it for now: the prices and the history need none, so they go on
    }
    if (loggedIn && (latestMono == Long.MIN_VALUE || m - latestMono >= settings.latestEveryMs)) {
      if (m >= notBefore[K_LATEST]) return Work.LATEST;
      held = true;
    }
    if (nextMissingHour(now) != null) {
      if (m >= notBefore[K_HOUR]) return Work.HOUR;
      held = true;
    }
    if (catalog != null && mappingStale(now)) { // a day-old list: refreshed when nothing else waits
      if (m >= notBefore[K_MAPPING]) return Work.MAPPING;
      held = true;
    }
    return held ? Work.WAIT : Work.IDLE;
  }

  private boolean mappingStale(long now) {
    return Math.floorDiv(now, MAPPING_EVERY_MS) > catalogDay;
  }

  /** The newest hour of the window not yet stored or answered (nextMissingFor), or null. Another client's file counts as stored. */
  Long nextMissingHour(long now) {
    long newest = newestClosedHour(now);
    long oldest = newest - (long) settings.retentionHours * HOUR;
    for (long ts = newest; ts >= oldest; ts -= HOUR) {
      if (known.contains(ts) || skipped.contains(ts)) continue;
      if (archive.done(ts)) { // written by the other client meanwhile
        learned(ts);
        dirty = true;
        if (newestHour == null || ts > newestHour.ts) otherWroteNewer = true;
        continue;
      }
      return ts;
    }
    return null;
  }

  /**
   * After a request of one kind: the spacing for every kind, and that kind's own back-off. A success resets ONLY its own
   * kind, so a /latest that works every minute cannot keep restarting the back-off of a /1h that does not.
   */
  private void requested(int kind, boolean ok) {
    long end = mono.getAsLong();
    nextAllowedAt = end + settings.gapMs;
    if (ok) {
      failures[kind] = 0;
      notBefore[kind] = Long.MIN_VALUE;
    } else {
      int n = ++failures[kind];
      long backoff = Math.min(BACKOFF_MAX_MS, BACKOFF_FIRST_MS << Math.min(20, n - 1));
      notBefore[kind] = end + Math.max(settings.gapMs, backoff);
    }
  }

  private void fetchMapping(long now) {
    String body;
    try {
      body = wiki.mapping();
      ItemCatalog c = ItemCatalog.parse(body);
      if (c.size() == 0) throw new IOException("the item list was empty");
      catalog = c;
      catalogDay = Math.floorDiv(now, MAPPING_EVERY_MS);
      requested(K_MAPPING, true);
    } catch (IOException | RuntimeException e) {
      requested(K_MAPPING, false);
      log.accept("EVI prices: item list not fetched (" + e.getMessage() + "); retrying in " + (notBefore[K_MAPPING] - mono.getAsLong()) / 1000 + " s");
      return;
    }
    saveMappingCache(body, catalogDay);
  }

  private void fetchLatest(long now, long m) {
    try {
      latest = WikiJson.latest(wiki.latest());
      latestAt = now;
      latestMono = m;
      requested(K_LATEST, true);
    } catch (IOException | RuntimeException e) {
      requested(K_LATEST, false);
      log.accept("EVI prices: latest prices not fetched (" + e.getMessage() + ")");
    }
  }

  private void fetchHour(Long ts) {
    if (ts == null) return;
    HourBucket b;
    try {
      b = WikiJson.hour(wiki.hour(ts));
    } catch (IOException | RuntimeException e) {
      hourFailed(ts, "not fetched", e);
      return;
    }
    // The Wiki may answer with a different hour than asked for: store what it says it is, and remember the asked-for
    // hour as answered so an empty or odd one is not asked for forever (priceArchive.mjs step()).
    try {
      if (b != null && b.size() > 0 && b.ts > 0 && b.ts % HOUR == 0 && !known.contains(b.ts)) {
        archive.store(b);
        learned(b.ts);
        dirty = true;
        if (newestHour == null || b.ts > newestHour.ts) {
          newestHour = b;
          prune(clock.getAsLong());
        }
      }
      if (!known.contains(ts)) {
        archive.markEmpty(ts);
        learned(ts);
      }
    } catch (IOException | RuntimeException e) {
      // A disk that cannot take the hour (full, read-only, held by another program) must not turn into the same request
      // every 2.5 s: it backs off and is given up for the session exactly like a failed request.
      hourFailed(ts, "could not be saved", e);
      return;
    }
    requested(K_HOUR, true); // only now: a fetch whose hour could not be kept is a failure, and its back-off keeps doubling
    hourFailures.remove(ts);
  }

  /** A failed hour: back off, and after {@value #HOUR_TRIES} failures in a row leave it for the next session. */
  private void hourFailed(long ts, String what, Exception e) {
    requested(K_HOUR, false);
    int n = hourFailures.merge(ts, 1, Integer::sum);
    if (n >= HOUR_TRIES) {
      skipped.add(ts);
      log.accept("EVI prices: hour " + ts + " failed " + n + " times (" + what + ": " + e.getMessage() + "); left for the next session");
    } else {
      log.accept("EVI prices: hour " + ts + " " + what + " (" + e.getMessage() + ")");
    }
  }

  private boolean rebuildDue(long now, long m) {
    if (known.isEmpty() && readings == null) return false;
    if (readings == null) return dirty;
    if (dirty && (!catchingUp(now) || m - builtMono >= REBUILD_WHILE_CATCHING_UP_MS)) return true;
    return m - builtMono >= REBUILD_EVERY_MS;
  }

  private boolean catchingUp(long now) {
    long newest = newestClosedHour(now);
    long oldest = newest - (long) settings.retentionHours * HOUR;
    for (long ts = newest; ts >= oldest; ts -= HOUR) if (!known.contains(ts) && !skipped.contains(ts)) return true;
    return false;
  }

  private void rebuild(long now) throws IOException {
    readings = MarketAggregates.build(archive, now);
    builtStored = window(now)[0];
    builtAt = now;
    builtMono = mono.getAsLong();
    dirty = false;
  }

  private void prune(long now) throws IOException {
    long oldestKept = newestClosedHour(now) - (long) settings.retentionHours * HOUR;
    archive.prune(oldestKept, now);
    known.removeIf(ts -> ts < oldestKept);
    skipped.removeIf(ts -> ts < oldestKept);
  }

  /**
   * Publishes what is known. {@code catchingUp} means hours are still to be FETCHED this session -- not merely absent:
   * an hour given up after {@value #HOUR_TRIES} failures is counted in {@code hoursUnavailable} instead, so one hour the
   * Wiki will not give cannot leave the layer "catching up" until that hour ages out of the window two weeks later.
   */
  /** An hour now known to be stored or answered: {@link #archiveRevision} moves when it is new. */
  private void learned(long ts) {
    if (known.add(ts)) archiveRevision++;
  }

  private void publish(long now) {
    int window = settings.retentionHours + 1;
    int[] w = window(now);
    int stored = w[0], unavailable = w[1];
    snapshot = new MarketSnapshot(catalog, latest, latestAt == Long.MIN_VALUE ? 0 : latestAt, newestHour, readings,
      builtAt == Long.MIN_VALUE ? 0 : builtAt, stored, unavailable, window, newestHour == null ? Long.MIN_VALUE : newestHour.ts,
      stored + unavailable < window, archiveRevision, readings == null ? 0 : builtStored);
  }

  /** The backfill window's hours at {@code now}: {stored (or answered), given up this session}. */
  private int[] window(long now) {
    long newest = newestClosedHour(now);
    int stored = 0, unavailable = 0;
    for (long ts = newest - (long) settings.retentionHours * HOUR; ts <= newest; ts += HOUR) {
      if (known.contains(ts)) stored++;
      else if (skipped.contains(ts)) unavailable++;
    }
    return new int[]{stored, unavailable};
  }

  // -------------------------------------------------------------------------------- the item list on disk

  private void loadMappingCache() throws IOException {
    long bestDay = Long.MIN_VALUE;
    Filepath best = null;
    if (root.isDirectory()) {
      try (Stream<Filepath> s = root.walk(1)) {
        for (Filepath f : (Iterable<Filepath>) s::iterator) {
          Matcher m = MAPPING.matcher(f.getFileName());
          if (m.matches() && Long.parseLong(m.group(1)) > bestDay) {
            bestDay = Long.parseLong(m.group(1));
            best = f;
          }
        }
      }
    }
    pruneMappingFiles(best == null ? Long.MIN_VALUE : bestDay, clock.getAsLong());
    if (best == null) return;
    try (InputStream in = best.openInputStream(); InputStream z = new GZIPInputStream(in)) {
      ItemCatalog c = ItemCatalog.parse(new String(z.readAllBytes(), StandardCharsets.UTF_8));
      if (c.size() > 0) {
        catalog = c;
        catalogDay = bestDay;
      }
    } catch (IOException | RuntimeException e) {
      log.accept("EVI prices: the saved item list is damaged; fetching a new one");
      best.deleteIfExists();
    }
  }

  private void saveMappingCache(String body, long day) {
    try {
      root.createDirectories();
      ArchiveFiles.writeNew(root.joinSegment("mapping-" + day + ".json.gz"), HourlyArchive.gzip(body));
      pruneMappingFiles(day, clock.getAsLong());
    } catch (IOException e) {
      log.accept("EVI prices: could not save the item list: " + e.getMessage());
    }
  }

  /**
   * Keeps one saved item list: removes lists older than {@code keepDay}, and temporary files a crash left behind while
   * saving one (older than {@link HourlyArchive#STALE_TMP_MS}; a live save's own is never that old).
   */
  private void pruneMappingFiles(long keepDay, long nowMs) throws IOException {
    if (!root.isDirectory()) return;
    try (Stream<Filepath> s = root.walk(1)) {
      for (Filepath f : (Iterable<Filepath>) s::iterator) {
        Matcher m = MAPPING.matcher(f.getFileName());
        if (m.matches() && Long.parseLong(m.group(1)) < keepDay) f.deleteIfExists();
        else if (MAPPING_TMP.matcher(f.getFileName()).matches() && nowMs - ArchiveFiles.modifiedMs(f) > HourlyArchive.STALE_TMP_MS) f.deleteIfExists();
      }
    }
  }
}

package com.evi.live.market;

import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.IOException;
import java.io.StringReader;
import java.util.TreeMap;
import java.util.regex.Pattern;

/**
 * Turns the Wiki's v2 response bodies into the plugin's types, ROUNDING EVERY NUMBER HALF-UP ON ARRIVAL.
 *
 * <p>Why on arrival: v2's aggregates carry up to two decimals while every calibrated constant in the engine was
 * measured on v1's integers, and v1 is exactly {@code Math.round(v2)}. Rounding before anything is stored or
 * computed keeps the stored basis identical to v1 and to the bridge's archive, so nothing downstream ever sees a
 * fraction -- and nothing fractional can reach a quote ({@code Suggestion.buyPrice} is a {@code long}, and the
 * outcome tracker matches prices by exact equality).
 *
 * <p>Parsed with Gson's STREAMING reader, so a 340 KB {@code /latest} body never becomes a tree of objects. A whole
 * number stays exact as a {@code long} (prices can exceed 2^31); a number with a fraction is parsed from its text to
 * the same double JavaScript would parse it to, and rounded with {@link Math#round(double)}.
 * No networking here: {@link WikiPriceClient} fetches, this only reads text.
 */
public final class WikiJson {
  private WikiJson() {}

  private static final Pattern INTEGER = Pattern.compile("-?\\d{1,18}");

  /**
   * A JSON number's text, rounded half-up: {@code "102.5"} is 103, {@code "102.49"} is 102, {@code "-2.5"} is -2,
   * exactly as JavaScript's {@code Math.round} (Java's {@code Math.round(double)} is {@code floor(x + 0.5)}).
   */
  static long rounded(String number) {
    if (INTEGER.matcher(number).matches()) return asJavaScript(Long.parseLong(number));
    return Math.round(Double.parseDouble(number));
  }

  /** Beyond 2^53 JavaScript holds a whole number as the NEAREST double ({@code 9007199254740993} reads as {@code ...992});
   *  a long converts to that same double. No GE price comes near this; it keeps the two readers identical anyway. */
  static long asJavaScript(long whole) {
    return whole > MAX_SAFE || whole < -MAX_SAFE ? (long) (double) whole : whole;
  }

  private static final long MAX_SAFE = 9007199254740991L;

  /**
   * The next JSON number, rounded half-up. A whole number is read by Gson's own long path, which allocates nothing (the
   * plugin's archive files hold only whole numbers and are read by the hundred); a number with a fraction makes
   * {@code nextLong} refuse WITHOUT consuming it, and it is then read as text and rounded by {@link #rounded}.
   */
  static long readRounded(JsonReader r) throws IOException {
    try {
      return asJavaScript(r.nextLong());
    } catch (NumberFormatException fraction) {
      return rounded(r.nextString());
    }
  }

  /** A JSON number's text as a long when it is a whole number; null for a fraction or anything out of range. */
  static Long integral(String number) {
    if (INTEGER.matcher(number).matches()) return Long.parseLong(number);
    double d;
    try {
      d = Double.parseDouble(number);
    } catch (NumberFormatException e) {
      return null;
    }
    if (Double.isNaN(d) || Double.isInfinite(d) || d != Math.floor(d) || Math.abs(d) > 9007199254740991d) return null;
    return (long) d;
  }

  /**
   * An object key as an item id, or null. The Wiki's keys are item ids in decimal; JavaScript orders such keys
   * numerically, which is the order the archive line is written in. A key that is not a canonical id (no sign, no
   * leading zero, at most 2^31-1) cannot be an item, and is skipped.
   */
  static Integer itemId(String key) {
    int v = itemIdOrMinus(key);
    return v < 0 ? null : v;
  }

  /** {@link #itemId} without boxing: the id, or -1. Hand-written (no regex) because it runs once per row of every hour read. */
  static int itemIdOrMinus(String key) {
    int n = key.length();
    if (n == 0 || n > 10 || (n > 1 && key.charAt(0) == '0')) return -1;
    long v = 0;
    for (int i = 0; i < n; i++) {
      char c = key.charAt(i);
      if (c < '0' || c > '9') return -1;
      v = v * 10 + (c - '0');
    }
    return v > Integer.MAX_VALUE ? -1 : (int) v;
  }

  /**
   * A {@code /1h} (or {@code /5m}) body as an hour bucket: compactBucket with v1's rounding. {@code timestamp} is the
   * bucket's start in unix seconds, as the Wiki labels it; null when the body has none (nothing is stored then,
   * as priceArchive.mjs stores only a safe-integer ts). A {@code null} row is skipped ({@code if (!x) continue});
   * an average that is null or absent stays absent; a volume that is null or absent is 0.
   */
  public static HourBucket hour(String body) throws IOException {
    JsonReader r = new JsonReader(new StringReader(body));
    Long ts = null;
    TreeMap<Integer, long[]> rows = new TreeMap<>();
    r.beginObject();
    while (r.hasNext()) {
      String name = r.nextName();
      if ("timestamp".equals(name) && r.peek() == JsonToken.NUMBER) {
        ts = integral(r.nextString());
      } else if ("data".equals(name) && r.peek() == JsonToken.BEGIN_OBJECT) {
        r.beginObject();
        while (r.hasNext()) {
          Integer id = itemId(r.nextName());
          if (id == null || r.peek() != JsonToken.BEGIN_OBJECT) {
            r.skipValue();
            continue;
          }
          long[] row = {HourBucket.NONE, 0, HourBucket.NONE, 0};
          r.beginObject();
          while (r.hasNext()) {
            String field = r.nextName();
            int k = "avgHighPrice".equals(field) ? 0 : "highPriceVolume".equals(field) ? 1 : "avgLowPrice".equals(field) ? 2
              : "lowPriceVolume".equals(field) ? 3 : -1;
            if (k < 0 || r.peek() != JsonToken.NUMBER) {
              r.skipValue(); // an absent or null field keeps its default: NONE for a price, 0 for a volume
              continue;
            }
            row[k] = readRounded(r);
          }
          r.endObject();
          rows.put(id, row); // a repeated key: the last one wins, as in JSON.parse
        }
        r.endObject();
      } else {
        r.skipValue();
      }
    }
    r.endObject();
    return ts == null ? null : HourBucket.of(ts, rows);
  }

  /**
   * A {@code /latest} body: each item's last instant-buy ({@code high}) and instant-sell ({@code low}) price and when
   * they printed. Integers on both API versions, rounded anyway so the rule has no exceptions.
   */
  public static LatestPrices latest(String body) throws IOException {
    JsonReader r = new JsonReader(new StringReader(body));
    TreeMap<Integer, LatestPrices.Quote> quotes = new TreeMap<>();
    r.beginObject();
    while (r.hasNext()) {
      String name = r.nextName();
      if (!"data".equals(name) || r.peek() != JsonToken.BEGIN_OBJECT) {
        r.skipValue();
        continue;
      }
      r.beginObject();
      while (r.hasNext()) {
        Integer id = itemId(r.nextName());
        if (id == null || r.peek() != JsonToken.BEGIN_OBJECT) {
          r.skipValue();
          continue;
        }
        long[] q = {HourBucket.NONE, HourBucket.NONE, HourBucket.NONE, HourBucket.NONE};
        r.beginObject();
        while (r.hasNext()) {
          String field = r.nextName();
          int k = "high".equals(field) ? 0 : "highTime".equals(field) ? 1 : "low".equals(field) ? 2 : "lowTime".equals(field) ? 3 : -1;
          if (k < 0 || r.peek() != JsonToken.NUMBER) {
            r.skipValue();
            continue;
          }
          q[k] = readRounded(r);
        }
        r.endObject();
        quotes.put(id, new LatestPrices.Quote(q[0], q[1], q[2], q[3]));
      }
      r.endObject();
    }
    r.endObject();
    return new LatestPrices(quotes);
  }
}

package com.evi.live.market;

import java.io.IOException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BooleanSupplier;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.BufferedSource;

/**
 * THE PLUGIN'S ONLY NETWORK CLASS. Every request EVI makes is made here, and only to the OSRS Wiki's public real-time
 * prices API, {@code https://prices.runescape.wiki/api/v2/osrs/}.
 *
 * <p>What it can ask for is fixed by the method list, not by a caller: {@link #latest()}, {@link #mapping()} and
 * {@link #hour(long)}. All three are ALL-ITEMS endpoints, the same requests for every player, so the Wiki learns
 * nothing about which items EVI is looking at. Nothing about the player is ever sent: the only variable part of any
 * URL is the hour's own timestamp, and the User-Agent names the plugin, its version and its public source page --
 * no account, name, cash, offer or trade history, in the URL, the headers or the User-Agent.
 *
 * <p>How it asks:
 * <ul>
 *   <li>through RuneLite's own injected {@link OkHttpClient}, derived with {@code newBuilder()} (never a new client),
 *       with the shared response cache turned OFF so hundreds of archive responses do not churn the 20 MB cache
 *       every other plugin uses, redirects refused, and a 20 s limit on the whole call;</li>
 *   <li>NEVER on the client thread or the Swing EDT: it refuses before sending (RuneLite's client would also throw);</li>
 *   <li>ONE request in flight at a time, across EVERY instance of this class (the guard is static, so a plugin turned
 *       off and on while a request is out cannot add a second one through a new instance): a concurrent call is
 *       refused, never queued. Spacing between requests and retries with back-off belong to the caller's scheduler
 *       ({@link PriceDataService}, which also hands its pacing to the next generation), because a wait here would
 *       need {@code Thread.sleep}, which the Hub forbids;</li>
 *   <li>a descriptive User-Agent, which is the one thing the Wiki asks of API users (generic Java agents are blocked
 *       pre-emptively). RuneLite prefixes its own {@code RuneLite/<version>} to it;</li>
 *   <li>answers above 10 MB are refused (the largest real one, {@code /mapping}, is under 1 MB).</li>
 * </ul>
 */
public final class WikiPriceClient {
  public static final String HOST = "prices.runescape.wiki";
  static final String BASE_PATH = "/api/v2/osrs/";
  static final long MAX_BYTES = 10_000_000L;
  static final long CALL_TIMEOUT_SECONDS = 20;
  /**
   * The plugin's version as it identifies itself. Must equal {@code version} in build.gradle and
   * runelite-plugin.properties; {@code MarketIntentTest.oneNetworkClass} fails the build when it does not, so it cannot drift
   * the way an older User-Agent version once did.
   */
  public static final String VERSION = "4.0.0";
  /** Where the source lives: the contact point the Wiki asks for, and nothing that is not already public. */
  static final String HOME = "https://github.com/therealLeEvi/evi-live-plugin";

  /** The User-Agent for one purpose: {@code EVI-Live/<version> (<what>; <purpose>; +<home>)}. */
  static String userAgent(String purpose) {
    return "EVI-Live/" + VERSION + " (RuneLite plugin; " + purpose + "; +" + HOME + ")";
  }

  /** The derived client (package-private so a test can read its settings: no cache, no redirects, the call limit). */
  final OkHttpClient http;
  private final BooleanSupplier forbiddenThread;
  /** One request in flight for the whole plugin, not per instance: see the class comment. */
  private static final AtomicBoolean IN_FLIGHT = new AtomicBoolean();

  /**
   * @param injected        RuneLite's own OkHttpClient (injected into the plugin)
   * @param forbiddenThread true while the caller is on a thread that must never block on the network: the client
   *                        thread (the plugin passes {@code client::isClientThread}); the Swing EDT is checked here too
   */
  public WikiPriceClient(OkHttpClient injected, BooleanSupplier forbiddenThread) {
    this.http = injected.newBuilder()
      .cache(null)
      .followRedirects(false)
      .followSslRedirects(false)
      .callTimeout(CALL_TIMEOUT_SECONDS, TimeUnit.SECONDS)
      .build();
    this.forbiddenThread = forbiddenThread;
  }

  /** {@code /latest}: every item's last instant-buy and instant-sell price. About 72 KB on the wire. */
  public String latest() throws IOException {
    return get("latest", null, "live prices");
  }

  /** {@code /mapping}: every item's name, buy limit and members flag. About 140 KB on the wire. */
  public String mapping() throws IOException {
    return get("mapping", null, "item list");
  }

  /** {@code /1h?timestamp=<ts>}: one hour of every item's averages. {@code ts} must be the start of an hour (unix seconds). */
  public String hour(long ts) throws IOException {
    if (ts <= 0 || ts % 3600 != 0) throw new IllegalArgumentException("not the start of an hour: " + ts);
    return get("1h", Long.toString(ts), "hourly price history");
  }

  /** The URL each method asks for. Package-private so a test can pin every byte of it. */
  static HttpUrl url(String endpoint, String timestamp) {
    HttpUrl.Builder b = new HttpUrl.Builder().scheme("https").host(HOST).encodedPath(BASE_PATH + endpoint);
    if (timestamp != null) b.addQueryParameter("timestamp", timestamp);
    return b.build();
  }

  private String get(String endpoint, String timestamp, String purpose) throws IOException {
    if (forbiddenThread.getAsBoolean() || javax.swing.SwingUtilities.isEventDispatchThread())
      throw new IllegalStateException("EVI prices: a network request on the client thread or the Swing EDT was refused");
    if (!IN_FLIGHT.compareAndSet(false, true)) throw new IllegalStateException("EVI prices: one Wiki request at a time");
    try {
      Request request = new Request.Builder().url(url(endpoint, timestamp)).header("User-Agent", userAgent(purpose)).get().build();
      try (Response response = http.newCall(request).execute()) {
        if (response.code() != 200) throw new IOException("the Wiki answered HTTP " + response.code());
        ResponseBody body = response.body();
        if (body == null) throw new IOException("the Wiki sent no body");
        BufferedSource source = body.source();
        if (source.request(MAX_BYTES + 1)) throw new IOException("the Wiki's answer is larger than " + MAX_BYTES + " bytes");
        return source.getBuffer().readUtf8();
      }
    } finally {
      IN_FLIGHT.set(false);
    }
  }
}

package com.evi.live;
import java.util.EnumSet;
import net.runelite.api.WorldType;

public final class EconomyScopeTest {
  public static void main(String[] args) {
    if(!EconomyScope.of(EnumSet.noneOf(WorldType.class)).isEmpty())throw new AssertionError("Free worlds share ordinary economy");
    if(!EconomyScope.of(EnumSet.of(WorldType.MEMBERS,WorldType.PVP,WorldType.HIGH_RISK)).isEmpty())throw new AssertionError("Ordinary world flags must not split account history");
    for(WorldType type:new WorldType[]{WorldType.DEADMAN,WorldType.SEASONAL,WorldType.FRESH_START_WORLD,WorldType.BETA_WORLD,WorldType.NOSAVE_MODE,WorldType.TOURNAMENT_WORLD}) {
      if(EconomyScope.of(EnumSet.of(type,WorldType.MEMBERS)).isEmpty())throw new AssertionError("Special economy merged into main: "+type);
    }
    if(EconomyScope.of(EnumSet.of(WorldType.DEADMAN)).equals(EconomyScope.of(EnumSet.of(WorldType.DEADMAN,WorldType.SEASONAL))))throw new AssertionError("Seasonal and permanent modes must remain separate");
    if(EconomyScope.of(null).isEmpty())throw new AssertionError("Unknown world is not ordinary economy");
    System.out.println("PASS: ordinary-world identity continuity and special-economy separation");
  }
}

