      // the import line is shown (4.0.0): the journal's notice reaches the sidebar, and carries no bridge-era word either
      call(p, "showImportNotice", new Class<?>[]{String.class}, PluginJournal.IMPORT_MISSING_NOTICE);
      call(p, "pollSuggestion", new Class<?>[]{long.class}, 1L);
      edt();
      edt();
      String seen = visibleText(run.panel);
      for (String word : new String[]{"ridge", "ompanion", "127.0.0.1", "plugin key", "Pairing", "pairing", "scanner", "dashboard", "Local"})
        check(!seen.contains(word), "the sidebar shows bridge-era wording (\"" + word + "\"):\n" + seen);
      check(seen.contains("Connected to OSRS Wiki prices. Last update: "), "the status line names the Wiki prices:\n" + seen);
      check(seen.startsWith("EVI Live\n"), "the sidebar's title is \"EVI Live\" (no \"Local\", no non-ASCII dot):\n" + seen);
      check(seen.contains(PluginJournal.IMPORT_MISSING_NOTICE + "\n"), "the journal's import line reaches the sidebar:\n" + seen);
      // and the journal's "hide" (null) takes it away again
      call(p, "showImportNotice", new Class<?>[]{String.class}, (Object) null);
      edt();
      check(!visibleText(run.panel).contains("Import is on"), "the journal's hide must take the import line away:\n" + visibleText(run.panel));
    } finally {
      sender.shutdown();
    }
  }

  // ------------------------------------------------------------------------------------------- 3. the poll's thread

  static final String LATEST = "{\"data\":{\"554\":{\"high\":6,\"highTime\":1,\"low\":5,\"lowTime\":1}}}";
  static final String MAPPING = "[{\"id\":554,\"name\":\"Fire rune\",\"members\":false,\"limit\":25000}]";

  static void pollThread() throws Exception {
    Filepath root = TestFiles.tempDir("evi-inprocess-wiring");
    PluginJournal journal = new PluginJournal(root, System::currentTimeMillis, s -> new JsonParser().parse(s), () -> false, m -> { });
    journal.start();
    EngineFeed.Market m = new EngineFeed.Market(WikiJson.latest(LATEST), System.currentTimeMillis(), null, ItemCatalog.parse(MAPPING), null, null,
      Long.MIN_VALUE, 140, InProcessEngine.BASIS_HOURS + 1, 0, 0, 1, 0, true, 120);
    EngineFeed.MarketSource market = new EngineFeed.MarketSource() {
      @Override public EngineFeed.Market market(long nowMs) {
        return m;
      }

      @Override public CompletableFuture<List<HourBucket>> hoursFrom(long fromTs) {
        return CompletableFuture.completedFuture(new ArrayList<>());
      }
    };
    // The plugin's own guard: true on the client thread or the EDT. Here a thread named "client" stands for the client thread.
    InProcessEngine engine = new InProcessEngine(root, EngineFeed.journalOf(() -> journal), market, s -> new JsonParser().parse(s), x -> { },
      () -> "client".equals(Thread.currentThread().getName()) || SwingUtilities.isEventDispatchThread(), () -> null);
    try {
      Run run = inProcess(engine);
      Throwable[] failed = {null};
      Thread client = new Thread(() -> {
        try {
          for (int i = 0; i < 20 && engine.decisions() == 0; i++) call(run.plugin, "pollSuggestion", new Class<?>[]{long.class}, 1L);
        } catch (Throwable t) {
          failed[0] = t;
        }
      }, "client");
      client.start();
      client.join(60_000);
      check(failed[0] == null, "the poll threw: " + failed[0]);
      check(engine.decisions() > 0, "decide never ran");
      check(InProcessEngine.THREAD_NAME.equals(engine.lastDecidedOn()), "decide ran on '" + engine.lastDecidedOn() + "', not " + InProcessEngine.THREAD_NAME);
      edt();
      edt();
      String note = ((javax.swing.JTextArea) get(run.panel, "backfillNote")).getText();
      check(("Loading price history: 140 of " + InProcessEngine.BASIS_HOURS + " hours. Buy suggestions start when it's done.").equals(note)
        && ((JComponent) get(run.panel, "backfillNote")).isVisible(), "the price-history line in the sidebar: " + note);
      String seen = visibleText(run.panel);
      check(seen.contains(EviLivePlugin.BUYS_PAUSED), "with no sell to show, the card says buys are paused (never \"nothing passes your settings\"):\n" + seen);
      check(!seen.contains("passes your settings"), "the no-suggestion sentence must not claim the buy tiers were searched");
    } finally {
      engine.shutdown();
      journal.shutdown();
      journal.awaitIdle(30_000);
      root.deleteRecursively();
    }

    // never blocking: an engine that does not answer leaves the poll at WAIT_MS and the sidebar exactly as it was
    CompletableFuture<InProcessEngine.Answer> never = new CompletableFuture<>();
    Run stuck = inProcess((q, at) -> never);
    stuck.panel.suggestion("before");
    edt();
    long t0 = System.nanoTime();
    Thread poll = new Thread(() -> {
      try {
        call(stuck.plugin, "pollSuggestion", new Class<?>[]{long.class}, 1L);
      } catch (Exception ignored) {
        // reported by the check below
      }
    }, "evi-local-sender");
    poll.setDaemon(true);
    poll.start();
    poll.join(InProcessTransport.WAIT_MS + 3_000);
    long ms = (System.nanoTime() - t0) / 1_000_000;
    check(!poll.isAlive() && ms < InProcessTransport.WAIT_MS + 1_000, "the poll waited " + ms + " ms for a stuck engine" + (poll.isAlive() ? " and is still waiting" : ""));
    edt();
    check(visibleText(stuck.panel).contains("before"), "a pending answer must leave the sidebar as it was:\n" + visibleText(stuck.panel));

    // a late answer is shown on the next poll for the same query
    String body = recordedBody();
    AtomicLong asked = new AtomicLong();
    Run late = inProcess((q, at) -> {
      asked.incrementAndGet();
      CompletableFuture<InProcessEngine.Answer> f = new CompletableFuture<>();
      CompletableFuture.delayedExecutor(InProcessTransport.WAIT_MS + 300, TimeUnit.MILLISECONDS)
        .execute(() -> f.complete(new InProcessEngine.Answer(q, body, null, null, true, at)));
      return f;
    });
    call(late.plugin, "pollSuggestion", new Class<?>[]{long.class}, 1L);
    check(((SuggestionCache) get(late.plugin, "suggestionCache")).get() == null, "nothing drawn while the first answer is still coming");
    CompletableFuture.runAsync(() -> { }, CompletableFuture.delayedExecutor(600, TimeUnit.MILLISECONDS)).get();
    call(late.plugin, "pollSuggestion", new Class<?>[]{long.class}, 1L);
    check(((SuggestionCache) get(late.plugin, "suggestionCache")).get() != null && asked.get() == 2, "the late answer is shown on the next poll");

    // an answer slower than REUSE_MS is still shown: it is timed from its ARRIVAL, not from the poll that asked (review, 10 Oct)
    AtomicLong clk = new AtomicLong(1_000);
    CompletableFuture<InProcessEngine.Answer> slow = new CompletableFuture<>();
    AtomicLong slowAsks = new AtomicLong();
    InProcessTransport slowT = new InProcessTransport((q, at) -> slowAsks.incrementAndGet() == 1 ? slow : new CompletableFuture<>(), clk::get);
    check(slowT.get("q") == null && slowT.lastGetStatus() == InProcessTransport.PENDING, "the slow answer is not in yet");
    clk.addAndGet(InProcessTransport.REUSE_MS + 5_000);
    slow.complete(new InProcessEngine.Answer("q", body, null, null, true, 1_000));
    check(body.equals(slowT.get("q")), "an answer that took longer than REUSE_MS is shown on the next poll, not dropped as stale on landing");
    clk.addAndGet(InProcessTransport.REUSE_MS + 1);
    check(slowT.get("q") == null, "and it still ages out REUSE_MS after it landed");

    // the status line stops saying "Connected" (and the dot stops being green) once the prices are stale (review, 10 Oct)
    long got = 1_000_000_000L;
    check(EviLivePlugin.inProcessStatus(got, got + 60_000L).startsWith("Connected to OSRS Wiki prices. Last update: "), "fresh: connected");
    String old = EviLivePlugin.inProcessStatus(got, got + InProcessEngine.STALE_PRICES_MS + 1);
    check(old.startsWith("OSRS Wiki prices last arrived at ") && !old.startsWith("Connected"), "stale: says when they last arrived, not connected: " + old);
    check(EviLivePlugin.inProcessStatus(0, got).equals(EviLivePlugin.IN_PROCESS_WAITING), "none yet: waiting");
  }

  // ------------------------------------------------------------------------------------------- 4. one voice per offer

  static EviLivePlugin.RelistAdvice[] wire(List<AdviceNote> notes) {
    EviLivePlugin.RelistAdvice[] out = new EviLivePlugin.RelistAdvice[notes.size()];
    for (int i = 0; i < out.length; i++) {
      // through JSON, exactly as the plugin parses the engine's body
      com.google.gson.JsonElement o = com.evi.live.engine.ResponseJson.note(notes.get(i));
      out[i] = new Gson().fromJson(o, EviLivePlugin.RelistAdvice.class);
    }
    return out;
  }

  static final java.util.Set<String> PRICE_LABELS = new java.util.HashSet<>(java.util.Arrays.asList("Priced over market", "Not selling", "Market moved away"));

  static void oneVoice() throws Exception {
    int item = 4151; // taxed, so break-even sits above what was paid
    long price = 1_000_000;
    int cases = 0, overlapInBridge = 0, relistVoice = 0, driftVoice = 0, belowBreakEvenSilenced = 0, silentBoth = 0;
    for (double gap : new double[]{0.003, 0.01, 0.016, 0.03, 0.045, 0.049, 0.05, 0.051, 0.06, 0.1, 0.25}) {
      long market = Math.round(price * (1 - gap));
      for (Double paidShare : new Double[]{null, 0.5, 0.9, 0.95, 0.97, 0.99, 1.05}) {
        Double paid = paidShare == null ? null : price * paidShare;
        for (double minutes : new double[]{5, 14, 15, 30, 200, 359, 360, 2000}) {
          for (double target : new double[]{120, 1440}) {
            cases++;
            List<AdviceNote> notes = RelistProbe.notes(item, "Abyssal whip", price, 10, market, paid, minutes, target);
            EviLivePlugin.RelistAdvice[] advice = wire(notes);
            Suggestion live = new Suggestion();
            live.itemId = item;
            live.buyPrice = market;
            live.sellPrice = market;
            Map<String, Long> breakEven = new HashMap<>();
            Long be = paid == null ? null : Tax.breakEvenSellPrice(item, paid);
            if (be != null) breakEven.put(String.valueOf(item), be);
            List<EviLivePlugin.ActiveOffer> offers = Collections.singletonList(new EviLivePlugin.ActiveOffer(item, price, false, "Abyssal whip", 10));
            List<EviLivePlugin.AdviceCard> one = EviLivePlugin.offerCards(offers, new Suggestion[]{live}, null, advice, breakEven, true);
            List<EviLivePlugin.AdviceCard> two = EviLivePlugin.offerCards(offers, new Suggestion[]{live}, null, advice, breakEven, false);
            String where = "gap " + gap + ", paid " + paid + ", break-even " + be + ", " + minutes + " min, pace " + target;
            int voices = 0;
            boolean drift = false;
            for (EviLivePlugin.AdviceCard c : one) if (PRICE_LABELS.contains(c.label)) {
              voices++;
              if ("Priced over market".equals(c.label)) drift = true;
            }
            check(voices <= 1, where + ": one offer got " + voices + " price sentences in IN_PROCESS mode");
            boolean below = be != null && market < be;
            if (below) check(!drift, where + ": below break-even the plugin must never add \"take the current price\"");
            if (!notes.isEmpty()) {
              check(voices == 1 && !drift, where + ": the relist sentence is the one voice when it speaks");
              relistVoice++;
            }
            // above break-even (or unknown) and silent relist: the plugin's own hint speaks exactly as before past 5%
            boolean pluginWould = (price - market) / (double) market > 0.05;
            if (notes.isEmpty() && !below) {
              check(drift == pluginWould, where + ": above break-even with relist silent, the drift hint must speak exactly as before");
              if (drift) driftVoice++;
            }
            if (notes.isEmpty() && below && pluginWould) belowBreakEvenSilenced++;
            if (voices == 0) silentBoth++;
            // BRIDGE mode is untouched: the relist cards plus the drift hint whenever it would speak, independently
            int bridgeVoices = 0;
            boolean bridgeDrift = false;
            for (EviLivePlugin.AdviceCard c : two) if (PRICE_LABELS.contains(c.label)) {
              bridgeVoices++;
              if ("Priced over market".equals(c.label)) bridgeDrift = true;
            }
            check(bridgeDrift == pluginWould && bridgeVoices == notes.size() + (pluginWould ? 1 : 0), where + ": BRIDGE mode must build the cards as before");
            if (bridgeVoices > 1) overlapInBridge++;
          }
        }
      }
    }
    check(overlapInBridge > 0, "the grid never reached an offer the two processes BOTH spoke about -- the rule is untested");
    check(relistVoice > 0 && driftVoice > 0 && belowBreakEvenSilenced > 0, "the grid must reach every voice: relist " + relistVoice + ", drift " + driftVoice
      + ", below break-even before the relist clock " + belowBreakEvenSilenced);
    // a BUY offer has no relist voice: its drift hint is unchanged in both modes
    Suggestion live = new Suggestion();
    live.itemId = item;
    live.buyPrice = 1_100_000;
    live.sellPrice = 1_100_000;
    List<EviLivePlugin.ActiveOffer> buy = Collections.singletonList(new EviLivePlugin.ActiveOffer(item, 1_000_000, true, "Abyssal whip", 3));
    for (boolean mode : new boolean[]{true, false}) {
      List<EviLivePlugin.AdviceCard> cards = EviLivePlugin.offerCards(buy, new Suggestion[]{live}, null, null, Collections.singletonMap(String.valueOf(item), 2_000_000L), mode);
      check(cards.size() == 1 && "Priced under market".equals(cards.get(0).label), "a buy offer's drift hint, oneVoice=" + mode);
    }
    System.out.println("  one voice: " + cases + " sell offers -- relist the voice in " + relistVoice + ", the plugin's hint in " + driftVoice
      + ", both silent in " + silentBoth + " (" + belowBreakEvenSilenced + " below break-even inside the relist clock's first 15 minutes or under 1.5%),"
      + " and " + overlapInBridge + " where BRIDGE mode still gives two");
  }
}

package com.evi.live;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import net.runelite.api.Client;

/**
 * Fake widget/client only; never launches a game client and never dispatches a real keyboard or
 * mouse event -- setOnOpListener/setOnKeyListener calls are captured as plain data
 * (EviLiveSuggestionTest.FakeWidget.onOpArgs/onKeyArgs), never invoked. Covers
 * SuggestionItemSelectWidget: the same visibility gate the row highlight and hint widget share (the
 * display toggle, a GE slot open, NOT already at the quantity/price prompt, a cached suggestion,
 * the suggested item not already selected), plus its own gate on the item-search results widget
 * actually existing (search genuinely open). Covers that update() creates exactly three child
 * widgets (a clickable backdrop, a text label, an item icon) wired with the exact script/argument
 * values Flipping Copilot's own published source uses for its equivalent row (see the widget's own
 * class doc for where that came from and why), that repeated updates for the same item reuse those
 * three widgets rather than creating duplicates, that a changed suggested item updates them in
 * place (still exactly three), and that every gating condition drops the widget references without
 * creating anything. Reuses EviLiveSuggestionTest's FakeClient/FakeWidget/suggestion() fixtures.
 */
public class EviLiveItemSelectWidgetTest {
  static void check(boolean value, String message) { if (!value) throw new AssertionError(message); }

  static void set(Object target, String name, Object value) throws Exception {
    Field f = target.getClass().getDeclaredField(name);
    f.setAccessible(true);
    f.set(target, value);
  }

  public static void main(String[] args) throws Exception {
    EviLiveSuggestionTest.FakeClient fc = new EviLiveSuggestionTest.FakeClient();
    fc.inputType = 0; // item-picking phase, not the quantity/price prompt
    Client client = fc.proxy();
    GEOffer geOffer = new GEOffer();
    set(geOffer, "client", client);
    SuggestionCache cache = new SuggestionCache();
    EviLiveConfig enabled = (EviLiveConfig) Proxy.newProxyInstance(EviLiveConfig.class.getClassLoader(), new Class[]{EviLiveConfig.class},
      (p, m, a) -> "showSuggestionHint".equals(m.getName()) ? Boolean.TRUE : null);

    SuggestionItemSelectWidget widget = new SuggestionItemSelectWidget();
    set(widget, "client", client);
    set(widget, "geOffer", geOffer);
    set(widget, "suggestionCache", cache);
    set(widget, "config", enabled);

    // -- Gating: none of these must create anything. --
    widget.update();
    check(fc.searchResults == null, "sanity: no search-results widget wired up yet");

    fc.searchResults = new EviLiveSuggestionTest.FakeWidget();
    widget.update();
    check(fc.searchResults.createdChildren.isEmpty(), "No GE slot open: nothing must be created");

    fc.openSlotVarbit = 1;
    widget.update();
    check(fc.searchResults.createdChildren.isEmpty(), "No cached suggestion: nothing must be created");

    cache.set(EviLiveSuggestionTest.suggestion(1, "buy", 100, 50, 65));
    // The real quantity/price prompt: already past item-picking. An open prompt is an ACTIVE
    // chatbox input (non-zero) whose title names a GE prompt -- the input type alone stopped
    // meaning that on 30 Sept 2026, when the price prompt's own value went from 7 to 30.
    fc.inputType = 7;
    fc.chatboxTitle.text = "Set a price for each item:";
    // A DIFFERENT item from the suggested one (1), deliberately: currentItemId == s.itemId would
    // clear the row for its own reason and the prompt gate would prove nothing. An open prompt
    // needs a chosen item, since the stale title alone also survives into the item search.
    fc.currentItemId = 2;
    widget.update();
    check(fc.searchResults.createdChildren.isEmpty(), "Already at the quantity/price prompt: nothing must be created");
    fc.inputType = 30; // the post-update value: it must gate the same way
    widget.update();
    check(fc.searchResults.createdChildren.isEmpty(), "A renumbered prompt is still a prompt: nothing must be created");
    fc.inputType = 0;
    fc.chatboxTitle.text = "";

    fc.currentItemId = 1; // the suggested item is already the one selected
    widget.update();
    check(fc.searchResults.createdChildren.isEmpty(), "Suggested item already selected: nothing left to point at, nothing created");
    fc.currentItemId = -1;

    EviLiveSuggestionTest.FakeWidget savedResults = fc.searchResults;
    fc.searchResults = null;
    widget.update();
    check(savedResults.createdChildren.isEmpty(), "No search-results widget (search not open yet): nothing must be created");
    fc.searchResults = savedResults;

    EviLiveConfig disabled = (EviLiveConfig) Proxy.newProxyInstance(EviLiveConfig.class.getClassLoader(), new Class[]{EviLiveConfig.class},
      (p, m, a) -> Boolean.FALSE);
    set(widget, "config", disabled);
    widget.update();
    check(fc.searchResults.createdChildren.isEmpty(), "Display toggle off: nothing must be created");
    set(widget, "config", enabled);

    // -- The actual creation, with everything eligible. --
    widget.update();
    check(fc.searchResults.createdChildren.size() == 3, "Must create exactly three child widgets: a clickable row, a text label, and an item icon");
    EviLiveSuggestionTest.FakeWidget row = fc.searchResults.createdChildren.get(0);
    EviLiveSuggestionTest.FakeWidget text = fc.searchResults.createdChildren.get(1);
    EviLiveSuggestionTest.FakeWidget icon = fc.searchResults.createdChildren.get(2);
    check(row.onOpArgs != null && row.onOpArgs.length == 3 && (int) row.onOpArgs[0] == 754 && (int) row.onOpArgs[1] == 1 && (int) row.onOpArgs[2] == 84,
      "The clickable row must be wired with the exact script/itemId/arg triple a genuine GE search-result row carries (on click)");
    check(row.onKeyArgs != null && row.onKeyArgs.length == 3 && (int) row.onKeyArgs[0] == 754 && (int) row.onKeyArgs[1] == 1 && (int) row.onKeyArgs[2] == -2147483640,
      "The clickable row must be wired with the exact script/itemId/arg triple a genuine GE search-result row carries (on Enter/key-select)");
    check(text.text != null && text.text.contains("EVI item:") && text.text.contains("Test item"), "The label must name the suggested item: " + text.text);
    check(icon.itemId == 1, "The icon must be the suggested item's own icon");
    // Placement: one row under the top line (where the game's previous search and Copilot's own row
    // sit), in fixed high child slots so an indexed write to slots 0-3 can never replace them.
    check(row.originalY == 32 && text.originalY == 32, "The row must sit one row below the top line, with or without other plugins: " + row.originalY);
    check(fc.searchResults.children.get(60) == row && fc.searchResults.children.get(61) == text && fc.searchResults.children.get(62) == icon,
      "The row, text and icon must occupy their fixed slots 60-62");
    check(!row.hidden, "With nothing typed, the row must be visible");

    // -- Reuse: updating again for the SAME item must not create more widgets. --
    widget.update();
    check(fc.searchResults.createdChildren.size() == 3, "Repeated updates for the same item must reuse the same three widgets, not duplicate them");

    // -- Another plugin (or the game rebuilding the list) takes over a slot: the row must come back. --
    fc.searchResults.children.put(60, new EviLiveSuggestionTest.FakeWidget());
    widget.update();
    check(fc.searchResults.createdChildren.size() == 6, "A replaced slot must be noticed and the row recreated, not left detached and invisible");
    row = fc.searchResults.createdChildren.get(3);
    text = fc.searchResults.createdChildren.get(4);
    icon = fc.searchResults.createdChildren.get(5);
    check(icon.itemId == 1 && row.onOpArgs != null && (int) row.onOpArgs[1] == 1, "The recreated row must point at the suggested item again");
    // Writes by index into the top line's slots (what Copilot does) must not disturb it.
    fc.searchResults.children.put(0, new EviLiveSuggestionTest.FakeWidget());
    fc.searchResults.children.put(3, new EviLiveSuggestionTest.FakeWidget());
    widget.update();
    check(fc.searchResults.createdChildren.size() == 6, "Writes to slots 0-3 must leave the row alone");

    // -- Typing: the live results own that space, so the row hides, and returns when cleared. --
    fc.typedSearch = "rune";
    widget.update();
    check(row.hidden && text.hidden && icon.hidden, "While a search is typed, the row must be hidden");
    check(fc.searchResults.createdChildren.size() == 6, "Typing must not create anything");
    fc.typedSearch = "";
    widget.update();
    check(!row.hidden && !text.hidden && !icon.hidden, "With the search box empty again, the row must be visible again");

    // -- Item change while still open: still exactly three widgets, but updated to the new item. --
    cache.set(EviLiveSuggestionTest.suggestion(2, "buy", 50, 200, 260));
    widget.update();
    check(fc.searchResults.createdChildren.size() == 6, "A changed suggested item must update the existing three widgets, not create new ones");
    check(row.onOpArgs != null && (int) row.onOpArgs[1] == 2, "The row's click target must switch to the new suggested item");
    check(icon.itemId == 2, "The icon must switch to the new suggested item");

    // -- Clearing: once the item becomes the one selected, references are dropped -- a later fresh
    // eligibility (a different, not-yet-selected suggestion) must create a fresh set of widgets. --
    fc.currentItemId = 2;
    widget.update();
    check(fc.searchResults.createdChildren.size() == 6, "Selecting the item must not itself create anything more");
    fc.currentItemId = -1;
    cache.set(EviLiveSuggestionTest.suggestion(3, "buy", 20, 400, 480));
    widget.update();
    check(fc.searchResults.createdChildren.size() == 9, "After the widget was cleared (item selected), a new eligible suggestion must create a fresh set of widgets");

    System.out.println("PASS: placement one row below the top line in fixed slots 60-62; recreation when a slot is taken over; untouched by writes to slots 0-3; hidden while typing and back when cleared; gating on the display toggle, GE-slot-open, the quantity/price prompt, a cached suggestion, an already-selected item, and the search-results widget existing; exactly-three-widget creation wired with Flipping Copilot's own verified script/argument values; reuse across repeated updates and item changes; and fresh creation after a clear");
  }
}

