    Suggestion clear=new Suggestion();
    clear.itemId=11832;clear.name="Bandos chestplate";clear.action="buy";clear.quantity=1;
    clear.buyPrice=20000000;clear.sellPrice=21000000;clear.expectedProfit=580000L;
