      EviLivePlugin.AdviceCard mist2=new EviLivePlugin.AdviceCard(mist.level,mist.label,mist.name,mist.figures,mist.message,22,"a1-5");
      hp.advice(List.of(offer,mist2,oldBridge,teak));
      SwingUtilities.invokeAndWait(()->{});
