      + " en-US grouping under a Dutch locale, on the card, the paragraph and the extra positions; never on a sell; nothing when unknown or past a long);"
      + " High with \"No limit\" named on the risk line, updated at once from the settings (a real ConfigManager) and the buttons; and the import line"
      + " shown only while the import is on and its file missing, gone once imported or switched off, per account, from the journal's own thread");
  }

  // ------------------------------------------------------------------------------------------- 2. total cost

  static void totalCost() throws Exception {
    check("Total 1,396,000 gp".equals(EviLivePanel.totalCost(pick("buy", 698, 2000, 2100, false))),
      "698 x 2,000 must read \"Total 1,396,000 gp\" with en-US grouping: " + EviLivePanel.totalCost(pick("buy", 698, 2000, 2100, false)));
    // Past 2^31 in the product AND in the unit price: int arithmetic would wrap to a wrong (negative) figure.
    check("Total 4,294,967,296,000 gp".equals(EviLivePanel.totalCost(pick("buy", 2000, 2_147_483_648L, 2_200_000_000L, false))),
      "2,000 x 2,147,483,648 must be computed in long: " + EviLivePanel.totalCost(pick("buy", 2000, 2_147_483_648L, 2_200_000_000L, false)));
    check("Total 46,340 gp".equals(EviLivePanel.totalCost(pick("buy", 46340, 1, 2, false))), "a 1 gp item: quantity times one");
    // Never on a sell or holding, never for an unknown quantity or price, never a wrapped figure.
    check(EviLivePanel.totalCost(pick("sell", 698, 2000, 2100, false)) == null, "a SELL (holding) card must carry no total");
    check(EviLivePanel.totalCost(pick(null, 698, 2000, 2100, false)) == null, "no action named: no total");
    check(EviLivePanel.totalCost(pick("buy", 0, 2000, 2100, false)) == null, "quantity unknown (0): no total");
    check(EviLivePanel.totalCost(pick("buy", -5, 2000, 2100, false)) == null, "a negative quantity: no total");
    check(EviLivePanel.totalCost(pick("buy", 698, 0, 2100, false)) == null, "price unknown (0): no total");
    check(EviLivePanel.totalCost(pick("buy", Integer.MAX_VALUE, 5_000_000_000L, 1, false)) == null,
      "a product past a long must show nothing, never a wrapped figure: " + EviLivePanel.totalCost(pick("buy", Integer.MAX_VALUE, 5_000_000_000L, 1, false)));
    check(EviLivePanel.totalCost(null) == null, "no suggestion: no total");

    EviLivePanel panel = panel(r -> { });
    JPanel card = (JPanel) get(panel, "suggestionCard");
    EviTheme.Palette p = EviTheme.palette();
    // The card, with a verdict.
    panel.suggestion(pick("buy", 698, 2000, 2100, true), "prose");
    edt();
    JLabel total = label(card, "Total 1,396,000 gp");
    check(total != null, "the BUY card must state \"Total 1,396,000 gp\": " + labels(card));
    check(total.getForeground().equals(p.muted), "the total is a plain figure in the muted text colour, not a verdict colour: " + total.getForeground());
    // A sell card: no total at all.
    panel.suggestion(pick("sell", 698, 2000, 2100, true), "prose");
    edt();
    check(labels(card).stream().noneMatch(t -> t != null && t.startsWith("Total")), "a SELL card must carry no total: " + labels(card));
    // A buy whose quantity is unknown: the card is drawn, without a total.
    panel.suggestion(pick("buy", 0, 2000, 2100, true), "prose");
    edt();
    check(labels(card).stream().noneMatch(t -> t != null && t.startsWith("Total")), "a buy with no quantity must carry no total: " + labels(card));
    // The paragraph (no verdict from the bridge): the total on its own last line, for a buy only.
    JTextArea prose = (JTextArea) get(panel, "suggestion");
    panel.suggestion(pick("buy", 698, 2000, 2100, false), "Test item x698");
    edt();
    check("Test item x698\nTotal 1,396,000 gp".equals(prose.getText()), "a buy drawn as a paragraph must end with its total: " + prose.getText());
    panel.suggestion(pick("sell", 698, 2000, 2100, false), "Test item x698");
    edt();
    check("Test item x698".equals(prose.getText()), "a sell drawn as a paragraph must carry no total: " + prose.getText());
    panel.suggestion(pick("buy", 698, 2000, 2100, false), "");
    edt();
    check("No suggestion yet.".equals(prose.getText()), "no paragraph at all: the placeholder, with no stray total: " + prose.getText());
    // The extra positions ("Also worth buying") are buy cards too.
    JPanel also = (JPanel) get(panel, "alsoList");
    panel.alsoSuggested(Arrays.asList(pick("buy", 10, 1_500_000, 1_600_000, false), pick("buy", 0, 7, 8, false)));
    edt();
    check(labels(also).contains("Total 15,000,000 gp"), "an extra position must state its total: " + labels(also));
    check(labels(also).stream().filter(t -> t != null && t.startsWith("Total")).count() == 1, "only the extra with a known quantity carries a total: " + labels(also));
  }

  // --------------------------------------------------------------------------------- 3. High with No limit

  // The line is part of the hidden Risk level section since 7 Oct 2026 (EviLiveRiskSkipTest.hiddenLevels proves it is
  // not drawn); these checks keep its dormant wiring whole for when the levels return. No odds, permanently.
  static final String HIGH_NO_LIMIT = "Adds gear whose price can drop suddenly."
    + " No trade-size limit (your setting): one High trade can use most of your stack.";

  static void highWithNoLimit() throws Exception {
    check(HIGH_NO_LIMIT.equals(RiskLevel.HIGH.aim(MaxTradeShare.OFF)), "High + No limit: " + RiskLevel.HIGH.aim(MaxTradeShare.OFF));
    // Every other combination is the plain aim, word for word.
    for (RiskLevel level : RiskLevel.values()) {
      for (MaxTradeShare share : new MaxTradeShare[]{null, MaxTradeShare.OFF, MaxTradeShare.TENTH, MaxTradeShare.QUARTER, MaxTradeShare.THIRD, MaxTradeShare.HALF}) {
        if (level == RiskLevel.HIGH && share == MaxTradeShare.OFF) continue;
        check(level.aim().equals(level.aim(share)), level + " with " + share + " must read exactly its plain aim: " + level.aim(share));
      }
    }
    check("No limit".equals(MaxTradeShare.OFF.toString()), "the setting the line names is the one labelled \"No limit\"");

    // The FIRST frame: startUp() draws the sidebar through buildPanel() from the stored settings, so a player who
    // already chose High and No limit sees the words before touching anything.
    for (MaxTradeShare share : new MaxTradeShare[]{MaxTradeShare.OFF, MaxTradeShare.QUARTER}) {
      EviLivePlugin fresh = new EviLivePlugin();
      set(fresh, "config", new EviLiveConfig() {
        public RiskLevel riskLevelV2() {
          return RiskLevel.HIGH;
        }

        public MaxTradeShare maxTradeShare() {
          return share;
        }
      });
      AtomicReference<EviLivePanel> built = new AtomicReference<>();
      SwingUtilities.invokeAndWait(() -> built.set(fresh.buildPanel()));
      edt();
      String first = ((JTextArea) get(built.get(), "riskAim")).getText();
      check((share == MaxTradeShare.OFF ? HIGH_NO_LIMIT : RiskLevel.HIGH.aim()).equals(first),
        "startUp's first frame at High with " + share + " must read: " + first);
    }

    // Through the shipping paths: a REAL RuneLite ConfigManager (the settings panel) and the sidebar's buttons.
    net.runelite.client.eventbus.EventBus bus = new net.runelite.client.eventbus.EventBus();
    ConfigManager cm = EviLiveRiskSkipTest.realConfigManager(bus);
    EviLiveConfig real = cm.getConfig(EviLiveConfig.class);
    EviLivePlugin plugin = new EviLivePlugin();
    set(plugin, "config", real);
    set(plugin, "configManager", cm);
    EviLivePanel panel = panel(plugin::chooseRisk);
    set(plugin, "panel", panel);
    bus.register(plugin);
    JTextArea aim = (JTextArea) get(panel, "riskAim");
    // As startUp() draws it: the stored level and share (defaults Low / 25%).
    panel.riskLevel(real.riskLevelV2(), real.maxTradeShare());
    edt();
    check(RiskLevel.LOW.aim().equals(aim.getText()), "default Low / 25%: " + aim.getText());
    // Settings panel: High, then No limit -- the line follows each change at once.
    cm.setConfiguration("evilive", "riskLevelV2", RiskLevel.HIGH);
    edt();
    check(RiskLevel.HIGH.aim().equals(aim.getText()), "High with the default 25% cap names no missing limit: " + aim.getText());
    cm.setConfiguration("evilive", "maxTradeShare", MaxTradeShare.OFF);
    edt();
    check(HIGH_NO_LIMIT.equals(aim.getText()), "High, then \"No limit\" chosen in the settings: the line must name it at once: " + aim.getText());
    cm.setConfiguration("evilive", "maxTradeShare", MaxTradeShare.HALF);
    edt();
    check(RiskLevel.HIGH.aim().equals(aim.getText()), "a cap chosen again (50%) must take the words away at once: " + aim.getText());
    cm.setConfiguration("evilive", "maxTradeShare", MaxTradeShare.OFF);
    edt();
    check(HIGH_NO_LIMIT.equals(aim.getText()), "back to No limit: " + aim.getText());
    // The sidebar's buttons, with No limit still set.
    SwingUtilities.invokeAndWait(() -> EviLiveRiskSkipTest.button(panel, "Medium").doClick());
    edt();
    check(RiskLevel.MEDIUM.aim().equals(aim.getText()), "Medium pressed: No limit is only named at High: " + aim.getText());
    SwingUtilities.invokeAndWait(() -> EviLiveRiskSkipTest.button(panel, "High").doClick());
    edt();
    check(HIGH_NO_LIMIT.equals(aim.getText()), "High pressed with No limit set: the line must name it: " + aim.getText());
    // Settings panel again: the level moved away from High.
    cm.setConfiguration("evilive", "riskLevelV2", RiskLevel.LOW);
    edt();
    check(RiskLevel.LOW.aim().equals(aim.getText()), "Low chosen in the settings: " + aim.getText());
    // The line stays neutral text: no warning colour for a setting the player chose.
    check(aim.getForeground().equals(EviTheme.palette().text), "the risk line must stay in the plain text colour: " + aim.getForeground());
    // And the button tooltips stay the bare aims.
    check(RiskLevel.HIGH.aim().equals(EviLivePanel.plainTip(EviLiveRiskSkipTest.button(panel, "High").getToolTipText())), "the High button's tooltip is its plain aim");
    check(!EviLiveRiskSkipTest.nowhere.exists(), "the test ConfigManager must never write a file");
  }

  // ------------------------------------------------------------------------------------------ 1. import line

  static void importLinePanel() throws Exception {
    EviLivePanel panel = panel(r -> { });
    JTextArea note = panel.importNote;
    check(!note.isVisible() && note.getText().isEmpty(), "the import line starts hidden and empty");
    check(note.getCaret() instanceof DefaultCaret && ((DefaultCaret) note.getCaret()).getUpdatePolicy() == DefaultCaret.NEVER_UPDATE,
      "the import line must pin its caret, or every update drags the sidebar");
    panel.importNotice(PluginJournal.IMPORT_MISSING_NOTICE);
    edt();
    check(note.isVisible() && PluginJournal.IMPORT_MISSING_NOTICE.equals(note.getText()), "shown: " + note.getText());
    EviTheme.Palette p = EviTheme.palette();
    check(note.getForeground().equals(p.text), "the import line is plain text, never a warning colour: " + note.getForeground());
    panel.importNotice(null);
    edt();
    check(!note.isVisible() && note.getText().isEmpty(), "null must hide and clear it");
    panel.importNotice(PluginJournal.IMPORT_MISSING_NOTICE);
    panel.importNotice("");
    edt();
    check(!note.isVisible(), "an empty text hides it too");
    // The folder's name comes from ONE constant (Phase 7 renames it with the internalName): the words follow it, and the
    // constant must name the folder RuneLite actually uses, i.e. agree with @PluginDescriptor's internalName.
    check(("Import is on, but no file was found at " + PluginFolder.PATH + "/import/events.jsonl.").equals(PluginJournal.IMPORT_MISSING_NOTICE),
      "the exact words: " + PluginJournal.IMPORT_MISSING_NOTICE);
    check(PluginFolder.PATH.equals(".runelite/plugin-data/" + PluginFolder.INTERNAL_NAME), "the data folder's path: " + PluginFolder.PATH);
    check(PluginFolder.INTERNAL_NAME.equals(EviLivePlugin.class.getAnnotation(net.runelite.client.plugins.PluginDescriptor.class).internalName()),
      "PluginFolder.INTERNAL_NAME must equal @PluginDescriptor's internalName, or every sentence names a folder RuneLite does not use");
    try {
      String described = EviLiveConfig.class.getMethod("importBridgeHistory").getAnnotation(net.runelite.client.config.ConfigItem.class).description();
      check(("Copies once: " + PluginFolder.PATH + "/import/events.jsonl and preferences.json. Off: reads nothing.").equals(described),
        "the import setting's tooltip names the data folder from the one constant: " + described);
    } catch (NoSuchMethodException e) {
      throw new AssertionError("no importBridgeHistory setting", e);
    }
  }

  /** One packet of eight empty slots for {@code account}, as the plugin builds it. */
  static String packet(String account, String session, long seq, long ts) {
    JsonObject p = new JsonObject();
    p.addProperty("version", 1);
    p.addProperty("session", session);
    p.addProperty("account", account);
    p.addProperty("seq", seq);
    p.addProperty("ts", ts);
    p.addProperty("loggedIn", true);
    JsonArray offers = new JsonArray();
    for (int i = 0; i < 8; i++) {
      JsonObject o = new JsonObject();
      o.addProperty("slot", i);
      o.addProperty("itemId", 0);
      o.addProperty("total", 0);
      o.addProperty("filled", 0);
      o.addProperty("price", 0);
      o.addProperty("spent", 0);
      o.addProperty("offerId", session + "-e" + i);
      o.addProperty("state", "EMPTY");
      o.addProperty("name", "");
      o.addProperty("knownStart", false);
      o.addProperty("ticksToFill", -1);
      offers.add(o);
    }
    p.add("offers", offers);
    return p.toString();
  }

  /** A one-line bridge journal holding a logged-out packet of {@code account}: enough to import. */
  static void writeImportFile(Filepath root, String account) throws Exception {
    Filepath d = root.joinSegment(PluginJournal.IMPORT_DIR);
    d.createDirectories();
    String line = "{\"type\":\"packet\",\"received\":" + (T0 - 100) + ",\"packet\":{\"version\":1,\"session\":\"bridge-1\",\"account\":\"" + account
      + "\",\"seq\":1,\"ts\":" + (T0 - 200) + ",\"loggedIn\":false,\"offers\":[]}}";
    d.joinSegment(PluginJournal.IMPORT_FILE).write((line + "\n").getBytes(StandardCharsets.UTF_8));
  }

  static final class Notices {
    final List<String> seen = Collections.synchronizedList(new ArrayList<>());
    final List<String> threads = Collections.synchronizedList(new ArrayList<>());

    void accept(String s) {
      seen.add(s);
      threads.add(Thread.currentThread().getName());
    }

    List<String> list() {
      synchronized (seen) {
        return new ArrayList<>(seen);
      }
    }
  }

  static PluginJournal journal(Filepath root, AtomicBoolean enabled, Notices n) {
    PluginJournal j = new PluginJournal(root, () -> T0 + 1000, s -> new JsonParser().parse(s), enabled::get, m -> { });
    j.onImportNotice(n::accept);
    j.start();
    return j;
  }

  static void importLineJournal() throws Exception {
    final String M = PluginJournal.IMPORT_MISSING_NOTICE;
    // (a) On, no file: shown once (not again at every packet), then the file arrives: imported, and hidden.
    {
      Filepath root = TestFiles.tempDir("evi-sidebar-test");
      AtomicBoolean on = new AtomicBoolean(true);
      Notices n = new Notices();
      PluginJournal j = journal(root, on, n);
      check(j.awaitIdle(30000) && n.list().isEmpty(), "nothing is said before the first packet names an account: " + n.list());
      j.offerPacket(packet(ACCOUNT, "s1", 1, T0));
      j.offerPacket(packet(ACCOUNT, "s1", 2, T0 + 1));
      check(j.awaitIdle(30000) && n.list().equals(Collections.singletonList(M)), "on with no file: shown exactly once: " + n.list());
      writeImportFile(root, ACCOUNT);
      j.offerPacket(packet(ACCOUNT, "s1", 3, T0 + 2));
      check(j.awaitIdle(30000) && n.list().equals(Arrays.asList(M, null)), "the file arrived and was imported: the line must go: " + n.list());
      check(root.joinSegment(PluginJournal.JOURNAL_DIR).joinSegment("imported-" + ACCOUNT + ".jsonl").exists(), "setup: the import ran");
      // Imported, and then the player tidies the import file away: the line must NOT come back.
      root.joinSegment(PluginJournal.IMPORT_DIR).joinSegment(PluginJournal.IMPORT_FILE).delete();
      j.offerPacket(packet(ACCOUNT, "s1", 4, T0 + 3));
      check(j.awaitIdle(30000) && n.list().equals(Arrays.asList(M, null)), "once imported, a removed import file must not bring the line back: " + n.list());
      // Switched off and on again: the account is still imported, so nothing to say either way.
      on.set(false);
      j.importRequested();
      on.set(true);
      j.importRequested();
      check(j.awaitIdle(30000) && n.list().equals(Arrays.asList(M, null)), "an imported account never shows the line: " + n.list());
      // Another account on the same machine, not imported, with no file: the line is about it.
      j.offerPacket(packet(OTHER, "s2", 1, T0 + 4));
      check(j.awaitIdle(30000) && n.list().equals(Arrays.asList(M, null, M)), "another account still waiting for a file: shown for it: " + n.list());
      j.offerPacket(packet(ACCOUNT, "s1", 5, T0 + 5));
      check(j.awaitIdle(30000) && n.list().equals(Arrays.asList(M, null, M, null)), "back on the imported account: hidden: " + n.list());
      for (String t : n.threads) check(PluginJournal.THREAD_NAME.equals(t), "the line must be decided on the journal's thread, not '" + t + "'");
      j.shutdown();
      check(j.awaitIdle(30000), "drain");
      root.deleteRecursively();
    }
    // (b) Off: never shown, file or no file. Switched on with no packet in between: shown AT ONCE; off: gone at once.
    {
      Filepath root = TestFiles.tempDir("evi-sidebar-test");
      AtomicBoolean on = new AtomicBoolean(false);
      Notices n = new Notices();
      PluginJournal j = journal(root, on, n);
      j.offerPacket(packet(ACCOUNT, "s1", 1, T0));
      j.offerPacket(packet(ACCOUNT, "s1", 2, T0 + 1));
      check(j.awaitIdle(30000) && n.list().equals(Collections.singletonList((String) null)), "off with no file: never shown: " + n.list());
      on.set(true);
      j.importRequested();
      check(j.awaitIdle(30000) && n.list().equals(Arrays.asList(null, M)), "switched on: shown at once, before any packet: " + n.list());
      on.set(false);
      j.importRequested();
      check(j.awaitIdle(30000) && n.list().equals(Arrays.asList(null, M, null)), "switched off: gone at once: " + n.list());
      j.offerPacket(packet(ACCOUNT, "s1", 3, T0 + 2));
      check(j.awaitIdle(30000) && n.list().equals(Arrays.asList(null, M, null)), "still off: nothing new at the next packet: " + n.list());
      j.shutdown();
      check(j.awaitIdle(30000), "drain");
      root.deleteRecursively();
    }
    // (c) Already imported on disk -- the imported file alone (no counts marker), or the marker alone -- with the
    //     setting on and no import file: never shown. The line must not ask for a file the account no longer needs.
    for (String present : new String[]{"imported-" + ACCOUNT + ".jsonl", "import-done-" + ACCOUNT + ".json"}) {
      Filepath root = TestFiles.tempDir("evi-sidebar-test");
      Filepath dir = root.joinSegment(PluginJournal.JOURNAL_DIR);
      dir.createDirectories();
      dir.joinSegment(present).write((present.startsWith("imported") ? "" : "{}\n").getBytes(StandardCharsets.UTF_8));
      AtomicBoolean on = new AtomicBoolean(true);
      Notices n = new Notices();
      PluginJournal j = journal(root, on, n);
      j.offerPacket(packet(ACCOUNT, "s1", 1, T0));
      j.importRequested();
      j.offerPacket(packet(ACCOUNT, "s1", 2, T0 + 1));
      check(j.awaitIdle(30000) && !n.list().contains(M), "with only " + present + " on disk the account is imported: the line must never show: " + n.list());
      j.shutdown();
      check(j.awaitIdle(30000), "drain");
      root.deleteRecursively();
    }
    // (d) Two accounts, one imported (its marker on disk) and one still waiting for a file. A settings change decides
    //     the line for the account of the LAST packet, not the first one the journal saw -- run in both orders, so a
    //     journal stuck on either account fails. Each step waits for the journal, so the setting it reads is the one set.
    for (boolean importedFirst : new boolean[]{true, false}) {
      Filepath root = TestFiles.tempDir("evi-sidebar-test");
      Filepath dir = root.joinSegment(PluginJournal.JOURNAL_DIR);
      dir.createDirectories();
      dir.joinSegment("import-done-" + ACCOUNT + ".json").write("{}\n".getBytes(StandardCharsets.UTF_8));
      AtomicBoolean on = new AtomicBoolean(true);
      Notices n = new Notices();
      PluginJournal j = journal(root, on, n);
      String first = importedFirst ? ACCOUNT : OTHER, second = importedFirst ? OTHER : ACCOUNT;
      String forFirst = importedFirst ? null : M, forSecond = importedFirst ? M : null;
      int seq = 1;
      j.offerPacket(packet(first, "s-" + first.substring(0, 2), seq++, T0));
      j.offerPacket(packet(second, "s-" + second.substring(0, 2), seq++, T0 + 1));
      check(j.awaitIdle(30000) && n.list().equals(Arrays.asList(forFirst, forSecond)), "setup, " + first.substring(0, 2) + " then " + second.substring(0, 2) + ": " + n.list());
      on.set(false);
      j.importRequested();
      check(j.awaitIdle(30000), "drain");
      on.set(true);
      j.importRequested();
      check(j.awaitIdle(30000), "drain");
      // The last packet was the second account's, so switching off and on ends on ITS answer: off hides the line
      // (sent only if it was showing), on brings back the second account's line -- never the first account's.
      List<String> want = new ArrayList<>(Arrays.asList(forFirst, forSecond));
      if (forSecond != null) want.addAll(Arrays.asList(null, M));
      check(n.list().equals(want), "off then on after " + second.substring(0, 2) + "'s packet must decide for " + second.substring(0, 2)
        + " (" + (forSecond == null ? "hidden" : "shown") + "): " + n.list());
      // And back to the first account: its packet moves the line, and a settings change now speaks for IT.
      j.offerPacket(packet(first, "s-" + first.substring(0, 2), seq++, T0 + 2));
      check(j.awaitIdle(30000), "drain");
      if (!java.util.Objects.equals(want.get(want.size() - 1), forFirst)) want.add(forFirst);
      on.set(false);
      j.importRequested();
      check(j.awaitIdle(30000), "drain");
      if (want.get(want.size() - 1) != null) want.add(null);
      on.set(true);
      j.importRequested();
      check(j.awaitIdle(30000), "drain");
      if (forFirst != null) want.add(M);
      check(n.list().equals(want), "off then on after " + first.substring(0, 2) + "'s packet must decide for " + first.substring(0, 2)
        + " (" + (forFirst == null ? "hidden" : "shown") + "): " + n.list() + ", wanted " + want);
      // The literal sequences, so the bookkeeping above cannot drift into agreeing with a wrong journal.
      List<String> literal = importedFirst ? Arrays.asList(null, M, null, M, null) : Arrays.asList(M, null, M, null, M);
      check(n.list().equals(literal), "the full sequence, " + (importedFirst ? "imported account first" : "waiting account first") + ": " + n.list());
      j.shutdown();
      check(j.awaitIdle(30000), "drain");
      root.deleteRecursively();
    }
  }

  /** A plugin with the journal started on {@code root} through startJournal(), its panel and the import setting read from {@code on}. */
  static final class Wired {
    final EviLivePlugin plugin = new EviLivePlugin();
    final EviLivePanel panel;
    final PluginJournal journal;

    Wired(Filepath root, AtomicBoolean on) throws Exception {
      set(plugin, "gson", new Gson());
      set(plugin, "config", new EviLiveConfig() {
        public boolean importBridgeHistory() {
          return on.get();
        }
      });
      panel = panel(r -> { });
      set(plugin, "panel", panel);
      Method start = EviLivePlugin.class.getDeclaredMethod("startJournal", Filepath.class);
      start.setAccessible(true);
      start.invoke(plugin, root);
      journal = (PluginJournal) get(plugin, "journal");
      check(journal != null, "startJournal() left no journal");
    }

    void packet(String account, int seq, long ts) throws Exception {
      journal.offerPacket(EviLiveSidebarLinesTest.packet(account, "s-" + account.substring(0, 2), seq, ts)); // one session per account
      check(journal.awaitIdle(30000), "drain");
      edt();
    }

    void setting(AtomicBoolean on, boolean value) throws Exception {
      on.set(value);
      ConfigChanged e = new ConfigChanged();
      e.setGroup("evilive");
      e.setKey("importBridgeHistory");
      e.setNewValue(Boolean.toString(value));
      plugin.onConfigChanged(e);
      check(journal.awaitIdle(30000), "drain");
      edt();
    }

    boolean shown() {
      return panel.importNote.isVisible() && PluginJournal.IMPORT_MISSING_NOTICE.equals(panel.importNote.getText());
    }

    void close(Filepath root) throws Exception {
      journal.shutdown();
      check(journal.awaitIdle(30000), "drain");
      root.deleteRecursively();
    }
  }

  /**
   * The plugin's own wiring (4.0.0, the maintainer's call of 8 Oct 2026: the line is SHOWN): startJournal() relays the journal's
   * line to the panel and a settings change re-reads it. Shown when the import is on and no file exists; NOT shown when the
   * setting is off, when the file exists (it is imported), or when the account is already imported. Every case goes through
   * the real plugin and a real journal, and the shown case is asserted first, so the hidden ones are not vacuous.
   */
  static void importLineWiring() throws Exception {
    // (1) On, no file: shown. Off in the settings panel: gone at once. On again: back at once.
    {
      Filepath root = TestFiles.tempDir("evi-sidebar-test");
      AtomicBoolean on = new AtomicBoolean(true);
      Wired w = new Wired(root, on);
      w.packet(ACCOUNT, 1, T0);
      check(w.shown(), "import on, no file: the line must be shown: visible=" + w.panel.importNote.isVisible() + " \"" + w.panel.importNote.getText() + "\"");
      w.setting(on, false);
      check(!w.panel.importNote.isVisible(), "switching the import OFF must hide the line at once");
      w.setting(on, true);
      check(w.shown(), "switching it ON again with no file must show the line at once");
      w.close(root);
    }
    // (2) Off from the start, no file: never shown.
    {
      Filepath root = TestFiles.tempDir("evi-sidebar-test");
      AtomicBoolean on = new AtomicBoolean(false);
      Wired w = new Wired(root, on);
      w.packet(ACCOUNT, 1, T0);
      w.packet(ACCOUNT, 2, T0 + 1);
      check(!w.panel.importNote.isVisible(), "import off, no file: the line must not be shown");
      w.close(root);
    }
    // (3) On, and the file exists: it is imported, so nothing is asked for.
    {
      Filepath root = TestFiles.tempDir("evi-sidebar-test");
      writeImportFile(root, ACCOUNT);
      AtomicBoolean on = new AtomicBoolean(true);
      Wired w = new Wired(root, on);
      w.packet(ACCOUNT, 1, T0);
      w.packet(ACCOUNT, 2, T0 + 1);
      check(root.joinSegment(PluginJournal.JOURNAL_DIR).joinSegment("imported-" + ACCOUNT + ".jsonl").exists(), "setup: the import ran");
      check(!w.panel.importNote.isVisible(), "import on and the file present: the line must not be shown");
      w.close(root);
    }
    // (4) On, no file, but the account is already imported (its marker on disk): not shown, and not after a settings change.
    {
      Filepath root = TestFiles.tempDir("evi-sidebar-test");
      Filepath dir = root.joinSegment(PluginJournal.JOURNAL_DIR);
      dir.createDirectories();
      dir.joinSegment("import-done-" + ACCOUNT + ".json").write("{}\n".getBytes(StandardCharsets.UTF_8));
      AtomicBoolean on = new AtomicBoolean(true);
      Wired w = new Wired(root, on);
      w.packet(ACCOUNT, 1, T0);
      check(!w.panel.importNote.isVisible(), "an already-imported account must not be asked for a file");
      w.setting(on, false);
      w.setting(on, true);
      check(!w.panel.importNote.isVisible(), "an already-imported account: still not shown after the setting goes off and on");
      // and another, not imported account on the same machine is asked for its file
      w.packet(OTHER, 1, T0 + 2);
      check(w.shown(), "another account with no file: shown for it");
      w.close(root);
    }
  }
}

package com.evi.live;

import com.google.gson.Gson;
import java.awt.event.KeyEvent;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ModifierlessKeybind;

/**
 * Fake widget/client only; never launches a game client and never touches the Confirm button
 * or a menu action. Asserts the hotkey writes the exact expected string and nothing else.
 */
public class EviLiveSuggestionTest {
  static void check(boolean value, String message) { if (!value) throw new AssertionError(message); }

  static class FakeWidget {
    String text = "";
    int originalY;
    int itemId = -1;
    boolean hidden = false;
    java.awt.Rectangle bounds;
    // Captured for SuggestionItemSelectWidget's tests: the exact (script, itemId, arg) triple
    // passed to setOnOpListener/setOnKeyListener, and the widget's name (used for its tooltip/menu
    // label, same as a real GE search-result row).
    Object[] onOpArgs;
    Object[] onKeyArgs;
    String name;
    Map<Integer, FakeWidget> children = new HashMap<>();
    // Populated by createChild(), so a test can inspect every child widget a caller created on
    // this fake (e.g. the chatbox container in EviLiveHintTest), in creation order.
    java.util.List<FakeWidget> createdChildren = new java.util.ArrayList<>();
    // Distinct from children/createdChildren (which key by fixed child index): models
    // getDynamicChildren(), the list-style children of a search results widget, keyed by nothing
    // but position, for EviLiveSearchHighlightTest.
    java.util.List<FakeWidget> dynamicChildren = new java.util.ArrayList<>();
    // One proxy per fake, like the real client, which hands back the same widget object every time --
    // SuggestionItemSelectWidget relies on that identity to tell whether its widgets are still attached.
    private Widget cached;
    Widget proxy() {
      if (cached != null) return cached;
      return cached = (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class[]{Widget.class}, (p, m, a) -> {
        switch (m.getName()) {
          case "getText": return text;
          case "setText": text = (String) a[0]; return null;
          case "getChild": return children.containsKey(a[0]) ? children.get((Integer) a[0]).proxy() : null;
          case "createChild": {
            FakeWidget child = new FakeWidget();
            createdChildren.add(child);
            // A real index replaces whatever held that slot, as in the client; -1 appends.
            if (a != null && a.length > 0 && a[0] instanceof Integer && (Integer) a[0] >= 0) children.put((Integer) a[0], child);
            return child.proxy();
          }
          case "getOriginalY": return originalY;
          case "setOriginalY": originalY = (Integer) a[0]; return null;
          case "getItemId": return itemId;
          case "isHidden": return hidden;
          case "isSelfHidden": return hidden;
          case "setHidden": hidden = (Boolean) a[0]; return null;
          case "getBounds": return bounds;
          case "getDynamicChildren": return dynamicChildren.stream().map(FakeWidget::proxy).toArray(Widget[]::new);
          // The fixed-index children as an array, which is what a caller searching for a child by
          // its TEXT rather than its index reads (GEOffer.offerTypeWidget). Without this the fake
          // answered an empty array and such a search could never find anything, so a test would
          // pass on the fallback path and never exercise the search at all.
          case "getChildren": return children.values().stream().map(FakeWidget::proxy).toArray(Widget[]::new);
          case "setOnOpListener": onOpArgs = (Object[]) a[0]; return null;
          case "setOnKeyListener": onKeyArgs = (Object[]) a[0]; return null;
          case "setName": name = (String) a[0]; return null;
          case "setItemId": itemId = (Integer) a[0]; return null;
          // Styling/layout/listener setters the hint widget calls but this fixture doesn't need to
          // model beyond accepting the call; revalidate/setOriginalX/etc. are no-ops here.
          default: return null;
        }
      });
    }
  }

  static class FakeClient {
    int openSlotVarbit = 0; // CURRENTLY_OPEN_GE_SLOT_VARBIT_ID raw value; 0 means "no slot open" (getOpenSlot() == -1)
    int offerCreationType = 0; // 0 = buying, 1 = selling (Varbits.GE_OFFER_CREATION_TYPE)
    int currentItemId = -1;
    int inputType = 7;
    FakeWidget chatboxTitle = new FakeWidget();
    FakeWidget chatboxInput = new FakeWidget();
    FakeWidget offerContainer = new FakeWidget();
    FakeWidget chatboxContainer = new FakeWidget();
    // Null by default, modelling the GE item-search results widget not existing yet (e.g. the
    // search box isn't open); EviLiveSearchHighlightTest assigns one in to exercise the rest.
    FakeWidget searchResults;
    String lastVarcStr;
    // What the player has typed into the chatbox input (VarClientStr.INPUT_TEXT); empty by default.
    String typedSearch = "";

    Client proxy() {
      return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class[]{Client.class}, (p, m, a) -> {
        switch (m.getName()) {
          case "getVarbitValue": {
            boolean isSlotVarbit = a[0] instanceof Integer && (Integer) a[0] == 4439;
            return isSlotVarbit ? openSlotVarbit : offerCreationType;
          }
          case "getVarpValue": return currentItemId;
          case "getVarcIntValue": return inputType;
          case "getWidget": {
            Object id = a[0];
            if (ComponentID.CHATBOX_TITLE == asInt(id)) return chatboxTitle.proxy();
            if (ComponentID.CHATBOX_FULL_INPUT == asInt(id)) return chatboxInput.proxy();
            if (ComponentID.GRAND_EXCHANGE_OFFER_CONTAINER == asInt(id)) return offerContainer.proxy();
            if (ComponentID.CHATBOX_CONTAINER == asInt(id)) return chatboxContainer.proxy();
            if (ComponentID.CHATBOX_GE_SEARCH_RESULTS == asInt(id)) return searchResults == null ? null : searchResults.proxy();
            return null;
          }
          case "setVarcStrValue": lastVarcStr = (String) a[1]; return null;
          case "getVarcStrValue": return typedSearch;
          default: return primitiveDefault(m.getReturnType());
        }
      });
    }
    private static int asInt(Object o) { return o instanceof Integer ? (Integer) o : -1; }
    private static Object primitiveDefault(Class<?> t) {
      if (t == boolean.class) return false;
      if (t == int.class) return 0;
      return null;
    }
  }

  /** buyPrice and sellPrice are always both set, matching what the bridge actually sends now. */
  static Suggestion suggestion(int itemId, String action, int quantity, int buyPrice, int sellPrice) {
    Suggestion s = new Suggestion();
    s.itemId = itemId; s.action = action; s.quantity = quantity; s.buyPrice = buyPrice; s.sellPrice = sellPrice; s.name = "Test item"; s.source = "personal";
    return s;
  }

  /** Models a bridge openItemPrice response: quantity always 0, name/action/source/reasoning left
   *  unset, exactly as OpenItemPriceCache's own class doc describes. */
  static Suggestion openItemPrice(int itemId, int buyPrice, int sellPrice) {
    Suggestion s = new Suggestion();
    s.itemId = itemId; s.buyPrice = buyPrice; s.sellPrice = sellPrice;
    return s;
  }

  public static void main(String[] args) throws Exception {
    // The bridge's real JSON shape must still deserialize into the plugin's field names, including
    // the separate openItemPrice field (a plain {itemId, buyPrice, sellPrice} shape -- no name,
    // action, quantity, source, or reasoning -- see OpenItemPriceCache's own class doc).
    String json = "{\"suggestion\":{\"itemId\":13190,\"name\":\"Fire rune\",\"action\":\"buy\",\"quantity\":500,\"buyPrice\":4,\"sellPrice\":5,\"source\":\"personal\",\"reasoning\":\"test\"},\"openItemPrice\":{\"itemId\":314,\"buyPrice\":180,\"sellPrice\":210}}";
    EviLivePlugin.SuggestionResponse parsed = new Gson().fromJson(json, EviLivePlugin.SuggestionResponse.class);
    check(parsed.suggestion.itemId == 13190 && "buy".equals(parsed.suggestion.action) && parsed.suggestion.quantity == 500
      && parsed.suggestion.buyPrice == 4 && parsed.suggestion.sellPrice == 5, "Bridge JSON shape must round-trip into plugin fields");
    check(parsed.openItemPrice.itemId == 314 && parsed.openItemPrice.buyPrice == 180 && parsed.openItemPrice.sellPrice == 210
      && parsed.openItemPrice.quantity == 0 && parsed.openItemPrice.name == null, "openItemPrice must round-trip as a plain price with no name/quantity");

    FakeClient fc = new FakeClient();
    Client client = fc.proxy();
    GEOffer geOffer = new GEOffer();
    Field clientField = GEOffer.class.getDeclaredField("client"); clientField.setAccessible(true); clientField.set(geOffer, client);
    SuggestionCache cache = new SuggestionCache();
    OpenItemPriceCache openItemPriceCache = new OpenItemPriceCache();
    SuggestionKeybindHandler handler = new SuggestionKeybindHandler(null, null, client, geOffer, cache, openItemPriceCache, null);
    Method fill = SuggestionKeybindHandler.class.getDeclaredMethod("fill"); fill.setAccessible(true);

    // No GE slot open at all: nothing should be touched even with a cached suggestion.
    cache.set(suggestion(1, "buy", 100, 50, 65));
    fc.currentItemId = 1;
    fill.invoke(handler);
    check(fc.chatboxInput.text.isEmpty() && fc.lastVarcStr == null, "Hotkey must do nothing when no GE slot is open");

    // Slot open, but neither the quantity nor price prompt is the open chatbox.
    fc.openSlotVarbit = 1;
    fill.invoke(handler);
    check(fc.chatboxInput.text.isEmpty(), "Hotkey must do nothing when the open chatbox is not the quantity/price prompt");

    // Quantity prompt open, matching item: fills quantity, exact string, touches nothing else.
    fc.chatboxTitle.text = "How many do you wish to buy?";
    fill.invoke(handler);
    check("100*".equals(fc.chatboxInput.text), "Hotkey must fill the exact suggested quantity");
    check("100".equals(fc.lastVarcStr), "Hotkey must set the matching VarClientStr value");

    // Different item selected in-game than the cached suggestion: must not fill.
    fc.chatboxInput.text = "";
    fc.lastVarcStr = null;
    fc.currentItemId = 999;
    fill.invoke(handler);
    check(fc.chatboxInput.text.isEmpty(), "Hotkey must not fill a suggestion for a different item than is currently selected");

    // Price prompt, buy side, matching item: fills the suggestion's buy price.
    fc.currentItemId = 1;
    fc.chatboxTitle.text = "Set a price for each item:";
    fc.offerContainer.children.put(20, new FakeWidget());
    fc.offerContainer.children.get(20).text = "Buy offer";
    fill.invoke(handler);
    check("50*".equals(fc.chatboxInput.text), "Hotkey must fill the exact suggested buy price");

    // The offer type is found by its TEXT, not by a fixed child index. Jagex's "Beyond Max Cash"
    // update on 30 Sept 2026 rebuilt that panel to show two currencies, which shifted every child
    // after the inserted widgets: child 20 stopped being the offer type, isSettingPrice() went
    // permanently false, and the price hint and hotkey died silently for every user while the
    // quantity prompt kept working. The wording never changed -- a screenshot showed "Buy offer"
    // exactly as before, just somewhere else. Moving it here must change nothing.
    fc.chatboxInput.text = "";
    fc.offerContainer.children.clear();
    // Something else now occupies the old index -- the running two-currency total the update added.
    // This is the distinguishing case: a fixed-index read finds THIS and refuses, where finding
    // nothing at all would have fallen through to the varbit and filled anyway, so a test that only
    // moved the label would have passed against the very bug it was written for.
    fc.offerContainer.children.put(20, new FakeWidget());
    fc.offerContainer.children.get(20).text = "1,589,329 coins";
    fc.offerContainer.children.put(37, new FakeWidget());
    fc.offerContainer.children.get(37).text = "Buy offer";
    fill.invoke(handler);
    check("50*".equals(fc.chatboxInput.text), "The offer type must be found wherever it sits, not only at one index: " + fc.chatboxInput.text);
    // And with no offer-type widget findable at all, the varbit decides rather than the price being
    // withheld -- refusing on absence is what turned one interface change into a dead feature.
    fc.chatboxInput.text = "";
    fc.offerContainer.children.clear();
    fill.invoke(handler);
    check("50*".equals(fc.chatboxInput.text), "With no offer-type widget, the varbit must still decide: " + fc.chatboxInput.text);

    // Price prompt, same item, but the player is actually selling: this is the same flip's other
    // side, so it must fill the suggestion's SELL price, not stay empty and not reuse the buy price.
    fc.chatboxInput.text = "";
    fc.offerCreationType = 1; // selling
    fc.offerContainer.children.put(20, new FakeWidget()); // restored: the block above emptied it
    fc.offerContainer.children.get(20).text = "Sell offer";
    fill.invoke(handler);
    check("65*".equals(fc.chatboxInput.text), "Hotkey must fill the exact suggested sell price while selling the same item");

    // A suggestion with no usable sell price (e.g. a malformed 0) must not fill anything while selling.
    fc.chatboxInput.text = "";
    cache.set(suggestion(1, "buy", 100, 50, 0));
    fill.invoke(handler);
    check(fc.chatboxInput.text.isEmpty(), "Hotkey must not fill a non-positive sell price");

    // No cached suggestion at all: never touches the input widget.
    cache.set(null);
    fc.offerCreationType = 0;
    fc.offerContainer.children.get(20).text = "Buy offer";
    fc.chatboxTitle.text = "How many do you wish to buy?";
    fill.invoke(handler);
    check(fc.chatboxInput.text.isEmpty(), "Hotkey must do nothing with no cached suggestion");

    // -- GEOffer.resolveOpenSuggestion: prefers the ranked pick when it matches the item currently
    // open, falls back to a plain OpenItemPriceCache price when only that matches, null otherwise.
    // This is what lets the hint/hotkey work for ANY item being traded, not only EVI's current #1
    // suggestion (the original limitation reported: an item with no reviewed history, or one that
    // simply wasn't the single top-ranked pick, got no hint and filled nothing at all). --
    check(geOffer.resolveOpenSuggestion(null, null) == null, "resolveOpenSuggestion: neither known: null");
    fc.currentItemId = 1;
    check(geOffer.resolveOpenSuggestion(suggestion(1, "buy", 100, 50, 65), openItemPrice(1, 40, 55)).source != null,
      "resolveOpenSuggestion: the ranked pick is preferred over the open-item price when both match the open item");
    check(geOffer.resolveOpenSuggestion(suggestion(2, "buy", 100, 50, 65), openItemPrice(1, 40, 55)).quantity == 0,
      "resolveOpenSuggestion: falls back to the open-item price when the ranked pick doesn't match the open item");
    check(geOffer.resolveOpenSuggestion(suggestion(2, "buy", 100, 50, 65), openItemPrice(3, 40, 55)) == null,
      "resolveOpenSuggestion: null when neither known suggestion matches the open item");

    // End-to-end via the hotkey: no ranked suggestion at all for this item, but a plain live
    // open-item price is known for it -- the price must still fill, but a quantity (always 0 for
    // an open-item price -- there's no track record to size one by) must never be offered/filled.
    cache.set(null);
    openItemPriceCache.set(openItemPrice(1, 42, 58));
    fc.currentItemId = 1;
    fc.offerCreationType = 0;
    fc.chatboxTitle.text = "How many do you wish to buy?";
    fc.chatboxInput.text = "";
    fill.invoke(handler);
    check(fc.chatboxInput.text.isEmpty(), "Hotkey must never fill a quantity for a plain open-item price");
    fc.chatboxTitle.text = "Set a price for each item:";
    fc.offerContainer.children.get(20).text = "Buy offer";
    fill.invoke(handler);
    check("42*".equals(fc.chatboxInput.text), "Hotkey must fill the open-item buy price for an item with no ranked suggestion");
    fc.chatboxInput.text = "";
    fc.offerCreationType = 1;
    fc.offerContainer.children.get(20).text = "Sell offer";
    fill.invoke(handler);
    check("58*".equals(fc.chatboxInput.text), "Hotkey must fill the open-item sell price for an item with no ranked suggestion");
    openItemPriceCache.set(null);
    fc.offerCreationType = 0;
    fc.offerContainer.children.get(20).text = "Buy offer";

    // The keybind listener itself must never treat Enter as the configured hotkey, even if somehow bound to it.
    EviLiveConfig config = (EviLiveConfig) Proxy.newProxyInstance(EviLiveConfig.class.getClassLoader(), new Class[]{EviLiveConfig.class},
      (p, m, a) -> "suggestionKeybind".equals(m.getName()) ? new ModifierlessKeybind(KeyEvent.VK_ENTER, 0) : null);
    SuggestionKeybindHandler enterBound = new SuggestionKeybindHandler(null, null, client, geOffer, cache, openItemPriceCache, config);
    Field listenerField = SuggestionKeybindHandler.class.getDeclaredField("listener"); listenerField.setAccessible(true);
    Object listener = listenerField.get(enterBound);
    Method keyPressed = listener.getClass().getMethod("keyPressed", KeyEvent.class);
    cache.set(suggestion(1, "buy", 100, 50, 65));
    fc.currentItemId = 1;
    fc.offerCreationType = 0; // buying, so the buy price is the one that could get filled
    fc.chatboxTitle.text = "Set a price for each item:";
    fc.offerContainer.children.get(20).text = "Buy offer";
    fc.chatboxInput.text = "";
    // A plain Component (not Label/Button/etc.) never touches a native peer, so this stays safe
    // under java.awt.headless=true, which this Gradle task sets the same way panelTest does.
    java.awt.Component dummy = new java.awt.Component() { };
    KeyEvent enterEvent = new KeyEvent(dummy, KeyEvent.KEY_PRESSED, System.currentTimeMillis(), 0, KeyEvent.VK_ENTER, KeyEvent.CHAR_UNDEFINED);
    // clientThread is null in this handler, so if Enter were not excluded first, the invokeLater
    // call below would throw immediately (synchronously, from within keyPressed) instead of quietly
    // returning; either way nothing gets filled.
    keyPressed.invoke(listener, enterEvent);
    check(fc.chatboxInput.text.isEmpty(), "Enter must never be treated as the fill hotkey even if configured that way");

    System.out.println("PASS: no-slot, wrong-prompt, quantity fill, item mismatch, buy price fill, sell price fill, non-positive sell price, no-suggestion, resolveOpenSuggestion precedence/fallback/null, open-item price fill without a fabricated quantity, and Enter-key exclusion");
  }
}

package com.evi.live;

/**
 * Do the replacement constants in net.runelite.api.gameval resolve to the SAME numbers the
 * deprecated ones do?
 *
 * <p>This exists because of 30 September 2026. {@code VarClientInt.INPUT_TYPE} kept its name and
 * changed its VALUE for the price prompt (7 -> 30), and the plugin's price hint and hotkey died
 * silently for every user. The lesson is that a constant's identity is its number, not its name --
 * so swapping fifteen deprecated references on the strength of a plausible-looking rename would be
 * repeating exactly the mistake that cost a release.
 *
 * <p>Every assertion below compares the deprecated constant with its replacement directly. A rename
 * that is really a rename passes; a rename that quietly points somewhere else fails here rather than
 * in someone's game. The deprecated references in THIS file are deliberate and are the only ones
 * that should remain once the swap is done -- they are the control half of the comparison.
 *
 * <p>Deliberately NOT asserting hard-coded numbers: those would record what the cache happened to
 * say on the day this was written, and Jagex is free to move them. What must hold is that both names
 * mean the same thing at the same moment.
 */
@SuppressWarnings("deprecation")
public class GamevalConstantsTest {
  static void check(boolean ok, String what) {
    if (!ok) throw new AssertionError(what);
  }

  static void same(int oldValue, int newValue, String what) {
    check(oldValue == newValue,
      what + ": the deprecated constant is " + oldValue + " and its replacement is " + newValue
        + ". These must be the same number -- a rename that moves the value is how the price prompt"
        + " broke on 30 Sept 2026. Do NOT swap this reference until the mismatch is understood.");
  }

  public static void main(String[] args) {
    // Widget/component ids used by GEOffer, SuggestionHintWidget, SuggestionItemSelectWidget,
    // SuggestionKeybindHandler and SuggestionSearchHighlightOverlay.
    same(net.runelite.api.widgets.ComponentID.CHATBOX_TITLE,
      net.runelite.api.gameval.InterfaceID.Chatbox.MES_TEXT, "CHATBOX_TITLE");
    same(net.runelite.api.widgets.ComponentID.CHATBOX_CONTAINER,
      net.runelite.api.gameval.InterfaceID.Chatbox.MES_LAYER, "CHATBOX_CONTAINER");
    same(net.runelite.api.widgets.ComponentID.CHATBOX_FULL_INPUT,
      net.runelite.api.gameval.InterfaceID.Chatbox.MES_TEXT2, "CHATBOX_FULL_INPUT");
    same(net.runelite.api.widgets.ComponentID.CHATBOX_GE_SEARCH_RESULTS,
      net.runelite.api.gameval.InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS, "CHATBOX_GE_SEARCH_RESULTS");
    same(net.runelite.api.widgets.ComponentID.GRAND_EXCHANGE_OFFER_CONTAINER,
      net.runelite.api.gameval.InterfaceID.GeOffers.SETUP, "GRAND_EXCHANGE_OFFER_CONTAINER");

    // Varbits / varps. GE_OFFER_CREATION_TYPE decides buy versus sell; CURRENT_GE_ITEM is the item
    // the offer screen has open; INPUT_TYPE is the one whose value moved under us.
    same(net.runelite.api.Varbits.GE_OFFER_CREATION_TYPE,
      net.runelite.api.gameval.VarbitID.GE_NEWOFFER_TYPE, "GE_OFFER_CREATION_TYPE");
    same(net.runelite.api.VarPlayer.CURRENT_GE_ITEM,
      net.runelite.api.gameval.VarPlayerID.TRADINGPOST_SEARCH, "CURRENT_GE_ITEM");
    same(net.runelite.api.VarClientInt.INPUT_TYPE,
      net.runelite.api.gameval.VarClientID.MESLAYERMODE, "INPUT_TYPE");

    same(net.runelite.api.VarClientStr.INPUT_TEXT,
      net.runelite.api.gameval.VarClientID.MESLAYERINPUT, "INPUT_TEXT");
    // InventoryID was an ENUM, not an int, so this one compares the enum's own id with the new
    // integer constant. Confirmed 29 Sept 2026 to be 93 on both sides -- recorded then because a
    // session had wrongly blamed this deprecation for an inventory read that was never broken.
    same(net.runelite.api.InventoryID.INVENTORY.getId(),
      net.runelite.api.gameval.InventoryID.INV, "INVENTORY");

    System.out.println("PASS: every deprecated constant EVI reads resolves to the same number as its "
      + "net.runelite.api.gameval replacement (chatbox title/container/input/search results, the GE "
      + "offer container, the buy-versus-sell varbit, the current GE item varp, and the chatbox "
      + "input type whose value moved on 30 Sept 2026)");
  }
}

package com.evi.live;

import net.runelite.client.util.Filepath;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.Function;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * The Plugin Hub's forbidden-API list ("Rejected or Rolled Back Features", revised 6 Oct 2026), checked over
 * every file of the plugin's MAIN source on every build, so a banned call cannot come back unnoticed. The
 * list is read off the code with comments and string literals removed: a comment that says "never
 * Thread.interrupt" is not a call, and a call hidden in a comment is not code.
 *
 * <p>What is forbidden, as the page words it: reflection; JNI and JNA; running external programs; downloading
 * or loading code at runtime; Desktop.open / Desktop.browse / LinkBrowser.open; Thread.interrupt and
 * Thread.sleep; Client.menuAction; java.io file APIs (use Filepath); java.lang.Runtime; KeyboardFocusManager;
 * any network client but OkHttp; creating your own Gson or OkHttp instance; net.runelite as the package. And
 * Filepath.Unchecked, which is restricted (manual review). shutdownNow() is added because it interrupts.
 *
 * <p>7 Oct 2026, the blind spots a verifier's mutation run found, each now a rule and a self-test line: a sleep
 * reached any other way ({@code TimeUnit.X.sleep}, a static import of {@code Thread.sleep}, a call split across
 * lines), an interrupt reached any other way ({@code Future.cancel(true)} and {@code invokeAll}/{@code invokeAny}
 * with a timeout, which cancel with interrupt), {@code java.io.*} imported whole and its {@code File} used bare,
 * RuneLite's own {@code java.io.File} folders ({@code RuneLite.RUNELITE_DIR} and the rest), and network IO outside
 * OkHttp through {@code java.net.URL} (e.g. {@code ImageIO.read(new URL(...))}). The scan now reads each file as
 * ONE text with whitespace collapsed and removed around a dot, so a call split over lines is still one call; a
 * hit still reports its real line.
 *
 * <p>7 Oct 2026, second pass, after a planted file stayed green end to end:
 * <ul>
 *   <li><b>Unicode escapes are decoded first, exactly as javac does</b> (JLS 3.3: any number of u's, and only a
 *       backslash preceded by an even run of backslashes starts one). Without it {@code Thread.\u005cu0073leep(1)}
 *       was invisible, and a {@code \u005cu0022} or {@code \u005cu000a} could move a string's or comment's edge so
 *       real code read as a literal. Text blocks are stripped whole, and a carriage return ends a line comment.</li>
 *   <li><b>Method references are read as calls</b>: {@code X::m} as {@code X.m(} and {@code X::new} as
 *       {@code new X(}, so {@code Thread::sleep}, {@code ExecutorService::shutdownNow}, {@code Class::forName},
 *       {@code Client::menuAction} and {@code Gson::new} meet the same rules as the calls they stand for. A
 *       reference to {@code cancel} is flagged: which overload it binds is the compiler's choice, not the reader's.</li>
 *   <li><b>Allow-lists instead of block-lists for {@code java.io}, {@code java.net}, {@code java.nio.file} and
 *       {@code java.nio.channels}</b>, which a JDK class can only be used from by naming it in an import or in
 *       full (only {@code java.lang} is implicit). So {@code PrintWriter}, {@code PrintStream}, {@code InetAddress},
 *       {@code SocketChannel} and {@code FileSystems} are caught without listing them, and any class added later
 *       must be put on the list deliberately. <b>Wildcard imports are banned for the same reason</b>: they would
 *       let a class be used without its package ever being written.</li>
 *   <li>Packages with nothing a flipping plugin needs: {@code java.beans} (reflection by another name),
 *       {@code javax.net} and {@code .createSocket(} (raw sockets, also reachable from OkHttp's socket factories),
 *       {@code java.rmi}, {@code javax.naming}, JMX, {@code java.lang.instrument}, and the JDK's internal
 *       {@code sun.*}, {@code jdk.*}, {@code com.sun.*}. Plus {@code FocusManager} (a
 *       {@code KeyboardFocusManager}), {@code ZipFile}/{@code JarFile}/{@code FileHandler}/{@code java.util.Formatter}
 *       (they open files by name), {@code ProcessHandle}, {@code LockSupport} (a sleep under another name), and a
 *       static import of a member of {@code Thread}, {@code Class}, {@code Runtime}, {@code ClassLoader},
 *       {@code System.load*} or {@code LinkBrowser.open}, which would let the call appear without its class.</li>
 * </ul>
 *
 * <p>The limit by construction: the scan reads NAMES, not types. An API reached only through a value whose type
 * is never written (a method chain, {@code var}) is seen only when its method's name is on a list -- which is why
 * the dangerous method names ({@code sleep}, {@code interrupt}, {@code createSocket}, {@code toFile}, {@code
 * openConnection} ...) are matched on their own, whatever they are called on.
 *
 * <p>11 Oct 2026, the Hub's review of 4.0.0: "all file i/o should be performed with Filepath rather than direct java
 * APIs" -- the tests included. So the TEST source is scanned too, by the two file rules ({@link #TEST_RULES}): every
 * test reads and writes through {@link TestFiles}, which is the one test file allowed to aim a Filepath at a folder
 * (Filepath.Unchecked: a temporary folder, or the project's own files) and to hand OkHttp's cache its java.io.File.
 *
 * <p>Test-only: tests do not ship in the plugin jar. The scanner proves itself first, on known-bad and
 * known-good snippets, so a pattern that silently matches nothing fails here rather than passing.
 */
public final class HubRulesScanTest {
  static final class Rule {
    final String name;
    final Pattern pattern;

    Rule(String name, String regex) {
      this.name = name;
      this.pattern = Pattern.compile(regex);
    }
  }

  /** java.io classes a plugin may use: streams, readers and exceptions. Nothing here opens a file by name. */
  static final String JAVA_IO_ALLOWED = "IOException|UncheckedIOException|EOFException|InputStream|OutputStream|Reader|Writer|BufferedReader"
    + "|BufferedWriter|InputStreamReader|OutputStreamWriter|ByteArrayInputStream|ByteArrayOutputStream|StringReader|StringWriter|Closeable"
    + "|Flushable|Serializable";
  /** java.net: names and encoders, OkHttp's Proxy.NO_PROXY, and the exceptions an OkHttp call can throw. Nothing that connects. */
  static final String JAVA_NET_ALLOWED = "URI|URISyntaxException|URLEncoder|URLDecoder|Proxy|MalformedURLException|SocketTimeoutException"
    + "|ConnectException|UnknownHostException|NoRouteToHostException";
  /** java.nio.file: options, exceptions and FileTime -- what Filepath's own methods take and throw. Not Files, Paths, Path or FileSystems. */
  static final String JAVA_NIO_FILE_ALLOWED = "StandardOpenOption|StandardCopyOption|OpenOption|CopyOption"
    + "|NoSuchFileException|AccessDeniedException|AtomicMoveNotSupportedException|DirectoryNotEmptyException|NotDirectoryException"
    + "|attribute\\.FileTime";
  /** java.nio.channels: the FileChannel that Filepath.openFileChannel hands out, and what goes with it. No socket or async channel. */
  static final String JAVA_NIO_CHANNELS_ALLOWED = "FileChannel|FileLock|Channels|ReadableByteChannel|WritableByteChannel|SeekableByteChannel"
    + "|ByteChannel|ClosedChannelException|OverlappingFileLockException";

  static String outside(String pkg, String allowed) {
    return "\\b" + pkg.replace(".", "\\.") + "\\.(?!(?:" + allowed + ")\\b)\\w[\\w.]*";
  }

  static final List<Rule> RULES = Arrays.asList(
    new Rule("reflection", "\\bjava\\.lang\\.reflect\\b|\\bjava\\.lang\\.invoke\\b|\\.setAccessible\\s*\\(|\\.getDeclared(Field|Method|Constructor)s?\\s*\\("
      + "|\\.get(Field|Method|Constructor)s?\\s*\\(|\\bClass\\.forName\\s*\\(|\\.newInstance\\s*\\(|\\bProxy\\.newProxyInstance\\b|\\bMethodHandles\\b|\\bsun\\.misc\\b"
      // reflection under other names: bean introspection, JMX, instrumentation
      + "|\\bjava\\.beans\\b|\\bIntrospector\\b|\\bjavax\\.management\\b|\\bjava\\.lang\\.management\\b|\\bjava\\.lang\\.instrument\\b"),
    new Rule("JNI / JNA", "\\bnative\\s+[\\w<>\\[\\], ]+\\s+\\w+\\s*\\(|\\bSystem\\.load(Library)?\\s*\\(|\\bcom\\.sun\\.jna\\b"),
    new Rule("external programs", "\\bProcessBuilder\\b|\\bRuntime\\b|\\bProcess\\b|\\bProcessHandle\\b"),
    new Rule("code loaded at runtime", "\\bURLClassLoader\\b|\\bdefineClass\\b|\\bjavax\\.script\\b|\\bScriptEngine\\w*\\b|\\bjavax\\.tools\\b|\\bClassLoader\\b"),
    new Rule("JDK internals", "(?<![\\w.])(sun|jdk|com\\.sun)\\.\\w"),
    new Rule("Desktop / LinkBrowser.open", "\\bDesktop\\b|\\bLinkBrowser\\.open\\b"),
    new Rule("Thread.sleep / interrupt", "\\bThread\\.sleep\\s*\\(|\\.interrupt\\s*\\(|\\bshutdownNow\\s*\\("
      // any sleep(...) call: TimeUnit.X.sleep, unit.sleep, a static import of Thread.sleep; LockSupport.park* is a sleep by another name
      + "|\\bsleep\\s*\\(|\\bimport\\s+static\\s+java\\.lang\\.Thread\\b|\\bLockSupport\\b"
      // Future.cancel with anything but a literal false interrupts the running task; invokeAll / invokeAny cancel with interrupt
      // (the space after the bracket is taken possessively, so "cancel( )" cannot backtrack into a match)
      + "|\\.cancel\\s*\\(\\s*+(?!false\\s*\\)|\\))|\\.invoke(All|Any)\\s*\\("),
    new Rule("Client.menuAction", "\\.menuAction\\s*\\("),
    new Rule("java.io file APIs", outside("java.io", JAVA_IO_ALLOWED)
      + "|\\b(FileInputStream|FileOutputStream|FileReader|FileWriter|RandomAccessFile|FileDescriptor)\\b|\\bnew\\s+File\\s*\\(|\\bFile\\.separator\\b"
