 *   <li>@PluginDescriptor says the same thing as the listing, and the version is ONE number in build.gradle, the listing and the
 *       User-Agent;</li>
 *   <li>the internalName is evi-flipping in the descriptor, PluginFolder (every sentence naming the data folder) and
 *       settings.gradle, and "evi-live" survives in the sources only as the GitHub repo name and history comments;</li>
 *   <li>THE CONFIG MIGRATION, through a REAL RuneLite 1.13.1 ConfigManager: a stored "Same as scanner" (SAME_AS_SCANNER, written
 *       into every profile that ever loaded the plugin) is replaced by All items when the plugin's defaults are loaded, a stored
 *       Gear survives, the import setting's stored choice survives its rename, and the Exit-risk check starts at Off under its NEW
 *       key while the old forecastHorizon value is left in the profile, unread.</li>
 * </ol>
 */
public final class ReleaseListingTest {
  static int checks;

  static void check(boolean ok, String message) {
    if (!ok) throw new AssertionError(message);
    checks++;
  }

  static final String DISPLAY_NAME = "EVI Live";
  static final String DESCRIPTION = "Flip suggestions for the Grand Exchange: what to buy, how many and at what price, plus a trade journal"
    + " with exact GE tax. Uses only public OSRS Wiki prices; nothing about you is sent.";
  static final List<String> TAGS = List.of("grand exchange", "ge", "flip", "flipping", "trading", "money making", "profit", "suggestions", "journal", "evi");

  public static void main(String[] args) throws Exception {
    Filepath project = TestFiles.project();
    listing(project);
    rename(project);
    migration();
    System.out.println("PASS: release listing (" + checks + " checks) -- runelite-plugin.properties ASCII to the byte with the decided name,"
      + " description and tags and no warning=; @PluginDescriptor agreeing; one version in build.gradle, the listing and the User-Agent; the"
      + " internalName evi-flipping in the descriptor, PluginFolder and settings.gradle; and the config migration through a real ConfigManager"
      + " (Same as scanner -> All items, Gear kept, the import choice kept, the Exit-risk check at Off on its new key)");
  }

  static void listing(Filepath project) throws Exception {
    byte[] raw = TestFiles.read(project.joinSegment("runelite-plugin.properties"));
    for (int i = 0; i < raw.length; i++) check((raw[i] & 0xff) < 0x80, "runelite-plugin.properties must be ASCII: byte " + i + " is 0x" + Integer.toHexString(raw[i] & 0xff));
    Properties props = new Properties();
    try (InputStream in = project.joinSegment("runelite-plugin.properties").openInputStream()) {
      props.load(in);
    }
    check(DISPLAY_NAME.equals(props.getProperty("displayName")), "displayName: " + props.getProperty("displayName"));
    check(DESCRIPTION.equals(props.getProperty("description")), "description: " + props.getProperty("description"));
    check(TAGS.equals(Arrays.asList(props.getProperty("tags").split(","))), "tags: " + props.getProperty("tags"));
    check("com.evi.live.EviLivePlugin".equals(props.getProperty("plugins")) && "standard".equals(props.getProperty("build"))
      && "therealLeEvi".equals(props.getProperty("author")), "plugins / build / author");
    check(props.getProperty("warning") == null, "no warning= line (the maintainer's decision, 6 Oct 2026)");
    for (String key : props.stringPropertyNames()) {
      String v = props.getProperty(key).toLowerCase();
      for (String bad : new String[]{"companion", "bridge", "local", "127.0.0.1", "scanner"}) check(!v.contains(bad), key + " names \"" + bad + "\": " + v);
    }
    PluginDescriptor d = EviLivePlugin.class.getAnnotation(PluginDescriptor.class);
    check(DISPLAY_NAME.equals(d.name()) && DESCRIPTION.equals(d.description()) && TAGS.equals(Arrays.asList(d.tags())),
      "@PluginDescriptor must say what the listing says: " + d.name() + " | " + d.description() + " | " + Arrays.toString(d.tags()));
    String gradle = TestFiles.text(project.joinSegment("build.gradle"));
    Matcher v = Pattern.compile("(?m)^version = '([^']+)'").matcher(gradle);
    check(v.find(), "build.gradle has no version line");
    check("4.0.0".equals(v.group(1)) && v.group(1).equals(props.getProperty("version")) && v.group(1).equals(WikiPriceClient.VERSION),
      "ONE version, 4.0.0: build.gradle " + v.group(1) + ", listing " + props.getProperty("version") + ", User-Agent " + WikiPriceClient.VERSION);
    Matcher pin = Pattern.compile("def runeLiteVersion = '([^']+)'").matcher(gradle);
    check(pin.find() && pin.group(1).matches("\\d+\\.\\d+\\.\\d+"), "build.gradle pins an exact RuneLite release (match plugin-hub/runelite.version at release)");
  }

  static void rename(Filepath project) throws Exception {
    PluginDescriptor d = EviLivePlugin.class.getAnnotation(PluginDescriptor.class);
    check("evi-flipping".equals(PluginFolder.INTERNAL_NAME) && "evi-flipping".equals(d.internalName()),
      "internalName evi-flipping in PluginFolder and @PluginDescriptor: " + PluginFolder.INTERNAL_NAME + " / " + d.internalName());
    check(".runelite/plugin-data/evi-flipping".equals(PluginFolder.PATH), "the data folder: " + PluginFolder.PATH);
    String settings = TestFiles.text(project.joinSegment("settings.gradle")).trim();
    check("rootProject.name = 'evi-flipping'".equals(settings), "settings.gradle: " + settings);
    // "evi-live" may remain only as the GitHub repo (evi-live-plugin) and in history comments naming the old folder.
    Filepath src = TestFiles.at(project, "src", "main", "java");
    List<String> left = new ArrayList<>();
    for (Filepath f : TestFiles.files(src, ".java")) {
      String[] lines = TestFiles.text(f).split("\n");
      for (int i = 0; i < lines.length; i++) {
        String l = lines[i];
        if (!l.contains("evi-live")) continue;
        String rest = l.replace("evi-live-plugin", "");
        boolean comment = l.trim().startsWith("//") || l.trim().startsWith("*") || l.trim().startsWith("/*");
        if (!rest.contains("evi-live") || comment) continue;
        left.add(f.getFileName() + ":" + (i + 1) + ": " + l.trim());
      }
    }
    check(left.isEmpty(), "\"evi-live\" in code (not the repo name, not a comment): " + left);
    // the panel's title and the navigation tooltip are the plugin's name
    String plugin = TestFiles.text(TestFiles.at(src, "com", "evi", "live", "EviLivePlugin.java"));
    check(plugin.contains(".tooltip(\"EVI Live\")"), "the sidebar button's tooltip is the plugin's name");
  }

  static void migration() throws Exception {
    ConfigManager cm = EviLiveRiskSkipTest.realConfigManager(new net.runelite.client.eventbus.EventBus());
    // What an existing profile holds: the old default focus (RuneLite wrote it on first load), a chosen ~1 hour forecast under
    // the old key, and the import switched on.
    cm.setConfiguration("evilive", "suggestionFocus", "SAME_AS_SCANNER");
    cm.setConfiguration("evilive", "forecastHorizon", "ONE_HOUR");
    cm.setConfiguration("evilive", "importBridgeHistory", "true");
    EviLiveConfig real = cm.getConfig(EviLiveConfig.class);
    cm.setDefaultConfiguration(real, false); // what RuneLite's PluginManager does when the plugin is loaded
    check("ALL_ITEMS".equals(cm.getConfiguration("evilive", "suggestionFocus")) && real.suggestionFocus() == SuggestionFocus.ALL_ITEMS,
      "a stored SAME_AS_SCANNER becomes All items when the defaults load: " + cm.getConfiguration("evilive", "suggestionFocus"));
    check(real.importBridgeHistory() && "true".equals(cm.getConfiguration("evilive", "importBridgeHistory")), "the import's stored choice survives its rename");
    check(real.exitRiskCheck() == ForecastHorizon.OFF, "the Exit-risk check starts at Off on its new key");
    check("ONE_HOUR".equals(cm.getConfiguration("evilive", "forecastHorizon")), "the old key is left alone (nothing declares or reads it)");
    // A chosen Gear is kept, and loading the defaults again changes nothing.
    ConfigManager cm2 = EviLiveRiskSkipTest.realConfigManager(new net.runelite.client.eventbus.EventBus());
    cm2.setConfiguration("evilive", "suggestionFocus", "GEAR");
    cm2.setConfiguration("evilive", "exitRiskCheck", "SIX_HOUR");
    EviLiveConfig real2 = cm2.getConfig(EviLiveConfig.class);
    cm2.setDefaultConfiguration(real2, false);
    cm2.setDefaultConfiguration(real2, false);
    check(real2.suggestionFocus() == SuggestionFocus.GEAR && real2.exitRiskCheck() == ForecastHorizon.SIX_HOUR, "chosen values survive the defaults loading, twice");
    check(new TreeSet<>(Arrays.asList("ALL_ITEMS", "GEAR", "BULK")).equals(new TreeSet<>(Arrays.stream(SuggestionFocus.values()).map(Enum::name).collect(Collectors.toList()))),
      "the stored names of the focus setting");
  }
}

package com.evi.live;

import com.evi.live.journal.PluginFolder;
import com.evi.live.market.WikiPriceClient;
import java.awt.Component;
import java.awt.Container;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.JButton;
import javax.swing.SwingUtilities;

/**
 * Voluntary trade-log sharing (9 Oct 2026), the sidebar half: the "Not now" rule as a pure function, the approved wording word
 * for word, the dialogs' figures (US grouping, the folder named by PluginFolder, an error with no stack trace), and the wiring --
 * "Not now" writes the CURRENT version under the hidden key and hides the block; a stored version equal to the current one keeps
 * it hidden on the next start; any other (or none) shows it. Headless: the modal dialogs themselves are not opened here.
 */
public final class ShareInviteTest {
  static int checks;

  static void check(boolean ok, String message) {
    if (!ok) throw new AssertionError(message);
    checks++;
  }

  static void set(Object target, String name, Object value) throws Exception {
    Field f = target.getClass().getDeclaredField(name);
    f.setAccessible(true);
    f.set(target, value);
  }

  static void edt() throws Exception {
    SwingUtilities.invokeAndWait(() -> { });
    SwingUtilities.invokeAndWait(() -> { });
  }

  static void visit(Container parent, List<Component> out) {
    for (Component c : parent.getComponents()) {
      out.add(c);
      if (c instanceof Container) visit((Container) c, out);
    }
  }

  static JButton button(Container root, String text) {
    List<Component> all = new ArrayList<>();
    visit(root, all);
    for (Component c : all) if (c instanceof JButton && text.equals(((JButton) c).getText())) return (JButton) c;
    throw new AssertionError("no button \"" + text + "\"");
  }

  static EviLivePlugin plugin(Map<String, String> stored) throws Exception {
    EviLivePlugin plugin = new EviLivePlugin();
    set(plugin, "config", new EviLiveConfig() {
      public String shareInviteDismissedVersion() {
        String v = stored.get(ShareInvite.CONFIG_KEY);
        return v == null ? "" : v;
      }
    });
    set(plugin, "configWriter", (java.util.function.BiConsumer<String, String>) stored::put);
    return plugin;
  }

  static EviLivePanel built(EviLivePlugin plugin) throws Exception {
    AtomicReference<EviLivePanel> ref = new AtomicReference<>();
    SwingUtilities.invokeAndWait(() -> ref.set(plugin.buildPanel()));
    set(plugin, "panel", ref.get());
    edt();
    return ref.get();
  }

  public static void main(String[] args) throws Exception {
    // The rule, as a pure function.
    String v = WikiPriceClient.VERSION;
    check(!ShareInvite.shown(v, v), "dismissed at this version: hidden");
    check(ShareInvite.shown("", v), "never dismissed (empty): shown");
    check(ShareInvite.shown(null, v), "never dismissed (null): shown");
    check(ShareInvite.shown("3.0.0", "4.0.0"), "dismissed at an older version: shown again after the update");
    check(ShareInvite.shown("4.0.0", "3.12.1"), "any OTHER version shows it, older or newer");
    check("shareInviteDismissedVersion".equals(ShareInvite.CONFIG_KEY), "the hidden keyName");

    // The approved wording, word for word.
    check("Want to help improve EVI? Your logs will make a difference!".equals(ShareInvite.INVITE), "the invitation");
    check("Save my trade log...".equals(ShareInvite.SAVE_BUTTON) && "Not now".equals(ShareInvite.NOT_NOW_BUTTON), "the two buttons");
    check("Not now hides this until the next EVI update.".equals(ShareInvite.NOT_NOW_NOTE), "the muted line");
    check("Share your trade log".equals(ShareInvite.CONFIRM_TITLE) && "Save file".equals(ShareInvite.CONFIRM_SAVE)
      && "Cancel".equals(ShareInvite.CONFIRM_CANCEL), "the confirm dialog's title and buttons");
    check(ShareInvite.CONFIRM_TEXT.equals(List.of(
      "This saves a file on your computer that you can open, read and send yourself. EVI never uploads anything.",
      "It contains: every Grand Exchange offer EVI saw (item, buy or sell, price, quantity, how much filled, when, and whether it was cancelled), EVI's suggested price when it suggested that item, and your finished flips with their profit or loss.",
      "It does not contain: your account, character name, cash stack or bank.",
      "Times are exact, because that is what makes the data useful. On a rarely traded item, someone watching that item could still recognise a trade by its time.")),
      "the confirm dialog's four paragraphs");
    check("Trade log saved".equals(ShareInvite.SAVED_TITLE), "the saved dialog's title");
    check("Saved 12,345 offers and 1,002 flips to:".equals(ShareInvite.savedCounts(12345, 1002)), "real counts, US grouping: "
      + ShareInvite.savedCounts(12345, 1002));
    check("Saved 0 offers and 1 flips to:".equals(ShareInvite.savedCounts(0, 1)), "the counts are printed as they are");
    check((PluginFolder.PATH + "/share/evi-trade-log-2026-10-09.csv").equals(ShareInvite.displayPath("evi-trade-log-2026-10-09.csv")),
      "the location shown names the plugin's own folder (PluginFolder), never a typed one");
    check(("The location is copied to your clipboard. To share it, go to #share-your-log on the EVI Discord "
      + "(discord.gg/gFcEBHknVN), press Create Ticket and upload the file in the private channel that opens. Thank you, it really helps.").equals(ShareInvite.savedClosing(true)), "the saved dialog's closing, copied");
    check(ShareInvite.savedClosing(false).startsWith("To share it, go to #share-your-log"), "no clipboard claim when the copy failed");
    String failed = ShareInvite.failedText(new java.util.concurrent.CompletionException(new java.nio.file.AccessDeniedException("evi-trade-log.csv")));
    check(failed.equals("The trade log could not be saved: evi-trade-log.csv"), "the failure states why, unwrapped: " + failed);
    check(ShareInvite.failedText(new IllegalStateException()).equals("The trade log could not be saved: IllegalStateException"),
      "no message: the kind of failure, never a stack trace");

    // The wiring: shown at first, "Not now" stores THIS version and hides it; the next start keeps it hidden.
    Map<String, String> stored = new HashMap<>();
    EviLivePlugin first = plugin(stored);
    check(first.shareInviteShown(), "never dismissed: shown");
    EviLivePanel panel = built(first);
    check(panel.shareSection.isVisible(), "the panel shows the invitation from the first frame");
    SwingUtilities.invokeAndWait(() -> button(panel, "Not now").doClick());
    edt();
    check(stored.equals(Map.of(ShareInvite.CONFIG_KEY, v)), "Not now writes the current version under the hidden key, and nothing else: " + stored);
    check(!panel.shareSection.isVisible(), "Not now hides the whole block at once");
    EviLivePanel again = built(plugin(stored));
    check(!again.shareSection.isVisible(), "the next start, same version: still hidden");
    Map<String, String> older = new HashMap<>(Map.of(ShareInvite.CONFIG_KEY, "0.0.1"));
    EviLivePanel updated = built(plugin(older));
    check(updated.shareSection.isVisible(), "dismissed at another version: shown again");
    System.out.println("PASS: share invitation (" + checks + " checks): the Not-now rule, the approved wording, the dialogs' figures,"
      + " and Not now storing this version and hiding the block until the version changes");
  }
}

package com.evi.live;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;

/**
 * File access for the tests, through RuneLite's {@link Filepath} like the plugin's own code: the Plugin Hub's review
 * (11 Oct 2026) asks that ALL file I/O go through Filepath, tests included. {@code Filepath.Unchecked} is called HERE
 * ONLY, to aim a Filepath at a folder that is no plugin's data folder -- a new temporary folder, or one of this project's
 * own folders named by build.gradle. The plugin never calls it. {@code HubRulesScanTest} holds every other test file to
 * the same file rules as the main source.
 */
public final class TestFiles {
  private TestFiles() {
  }

  /** An absolute folder named by the build (a system property such as evi.projectDir, or a task argument). */
  public static Filepath rooted(String dir) {
    if (dir == null || dir.isEmpty()) throw new IllegalStateException("a folder the build should have named is not set");
    return Filepath.Unchecked.getRooted(java.nio.file.Paths.get(dir).toAbsolutePath());
  }

  /** The project folder (build.gradle's evi.projectDir). */
  public static Filepath project() {
    return rooted(System.getProperty("evi.projectDir"));
  }

  /** The system's temporary folder. */
  public static Filepath systemTemp() {
    return rooted(System.getProperty("java.io.tmpdir"));
  }

  /** A new, empty folder under the system's temporary folder. */
  public static Filepath tempDir(String prefix) throws IOException {
    return systemTemp().createTempDir(prefix);
  }

  /**
   * {@code f} as a {@code java.io.File}, for the two library constructors the tests call that take nothing else: OkHttp's
   * {@code Cache} (a stand-in of RuneLite's injected client; the plugin itself never makes a cache) and RuneLite's
   * {@code ConfigData} (a test ConfigManager whose file is never written). Nothing here reads or writes through it.
   */
  public static java.io.File asFile(Filepath f) {
    return Filepath.Unchecked.getFile(f);
  }

  /** A new temporary folder as the {@code java.io.File} OkHttp's {@code Cache} takes ({@link #asFile}). */
  public static java.io.File okHttpCacheDir(String prefix) throws IOException {
    return asFile(tempDir(prefix));
  }

  public static byte[] read(Filepath f) throws IOException {
    try (InputStream in = f.openInputStream()) {
      return in.readAllBytes();
    }
  }

  public static String text(Filepath f) throws IOException {
    return new String(read(f), StandardCharsets.UTF_8);
  }

  /** The file's lines, split as BufferedReader.readLine splits them (\n, \r\n or \r). */
  public static List<String> lines(Filepath f) throws IOException {
    List<String> out = new ArrayList<>();
    try (BufferedReader r = f.openBufferedReader()) {
      for (String line = r.readLine(); line != null; line = r.readLine()) out.add(line);
    }
    return out;
  }

  /** The names of what is directly inside {@code dir}, sorted. */
  public static List<String> names(Filepath dir) throws IOException {
    try (Stream<Filepath> s = dir.walk(1)) {
      return s.filter(f -> !f.equals(dir)).map(Filepath::getFileName).sorted().collect(Collectors.toList());
    }
  }

  /** Every file under {@code root} (any depth) whose name ends with {@code suffix}, sorted by path. */
  public static List<Filepath> files(Filepath root, String suffix) throws IOException {
    try (Stream<Filepath> s = root.walk()) {
      return s.filter(f -> f.isFile() && f.getFileName().endsWith(suffix)).sorted().collect(Collectors.toList());
    }
  }

  /** {@code f}'s path below {@code root}, with forward slashes. */
  public static String relative(Filepath root, Filepath f) {
    String r = root.toString(), p = f.toString();
    if (!p.startsWith(r)) throw new IllegalArgumentException(p + " is not under " + r);
    String rest = p.substring(r.length()).replace('\\', '/');
    return rest.startsWith("/") ? rest.substring(1) : rest;
  }

  /** {@code root} joined with each of {@code segments}, one folder or file name at a time. */
  public static Filepath at(Filepath root, String... segments) {
    Filepath f = root;
    for (String s : segments) f = f.joinSegment(s);
    return f;
  }
}

