    store.ingest(packet("acct-b", "sb", 2, now - 1000, sellOffer(0, "b1", 565, "Blood rune", 1010, 10)), now - 1000);
    AdviceNotes.Inputs in = new AdviceNotes.Inputs();
    in.marketLatest = latest();
