  private static final String HOUR = "{\"timestamp\":" + (NOW / 1000 / 3600 * 3600 - 3600) + ",\"data\":{\"561\":{\"avgHighPrice\":214,\"highPriceVolume\":300000,\"avgLowPrice\":200,\"lowPriceVolume\":300000}}}";
