import net.runelite.client.util.Filepath;

/**
 * THE SIDEBAR'S BUTTONS IN IN_PROCESS MODE (SELF-CONTAINED decision 12): every golden transcript in which the real bridge was sent a
 * sidebar button (Block, Personal use on a buy, "Yours, not stock", "I don't have this anymore", Reset, "I took this one"), replayed
 * through the PLUGIN's own stores -- {@link PluginJournal}'s marks, {@link BlockedItems} over a config map, the profit reset in that
 * map, {@link SuggestionRecords} -- and the real {@link InProcessEngine} thread. Where the bridge RESTARTED, the plugin restarts too:
 * a NEW journal, engine, records and block list over the SAME folder and config map (nothing carried in memory). Asserted:
 * <ol>
 *   <li>every poll's body is the bridge's (BodyDiff, the one plugin-only field aside) -- so the engine received the inputs the
 *       bridge fed itself after the same presses, before and after every restart;</li>
 *   <li>THE ID: every suggestion's id is the bridge's id, character for character, and {@code accepted} is the bridge's;</li>
 *   <li>a press the bridge refused (400) is refused by the plugin's store with the bridge's message, and one it took is taken;</li>
 *   <li>after the last step, one more restart leaves the journal's marks (personal use, kept counts, closed positions) as they were.</li>
 * </ol>
 * Flip imports (a scanner action; the plugin has none) are put in place as the account's imported journal file, which the plugin
 * journal replays as it replays any import.
 */
public final class InProcessButtonsTest {
  static int checks;

  static void check(boolean ok, String message) {
    if (!ok) throw new AssertionError(message);
    checks++;
  }

  /** Every transcript holding a sidebar POST; the three sidebar-* ones also restart the bridge after each press. */
  static final List<String> REQUIRED = List.of("sidebar-block-persists", "sidebar-accept-persists", "sidebar-marks-persist",
    "version-and-profit-reset", "tier-inventory-kept-count", "tier-inventory-personal-use-blanket", "yours-not-stock-marks",
    "personal-use-buy", "not-held-close");

  public static void main(String[] args) throws Exception {
    int[] totals = new int[5];
    List<String> seen = new ArrayList<>();
    for (String name : EngineRig.index()) {
      JsonObject t = EngineRig.transcript(name);
      if (!hasSidebarPost(t)) continue;
      int[] r = replay(name, t);
      seen.add(name);
      for (int i = 0; i < r.length; i++) totals[i] += r[i];
    }
    for (String r : REQUIRED) check(seen.contains(r), "a transcript with sidebar presses is no longer replayed: " + r);
    check(totals[1] >= 10 && totals[2] >= 8 && totals[3] >= 6 && totals[4] >= 4,
      "too little exercised: " + java.util.Arrays.toString(totals));
    System.out.println("PASS: in-process sidebar buttons (" + checks + " checks) -- " + seen.size() + " transcripts with sidebar presses, "
      + totals[0] + " polls whose body AGREES with the real bridge's after the same presses through the plugin's own stores (" + totals[1]
      + " carrying the bridge's very suggestion id and accepted flag), " + totals[2] + " presses answered as the bridge answered them, "
      + totals[3] + " plugin restarts where the bridge restarted, " + totals[4] + " marks unchanged across a final restart");
  }

  static boolean hasSidebarPost(JsonObject t) {
    for (JsonElement se : t.getAsJsonArray("steps")) {
      JsonObject s = se.getAsJsonObject();
      if (!s.has("request")) continue;
      String p = s.getAsJsonObject("request").get("path").getAsString();
      if (p.startsWith("/api/suggestion/") || p.equals("/api/profit/reset")) return true;
    }
    return false;
  }

  /** The plugin's stores for one plugin lifetime (a restart builds a new one over the same folder and config map). */
  static final class Life {
    PluginJournal journal;
    InProcessEngine engine;
    SuggestionRecords records;
    BlockedItems blocks;
    /** EviLivePlugin.inProcessProfitSince: read from the config at start, set (with the config) by Reset. */
    final java.util.concurrent.atomic.AtomicReference<Long> since = new java.util.concurrent.atomic.AtomicReference<>();
  }

  static Life start(Filepath root, AtomicLong clock, Map<String, String> config, EngineRig.TestMarket tm, Life before, List<String> logged) {
    Life l = new Life();
    l.journal = new PluginJournal(root, clock::get, EngineRig.PARSER, () -> false, logged::add);
    l.journal.start(before == null ? null : before.journal);
    l.records = new SuggestionRecords(root, EngineRig.PARSER, logged::add);
    // per character since 8 Oct 2026: one list per profile (here the account stands for its RuneScape profile)
    l.blocks = new BlockedItems(new BlockedItems.Store() {
      @Override public String read(String profile) {
        return config.get(profile + "." + BlockedItems.CONFIG_KEY);
      }

      @Override public void write(String profile, String value) {
        if (value.isEmpty()) config.remove(profile + "." + BlockedItems.CONFIG_KEY);
        else config.put(profile + "." + BlockedItems.CONFIG_KEY, value);
      }
    });
    String since = config.get("inProcessProfitSince"); // read once at start, as EviLivePlugin.readProfitSince
    l.since.set(since == null ? null : Long.valueOf(since));
    l.engine = new InProcessEngine(root, EngineFeed.journalOf(() -> l.journal),
      InProcessEngineTest.withHistory(tm, InProcessEngine.BASIS_HOURS), EngineRig.PARSER, logged::add, () -> false, l.since::get,
      RecordedSeries.of(id -> tm.body(InProcessEngineTest.API + "timeseries?id=" + id + "&timestep=1h")), l.blocks::all, l.records); // the query's account's list
    return l;
  }

  /** The query without its account parameter: the poll a plugin with no account worked out sends. */
  static String withoutAccount(String query) {
    StringBuilder b = new StringBuilder();
    for (String part : query.split("&")) {
      if (part.startsWith("account=")) continue;
      if (b.length() > 0) b.append('&');
      b.append(part);
    }
    return b.toString();
  }

  /**
   * The REAL plugin's blockedFor (EviLivePlugin, reached by reflection: another package) over these blocks, IN_PROCESS, with
   * {@code last} remembered as the last logged-in character (the rig's profiles are its accounts), or none when null.
   */
  @SuppressWarnings("unchecked")
  static java.util.function.Function<String, java.util.Collection<Integer>> pluginBlocks(BlockedItems blocks, String last) throws Exception {
    com.evi.live.EviLivePlugin p = new com.evi.live.EviLivePlugin();
    java.lang.reflect.Field f = com.evi.live.EviLivePlugin.class.getDeclaredField("blockedItems");
    f.setAccessible(true);
    f.set(p, blocks);
    if (last != null) {
      java.lang.reflect.Method remember = com.evi.live.EviLivePlugin.class.getDeclaredMethod("rememberLastProfile", String.class);
      remember.setAccessible(true);
      remember.invoke(p, last);
    }
    java.lang.reflect.Method m = com.evi.live.EviLivePlugin.class.getDeclaredMethod("blockedFor", String.class);
    m.setAccessible(true);
    return account -> {
      try {
        return (java.util.Collection<Integer>) m.invoke(p, account);
      } catch (Exception e) {
        throw new IllegalStateException(e);
      }
    };
  }

  /** One query (asked twice, as a cold engine needs) to a side engine over this lifetime's journal and market, with the given block
   *  lists and NO suggestion records (so the replay's own ids are untouched); its suggestion, or null. */
  static JsonElement suggestionFor(Life life, EngineRig.TestMarket tm, Filepath root, List<String> logged,
                                   java.util.function.Function<String, java.util.Collection<Integer>> blocked, String query, long at) throws Exception {
    InProcessEngine side = new InProcessEngine(root, EngineFeed.journalOf(() -> life.journal), InProcessEngineTest.withHistory(tm, InProcessEngine.BASIS_HOURS),
      EngineRig.PARSER, logged::add, () -> false, life.since::get,
      RecordedSeries.of(id -> tm.body(InProcessEngineTest.API + "timeseries?id=" + id + "&timestep=1h")), blocked, null);
    try {
      InProcessEngine.Answer o = null;
      for (int k = 0; k < 2; k++) o = side.request(query, at).get(60, TimeUnit.SECONDS);
      return o == null || o.body == null ? null : EngineRig.j(o.body).getAsJsonObject().get("suggestion");
    } finally {
      side.shutdown();
      check(side.awaitTermination(30_000), "the side engine stopped");
    }
  }

  static void stop(Life l) throws Exception {
    l.engine.shutdown();
    check(l.engine.awaitTermination(30_000), "the engine stopped");
    l.journal.shutdown();
    l.journal.awaitIdle(30_000);
  }

  /** Returns {polls compared, ids compared, presses compared, restarts, marks checked after the final restart}. */
  static int[] replay(String name, JsonObject t) throws Exception {
    int polls = 0, ids = 0, presses = 0, restarts = 0, kept = 0;
    Filepath root = TestFiles.tempDir("evi-buttons-test");
    AtomicLong clock = new AtomicLong();
    List<String> logged = Collections.synchronizedList(new ArrayList<>());
    Map<String, String> config = new ConcurrentHashMap<>();
    JsonObject boot = t.getAsJsonObject("input").getAsJsonObject("boot");
    JsonElement prefs = boot.get("preferences");
    if (prefs != null && !prefs.isJsonNull()) root.joinSegment(InProcessEngine.PREFERENCES).write(prefs.toString().getBytes(StandardCharsets.UTF_8));
    List<HourBucket> archive = null;
    JsonElement a = boot.get("archive1h");
    if (a != null && a.isJsonArray()) {
      archive = new ArrayList<>();
      for (JsonElement b : a.getAsJsonArray()) archive.add(HourBucket.parseLine(b.toString()));
    }
    EngineRig.TestMarket tm = new EngineRig.TestMarket(archive, t.getAsJsonArray("wiki"));
    Life life = start(root, clock, config, tm, null, logged);
    String account = null; // the account the last packet named
    // THE PRESSER: the account of the poll whose pick the button was pressed on (the plugin presses for the account it polls
    // for), else the packets'. One account in every transcript but tier-inventory-personal-use-blanket.
    String presser = null;
    int intended = 0;
    try {
      for (JsonElement se : t.getAsJsonArray("steps")) {
        JsonObject s = se.getAsJsonObject();
        long at = s.get("at").getAsLong();
        String where = name + " step " + s.get("i").getAsInt();
        clock.set(at);
        if (s.has("restart")) {
          stop(life);
          life = start(root, clock, config, tm, life, logged);
          restarts++;
          continue;
        }
        if (s.has("store1h")) {
          List<HourBucket> hours = new ArrayList<>();
          for (JsonElement b : s.getAsJsonArray("store1h")) hours.add(HourBucket.parseLine(b.toString()));
          tm.store(hours);
          continue;
        }
        if (!s.has("request")) continue;
        JsonObject r = s.getAsJsonObject("request");
        String path = r.get("path").getAsString(), method = r.get("method").getAsString();
        JsonObject body = r.has("body") && r.get("body").isJsonObject() ? r.getAsJsonObject("body") : new JsonObject();
        JsonObject response = s.getAsJsonObject("response");
        int status = response.get("status").getAsInt();
        if (method.equals("POST") && path.equals("/api/events")) {
          life.journal.offerPacket(r.get("body").toString());
          if (body.has("account") && body.get("account").isJsonPrimitive()) account = body.get("account").getAsString();
          continue;
        }
        if (method.equals("POST") && path.equals("/api/flips/import")) {
          // the history tier's flips, as an imported file (see the class note); written once, before the next poll reads it
          List<JournalRecord> recs = new ArrayList<>();
          new Store(recs::add).importFlips(body);
          StringBuilder sb = new StringBuilder();
          for (JournalRecord x : recs) sb.append(JournalCodec.encodeLine(x)).append('\n');
          life.journal.awaitIdle(30_000);
          Filepath dir = root.joinSegment(PluginJournal.JOURNAL_DIR);
          dir.createDirectories();
          dir.joinSegment("imported-" + account + ".jsonl").write(sb.toString().getBytes(StandardCharsets.UTF_8));
          continue;
        }
        if (method.equals("POST")) {
          String refusal = press(life, path, body, presser != null ? presser : account, at, config);
          String bridgeError = status == 200 ? null : response.getAsJsonObject("body").get("error").getAsString();
          check(java.util.Objects.equals(refusal, bridgeError), where + " " + path + ": the bridge answered " + status + " " + bridgeError
            + ", the plugin's store " + (refusal == null ? "took it" : "refused it: " + refusal));
          presses++;
          continue;
        }
        if (!path.equals("/api/suggestion")) continue;
        tm.at = at;
        presser = queryAccount(r.get("query").getAsString(), presser);
        JsonObject bridge = response.getAsJsonObject("body");
        int repeat = s.has("repeat") ? s.get("repeat").getAsInt() : 1;
        InProcessEngine.Answer ans = null;
        // as the recorder did: the cold first issue (its own query when it differed), then the recorded one
        for (int k = 0; k < repeat; k++) {
          String q = k < repeat - 1 && s.has("warmupQuery") ? s.get("warmupQuery").getAsString() : r.get("query").getAsString();
          ans = life.engine.request(q, at).get(60, TimeUnit.SECONDS);
        }
        check(ans != null && ans.body != null, where + ": no body (" + (ans == null ? "replaced" : ans.unavailable) + ")");
        JsonObject plugin = EngineRig.j(ans.body).getAsJsonObject();
        if (name.equals("tier-inventory-personal-use-blanket") && s.has("label") && s.get("label").getAsString().equals("after-mark")) {
          // THE ONE INTENDED DIFFERENCE (8 Oct 2026). Two accounts' bags were read in the minute before the press and the bridge's
          // request names no presser, so it stores the BLANKET mark and the whip is never offered again. The plugin always names
          // its own account (acct-a, whose pick was on screen), so its mark keeps acct-a's count, 2, and the third whip -- the
          // surplus -- is offered. Asserted as the per-account result, not compared with the bridge.
          JsonElement ps0 = plugin.get("suggestion");
          check(bridge.get("suggestion") == null || bridge.get("suggestion").isJsonNull(), where + ": the bridge's blanket mark hides the whip");
          check(ps0 != null && ps0.isJsonObject() && ps0.getAsJsonObject().get("itemId").getAsInt() == 4151
            && ps0.getAsJsonObject().get("quantity").getAsInt() == 1 && "sell".equals(ps0.getAsJsonObject().get("action").getAsString())
            && "inventory".equals(ps0.getAsJsonObject().get("source").getAsString()),
            where + ": the plugin's mark counts the presser's 2, so the surplus whip is offered: " + ps0);
          intended++;
          polls++;
          continue;
        }
        if (name.equals("sidebar-block-persists") && s.has("label") && s.get("label").getAsString().equals("after-block")) {
          // PER CHARACTER (8 Oct 2026), asserted explicitly: the bridge's block is one for the machine, the plugin's is acct-a's own.
          // The very same poll for ANOTHER account still gets the whip (the shared history tier's pick before the block).
          String other = r.get("query").getAsString().replace("account=" + presser, "account=acct-other");
          check(!other.equals(r.get("query").getAsString()), where + ": the poll names its account");
          InProcessEngine.Answer o = null;
          for (int k = 0; k < 2; k++) o = life.engine.request(other, at).get(60, TimeUnit.SECONDS);
          JsonElement os = o == null || o.body == null ? null : EngineRig.j(o.body).getAsJsonObject().get("suggestion");
          check(os != null && os.isJsonObject() && os.getAsJsonObject().get("itemId").getAsInt() == 4151,
            where + ": another character is not blocked by acct-a's press: " + os);
          intended++;
          // BEFORE LOGIN (the maintainer, 8 Oct 2026): the same poll naming NO account, answered by an engine handed the REAL plugin's
          // blockedFor over this config. With the presser as the last logged-in character the whip stays blocked; a plugin with no
          // last character offers it (no list, as before the change).
          String none = withoutAccount(r.get("query").getAsString());
          check(!none.contains("account="), where + ": the query no longer names an account: " + none);
          JsonElement lastKnown = suggestionFor(life, tm, root, logged, pluginBlocks(life.blocks, presser), none, at);
          check(lastKnown == null || lastKnown.isJsonNull() || lastKnown.getAsJsonObject().get("itemId").getAsInt() != 4151,
            where + ": before login, the last character's block holds: " + lastKnown);
          JsonElement neverKnown = suggestionFor(life, tm, root, logged, pluginBlocks(life.blocks, null), none, at);
          check(neverKnown != null && neverKnown.isJsonObject() && neverKnown.getAsJsonObject().get("itemId").getAsInt() == 4151,
            where + ": no character ever logged in: no list, the whip is offered: " + neverKnown);
          intended++;
          // the press's own account, asked again AFTER the other one, is still blocked (the list is read per query)
          ans = life.engine.request(r.get("query").getAsString(), at).get(60, TimeUnit.SECONDS);
          plugin = EngineRig.j(ans.body).getAsJsonObject();
        }
        List<BodyDiff.Difference> d = BodyDiff.diff(bridge, InProcessEngineTest.without(plugin, "sellBreakEven"));
        check(d.isEmpty(), where + ": the in-process body differs from the bridge's: " + d.subList(0, Math.min(3, d.size())));
        polls++;
        JsonElement bs = bridge.get("suggestion"), ps = plugin.get("suggestion");
        if (bs != null && bs.isJsonObject()) {
          JsonObject b = bs.getAsJsonObject(), p = ps.getAsJsonObject();
          check(b.has("id") && p.has("id") && b.get("id").getAsString().equals(p.get("id").getAsString()),
            where + ": the suggestion id is not the bridge's: bridge " + b.get("id") + ", plugin " + p.get("id"));
          check(b.get("accepted").getAsBoolean() == p.get("accepted").getAsBoolean(),
            where + ": accepted is not the bridge's: bridge " + b.get("accepted") + ", plugin " + p.get("accepted"));
          ids++;
        }
      }
      // one more restart: the journal's marks read back as they were
      StoreState before = state(life, clock.get());
      stop(life);
      life = start(root, clock, config, tm, life, logged);
      StoreState after = state(life, clock.get());
      check(before.personalUseBuyIds.equals(after.personalUseBuyIds), name + ": personal-use buys changed across a restart");
      check(before.personalUseItemIds.equals(after.personalUseItemIds) && before.personalUseItems.equals(after.personalUseItems)
        && before.personalUseKept.equals(after.personalUseKept), name + ": item marks or kept counts changed across a restart");
      check(before.closedPositions.size() == after.closedPositions.size() && before.autoOpenPositions.size() == after.autoOpenPositions.size(),
        name + ": closed or open positions changed across a restart");
      kept++;
      check(intended == (name.equals("sidebar-block-persists") ? 2 : name.equals("tier-inventory-personal-use-blanket") ? 1 : 0),
        name + ": the intended per-account difference was met " + intended + " times");
      for (String l : logged) check(!l.contains("could not be saved") && !l.contains("could not be logged"), name + ": " + l);
    } finally {
      stop(life);
      root.deleteRecursively();
    }
    return new int[]{polls, ids, presses, restarts, kept};
  }

  /** The account a recorded poll query names (account=...), else {@code fallback}. */
  static String queryAccount(String query, String fallback) {
    for (String part : query.split("&")) if (part.startsWith("account=") && part.length() > 8) return part.substring(8);
    return fallback;
  }

  static StoreState state(Life l, long now) throws Exception {
    PluginJournal.EngineView v = l.journal.engineView(now).get(30, TimeUnit.SECONDS);
    check(v != null, "the journal answered");
    return v.state;
  }

  /**
   * One sidebar press, through the plugin's own store for it -- what EviLivePlugin does in IN_PROCESS mode -- with the body the
   * plugin would have sent the bridge. Returns null when taken, else the refusal.
   */
  static String press(Life l, String path, JsonObject body, String account, long at, Map<String, String> config) throws Exception {
    switch (path) {
      case "/api/suggestion/block":
        return l.blocks.block(account, body.get("itemId").getAsInt()) ? null : "refused"; // the presser's character
      case "/api/profit/reset":
        l.since.set(at); // EviLivePlugin.resetProfit: the field the engine reads, and the config write
        config.put("inProcessProfitSince", String.valueOf(at));
        return null;
      case "/api/suggestion/accept":
        return l.records.accept(body.get("id").getAsString(), account, body.get("itemId").getAsInt(), body.get("accepted").getAsBoolean(), at)
          ? null : "refused";
      case "/api/suggestion/not-held":
        return l.journal.closePosition(account, body.get("buyId").getAsString()).get(30, TimeUnit.SECONDS);
      case "/api/suggestion/personal-use":
        if (body.has("buyId") && !body.get("buyId").isJsonNull())
          return l.journal.markPersonalUse(account, body.get("buyId").getAsString()).get(30, TimeUnit.SECONDS);
        int itemId = body.get("itemId").getAsInt();
        // the plugin names the presser (its own account); the bridge, given no account, finds the one bag read in the last
        // minute (the 8 Oct fix) -- the same bag in every replayed transcript, which the bodies and the marks prove
        return l.journal.markPersonalUseItem(account, itemId, l.engine.keptFor(account, itemId, at)).get(30, TimeUnit.SECONDS);
      default:
        throw new IllegalStateException("not a sidebar press: " + path);
    }
  }
}

package com.evi.live.inprocess;

import com.evi.live.TestFiles;
import com.evi.live.inprocess.EngineFeed;
import com.evi.live.inprocess.InProcessEngine;
import com.evi.live.journal.PluginJournal;
import com.evi.live.market.HourBucket;
import com.evi.live.market.ItemCatalog;
import com.evi.live.market.MarketAggregates;
import com.evi.live.market.WikiJson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import net.runelite.client.util.Filepath;

/**
 * THE IN-PROCESS ENGINE (com.evi.live.inprocess), which answers the sidebar. Uses {@link EngineRig}'s transcript rig (a REAL
 * {@link PluginJournal} fed the transcript's packets, and the transcript's market as the price layer would hold it).
 * <ol>
 *   <li>THE COMPOSITION REPRODUCES THE BRIDGE: with the price history complete, every poll of every transcript in the in-process
 *       scope, asked through the real engine thread, gives the body the real bridge sent (the one field the bridge never sends,
 *       {@code sellBreakEven}, aside -- and it is checked against the relist notes' own break-even);</li>
 *   <li>THE FIRST-RUN GATE: one hour short of the basis ({@link InProcessEngine#BASIS_HOURS}, the engine's own
 *       {@link MarketAggregates#ROBUST_PRICE_HOURS}) no poll offers a buy, a further position or a reachable figure; every
 *       poll whose bridge answer was a SELL still gets that very sell; the advice, prices, fill estimates, slots and profit
 *       line are the bridge's; at the basis the buys come back;</li>
 *   <li>the price-history line's words and numbers, ASCII; the query without the buy tiers;</li>
 *   <li>the thread: the hand-over returns at once, a newer query replaces a waiting one, the work refuses the client thread
 *       and the EDT, decide runs on evi-engine only, and a shut-down engine answers nothing.</li>
 * </ol>
 */
public final class InProcessEngineTest {
  static int checks;

  static void check(boolean ok, String message) {
    if (!ok) throw new AssertionError(message);
    checks++;
  }

  public static void main(String[] args) throws Exception {
    pure();
    int[] open = transcripts(true, false);
    int[] openSeries = transcripts(true, true);
    int[] closed = transcripts(false, true);
    // the whole basis, but the latest prices one millisecond past STALE_PRICES_MS old: buys held back exactly as one hour short
    staleRun = true;
    int[] stale = transcripts(false, true);
    staleRun = false;
    check(stale[2] > 0 && stale[2] == closed[2] && stale[3] == closed[3], "stale prices withhold the same buys and keep the same sells as a short history: "
      + stale[2] + "/" + stale[3] + " against " + closed[2] + "/" + closed[3]);
    threads();
    int readHours = com.evi.live.market.ReadHoursCheck.run(); // the price layer's archive door the engine reads through
    checks += readHours;
    System.out.println("PASS: in-process engine (" + checks + " checks, " + readHours + " of them the archive read) -- " + open[0] + " transcripts / " + open[1] + " polls through the real engine"
      + " thread AGREEING with the real bridge's body once the price history holds the basis (" + openSeries[0] + " / " + openSeries[1] + " whole, with"
      + " the bridge's recorded per-item series handed in, " + openSeries[2] + " of them buys); one hour short, " + closed[2] + " bridge buys withheld"
      + " (no buy, no further position, no reachable figure) while " + closed[3] + " sells still spoke as the bridge's; the price-history line, the"
      + " query without the buy tiers, the hand-over never blocking, newest query wins, never on the client thread or the EDT");
  }

  // ------------------------------------------------------------------------------------------- 1. pure

  static EngineFeed.Market market(int stored, int window, int unavailable, boolean catchingUp, int readings) {
    return new EngineFeed.Market(null, 0, null, null, null, null, Long.MIN_VALUE, stored, window, 0, 0, 0, unavailable, catchingUp, readings);
  }

  static void pure() throws IOException {
    int basis = InProcessEngine.BASIS_HOURS;
    check(basis == MarketAggregates.ROBUST_PRICE_HOURS, "the gate is the engine's own 336-hour constant, not a new number");
    int window = basis + 1;
    check(!InProcessEngine.buysReady(null) && InProcessEngine.backfillLine(null) == null, "no market known: no gate line, no buys");
    check(!InProcessEngine.buysReady(market(0, window, 0, true, 0)), "an empty archive withholds buys");
    check(!InProcessEngine.buysReady(market(basis - 1, window, 0, true, basis - 1)), "one hour short withholds buys");
    check(InProcessEngine.buysReady(market(basis, window, 0, true, basis)), "the basis releases them");
    check(InProcessEngine.buysReady(market(window, window, 0, false, window)), "the whole window releases them");
    check(!InProcessEngine.buysReady(market(window, window, 0, false, basis - 1)),
      "every hour downloaded but the readings not yet rebuilt over them: still withheld (the engine ranks on the READINGS)");
    check(("Loading price history: 140 of " + basis + " hours. Buy suggestions start when it's done.").equals(InProcessEngine.backfillLine(market(140, window, 0, true, 120))),
      "the progress line: " + InProcessEngine.backfillLine(market(140, window, 0, true, 120)));
    check(("Loading price history: 0 of " + basis + " hours. Buy suggestions start when it's done.").equals(InProcessEngine.backfillLine(market(0, window, 0, true, 0))),
      "a first run starts at 0");
    check(("Loading price history: " + basis + " of " + basis + " hours. Buy suggestions start when it's done.").equals(InProcessEngine.backfillLine(market(window, window, 0, false, 100))),
      "downloaded but not rebuilt: never more than the basis");
    check(InProcessEngine.backfillLine(market(basis, window, 0, false, basis)) == null, "no line once buys are released");
    String gaveUp = InProcessEngine.backfillLine(market(300, window, 37, false, 300));
    check(gaveUp != null && gaveUp.startsWith("Price history: 300 of " + basis + " hours.") && gaveUp.contains("next starts")
      && gaveUp.endsWith("Buy suggestions start once it is complete."), "hours the Wiki would not send: said so, with the retry: " + gaveUp);
    for (String l : new String[]{InProcessEngine.backfillLine(market(140, window, 0, true, 120)), gaveUp})
      for (char c : l.toCharArray()) check(c >= 32 && c < 127, "ASCII only: " + l);
    // the query without the buy tiers
    check(InProcessEngine.withoutBuyTiers("").equals("source=market"), "an empty query");
    check(InProcessEngine.withoutBuyTiers("minProfit=500&includeMarket=1&account=a&source=both&cash=5")
      .equals("minProfit=500&account=a&cash=5&source=market"), InProcessEngine.withoutBuyTiers("minProfit=500&includeMarket=1&account=a&source=both&cash=5"));
    check(InProcessEngine.withoutBuyTiers("includeMarket=1&includeMarket=1&source=market&source=history").equals("source=market"), "repeated names all go");
    check(InProcessEngine.withoutBuyTiers("include%4Darket=1&sourc%65=history&x=1").equals("x=1&source=market"),
      "names compared as the engine DECODES them (URLSearchParams): " + InProcessEngine.withoutBuyTiers("include%4Darket=1&sourc%65=history&x=1"));
    check(InProcessEngine.withoutBuyTiers("myincludeMarket=1&holdItemId=5").equals("myincludeMarket=1&holdItemId=5&source=market"), "only those two names");
    thinIndexAfterCatchUp();
    // STALE PRICES (review, 10 Oct): past STALE_PRICES_MS buys wait for fresh ones, with a line saying how old they are
    long fetched = 1_000_000_000L;
    check(InProcessEngine.STALE_PRICES_MS == 10 * 60_000L, "the maintainer's ten minutes");
    check(!InProcessEngine.pricesStale(fetched, fetched + InProcessEngine.STALE_PRICES_MS), "exactly ten minutes old: still quoted");
    check(InProcessEngine.pricesStale(fetched, fetched + InProcessEngine.STALE_PRICES_MS + 1), "past ten minutes: stale");
    check(!InProcessEngine.pricesStale(0, fetched), "no prices at all is not 'stale' (nothing is quoted; the waiting line speaks)");
    String staleLine = InProcessEngine.staleLine(fetched, fetched + 25 * 60_000L + 59_000L);
    check(("The latest prices from the OSRS Wiki are 25 minutes old. Buy suggestions are paused until fresh prices arrive (they load"
      + " while you are logged in).").equals(staleLine), "the stale line: " + staleLine);
    for (char c : staleLine.toCharArray()) check(c >= 32 && c < 127, "ASCII only: " + staleLine);
  }

  /**
   * THE THIN INDEX AFTER A CATCH-UP (10 Oct): built while the archive was still catching up it misses the older hours
   * of the gap; it is built once more when the catch-up ends, and otherwise kept for the bridge's six hours.
   */
  static void thinIndexAfterCatchUp() throws IOException {
    AtomicLong stored = new AtomicLong(330);
    AtomicReference<Boolean> catching = new AtomicReference<>(true);
    AtomicLong reads = new AtomicLong();
    EngineFeed feed = new EngineFeed(new EngineFeed.MarketSource() {
      @Override public EngineFeed.Market market(long nowMs) {
        return null;
      }

      @Override public CompletableFuture<List<HourBucket>> hoursFrom(long fromTs) {
        reads.incrementAndGet();
        List<HourBucket> hours = new ArrayList<>();
        try {
          for (int i = 0; i < stored.get(); i++) hours.add(HourBucket.parseLine("{\"ts\":" + (3600L * (1000 + i)) + ",\"d\":{\"2\":[5,10,4,10]}}"));
        } catch (IOException e) {
          throw new AssertionError(e);
        }
        return CompletableFuture.completedFuture(hours);
      }
    }, 5_000);
    long t0 = 1_000_000_000L;
    feed.refresh(market(330, 337, 0, catching.get(), 330), t0, new JsonObject());
    check(feed.thin() != null && feed.thin().hours == 330, "built mid catch-up on the hours stored then");
    stored.set(334);
    feed.refresh(market(334, 337, 0, true, 334), t0 + 60_000, new JsonObject());
    check(feed.thin().hours == 330, "still catching up: kept, not rebuilt on every poll");
    feed.refresh(market(337, 337, 0, false, 337), t0 + 120_000, new JsonObject());
    long readsAtEnd = reads.get();
    check(feed.thin().hours == 334, "the catch-up ended: built once more over the whole archive, got " + feed.thin().hours);
    stored.set(336);
    feed.refresh(market(337, 337, 0, false, 337), t0 + 180_000, new JsonObject());
    check(feed.thin().hours == 334, "built on a complete archive: kept for the six hours as the bridge keeps it");
    feed.refresh(market(337, 337, 0, false, 337), t0 + 120_000 + EngineFeed.THIN_EVERY_MS, new JsonObject());
    check(feed.thin().hours == 336, "and rebuilt when the six hours are up");
    check(reads.get() >= readsAtEnd + 1, "the rebuilds read the archive");
    // a complete archive from the start: the old clock alone
    EngineFeed whole = new EngineFeed(new EngineFeed.MarketSource() {
      @Override public EngineFeed.Market market(long nowMs) {
        return null;
      }

      @Override public CompletableFuture<List<HourBucket>> hoursFrom(long fromTs) {
        List<HourBucket> hours = new ArrayList<>();
        try {
          for (int i = 0; i < stored.get(); i++) hours.add(HourBucket.parseLine("{\"ts\":" + (3600L * (1000 + i)) + ",\"d\":{\"2\":[5,10,4,10]}}"));
        } catch (IOException e) {
          throw new AssertionError(e);
        }
        return CompletableFuture.completedFuture(hours);
      }
    }, 5_000);
    whole.refresh(market(337, 337, 0, false, 337), t0, new JsonObject());
    stored.set(300);
    whole.refresh(market(337, 337, 0, false, 337), t0 + 60_000, new JsonObject());
    check(whole.thin().hours == 336, "never catching up: unchanged behaviour, kept between polls");
  }
  // ------------------------------------------------------------------------------------------- 2. the transcripts

  /** The rig's market with the backfill state the gate reads: {@code readings} stored hours behind the built readings. */
  static EngineFeed.MarketSource withHistory(EngineRig.TestMarket t, int readings) {
    int window = InProcessEngine.BASIS_HOURS + 1;
    return new EngineFeed.MarketSource() {
      @Override public EngineFeed.Market market(long nowMs) {
        EngineFeed.Market m = t.market(nowMs);
        long fetched = staleRun ? nowMs - InProcessEngine.STALE_PRICES_MS - 1 : m.latestFetchedAtMs;
        return new EngineFeed.Market(m.latest, fetched, m.latestHour, m.catalog, m.typical, m.robust, m.newestStoredTs, readings, window,
          m.robustHours, m.typicalHours, m.archiveRevision, 0, readings < window, readings);
      }

      @Override public CompletableFuture<List<HourBucket>> hoursFrom(long fromTs) {
        return t.hoursFrom(fromTs);
      }
    };
  }

  static boolean isBuy(JsonElement s) {
    return s != null && s.isJsonObject() && s.getAsJsonObject().has("action") && "buy".equals(s.getAsJsonObject().get("action").getAsString());
  }

  static boolean isSell(JsonElement s) {
    return s != null && s.isJsonObject() && s.getAsJsonObject().has("action") && "sell".equals(s.getAsJsonObject().get("action").getAsString());
  }

  static JsonObject without(JsonObject body, String... keys) {
    JsonObject o = body.deepCopy();
    for (String k : keys) o.remove(k);
    return o;
  }

  /**
   * Every in-scope transcript through the real engine thread and a real plugin journal. {@code complete}: the readings rest on
   * the basis (every body must agree with the bridge's); else one hour short (buys withheld, sells and advice kept).
   * Returns {transcripts, polls, buys withheld, sells kept}.
   */
  /** While set, {@link #withHistory} reports the latest prices as just past {@link InProcessEngine#STALE_PRICES_MS} old, and
   *  {@link #transcripts} stores the WHOLE basis while expecting buys withheld (review, 10 Oct). */
  static boolean staleRun;

  static int[] transcripts(boolean complete, boolean withSeries) throws Exception {
    int transcripts = 0, polls = 0, withheld = 0, sellsKept = 0, breakEvens = 0, buys = 0;
    for (String name : EngineRig.index()) {
      JsonObject t = EngineRig.transcript(name);
      if (EngineRig.outOfScope(t) != null) continue;
      // Production asks no per-item series: compared only up to the bridge's first one. With the recorded series handed in
      // (tests only), the whole transcript.
      long cutoff = withSeries ? Long.MAX_VALUE : EngineRig.firstSeries(t);
      if (EngineRig.pollsBefore(t, cutoff) == 0) continue;
      transcripts++;
      int upTo = EngineRig.stepBefore(t, cutoff);
      Filepath root = TestFiles.tempDir("evi-inprocess-test");
      AtomicLong clock = new AtomicLong();
      List<String> logged = Collections.synchronizedList(new ArrayList<>());
      JsonObject boot = t.getAsJsonObject("input").getAsJsonObject("boot");
      JsonElement prefs = boot.get("preferences");
      if (prefs != null && !prefs.isJsonNull()) root.joinSegment(InProcessEngine.PREFERENCES).write(prefs.toString().getBytes(StandardCharsets.UTF_8));
      PluginJournal journal = new PluginJournal(root, clock::get, EngineRig.PARSER, () -> false, logged::add);
      journal.start();
      List<HourBucket> archive = null;
      JsonElement a = boot.get("archive1h");
      if (a != null && a.isJsonArray()) {
        archive = new ArrayList<>();
        for (JsonElement b : a.getAsJsonArray()) archive.add(HourBucket.parseLine(b.toString()));
      }
      EngineRig.TestMarket tm = new EngineRig.TestMarket(archive, t.getAsJsonArray("wiki"));
      AtomicReference<Long> since = new AtomicReference<>();
      List<String> journalThreads = Collections.synchronizedList(new ArrayList<>());
      EngineFeed.JournalSource real = EngineFeed.journalOf(() -> journal);
      InProcessEngine engine = new InProcessEngine(root, now -> {
        journalThreads.add(Thread.currentThread().getName());
        return real.view(now);
      }, withHistory(tm, complete || staleRun ? InProcessEngine.BASIS_HOURS : InProcessEngine.BASIS_HOURS - 1), EngineRig.PARSER, logged::add, () -> false, since::get,
        withSeries ? com.evi.live.engine.RecordedSeries.of(id -> tm.body(API + "timeseries?id=" + id + "&timestep=1h")) : null);
      try {
        for (JsonElement se : t.getAsJsonArray("steps")) {
          JsonObject s = se.getAsJsonObject();
          if (s.get("i").getAsInt() >= upTo) break;
          if (s.has("store1h")) {
            List<HourBucket> hours = new ArrayList<>();
            for (JsonElement b : s.getAsJsonArray("store1h")) hours.add(HourBucket.parseLine(b.toString()));
            tm.store(hours);
            continue;
          }
          if (!s.has("request")) continue;
          JsonObject r = s.getAsJsonObject("request");
          long at = s.get("at").getAsLong();
          if (r.get("method").getAsString().equals("POST")) {
            clock.set(at);
            journal.offerPacket(r.get("body").toString());
            continue;
          }
          if (!r.get("path").getAsString().equals("/api/suggestion")) continue;
          tm.at = at;
          JsonObject bridge = s.getAsJsonObject("response").getAsJsonObject("body");
          // the plugin keeps the profit reset itself in this mode; the transcripts in scope never press Reset
          JsonElement p = bridge.get("profit");
          since.set(p != null && p.isJsonObject() && p.getAsJsonObject().get("since") != null && !p.getAsJsonObject().get("since").isJsonNull()
            ? p.getAsJsonObject().get("since").getAsLong() : null);
          String query = r.get("query").getAsString();
          InProcessEngine.Answer ans = engine.request(query, at).get(60, TimeUnit.SECONDS);
          String where = name + " step " + s.get("i").getAsInt() + (complete ? " (history complete)" : " (one hour short)");
          check(ans != null && ans.body != null, where + ": no body (" + (ans == null ? "replaced" : ans.unavailable) + ")");
          check(ans.buysReady == complete, where + ": buysReady");
          check(complete == (ans.backfillLine == null), where + ": the price-history line is shown exactly while buys wait: " + ans.backfillLine);
          check(ans.pricesStale == staleRun, where + ": pricesStale");
          if (staleRun) check(ans.backfillLine.startsWith("The latest prices from the OSRS Wiki are 10 minutes old."), where + ": the stale line: " + ans.backfillLine);
          JsonObject plugin = EngineRig.j(ans.body).getAsJsonObject();
          check(plugin.has("sellBreakEven") && plugin.get("sellBreakEven").isJsonObject(), where + ": the one-voice break-evens are sent");
          polls++;
          if (isBuy(bridge.get("suggestion"))) buys++;
          if (complete) {
            List<BodyDiff.Difference> d = BodyDiff.diff(bridge, without(plugin, "sellBreakEven"));
            check(d.isEmpty(), where + ": the in-process body differs from the bridge's: " + d.subList(0, Math.min(3, d.size())));
            // the break-even the plugin will compare with is the relist advice's own
            for (JsonElement n : bridge.getAsJsonArray("relistAdvice")) {
              JsonObject o = n.getAsJsonObject();
              if (!o.has("offerPrice") || !o.has("breakEven") || o.get("breakEven").isJsonNull()) continue;
              JsonElement be = plugin.getAsJsonObject("sellBreakEven").get(o.get("itemId").getAsString());
              check(be != null && be.getAsLong() == o.get("breakEven").getAsLong(), where + ": sellBreakEven for " + o.get("itemId") + " is not the relist's " + o.get("breakEven"));
              breakEvens++;
            }
          } else {
            check(!isBuy(plugin.get("suggestion")), where + ": a BUY was offered one hour short of the basis");
            check(plugin.getAsJsonArray("additional").size() == 0, where + ": a further position was offered one hour short");
            check(BodyDiff.isNullish(plugin.get("reachable")), where + ": a reachable figure one hour short");
            if (isBuy(bridge.get("suggestion"))) withheld++;
            if (isSell(bridge.get("suggestion"))) {
              sellsKept++;
              JsonObject bs = new JsonObject(), ps = new JsonObject(); // wrapped, so the suggestion log's id/accepted stay ignored
              bs.add("suggestion", bridge.get("suggestion"));
              ps.add("suggestion", plugin.get("suggestion"));
              List<BodyDiff.Difference> d = BodyDiff.diff(bs, ps);
              check(d.isEmpty(), where + ": the bridge's SELL did not speak one hour short: " + d);
            }
            // everything about what the player already has is the bridge's (the advice when no buy shaped it)
            String[] buySide = isBuy(bridge.get("suggestion"))
              ? new String[]{"suggestion", "additional", "reachable", "heldBack", "fellThroughFromHistory", "relistAdvice", "sellBreakEven"}
              : new String[]{"suggestion", "additional", "reachable", "heldBack", "fellThroughFromHistory", "sellBreakEven"};
            List<BodyDiff.Difference> d = BodyDiff.diff(without(bridge, buySide), without(plugin, buySide));
            check(d.isEmpty(), where + ": prices, fill estimates, slots, profit or advice differ one hour short: " + d.subList(0, Math.min(3, d.size())));
          }
        }
        check(engine.decisions() > 0 && InProcessEngine.THREAD_NAME.equals(engine.lastDecidedOn()), name + ": decide ran on " + engine.lastDecidedOn());
        for (String th : journalThreads) check(InProcessEngine.THREAD_NAME.equals(th), name + ": the journal was asked from '" + th + "'");
        for (String th : tm.threads) check(InProcessEngine.THREAD_NAME.equals(th), name + ": the market was read from '" + th + "'");
      } finally {
        engine.shutdown();
        journal.shutdown();
        journal.awaitIdle(30_000);
        root.deleteRecursively();
      }
    }
    check(transcripts >= 40 && polls >= 70, "too few transcripts in scope: " + transcripts + " / " + polls);
    if (complete) check(breakEvens >= 1, "no relist note with a break-even was compared: " + breakEvens);
    if (complete && withSeries) check(buys >= 10, "too few bridge buys reproduced to say the buy tiers run: " + buys);
    if (!complete) check(withheld >= 10 && sellsKept >= 10, "too few withheld buys (" + withheld + ") or kept sells (" + sellsKept + ") to say anything");
    return new int[]{transcripts, polls, complete ? buys : withheld, sellsKept};
  }

  // ------------------------------------------------------------------------------------------- 3. the thread

  static final String API = "https://prices.runescape.wiki/api/v1/osrs/";
  static final String LATEST = "{\"data\":{\"554\":{\"high\":6,\"highTime\":1,\"low\":5,\"lowTime\":1}}}";
  static final String MAPPING = "[{\"id\":554,\"name\":\"Fire rune\",\"members\":false,\"limit\":25000}]";

  static EngineFeed.MarketSource tiny(int readings) throws Exception {
    EngineFeed.Market m = new EngineFeed.Market(WikiJson.latest(LATEST), 1_000, null, ItemCatalog.parse(MAPPING), null, null, Long.MIN_VALUE, readings,
      InProcessEngine.BASIS_HOURS + 1, 0, 0, 1, 0, false, readings);
    return new EngineFeed.MarketSource() {
      @Override public EngineFeed.Market market(long nowMs) {
        return m;
      }

      @Override public CompletableFuture<List<HourBucket>> hoursFrom(long fromTs) {
        return CompletableFuture.completedFuture(new ArrayList<>());
      }
    };
  }

  static void threads() throws Exception {
    Filepath root = TestFiles.tempDir("evi-inprocess-threads");
    try {
      // the hand-over returns at once while the engine waits on a journal that has not answered; a newer query replaces a waiting one
      CompletableFuture<PluginJournal.EngineView> held = new CompletableFuture<>();
      List<String> logged = Collections.synchronizedList(new ArrayList<>());
      InProcessEngine e = new InProcessEngine(root, now -> held, tiny(0), EngineRig.PARSER, logged::add, () -> false, () -> null);
      long t0 = System.nanoTime();
      CompletableFuture<InProcessEngine.Answer> first = e.request("account=a", 1);
      CompletableFuture<InProcessEngine.Answer> second = e.request("account=a&x=2", 2);
      CompletableFuture<InProcessEngine.Answer> third = e.request("account=a&x=3", 3);
      check((System.nanoTime() - t0) / 1_000_000 < 500, "the hand-over must return at once");
      check(second.get(5, TimeUnit.SECONDS) == null, "a waiting query is replaced by a newer one (its future completes with null)");
      check(!first.isDone() && !third.isDone(), "the running one is still waiting for the journal");
      held.complete(null); // a journal that has stopped
      InProcessEngine.Answer a1 = first.get(10, TimeUnit.SECONDS), a3 = third.get(10, TimeUnit.SECONDS);
      check(a1 != null && a1.body == null && a1.unavailable.contains("trade record"), "a stopped journal: a plain sentence, no body: " + (a1 == null ? null : a1.unavailable));
      check(a3 != null && "account=a&x=3".equals(a3.query), "the newest query was answered after the running one");
      check(e.decisions() == 0, "decide never ran without a journal");
      check(("Loading price history: 0 of " + InProcessEngine.BASIS_HOURS + " hours. Buy suggestions start when it's done.").equals(a1.backfillLine),
        "the line travels with an answer that has no body too: " + a1.backfillLine);
      e.shutdown();
      check(e.awaitTermination(10_000), "shut down");
      CompletableFuture<InProcessEngine.Answer> late = e.request("account=a", 4);
      check(late.isDone() && late.get() == null, "a shut-down engine answers nothing");

      // the client thread and the EDT are refused: no decide, a plain sentence
      InProcessEngine refusing = new InProcessEngine(root, now -> held, tiny(InProcessEngine.BASIS_HOURS), EngineRig.PARSER, logged::add, () -> true,
        () -> null);
      InProcessEngine.Answer r = refusing.request("account=a", 5).get(10, TimeUnit.SECONDS);
      check(r != null && r.body == null && refusing.decisions() == 0, "work on the client thread / EDT must be refused");
      check(logged.stream().anyMatch(l -> l.contains("not " + InProcessEngine.THREAD_NAME)), "the refusal is logged: " + logged);
      refusing.shutdown();

      // no price data yet: no decide, the reason said plainly
      InProcessEngine noPrices = new InProcessEngine(root, now -> held, new EngineFeed.MarketSource() {
        @Override public EngineFeed.Market market(long nowMs) {
          return new EngineFeed.Market(null, 0, null, null, null, null, Long.MIN_VALUE, 3, InProcessEngine.BASIS_HOURS + 1, 0, 0, 0, 0, true, 0);
        }

        @Override public CompletableFuture<List<HourBucket>> hoursFrom(long fromTs) {
          return CompletableFuture.completedFuture(new ArrayList<>());
        }
      }, EngineRig.PARSER, logged::add, () -> false, () -> null);
      InProcessEngine.Answer np = noPrices.request("account=a", 6).get(10, TimeUnit.SECONDS);
      check(np != null && np.body == null && np.unavailable.startsWith("Loading the item list") && noPrices.decisions() == 0, "no item list yet: " + np.unavailable);
      noPrices.shutdown();
    } finally {
      root.deleteRecursively();
    }
  }
}

package com.evi.live.journal;

import static com.evi.live.journal.ParityJson.check;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;

/**
 * The journal engine's traps, written as INTENT rather than recorded from JS, so a failure here reads as
 * "a rule broke" and a parity failure reads as "Java and JS disagree". Each was proven by sabotage.
 * Every assertion is a literal value, never a re-derivation of the code under test.
 */
public final class JournalIntentTest {
  private static final long T0 = 1789992000000L;

  public static void main(String[] args) {
    // Run under a locale that groups with dots and writes decimal commas: every figure the engine
    // writes must still be en-US (the bridge's 6 Oct F2 fix is the same rule).
    Locale.setDefault(new Locale("nl", "NL"));
    taxRules();
    halfUpRounding();
    probesAreInvisible();
    accountsNeverCross();
    restartMidOffer();
    absentIsNotZero();
    aboveTwoToThe31();
    localeAndLineFormat();
    keptCountsIterateAscending();
    pastTwoToThe63();
    closePositionPastTwoToThe63();
    bridgeWrittenHugePurchase();
    importRefusesUnsafeNet();
    profitSinceBoundary();
    System.out.println("PASS: journal intent -- tax (under-50 floor, the 5,000,000 cap from 250m, exempt chisel and bond, the 30 May 2025 era), "
      + "Math.round half-up on .5 ties (+0.5 -> 1, -1.5 -> -1, capital 2.5 -> 3), the 1-unit instant probe invisible while one at its asked price is a trade, "
      + "FIFO/limits/cost basis never crossing accounts (null account answers nothing), a client restart mid-offer linked to its original, "
      + "absent kept distinct from zero (no window, no tick reading, no completion), totals past 2^31, a recorded cost capped at 2^53 - 1, "
      + "JS-equal GP arithmetic past 2^53 and a loud refusal (never a wrapped sign) past 2^63, closing a position on such a journal refused with the journal's own message, an import whose net is not a safe integer refused, "
      + "the profit line counting a flip whose last sale is exactly at the reset, "
      + "en-US grouping plus JSON.stringify line text under a Dutch default locale, and kept counts listed by ascending item id as a JS object lists them");
  }

  // ------------------------------------------------------------------------------------------ helpers

  private static final class Client {
    final String account, session;
    long seq;
    final JsonObject[] slots = new JsonObject[8];
    int gen;

    Client(String account, String session) {
      this.account = account;
      this.session = session;
    }

    String place(int slot, int itemId, String name, long price, long total, boolean buy) {
      JsonObject o = new JsonObject();
      o.addProperty("itemId", itemId);
      o.addProperty("total", total);
      o.addProperty("filled", 0);
      o.addProperty("price", price);
      o.addProperty("spent", 0);
      String id = session + "-o" + (++gen);
      o.addProperty("offerId", id);
      o.addProperty("state", buy ? "BUYING" : "SELLING");
      o.addProperty("name", name);
      o.addProperty("knownStart", true);
      o.addProperty("ticksToFill", -1);
      slots[slot] = o;
      return id;
    }

    void fill(int slot, long filled, long spent, int ticks) {
      JsonObject o = slots[slot];
      o.addProperty("filled", filled);
      o.addProperty("spent", spent);
      if (ticks >= 0) o.addProperty("ticksToFill", ticks);
      if (filled == o.get("total").getAsLong()) o.addProperty("state", "BUYING".equals(o.get("state").getAsString()) ? "BOUGHT" : "SOLD");
    }

    void cancel(int slot) {
      JsonObject o = slots[slot];
      String st = o.get("state").getAsString();
      o.addProperty("state", "BUYING".equals(st) || "BOUGHT".equals(st) ? "CANCELLED_BUY" : "CANCELLED_SELL");
      o.addProperty("ticksToFill", -1);
    }

    Client restart(String newSession) {
      Client c = new Client(account, newSession);
      for (int i = 0; i < 8; i++) {
        if (slots[i] == null) continue;
        JsonObject o = slots[i].deepCopy();
        o.addProperty("offerId", newSession + "-o" + (++c.gen));
        o.addProperty("knownStart", false);
        o.addProperty("ticksToFill", -1);
        c.slots[i] = o;
      }
      return c;
    }

    JsonObject packet(long ts) {
      JsonObject p = new JsonObject();
      p.addProperty("version", 1);
      p.addProperty("session", session);
      p.addProperty("account", account);
      p.addProperty("seq", ++seq);
      p.addProperty("ts", ts);
      p.addProperty("loggedIn", true);
      JsonArray offers = new JsonArray();
      for (int i = 0; i < 8; i++) {
        JsonObject o;
        if (slots[i] != null) o = slots[i].deepCopy();
        else {
          o = new JsonObject();
          o.addProperty("itemId", 0);
          o.addProperty("total", 0);
          o.addProperty("filled", 0);
          o.addProperty("price", 0);
          o.addProperty("spent", 0);
          o.addProperty("offerId", session + "-e" + i);
          o.addProperty("state", "EMPTY");
          o.addProperty("name", "");
          o.addProperty("knownStart", false);
          o.addProperty("ticksToFill", -1);
        }
        o.addProperty("slot", i);
        offers.add(o);
      }
      p.add("offers", offers);
      return p;
    }
  }

  private static final List<String> journal = new ArrayList<>();

  private static Store fresh() {
    journal.clear();
    return new Store(r -> journal.add(JournalCodec.encodeLine(r)));
  }

  private static long t;

  private static void send(Store s, Client c) {
    t += 1000;
    s.ingest(c.packet(t - 300), t);
  }

  private static Offer probeBuy(long price, long spent, int ticks) {
    return new Offer(0, "BOUGHT", "p", 4151, "Abyssal whip", price, 1, 1, spent, true, ticks, "acct-a", "s", T0, T0 + 1000, T0 + 1000, null);
  }

  // -------------------------------------------------------------------------------------------- rules

  private static void taxRules() {
    check(Tax.estimateUnitTax(561, 49) == 0, "under 50 gp pays no tax (floor of 2%)");
    check(Tax.estimateUnitTax(561, 50) == 1, "50 gp pays 1");
    check(Tax.estimateUnitTax(561, 99.99) == 1, "the 2% is floored, never rounded");
    check(Tax.estimateUnitTax(22325, 249_999_999) == 4_999_999, "just under the cap: 4,999,999");
    check(Tax.estimateUnitTax(22325, 250_000_000) == 5_000_000, "the cap binds at 250m");
    check(Tax.estimateUnitTax(20997, 2_147_483_648.0) == 5_000_000, "above 2^31 the cap still binds");
    check(Tax.estimateUnitTax(1755, 1_000_000) == 0, "a chisel is tax-exempt");
    check(Tax.estimateUnitTax(13190, 10_000_000) == 0, "an Old school bond is tax-exempt");
    check(Tax.estimateUnitTax(561, Double.NaN) == 0 && Tax.estimateUnitTax(561, -5) == 0, "no price, no tax (never a guess)");
    Offer before = new Offer(0, "SOLD", "x", 561, "Nature rune", 214, 10, 10, 2140, true, null, "acct-a", "s", Tax.TAX_ERA_START_MS - 1, null, null, null);
    check(Tax.saleProceeds(before) == null, "a sale first seen before 30 May 2025 is never reinterpreted");
    Offer mixed = new Offer(0, "SOLD", "x", 561, "Nature rune", 214, 1000, 1000, 214_500, true, null, "acct-a", "s", T0, null, null, null);
    Tax.Proceeds p = Tax.saleProceeds(mixed);
    check(p.net == 210_500 && p.tax == 4_000 && !p.exact, "1,000 sold for 214,500: tax 4 a unit, net 210,500, NOT exact (mixed fill prices)");
    check(Tax.breakEvenSellPrice(561, 205) == 209L, "break-even of 205 is 209: 209 - floor(209/50) = 205, and 208 - 4 = 204 falls short");
    check(Tax.breakEvenSellPrice(1755, 20.5) == 21L, "exempt: break-even is just the cost rounded UP");
  }

  private static void halfUpRounding() {
    // Buy 2 for 5 gp (2.5 each), sell 1 for 3 gp, then say the rest is gone: the sold part is a flip with
    // capital 2.5 and profit 0.5. JS Math.round: 3 and 1. HALF_EVEN / rint would say 2 and 0.
    Offer buy = new Offer(0, "BOUGHT", "b1", 561, "Nature rune", 3, 2, 2, 5, true, 5, "acct-a", "s", T0, T0 + 2000, T0 + 2000, null);
    Offer sell = new Offer(1, "SOLD", "s1", 561, "Nature rune", 3, 1, 1, 3, true, null, "acct-a", "s", T0 + 3000, T0 + 4000, T0 + 4000, null);
    java.util.Map<String, FifoMatcher.Closed> closed = new java.util.HashMap<>();
    closed.put("b1", new FifoMatcher.Closed("used", T0 + 5000));
    FifoMatcher.Result r = FifoMatcher.computeAutoFlips(Arrays.asList(buy, sell), closed);
    check(r.flips.size() == 1, "one partial flip from the closed lot");
    FifoMatcher.AutoFlip f = r.flips.get(0);
    check(f.capital == 3 && f.netProceeds == 3 && f.profit == 1 && Boolean.TRUE.equals(f.partial), "capital 2.5 -> 3, profit 0.5 -> 1 (half-up), got " + f.capital + "/" + f.profit);
    // Fire runes: 2 for 7 (3.5 each), 1 sold for 2: profit -1.5 rounds to -1 (toward +infinity), not -2.
    Offer fb = new Offer(0, "BOUGHT", "b2", 554, "Fire rune", 4, 2, 2, 7, true, 6, "acct-a", "s", T0, T0 + 2000, T0 + 2000, null);
    Offer fs = new Offer(1, "SOLD", "s2", 554, "Fire rune", 2, 1, 1, 2, true, null, "acct-a", "s", T0 + 3000, T0 + 4000, T0 + 4000, null);
    closed.clear();
    closed.put("b2", new FifoMatcher.Closed("sold-untracked", T0 + 5000));
    FifoMatcher.AutoFlip g = FifoMatcher.computeAutoFlips(Arrays.asList(fb, fs), closed).flips.get(0);
    check(g.profit == -1 && g.capital == 4, "profit -1.5 -> -1 and capital 3.5 -> 4 (JS half-up), got " + g.profit + "/" + g.capital);
  }

  private static void probesAreInvisible() {
    check(FifoMatcher.isMarginCheck(probeBuy(1_600_000, 1_500_000, 1)), "1 unit, tick 1, filled BELOW its asking: a probe");
    check(!FifoMatcher.isMarginCheck(probeBuy(1_500_000, 1_500_000, 1)), "filled AT its asked price: a real trade (the reported chestplate lesson)");
    check(!FifoMatcher.isMarginCheck(probeBuy(1_600_000, 1_500_000, 3)), "tick 3 is too slow for a probe");
    check(!FifoMatcher.isMarginCheck(probeBuy(1_600_000, 1_500_000, -1)) && !FifoMatcher.isMarginCheck(
      new Offer(0, "BOUGHT", "p", 4151, "w", 1_600_000, 1, 1, 1_500_000, true, null, "acct-a", "s", T0, T0, T0, null)),
      "no tick reading is never a probe (only positive evidence excludes)");
    FifoMatcher.Result r = FifoMatcher.computeAutoFlips(Arrays.asList(probeBuy(1_600_000, 1_500_000, 1)), new java.util.HashMap<>());
    check(r.openPositions.isEmpty() && r.flips.isEmpty(), "a probe never becomes a position");
    FifoMatcher.Result r2 = FifoMatcher.computeAutoFlips(Arrays.asList(probeBuy(1_500_000, 1_500_000, 1)), new java.util.HashMap<>());
    check(r2.openPositions.size() == 1 && r2.openPositions.get(0).unitCost == 1_500_000, "the at-price buy IS held, at 1,500,000");
  }

  private static void accountsNeverCross() {
    Store s = fresh();
    t = T0;
    Client a = new Client("acct-a", "s-a1"), b = new Client("acct-b", "s-b1");
    send(s, a);
    send(s, b);
    a.place(0, 561, "Nature rune", 205, 100, true);
    b.place(0, 561, "Nature rune", 205, 100, true);
    send(s, a);
    send(s, b);
    a.fill(0, 100, 20_400, 3);
    b.fill(0, 100, 20_500, 3);
    send(s, a);
    send(s, b);
    a.slots[0] = null;
    a.place(1, 561, "Nature rune", 214, 150, false);
    send(s, a);
    a.fill(1, 150, 32_100, -1);
    send(s, a);
    StoreState st = s.state(t);
    check(st.autoFlips.size() == 1 && "acct-a".equals(st.autoFlips.get(0).account) && st.autoFlips.get(0).quantity == 100,
      "acct-a's 150 sold match only acct-a's 100 bought");
    check(st.autoUnmatchedSells.size() == 1 && st.autoUnmatchedSells.get(0).unmatchedQty == 50, "the other 50 stay unmatched even though acct-b holds 100");
    check(st.autoOpenPositions.size() == 1 && "acct-b".equals(st.autoOpenPositions.get(0).account), "acct-b keeps its own position");
    check(s.buyLimitUsage("acct-a", 561, t).used == 100 && s.buyLimitUsage("acct-b", 561, t).used == 100, "limits per account");
    check(s.buyLimitUsage(null, 561, t).used == 0 && s.buyLimitUsage(null, 561, t).windowEndsAt == null, "no account counts NOTHING, never everything");
    CostBasis cb = CostBasis.held(st.autoOpenPositions, st.active, 561, "acct-b");
    check(cb != null && cb.unitCost == 205 && cb.quantity == 100, "acct-b's cost basis is its own 205");
    check(CostBasis.held(st.autoOpenPositions, st.active, 561, "acct-a") == null, "acct-a holds none: no cost basis, not acct-b's");
    check(CostBasis.held(st.autoOpenPositions, st.active, 561, null) == null, "no account: no cost basis (the PORT WARNING)");
    JsonObject evil = a.packet(t + 500);
    evil.addProperty("account", "acct-b");
    try {
      s.ingest(evil, t + 1000);
      throw new AssertionError("a session changing account must be refused");
    } catch (JournalException e) {
      check("Session account changed".equals(e.getMessage()), "message: " + e.getMessage());
    }
  }

  private static void restartMidOffer() {
    Store s = fresh();
    t = T0;
    Client c = new Client("acct-a", "s-a1");
    send(s, c);
    String original = c.place(2, 565, "Blood rune", 400, 1000, true);
    send(s, c);
    c.fill(2, 300, 120_000, 7);
    send(s, c);
    Client c2 = c.restart("s-a2");
    c2.fill(2, 600, 240_000, -1);
    send(s, c2);
    // Partial fill then cancel: the cancel packet carries no tick reading either.
    c2.cancel(2);
    send(s, c2);
    StoreState st = s.state(t);
    check(st.linkedLoginOffers == 1, "the login-time offerId is linked to the original record");
    check(st.autoOpenPositions.size() == 1 && original.equals(st.autoOpenPositions.get(0).buyId) && st.autoOpenPositions.get(0).remaining == 600,
      "ONE position of the 600 filled, under the original offerId, not a separate baseline record");
    Offer kept = null;
    for (Offer o : s.offers()) if (o.offerId.equals(original)) kept = o;
    check(kept != null && kept.ticksToFill == 7 && "CANCELLED_BUY".equals(kept.state) && kept.firstSeen == T0 + 1700,
      "ticksToFill 7 and the first-seen time survive the restart and the cancel's -1");
    // ... and the link survives a bridge restart, rebuilt purely from the journal lines.
    List<JournalRecord> records = new ArrayList<>();
    for (String l : journal) records.add(JournalCodec.decode(ParityJson.parse(l)));
    Store again = Store.replay(records, r -> { });
    check(again.state(t).linkedLoginOffers == 1 && again.state(t).autoOpenPositions.get(0).remaining == 600, "alias rebuilt from the journal");
  }

