package com.evi.live.journal;

import static com.evi.live.journal.ParityJson.check;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Every PUBLIC golden transcript (synthetic, recorded from the real bridge by the project's own
 * recorder) replayed through the Java journal engine, with every journal-owned
 * answer compared with what the bridge said. See {@link TranscriptDriver} for exactly what is compared.
 */
public final class JournalParityTest {
  public static void main(String[] args) throws Exception {
    String index = ParityJson.readText("/parity/transcripts/index.txt");
    check(index != null, "parity/transcripts/index.txt is missing from the test resources");
    List<String> diffs = new ArrayList<>();
    Set<String> locks = new LinkedHashSet<>();
    int fixtures = 0, steps = 0, compared = 0;
    for (String name : index.split("\n")) {
      if (name.isBlank()) continue;
      JsonElement root = ParityJson.read("/parity/transcripts/" + name.trim() + ".json.gz");
      check(root != null, "listed fixture " + name + " is missing");
      JsonObject t = root.getAsJsonObject();
      check("evi-golden-transcript/1".equals(t.get("format").getAsString()), name + ": unexpected format");
      check("public".equals(t.get("tier").getAsString()), name + ": a non-public fixture in the public resources");
      JsonObject boot = t.getAsJsonObject("input").getAsJsonObject("boot");
      check(ParityJson.isNull(boot.get("journal")), name + ": a public fixture must not carry a journal");
      locks.add(t.getAsJsonObject("engineLock").get("combined").getAsString());
      TranscriptDriver d = new TranscriptDriver(name);
      d.boot(null, boot.get("preferences"));
      d.run(t.getAsJsonArray("steps"));
      diffs.addAll(d.diffs);
      fixtures++;
      steps += t.getAsJsonArray("steps").size();
      compared += d.compared;
    }
    if (!diffs.isEmpty()) {
      StringBuilder sb = new StringBuilder(diffs.size() + " parity divergence(s) from the JS bridge:");
      for (String d : diffs.subList(0, Math.min(40, diffs.size()))) sb.append("\n  ").append(d);
      throw new AssertionError(sb.toString());
    }
    // Inert-test guard: the four checks that shipped silently inert all passed a green suite.
    check(fixtures >= 34 && compared >= 280, "too little compared: " + fixtures + " fixtures, " + compared + " comparisons");
    check(locks.size() == 1, "public fixtures were recorded under different engines: " + locks);
    System.out.println("PASS: journal parity with the JS bridge over " + fixtures + " public golden transcripts (" + steps + " steps, "
      + compared + " compared answers: packet ingest and refusals, full /api/state bodies, buy-limit usage, not-held, personal use, profit reset and every reply's profit line, bridge restarts through the Java line codec), engine lock "
      + locks.iterator().next().substring(0, 16));
  }
}

package com.evi.live.journal;

import static com.evi.live.journal.ParityJson.check;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

/**
 * The Java journal engine against what the REAL JS engine answered for generated edge cases
 * (recorded from the real JS engine by the project's own recorder; synthetic, so it
 * ships with the plugin's tests). Every expectation here is a recorded JS answer, not a hand-computed one.
 *
 * <p>Two halves. Function vectors: estimateUnitTax, saleProceeds, breakEvenSellPrice (.5 costs, the 250m
 * cap boundary, above 2^31, exempt ids, junk input), the whole exempt set, isMarginCheck and availableAt,
 * heldCostBasis, validatePacket from raw JSON text, the journal line's string and number formatting, and
 * integer GP arithmetic (+, -, x, Math.round) past 2^53 and past 2^63.
 * Scenarios: op sequences against a real Store (rounding ties, totals past 2^31, two accounts, a restart
 * mid-offer, partial fill then cancel, relist, probes, personal use, recorded purchases, manual review,
 * imports, closing positions, ingest refusals, the buy-limit window, fill ordering, the exact boundaries of
 * liveness / continuation / closing / personal-use cover, and GP totals past 2^53), each answer compared,
 * and the journal the Java store wrote compared with the JS journal LINE BY LINE, byte for byte.
 */
public final class JournalVectorsTest {
  private static final List<String> diffs = new ArrayList<>();
  private static int compared;
  private static int knownNoAccountDivergences;
  private static int knownBeyondLong;

  public static void main(String[] args) throws Exception {
    JsonElement root = ParityJson.read("/parity/journal-vectors.json.gz");
    check(root != null, "parity/journal-vectors.json.gz is missing from the test resources");
    JsonObject v = root.getAsJsonObject();
    check("evi-journal-vectors/1".equals(v.get("format").getAsString()), "unexpected vectors format");
    constants(v.getAsJsonObject("constants"));
    int functions = 0;
    for (JsonElement e : v.getAsJsonArray("functions")) {
      function(e.getAsJsonObject());
      functions++;
    }
    int ops = 0, lines = 0;
    for (JsonElement e : v.getAsJsonArray("scenarios")) {
      JsonObject s = e.getAsJsonObject();
      ops += s.getAsJsonArray("ops").size();
      lines += s.getAsJsonArray("journal").size();
      scenario(s);
    }
    if (!diffs.isEmpty()) {
      StringBuilder sb = new StringBuilder(diffs.size() + " journal-vector divergence(s) from the JS engine:");
      for (String d : diffs.subList(0, Math.min(40, diffs.size()))) sb.append("\n  ").append(d);
      throw new AssertionError(sb.toString());
    }
    // Inert-test guard: a vectors file that silently stopped being read would pass with nothing compared.
    check(functions >= 400 && ops >= 300 && lines >= 190 && compared >= 900,
      "too little was compared (" + functions + " functions, " + ops + " ops, " + lines + " lines, " + compared + " comparisons)");
    check(knownNoAccountDivergences > 0, "the no-account heldCostBasis vectors no longer exercise the JS predicate");
    check(knownBeyondLong >= 50, "too few arithmetic vectors reach past 2^63 (" + knownBeyondLong + "): the refusal is no longer exercised");
    System.out.println("PASS: journal vectors vs the JS engine (engine " + v.getAsJsonObject("engineLock").get("combined").getAsString().substring(0, 16)
      + "): " + functions + " function vectors, " + v.getAsJsonArray("scenarios").size() + " Store scenarios, " + ops + " ops, "
      + lines + " journal lines byte-identical, " + compared + " comparisons; heldCostBasis scoped by design where JS sums every account ("
      + knownNoAccountDivergences + " no-account calls)");
  }

  private static void same(String where, JsonElement exp, JsonElement act) {
    compared++;
    for (String d : ParityJson.diff(exp, act)) diffs.add(where + ": " + d);
  }

  private static void constants(JsonObject c) {
    same("constants.taxCap", c.get("taxCap"), new JsonPrimitive(Tax.CAP));
    same("constants.taxEraStart", c.get("taxEraStart"), new JsonPrimitive(Tax.TAX_ERA_START_MS));
    same("constants.marginCheckTicks", c.get("marginCheckTicks"), new JsonPrimitive(FifoMatcher.MARGIN_CHECK_TICKS));
    same("constants.gameTickMs", c.get("gameTickMs"), new JsonPrimitive(FifoMatcher.GAME_TICK_MS));
    same("constants.limitWindowMs", c.get("limitWindowMs"), new JsonPrimitive(BuyLimitUsage.WINDOW_MS));
    same("constants.packetIntMax", c.get("packetIntMax"), new JsonPrimitive((long) Js.INT32_MAX));
  }

  // An Offer from a partial JS object: absent numbers are 0 (JS would compare undefined, which every
  // recorded vector avoids for the fields it reads), absent longs that may be absent stay null.
  static Offer offer(JsonObject o) {
    o = ParityJson.stripUndefined(o);
    Double ticks = Js.number(o.get("ticksToFill"));
    return new Offer(i(o, "slot"), Js.string(o.get("state")), Js.string(o.get("offerId")), i(o, "itemId"), Js.string(o.get("name")),
      l(o, "price"), l(o, "total"), l(o, "filled"), l(o, "spent"), o.has("knownStart") && o.get("knownStart").getAsBoolean(),
      ticks != null && Js.isInteger(ticks) ? Integer.valueOf((int) (double) ticks) : null, Js.string(o.get("account")),
      Js.string(o.get("session")), ln(o, "firstSeen"), ln(o, "updated"), ln(o, "completedAt"), null);
  }

  private static int i(JsonObject o, String k) {
    Double d = Js.number(o.get(k));
    return d == null ? 0 : (int) (double) d;
  }

  private static long l(JsonObject o, String k) {
    Double d = Js.number(o.get(k));
    return d == null ? 0 : (long) (double) d;
  }

  private static Long ln(JsonObject o, String k) {
    Double d = Js.number(o.get(k));
    return d == null ? null : (long) (double) d;
  }

  private static JsonElement num(Number n) {
    if (n == null) return JsonNull.INSTANCE;
    if (n instanceof Double && (((Double) n).isNaN() || ((Double) n).isInfinite())) return JsonNull.INSTANCE;
    return new JsonPrimitive(n);
  }

  private static void function(JsonObject f) {
    String fn = f.get("fn").getAsString();
    JsonArray a = f.has("args") ? f.getAsJsonArray("args") : null;
    String where = fn + " " + (a != null ? a : f.get("text").getAsString());
    if (where.length() > 160) where = where.substring(0, 160) + "...";
    switch (fn) {
      case "estimateUnitTax":
        same(where, f.get("result"), new JsonPrimitive(Tax.estimateUnitTax(a.get(0).getAsInt(), ParityJson.tagNumber(a.get(1)))));
        break;
      case "saleProceeds":
        same(where, f.get("result"), ParityJson.proceeds(Tax.saleProceeds(offer(a.get(0).getAsJsonObject()))));
        break;
      case "breakEvenSellPrice":
        same(where, f.get("result"), num(Tax.breakEvenSellPrice(a.get(0).getAsInt(), ParityJson.tagNumber(a.get(1)))));
        break;
      case "isMarginCheck":
        same(where, f.get("result"), new JsonPrimitive(FifoMatcher.isMarginCheck(offer(a.get(0).getAsJsonObject()))));
        break;
      case "availableAt":
        same(where, f.get("result"), num(FifoMatcher.availableAt(offer(a.get(0).getAsJsonObject()))));
        break;
      case "heldCostBasis": {
        List<FifoMatcher.OpenPosition> positions = new ArrayList<>();
        for (JsonElement p : a.get(0).getAsJsonArray()) {
          JsonObject o = p.getAsJsonObject();
          positions.add(new FifoMatcher.OpenPosition(Js.string(o.get("account")), i(o, "itemId"), null, null, l(o, "remaining"),
            l(o, "remaining"), null, Js.number(o.get("unitCost")), false));
        }
        List<Offer> active = new ArrayList<>();
        for (JsonElement o : a.get(1).getAsJsonArray()) active.add(offer(o.getAsJsonObject()));
        boolean noAccount = ParityJson.isUndefined(a.get(3)) || a.get(3).isJsonNull();
        CostBasis got = CostBasis.held(positions, active, a.get(2).getAsInt(), noAccount ? null : a.get(3).getAsString());
        if (noAccount) {
          // BY DESIGN (the PORT WARNING): no account, no answer. JS sums every account here.
          compared++;
          if (got != null) diffs.add(where + ": Java must answer null without an account, got " + got.unitCost);
          if (!ParityJson.isNull(f.get("result"))) knownNoAccountDivergences++;
          break;
        }
        JsonObject j = null;
        if (got != null) {
          j = new JsonObject();
          j.addProperty("unitCost", got.unitCost);
          j.addProperty("quantity", got.quantity);
        }
        same(where, f.get("result"), j);
        break;
      }
      case "validatePacket": {
        JsonElement got;
        try {
          got = packetJson(Packet.validate(ParityJson.parse(f.get("text").getAsString())));
        } catch (JournalException e) {
          JsonObject err = new JsonObject();
          err.addProperty("error", e.getMessage());
          got = err;
        }
        JsonElement exp = f.has("error") ? errorJson(f.get("error").getAsString()) : f.get("result");
        same(where, exp, got);
        break;
      }
      case "jsonString":
        compared++;
        if (!Js.quote(a.get(0).getAsString()).equals(f.get("result").getAsString()))
          diffs.add(where + ": JSON.stringify gave " + f.get("result").getAsString() + " but Java wrote " + Js.quote(a.get(0).getAsString()));
        break;
      case "numberToString": {
        compared++;
        String got = Js.numberToString(ParityJson.tagNumber(a.get(0)));
        if (!got.equals(f.get("result").getAsString())) diffs.add(where + ": String(x) is " + f.get("result").getAsString() + " but Java wrote " + got);
        break;
      }
      case "jsAdd":
      case "jsSubtract":
      case "jsMultiply":
      case "jsRound": {
        // JS's double answer, which Java must hold EXACTLY as a long -- or, when that double is NaN or
        // at/past 2^63, refuse with an ArithmeticException (never wrap, never saturate).
        compared++;
        double js = ParityJson.tagNumber(f.get("result"));
        boolean longCanHold = !Double.isNaN(js) && js < 0x1p63 && js >= -0x1p63;
        Long got;
        try {
          long x = (long) ParityJson.tagNumber(a.get(0));
          got = "jsRound".equals(fn) ? Js.round(ParityJson.tagNumber(a.get(0)))
            : "jsAdd".equals(fn) ? Js.add(x, (long) ParityJson.tagNumber(a.get(1)))
            : "jsSubtract".equals(fn) ? Js.subtract(x, (long) ParityJson.tagNumber(a.get(1)))
            : Js.multiply(x, (long) ParityJson.tagNumber(a.get(1)));
        } catch (ArithmeticException e) {
          got = null;
        }
        if (!longCanHold && got != null) diffs.add(where + ": JS gives " + Js.numberToString(js) + ", past a long, but Java returned " + got + " instead of refusing");
        if (longCanHold && (got == null || new BigDecimal(js).compareTo(BigDecimal.valueOf(got)) != 0))
          diffs.add(where + ": JS gives " + new BigDecimal(js).toPlainString() + " but Java " + (got == null ? "threw" : "gave " + got));
        if (!longCanHold) knownBeyondLong++;
        break;
      }
      case "exemptIds": {
        JsonArray ids = new JsonArray();
        for (int id = a.get(0).getAsInt(); id < a.get(1).getAsInt(); id++) if (Tax.estimateUnitTax(id, 1000000) == 0) ids.add(id);
        same(where, f.get("result"), ids);
        break;
      }
      default:
        diffs.add("unknown vector function " + fn);
    }
  }

  private static JsonObject errorJson(String message) {
    JsonObject o = new JsonObject();
    o.addProperty("error", message);
    return o;
  }

  static JsonObject packetJson(Packet p) {
    JsonObject j = new JsonObject();
    j.addProperty("version", p.version);
    j.addProperty("session", p.session);
    j.addProperty("account", p.account);
    j.addProperty("seq", p.seq);
    j.addProperty("ts", p.ts);
    j.addProperty("loggedIn", p.loggedIn);
    JsonArray offers = new JsonArray();
    for (Packet.SlotOffer o : p.offers) {
      JsonObject x = new JsonObject();
      x.addProperty("slot", o.slot);
      x.addProperty("state", o.state);
      x.addProperty("offerId", o.offerId);
      x.addProperty("itemId", o.itemId);
      x.addProperty("name", o.name);
      x.addProperty("price", o.price);
      x.addProperty("total", o.total);
      x.addProperty("filled", o.filled);
      x.addProperty("spent", o.spent);
      x.addProperty("knownStart", o.knownStart);
      ParityJson.put(x, "ticksToFill", o.ticksToFill);
      offers.add(x);
    }
    j.add("offers", offers);
    return j;
  }

  private static JsonObject ok() {
    JsonObject o = new JsonObject();
    o.addProperty("ok", true);
    return o;
  }

  private static void scenario(JsonObject s) {
    String name = s.get("name").getAsString();
    List<String> lines = new ArrayList<>();
    Store.Journal sink = r -> lines.add(JournalCodec.encodeLine(r));
    Store store = new Store(sink);
    int n = 0;
    for (JsonElement oe : s.getAsJsonArray("ops")) {
      JsonObject op = oe.getAsJsonObject();
      String kind = op.get("op").getAsString();
      long at = op.get("at").getAsLong();
      String where = name + " op " + (n++) + " " + kind;
      if ("restart".equals(kind)) {
        List<JournalRecord> records = new ArrayList<>();
        for (String l : lines) records.add(JournalCodec.decode(ParityJson.parse(l)));
        store = Store.replay(records, sink);
        continue;
      }
      if ("appendJournal".equals(kind)) {
        // A raw line written behind the store's back (the recorder appends it to the JS file the same way):
        // nothing reads it until the next restart replays the journal, and replay never validates a line.
        lines.add(op.get("args").getAsString());
        continue;
      }
      JsonElement args = op.get("args");
      JsonElement got;
      try {
        got = run(store, kind, args, at, op);
      } catch (JournalException e) {
        got = errorJson(e.getMessage());
      }
      JsonElement exp = op.has("error") ? errorJson(op.get("error").getAsString()) : op.get("result");
      same(where, exp, got);
      if ("state".equals(kind) && exp.isJsonObject()) {
        compared++;
        if (!ParityJson.keyOrder(exp.getAsJsonObject().getAsJsonObject("personalUseKept"))
          .equals(ParityJson.keyOrder(got.getAsJsonObject().getAsJsonObject("personalUseKept"))))
          diffs.add(where + ": personalUseKept key order differs");
      }
    }
    JsonArray js = s.getAsJsonArray("journal");
    compared++;
    if (js.size() != lines.size()) diffs.add(name + ": JS journalled " + js.size() + " lines, Java " + lines.size());
    for (int k = 0; k < Math.min(js.size(), lines.size()); k++) {
      compared++;
      if (!js.get(k).getAsString().equals(lines.get(k)))
        diffs.add(name + " journal line " + k + ":\n    JS   " + js.get(k).getAsString() + "\n    Java " + lines.get(k));
    }
  }

  private static JsonElement run(Store store, String kind, JsonElement args, long at, JsonObject op) {
    switch (kind) {
      case "ingest": {
        JsonObject o = new JsonObject();
        o.addProperty("duplicate", store.ingest(args, at));
        return o;
      }
      case "state":
        return ParityJson.state(store.state(at));
      case "buyLimitUsage": {
        JsonArray a = args.getAsJsonArray();
        BuyLimitUsage u = store.buyLimitUsage(a.get(0).isJsonNull() ? null : a.get(0).getAsString(), a.get(1).getAsInt(), at);
        JsonObject o = new JsonObject();
        o.addProperty("used", u.used);
        ParityJson.put(o, "windowEndsAt", u.windowEndsAt);
        return o;
      }
      case "closePosition":
        store.closePosition(args.getAsJsonObject(), at);
        return ok();
      case "markPersonalUse":
        store.markPersonalUse(args.getAsJsonObject());
        return ok();
      case "markPersonalUseItem": {
        Store.PersonalUseItemReply r = store.markPersonalUseItem(args.getAsJsonObject());
        JsonObject o = ok();
        o.addProperty("itemId", r.itemId);
        o.addProperty("personal", r.personal);
        ParityJson.put(o, "kept", r.kept);
        return o;
      }
      case "recordPurchase": {
        Store.RecordResult r = store.recordPurchase(args.getAsJsonObject(), at);
        JsonObject o = new JsonObject();
        ParityJson.put(o, "removed", r.removed);
        ParityJson.put(o, "recorded", r.recorded);
        ParityJson.put(o, "offerId", r.offerId);
        ParityJson.put(o, "duplicate", r.duplicate);
        ParityJson.put(o, "cost", r.cost);
        return o;
      }
      case "confirm": {
        String id = op.has("result") && op.get("result").isJsonObject() ? op.getAsJsonObject("result").get("id").getAsString() : "never-used";
        return ParityJson.manualFlip(store.confirm(args.getAsJsonObject(), at, () -> id));
      }
      case "setRemoved":
        store.setRemoved(args.getAsJsonObject());
        return ok();
      case "reopen":
        store.reopen(args.getAsJsonObject());
        return ok();
      case "importFlips": {
        Store.ImportResult r = store.importFlips(args.getAsJsonObject());
        JsonObject o = new JsonObject();
        ParityJson.put(o, "removed", r.removed);
        ParityJson.put(o, "accepted", r.accepted);
        ParityJson.put(o, "duplicates", r.duplicates);
        o.addProperty("total", r.total);
        return o;
      }
      default:
        throw new IllegalArgumentException("unknown op " + kind);
    }
  }
}

package com.evi.live.journal;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeSet;
import java.util.zip.GZIPInputStream;

/**
 * Test-side helpers for the journal parity tests: loading fixtures from the CLASSPATH only (no file API), the comparator,
 * and the Java state as the JSON the bridge would have sent.
 *
 * <p>COMPARATOR RULES (the parity design's comparator section): absent and null are equal (JSON.stringify
 * drops undefined), numbers compare by value (5 and 5.0 are equal; -0 equals 0), strings compare EXACTLY,
 * arrays in order, objects over the union of their keys. Every difference is reported with its JSON path.
 */
final class ParityJson {
  private ParityJson() {}

  static void check(boolean ok, String message) {
    if (!ok) throw new AssertionError(message);
  }

  /** A classpath resource, gunzipped when its name ends in .gz; null when absent. */
  static InputStream open(String resource) throws IOException {
    InputStream in = ParityJson.class.getResourceAsStream(resource);
    if (in == null) return null;
    return resource.endsWith(".gz") ? new GZIPInputStream(in) : in;
  }

  static JsonElement read(String resource) throws IOException {
    try (InputStream in = open(resource)) {
      if (in == null) return null;
      try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
        return new JsonParser().parse(r);
      }
    }
  }

  /** One JSON text, parsed. (This Gson predates the static JsonParser.parseString.) */
  static JsonElement parse(String text) {
    return new JsonParser().parse(text);
  }

  static String readText(String resource) throws IOException {
    try (InputStream in = open(resource)) {
      if (in == null) return null;
      return new String(in.readAllBytes(), StandardCharsets.UTF_8);
    }
  }

  // ------------------------------------------------------------------------------------------- compare

  static boolean isNull(JsonElement e) {
    return e == null || e.isJsonNull();
  }

  static void diff(JsonElement exp, JsonElement act, String path, List<String> out) {
    if (out.size() > 200) return;
    if (isNull(exp) || isNull(act)) {
      if (isNull(exp) != isNull(act)) out.add(path + ": expected " + exp + " but was " + act);
      return;
    }
    if (exp.isJsonObject() && act.isJsonObject()) {
      TreeSet<String> keys = new TreeSet<>(exp.getAsJsonObject().keySet());
      keys.addAll(act.getAsJsonObject().keySet());
      for (String k : keys) diff(exp.getAsJsonObject().get(k), act.getAsJsonObject().get(k), path + "." + k, out);
      return;
    }
    if (exp.isJsonArray() && act.isJsonArray()) {
      JsonArray a = exp.getAsJsonArray(), b = act.getAsJsonArray();
      if (a.size() != b.size()) out.add(path + ": expected " + a.size() + " elements but was " + b.size());
      for (int i = 0; i < Math.min(a.size(), b.size()); i++) diff(a.get(i), b.get(i), path + "[" + i + "]", out);
      return;
    }
    if (exp.isJsonPrimitive() && act.isJsonPrimitive()) {
      JsonPrimitive x = exp.getAsJsonPrimitive(), y = act.getAsJsonPrimitive();
      if (x.isNumber() && y.isNumber()) {
        Number raw = y.getAsNumber();
        if (raw instanceof Long || raw instanceof Integer) {
          // A Java INTEGER against JS's double: EXACT. Comparing (double) of the long would hide a
          // difference past 2^53, where a long holds values a double cannot (the 6 Oct finding: an
          // imported total off by 2 passed this check while it converted both sides to double).
          double js = Js.number(x);
          if (!Js.isInteger(js) || new BigDecimal(js).compareTo(BigDecimal.valueOf(raw.longValue())) != 0)
            out.add(path + ": expected " + x + " but was " + y + " (exact integer comparison)");
          return;
        }
        if (Js.number(x).doubleValue() != Js.number(y).doubleValue()) out.add(path + ": expected " + x + " but was " + y);
        return;
      }
      if (x.isString() && y.isString()) {
        if (!x.getAsString().equals(y.getAsString())) out.add(path + ": expected " + x + " but was " + y);
        return;
      }
      if (x.isBoolean() && y.isBoolean()) {
        if (x.getAsBoolean() != y.getAsBoolean()) out.add(path + ": expected " + x + " but was " + y);
        return;
      }
    }
    out.add(path + ": expected " + exp + " but was " + act + " (different JSON types)");
  }

  static List<String> diff(JsonElement exp, JsonElement act) {
    List<String> out = new ArrayList<>();
    diff(exp, act, "$", out);
    return out;
  }

  // ------------------------------------------------------------------------------- tagged JSON values

  /** The recorder's tags: {"$num":"NaN"|"Infinity"|"-Infinity"|"-0"} and {"$u":1} for undefined. */
  static double tagNumber(JsonElement e) {
    if (e != null && e.isJsonObject() && e.getAsJsonObject().has("$num")) {
      String s = e.getAsJsonObject().get("$num").getAsString();
      switch (s) {
        case "NaN": return Double.NaN;
        case "Infinity": return Double.POSITIVE_INFINITY;
        case "-Infinity": return Double.NEGATIVE_INFINITY;
        case "-0": return -0.0;
        default: throw new IllegalArgumentException(s);
      }
    }
    if (e == null || e.isJsonNull() || isUndefined(e)) return Double.NaN;
    return Js.number(e);
  }

  static boolean isUndefined(JsonElement e) {
    return e == null || (e.isJsonObject() && e.getAsJsonObject().has("$u"));
  }

  /** An object with every {"$u":1} member removed (undefined is simply absent in JS). */
  static JsonObject stripUndefined(JsonObject o) {
    JsonObject out = new JsonObject();
    for (Map.Entry<String, JsonElement> e : o.entrySet()) if (!isUndefined(e.getValue())) out.add(e.getKey(), e.getValue());
    return out;
  }

  // ------------------------------------------------------------------------- Java values as bridge JSON

  static void put(JsonObject o, String k, Number v) {
    if (v == null) return;
    if (v instanceof Double && (((Double) v).isNaN() || ((Double) v).isInfinite())) return; // JSON.stringify: null
    o.addProperty(k, v);
  }

  static void put(JsonObject o, String k, String v) {
    if (v != null) o.addProperty(k, v);
  }

  static void put(JsonObject o, String k, Boolean v) {
    if (v != null) o.addProperty(k, v);
  }

  static JsonArray strings(List<String> list) {
    JsonArray a = new JsonArray();
    for (String s : list) {
      if (s == null) a.add(JsonNull.INSTANCE);
      else a.add(s);
    }
    return a;
  }

  static JsonArray ints(List<Integer> list) {
    JsonArray a = new JsonArray();
    for (Integer s : list) a.add(s);
    return a;
  }

  static JsonObject offer(Offer o) {
    JsonObject j = new JsonObject();
    put(j, "slot", o.slot);
    put(j, "state", o.state);
    put(j, "offerId", o.offerId);
    put(j, "itemId", o.itemId);
    put(j, "name", o.name);
    put(j, "price", o.price);
    put(j, "total", o.total);
    put(j, "filled", o.filled);
    put(j, "spent", o.spent);
    put(j, "knownStart", o.knownStart);
    put(j, "ticksToFill", o.ticksToFill);
    put(j, "account", o.account);
    put(j, "session", o.session);
    put(j, "firstSeen", o.firstSeen);
    put(j, "updated", o.updated);
    put(j, "completedAt", o.completedAt);
    put(j, "recorded", o.recorded);
    return j;
  }

  static JsonObject proceeds(Tax.Proceeds p) {
    if (p == null) return null;
    JsonObject j = new JsonObject();
    put(j, "net", p.net);
    put(j, "tax", p.tax);
    put(j, "exact", p.exact);
    return j;
  }

  static JsonObject manualFlip(ManualFlip f) {
    JsonObject j = new JsonObject();
    put(j, "id", f.id);
    put(j, "buyId", f.buyId);
    put(j, "sellId", f.sellId);
    if (f.sellIds != null) j.add("sellIds", strings(f.sellIds));
    put(j, "account", f.account);
    put(j, "itemId", f.itemId);
    put(j, "item", f.item);
    put(j, "quantity", f.quantity);
    put(j, "capital", f.capital);
    put(j, "netProceeds", f.netProceeds);
    put(j, "profit", f.profit);
    put(j, "firstBuy", f.firstBuy);
    put(j, "lastSell", f.lastSell);
    put(j, "hold", f.hold);
    put(j, "confirmedAt", f.confirmedAt);
    put(j, "source", f.source);
    put(j, "proceedsMethod", f.proceedsMethod);
    put(j, "removed", f.removed());
    put(j, "reopened", f.reopened());
    return j;
  }

  static JsonObject autoFlip(FifoMatcher.AutoFlip f) {
    JsonObject j = new JsonObject();
    put(j, "id", f.id);
    put(j, "account", f.account);
    put(j, "itemId", f.itemId);
    put(j, "item", f.item);
    put(j, "quantity", f.quantity);
    put(j, "capital", f.capital);
    put(j, "netProceeds", f.netProceeds);
    put(j, "profit", f.profit);
    put(j, "firstBuy", f.firstBuy);
    put(j, "lastSell", f.lastSell);
    put(j, "hold", f.hold);
    put(j, "buyId", f.buyId);
    j.add("sellIds", strings(f.sellIds));
    put(j, "exact", f.exact);
    put(j, "source", f.source);
    put(j, "partial", f.partial);
    put(j, "closedReason", f.closedReason);
    return j;
  }

  static JsonObject openPosition(FifoMatcher.OpenPosition p) {
    JsonObject j = new JsonObject();
    put(j, "account", p.account);
    put(j, "itemId", p.itemId);
    put(j, "item", p.item);
    put(j, "buyId", p.buyId);
    put(j, "remaining", p.remaining);
    put(j, "totalQty", p.totalQty);
    put(j, "firstSeen", p.firstSeen);
    put(j, "unitCost", p.unitCost);
    put(j, "partiallySold", p.partiallySold);
    if (p.endedUnseen != null) {
      JsonObject u = new JsonObject();
      put(u, "sellId", p.endedUnseen.sellId);
      put(u, "price", p.endedUnseen.price);
      put(u, "at", p.endedUnseen.at);
      put(u, "quantity", p.endedUnseen.quantity);
      j.add("endedUnseen", u);
    }
    return j;
  }

  static JsonObject importedFlip(ImportedFlip f) {
    JsonObject j = new JsonObject();
    put(j, "fp", f.fp);
    put(j, "source", f.source);
    put(j, "itemId", f.itemId);
    put(j, "item", f.item);
    put(j, "quantity", f.quantity);
    put(j, "capital", f.capital);
    put(j, "netProceeds", f.netProceeds);
    put(j, "profit", f.profit);
    put(j, "firstBuy", f.firstBuy);
    put(j, "lastSell", f.lastSell);
    put(j, "hold", f.hold);
    put(j, "account", f.account);
    j.addProperty("imported", true);
    return j;
  }

  static JsonObject dataHealth(FifoMatcher.DataHealth h) {
    JsonObject j = new JsonObject();
    put(j, "openPositions", h.openPositions);
    put(j, "openCost", h.openCost);
    j.add("openItemIds", ints(h.openItemIds));
    put(j, "unmatchedSales", h.unmatchedSales);
    put(j, "unmatchedGross", h.unmatchedGross);
    put(j, "personalUseSales", h.personalUseSales);
    put(j, "personalUseGross", h.personalUseGross);
    return j;
  }

  static JsonObject state(StoreState s) {
    JsonObject j = new JsonObject();
    put(j, "version", s.version);
    put(j, "serverTime", s.serverTime);
    JsonArray sessions = new JsonArray();
    for (StoreState.SessionView v : s.sessions) {
      JsonObject o = new JsonObject();
      put(o, "id", v.id);
      put(o, "account", v.account);
      put(o, "seq", v.seq);
      put(o, "lastSeen", v.lastSeen);
      put(o, "loggedIn", v.loggedIn);
      o.add("slots", strings(v.slots));
      put(o, "capturedAt", v.capturedAt);
      put(o, "live", v.live);
      sessions.add(o);
    }
    j.add("sessions", sessions);
    JsonArray active = new JsonArray(), occupied = new JsonArray(), completed = new JsonArray();
    for (Offer o : s.active) active.add(offer(o));
    for (Offer o : s.occupied) occupied.add(offer(o));
    for (StoreState.CompletedOffer c : s.completed) {
      JsonObject o = offer(c.offer);
      JsonObject p = proceeds(c.proceeds);
      if (p != null) o.add("proceeds", p);
      o.addProperty("marginCheck", c.marginCheck);
      completed.add(o);
    }
    j.add("active", active);
    j.add("occupied", occupied);
    j.add("completed", completed);
    JsonArray flips = new JsonArray(), removed = new JsonArray(), auto = new JsonArray(), open = new JsonArray(), unmatched = new JsonArray();
    for (ManualFlip f : s.flips) flips.add(manualFlip(f));
    for (ManualFlip f : s.removedFlips) removed.add(manualFlip(f));
    for (FifoMatcher.AutoFlip f : s.autoFlips) auto.add(autoFlip(f));
    for (FifoMatcher.OpenPosition p : s.autoOpenPositions) open.add(openPosition(p));
    for (FifoMatcher.UnmatchedSell u : s.autoUnmatchedSells) {
      JsonObject o = offer(u.offer);
      put(o, "unmatchedQty", u.unmatchedQty);
      put(o, "reason", u.reason);
      unmatched.add(o);
    }
    j.add("flips", flips);
    j.add("removedFlips", removed);
    j.add("autoFlips", auto);
    j.add("autoOpenPositions", open);
    j.add("autoUnmatchedSells", unmatched);
    j.add("dataHealth", dataHealth(s.dataHealth));
    j.add("personalUseBuyIds", strings(s.personalUseBuyIds));
    j.add("personalUseItemIds", ints(s.personalUseItemIds));
    j.add("personalUseItems", ints(s.personalUseItems));
    JsonObject kept = new JsonObject();
    for (Map.Entry<Integer, Long> e : s.personalUseKept.entrySet()) kept.addProperty(String.valueOf(e.getKey()), e.getValue());
    j.add("personalUseKept", kept);
    JsonArray imported = new JsonArray();
    for (ImportedFlip f : s.importedFlips) imported.add(importedFlip(f));
    j.add("importedFlips", imported);
    if (s.importedSummary != null) {
      JsonObject o = new JsonObject();
      put(o, "count", s.importedSummary.count);
      put(o, "items", s.importedSummary.items);
      put(o, "profit", s.importedSummary.profit);
      put(o, "from", s.importedSummary.from);
      put(o, "to", s.importedSummary.to);
      o.add("sources", strings(s.importedSummary.sources));
      j.add("importedSummary", o);
    }
    JsonArray closed = new JsonArray();
    for (StoreState.ClosedPosition c : s.closedPositions) {
      JsonObject o = new JsonObject();
      put(o, "buyId", c.buyId);
      put(o, "reason", c.reason);
      put(o, "at", c.at);
      put(o, "item", c.item);
      put(o, "itemId", c.itemId);
      put(o, "account", c.account);
      closed.add(o);
    }
    j.add("closedPositions", closed);
    put(j, "linkedLoginOffers", s.linkedLoginOffers);
    JsonArray unseen = new JsonArray();
    for (StoreState.EndedUnseenOffer u : s.endedUnseen) {
      JsonObject o = new JsonObject();
      put(o, "offerId", u.offerId);
      put(o, "at", u.at);
      unseen.add(o);
    }
    j.add("endedUnseen", unseen);
    put(j, "netProfit", s.netProfit);
    put(j, "tradeCount", s.tradeCount);
    return j;
  }

  /** Key ORDER of personalUseKept matters in JS output (integer keys ascend); value comparison ignores order, so check it separately. */
  static List<String> keyOrder(JsonObject o) {
    return new ArrayList<>(o.keySet());
  }

  static JsonObject profit(Profit p) {
    JsonObject j = new JsonObject();
    put(j, "since", p.since);
    put(j, "gp", p.gp);
    put(j, "trades", p.trades);
    put(j, "winners", p.winners);
    put(j, "losers", p.losers);
    put(j, "unmatchedSales", p.unmatchedSales);
    put(j, "openPositions", p.openPositions);
    return j;
  }
}

package com.evi.live.journal;

import com.evi.live.TestFiles;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
