/**
 * The voluntary trade-log export (9 Oct 2026): {@link TradeLogExport}'s CSV, and {@link PluginJournal#exportTradeLog} writing
 * it from every account's journal. Every check asserts a VALUE -- a byte, a line, a field, a count. SYNTHETIC data only: the
 * offers below and PluginJournalTest's synthetic clients. The point the file must never miss: no account id, no character name,
 * no session and no offer id appear anywhere in it.
 */
public final class TradeLogExportTest {
  static int checks;
  static final String ACCOUNT = "f00d".repeat(16);
  static final String CHARACTER = "Synthetic Trader";
  static final long T = 1789992000000L; // 2026-09-21T12:00:00Z

  static void check(boolean ok, String message) {
    if (!ok) throw new AssertionError(message);
    checks++;
  }

  public static void main(String[] args) throws Exception {
    headerAndShape();
    rowsAndQuoting();
    nothingIdentifying();
    journalWritesEveryAccount();
    System.out.println("PASS: trade-log export (" + checks + " checks): BOM, sep=, line, the header, RFC 4180 quoting, an offer row, a"
      + " cancelled offer, an ended-unseen offer, a recorded purchase left out, a reviewed flip at a loss with its refs, EVI's suggested price and link type (observed / matched / inferred from the plugin's own join, empty when unlinked, a linker failure costing only the links), ISO UTC times"
      + " to the millisecond, rows sorted by time not account, no account id / character name / session / offer id anywhere; and the"
      + " journal writing every account's offers and flips to share/, replacing the same day's file, off no thread but its own");
  }

  static Offer offer(String id, String state, int itemId, String name, long price, long total, long filled, Long firstSeen, Long updated,
                     Long completedAt, Integer ticks, boolean knownStart, Boolean recorded) {
    return new Offer(3, state, id, itemId, name, price, total, filled, price * filled, knownStart, ticks, ACCOUNT, "session-x", firstSeen,
      updated, completedAt, recorded);
  }

  static List<Offer> sample() {
    return Arrays.asList(
      // listed out of time order on purpose: the file sorts by first seen
      offer("o-sell", "CANCELLED_SELL", 1515, "Yew logs", 320, 500, 120, T + 60_000, T + 90_000, T + 90_000, null, true, null),
      offer("o-buy", "BOUGHT", 4151, "Abyssal whip", 1_500_000, 2, 2, T, T + 30_123, T + 30_123, 40, true, null),
      offer("o-odd", "BUYING", 12345, "Odd, \"quoted\" item", 7, 100, 0, T + 120_000, T + 120_000, null, null, false, null),
      offer("o-told", "BOUGHT", 4151, "Abyssal whip", 1_400_000, 1, 1, T - 5_000, T - 5_000, T - 5_000, null, true, Boolean.TRUE),
      offer("o-sold", "SOLD", 4151, "Abyssal whip", 1_450_000, 2, 2, T + 40_000, T + 50_000, T + 50_000, 12, true, null));
  }

  /** A suggestion-log line as SuggestionRecords writes it, plus fields the file must never carry (an account and a minimum profit). */
  static com.google.gson.JsonObject suggestion(String id, long ts, int itemId, String action, long buy, long sell, long quantity) {
    com.google.gson.JsonObject e = new com.google.gson.JsonObject();
    e.addProperty("id", id);
    e.addProperty("ts", ts);
    e.addProperty("account", "acct-secret");
    e.addProperty("itemId", itemId);
    e.addProperty("action", action);
    e.addProperty("quantity", quantity);
    e.addProperty("buyPrice", buy);
    e.addProperty("sellPrice", sell);
    e.addProperty("minProfit", 424242);
    return e;
  }

  static List<TradeLogExport.Flip> sampleFlips() {
    ManualFlip loss = new ManualFlip("m1", "o-buy", null, Arrays.asList("o-sold", "o-gone"), ACCOUNT, 4151, "Abyssal whip", 2, 3_000_000,
      2_842_000, -158_000, T, T + 50_000, 0.01, T + 60_000, "manual", "exact");
    return new ArrayList<>(Arrays.asList(TradeLogExport.Flip.of(loss)));
  }

  static TradeLogExport.Csv sampleCsv() {
    // EVI's suggested price beside two offers: the buy linked as OBSERVED at a price that differs from the offer's own, the sale
    // MATCHED at its own price; the cancelled sell and the odd buy have no link
    java.util.Map<String, TradeLogExport.Link> links = new java.util.HashMap<>();
    links.put("o-buy", new TradeLogExport.Link("observed", 1_490_000L));
    links.put("o-sold", new TradeLogExport.Link("matched", 1_450_000L));
    links.put("o-told", new TradeLogExport.Link("inferred", 1L)); // an offer left out of the file carries nothing in
    return TradeLogExport.build(sample(), new HashSet<>(Arrays.asList("o-odd")), sampleFlips(), links);
  }

  /** Parses the file the way a spreadsheet reads RFC 4180: quoted fields, doubled quotes, CRLF records. */
  static List<List<String>> parse(String text) {
    List<List<String>> rows = new ArrayList<>();
    List<String> row = new ArrayList<>();
    StringBuilder f = new StringBuilder();
    boolean quoted = false;
    for (int i = 0; i < text.length(); i++) {
      char c = text.charAt(i);
      if (quoted) {
        if (c == '"' && i + 1 < text.length() && text.charAt(i + 1) == '"') { f.append('"'); i++; }
        else if (c == '"') quoted = false;
        else f.append(c);
      } else if (c == '"') quoted = true;
      else if (c == ',') { row.add(f.toString()); f.setLength(0); }
      else if (c == '\r' && i + 1 < text.length() && text.charAt(i + 1) == '\n') {
        row.add(f.toString()); f.setLength(0); rows.add(row); row = new ArrayList<>(); i++;
      } else f.append(c);
    }
    check(f.length() == 0 && row.isEmpty(), "the file ends with a complete record");
    return rows;
  }

  static String text(byte[] bytes) {
    check(bytes.length > 3 && (bytes[0] & 0xFF) == 0xEF && (bytes[1] & 0xFF) == 0xBB && (bytes[2] & 0xFF) == 0xBF, "UTF-8 BOM first");
    return new String(bytes, 3, bytes.length - 3, StandardCharsets.UTF_8);
  }

  static void headerAndShape() {
    String t = text(sampleCsv().bytes);
    check(t.startsWith("sep=,\r\n" + TradeLogExport.HEADER + "\r\n"), "sep=, then the header, CRLF: " + t.substring(0, Math.min(80, t.length())));
    check(TradeLogExport.HEADER.equals("record,ref,item_id,item_name,side,state,price,evi_price,evi_link,quantity,filled,cancelled,ended_unseen,known_start,"
      + "ticks_to_fill,first_seen_utc,last_seen_utc,completed_utc,matched,buy_ref,sell_refs,cost,proceeds,profit,first_buy_utc,last_sell_utc"),
      "the header, word for word");
    check(!t.contains(";"), "never a semicolon");
    List<List<String>> rows = parse(t);
    check(rows.get(0).equals(List.of("sep=", "")), "line 1 is sep=, (Excel reads it as the separator, not data): " + rows.get(0));
    for (List<String> r : rows.subList(1, rows.size()))
      check(r.size() == TradeLogExport.COLUMNS, "every record has " + TradeLogExport.COLUMNS + " fields: " + r);
    check(TradeLogExport.fileName(LocalDate.of(2026, 10, 9)).equals("evi-trade-log-2026-10-09.csv"), "file name per local day");
    check(TradeLogExport.field(null).isEmpty() && TradeLogExport.field("a,b").equals("\"a,b\"") && TradeLogExport.field("say \"hi\"")
      .equals("\"say \"\"hi\"\"\"") && TradeLogExport.field("two\nlines").equals("\"two\nlines\"") && TradeLogExport.field("plain").equals("plain"),
      "RFC 4180 quoting");
    check("2026-09-21T12:00:30.123Z".equals(TradeLogExport.time(T + 30_123)) && "2026-09-21T12:00:00.000Z".equals(TradeLogExport.time(T)),
      "ISO-8601 UTC, exact to the millisecond: " + TradeLogExport.time(T + 30_123));
  }

  static void rowsAndQuoting() {
    TradeLogExport.Csv csv = sampleCsv();
    check(csv.offers == 4 && csv.flips == 1, "four offers (the told purchase left out) and one flip: " + csv.offers + "/" + csv.flips);
    List<List<String>> rows = parse(text(csv.bytes));
    List<List<String>> data = rows.subList(2, rows.size());
    check(data.size() == 5, "five records: " + data.size());
    // sorted by first seen: the buy (T), the sale (T+40s), the cancelled sell (T+60s), the odd buy (T+120s); then the flip
    check(data.get(0).equals(List.of("offer", "1", "4151", "Abyssal whip", "buy", "BOUGHT", "1500000", "1490000", "observed", "2", "2", "no", "no", "yes", "40",
      "2026-09-21T12:00:00.000Z", "2026-09-21T12:00:30.123Z", "2026-09-21T12:00:30.123Z", "", "", "", "", "", "", "", "")),
      "a filled buy linked to EVI's suggestion at a DIFFERENT price, field for field: " + data.get(0));
    check(data.get(1).get(1).equals("2") && data.get(1).get(5).equals("SOLD") && data.get(1).get(4).equals("sell")
      && data.get(1).get(6).equals("1450000") && data.get(1).get(7).equals("1450000") && data.get(1).get(8).equals("matched"),
      "the sale second, MATCHED at its own price: " + data.get(1));
    check(data.get(2).equals(List.of("offer", "3", "1515", "Yew logs", "sell", "CANCELLED_SELL", "320", "", "", "500", "120", "yes", "no", "yes", "",
      "2026-09-21T12:01:00.000Z", "2026-09-21T12:01:30.000Z", "2026-09-21T12:01:30.000Z", "", "", "", "", "", "", "", "")),
      "a cancelled, part-filled sell with no link (both suggestion cells empty): cancelled=yes, no tick reading: " + data.get(2));
    check(data.get(3).get(3).equals("Odd, \"quoted\" item") && data.get(3).get(12).equals("yes") && data.get(3).get(13).equals("no")
      && data.get(3).get(17).isEmpty() && data.get(3).get(7).isEmpty() && data.get(3).get(8).isEmpty(), "a name with a comma and quotes survives quoting; ended-unseen; not seen from its start; not completed: " + data.get(3));
    check(data.get(4).equals(List.of("flip", "5", "4151", "Abyssal whip", "", "", "", "", "", "2", "", "", "", "", "", "", "", "", "reviewed", "1", "2",
      "3000000", "2842000", "-158000", "2026-09-21T12:00:00.000Z", "2026-09-21T12:00:50.000Z")),
      "a reviewed flip at a LOSS: negative profit, its buy and sale named by ref, an offer not in the file dropped from sell_refs: " + data.get(4));
  }

  static void nothingIdentifying() {
    String t = text(sampleCsv().bytes);
    for (String s : List.of(ACCOUNT, ACCOUNT.substring(0, 8), "session-x", "o-buy", "o-sell", "o-odd", "o-told", "o-sold", "o-gone", "m1"))
      check(!t.contains(s), "the file must not contain \"" + s + "\"");
  }

  /**
   * End to end: two clients (two accounts) write their own journals into one folder; the export from ONE journal holds every
   * account's offers and the FIFO flips, is exactly TradeLogExport over a store that saw every packet, lands in share/, and a
   * second export the same day replaces the file. No account id, character name, session or offer id is in it.
   */
  static void journalWritesEveryAccount() throws Exception {
    Filepath root = PluginJournalTest.tempRoot();
    AtomicLong c1 = new AtomicLong(), c2 = new AtomicLong();
    PluginJournal j1 = PluginJournalTest.journal(root, c1, () -> false);
    PluginJournal j2 = PluginJournalTest.journal(root, c2, () -> false);
    j1.characterName(PluginJournalTest.A, CHARACTER);
    j2.characterName(PluginJournalTest.B, CHARACTER + " Two");
    PluginJournalTest.Client a = PluginJournalTest.streamA(), b = PluginJournalTest.streamB();
    Store ref = new Store(r -> { });
    PluginJournalTest.feed(a, 0, a.packets.size(), j1, c1, ref);
    PluginJournalTest.feed(b, 0, b.packets.size(), j2, c2, ref);
    check(j1.awaitIdle(30000) && j2.awaitIdle(30000), "drain");
    long t = PluginJournalTest.T0 + 900_000;
    String name = TradeLogExport.fileName(LocalDate.of(2026, 10, 9));
    // EVI's suggestions, through the plugin's own join (SuggestionOutcomes): a whip buy suggested at a price the player did not
    // use (INFERRED), a nature-rune buy at the offer's exact price and quantity (MATCHED), and a chestplate sale the player said
    // they took (OBSERVED). Each record also holds an id, an account and a minimum profit that must never reach the file.
    List<com.google.gson.JsonObject> suggestions = new ArrayList<>();
    suggestions.add(suggestion("sugg-secret-1", PluginJournalTest.T0 + 30_000, 4151, "buy", 1_490_000, 1_600_000, 10));
    suggestions.add(suggestion("sugg-secret-3", PluginJournalTest.T0 + 180_000, 11832, "sell", 20_000_000, 21_000_000, 2));
    suggestions.add(suggestion("sugg-secret-2", PluginJournalTest.T0 + 290_000, 561, "buy", 100, 110, 1000));
    java.util.function.BiFunction<StoreState, java.util.Collection<Offer>, java.util.Map<String, TradeLogExport.Link>> linker =
      (state, offers) -> com.evi.live.inprocess.SuggestionOutcomes.offerLinks(com.evi.live.inprocess.SuggestionOutcomes.join(suggestions, offers,
        com.evi.live.inprocess.SuggestionOutcomes.Flip.of(state.flips, state.autoFlips), com.evi.live.inprocess.SuggestionOutcomes.TAKEN_WINDOW_MS,
        "sugg-secret-3"::equals));
    PluginJournal.SavedLog saved = j1.exportTradeLog(name, t, linker).get(30, TimeUnit.SECONDS);
    Filepath file = saved.file;
    check(file.equals(root.joinSegment(TradeLogExport.SHARE_DIR).joinSegment(name)) && file.toString().startsWith(root.toString()),
      "saved as share/" + name + " under the data folder, an absolute path: " + file);
    byte[] bytes = TestFiles.read(file);
    StoreState st = ref.state(t);
    TradeLogExport.Csv expected = TradeLogExport.of(st, ref.offers(), linker.apply(st, ref.offers()));
    check(Arrays.equals(bytes, expected.bytes), "the file is exactly the export of a store that saw both accounts' packets");
    check(saved.offers == ref.offers().size() && saved.offers == 6 && saved.flips == st.autoFlips.size() + st.flips.size() && saved.flips == 2,
      "every account's offers (6) and both FIFO flips: " + saved.offers + " offers, " + saved.flips + " flips");
    String t1 = text(bytes);
    for (String item : List.of("Abyssal whip", "Nature rune", "Bandos chestplate", "Dragon bones")) check(t1.contains(item), "has " + item);
    for (String s : List.of(PluginJournalTest.A, PluginJournalTest.B, "a1a1a1a1", "b2b2b2b2", CHARACTER, "sa1", "sb1", "-b1", "-s1",
      "sugg-secret", "acct-secret", "424242", "minProfit"))
      check(!t1.contains(s), "the saved file must not contain \"" + s + "\"");
    List<List<String>> rows = parse(t1);
    java.util.Map<String, String> linked = new java.util.TreeMap<>();
    for (List<String> r : rows.subList(2, rows.size()))
      if (r.get(0).equals("offer")) linked.put(r.get(3) + " " + r.get(4), r.get(6) + "|" + r.get(7) + "|" + r.get(8));
    check(linked.equals(new java.util.TreeMap<>(java.util.Map.of(
      "Abyssal whip buy", "1500000|1490000|inferred",
      "Abyssal whip sell", "1600000||",
      "Nature rune buy", "100|100|matched",
      "Bandos chestplate buy", "20000000||",
      "Bandos chestplate sell", "21000000|21000000|observed",
      "Dragon bones buy", "3000||"))),
      "each offer's price | EVI's suggested price | link type, from the plugin's own join (unlinked offers empty): " + linked);
    int flips = 0;
    for (List<String> r : rows.subList(2, rows.size())) {
      if (!r.get(0).equals("flip")) continue;
      flips++;
      check(r.get(18).equals("auto") && !r.get(19).isEmpty() && !r.get(20).isEmpty(), "a FIFO flip names its buy and sale: " + r);
      check(Long.parseLong(r.get(23)) == Long.parseLong(r.get(22)) - Long.parseLong(r.get(21)), "profit = proceeds - cost: " + r);
    }
    check(flips == 2, "two flip rows");
    // the same day again: replaced, not duplicated, and no temporary file left behind
    PluginJournalTest.Client more = new PluginJournalTest.Client("sa3", PluginJournalTest.A);
    more.set(PluginJournalTest.offer(5, "sa3-b5", "BUYING", 1515, "Yew logs", 300, 50, 0, 0, true, -1)).send(PluginJournalTest.T0 + 800_000, true);
    PluginJournalTest.feed(more, 0, more.packets.size(), j1, c1, ref);
    check(j1.awaitIdle(30000), "drain");
    // a linker that fails (an unreadable suggestion log) costs the links, never the file, and never a guessed link
    PluginJournal.SavedLog again = j1.exportTradeLog(name, t, (state, offers) -> { throw new IllegalStateException("synthetic"); }).get(30, TimeUnit.SECONDS);
    check(again.offers == 7 && Arrays.equals(TestFiles.read(file), TradeLogExport.of(ref.state(t), ref.offers(), null).bytes),
      "a second export the same day replaces the file with the newer journal: " + again.offers);
    List<String> names = TestFiles.names(file.getParent());
    check(names.equals(List.of(name)), "only the one file in share/: " + names);
    PluginJournalTest.stop(j1);
    PluginJournalTest.stop(j2);
    try {
      j1.exportTradeLog(name, t, null).get(30, TimeUnit.SECONDS);
      check(false, "a stopped journal must refuse");
    } catch (java.util.concurrent.ExecutionException e) {
      check(e.getCause() instanceof IllegalStateException, "a stopped journal refuses with a reason: " + e.getCause());
    }
    root.deleteRecursively();
  }
}

package com.evi.live.journal;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Replays one golden transcript (format evi-golden-transcript/1, recorded from the real bridge) through the
 * Java {@link Store} and compares every journal-owned answer with what the JS bridge recorded:
 *
 * <ul>
 *   <li>POST /api/events -- {duplicate} or the exact 400 message</li>
 *   <li>GET /api/state -- the whole body: sessions, active/occupied, completed with proceeds, manual and
 *       automatic flips, open positions (cost basis), unmatched sells, data health, personal use, imports,
 *       closed positions, net profit, trade count</li>
 *   <li>store.buyLimitUsage calls -- {used, windowEndsAt}</li>
 *   <li>POST /api/suggestion/not-held and /personal-use -- the reply or the exact message</li>
 *   <li>POST /api/profit/reset, and the {@code profit} field of every GET /api/suggestion reply</li>
 *   <li>POST /api/suggestion/block -- the reply; the list it leaves in preferences.json is {@link #blockedNow()}, which the
 *       engine replays read (server.mjs keeps it in the preferences file, not the journal)</li>
 *   <li>POST /api/flips/import (the scanner's import, with its cookie, origin and x-evi-ui header) -- the reply</li>
 *   <li>a bridge restart -- the Store rebuilt by decoding the lines the JAVA engine journalled, so every
 *       restart also proves the line codec round-trips</li>
 * </ul>
 *
 * <p>The rest of a suggestion reply is the engine (Phase 3) and is not compared here. The server glue the
 * journal routes depend on is reproduced in a few lines and named as such: the plugin-key check, the
 * last-inventory memory that gives an item mark its kept count, the inventory-check memory behind
 * {@code dataHealth.inventoryCheck}, and the profit reset time. Each mirrors server.mjs; the last-inventory
 * one is an approximation (the bridge only refreshes it when the idle-inventory tier is reached) that is
 * exact for every recorded transcript and would show up as a diff the day it is not.
 */
public final class TranscriptDriver {
  /**
   * Called for every GET /api/suggestion step, after the journal glue has seen its query and before the next step runs, so
   * the Store it is handed holds exactly what the bridge's held when it answered (Phase 3b: the engine's tiers are composed
   * against it by EngineTranscriptTest).
   */
  public interface SuggestionObserver {
    void onSuggestion(int step, long at, String query, JsonObject response, Store store);
  }

  private SuggestionObserver observer;

  public void observe(SuggestionObserver o) {
    observer = o;
  }

  private final String name;
  public final List<String> diffs = new ArrayList<>();
  public int compared;
  /** The journal lines the JAVA store wrote (plus any seed lines), in order. */
  final List<String> lines = new ArrayList<>();
  private Store store;
  private Long profitSince;
  /** preferences.json's blocked list as the bridge holds it (readPreferences' filter), or null while no Block was pressed. */
  private List<Integer> blocked;
  private List<Integer> bootBlocked = new ArrayList<>();
  /**
   * The plugin's PER-CHARACTER lists (8 Oct 2026): each Block press goes to the account of the poll whose pick it was pressed on
   * (the request names none; the plugin presses for the account it polls for), "" when that poll named none.
   */
  private final Map<String, LinkedHashSet<Integer>> pressedBy = new HashMap<>();
  private String lastPolledAccount = "";
  private final Map<String, Object[]> inventoryChecks = new LinkedHashMap<>(); // key -> {account|null, at, List<Integer>}
  private final Map<String, Object[]> lastInventory = new HashMap<>();         // key -> {Map<Integer,Long>, at}
  private final Store.Journal sink = r -> lines.add(JournalCodec.encodeLine(r));

  public TranscriptDriver(String name) {
    this.name = name;
  }

  private void rebuild() {
    List<JournalRecord> records = new ArrayList<>();
    for (String l : lines) records.add(JournalCodec.decode(ParityJson.parse(l)));
    store = Store.replay(records, sink);
  }

  /** Boot as the bridge does: replay the seed journal (if any), and read preferences.json's profitSince. */
  public void boot(List<String> seedLines, JsonElement preferences) {
    Double since = preferences != null && preferences.isJsonObject() ? Js.number(preferences.getAsJsonObject().get("profitSince")) : null;
    profitSince = since == null || since.isNaN() || since.isInfinite() ? null : (long) (double) since;
    bootBlocked = new ArrayList<>();
    JsonElement b = preferences != null && preferences.isJsonObject() ? preferences.getAsJsonObject().get("blocked") : null;
    if (b != null && b.isJsonArray())
      for (JsonElement x : b.getAsJsonArray()) {
        Double v = Js.number(x);
        if (v != null && Js.isSafeInteger(v) && v > 0) bootBlocked.add((int) (double) v); // Number.isSafeInteger(id) && id > 0
      }
    blocked = null;
    pressedBy.clear();
    lastPolledAccount = "";
    lines.clear();
    if (seedLines != null) lines.addAll(seedLines);
    rebuild();
    // The seed is the bridge's file; only what the Java engine appends afterwards is "its" output.
  }

  public Store store() {
    return store;
  }

  /**
   * preferences.json's blocked list as the bridge holds it at this step, in the stored order, or null when no Block was pressed
   * in this transcript (the boot preferences then stand as they are).
   */
  public List<Integer> blockedNow() {
    return blocked == null ? null : new ArrayList<>(blocked);
  }

  /**
   * What the PLUGIN's engine reads at this step for a query naming {@code account}: the boot file's blocked list (the plugin's own
   * preferences.json, read as the bridge reads its file) plus that character's own presses, ascending -- or null when no Block was
   * pressed and the boot list stands as it is. Equal to {@link #blockedNow()} whenever only one account pressed and polled.
   */
  public List<Integer> blockedFor(String account) {
    if (blocked == null) return null;
    java.util.TreeSet<Integer> all = new java.util.TreeSet<>(bootBlocked);
    LinkedHashSet<Integer> mine = pressedBy.get(account == null ? "" : account);
    if (mine != null) all.addAll(mine);
    return new ArrayList<>(all);
  }

  /** The profit line's reset time as the bridge holds it at this step (null: never reset), for the engine's shared journal. */
  public Long profitSince() {
    return profitSince;
  }

  private void expect(int i, String what, JsonElement exp, JsonElement act) {
    compared++;
    for (String d : ParityJson.diff(exp, act)) diffs.add(name + " step " + i + " " + what + ": " + d);
  }

  private static JsonObject error(int status, String message) {
    JsonObject o = new JsonObject();
    o.addProperty("status", status);
    JsonObject b = new JsonObject();
    b.addProperty("error", message);
    o.add("body", b);
    return o;
  }

  private static JsonObject ok(JsonElement body) {
    JsonObject o = new JsonObject();
    o.addProperty("status", 200);
    o.add("body", body);
    return o;
  }

  public void run(JsonArray steps) {
    for (JsonElement se : steps) {
      JsonObject step = se.getAsJsonObject();
      int i = step.get("i").getAsInt();
      long at = step.get("at").getAsLong();
      JsonObject response = step.getAsJsonObject("response");
      if (step.has("restart")) {
        rebuild();
        inventoryChecks.clear();
        lastInventory.clear();
        continue;
      }
      // Phase 4: a five-minute bucket handed straight to the bridge's crash watch (tools/golden-advice-scenarios.mjs). Not a
      // journal event; AdviceTranscriptTest feeds the Java watch from it.
      if (step.has("feed5m")) continue;
      // Stage 4: hours stored into the bridge's archive mid-run (store1h). Not a journal event; the engine and shadow replays
      // add them to their archive from that step on.
      if (step.has("store1h")) continue;
      if (step.has("call")) {
        JsonArray args = step.getAsJsonObject("call").getAsJsonArray("args");
        String account = args.get(0).isJsonNull() ? null : args.get(0).getAsString();
        BuyLimitUsage u = store.buyLimitUsage(account, args.get(1).getAsInt(), at);
        JsonObject b = new JsonObject();
        b.addProperty("used", u.used);
        ParityJson.put(b, "windowEndsAt", u.windowEndsAt);
        expect(i, "buyLimitUsage", response.get("body"), b);
        continue;
      }
      JsonObject req = step.getAsJsonObject("request");
      String method = req.get("method").getAsString(), path = req.get("path").getAsString();
      String auth = req.has("auth") ? req.get("auth").getAsString() : "";
      int repeat = step.has("repeat") ? step.get("repeat").getAsInt() : 1;
      JsonObject body = req.has("body") && req.get("body").isJsonObject() ? req.getAsJsonObject("body") : new JsonObject();
      if ("POST".equals(method) && "ui".equals(auth) && "/api/flips/import".equals(path)) {
        // The scanner's flip import (server.mjs: send(200, store.importFlips(body))): ranking history, never profit.
        JsonObject got;
        try {
          Store.ImportResult r = store.importFlips(body);
          JsonObject b = new JsonObject();
          ParityJson.put(b, "removed", r.removed);
          ParityJson.put(b, "accepted", r.accepted);
          ParityJson.put(b, "duplicates", r.duplicates);
          b.addProperty("total", r.total);
          got = ok(b);
        } catch (JournalException e) {
          got = error(400, e.getMessage());
        }
        expect(i, path, response, got);
        continue;
      }
      if ("POST".equals(method) && !"plugin".equals(auth)) {
        // server.mjs refuses a wrong plugin key before the store sees anything.
        expect(i, path + " (wrong key)", response, error(401, "Plugin key required"));
        continue;
      }
      switch (method + " " + path) {
        case "POST /api/events": {
          JsonObject got = null;
          for (int k = 0; k < repeat; k++) {
            try {
              JsonObject b = new JsonObject();
              b.addProperty("duplicate", store.ingest(req.get("body"), at));
              got = ok(b);
            } catch (JournalException e) {
              got = error(400, e.getMessage());
            }
          }
          expect(i, "POST /api/events", response, got);
          break;
        }
        case "GET /api/state": {
          JsonObject st = ParityJson.state(store.state(at));
          addInventoryCheck(st, at);
          expect(i, "GET /api/state", response.get("body"), st);
          JsonElement kept = response.get("body").getAsJsonObject().get("personalUseKept");
          if (kept != null && kept.isJsonObject()) {
            compared++;
            if (!ParityJson.keyOrder(kept.getAsJsonObject()).equals(ParityJson.keyOrder(st.getAsJsonObject("personalUseKept"))))
              diffs.add(name + " step " + i + ": personalUseKept key ORDER " + st.get("personalUseKept") + " vs JS " + kept);
          }
          break;
        }
        case "POST /api/suggestion/not-held": {
          JsonObject got;
          try {
            JsonObject a = new JsonObject();
            if (body.has("buyId")) a.add("buyId", body.get("buyId"));
            a.addProperty("reason", "used".equals(Js.string(body.get("reason"))) ? "used" : "sold-untracked");
            store.closePosition(a, at);
            JsonObject b = new JsonObject();
            b.addProperty("ok", true);
            got = ok(b);
          } catch (JournalException e) {
            got = error(400, e.getMessage());
          }
          expect(i, path, response, got);
          break;
        }
        case "POST /api/suggestion/personal-use": {
          JsonObject got;
          try {
            JsonElement personal = body.has("personal") ? body.get("personal") : new com.google.gson.JsonPrimitive(true);
            if (ParityJson.isNull(body.get("buyId"))) {
              JsonObject a = new JsonObject();
              if (body.has("itemId")) a.add("itemId", body.get("itemId"));
              a.add("personal", personal);
              Long kept = keptFor(Js.string(body.get("account")), body.get("itemId"), at);
              if (kept != null) a.addProperty("kept", kept);
              Store.PersonalUseItemReply r = store.markPersonalUseItem(a);
              JsonObject b = new JsonObject();
              b.addProperty("ok", true);
              b.addProperty("itemId", r.itemId);
              b.addProperty("personal", r.personal);
              ParityJson.put(b, "kept", r.kept);
              got = ok(b);
            } else {
              JsonObject a = new JsonObject();
              a.add("buyId", body.get("buyId"));
              a.add("personal", personal);
              store.markPersonalUse(a);
              JsonObject b = new JsonObject();
              b.addProperty("ok", true);
              got = ok(b);
            }
          } catch (JournalException e) {
            got = error(400, e.getMessage());
          }
          expect(i, path, response, got);
          break;
        }
        case "POST /api/suggestion/block": {
          // server.mjs setBlocked: Number(itemId) must be a safe integer above 0 (else 400 'Invalid itemId'); the set is the stored
          // list deduplicated in order, the id added (or removed for blocked:false); the FILE gets it sorted, the reply the set's order.
          JsonObject got;
          JsonElement idEl = body.get("itemId");
          Double id = idEl == null || idEl.isJsonNull() ? null : Js.number(idEl);
          if (id == null || !Js.isSafeInteger(id) || id <= 0) {
            got = error(400, "Invalid itemId");
          } else {
            LinkedHashSet<Integer> set = new LinkedHashSet<>(blocked == null ? bootBlocked : blocked);
            JsonElement flag = body.get("blocked");
            if (flag != null && flag.isJsonPrimitive() && flag.getAsJsonPrimitive().isBoolean() && !flag.getAsBoolean()) set.remove((int) (double) id);
            else set.add((int) (double) id);
            List<Integer> sorted = new ArrayList<>(set);
            java.util.Collections.sort(sorted);
            blocked = sorted;
            LinkedHashSet<Integer> mine = pressedBy.computeIfAbsent(lastPolledAccount, k -> new LinkedHashSet<>());
            if (flag != null && flag.isJsonPrimitive() && flag.getAsJsonPrimitive().isBoolean() && !flag.getAsBoolean()) mine.remove((int) (double) id);
            else mine.add((int) (double) id);
            JsonObject b = new JsonObject();
            b.addProperty("ok", true);
            JsonArray reply = new JsonArray();
            for (Integer x : set) reply.add(x);
            b.add("blocked", reply);
            got = ok(b);
          }
          expect(i, path, response, got);
          break;
        }
        case "POST /api/profit/reset": {
          profitSince = at;
          JsonObject b = new JsonObject();
          b.addProperty("ok", true);
          b.add("profit", ParityJson.profit(Profit.sinceAllAccounts(store.state(at), profitSince)));
          expect(i, path, response, ok(b));
          break;
        }
        case "GET /api/suggestion": {
          if (step.has("warmupQuery")) observeQuery(step.get("warmupQuery").getAsString(), at);
          observeQuery(req.get("query").getAsString(), at);
          JsonElement rb = response.get("body");
          if (response.get("status").getAsInt() == 200 && rb != null && rb.isJsonObject() && rb.getAsJsonObject().has("profit"))
            expect(i, "GET /api/suggestion .profit", rb.getAsJsonObject().get("profit"),
              ParityJson.profit(Profit.sinceAllAccounts(store.state(at), profitSince)));
          if (observer != null) observer.onSuggestion(i, at, req.get("query").getAsString(), response, store);
          break;
        }
        default:
          break; // /api/version and anything else: not the journal's
      }
    }
  }

  // ------------------------------------------------------------------------------------- server glue

  private static Map<String, String> query(String q) {
    Map<String, String> out = new LinkedHashMap<>();
    for (String part : q.split("&")) {
      if (part.isEmpty()) continue;
      int eq = part.indexOf('=');
      String k = URLDecoder.decode(eq < 0 ? part : part.substring(0, eq), StandardCharsets.UTF_8);
      String v = eq < 0 ? "" : URLDecoder.decode(part.substring(eq + 1), StandardCharsets.UTF_8);
      out.putIfAbsent(k, v); // URLSearchParams.get returns the first
    }
    return out;
  }

  /** JS parseInt(s, 10): leading whitespace, a sign, then digits; anything else is NaN (null here). */
  private static Long parseIntJs(String s) {
    String t = s.trim();
    int i = 0;
    if (i < t.length() && (t.charAt(i) == '+' || t.charAt(i) == '-')) i++;
    int start = i;
    while (i < t.length() && Character.isDigit(t.charAt(i)) && t.charAt(i) < 128) i++;
    if (i == start) return null;
    return Long.parseLong(t.substring(0, i));
  }

  // server.mjs: every /api/suggestion with heldPositions= (even empty) records an inventory check for that
  // account; with includeInventory=1 and a non-empty inventory= it records the bag (lastInventory).
  private void observeQuery(String q, long at) {
    Map<String, String> p = query(q);
    String account = p.get("account");
    if (account != null && account.isEmpty()) account = null;
    String key = account == null ? "" : account;
    lastPolledAccount = key;
    if (p.containsKey("heldPositions")) {
      Set<Integer> confirmed = new LinkedHashSet<>();
      for (String s : p.get("heldPositions").split(",", -1)) {
        Long v = parseIntJs(s);
        if (v != null) confirmed.add((int) (long) v);
      }
      inventoryChecks.put(key, new Object[]{account, at, new ArrayList<>(confirmed)});
    }
    if ("1".equals(p.get("includeInventory"))) {
      Map<Integer, Long> inv = new LinkedHashMap<>();
      for (String pair : p.getOrDefault("inventory", "").split(",", -1)) {
        String[] parts = pair.split(":", -1);
        Long id = parseIntJs(parts[0]);
        Long qty = parts.length > 1 ? parseIntJs(parts[1]) : null;
        if (id != null && id > 0 && qty != null && qty > 0) inv.put((int) (long) id, qty);
      }
      if (!inv.isEmpty()) lastInventory.put(key, new Object[]{inv, at});
    }
  }

  // server.mjs /personal-use: the kept count is what the last poll of THAT account (or of "") held, if
  // that poll is under a minute old. The plugin sends no account, so its marks look up "" -- and, since 8 Oct 2026, when
  // that reading is absent or stale, the ONE account whose bag was read in the last minute (two or more: no count).
  @SuppressWarnings("unchecked")
  private Long keptFor(String account, JsonElement itemId, long at) {
    boolean named = account != null && !account.isEmpty();
    Object[] seen = lastInventory.get(named ? account : "");
    if (seen == null) seen = lastInventory.get("");
    Map<Integer, Long> fresh = seen != null && at - (long) seen[1] < 60000 ? (Map<Integer, Long>) seen[0] : null;
    if (fresh == null && !named) {
      List<Object[]> recent = new ArrayList<>();
      for (Object[] r : lastInventory.values()) if (at - (long) r[1] < 60000) recent.add(r);
      if (recent.size() == 1) fresh = (Map<Integer, Long>) recent.get(0)[0];
    }
    if (fresh == null) return null;
    Double id = Js.number(itemId);
    if (id == null) return null;
    return fresh.get((int) (double) id);
  }

  // server.mjs /api/state: the newest inventory check under ten minutes old, counted against that
  // account's positions -- or, when the poll named no account, against every position (the scanner's
  // machine-wide line; the bridge does this, the glue reproduces it explicitly rather than by predicate).
  @SuppressWarnings("unchecked")
  private void addInventoryCheck(JsonObject st, long now) {
    Object[] newest = null;
    for (Object[] c : inventoryChecks.values()) if (newest == null || (long) c[1] > (long) newest[1]) newest = c;
    if (newest == null || now - (long) newest[1] >= 600000) return;
    String account = (String) newest[0];
    Set<Integer> items = new LinkedHashSet<>();
    for (FifoMatcher.OpenPosition p : store.state(now).autoOpenPositions)
      if (account == null || account.equals(p.account)) items.add(p.itemId);
    int seen = 0;
    for (Integer id : (List<Integer>) newest[2]) if (items.contains(id)) seen++;
    JsonObject ic = new JsonObject();
    ic.addProperty("at", (long) newest[1]);
    ic.addProperty("positions", items.size());
    ic.addProperty("seenInInventory", seen);
    st.getAsJsonObject("dataHealth").add("inventoryCheck", ic);
  }
}

